import scala.util.control.Breaks.{breakable,break}
import scala.collection.mutable.{Map, Stack, Queue, PriorityQueue, Set}

object Main extends App {
  val in = new InputReader(System.in)
  val pw = new PrintWriter(System.out)

  val N = in.next().toInt
  val P = new Array[Int](N+1)
  val indexMap = new Array[Int](N+1)
  for (i <- 1 to N) {
    P(i) = in.next().toInt
    indexMap(P(i)) = i
  }

  //
  val bit = new BIT(N+1)
  bit.add(N+1, 1)

  // 条件を満たす最大の値を返す
  def binarySearchMax(_min: Int, _max: Int, n: Int): Int = {
    def check(i: Int): Boolean = bit.sum(i) <= n

    def func(min: Int, max: Int): Int = {
      val mid: Int = (max + min) / 2
        (max - min) match{
        case 0 | 1 =>
          check(max) match{
            case true  => max
            case false => min
          }
        case _ =>
          (check(mid)) match{
            case true  => func(mid, max)
            case false => func(min, mid)
          }
      }
    }

    func(_min, _max)
  }

  // 条件を満たす最小の値を返す
  def binarySearchMin(_min: Int, _max: Int, n: Int): Int = {
    def check(i: Int): Boolean = bit.sum(i) >= n

    def func(min: Int, max: Int): Int = {
      val mid: Int = (max + min) / 2
        (max - min) match{
        case 0 | 1 =>
          check(min) match{
            case true  => min
            case false => max
          }
        case _ =>
          (check(mid)) match{
            case true  => func(min, mid)
            case false => func(mid, max)
          }
      }
    }

    func(_min, _max)
  }

  var ans = 0
  for (k <- (1 to N).reverse) {
    val i = indexMap(k)

    if (k < N) {
      val now = bit.sum(i)
      val l1 = binarySearchMin(0, i, now)
      val r1 = binarySearchMin(i, N+1, now+1)

      if (now > 0) { // 左に自分より大きい値が存在する
        val l2 = if (bit.sum(1) < now) binarySearchMax(1, i, now-1) else 0
        val l = l1 - l2
        val r = (r1-1) - (i-1)
        ans += (l * r) * k
      }

      if (bit.sum(N) > now) { // 右に自分より大きい値が存在する
        val r2 = if (bit.sum(N) >= now+2) binarySearchMin(i, N, now+2) else N+1
        val l = i - l1
        val r = r2 - r1
        // println(s"r1: $r1, r2: $r2, r: $r")
        ans += (l * r) * k
      }
    }

    bit.add(i, 1)
  }

  println(ans)
}

