ll N;

using point = tuple<ll, ll>;

vector<vector<ll>> solve(vector<ll> const &V)
{
  vector<vector<ll>> ans(2, vector<ll>(N, -1));
  priority_queue<point, vector<point>, greater<point>> P, Q;
  for (auto i = 0LL; i < N; i++)
  {
    while (!Q.empty() && get<0>(Q.top()) < V[i])
    {
      ll val, ind;
      tie(val, ind) = Q.top();
      Q.pop();
      ans[1][ind] = i - ind;
    }
    while (!P.empty() && get<0>(P.top()) < V[i])
    {
      ll val, ind;
      tie(val, ind) = P.top();
      P.pop();
      ans[0][ind] = i - ind;
      Q.push(point(val, ind));
    }
    P.push(point(V[i], i));
  }
#if DEBUG == 1
  for (auto i = 0; i < N; i++)
  {
    cerr << "ans[0][" << i << "] = " << ans[0][i] << endl;
    cerr << "ans[1][" << i << "] = " << ans[1][i] << endl;
  }
#endif
  for (auto i = 0; i < N; i++)
  {
    if (ans[0][i] == -1)
    {
      assert(ans[1][i] == -1);
      ans[0][i] = N - i;
      ans[1][i] = 0;
    }
    else if (ans[1][i] == -1)
    {
      ans[1][i] = N - i;
      ans[1][i] -= ans[0][i];
    }
    else
    {
      ans[1][i] -= ans[0][i];
    }
  }
#if DEBUG == 1
  for (auto i = 0; i < N; i++)
  {
    cerr << "ans[0][" << i << "] = " << ans[0][i] << endl;
    cerr << "ans[1][" << i << "] = " << ans[1][i] << endl;
  }
#endif

  return ans;
}

int main()
{
  cin >> N;
  vector<ll> V(N);
  for (auto i = 0; i < N; i++)
  {
    cin >> V[i];
  }
  vector<vector<ll>> left{solve(V)};
  reverse(V.begin(), V.end());
  vector<vector<ll>> right{solve(V)};
  for (auto i = 0; i < 2; i++)
  {
    reverse(right[i].begin(), right[i].end());
  }
#if DEBUG == 1
  for (auto i = 0; i < N; i++)
  {
    cerr << "left[0][" << i << "] = " << left[0][i] << endl;
    cerr << "left[1][" << i << "] = " << left[1][i] << endl;
    cerr << "right[0][" << i << "] = " << right[0][i] << endl;
    cerr << "right[1][" << i << "] = " << right[1][i] << endl;
  }
#endif
  reverse(V.begin(), V.end());
  ll ans{0LL};
  for (auto i = 0; i < N; i++)
  {
    ans += (left[0][i] * right[1][i] + left[1][i] * right[0][i]) * V[i];
#if DEBUG == 1
    cerr << "V[" << i << "] = " << V[i] << ", " << (left[0][i] * right[1][i] + left[1][i] * right[0][i]) << endl;
#endif
  }
  cout << ans << endl;
}

