  FOR(i, N) cin >> P[i];
  ll ans = 0;
  vector<int> pos(N + 1);
  FOR(i, N) pos[P[i]] = i;
  FOR(i, N) {
    ll x = P[i];
    if (x == N)
      continue;
    if (x == N - 1) {
      int p = pos[N];
      if (i < p) {
        ans += (i + 1) * (N - p) * x;
      } else {
        ans += (p + 1) * (N - i) * x;
      }
      continue;
    }
    int l1 = i - 1;
    while (l1 >= 0 && P[l1] < x)
      --l1;
    int l2 = l1 - 1;
    while (l2 >= 0 && P[l2] < x)
      --l2;
    ++l2;
    int r1 = i + 1;
    while (r1 < N && P[r1] < x)
      ++r1;
    int r2 = r1 + 1;
    while (r2 < N && P[r2] < x)
      ++r2;
    --r2;
    ans += ((l1 >= 0 ? (ll)(l1 - l2 + 1) * (r1 - i) : 0) +
            (r1 < N ? (ll)(r2 - r1 + 1) * (i - l1) : 0)) *
