ll N, P[101010];
ll A[101010];

ll i, j, k,ans;

int main(){
    scanf("%lld",&N);
    fornum(i,0,N){
        scanf("%lld", &P[i]);
        A[P[i]] = i + 1;
    }
    mn.init(N + 1, N + 1);
    mx.init(N + 1, 0);
    for (i = N; i > 0;i--)
    {
        ll ai = A[i];
        ll aa2, bb2;
        ll aa = mn.gett(ai, N);
        if(aa>=N){
            aa2 = N + 1 - aa;
        }else{
            aa2 = mn.gett(aa + 1, N) - aa;
        }
        aa = aa - ai;
        ll bb = mx.gett(1, ai);
        if(bb<=1){
            bb2 = bb;
        }else{
            bb2 = bb - mx.gett(1, bb - 1);
        }
        bb = ai - bb;
        //printf("%lld,%lld,%lld,%lld ", bb2, bb, aa, aa2);
        ans += (aa * bb2 + aa2 * bb) * i;
        mn.sett(ai, ai);
        mx.sett(ai, ai);
        //printf("%lld:%lld\n",i, ans);
    }
    printf("%lld", ans);

    return 0;
}

