unsigned long check(vector<int> &top, vector<int> &second, int limit){
    unsigned long sum = 0;
    for(int i=1; i<limit; i++){
        if(top[i-1]<top[i]){
            second[i-1] = max(max(top[i-1],second[i-1]),second[i]);
            top[i-1] = top[i];
        }else if(top[i-1]>top[i]){
            second[i-1] = max(max(top[i],second[i-1]),second[i]);
            top[i-1] = top[i-1];
        }else{
            second[i-1] = max(second[i-1],second[i]);
        }
        sum += second[i-1];
    }
    limit--;
    if(limit > 1){
        sum += check(top,second,limit);
    }
    return sum;
}

