int secondmin(vector<int> v)
{
    int n=v.size();
    priority_queue<int, vector<int>, greater<int> > pq;
    pq.push(v[0]);
    pq.push(v[1]);
    for(int i=2; i<n; i++){
        if(v[i]>pq.top()){
            pq.pop();
            pq.push(v[i]);
        }
    }

    return pq.top();
}

