ll find(BIT &bitree, ll n, ll aim)
{
    ll left = 1LL;
    ll right = n;
    ll now = (left + right) / 2LL;
    ll ret = n + 1LL;

    if (aim <= 0) return 0LL;

    for ( ; left <= right; now = (left + right) / 2LL) {
        ll lsum = bitree.sum(now);
        if (lsum < aim) {
            left = now + 1LL;
        }
        if (lsum == aim) {
            ret = min(ret, now);
            right = now - 1LL;
        }
        if (lsum > aim) {
            right = now - 1LL;
        }
    }

    return ret;
}

