signed main(){
  int N;cin>>N;
  std::vector<int> v(N),w(N);
  for(int i=0;i<N;i++)cin>>v[i];
  for(int i=0;i<N;i++)w[i]=v[i];
  reverse(w.begin(),w.end());
  auto f=[](int a,int b){return max(a,b);};
  SegmentTree<int> seg(f,0),seg2(f,0);
  seg.build(v);seg2.build(w);
  auto check=[&](int v,int d){return d>v;};
  int ans=0;
  for(int i=0;i<N;i++){
    int idx=seg.find(i,v[i],check);
    int idx2=-1,idx3=-1,idx4=-1;
    if(~idx)idx2=seg.find(idx+1,v[i],check);
    idx3=seg2.find(N-1-i,v[i],check);
    if(~idx3)idx4=seg2.find(idx3+1,v[i],check);
    if(idx3==N-1)idx4=N;
    if(idx==N-1)idx2=N;
    if(idx<0)idx=N;if(idx2<0)idx2=N;
    if(idx3<0)idx3=N;if(idx4<0)idx4=N;
    idx3=N-1-idx3;idx4=N-1-idx4;
    //cout<<idx<<" "<<idx2<<" "<<idx3<<" "<<idx4<<endl;
    ans+=v[i]*((idx2-idx)*(i-idx3)+(idx-i)*(idx3-idx4));
    //cout<<ans<<endl;
  }
  fin(ans);
}

