using namespace std;
using Int = long long;
struct SegTree {
    int N;
    vector<int> A;
    SegTree(int n) {
        N = 1;
        while (N < n) N *= 2;
        A.resize(2 * N);
    }
    void set(int idx, int val) {
        idx += N;
        A[idx] = val;
        idx /= 2;
        while (idx > 0) {
            A[idx] = max(A[2*idx+0], A[2*idx+1]);
            idx /= 2;
        }
    }
    int greater_index(int L, int R, int val, int dir) {
        L += N, R += N;
        deque<int> D1, D2;
        while (L < R) {
            if (R & 1) D2.push_front(--R);
            if (L & 1) D1.push_back(L++);
            L /= 2, R /= 2;
        }
        vector<int> D;
        for (auto d : D1) D.push_back(d);
        for (auto d : D2) D.push_back(d);
        if (dir == 1) reverse(begin(D), end(D));
        for (auto d : D) {
            if (A[d] <= val) continue;
            while (d < N) {
                if (A[2*d+dir] > val) d = 2*d+dir;
                else d = 2*d+!dir;
            }
            return d - N;
        }
        return -1;
    }
};
const int INF = 1e9;
int main() {
    int N; cin >> N;
    vector<int> P(N); for (auto &p : P) cin >> p;
    SegTree st(N);
    for (int i = 0; i < N; i++) {
        st.set(i, P[i]);
    }
    Int ans = 0;
    for (int i = 0; i < N; i++) {
        int L1 = -1, L2 = -1;
        int R1 = -1, R2 = -1;
        L1 = st.greater_index(0, i, P[i], 1);
        if (L1 != -1) L2 = st.greater_index(0, L1, P[i], 1);
        R1 = st.greater_index(i, N, P[i], 0);
        if (R1 != N) R2 = st.greater_index(R1+1, N, P[i], 0);
        if (L1 != -1) {
            int l2 = L2 == -1 ? -1 : L2;
            int r1 = R1 == -1 ? N : R1;
            ans += (L1 - l2) * (r1 - i) * P[i];
        }
        if (R1 != -1) {
            int l1 = L1 == -1 ? -1 : L1;
            int r2 = R2 == -1 ? N : R2;
            ans += (i - l1) * (r2 - R1) * P[i];
        }
    }
    cout << ans << endl;
    return 0;
}

