vector<int> P;

int search(int idx1, int idx2) {
    if (idx2 - idx1 < 1) {
        return 0;
    }
    if (idx2 - idx1 == 1) {
        return (P[idx1] > P[idx2]) ? P[idx2] : P[idx1];
    }

    int i1 = 0, i2 = 0, v1 = 0, v2 = 0;
    if (P[idx1] > P[idx1+1]) {
        i1 = idx1; i2 = idx1+1;
    }
    else {
        i2 = idx1; i1 = idx1+1;
    }
    v1 = P[i1]; v2 = P[i2];

    for (int j = idx1 + 2; j <= idx2; ++j) {
        if (P[j] > v1) {
            i2 = i1; i1 = j;
        } 
        else if (P[j] > v2) {
            i2 = j;
        }
        v1 = P[i1]; v2 = P[i2];
    }

    int ret = 0;
    int ii1 = (i1 < i2) ? i1 : i2;
    int ii2 = (i1 > i2) ? i1 : i2;

    ret = (ii1 - idx1 + 1) * (idx2 - ii2 + 1) * v2;
    ret += search(idx1, ii2-1) + search(ii1+1, idx2) - search(ii1+1, ii2-1); 

    return ret;
}

