                if (secondPrev > current) {
                    dp[i][j] = dp[i][j - 1];
                } else if (current > firstPrev) {
                    dp[i][j] = firstSecond(current, firstPrev);
                } else {
                    dp[i][j] = firstSecond(firstPrev, current);
                }
            }

            ans += dp[i][j].second;
        }
    }

    cout << ans << endl;
    return 0;
}

