struct MaxInfo {
	int first{ 0 };
	int second{ 0 };
	bool calculated{ false };
	static MaxInfo fromTry(int a, int b, int c) {
		if (a > b) {
			if (a > c) return { a,max(b,c),true };
			else return { c,a,true };
		} else {
			if (b > c)return { b,max(a,c),true };
			else return { c,b,true };
		}
	}
	static MaxInfo merge(MaxInfo a, MaxInfo b) {
		auto info = MaxInfo();
		if (a.first > b.first) return { a.first,max(a.second,b.first),true };
		else return { b.first,max(b.second,a.first),true };
	}
};

MaxInfo E_impl(const vector<int>& ns, Table<MaxInfo>& result, int l, int r) {
	if (result(l, r).calculated) return result(l, r);
	if (r - l == 1) {
		result(l, r) = { max(ns[l], ns[r]),min(ns[l],ns[r]),true };
		return result(l, r);
	}
	if (r - l == 2) {
		result(l, r) = MaxInfo::fromTry(ns[l], ns[l + 1], ns[l + 2]);
		return result(l, r);
	}
	// l=0  r=3 ->inter = 1
	auto inter = l + (r - l) / 2;
	result(l, inter) = E_impl(ns, result, l, inter);
	result(inter + 1, r) = E_impl(ns, result, inter + 1, r);
	result(l, r) = MaxInfo::merge(result(l, inter), result(inter + 1, r));
	return result(l, r);
}

void E() {
	read(int, n);
	auto ns = vector<int>(n);
	auto result = Table<MaxInfo>(n, n, {});
	for (auto i = 0; i < n; i++) cin >> ns[i];
	ll sum = 0;
	for (int l = 0; l < n-1; l++) {
		for (int r = l + 1; r < n; r++) {
			sum += E_impl(ns, result, l, r).second;
		}
	}
	cout << sum << endl;
}
