			nx = *nxt;
			nxt = next(nxt);
			if (nxt != st.end())
				nx1 = *nxt;
		}
		ans += ((p - p1) * (nx - idx[k])) * k;
		ans += ((nx1 - nx) * (idx[k] - p)) * k;
	}
	cout << ans << endl;
	return 0;
}

