template<typename T> struct SegmentTree_max{
	int n;
	vector<T> node;
	T MIN;

	SegmentTree_max(const vector<T> &v, const T &MIN_=0){
		init(v, MIN_);
	}

	// nodeの初期化
	void init(const vector<T> &v, const T &MIN_){
		int n_=v.size();
		n=1;
		while(n<n_){
			n<<=1;
		}
		node.resize(n*2-1);
		MIN=MIN_;
		REP(i, n_){
			node[i+n-1]=v[i];
		}
		FORR(i, 0, n-1){
			node[i]=max(node[i*2+1], node[i*2+2]);
		}
	}

	// k番目(0-indexed)をaに変更
	void update(int k, const T &a){
		k+=n-1;
		node[k]=a;
		while(k>0){
			k=(k-1)/2;
			node[k]=max(node[k*2+1], node[k*2+2]);
		}
	}

	// [a, b)の最大値を求める
	// k: 節点の番号、その節点は[l, r)に対応づく
	T query(int a, int b, int k, int l, int r){
		// [a, b)と[l, r)が交差しなければMIN
		if(r<=a || b<=l){
			return MIN;
		}
		// [a, b)と[l, r)が完全に含んでいればこの節点の値
		if(a<=l && r<=b){
			return node[k];
		}
		// そうでなければ2つの子の最大値
		else{
			T v1=query(a, b, k*2+1, l, (l+r)/2), v2=query(a, b, k*2+2, (l+r)/2, r);
			return max(v1, v2);
		}
	}

	T query(int a, int b){
		return query(a, b, 0, 0, n);
	}
};

ll n;

ll f(SegmentTree_max<ll> &st, ll r, ll p){
	ll lb=-1, ub=r;
	while(ub-lb>1){
		ll mid=(lb+ub)/2;
		if(st.query(mid, r+1)<=p){
			ub=mid;
		}
		else{
			lb=mid;
		}
	}
	return ub;
}

ll g(SegmentTree_max<ll> &st, ll l, ll p){
	ll lb=l, ub=n+2;
	while(ub-lb>1){
		ll mid=(lb+ub)/2;
		if(st.query(l, mid)<=p){
			lb=mid;
		}
		else{
			ub=mid;
		}
	}
	return lb;
}

