	ios::sync_with_stdio(false);
	cin.tie(0);
	// cout<<setprecision(10)<<fixed;
	cin>>n;
	vl p(n+2);
	FOR(i, 1, n+1){
		cin>>p[i];
	}
	p[0]=p[n+1]=0;
	SegmentTree_max<ll> st(p);
	ll ans=0;
	FOR(i, 1, n+1){
		ll l1=f(st, i, p[i]);
		ll l2=f(st, l1-2, p[i]);
		ll r1=g(st, i, p[i]);
		ll r2=g(st, r1+1, p[i]);
		if(p[l2]>p[i]) l2=l1-1;
		--r1;--r2;
		// cout<<l2<<' '<<l1<<' '<<r1<<' '<<r2<<'\n';
		if(l1<1){
			if(r1<=n){
				ans+=p[i]*i*(min(r2, n)-r1);
			}
		}
		else if(r1>n){
			if(l1>=1){
				ans+=p[i]*(l1-max(l2, 1ll))*(n-i+1);
			}
		}
		else{
			ans+=p[i]*((i-l1+1)*(min(r2, n)-r1)+(l1-max(l2, 1ll))*(r1-i+1));
		}
		// DEBUG(ans);
	}
	cout<<ans<<'\n';
	return 0;
}

