#define REP(i, n) for (int i = 0; i < (n); i++)
#define RREP(i, n) for (int i = (n) - 1; i >= 0; i--)
#define FOR(i, a, b) for (int i = (a); i < (b); i++)
#define RFOR(i, a, b) for (int i = (a); i > (b); i--)
#define ALL(a) (a).begin(), (a).end()

ll N, P[100000];
int next_r[2][100000], next_l[2][100000];

int main() {
    cin >> N;
    REP(i, N) {
        cin >> P[i];
        P[i]--;
    }
    REP(i, 2) REP(j, N) {
        next_r[i][j] = next_l[i][j] = -1;
    }

    priority_queue<pii, vector<pii>, greater<pii>> que;
    REP(i, N) {
        vector<pii> vp;
        while (!que.empty() && que.top().first < P[i]) {
            auto p = que.top(); que.pop();
            next_r[p.second][p.first] = i;
            if (p.second == 0) vp.push_back({p.first, 1});
        }
        for (auto p : vp) que.push(p);
        que.push({P[i], 0});
    }
    while (!que.empty()) que.pop();

    RREP(i, N) {
        vector<pii> vp;

        while (!que.empty() && que.top().first < P[i]) {
            auto p = que.top(); que.pop();
            next_l[p.second][p.first] = i;
            if (p.second == 0) vp.push_back({p.first, 1});
        }
        for (auto p : vp) que.push(p);
        que.push({P[i], 0});
    }

    ll ans = 0;
    REP(i, N) {
        int l1 = next_l[0][P[i]], l2 = next_l[1][P[i]];
        int r1 = next_r[0][P[i]], r2 = next_r[1][P[i]];
        if (r1 != -1) {
            int l = (l1 != -1) ? (i - l1) : (i + 1);
            int r = (r2 != -1) ? (r2 - r1) : (N - r1);
            ans += (P[i] + 1) * l * r;
        }
        if (l1 != -1) {
            int l = (l2 != -1) ? (l1 - l2) : (l1 + 1);
            int r = (r1 != -1) ? (r1 - i) : (N - i);
            ans += (P[i] + 1) * l * r;
        }
    }
    cout << ans << endl;
    return 0;
}

