    vector<int> pos(N+1);
    REP(i, N) pos[P[i]] = i;

    long long ans = 0;
    set<int> s{-1, pos[N], N};
    for(int i = N-1; i >= 1; --i){
        auto tmp = s.lower_bound(pos[i]);
        int w, x, y, z;
