int arr[maxn];
pii seg[4 * maxn];
pii merge(pii a, pii b) {
	pii tmp;
	tmp.first = max(a.first, b.first);
	tmp.second = max(min(a.first, b.first), max(a.second, b.second));
	return tmp;
}
void build(int index, int left, int right) {
	if (left == right) {
		seg[index].first = arr[left];
		return;
	}
	int mid = (left + right) / 2;
	build(2 * index, left, mid);
	build(2 * index + 1, mid + 1, right);
	seg[index] = merge(seg[2 * index], seg[2 * index + 1]);
}
pii query(int index, int left, int right, int lo, int hi) {
	if (lo <= left && right <= hi)
		return seg[index];
	int mid = (left + right) / 2;
	if (hi <= mid)
		return query(2 * index, left, mid, lo, hi);
	else if (lo > mid)
		return query(2 * index + 1, mid + 1, right, lo, hi);
	return merge(query(2 * index, left, mid, lo, hi), query(2 * index + 1, mid + 1, right, lo, hi));
}
