int a[200005],b[200005],root[200005],cnt=0,lson[4000005],rson[4000005],sum[4000005];
void buildtree(int &i,int l,int r){
    i=++cnt;
    if(l==r) return ;
    buildtree(lson[i],l,(l+r)/2);
    buildtree(rson[i],(r+l)/2+1,r);
}
void update(int &i,int pre,int l,int r,int x){
    i=++cnt;
    sum[i]=sum[pre]+1;
    lson[i]=lson[pre],rson[i]=rson[pre];
    if(l==r) return;
    int m=(l+r)/2;
    if(x<=m) update(lson[i],lson[pre],l,m,x);
    if(x>m) update(rson[i],rson[pre],m+1,r,x);
}
int query(int down,int up,int l,int r,int k){
    if(l==r) return l;
    int x=sum[lson[up]]-sum[lson[down]];
    if(x>=k) return query(lson[down],lson[up],l,(l+r)/2,k);
    else return query(rson[down],rson[up],(l+r)/2+1,r,k-x);
}
