    buildtree(root[0],1,tot);
    for(int i=1;i<=n;i++){
        int x=lower_bound(b+1,b+1+tot,a[i])-b;
        update(root[i],root[i-1],1,tot,x);
    }
    for(int l=1;l<n;l++){
        for(int r=l+1;r<=n;r++){
            sum+=b[query(root[l-1],root[r],1,tot,r-l)];
        }
    }
    cout<<sum;
}

