#define lli long long int
#define pii pair <int,int>
vector<int> a;
vector<int> t1;
vector<pii> t2;
pii combine(pii a,pii b)
{
    pii ans = make_pair(0,0);
    if(a.first>b.first)
    {
        ans.first = a.first;
        if(a.second>b.first)
            ans.second = a.second;
        else
            ans.second = b.first;
    }
    else
    {
        ans.first = b.first;
        if(b.second>a.first)
            ans.second = b.second;
        else
            ans.second = a.first;
    }
    return ans;
}
void build2(int node,int l,int r)
{
    if(l==r)
        {
            t2[node].first = a[l];
            t2[node].second = 0;
        }
    else
    {
        int mid = (l+r)/2;
        build2(2*node,l,mid);
        build2(2*node+1,mid+1,r);
        t2[node] = combine(t2[2*node],t2[2*node+1]);
    }
    return ;
}
pii query2(int node,int l,int r,int ql,int qr)
{
    if(ql>qr)
        return make_pair(0,0);
    if(l==ql && r==qr)
        return t2[node];
    int mid = (l+r)/2;
    if(qr<=mid)
        return query2(2*node,l,mid,ql,qr);
    if(ql>mid)
        return query2(2*node+1,mid+1,r,ql,qr);
    return combine(query2(2*node,l,mid,ql,mid),query2(2*node+1,mid+1,r,mid+1,qr));
}
void build1(int node,int l,int r)
{
    if(l==r)
        t1[node]=a[l]; 
    else
    {
        int mid = (l+r)/2;
        build2(2*node,l,mid);
        build2(2*node+1,mid+1,r);
        t1[node] = max(t1[2*node],t1[2*node+1]);
    }
    return ;
}
int query1(int node,int l,int r,int ql,int qr)
{
    if(ql>qr)
        return 0;
    if(l==ql && r==qr)
        return t1[node];
    int mid = (l+r)/2;
    if(qr<=mid)
        return query1(2*node,l,mid,ql,qr);
    if(ql>mid)
        return query1(2*node+1,mid+1,r,ql,qr);
    return max(query1(2*node,l,mid,ql,mid),query1(2*node+1,mid+1,r,mid+1,qr));
}
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin>>n;
    a.resize(n);
    t1.resize(4*n+4);
    t2.resize(4*n+4);
    int i;
    vector<int> pos;
    pos.resize(n+1);
    for(i=0;i<n;i++)
    {
        cin>>a[i];
        pos[a[i]] = i;
    }
    build1(1,0,n-1);
    build2(1,0,n-1);
    lli ans = 0;
    for(i=0;i<n;i++)
    {
        int tl,tr;
        pii lft = query2(1,0,n-1,0,i-1);
        if(a[i]>lft.first)
            tl=0;
        else if(a[i]>lft.second)
            tl=1;
        else
            tl=2;
        pii rgt = query2(1,0,n-1,i+1,n-1);
        if(a[i]>rgt.first)
            tr=0;
        else if(a[i]>rgt.second)
            tr=1;
        else
            tr=2;
        lli x1=0,x2=0,x3=0,x4=0;
        if(tl==0){
            x1 = -1;
            x2 = i;
        }
        else if(tl==1)
        {
            x1 = pos[lft.first];
            x2 = i-x1-1;
        }
        else
        {
            int lo = 0;
            int hi = i;
            int md;
            while(lo<hi)
            {
                md = lo + (hi-lo)/2;
                int vl = query1(1,0,n-1,md,i);
                if(vl==a[i])
                    hi = md;
                else
                    lo = md+1;
            }
            int p1 = lo-1;
            lo = 0;
            hi = p1;
            while(lo<hi)
            {
                md = lo + (hi-lo)/2;
                pii vl = query2(1,0,n-1,md,i);
                if(vl.second==a[i])
                    hi = md;
                else
                    lo = md+1;
            }
            int p2 = lo-1;
            x1 = p1-p2-1;
            x2 = i-p1-1;
            // cout<<a[i]<<" l "<<p1<<" "<<" "<<p2<<endl;;
        }
        if(tr==0){
            x3 = n-1-i;
            x4=-1;
        }
        else if(tr==1)
        {
            x3 = pos[rgt.first]-i-1;
            x4 = n-1-pos[rgt.first];
        }
        else
        {
            int lo = i;
            int hi = n-1;
            int md;
            while(lo<hi)
            {
                md = lo + (hi-lo)/2;
                int vl = query1(1,0,n-1,i,md);
                if(vl==a[i])
                    lo = md+1;
                else
                    hi= md;
            }
            int p1 = lo+1;
            lo = p1;
            hi = n-1;
            while(lo<hi)
            {
                md = lo + (hi-lo)/2;
                pii vl = query2(1,0,n-1,i,md);
                if(vl.second==a[i])
                    lo = md+1;
                else
                    hi = md;
            }
            int p2 = lo;
            x3 = p1-i-1;
            x4 = p2-p1-1;
            // cout<<a[i]<<" r "<<p1<<" "<<" "<<p2<<endl;;
        }
        lli curterm = a[i]*((x1+1)*(x3+1) + (x2+1)*(x4+1));
        // cout<<curterm<<endl;
        ans = ans + curterm;
    }
    cout<<ans<<endl;
    return 0;
}

