    long long res = 0;
    set<int> S;
    S.insert(0); S.insert(N + 1);
    for(P a : A) {
        int index = a.second;
        auto itr = S.upper_bound(index);
        if(++itr != S.end()) {
            int com = *itr--;
            com -= *itr--;
            com *= (index - *itr);
            res += a.first * com;
        }
        itr = S.upper_bound(index);
        if(--itr != S.begin()) {
            int com = *itr--;
            com -= *itr++;
            com *= *(++itr) - index;
            res += a.first * com;
        }
        S.insert(index);
    }
    cout << res << endl;
