int p[200005];

int root(int x) {return p[x] < 0 ? x : p[x] = root(p[x]);}

void mer(int x, int y) {
    if ((x = root(x)) == (y = root(y))) return;
    if (p[x] > p[y]) swap(x, y);
    p[x] += p[y];
    p[y] = x;
}

int n, t[100005];

void inc(int x) {
    for (; x <= n; x += x & -x) t[x]++;
}

int que(int x) {
    int z = 0;
    for (; x; x -= x & -x) z += t[x];
    return z;
}

int main() {
    ios::sync_with_stdio(false);
    int a[100005] = {}, b[100005] = {}, c[100005] = {}, d[100005] = {}, e[100005] = {}, f[100005] = {};
