    for (int i = n; i; i--) {
        int l = 0, r = f[i];
        while (l + 1 < r) {
            int m = (l + r) / 2;
            if (que(f[i]) - que(m - 1) < 1) r = m;
            else l = m;
        }
        b[f[i]] = l;
        l = 0, r = f[i];
        while (l + 1 < r) {
            int m = (l + r) / 2;
            if (que(f[i]) - que(m - 1) < 2) r = m;
            else l = m;
        }
        c[f[i]] = l;
        l = f[i], r = n + 1;
        while (l + 1 < r) {
            int m = (l + r) / 2;
            if (que(m) - que(f[i]) < 1) l = m;
            else r = m;
        }
        d[f[i]] = r;
        l = f[i], r = n + 1;
        while (l + 1 < r) {
            int m = (l + r) / 2;
            if (que(m) - que(f[i]) < 2) l = m;
            else r = m;
        }
        e[f[i]] = r;
        //for (int j = 1; j <= n; j++) cout << que(j) << ' '; cout << '\n';
        inc(f[i]);
    }
    for (int i = 1; i <= n; i++) {
        //cout << b[i] << ' ' << c[i] << ' ' << d[i] << ' ' << e[i] << '\n';
        z += 1ll * a[i] * (b[i] - c[i]) * (d[i] - i) + 1ll * a[i] * (i - b[i]) * (e[i] - d[i]);
    }
    cout << z;
}

