{
	cin >> n;
	vec = new type[n];
	type * const start = vec;
	type * const end = vec + n;
	for (type * i = start; i < end; i++)
		scanf_s("%d", &*i);
	func(start, end);
	printf_s("%d", ans);
	return 0;
}

