long think(vector<int> input) {
  auto n = input.size();
  auto dp1 = vector< vector<int> > (n, vector<int> (n, 0));
  auto dp2 = vector< vector<int> > (n, vector<int> (n, 0));

  for (int i = 0; i < n - 1; i++) {
    dp1.at(i).at(i + 1) = max(input.at(i), input.at(i + 1));
    dp2.at(i).at(i + 1) = min(input.at(i), input.at(i + 1));
  }

  for (int left = 0; left < n - 1; left++) {
    for (int right = left + 2; right < n; right++) {
      if (dp2.at(left).at(right - 1) > input.at(right)) {
        dp1.at(left).at(right) = dp1.at(left).at(right - 1);
        dp2.at(left).at(right) = dp2.at(left).at(right - 1);
      } else {
        if (dp1.at(left).at(right- 1 ) <= input.at(right)) {
          dp2.at(left).at(right) = dp1.at(left).at(right - 1);
          dp1.at(left).at(right) = input.at(right);
        } else {
          dp1.at(left).at(right) = dp1.at(left).at(right - 1);
          dp2.at(left).at(right) = input.at(right);
        }
      }
    }
  }

  long total = 0;
  for (int left = 0; left < n - 1; left++) {
    for (int right = left + 1; right < n; right++) {
      total += dp2.at(left).at(right);
    }
  }
  return total;
}

