int IT[maxN * 4];
void up(int i, int L, int R, int u, int val) {
    if (L > u || R < u) return;
    if (L == R) {
        IT[i] = val;
        return;
    }
    int mid = (L + R) >> 1;
    up(i << 1, L, mid, u, val);
    up(i << 1 | 1, mid + 1, R, u, val);
    IT[i] = max(IT[i << 1], IT[i << 1 | 1]);
}
int Get(int i, int L, int R, int u, int v) {
    if (L > v || R < u) return 0;
    if (L >= u && R <= v) return IT[i];
    int mid = (L + R) >> 1;
    int Left = Get(i << 1, L, mid, u, v);
    int Right = Get(i << 1 | 1, mid + 1, R, u, v);
    return max(Left, Right);
}
int n;
int Next(int x, int L, int R) {
    int Res = L;
    int tmp = L;
    while (L <= R) {
        int mid = (L + R) >> 1;
        if (Get(1, 1, n, tmp + 1, mid) < x) {
            Res = mid;
            L = mid + 1;
        }
        else R = mid - 1;
    }
    return Res;
}
int Prev(int x, int L, int R) {
    int Res = R;
    int tmp = R;
    while (L <= R) {
        int mid = (L + R) >> 1;
        if (Get(1, 1, n, mid, tmp - 1) < x) {
            Res = mid;
            R = mid - 1;
        }
        else L = mid + 1;
    }
    return Res;
}
void solve() {
    cin >> n;
    int P[n + 1], L[n + 1], R[n + 1];
    for (int i = 1; i <= n; i++) {
        cin >> P[i];
        up(1, 1, n, i, P[i]);
    }
    for (int i = 1; i <= n; i++) {
        L[i] = i;
        int k = i - 1;
        while (k >= 1 && P[i] > P[k]) {
            L[i] = L[k];
            k = L[k] - 1;
        }
    }
    for (int i = n; i >= 1; i--) {
        R[i] = i;
        int k = i + 1;
        while (k <= n && P[i] > P[k]) {
            R[i] = R[k];
            k = R[k] + 1;
        }
    }
    long long Res = 0;
    for (int i = 1; i <= n; i++) {
        int Le = L[i];
        int Ri = R[i];
        if (Le == 1 && Ri == n) continue;
        int nRi = Next(P[i], Ri + 1, n);
        int pLe = Prev(P[i], 1, Le - 1);
        if (Le != 1) Res += (Le - pLe) * (Ri - i + 1) * P[i];
        if (Ri != n) Res += (nRi - Ri) * (i - Le + 1) * P[i];
        //cout << Res << '\n';
    }
    cout << Res;
}
