using namespace std;

const int N = 1e5 + 5;

int arr[N], mxl[N], mxr[N], mx[N<<3], n;

void build(int ind, int l, int r)
{
    if(l == r)
    {
        mx[ind] = arr[l];
        return;
    }
    int mid = (l+r)>>1;
    build(ind<<1, l, mid);
    build(ind<<1|1, mid+1, r);
    mx[ind] = max(mx[ind<<1], mx[ind<<1|1]);
}

int getL(int ind, int l, int r, int s, int e, int v)
{
    if(e < l or s > r or mx[ind] < v) return n;
    if(l == r) return l;
    int mid = (l+r)>>1;
    if(l >= s and r <= e)
    {
        if(mx[ind<<1] > v)
        {
            return getL(ind<<1, l, mid, s, e, v);
        }
        else if(mx[ind<<1|1] > v) return getL(ind<<1|1, mid+1, r, s, e, v);
        else return n;
    }
    else return min(getL(ind<<1|1, mid+1, r, s, e, v), getL(ind<<1, l, mid, s, e, v));
}

int getR(int ind, int l, int r, int s, int e, int v)
{
    if(e < l or s > r or mx[ind] < v) return -1;
    if(l == r) return l;
    int mid = (l+r)>>1;
    if(l >= s and r <= e)
    {
        if(mx[ind<<1|1] > v)
        {
            return getR(ind<<1|1, mid+1, r, s, e, v);
        }
        else if(mx[ind<<1] > v) return getR(ind<<1, l, mid, s, e, v);
        else return -1;
    }
    else return max(getR(ind<<1|1, mid+1, r, s, e, v), getR(ind<<1, l, mid, s, e, v));
}

