    v.emplace_back(a.second);
    v.emplace_back(b.first);
    v.emplace_back(b.second);
    sort(v.rbegin(), v.rend());
    return P(v[0], v[1]);
  };
  SegmentTree<P> st1(n, func1, P(-1, -1));
  auto func2 = [](P a, P b) {
    vi32 v;
    v.emplace_back(a.first);
    v.emplace_back(a.second);
    v.emplace_back(b.first);
    v.emplace_back(b.second);
    sort(v.begin(), v.end());
    return P(v[0], v[1]);
  };
  SegmentTree<P> st2(n, func2, P(n, n));

  vector<vi32> r(n);
  rep(i, n) {
    auto pa = st1.query(p[i] + 1, n);
    r[i].emplace_back(pa.second);
    r[i].emplace_back(pa.first);
    st1.update(p[i], P(i, -1));
