    ll x=s-2-Left[s];
    while(P[x]<P[s]){
        res++;
        x--;
    }
    return res;
}
ll func_right(ll t){
    ll res=1;
    ll y=t+2+Right[t];
    while(P[y]<P[t]){
        res++;
        y++;
    }
