#include<bits/stdc++.h>
using namespace std;
using P = pair<int,int>;
using ll = long long;

vector<P> seg_tree;
int N;

P secmax(const P x, const P y){
    P ret;
    if(x.first > y.first){
        ret.first = x.first;
        ret.second = max(x.second, y.first);
    }else if(x.first < y.first){
        ret.first = y.first;
        ret.second = max(y.second, x.first);
    }else{
        ret.first = x.first;
        ret.second = y.first;
    }
    return ret;
}

void init(vector<int> &v){
  int n = v.size();
  N = pow(2, ceil(log2(n))); 
  seg_tree.resize(2*N-1);

  for(int i=0;i<N;i++) seg_tree[N-1+i] = make_pair(i>=n?0:v[i], 0);
  for(int i=N-2;i>=0;i--) seg_tree[i] = secmax(seg_tree[2*i+1], seg_tree[2*i+2]);
}

P query(int a, int b, int ind, int l, int r){
  if(r < a || b < l) return make_pair(0,0);
  if(a <= l && r <= b) return seg_tree[ind];
  else return secmax(query(a, b, 2*ind+1, l, (l+r)/2), 
                     query(a, b, 2*ind+2, (l+r)/2+1, r));
}

int main(){
    int n;
    cin >> n;
    vector<int> p(n);
    for(int i=0;i<n;i++) cin >> p[i];
    init(p);
    ll ans = 0;
    for(int l = 0; l < n; l++){
        for(int r = l+1; r<n;r++){
            ans += query(l, r, 0, 0, N-1).second;
        }
    }
    cout << ans << endl;
}

