void solve(long long N, std::vector<long long> P) {
    vector<pair<int, int> > a;
    for (int i = 0; i < P.size(); i++) a.push_back({P[i], i});
    sort(a.rbegin(), a.rend());

    set<int> ps;
    ps.insert(-1);
    ps.insert(-2);
    ps.insert(N);
    ps.insert(N + 1);

    long long ans = 0;
    for (auto i : a) {
        int l = *--ps.lower_bound(i.second);
        int r = *ps.upper_bound(i.second);
        if (l >= 0) {
            int l2 = *--ps.lower_bound(l);
            int r2 = *ps.upper_bound(i.second);
            ans += 1ll * (l - l2) * (r2 - i.second) * i.first;
        }

        if (r < N) {
            int r2 = *ps.upper_bound(r);
            int l2 = *--ps.lower_bound(i.second);
            ans += 1ll * (r2 - r) * (i.second - l2) * i.first;
        }
        ps.insert(i.second);
    }
    cout << ans << endl;

}

