vector<ll> right_bigger(vector<ll> p, int n)
{
    vector<ll> right(n);
    right[n-1] = n;
    rrep(i, n - 1, 0)
    {
        rep(j, i + 1, n)
        {
            if (p[i] < p[j])
            {
                right[i] = j;
                break;
            }
            else if (right[j] == n)
            {
                right[i] = n;
                break;
            }
            else
                j = right[j] - 1;
        }
    }
    return right;
}

