/*
 * 区間の最大値から2番目を準最大値と呼ぶことにする.
 * 区間を列挙するとO(N^2)かかるので、N-1個ある準最大値を１つずつxに固定した時に、
 * それを満たす区間のうち作れるものの組み合わせ数を数える.
 *
 * 順列Pの大きい方からx =（N-1, N-2, ..., 2, 1)見ていき、
 * すでにチェック済み集合Xをもっておくと、Xにはxよりも大きいもののみの集合になる.
 * xが準最大値とすると、自身より左右どちらかにちょうど1つXの要素を含み、
 * その反対サイドには１つも含まない組み合わせ.
 * 左右２つの和.
 */
#include <set>
const int k = 2;
void solve() {
  int n;
  cin >> n;
  vector<int> A(n);
  vector<int> idx(n);
  loop(i,0,n) {
    cin >> A[i];
    A[i]--;
    idx[A[i]] = i;
  }

  set<int> S;
  ll total = 0;
  for (int x=n-1; x>=0; x--) {
    int i = idx[x]; // oooxooooxoooioooxooxoox
    ll com = 0; // 組み合わせ
    {
      S.insert(i);
      vector<ll> ls(k, -1); // xよりも左にある大きい整数のインデックス. 大きい整数が無ければ距離をとった時に正しい値になるように-1
      vector<ll> rs(k, n); // xよりも右にある
      {
        // 左
        auto iter = S.find(i);
        loop(j,0,k) {
          if (iter == S.begin()) break; // begin=0, それより左のインデックスはない.
          iter--;
          ls[j] = *iter;
        }
      }
      {
        // 右
        auto iter = S.find(i);
        loop(j,0,k) {
          iter++;
          if (iter == S.end()) break; // end=n, それより左のインデックスはない.
          rs[j] = *iter;
        }
      }

      /*
       *    ls1  ls0     rs0  rs1
       * oooxooooxoooioooxooxoox
       *     -----
       *          ----
       *             ----
       *                 ---
       */
      // 自分より大きいのが左にある区間の数
      com += abs(ls[0]-ls[1]) * abs(rs[0] - i);
      // 自分より大きいのが右に
      com += abs(rs[1]-rs[0]) * abs(ls[0] - i);
    }
    total += com * (x+1);
  }

  cout << total << endl;
}

