    int blo,nall;
    void build() {
        blo = sqrt(n);
        for(int i = 1; i <= n; i++) {
            bel[i] = (i + blo - 1) / blo;
            v[bel[i]].push_back({a[i], i});
        }
        nall = bel[n];
        for(int i = 1; i <= nall; i++) sort(v[i].begin(), v[i].end());
        for(int i = 1; i <= nall; i++) {
            int m = v[i].size();
            for(int j = m - 1; j >= 0; j--) mx[i][j] = max(mx[i][j + 1], v[i][j].second),mi[i][j] = INF;
            for(int j = m - 1; j >= 0; j--) mi[i][j] = min(mi[i][j + 1], v[i][j].second);
        }
    }
    int queryleft(int l, int r, int w) {
        int ans = l - 1;
        if(l > r) return -1;
        int lb = (l + blo - 1) / blo;
        int rb = (r + blo - 1) / blo;
        if(lb == rb) {
            for(int i = r; i >= l; i--) {
                if(a[i] > w) {
                    return i;
                }
            }
        } else {
            int now = lb;
            for(int i = l; i <= min(lb * blo, n); i++) {
                if(a[i] > w) ans = max(i, ans);
            }
            now++;
            for(int i = now; i <= rb - 1; i++) {
                auto it = lower_bound(v[i].begin(), v[i].end(), make_pair(w, 0));
                if(it == v[i].end()) continue;
                else {
                    int p = lower_bound(v[i].begin(), v[i].end(), make_pair(w, 0)) - v[i].begin();
                    ans = max(mx[i][p], ans);
                }
            }
            for(int i = (rb - 1) * blo + 1; i <= r; i++) {
                if(a[i] > w) ans = max(i, ans);
            }
        }
        return ans;
    }
    int queryright(int l, int r, int w) {
        int ans = r + 1;
        if(l > r) return -1;
        int lb = (l + blo - 1) / blo;
        int rb = (r + blo - 1) / blo;
        if(lb == rb) {
            for(int i = r; i >= l; i--) {
                if(a[i] > w) {
                    ans = min(i, ans);
                }
            }
        } else {
            int now = lb;
            for(int i = l; i <= min(lb * blo, n); i++) {
                if(a[i] > w) ans = min(i, ans);
            }
            now++;
            for(int i = now; i <= rb - 1; i++) {
                auto it = lower_bound(v[i].begin(), v[i].end(), make_pair(w, 0));
                if(it == v[i].end()) continue;
                else {
                    int p = lower_bound(v[i].begin(), v[i].end(), make_pair(w, 0)) - v[i].begin();
                    ans = min(mx[i][p], ans);
                }
            }
            for(int i = (rb - 1) * blo + 1; i <= r; i++) {
                if(a[i] > w) ans = min(i, ans);
            }
        }
        if(ans == INF) return -1;
        return ans;
    }
}block;
