void init() {
    for (int i=n-1;i>0;i--) {
        dt[i] = opr(dt[i<<1],dt[i<<1|1]);
    }
}

int qry(int l,int r) {
    int ret = les;
    for (l+=n,r+=n;l<r;l>>=1,r>>=1) {
        if (l&1) {
            ret = opr(ret,dt[l++]);
        }
        if (r&1) {
            ret = opr(ret,dt[--r]);
        }
    }
    return ret;
}

int find_lft (int idx, int val) {
    int l = -1, r = idx;
    while (l < r - 1) {
        int m = (l + r) >> 1;
        if (qry(m, idx) > val) {
            l = m;
        } else {
            r = m;
        }
    }
    return l;
}

int find_rgt (int idx, int val) {
    int l = idx, r = n;
    while (l < r - 1) {
        int m = (l + r) >> 1;
        if (qry(idx+1, m+1) > val) {
            r = m;
        } else {
            l = m;
        }
    }
    return r;
}


