const bool DEBUG = false;

tuple<Memory, long long> reduce(const Memory& X) {
  long long total = 0;
  long long second;
  Memory Y(X.size() - 1);
  for (size_t i = 0; i < X.size() - 1; i++) {
    if (X[i].first == X[i + 1].first)
      second = max(X[i].second, X[i + 1].second);
    else
      second = max(min(X[i].first, X[i + 1].first),
                   max(X[i].second, X[i + 1].second));
    Y[i] = make_pair(max(X[i].first, X[i + 1].first), second);
    total += Y[i].second;
  }
  return forward_as_tuple(Y, total);
}

