	for (int index = 0; index < N; index++) {
		int leftMax = -1, leftMin = -1;
		for (int left = index - 1; left >= 0; left--) {
			if (P[left] > P[index]) {
				if (leftMin == -1) {
					leftMin = left;
				}
				else {
					leftMax = left;
					break;
				}
			}
		}
		int rightMax = N, rightMin = N;
		for (int right = index + 1; right < N; right++) {
			if (P[right] > P[index]) {
				if (rightMin == N) {
					rightMin = right;
				}
				else {
					rightMax = right;
					break;
				}
			}
		}
		sum += ((leftMin - leftMax) * int(rightMin - index) + (index - leftMin) * (rightMax - rightMin)) * P[index];
	}

	cout << sum << flush;
	return;
}

