}

vector<ll> place(N);
rep(i,N){
    place[P[i]]=i;
}
set<ll> s;
ll ans=0;
repr(x,N){
    s.insert(place[x]);
    auto it=s.find(place[x]);
    ll left[2],right[2];
    rep(j,2)left[j]=-1;rep(j,2)right[j]=N;
    rep(j,2){
        if(it==s.begin())break;
        --it;

        left[j]=*it;

    }
    auto it2=s.find(place[x]);
    rep(j,2){
        ++it2;
        if(it2==s.end())break;
        right[j]=*it2;


    }
    ll count=0;
    if(left[0]!=-1){
        count+=(right[0]-place[x])*(left[0]-left[1]);
    }
    if(right[0]!=N){
        count+=(right[1]-right[0])*(place[x]-left[0]);
    }
    ans+=count*(x+1);

}

out(ans);

}

