int main(){
	cin>>n;
	int x;
	for (int i=1;i<=n;i++){
		cin>>x;
		w[x]=i;
		L[i]=i-1;
		R[i]=i+1;
	}

	for (int i=1;i<=n;i++){
		int b=L[w[i]],a=L[b];
		int c=R[w[i]],d=R[c];
		if (b!=0) ans+=1ll*(b-a)*(c-w[i])*i;
		if (c!=n+1) ans+=1ll*(d-c)*(w[i]-b)*i;

		L[c]=b;
		R[b]=c;
	}

	cout<<ans;
	return 0;
}

