const int MAX_N=1e6+1;
int P[MAX_N];
int N;

int pos[MAX_N];
void solve() {
  REP(i,N) pos[P[i]]=i;
  multiset<int> S; S.emplace(-1),S.emplace(-1),S.emplace(N),S.emplace(N);
  LL res=0;
  for(int a=N; a>=1; --a) {
    int i=pos[a];
    auto r=S.upper_bound(i),l=r; --l;
    int l2=*l; --l; int l1=*l;
    int r1=*r; ++r; int r2=*r;
    LL x=(r1-i)*(l2-l1),y=(r2-r1)*(i-l2);
    res+=+(x+y)*a;
    S.emplace(i);
  }
  cout<<res<<endl;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout<<setprecision(12)<<fixed;

  cin>>N;
  REP(i,N) cin>>P[i];
  solve();

  return 0;
}

