// no MOD


void solve(int n, vi p) {
  vi ids(n);
  rep(i, n)ids[p[i]] = i;
  seti ui;
  ui.insert(-1);
  ui.insert(n);
  ui.insert(ids[n - 1]);
  int ans = 0;
  rrep(i, n - 1) {
    ui.insert(ids[i]);
    auto it = ui.find(ids[i]);
    auto pr = prev(it), ne = next(it);
    int cnt = 0;
    if(*pr != -1)cnt += (*next(it) - *it) * (*pr - *prev(pr));
    if(*ne != n)cnt += (*next(ne) - *ne) * (*it - *prev(it));
    ans += (i + 1) * cnt;
  }
  COUT(ans);
}


