constexpr int N = 100000 + 10, L = 22;
int n, p[N], mx[N][L], lg[N];

int Mx(int l, int r) {
    int j = lg[r - l + 1];
    return max(mx[l][j], mx[r - (1 << j) + 1][j]);
}

int mn_idx(int l, int r, int x) {
    if(r < l || Mx(l, r) < x) return r;
    int L = l, R = r;
    while(r - l > 1) {
        int m = (l + r) >> 1;
        if(Mx(L, m) > x) {
            r = m;
        } else {
            l = m + 1;
        }
    }
    if(Mx(L, l) > x) r = l;
    return r;
}

int mx_idx(int l, int r, int x) {
    if(r < l || Mx(l, r) < x) return l;
    int L = l, R = r;
    while(r - l > 1) {
        int m = (l + r) >> 1;
        if(Mx(m, R) > x) {
            l = m;
        } else {
            r = m - 1;
        }
    }
    if(Mx(r, R) > x) l = r;
    return l;
}


int main() {
    ios::sync_with_stdio(0); cin.tie(0);
    cin >> n;
    for(int i = 1; i <= n; ++i) {
        cin >> p[i];
        mx[i][0] = p[i];
    }
    for(int i = 2; i < N; ++i) {
        lg[i] = lg[i >> 1] + 1;
    }
    for(int j = 1; j < L; ++j) {
        for(int i = 0; i + (1 << j) < N; ++i)
            mx[i][j] = max(mx[i][j - 1], mx[i + (1 << (j - 1))][j - 1]);
    }

    long long ans = 0;
    for(int i = 1; i <= n; ++i) {
        int lr = mx_idx(0, i - 1, p[i]);
        int ll = mx_idx(0, lr - 1, p[i]);
        int rl = mn_idx(i + 1, n + 1, p[i]);
        int rr = mn_idx(rl + 1, n + 1, p[i]);

        long long t = 0;
        t += 1ll * (lr - ll) * (rl - i) * p[i];
        t += 1ll * (rr - rl) * (i - lr) * p[i];
        ans += t;
    }
    cout << ans << '\n';
}

