int X(const vector<int> &P, const int &L, const int &R) {
	int l = P.at(L+1);
	int sl = P.at(L);
	if (P.at(L) > P.at(L+1)) {
		l = P.at(L);
		sl = P.at(L+1);
	}

	for (int i = L; i <= R; i++) {
		if (P.at(i) > l) {
			sl = l;
			l = P.at(i);
		} else if (P.at(i) > sl && P.at(i) < l) {
			sl = P.at(i);
		}
	}

	return sl;
}

