                uppers[1][p] = *itr;
            }
        }
        itr = used2.lower_bound(-idx);
        if(itr != used2.end()) {
            lowers[0][p] = -*itr;
            itr = used2.upper_bound(*itr);
            if(itr != used2.end()) {
                lowers[1][p] = -*itr;
            }
        }
        cerr << p << ", " << idx << ": " << lowers[1][p] << " " << lowers[0][p] << " " << uppers[0][p] << " " << uppers[1][p] << endl;

        ans += (lowers[0][p]-lowers[1][p]) * (uppers[0][p] - idx) * p;
        ans += (uppers[1][p]-uppers[0][p]) * (idx - lowers[0][p]) * p;

        used.insert(idx);
        used2.insert(-idx);

    }
    cout << ans << endl;
}

