template<typename dtype, dtype initValue/*範囲外のときに返す値*/>
class RMQ{
public:
  int n,n_;
  vector<dtype> dat;
  int toMax;

  //初期化
  RMQ(){n=-1;}
  RMQ(int n_,int toMax = 0):n_(n_),toMax(toMax){
    n=1;
    while(n<n_)n*=2;
    dat.resize(2*n-1,initValue);
  }

  inline dtype merge(dtype a,dtype b){return toMax? max(a, b):min(a, b); }

  //k番目の値をaに変更
  void update(int k,dtype a){
    k+=n-1;
    dat[k]=a;
    while(k>0){
      k=(k-1)/2;
      dat[k]=merge(dat[k*2+1],dat[k*2+2]);
    }
  }

  dtype dfs(int a,int b,int k,int l,int r){
    if(r<=a||b<=l)return initValue;
    if(a<=l&&r<=b)return dat[k];
    dtype vl = dfs(a,b,k*2+1,l,(l+r)/2);
    dtype vr = dfs(a,b,k*2+2,(l+r)/2,r);
    return merge(vl,vr);
  }

  //[a,b)の最小値を求める
  dtype get(int a,int b){
    assert(a <= b), assert(a <= n_ && b <= n_), assert(a >= 0 && a >= 0);
    return dfs(a,b,0,0,n);
  }
};

Int solve(Int N, vector<Int> A){
  vector<Int> Idx(N);
  for(Int i=0;i<N;i++) Idx[A[i]] = i;

  RMQ<Int, -INF> seg(N, 1);
  for(Int i=0;i<N;i++) seg.update(i, A[i]);

  auto get = [&](Int l, Int r){ //[l, r)
    Int top = seg.get(l, r);
    seg.update(Idx[top], -INF);
    Int top2 = seg.get(l, r);
    seg.update(Idx[top], top);
    return top2;
  };

  auto calc = [&](Int l){
    Int L = 0, R = N - l;
    while(L + 1 < R){
      Int M = (L + R) / 2;
      if( seg.get(l, l + M + 1) == A[l]) L = M;
      else R = M;
    }
    return l + L;
  };

  auto calc1 = [&](Int l, Int L){
    Int R = N - l;
    while(L + 1 < R){
      Int M = (L + R) / 2;
      if( get(l, l + M + 1) == A[l] ) L = M;
      else R = M;
    }
    return l + L;
  };

  auto calc2 = [&](Int l){
    Int L = 0, R = l + 1;
    while(L + 1 < R){
      Int M = (L + R) / 2;
      if( seg.get(l - M, l+1) == A[l] ) L = M;
      else R = M;
    }
    return L;
  };

  Int ans = 0;
  for(Int i=0;i<N - 1;i++){
    Int numRight = calc(i) + 1;
    if(numRight == N) continue;
    Int len = calc1(i, numRight - i) - numRight + 1;
    Int numLeft = calc2(i) + 1;
    Int score = len * numLeft * (A[i] + 1);
    //pr(i, A[i], numRight, calc1(i, numRight - i), len, numLeft, score);
    ans += score;
  }
  return ans;
}

