	ll res = 0;
	for (size_t i = 1; i < n; i++)
	{
		auto v = st.lower_bound(p[i].second);
		if (v == st.end()) { // 一番後ろに追加
			ll t = n - (p[i].second - 1);
			v--;
			ll bi = *v;
			ll fr = 0;
			if (v != st.begin()) {
				v--;
				fr = bi - *v;
			}
			else {
				fr = *v;
			}
			res += p[i].first * t * fr;
		}
		else if (v == st.begin()) { // 一番前に追加
			ll fr = p[i].second;
			ll bi = *v;
			v++;
			ll t = 0;
			if (v == st.end()) {
				t = n - (bi - 1);
			}
			else {
				t = *v - bi;
			}
			res += p[i].first * fr * t;
		}
		else { // 中に追加
