			if (v2 == st.end()) {
				t = n - (v2bi - 1);
			}
			else {
				t = *v2 - v2bi;
			}
			res += p[i].first * fr * (v2bi-p[i].second);
			res += p[i].first * t * (p[i].second - bi);
		}
