using namespace std;

const int DEPTH = 17;
struct SegTree {
	int d[1 << (DEPTH + 1)];
	SegTree() {
		int i;
		rep(i, (1 << (DEPTH + 1))) d[i] = 0;
	}

	void update(int pos, int x) {
		pos += (1 << DEPTH) - 1;
		d[pos] = x;
		while (pos > 0) {
			pos = (pos - 1) / 2;
			d[pos] = max(d[pos * 2 + 1], d[pos * 2 + 2]);
		}
	}

	int getMax(int l, int r, int a = 0, int b = (1 << DEPTH), int id = 0) {
		if (a >= r || b <= l) return 0;
		if (l <= a && b <= r) return d[id];
		int vl = getMax(l, r, a, (a + b) / 2, id * 2 + 1);
		int vr = getMax(l, r, (a + b) / 2, b, id * 2 + 2);
		return max(vl, vr);
	}

};

int n;
int p[100000];
SegTree seg;

int getL(int pos, int x) {
	int st = -1, ed = pos, mid; //oooxxx, [st, ed)
	while (ed - st >= 2) {
		mid = (st + ed) / 2;
		if (seg.getMax(mid, pos) > x) st = mid;
		else ed = mid;
	}
	return st;
}

int getR(int pos, int x) {
	int st = pos, ed = n, mid;	//xxxooo, (st, ed]
	while (ed - st >= 2) {
		mid = (st + ed) / 2;
		if (seg.getMax(pos + 1, mid + 1) > x) ed = mid;
		else st = mid;
	}
	return ed;
}

