class memoization_t
{
	std::map<std::int64_t, index_t> map;
	max_seg_tree seg;
	std::size_t N;
	std::int64_t run(index_t lhs, index_t rhs, index_t mid, std::int64_t v)
	{
		if (lhs == rhs)
		{
			return 0;
		}
		else if (lhs == mid)
		{
			std::int64_t sum = 0;
			for (auto i = lhs + 1; i <= rhs; ++i)
			{
				auto s = seg(lhs + 1, i + 1);
				if (s == v - 1)
				{
					sum += (v - 1) * (rhs - i + 1);
					return sum + run(i, lhs + 1, i, v - 1);
				}
				else
				{
					sum += s;
				}
			}
		}
		else if (rhs == mid)
		{
			std::int64_t sum = 0;
			for (auto i = rhs - 1; lhs <= i; --i)
			{
				auto s = seg(i, rhs);
				if (s == v - 1)
				{
					sum += (v - 1) * (i - lhs + 1);
					return sum + run(lhs, rhs - 1, i, v - 1);
				}
				else
				{
					sum += s;
				}
			}
		}
		else
		{
			std::priority_queue<std::pair<std::int64_t, index_t>> queue;
			for (auto i : boost::irange(lhs, mid))
			{
				queue.emplace(seg(i, mid), i);
			}
			for (auto i : boost::irange(mid + 1, rhs + 1))
			{
				queue.emplace(seg(mid + 1, i + 1), i);
			}
			std::int64_t sum = 0;
			auto ilhs = lhs;
			auto irhs = rhs;
			while (queue.size())
			{
				auto p = queue.top();
				auto s = p.first;
				auto i = p.second;
				queue.pop();
				if (i < mid)
				{
					sum += (i - ilhs + 1) * (irhs - mid + 1) * s;
					ilhs = i + 1;
				}
				else
				{
					sum += (irhs - i + 1) * (mid - ilhs + 1) * s;
					irhs = i + 1;
				}
			}
			auto left = seg(lhs, mid);
			auto right = seg(mid + 1, rhs + 1);
			return sum + run(lhs, mid - 1, map[left], left) + run(mid + 1, rhs, map[right], right);
		}
		return 0;
	}
public:
	memoization_t(std::vector<std::int64_t>const& values) :map(), seg(values.size()), N(values.size())
	{
		for (auto i : boost::irange<index_t>(0, N))
		{
			map[values[i]] = i;
		}
		seg.set(values);
	}
	memoization_t(memoization_t const&) = delete;
	memoization_t(memoization_t&&) = delete;

	auto operator()()
	{
		return run(0, N - 1, map[N], N);
	}
};


void Main()
{
	int N;
	std::cin >> N;
	std::vector<std::int64_t> values(N);
	for (auto& v : values)
	{
		std::cin >> v;
	}
	memoization_t memo(values);
	std::cout << memo() << std::endl;
}

