struct Node {
	int l, r, c;
	ll s, res;
	Node(int l, int r, int c, ll s, ll res) : l(l), r(r), c(c), s(s), res(res) {}
	void print() {
		cout << "(" << l << ", " << r << "): " << c << " " << res << endl;
	}
};

int main() {
	int n;
	cin >> n;
	vector<int> p(n);
	vector<int> pos(n + 1);
	vector<vector<PII>> st(n, vector<PII>(20));
	for (int i = 0; i < n; i++) {
		cin >> p[i];
		pos[p[i]] = i;
		st[i][0] = make_pair(p[i], -1);
	}
	for (int k = 1; 1 << k <= n; k++) {
		// cout << k << endl;
		int b = 1 << (k - 1);
		for (int i = 0; i <= n - (1 << k); i++) {
			int j = i + b;
			// cout << i << " " << j << endl;
			vector<int> v(4);
			v[0] = st[i][k - 1].first;
			v[1] = st[j][k - 1].first;
			v[2] = st[i][k - 1].second;
			v[3] = st[j][k - 1].second;
			sort(v.begin(), v.end());
			st[i][k].first = v[3];
			st[i][k].second = v[2];
		}
	}
	ll ans = 0;
	stack<Node> s;
	s.push(Node(0, n - 1, 0, 1, 0));
	while (s.size()) {
		Node cur = s.top();
		// cur.print();
		if (cur.c == 3) {
			ans = cur.res;
			// cur.print();
			s.pop();
			if (s.size()) {
				s.top().res += cur.s * cur.res;
				// cout << "Update--";
				// s.top().print();
			}
			continue;
		}
		int k = 1;
		int p1, p2;
		ll val = 0;
		while (1 << (k + 1) <= cur.r - cur.l + 1) k++;
		if (1 << k == cur.r - cur.l + 1) {
			val = st[cur.l][k].second;
			p1 = pos[st[cur.l][k].first];
			p2 = pos[st[cur.l][k].second];
			if (p1 > p2) swap(p1, p2);
		} else{
			int i, j;
			i = cur.l, j = cur.r - (1 << k) + 1;
			vector<int> v(4);
			v[0] = st[i][k].first;
			v[1] = st[j][k].first;
			v[2] = st[i][k].second;
			v[3] = st[j][k].second;
			sort(v.begin(), v.end());
			p1 = pos[v[3]];
			for (int ptr = 2; ptr >= 0; ptr--) {
				if (v[ptr] != v[ptr + 1]) {
					val = v[ptr];
					p2 = pos[v[ptr]];
					break;
				}
			}
			if (p1 > p2) swap(p1, p2);
		}
		if (cur.c == 0) {
			s.top().res += (p1 - cur.l + 1) * (cur.r - p2 + 1) * val;
			// cout << "Update--";
			// s.top().print();
			s.top().c = 1;
			if (p2 - 1 > cur.l) {
				s.push(Node(cur.l, p2 - 1, 0, 1, 0));
			}
		}
		if (cur.c == 1) {
			s.top().c = 2;
			if (p1 + 1 < cur.r) {
				s.push(Node(p1 + 1, cur.r, 0, 1, 0));
			}
		}
		if (cur.c == 2) {
			s.top().c = 3;
			if (p1 + 1 < p2 - 1) {
				s.push(Node(p1 + 1, p2 - 1, 0, -1, 0));
			}
		}
	}
	cout << ans << endl;
	return 0;
}

