    scanf("%d", &n);
    vector<int> p(n), pos(n);
    for(int &i: p){
        scanf("%d", &i);
    }
    rep(i, n) pos[i] = i;
    sort(pos.begin(), pos.end(), [&p](int a, int b){return p[a] > p[b];});

    SegTree<int> st(n, 0, plus<>(), plus<>());
    lint ans = 0;

    for(int i: pos){
        int a = st.upper_bound_right(i, 1);
        int b = st.lower_bound_right(i, 1);
        int c = min(n, st.lower_bound_left(i, 1));
        int d = min(n, st.upper_bound_left(i, 1));
        if(b >= 0) ans += (lint)p[i] * (b-a) * (c-i);
        if(c < n) ans += (lint)p[i] * (d-c) * (i-b);
        st.update(i, 1);
    }
    printf("%lld\n", ans);
}

