void solve()
{
	READ(int, N);
	auto A = read<int>(N);
	vector<int> R(N);

	REP(i, N)
	{
		R[A[i] - 1] = i;
	}

	multiset<int> visited;

	visited.insert(-1);
	visited.insert(-1);
	visited.insert(N);
	visited.insert(N);

	llong ans = 0;
	RREP(i, N)
	{
		int index = R[i];
		visited.insert(index);

		auto it = visited.find(index);

		int c = *it;
		auto lit = it;
		llong l = *--lit;
		llong ll = *--lit;
		auto rit = it;
		llong r = *++rit;
		llong rr = *++rit;

		ans += (l - ll) * (r - c) * (i + 1);
		ans += (rr - r) * (c - l) * (i + 1);
	}
	WRITE(ans);
}

