int searchR(const int i, const int val)
{
    int lo = i, hi = n;
    while (lo < hi) {
        const int mid = lo + (hi-lo)/2;
        if (query(i,mid+1,n) > val)
            hi = mid;
        else
            lo = mid+1;
    }
    return lo;
}

