template<typename T>
class segment_tree{
	int n;
	T fval;
	function<T(T,T)> operation;
	vector<T> dat;

	T _query(int a, int b, int k, int l, int r){
		if(r <= a || b <= l){
			return fval;
		}

		if(a <= l && r <= b){
			return dat[k];
		}else {
			T vl = _query(a, b, k * 2 + 1, l, (l + r) / 2 );
			T vr = _query(a, b, k * 2 + 2, (l + r) / 2, r);
			return operation(vl, vr);
		}
	}

public:

	segment_tree(){

	}

	segment_tree(int n_, T val, function<T(T,T)> fun){
		init(n_, val, fun);
	}

	~segment_tree(){

	}

	void init(int n_, T val, function<T(T,T)> fun){
		fval = val;

		operation = fun;

		n = 1;

		while(n < n_) n *= 2;

		dat.resize(2 * n - 1);

		for(int i = 0; i < 2 * n - 1; i++) dat[i] = fval;
	}

	void update(int k, T a){
		k += n - 1;
		dat[k] = a;
		while(k > 0){
			k = (k - 1) / 2;
			dat[k] = operation(dat[k*2 + 1],dat[k*2 + 2]);
		}
	}

	T query(int a, int b){
		return _query(a, b, 0, 0, n);
	}

};

segment_tree<pair<int,int>> seg;
vector<int> P;
int N;
map<pair<int,int>,int> mp;

int solve(int l = 0, int r = N-1){
	if(l >= r) return 0;
	int L = l, R = r;

	if(mp[make_pair(l,r)]) return mp[make_pair(l,r)]-1;
	if(L+1 == R) return min(P[L],P[R]);


	pair<int,int> max1 = seg.query(l, r + 1);
	seg.update(max1.second, make_pair(0, max1.second));
	pair<int,int> max2 = seg.query(l, r + 1);
	int res = 0;

	// cout<<"l = "<<l<<" r = "<<r<<endl;

	if(max1.second < max2.second){
		res += (max1.second + 1 - l) * (r + 1 - max2.second) * max2.first;
		l = max1.second;
		r = max2.second;
	} else {
		res += (max2.second + 1 - l) * (r + 1 - max1.second) * max2.first;
		l = max2.second;
		r = max1.second;
	}

	seg.update(max1.second, max1);

	// cout<<"l = "<<l<<" r = "<<r<<" B"<<endl;
	// cout<<"max1 "<<max1.first<<" "<<" max2 "<<max2.first<<endl;
	// cout<<"res = "<<res<<endl;
	// cout<<"seg "<<seg.query(0, 0 + 1).first<<" "<<seg.query(1, 1 + 1).first<<" "<<seg.query(2, 2 + 1).first<<endl;

	// string hogehoge; 
	// cin>>hogehoge;
	mp[make_pair(l,r)] = res+1;

	if(L+1 == R) return  res;
	res += solve(L,r-1);
	res += solve(l+1,R);
	res -= solve(l+1,r-1);

	return res;
}

