// dijkstra
template<typename T, int MAXN>
struct dijkstra {
  struct edge {
    T cost; int to; 
    edge(T const& c, int id): cost(c), to(id){}
  };
  typedef std::pair<T, int> GP; // dist, id
  std::vector<edge> G[MAXN];
  T d[MAXN], INF_;
  int N_;
  dijkstra(int N, T inf) : N_(N), INF_(inf) {}
  void search(int s) {
    std::priority_queue<GP, std::vector<GP>, std::greater<GP>> q;
    std::fill_n(d, N_, INF_);
    d[s] = 0;
    q.push(GP(0, s));
    while(!q.empty()) {
      GP p = q.top(); q.pop();
      int v = p.second;
      if(d[v] < p.first) continue;
      for(auto e: G[v]) {
        T newd = d[v]+e.cost;
        if(newd >= d[e.to]) continue;
        if(newd >= INF_) continue;
        d[e.to] = newd;
        q.push(GP(d[e.to], e.to));
      }
    }
  }
};

int const MAXN = 50;
int const MAXM = 100;
int const MAXA = 50;
int const MAXS = (MAXN-1)*MAXA;
int64_t const INF = 1e18;
int N, M, S, U[MAXM], V[MAXM], A[MAXM];
int64_t B[MAXM];

int main() {
  std::cin >> N >> M >> S;
  int maxa = 0, maxs;
  for(int i = 0; i < M; ++i) {
    std::cin >> U[i] >> V[i] >> A[i] >> B[i]; --U[i]; --V[i];
    maxa = std::max(maxa, A[i]);
  }
  maxs = maxa*(N-1);
  dijkstra<int64_t, (MAXS+1)*MAXN> dj(N*(maxs+1), INF);
  for(int i = 0; i < M; ++i) {
    // add train edge; (U,S)->(V,S-A) and (V,S)->(U,S-A) cost B
    for(int s = A[i]; s <= maxs; ++s) {
      dj.G[s*N+U[i]].emplace_back((int64_t)B[i], (s-A[i])*N+V[i]);
      dj.G[s*N+V[i]].emplace_back((int64_t)B[i], (s-A[i])*N+U[i]);
    }
  }
  for(int i = 0; i < N; ++i) {
    // add exchange edge; (i,S)->(i,min(S+C, maxs)) cost D
    int C, D; std::cin >> C >> D;
    for(int s = 0; s < maxs; ++s) {
      dj.G[s*N+i].emplace_back((int64_t)D, std::min(maxs, s+C)*N+i);
    }
  }
  dj.search(std::min(maxs, S)*N);
  for(int i = 1; i < N; ++i) {
    int64_t ans = INF;
    for(int s = 0; s <= maxs; ++s) ans = std::min(ans, dj.d[i+N*s]);
    std::cout << ans << "\n";
  }
  return 0;
}

