vector<tuple<int64_t, int64_t, size_t>> next_;

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  int N;
  cin >> N;
  nums.reserve(N + 1);
  nums.emplace_back();
  for (int i = 1; i <= N; ++i) {
    nums.emplace_back();
    cin >> nums.back();
  }

  const auto left_end = nums.cbegin();
  int64_t result = 0;
  int64_t val = 0;
  for (auto it = left_end + 1; it != nums.cend(); ++it) {
    next_.clear();
    while (!s.empty() && get<1>(s.top()) < *it) {
      auto top = s.top();
      s.pop();
      val -= get<1>(top) * get<2>(top);
      if (get<0>(top) < *it) {
        top = {*it, get<0>(top), get<2>(top)};
      } else {
        top = {get<0>(top), *it, get<2>(top)};
      }
      val += get<1>(top) * get<2>(top);
      if (!next_.empty() && get<0>(next_.back()) == get<0>(top) &&
          get<1>(next_.back()) == get<1>(top)) {
        get<2>(next_.back()) += get<2>(top);
      } else {
        next_.emplace_back(top);
      }
    }
    result += val;
    for (auto it = next_.crbegin(); it != next_.crend(); ++it) {
      s.emplace(move(*it));
    }
    s.emplace(*it, 0, 1);
  }
  cout << result << endl;
}

