bool isPrime(ll num) {

	bool flag = true;
	for (int i = 2; i <= sqrt(num); i++) {
		if (num%i == 0) {
			flag = false;
			break;
		}
	}

	return flag;
}


void solve() {

	ll N;
	cin >> N;
	vector<ll> P(N);
	vector<ll> pos(N+1,0);

	rep(i, N) {
		cin >> P[i];
		pos[P[i]] = i;
	}

	vector<ll> R(N);
	vector<ll> L(N);
	R[N - 1] = P[N - 1];
	L[0] = P[0];

	for (ll i = 1; i < N; i++) {
		L[i] = max(L[i - 1], P[i]);
		R[N - i - 1] = max(R[N - i], P[N - i - 1]);
	}

	ll ans = 0;

	for (ll i = N; i > 0; i--) {
		ll now = pos[i];

		ll tmp = 0;

		ll right_big = 0;
		ll left_big = 0;

		for (ll j = now + 1; j < N; j++) {
			if (P[j] > i) break;
			right_big = max(right_big, P[j]);
			tmp += right_big;
		}
		for (ll k = now - 1; k >= 0; k--) {
			if (P[k] > i) break;
			left_big = max(left_big, P[k]);
			tmp += left_big;
		}

		right_big = 0;
		left_big = 0;

		if (now == 0 || now == N - 1) {
			ans += tmp;
			continue;
		}

		//右へ
		for (ll j = now + 1; j < N; j++) {
			if (P[j] > i) break;
			right_big = max(right_big, P[j]);

			left_big = 0;
			//左へ
			for (ll k = now - 1; k >= 0; k--) {
				if (P[k] > i) break;
				left_big = max(left_big, P[k]);

				tmp += max(right_big, left_big);

			}

		}
		ans += tmp;

	}

	cout << ans;

}


