        set<int>::iterator k = s.lower_bound(i);
        if (k != s.begin()){
            k = prev(k);
            l[i] = *k;
        }
        else l[i] = 0;
        if (k != s.begin()){
            k = prev(k);
            ll[i] = *k;
        }
        else ll[i] = 0;
        s.insert(i);
    }
    s.clear(); s.insert(n+1);
    for (int j = n; j >= 1; j--){
        int i = p[j];
        set<int>::iterator k = s.lower_bound(i);
        if (k != s.end()){
            r[i] = *k;
        }
        else r[i] = n+1;
        k = next(k);
        if (k != s.end()){
            rr[i] = *k;
        }
        else rr[i] = n+1;
        s.insert(i);
