int solve(vector<pair<int,int>>& P){
	int N = P.size(), res = 0;
	multiset<int> s;

	s.insert(-1);
	s.insert(-1);
	s.insert(N);
	s.insert(N);

	sort(P.begin(), P.end(), greater<pair<int,int>>());

	for(int i = 0; i < N; i++){
		decltype(s)::iterator it =  s.lower_bound(P[i].second);
		int a, b, c, d;
