        auto it = used.lower_bound(ps[a]);
        if (it == used.end()) return {n, n};
        vector<int> ret;
        ret.push_back(*it);
        it++;
        if (it == used.end()) {
            ret.push_back(n);
            return ret;
        }
        ret.push_back(*it);
        return ret;
    };
    auto get_lt = [&](int a) -> vector<int> {
