const int K = 18;
const int N = (1 << K) + 100;
ll fl[N], fr[N], gl[N], gr[N], a[N], n;
ll h[N][K], rd[N]; /* rd[x] = k => x rounded down to nearest power of 2 = 2^k */

ll mx (int i, int j) {
	int k = rd[j - i + 1];
	return max(h[i][k], h[j - (1 << k) + 1][k]);
}

/* return first index at which value is > val in [ix...n] */
ll calcFR (int ix, ll val) {
	int l = ix, r = n + 1, mid;
	while (l < r) {
		mid = (l + r) >> 1;
		if (mx(ix, mid) > val) r = mid;
		else l = mid + 1;
	}
	return r;
}

/* returns first index (going from right to left) at which value is > val in [1...ix] */
ll calcFL (int ix, ll val) {
	int l = 0, r = ix, mid;
	while (l < r) {
		mid = (l + r) - ((l + r) >> 1);
		if (mx(mid, ix) > val) l = mid;
		else r = mid - 1;
	}
	return l;
}

void prep() {
	rd[1] = 0; /* 2 ^ 0 */
	for (int k = 1; k < K; k++)
		for (int i = (1 << k); i <= (1 << (k + 1)) - 1; i++)
			rd[i] = k;

	for (int i = 1; i <= n; i++) h[i][0] = a[i];
	for (int k = 1; (1 << k) <= n; k++)
		for (int i = 1; i <= n - (1 << k) + 1; i++)
			h[i][k] = max(h[i][k - 1], h[i + (1 << (k - 1))][k - 1]);

	fl[0] = fr[n + 1] = 0;

	for (int i = n; i >= 1; i--) {
		fr[i] = calcFR(i, a[i]);
		gr[i] = calcFR(fr[i] + 1, a[i]);

		fr[i] = fr[i] - i;
		gr[i] = gr[i] - i - fr[i];
	}

	for (int i = 1; i <= n; i++) {
		fl[i] = calcFL(i, a[i]);
		gl[i] = calcFL(fl[i] - 1, a[i]);

		fl[i] = i - fl[i];
		gl[i] = i - gl[i] - fl[i];
	}
}

ll solve() {
	ll ans = 0;
	for (int i = 1; i <= n; i++) ans += a[i] * (fr[i] * gl[i] + fl[i] * gr[i]);
	return ans;
}

int main () { 
#ifdef XVENOM
	// freopen("input.txt", "r", stdin);
	// freopen("output.txt", "w", stdout);
#endif

	scanf("%lld", &n);
	for (int i = 1; i <= n; i++) scanf("%lld", &a[i]);
	prep();
	printf("%lld\n", solve());
}

