#define rep(i, n) for(long i = 0; i < (n); i++)

using namespace std;

void solve() {
  long N;
  cin >> N;
  vector<long> P(N);
  rep (i, N) cin >> P[i];
  map<long, long> pos;
  rep (i, N) pos[P[i]] = i;
  set<long> largest;
  long ans = 0;
  for (long current = N; current >= 1; current--) {
    long p = pos[current];
    auto next_itr = largest.upper_bound(p);
    // right
    if (next_itr != largest.end()) {
      long before = 0;
      if (next_itr != largest.begin()) {
        auto before_itr = next_itr;
        before_itr--;
        before = (*before_itr) + 1;
      }
      auto next_next_itr = next_itr;
      next_next_itr++;
      long end = N-1;
      if (next_next_itr != largest.end()) {
        end = (*next_next_itr) - 1;
      }
      //cout << "right: ans += " << current << " * " << (p-before+1) << " * " << (end-(*next_itr)+1) << endl;
      //cout << "end: " << end << ", *next_itr: " << *next_itr << endl;
      ans += current * (p-before+1) * (end-(*next_itr)+1);
    }
    // left
    if (next_itr != largest.begin()) {
      auto before_itr = next_itr;
      before_itr--;
      long start = 0;
      if (before_itr != largest.begin()) {
        auto before_before_itr = before_itr;
        before_before_itr--;
        start = (*before_before_itr) + 1;
      }
      long end = N - 1;
      if (next_itr != largest.end()) end = (*next_itr) - 1;
      ans += current * ((*before_itr)-start+1) * (end-p+1);
      //cout << "left: ans += " << current << " * " << ((*before_itr)-start+1) << " * " << (end-p+1) << endl;;
    }
    largest.insert(pos[current]);
  }
  cout << ans << endl;
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout.precision(12);
  solve();
  return 0;
}

