template<class ValueMonoid, int HEIGHT = 20> // HEIGHT is log size
class SparseTable {
private:
    using value_structure = ValueMonoid;
    using value_type = typename value_structure::value_type;
    using size_type = std::uint32_t;

    size_type size_;
    std::array<std::vector<value_type>, HEIGHT> table;
public:
    SparseTable() : size_(0) {}
    SparseTable(const std::vector<value_type>& v) : size_(v.size()) {
        table[0] = v;
        for (size_type i = 1, w = 1; i < HEIGHT; i++, w *= 2) {
            table[i].resize(size_, value_structure::identity());
            for (size_type j = 0; j < size_; j++) {
                if (j + w < size_) table[i][j] = value_structure::operation(table[i-1][j], table[i-1][j+w]);
                else table[i][j] = table[i-1][j];
            }
        }
    }

    static inline size_type log2(size_type x) {
        if (x == 0) return 0;
        return size_type(31) ^ __builtin_clz(x);
    }

    value_type query(size_type l, size_type r) {
        if (r <= l) return value_structure::identity();
        size_type k = log2(r - l);
        return value_structure::operation(table[k][l], table[k][r-(size_type(1) << k)]);
    }
};

class v_monoid {
public:
    using value_type = int64;
    static value_type identity() { return 0; }
    static value_type operation (const value_type& a, const value_type& b) {
        return max(a, b);
    }
};

int main(void) {
    int64 N;
    cin >> N;
    vector<int64> P(N);
    REP(i, N) cin >> P[i];
    SparseTable<v_monoid> st(P);

    int64 res = 0;
    REP(i, N) {
        int64 l = -1, r = i, m;
        auto lbin = [&](int64 l, int64 r) {
            int64 fr = r;
            while (r - l > 1) {
                m = (l + r + 1) >> 1;
                if (st.query(m, fr) < P[i]) {
                    r = m;
                } else {
                    l = m;
                }
            }
            return r;
        };
        auto rbin = [&](int64 l, int64 r) {
            int64 fl = l;
            while (r - l > 1) {
                m = (l + r) >> 1;
                if (st.query(fl + 1, m) < P[i]) {
                    l = m;
                } else {
                    r = m;
                }
            }
            return l;
        };
        int64 ll = lbin(-1, i), rr = rbin(i, N+1);
        int64 ll2 = lbin(-1, ll-1), rr2 = rbin(rr, N+1);
        chmax(ll, (int64)0);
        chmax(ll2, (int64)0);
        if (ll != ll2) {
            res += (ll - ll2) * (rr - i) * P[i];
        }
        if (rr != rr2) {
            res += (i - ll + 1) * (rr2 - rr) * P[i];
        }
    }
    cout << res << endl;
}

