vector<LL> arg_sort(vector<LL> A, bool ascend = true) {

  // 配列のインデックス indiecs = {0, 1, 2, 3, 4} を作成する。
  vector<LL> index(A.size());
  iota(index.begin(), index.end(), 0);

  // ソートする。
  if (ascend) {
    std::sort(index.begin(), index.end(), [&A](LL i1, LL i2) {
      return A[i1] < A[i2];
      });
  }
  else {
    std::sort(index.begin(), index.end(), [&A](LL i1, LL i2) {
      return A[i1] > A[i2];
      });
  }

  return index;
}

