class sparse_table {
  private:
    size_t len;
    vector<vector<Z>> data;
  public:
    sparse_table(vector<Z> const& v): len(v.size()), data(len) {
      for (auto i = 0; i < len; i++)
        data[i].push_back(v[i]);
      for (auto j = 1; (1 << j) <= len; j++) {
        for (auto i = 0; i < len; i++) {
          if (i + (1 << j) > len) break;
          data[i].push_back(max(data[i][j - 1], data[i + (1 << (j - 1))][j - 1]));
        }
      }
      dump(data);
    }
    Z maximum(int left, int right) {
      int width = right - left, w = 0;
      while ((1 << (w + 1)) <= width) w++;
      Z ans = -INF;
      int pos = left;
      for (int i = 0; (1 << i) <= width; i++) {
        int w = 1 << i;
        if (!(w & width)) continue;
        ans = max(ans, data[pos][i]);
        pos += w;
      }
      return ans;
    }
};


template <class T, class F>
T boundary(F is_ok, T ok, T ng) {
  while (abs(ok - ng) > 1) {
    T m = (ok + ng) / 2;
    (is_ok(m) ? ok : ng) = m;
  }
  return ok;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  Z N;
  cin >> N;
  vector<Z> ps(N);
  cin >> ps;
  sparse_table st(ps);
  Z ans = 0;
  for (auto i = 0; i < N; i++) {
    if (ix(ps, i) == N) continue;
    dump(i);
    Z left_small, left_large, right_small, right_large;
    if (st.maximum(0, i) < ix(ps, i)) {
      dump(st.maximum(0, i));
      left_small = i + 1;
      left_large = 0;
    }
    else {
      Z lr = boundary([&] (Z j) { return st.maximum(j, i) > ix(ps, i); }, 0, i);
      dump(lr);
      left_small = i - lr;
      if (st.maximum(0, lr) < ix(ps, i))
        left_large = lr + 1;
      else {
        Z ll = boundary<Z>([&] (Z j) { return st.maximum(j, lr) > ix(ps, i); }, 0, lr);
        dump(ll);
        left_large = lr - ll;
      }
    }
    if (st.maximum(i, N) <= ix(ps, i)) {
      right_small = N - i;
      right_large = 0;
    }
    else {
      Z rl = boundary<Z>([&] (Z j) { return st.maximum(i, j) > ix(ps, i); }, N, i) - 1;
      dump(rl);
      right_small = rl - i;
      if (st.maximum(rl + 1, N) <= ix(ps, i))
        right_large = N - rl;
      else {
        Z rr = boundary([&] (Z j) { return st.maximum(rl + 1, j) > ix(ps, i); }, N, rl + 1) - 1;
        dump(rr);
        right_large = rr - rl;
      }
    }
    ans += ix(ps, i) * (left_small * right_large + left_large * right_small);
    dump(left_small);
    dump(left_large);
    dump(right_small);
    dump(right_large);
  }
  cout << ans << endl;
}

