int main(){
  int N;
  std::cin >> N;
  std::vector<int> p_arr(N), pos_arr(N);
  for(int i = 0; i < N; i++){
    int p;
    std::cin >> p;
    p--;
    p_arr[i] = p;
    pos_arr[i] = i;
  }
  std::sort(pos_arr.begin(), pos_arr.end(), [&](int l, int r){return p_arr[l] > p_arr[r];});

  std::set<int> pos_set;
  long long ans = 0;
  for(auto&& pos: pos_arr){
    if(pos_set.size() == 0){
      pos_set.insert(pos);
      continue;
    }
    long long l,r,l2,r2;
    std::set<int>::iterator it = pos_set.upper_bound(pos);
    if(it == pos_set.end()){
      r = 0;
      r2 = N-pos;
    }else if(std::next(it) == pos_set.end()){
      r = N-*(it);
      r2 = *it-pos;
    }else{
      r = *(std::next(it)) - *(it);
      r2 = *it-pos;
    }
    if(it == pos_set.begin()){
      l = 0;
      l2 = pos+1;
    }else if(std::prev(it) == pos_set.begin()){
      l = *(std::prev(it))+1;
      l2 = pos-*(std::prev(it));
    }else{
      l = *(std::prev(it)) - *(std::prev(std::prev(it))); 
      l2 = pos-*(std::prev(it));
    }
    pos_set.insert(pos);
    ans += (p_arr[pos]+1)*(l*r2+r*l2);
  }
  std::cout << ans << std::endl;
}

