class Segtree {
public:
    int n;
    vector<int> nodes;
    Segtree(int _n) {
        n = 1 << (int)ceil(log2(_n));
        nodes.resize(n*2-1, -INT_MAX);
    }
    void set(int i, int v) {
        i += n - 1;
        nodes[i] = v;
        while (i > 0) {
            i = (i-1) / 2;
            nodes[i] = max(nodes[i*2+1], nodes[i*2+2]);
        }
    }
    int get_max(int l, int r) {
        return get_max(l, r, 0, 0, n);
    }
    int get_max(int l, int r, int i, int tl, int tr) {
        if (tr <= l || r <= tl) return -INT_MAX;
        if (l <= tl && tr <= r) return nodes[i];
        int t1 = get_max(l, r, i*2+1, tl, (tl+tr)/2);
        int t2 = get_max(l, r, i*2+2, (tl+tr)/2, tr);
        return max(t1, t2);
    }
};

