    vector<int> P(N);
    for (int i=0; i<N; ++i) {
        cin >> P[i];
    }

    Segtree tr1(N+1);
    for (int i=0; i<N; ++i) {
        int j = tr1.get_max(P[i]+1, N+1);
        if (j == -INT_MAX) {
            ps[i][0] = ps[i][1] = -1;
        } else {
            ps[i][1] = j;
            tr1.set(P[j], -INT_MAX);
            int k = tr1.get_max(P[i]+1, N+1);
            ps[i][0] = (k == -INT_MAX ? -1 : k);
            tr1.set(P[j], j);
        }
        tr1.set(P[i], i);
    }

    Segtree tr2(N+1);
    for (int i=N-1; i>=0; --i) {
        int j = tr2.get_max(P[i]+1, N+1);
        if (j == -INT_MAX) {
            ps[i][2] = ps[i][3] = N;
        } else {
            ps[i][2] = -j;
            tr2.set(P[-j], -INT_MAX);
            int k = tr2.get_max(P[i]+1, N+1);
            ps[i][3] = (k == -INT_MAX ? N : -k);
            tr2.set(P[-j], j);
        }
        tr2.set(P[i], -i);
    }

    long long res = 0;
    for (int i=0; i<N; ++i) {
        if (ps[i][1] == -1 && ps[i][2] == N) continue;
        if (ps[i][1] != -1) {
