    vector<pii> pp(N);
    for ( int i = 0; i < N; i++ ) {
        cin >> P[i];
        pp[i] = pii(P[i], i);
    }
    sort(pp.begin(), pp.end());
    vector<int> l1(N, -1), l2(N, -1), r1(N, N), r2(N, N);
    set<int> s;
    for ( int j = N-1; j >= 0; j-- ) {
        ll p = pp[j].first;
        int i = pp[j].second;
        auto u0 = s.upper_bound(i);
        auto u = u0;
        if ( u != s.end() ) {
            r1[i] = *u;
            u++;
            if ( u != s.end() ) {
                r2[i] = *u;
            }
        }
        u = u0;
        if ( u != s.begin() && !s.empty() ) {
            u--;
            l1[i] = *u;
            if ( u != s.begin() ) {
                u--;
                l2[i] = *u;
            }
        }
        s.insert(i);
   }
    ll ans = 0;
