int qry(int pos,int l,int r,int I,int J,int val)
{
    if(l>J || r<I)return -1;
    int id=tre[pos];
    if(a[id]<=val)return -1;
    if(l==r)
    {
        if(a[l]>val)return l;
        else return -1;
    }
    int mid=(l+r)>>1;
    int x=qry(2*pos,l,mid,I,J,val);
    int y=qry(2*pos+1,mid+1,r,I,J,val);
    if(x==-1 && y==-1)return -1;
    if(x!=-1 && a[x]>val)return x;
    if(y!=-1 && a[y]>val)return y;
    return -1;
}
