template <class RMQ_>
int second_largest(RMQ_ &rmq, int l, int r){
  int pos = rmq.query(l,r+1).first.second;
  int c1=1; int c2=1;
  if(l<pos){
    pii ret2 = rmq.query(l,pos).first;
    c1 = ret2.first;
