    range(i, 0, N) {
        lint P = P_list.at(i);
        while (!stack.empty() and P_list.at(stack.back()) < P) stack.pop_back();
        prev_larger.at(i) = (stack.empty() ? -1 : stack.back());
        stack.emplace_back(i);
    }
    stack.clear();
    reversed_range(i, 0, N) {
        lint P = P_list.at(i);
        while (!stack.empty() and P_list.at(stack.back()) < P) stack.pop_back();
        next_larger.at(i) = (stack.empty() ? N : stack.back());
        stack.emplace_back(i);
