        range(k, i, j + 1) count += (P_list.at(k) > P ? 1 : 0);
        return count >= 2;
    };
    range(i, 2, N) {
        lint P = P_list.at(i);
        lint ok = -1, ng = i - 1;
        while (ng - ok > 1) {
            lint mid = (ok + ng) / 2;
            if (contains_larger_two_items(P, mid, i - 1)) ok = mid;
            else ng = mid;
        }
        pprev_larger.at(i) = ok;
    }
    range(i, 0, N - 2) {
        lint P = P_list.at(i);
        lint ng = i + 1, ok = N;
        while (ok - ng > 1) {
            lint mid = (ok + ng) / 2;
            if (contains_larger_two_items(P, i + 1, mid)) ok = mid;
            else ng = mid;
        }
        nnext_larger.at(i) = ok;
