        res += P * (prev_larger.at(i) - pprev_larger.at(i)) * (next_larger.at(i) - i - 1);
        res += P * (nnext_larger.at(i) - next_larger.at(i)) * (i - prev_larger.at(i) - 1);
        // cout << res << "\n";
    }
    cout << res << "\n";
}

