using namespace std;

const LL MAXN = 1000047;
const LL INF = 1000000000;

struct Vertex{
	LL l,r;
	PLL v;
	Vertex *lc,*rc;

	Vertex(LL _l, LL _r){
		l = _l;
		r = _r;
		v = {INF,l};
		if (r-l > 1){
			LL mid = (l+r)/2;
			lc = new Vertex(l,mid);
			rc = new Vertex(mid,r);
		}
		else{
			lc = nullptr;
			rc = nullptr;
		}
	}

	void update(LL _l, LL _v){
		if (r-l == 1){
			v = {_v,l};
			return;
		}
		if (_l >= rc->l){
			rc->update(_l,_v);
		}
		else{
			lc->update(_l,_v);
		}
		v = min(lc->v,rc->v);
	}

	PLL query(LL _l, LL _r){
		if (_l >= r || _r <= l){
			return {INF,INF};
		}
		if (_l <= l && _r >= r){
			return v;
		}
		return min(lc->query(_l,_r),rc->query(_l,_r));
	}

	PLL query2nd(LL _l, LL _r){
		PLL p = query(_l,_r);
		update(p.second,INF);
		PLL res = query(_l,_r);
		update(p.second,p.first);
		return res;
	}
};

