        while(a[stk.top()]<a[i]) stk.pop();
        L[i] = stk.top();
        stk.push(i);
    }

    a[N+1] = INT_MAX;
    while(stk.size()>0) stk.pop();
    stk.push(N+1);
    fr(i,N,1)
    {
        while(a[stk.top()]<a[i]) stk.pop();
        R[i] = stk.top();
        stk.push(i);
    }
    ll tot = 0;
    f1(i,N)
    {
        //cout << L[i] << " " << R[i] << "\n";
        if(a[i]==N) continue;
        if(L[i]>=1){
            int lft = L[i]-1;
            if(L[i]>1) lft = lastAtLeast(1,L[i]-1,a[i]+1);
            if(lft==-1) lft = 0;
            //cout << a[i] << ": L " << lft << " -> " << L[i] << "\n";
            tot+=(L[i]-lft)*1LL*(R[i]-i)*1LL*a[i];
        }
        if(R[i]<=N){
            int rgt = R[i]+1;
            if(R[i]<N) rgt = firstAtLeast(R[i]+1,N,a[i]+1);
            if(rgt==-1) rgt = N+1;
           // cout << a[i] << ": R " << R[i] << " -> " << rgt << "\n";
            tot+=(rgt-R[i])*1LL*(i-L[i])*1LL*a[i];
        }
    }
    cout << tot;
    return 0;
}

