using namespace std;

ll tree[5000000],ar[100001];
int n;

void build(int node,int l,int r)
{
    if(l==r)
    {
        tree[node]=ar[l];   //Change for min/sum
        return;
    }
    build(node*2,l,(l+r)/2);
    build(node*2+1,(l+r)/2+1,r);
    tree[node]=max(tree[node*2],tree[node*2+1]);    //Change for min/sum
}

ll query(int node,int l,int r,int i,int j,int x)
{
    //cout<<l<<"...."<<r<<" "<<i<<" "<<j<<" "<<x<<" "<<tree[node]<<endl;
    if(j<l || r<i)
        return n+1;   //Change for min/sum
    if(tree[node]<x)
        return n+1;
    if(l==r)
        return l;
    //cout<<l<<"...."<<r<<" "<<i<<" "<<j<<" "<<x<<" "<<tree[node]<<endl;
    int z=query(node*2,l,(l+r)/2,i,j,x);
    if(z!=n+1)
        return z;
    return query(node*2+1,(l+r)/2+1,r,i,j,x); 
}

ll query2(int node,int l,int r,int i,int j,int x)
{
    if(j<l || r<i)
        return 0;   //Change for min/sum
    if(tree[node]<x)
        return 0;
    if(l==r)
        return l;
    int z=query2(node*2+1,(l+r)/2+1,r,i,j,x);
    if(z!=0)
        return z;
    return query2(node*2,l,(l+r)/2,i,j,x);
}


