#define IFOR(i, begin, end) for(int i=(end)-1,i##_begin_=(begin);i>=i##_begin_;i--)
#define REP(i, n) FOR(i,0,n)


int main()
{
    int N;
    cin >> N;
    vector<int> P(N), Pinv(N + 1);
    REP(i, N) cin >> P[i], Pinv[P[i]] = i;

    multiset<int> m{-1, -1, N, N};
    lint ret = 0;
    IFOR(i, 1, N + 1)
    {
        lint now = Pinv[i];
        lint r = *m.lower_bound(now);
        lint rr = *next(m.lower_bound(now));
        lint l = *prev(m.lower_bound(now));
        lint ll = *prev(m.lower_bound(now), 2);
        ret += ((rr - r) * (now - l) + (l - ll) * (r - now)) * i;
        m.insert(now);
    }
    cout << ret << endl;
}

