using namespace std ;

const int MAX = 1e5 + 10 ;

vector<int>tree[4 * MAX] ;
int arr[MAX] ;

void build(int node , int l , int r)
{
	if(l == r)
	{
		tree[node].push_back(arr[l]) ;
		return ;
	}
	int mid = (l + r) >> 1 ;
	build(node << 1 , l , mid) ;
	build(node << 1 | 1 , mid + 1 , r) ;
	merge(tree[node << 1].begin(), tree[node << 1].end(), tree[node << 1 | 1].begin(), tree[node << 1 | 1].end(), inserter(tree[node], tree[node].begin()));
}

int query(int node , int l , int r , int from , int to , int x)
{
	if(from > r || to < l)
		return 0 ;
	if(l >= from && r <= to)
	{
		int idx = upper_bound(tree[node].begin() , tree[node].end() , x) - tree[node].begin() ;
		return (tree[node].size() - idx) ;
	}
	int mid = (l + r) >> 1 ;
	int a = query(node << 1 , l , mid , from  , to , x) ;
	int b = query(node << 1 | 1 , mid + 1 , r , from , to , x) ;
	return (a + b) ;
}

int readInt () {
	bool minus = false;
	int result = 0;
	char ch;
	ch = getchar();
	while (true) {
		if (ch == '-') break;
		if (ch >= '0' && ch <= '9') break;
		ch = getchar();
	}
	if (ch == '-') minus = true; else result = ch-'0';
	while (true) {
		ch = getchar();
		if (ch < '0' || ch > '9') break;
		result = result*10 + (ch - '0');
	}
	if (minus)
		return -result;
	else
		return result;
}

int main()
{
	int n ;
	n = readInt() ;
	for(int i = 1 ; i <= n ; ++i)
		arr[i] = readint() ;
	build(1 , 1 , n) ;
	long long ans = 0ll ;
	for(int i = 1 ; i <= n ; ++i)
	{
		int l = i , r = n ;
		int a = i , c = i;
		while(l <= r)
		{
			int mid = (l + r) >> 1 ;
			int x = query(1 , 1 , n , i , mid , arr[i]) ;
			if(x <= 1)
			{
				l = mid+1 ;
				if(x == 1)
					a = mid ;
			}
			else
				r = mid - 1;
		}
		l = i , r = n ;
		while(l <= r)
		{
			int mid = (l + r) >> 1 ;
			int x = query(1 , 1 , n , i , mid , arr[i]) ;
			if(x == 0)
			{
				l = mid+1 ;
				c = mid ;
			}
			else
				r = mid - 1;
		}
		l = 1 , r = i ;
		int b = i , d = i;
		while(l <= r)
		{
			int mid = (l + r) >> 1 ;
			int x = query(1 , 1 , n , mid , i , arr[i]) ;
			if(x <= 1)
			{
				r = mid-1 ;
				if(x == 1)
					b = mid ;
			}
			else
				l = mid + 1;
		}
		l = 1 , r = i ;
		while(l <= r)
		{
			int mid = (l + r) >> 1 ;
			int x = query(1 , 1 , n , mid , i , arr[i]) ;
			if(x == 0)
			{
				r = mid-1 ;
				d = mid ;
			}
			else
				l = mid + 1;
		}
		long long x1 = (i - d + 1ll) * 1ll ;
		long long x2 = (a - c) * 1ll ;
		x1 = max(x1 , 0ll) ;
		x2 = max(x2 , 0ll) ;
		ans += (x1 * x2) * arr[i] * 1ll ;
		x1 = (d - b) * 1ll ;
		x2 = (c - i + 1ll) * 1ll ;
		x1 = max(x1 , 0ll) ;
		x2 = max(x2 , 0ll) ;
		ans += (x1 * x2) * arr[i] * 1ll ;
	}
	return printf("%lld\n" , ans) , 0 ;
}

