  cin>>A;
  for(Int i=0;i<N;i++) A[i]--;

  Int a = solve(N, A);
  reverse(A.begin(), A.end());
  Int b = solve(N, A);
  Int ans = a + b;
  cout<<ans<<endl;
  return 0;
}

