    for (int i = n; i > 0; i--){
        int x = order[i];
        long long c = 0;
        vector<int> l(2);
        vector<int> r(2);
        s.insert(x);
        {
            auto itr = s.find(x);
            --itr; l[0] = *itr;
            --itr; l[1] = *itr;
        }
        {
            auto itr = s.find(x);
            ++itr; r[0] = *itr;
            ++itr; r[1] = *itr;
