template<typename Monoid>
class SegTree {

//半開区間!!!!!!!!!!!!!!!
public:
    int p = 2;
    vector<Monoid> node;
    using Func = function<Monoid(Monoid,Monoid)>;
    Func pick; Monoid init;//操作と単位元

    SegTree(vector<Monoid> A, string type, Monoid m) {
        if (type == "min") {
            pick = [](int a, int b){return min(a,b);};
        } else if (type == "max") {
            pick = [](int a, int b){return max(a,b);};
        } else if (type == "sum") {
            pick = [](int a, int b){return a + b;};
        }

        init = m;
        while (A.size() > p) p *= 2;
        node = vector<Monoid>(2*p-1,init);

        for (int i = 0;i < A.size();i++) {
            node[p-1+i] = A[i];
        }

        for (int i = p - 2;i >= 0;i--) {
            node[i] = pick(node[i*2+1],node[i*2+2]);
        }
    }

    SegTree(vector<Monoid> A, Func f, Monoid m) {
        pick = f; init = m;
        while (A.size() > p) p *= 2;
        node = vector<Monoid>(2*p-1,init);

        for (int i = 0;i < A.size();i++) {
            node[p-1+i] = A[i];
        }

        for (int i = p - 2;i >= 0;i--) {
            node[i] = pick(node[i*2+1],node[i*2+2]);
        }
    }

    //1点更新
    void update(int i, Monoid v) {
        for (node[(i+=p)-1] = v; i >>= 1;) {
            node[i-1] = pick(node[i*2-1], node[i*2]);
        }
    }

    //1点加算
    void add(int i, Monoid v) {
        update(i, this[i] + v);
    }

    int getval(int start,int end,int k = 0,int l = 0,int r = -1) {
        if (r < 0) r = p;
        if (r <= start || end <= l) {return init;}
        if (start <= l && r <= end) {return node[k];}
        int L,R;
        L = getval(start,end,k*2+1,l,(l+r)/2);
        R = getval(start,end,k*2+2,(l+r)/2,r);
        return {pick(L,R)};
    }

    inline Monoid operator [] (int i) {
        return node[i+p-1];
    }

	int bsr(int pos, int num, int n) {
		int l, r; l = pos, r = n;
		if (getval(pos, r) < num) return n;
		if (getval(pos, r) == num) return l;
		while (r - l > 1) {
			int mid = (r + l) / 2;
			if (getval(pos, mid) > num) r = mid;
			else l = mid;
		}
		return l;
	}

	int bsl(int pos, int num) {
		int l, r; l = 0, r = pos+1;
		if (getval(0, r) == num) return r-1;
		while (r - l > 1) {
			int mid = (r + l) / 2;
			if (getval(mid, pos+1) > num) l = mid;
			else r = mid;
		}
		return l;
	}
};

bool solve() {
	int n; cin >> n;
	vi p(n+1); rep (i, n) cin >> p[i]; p[n] = -1;
	SegTree<int> seg(p,"max",0);
	int ans = 0;
	rep (i, n) {
		int p1 = seg.bsr(i, p[i], n);
		int p2 = seg.bsr(p1+1, p[i], n);
		if (p2 == p1) p2 = n;
		int l1 = seg.bsl(i, p[i]);
		int l2 = seg.bsl(l1-1, p[i]);
		if (l1 == l2) l2 = -1;

		if (l1 == i && p1 == i) continue;
		if (l1 == i) {
			ans += p[i] * (i+1) * (p2 - p1);
		} else if (p1 == i) {
			ans += p[i] * (n-i) * (l1 - l2);
		} else {
			ans += p[i] * (i - l1) * (p2 - p1);
			ans += p[i] * (p1 - i) * (l1 - l2);
		}

	}
	cout << ans << endl;
}

signed main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	solve();
}

