void solve(void)
{
  int N; cin >> N;

  std::multiset<int> S{};
  S.emplace(0);
  S.emplace(0);
  S.emplace(N + 1);
  S.emplace(N + 1);
  using Pair = pair<int, ui>;
  vector<Pair> P(N);
  for(int i = 0; i < N; ++i)
  {
    int p; cin >> p;
    P[i] = {p, (ui)i + 1};

  }
  boost::sort(P, [](Pair p1, Pair p2){
    return p1.first > p2.first;
  });

  ull ans{};
  for(const auto& p : P)
  {
    auto index = (int) p.second;
    auto it = boost::lower_bound(S, index);
    auto x = std::prev(it);
    auto w = std::prev(x);
    auto y = it;
    auto z = std::next(y);
    auto r = (*x - *w) * (*y - index) + (index - *x) * (*z - *y);
    ans += (ull)(r * p.first);
    S.emplace(index);
  }

  cout << ans << CRLF;
  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

