vector<ll> argsort(const vector<ll> &vec) {
  vector<pair<ll, ll>> values;
  rep (i, vec.size()) {
    values.emplace_back(vec[i], i);
  }
  sort(all(values), greater<pair<ll, ll>>());
  vector<ll> ret;
  each (item, values) {
    ret.push_back(item.second);
  }

  return ret;
}

