        n2 = *next(it, 2);
      } else {
        n2 = N;
      }
    } else {
      n1 = N;
      n2 = N;
    }

    ans += (n1 - i) * (p1 - p2) * P[i];
    ans += (i - p1) * (n2 - n1) * P[i];
  }
  cout << ans << "\n";
}

