int fun(int i, int j)
{

    if (dp[i][j] != 0)
    {
        return dp[i][j];
    }

    if (i == (j - 1))
    {
        dp[i][j] = min(p[i], p[i + 1]);
        return dp[i][j];
    }

    return max(fun(i, j - 1), fun(i + 1, j));
}

