#include <bits/stdc++.h>
using namespace std;
using lint = long long;
template<class T = int> using V = vector<T>;
template<class T = int> using VV = V< V<T> >;

struct SegmentTree {
  using T = int;
  static T op(const T& a, const T& b) { return max(a, b); }
  static constexpr T e() { return -1; }

  const int n;
  V<T> t;
  SegmentTree(int n) : n(n), t(2 * n, e()) {}
  T& operator[](int i) { return t[i + n]; }
  void build() { for (int i = n - 1; i; --i) t[i] = op(t[2 * i], t[2 * i + 1]); }
  T acc(int l, int r) const {
    T resl = e(), resr = e();
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l & 1) resl = op(resl, t[l++]);
      if (r & 1) resr = op(t[--r], resr);
    }
    return op(resl, resr);
  }
  void set(int i, const T& a) {
    t[i += n] = a;
    while (i >>= 1) t[i] = op(t[2 * i], t[2 * i + 1]);
  }
};

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);
  int n; cin >> n;
  SegmentTree st(n + 2);
  st[0] = st[n + 1] = n + 1;
  for (int i = 1; i <= n; ++i) {
    cin >> st[i];
  }
  st.build();

  auto fl = [&](int i, int x) -> int {
    int ng = -1, ok = i - 1;
    while (ok - ng > 1) {
      int mid = ng + ok >> 1;
      (st.acc(mid + 1, i) <= x ? ok : ng) = mid;
    }
    return ok;
  };
  auto fr = [&](int i, int x) -> int {
    int ok = i + 1, ng = n + 2;
    while (ng - ok > 1) {
      int mid = ok + ng >> 1;
      (st.acc(i + 1, mid) <= x ? ok : ng) = mid;
    }
    return ok;
  };

  lint res = 0;
  for (int i = 1; i <= n; ++i) {
    lint l = fl(i, st[i]);
    lint r = fr(i, st[i]);
    if (l) {
      lint ll = fl(l, st[i]);
      res += (l - ll) * (r - i) * st[i];
    }
    if (r <= n) {
      lint rr = fr(r, st[i]);
      res += (i - l) * (rr - r) * st[i];
    }
  }
  cout << res << '\n';
}

