        p[x] = i;
    }

    long ans = 0;
    set<int> ind;
    for (map<int, int>::reverse_iterator i = p.rbegin(), e = p.rend(); i != e; i++) {
        if (ind.empty()) {
            ind.emplace(i->second);
            continue;
        }
        set<int>::iterator it = ind.lower_bound(i->second);
        int w, x, y, z;
        y = (it == ind.end()) ? n + 1 : *it;
        z = (it == --ind.end() || y == n + 1) ? n + 1 : *next(it);
        x = (it == ind.begin()) ? 0 : *prev(it);
        w = (it == ++ind.begin() || x == 0) ? 0 : *prev(it, 2);
        ans += static_cast<long>(i->first) * (y - i->second) * (x - w);
        ans += static_cast<long>(i->first) * (z - y) * (i->second - x);
        ind.emplace(i->second);
    }

    printf("%ld\n", ans);
    return 0;
}

