	for (int i = n; i >= 1; i--) {
		auto itr = st.lower_bound(now[i]);
		int r = *itr;
		itr++; int r2 = *itr;
		itr--; itr--;
		int l = *itr;
		itr--; int l2 = *itr;
		ans += i * (r - now[i])*(l - l2);
		ans += i * (r2 - r)*(now[i] - l);
		st.insert(now[i]);
	}
