void solve(void)
{
  std::multiset<int> S;
  int N;
  cin>>N;
  vector<int> v(N,0),pos(N+1,0);

  for (int i = 0; i < N; i++)
  {
    cin>>v[i];
    pos[v[i]] = i +1;
  }

  long long ans = 0;

  S.insert(0);
  S.insert(0);
  S.insert(N+1);
  S.insert(N+1);

  for (ll i = N; i >= 1; i--)
  {
    auto it = S.lower_bound(pos[i]);

    ll pos_r = *it;

    it++;

    ll pos_rr = *it;

    it--;
    it--;

    ll pos_l = *it;
    it--;
    ll pos_ll = *it;

    ans += i*(pos_r - pos[i])*(pos_l - pos_ll);
    ans += i*(pos_rr - pos_r)*(pos[i] - pos_l);

