	}
	long long int ans = 0;
	set<long long int> indices = { arr[n] };
	for (long long int i = n - 1; i > 0; i--) {
		auto low = indices.lower_bound(arr[i]);
		long long int left1 = -1, left2 = -1;
		if (low != indices.begin()) {
			low--;
			left1 = *low;
			if (low != indices.begin()) {
				low--;
				left2 = *low;
			}
		}
		long long int right1 = n, right2 = n;
		auto high = indices.upper_bound(arr[i]);
		if (high != indices.end()) {
			right1 = *high;
			high++;
			if (high != indices.end()) {
				right2 = *high;
			}
		}
		//cout << left1 << left2 << right1 << right2 << endl;
		ans += i * (left1 - left2) * (right1 - arr[i]);
		ans += i * (arr[i] - left1) * (right2 - right1);
		indices.insert(arr[i]);
	}
	cout << ans << endl;
}

