lli bruteforce(vector<int>& P,int N)
{
  lli sm = 0LL;
  REP(l,N-1)
    {
      int mx1 = P[l];
      int mx2 = -1;

      FOR(r,l+1,N)
	{
	  if( mx1 < P[r] )
	    {
	      mx2 = mx1;
	      mx1 = P[r];
	    }
	  else if( mx2 < P[r] )
	    {
	      mx2 = P[r];
	    }

	  sm += mx2;
	}
    }

  return sm;

}








