    ps[p] = i;
  }

  long long int result = 0;

  multiset<int> s; // setは内部でソートされる。(されないのはunordered_set。さらにmultiだと、同じキーを複数持てる(番兵用に)
  // 番兵
  s.emplace(0);
  s.emplace(0);
  s.emplace(n+1);
  s.emplace(n+1);

  for (int p = n; p > 0; p--) { // 値が大きい順に処理して、setには自分自身以上の値しかない状態にする。
    const auto& set_result = s.emplace(ps[p]); // 挿入時、自分の位置を返してくれるので、再度findする必要はない
    int w = *prev(set_result, 2);
    int x = *prev(set_result, 1);
    int i = *set_result;
    int y = *next(set_result);
    int z = *next(next(set_result));

    // 自分自身が2番目になる組み合わせ
    // 自分の周辺5点とりだして、
    long long int c = (x-w) * (y-i) // 自分の1個前が1番目で、自分が2番目。つまり、wと自分のみlrの範囲に含む組み合わせ数
      + (z-y) * (i-x); // 自分の1個跡が1番目で、自分が2番目。つまり、yと自分のみlrの範囲に含む組み合わせ数
    result += p*c;
  }

