                ll left = itrLeft != processed.end() ? targetIndex - *itrLeft : targetIndex+1;
                ll right = itrRight2 != processed.end() ? *itrRight2 - *itrRight : N - *itrRight;
                answer += left * right * target;
            }
            if (itrLeft != processed.end()) {
                const auto itrLeft2 = itrLeft != processed.begin() && processed.size() != 0 ? prev(itrLeft) : processed.end();
                ll left = itrLeft2 != processed.end() ? *itrLeft - *itrLeft2 : (*itrLeft)+1;
                ll right = itrRight != processed.end() ? *itrRight - targetIndex : N - targetIndex;
                answer += left * right * target;
            }
            processed.insert(targetIndex);
        }
        out << answer << "\n";
    }
};


int main() {
    ESecondSum solver;
    std::istream& in(std::cin);
    std::ostream& out(std::cout);
    solver.solve(in, out);
    return 0;
}

