	ll ans = 0, cc = 0;
	bit.add(v[0].se, 1);
	FOR(i, 1, N) {
		pll cur = v[i];
		int p = cur.se;
		int l1 = bit.lower_bound(bit.sum(p));
		int l2 = bit.lower_bound(bit.sum(p) - 1);

		int r1 = bit.lower_bound(bit.sum(p) + 1);
		int r2 = bit.lower_bound(bit.sum(p) + 2);
		if (bit.sum(p) == 0) l1 = l2 = -1;
		if (l1 > -1 && bit.sum(l1) == 1) l2 = -1;
		if (r1 == -1) r1 = N;
		if (r2 == -1) r2 = N;


		ll pat = 0;
		pat += (l1 - l2) * (r1 - p);
		pat += (p - l1 - 1) * (r2 - r1);
		pat += r2 - r1;

		ans += cur.fi * pat;
		bit.add(p, 1);
		cc += pat;
	}
	cout << ans << endl;
	return 0;
