vector<ll> tree;

void build(ll node, ll start, ll end) {
    if(start == end) {
        tree[node] = p[start];
    }
    else {
        ll mid = (start + end)/2;
        build(2*node, start, mid);
        build(2*node+1, mid+1, end);
        tree[node] = max(tree[node*2], tree[node*2+1]);
    }
}

ll query(ll node, ll start, ll end, ll ustart, ll uend) {
    if(start >= ustart && end <= uend) {
        return tree[node];
    }
    if(start > uend || end < ustart)
        return -1;
    ll mid = (start+end)/2;
    return max(query(node * 2, start, mid, ustart, uend), query(node*2+1, mid+1, end, ustart, uend));
}

