#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int maxn = 100000 + 5, INF = 1 << 30;
ll arr[maxn];
int seg[4 * maxn];
void build(int index, int left, int right) {
	if (left == right) {
		seg[index] = arr[left];
		return;
	}
	int mid = (left + right) / 2;
	build(2 * index, left, mid);
	build(2 * index + 1, mid + 1, right);
	seg[index] = max(seg[2 * index], seg[2 * index + 1]);
}
int query_left(int index, int left, int right, int lo, int hi, int val) {
	if (left == right)
		return left;
	int mid = (left + right) / 2;
	if (hi <= mid)
		return query_left(2 * index, left, mid, lo, hi, val);
	else if (lo > mid)
		return query_left(2 * index + 1, mid + 1, right, lo, hi, val);
	else if (lo <= left && right <= hi) {
		if (seg[2 * index + 1] < val)
			return query_left(2 * index, left, mid, lo, hi, val);
		else
			return query_left(2 * index + 1, mid + 1, right, lo, hi, val);
	}
	int a = query_left(2 * index, left, mid, lo, hi, val), b = query_left(2 * index + 1, mid + 1, right, lo, hi, val);
	return arr[b] > val? b: a;
}
int query_right(int index, int left, int right, int lo, int hi, int val) {
	if (left == right)
		return left;
	int mid = (left + right) / 2;
	if (hi <= mid)
		return query_right(2 * index, left, mid, lo, hi, val);
	else if (lo > mid)
		return query_right(2 * index + 1, mid + 1, right, lo, hi, val);
	else if (lo <= left && right <= hi) {
		if (seg[2 * index] < val)
			return query_right(2 * index + 1, mid + 1, right, lo, hi, val);
		else
			return query_right(2 * index, left, mid, lo, hi, val);
	}
	int a = query_right(2 * index, left, mid, lo, hi, val), b = query_right(2 * index + 1, mid + 1, right, lo, hi, val);
	return arr[a] > val? a: b;
}
int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	int n;
	cin >> n;
	arr[0] = arr[n + 1] = INF;
	for (int i = 1; i <= n; ++i)
		cin >> arr[i];
	build(1, 0, n + 1);
	ll res = 0;
	for (ll i = 1; i <= n; ++i) {
		ll Left = query_left(1, 0, n + 1, 0, i - 1, arr[i]), Right = query_right(1, 0, n + 1, i + 1, n + 1, arr[i]);
		if (Left == 0 && Right == n + 1)
			continue;
		else if (Left == 0) {
			ll RRight = query_right(1, 0, n + 1, Right + 1, n + 1, arr[i]);
			res += arr[i] * (i * (RRight - Right));
		}
		else if (Right == n + 1) {
			ll LLeft = query_left(1, 0, n + 1, 0, Left - 1, arr[i]);
			res += arr[i] * ((Left - LLeft) * (n + 1 - i));
		}
		else {
			ll LLeft = query_left(1, 0, n + 1, 0, Left - 1, arr[i]);
			ll RRight = query_right(1, 0, n + 1, Right + 1, n + 1, arr[i]);
			res += arr[i] * (Left - LLeft) * (Right - i);
			res += arr[i] * (i - Left) * (RRight - Right);
		}
	}
	cout << res << '\n';
	return 0;
}

