    UnionFind uf(n + 2);
    auto left = [&](int i) -> int {
        if (i == 0) return 0;
        if (!deleted[i - 1]) return i - 1;
        return uf.left(i - 1) - 1;
    };
    auto right = [&](int i) -> int {
        if (i == n + 1) return n + 1;
        if (!deleted[i + 1]) return i + 1;
        return uf.right(i + 1);
    };
    int ans = 0;
