	std::vector<int64_t> init(N + 2);
	std::vector<int> l2(N + 2), l1(N + 2), r1(N + 2), r2(N + 2);
	{
		RMaxQ rmq(init);
		for (int i{1}; i <= N; i++)
		{
			l1[i] = rmq.get(P[i] + 1, N + 2);
			l2[i] = std::max(rmq.get(P[i] + 1, P[l1[i]]), rmq.get(P[l1[i]] + 1, N + 2));
