template <typename T> struct Segtree {
	Segtree(int n):base(1){
		while (base < n) base *= 2;
		nodes.resize(base*2, T::id());
	}
	void setLeaf(int i, T x) {
		nodes[base+i] = x;
		for (auto v=(base+i)/2; v>0; v/=2)
			nodes[v] = T::merge(nodes[v*2], nodes[v*2+1]);
	}
	T readRange(int left, int right) const { return implRR(left, right, 0, base, 1); }
	T implRR(int left, int right, int i, int e, int v) const {
		if (left >= e or right <= i) return T::id();
		if (left <= i and right >= e) return nodes[v];
		return T::merge(implRR(left, right, i, (i+e)/2, v*2), implRR(left, right, (i+e)/2, e, v*2+1));
	}
	template <typename F> int find(int left, int right, bool last, F f) const { return implF(left, right, last, f, 0, base, 1); }
	template <typename F> int implF(int left, int right, bool last, F f, int i, int e, int v) const { 
		if (left >= e or right <= i) return -1;
		if (left <= i and right >= e) return implF2(left, right, last, f, i, e, v);
		auto i1 = i;
		auto j1 = (i+e)/2;
		auto v1 = 2*v;
		auto i2 = (i+e)/2;
		auto j2 = e;
		auto v2 = 2*v+1;
		if (last)
			swap(i1, i2), swap(j1, j2), swap(v1, v2);
		auto r = implF(left, right, last, f, i1, j1, v1);
		return r == -1 ? implF(left, right, last, f, i2, j2, v2) : r;
	}
	template <typename F> int implF2(int left, int right, bool last, F f, int i, int e, int v) const { 
		if (not f(nodes[v])) return -1;
		if (e - i == 1) return i;
		auto i1 = i;
		auto j1 = (i+e)/2;
		auto v1 = 2*v;
		auto i2 = (i+e)/2;
		auto j2 = e;
		auto v2 = 2*v+1;
		if (last)
			swap(i1, i2), swap(j1, j2), swap(v1, v2);
		auto r = implF2(left, right, last, f, i1, j1, v1);
		return r == -1 ? implF2(left, right, last, f, i2, j2, v2) : r;
	}
	int base;
	vector<T> nodes;
};

template <typename T> T load() { T r; cin >> r; return r; }
template <typename T> vector<T> loadMany(int n) { vector<T> rs(n); generate(rs.begin(), rs.end(), &load<T>); return rs; }

template <typename T> struct Max {
	T x;
	static Max id() { return {numeric_limits<T>::min()}; }
	static Max merge(const Max& a, const Max& b) { return {max(a.x, b.x)}; }
};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	auto n = load<int>();
	auto perm = loadMany<int>(n);
	auto segtree = Segtree<Max<int>>(n);
	for (auto i=0; i<n; ++i)
		segtree.setLeaf(i, {perm[i]});
	auto score = 0ll;
	for (auto i=0; i<n; ++i) {
		auto val = perm[i];
		auto ileft = segtree.find(0, i, true, [&](auto v){ return v.x > val; });
		auto iright = segtree.find(i+1, n, false, [&](auto v){ return v.x > val; });
		if (iright == -1)
			iright = n;
		auto jleft = segtree.find(0, ileft, true, [&](auto v){ return v.x > val; });
		auto jright = segtree.find(iright+1, n, false, [&](auto v){ return v.x > val; });
		if (jright == -1)
			jright = n;
		auto l1 = i - ileft - 1;
		auto l2 = i - jleft - 1;
		auto r1 = iright - i - 1;
		auto r2 = jright - i - 1;
		score += max((long long)(l2 - l1) * (r1 + 1), 0ll) * val;
		score += max((long long)(r2 - r1) * (l1 + 1), 0ll) * val;
	}
	cout << score << '\n';
}

