int main()
{
	int n;
	cin >> n;
	vector<pair<int, int> > v;
	for(int i = 1; i <= n; i++){
		int p;
		cin >> p;
		v.push_back(make_pair(p, i));
	}
	sort(v.begin(), v.end());
	reverse(v.begin(), v.end());

	long long int ans = 0;

	set<int> s;

	s.insert(v[0].second);
	for(int i = 1; i < v.size(); i++){
		int nowv = v[i].first;
		int p = v[i].second;
		auto r1 = s.upper_bound(p);
		// nowvより大きい値が左側に1つ入っている またはnowvより大きい値が右側に1つ入っている
		// (L \in (*l1, *l2] かつ　R \in [p, *r1)) または ( L \in (*l2, p] かつ [*r1, *r2) ) となればよい
		long long int combnum = 0;

		// L \in (*l1, *l2] かつ　R \in [p, *r1)となる組み合わせの数
		// r1 == s.begin()のとき、l1およびl2は存在しない
		// つまりnowvの左側にnowvより大きい値は存在しない
		// この場合は何もしない
		if(r1 != s.begin()){
			int l_range, r_range;
			auto l2 = r1;
			l2--;
			if(l2 == s.begin()){
				// l1は存在しない
				// よってLの範囲は[1, *l2]
				l_range = *l2;
			} else {
				auto l1 = l2;
				l1--;
				l_range = *l2 - *l1;
			}
			if(r1 == s.end()){
				// r1は存在しない
				// つまりnowvの右側にnowvより大きな値は存在しない
				// よってRの範囲は[p, n]
				r_range = n - p + 1;
			} else {
				r_range = *r1 - p;
			}
			combnum += l_range * r_range;
		}

		// L \in (*l2, p] かつ [*r1, *r2) となる組み合わせの数
		//  r1 == s.end()のとき、r1、r2は存在しない
		// つまりnowvより大きい値はnowvより右側に存在しない
		// この場合は何もしない
		if(r1 != s.end()){
			int l_range, r_range;
			if(r1 == s.begin()){
				// l2は存在しない
				// よってLの範囲は[1, p]
				l_range = p;
			} else {
				auto l2 = r1;
				l2--;
				l_range = p - *l2;
			}
			auto r2 = r1;
			r2++;
			if(r2 == s.end()){
				// r2は存在しない
				// よってRの範囲は[*r1, n]
				r_range = n - *r1 + 1;
			} else {
				r_range = *r2 - *r1;
			}
			combnum += l_range * r_range;
		}
		ans += combnum * nowv;
		s.insert(p);
	}
	cout << ans << endl;
}

