pii qry[1<<17];

void solve()
{
    for(int i = 0, t = 0, stk[1 << 17]; i < n; i++)
    {
        while(t and p[stk[t - 1]] < p[i])
        {
            t--;
        }
        l[i] = t ? stk[t - 1] : -1;
        dump(i, l[i]);
        stk[t++] = i;
        qry[i]={l[i],i};
        ll[i]=-1;
    }

    {
        sort(qry,qry+n);
        Segment_tree<int,int> seg(n+1,-1,maxf<int>,[](int &x,int y){x=y;});
        for(int i=0,j=0; i<n; i++)
        {
            while(j<n and qry[j].first<i)
            {
                j++;
            }
            while(j<n and qry[j].first==i)
            {
                int k=qry[j].second;
                ll[k]=seg.query(p[k],n+1);
                j++;
            }
            seg.update(p[i],i);
        }
    }

    for(int i = n - 1, t = 0, stk[1 << 17]; i >= 0; i--)
    {
        while(t and p[stk[t - 1]] < p[i])
        {
            t--;
        }
        r[i] = t ? stk[t - 1] : n;
        stk[t++] = i;
        dump(i, r[i]);
        qry[i]={r[i],i};
        rr[i]=n;
    }

    {
        rsort(qry,qry+n);
        Segment_tree<int,int> seg(n+1,n,minf<int>,[](int &x,int y){x=y;});
        for(int i=n-1,j=0; i>=0; i--)
        {
            while(j<n and qry[j].first>i)
            {
                j++;
            }
            while(j<n and qry[j].first==i)
            {
                int k=qry[j].second;
                rr[k]=seg.query(p[k],n+1);
                j++;
            }
            seg.update(p[i],i);
        }
    }

    i64 ans = 0;
    for(int i = 0; i < n; i++)
    {
        ans += (i64)p[i] * (l[i] - ll[i]) * (r[i] - i);
        ans += (i64)p[i] * (rr[i] - r[i]) * (i - l[i]);
        dump(i, ans);
    }
    std::cout << ans << "\n";
}

