template<typename D, Int useAssert = 1>
class RMQ{
public :
  struct T{ //遅延データ
    Int type; //0 - empty, 1 - update, 2 - ifUpdate
    D value;
    T(Int type, D value):type(type), value(value){}
  };

  Int n, n_;
  D initValue;        //範囲外の時に返す値
  vector<D> dat;
  vector<T> td;
  Int toMax;          //0 -> RangeMin 1->RangeMax;

  RMQ(){n=-1;}
  RMQ(Int n_, D initValue, Int toMax = 0):n_(n_), initValue(initValue), toMax(toMax){
    n=1;
    while(n<n_)n*=2;
    td.resize(2*n-1, T(0, initValue));
    dat.resize(2*n-1, initValue);
  }

  //目的データのマージ
  inline D mergeD(D l, D r){return toMax? max(l, r):min(l, r);}

  //遅延データのマージ
  inline T mergeT(T from, T to){
    if(to.type == 0) return from;
    if(from.type == 0) return to; //from-empty
    if(to.type == 1) return to; //to-update;
    if(to.type == 2) return T(from.type, mergeD(from.value, to.value)); //to-ifupdate
    if(useAssert) assert(0);
  }

  //目的データに遅延データを反映
  inline void apply(D &a, T b){
    if(b.type == 0) return;
    if(b.type == 1) a = b.value; //update
    else a = mergeD(a, b.value); // if-update
  }

  D dfs(Int a, Int b, T x, Int k, Int l, Int r){
    if(r <= a || b <= l) return x.type == 0? initValue : dat[k];
    if(a <= l && r <= b){
      td[k] = mergeT(td[k], x);
      apply(dat[k], x);
      return dat[k];
    }
    Int kl = k * 2 + 1, kr = k * 2 + 2;
    { //遅延を子に反映
      td[kl] = mergeT(td[kl], td[k]);
      td[kr] = mergeT(td[kr], td[k]);
      apply(dat[kl], td[k]);
      apply(dat[kr], td[k]);
      td[k] = T(0, initValue);
    }
    D vl = dfs(a, b, x, kl, l, (l+r)/2);
    D vr = dfs(a, b, x, kr, (l+r)/2, r);
    return x.type == 0? mergeD(vl,vr) : (dat[k] = mergeD(vl, vr));
  }

  //[l,r)の値をxに変更　update(l,r,x)
  void update(Int l,Int r, D x){
    if(useAssert) assert(l <= r), assert(l <= n && r <= n), assert(l >= 0 && r >= 0);
    dfs(l, r,  T(1, x), 0, 0, n);
  }

  //[l,r)の値をもしもxの方が小さければ変更　ifupdate(l,r,x)
  //toMaxのときは[l,r)の値をもしもxの方が大きければ変更　ifupdate(l,r,x)
  void ifupdate(Int l,Int r, D x){
    if(useAssert) assert(l <= r), assert(l <= n && r <= n), assert(l >= 0 && r >= 0);
    dfs(l, r,  T(2, x), 0, 0, n);
  }

  //[l,r)の最小値を得る　get(l,r);
  D get(Int l,Int r){
    if(useAssert) assert(l <= r), assert(l <= n && r <= n), assert(l >= 0 && r >= 0);
    return dfs(l, r, T(0, initValue), 0 , 0 ,n);
  }
};

Int solve(Int N, vector<Int> A){
  vector<Int> Idx(N);
  for(Int i=0;i<N;i++) Idx[A[i]] = i;

  RMQ<Int, 0> seg(N, -INF, 1);
  for(Int i=0;i<N;i++) seg.update(i, i+1, A[i]);

  auto get = [&](Int l, Int r){ //[l, r)
    Int top = seg.get(l, r);
    seg.update(Idx[top], Idx[top]+1, -INF);
    Int top2 = seg.get(l, r);
    seg.update(Idx[top], Idx[top]+1, top);
    return top2;
  };

  auto calc = [&](Int l){
    Int L = 0, R = N - l;
    while(L + 1 < R){
      Int M = (L + R) / 2;
      if( seg.get(l, l + M + 1) == A[l]) L = M;
      else R = M;
    }
    return l + L;
  };

  auto calc1 = [&](Int l, Int L){
    Int R = N - l;
    while(L + 1 < R){
      Int M = (L + R) / 2;
      if( get(l, l + M + 1) == A[l] ) L = M;
      else R = M;
    }
    return l + L;
  };

  auto calc2 = [&](Int l){
    Int L = 0, R = l + 1;
    while(L + 1 < R){
      Int M = (L + R) / 2;
      if( seg.get(l - M, l+1) == A[l] ) L = M;
      else R = M;
    }
    return L;
  };

  Int ans = 0;
  for(Int i=0;i<N - 1;i++){
    Int numRight = calc(i) + 1;
    if(numRight == N) continue;
    Int len = calc1(i, numRight - i) - numRight + 1;
    Int numLeft = calc2(i) + 1;
    Int score = len * numLeft * (A[i] + 1);
    //pr(i, A[i], numRight, calc1(i, numRight - i), len, numLeft, score);
    ans += score;
  }
  return ans;
}

