void fast_salve(vector<int>& a) {
	int n = a.size(), ans = 0;
	for (int l = 0; l < n - 1; ++l) {
		int mx1 = a[l], mx2 = 0;
		for (int r = l + 1; r < n; ++r) {
			if (a[r] > mx1) {
				ans += mx1;
				mx2 = mx1;
				mx1 = a[r];
			}
			else if (a[r] > mx2) {
				ans += a[r];
				mx2 = a[r];
			}
			else {
				ans += mx2;
			}
		}
	}
	cout << ans;
}

