ll numRange(const vector<int>& l, int i, const vector<int>& r) {
  return 1LL * (i - l[1]) * (r[1] - r[0]) + 1LL * (l[1] - l[0]) * (r[0] - i);
}

ll solve(int N, const vector<int>& P) {
  vector<int> pos(N);
  REP(i, N) pos[P[i]] = i;
  set<int> ix;
  ll ans = 0;
  for (int i = N - 1; i >= 0; --i) {
    auto it = ix.lower_bound(pos[i]);
    auto rit = it;
    auto lit = reverse_iterator<decltype(rit)>(rit);
    vector<int> l, r;
    REP(_, 2) {
      if (rit == ix.end()) break;
      r.push_back(*rit++);
    }
    while (r.size() < 2) r.push_back(N);
    REP(_, 2) {
      if (lit == ix.rend()) break;
      l.push_back(*lit++);
    }
    while (l.size() < 2) l.push_back(-1);
    reverse(l.begin(), l.end());
    ans += i * numRange(l, pos[i], r);
    ix.insert(pos[i]);
  }
  return ans;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int N;
  cin >> N;
  vector<int> P(N);
  for (int& p : P) cin >> p, --p;
  cout << solve(N, P) + 1LL * N * (N - 1) / 2 << '\n';

  return 0;
}

