const int MAXN = 100000;
int fa[MAXN + 5], siz[MAXN + 5];
int find(int x) {
	return fa[x] = (fa[x] == x ? x : find(fa[x]));
}
void unite(int x, int y) {
	int fx = find(x), fy = find(y);
	if( fx != fy ) {
		fa[fx] = fy;
		siz[fy] += siz[fx];
	}
}
int P[MAXN + 5], Q[MAXN + 5];
int l[MAXN + 5], r[MAXN + 5];
int stk[MAXN + 5], tp;
int main() {
	int N; scanf("%d", &N);
	for(int i=1;i<=N;i++)
		scanf("%d", &P[i]), Q[P[i]] = i;
	P[0] = P[N + 1] = N + 1;
	stk[tp = 1] = 0;
	for(int i=1;i<=N;i++) {
		while( P[stk[tp]] < P[i] ) tp--;
		l[i] = stk[tp], stk[++tp] = i;
	}
	stk[tp = 1] = N + 1;
	for(int i=N;i>=1;i--) {
		while( P[stk[tp]] < P[i] ) tp--;
		r[i] = stk[tp], stk[++tp] = i;
	}
	long long ans = 0;
	for(int i=1;i<=N;i++) {
		int x = Q[i];
		fa[x] = x, siz[x] = 1;
		if( P[x - 1] < P[x] ) unite(x, x - 1);
		if( P[x + 1] < P[x] ) unite(x, x + 1);
		long long del = 0;
		if( l[x] != 0 )
			del += (r[x] - x)*(siz[find(l[x] - 1)] + 1);
		if( r[x] != N + 1 )
			del += (x - l[x])*(siz[find(r[x] + 1)] + 1);
		ans += 1LL*del*i;
	}
	printf("%lld\n", ans);
}

