int get(int l, int r){
    int res = 0;
    while (r >= l){
        if (r - (r & -r) >= l){
            res = max (res, f[r]);
            r -= r & -r;
        }
        else {
            res = max (res, a[r]);
            r--;
        }
    }
    return res;
}

int bs1(int hi, int i){
    int lo = 1, val = a[i], pre = hi;
    while (lo < hi){
        int mid = (lo + hi) / 2;
        if (get(mid, pre - 1) < a[i]) hi = mid;
        else lo = mid + 1;
    }
    return hi;
}

