class BIT{
    int dat[N+5];
    //
    int LSOne(int a){ return a&-a; }
public:
    int reset(){
        FOR(i,N+3) dat[i] = 0;
        return 0;
    }
    int upd(int pos, int val=1){
        REPP(i,pos,N,LSOne(i)) dat[i] += val;
        return 0;
    }
    int que(int pos){
        int res = 0;
        REVV(i,pos,1,LSOne(i)) res += dat[i];
        return res;
    }
    int que(int a, int b){
        return que(b) - que(a-1);
    }
};

pii dat[N+5];
BIT ds;

int main(){
    // reset
    ds.reset();
    // input
    int n; scanf("%d", &n);
    REP(i,1,n) scanf("%d", &dat[i].fi), dat[i].se = i;
    sort(dat+1, dat+1+n);
    //
    ll res = (ll)0;
    REP(i,1,n-1){
        int pos = dat[i].se;
        ds.upd(pos);
        // find left
        int reta = pos;
        for(int lo=1,hi=pos-1; lo<=hi; ){
            int mid = (lo+hi) / 2;
            int key = ds.que(mid,pos-1);
            //
            if(key+1 < pos-mid){
                lo = mid+1;
            } else {
                hi = mid-1;
                reta = mid;
            }
        }
        // find right
        int retb = pos;
        for(int lo=pos+1,hi=n; lo<=hi; ){
            int mid = (lo+hi) / 2;
            int key = ds.que(pos+1,mid);
            //
            if(key+1 >= mid-pos){
                lo = mid+1;
                retb = mid;
            } else {
                hi = mid-1;
            }
        }
        // find left 2
        int retae = pos;
        for(int lo=1,hi=pos-1; lo<=hi; ){
            int mid = (lo+hi) / 2;
            int key = ds.que(mid,pos-1);
            //
            if(key != pos-mid){
                lo = mid+1;
            } else {
                hi = mid-1;
                retae = mid;
            }
        }
        // find right 2
        int retbe = pos;
        for(int lo=pos+1,hi=n; lo<=hi; ){
            int mid = (lo+hi) / 2;
            int key = ds.que(pos+1,mid);
            //
            if(key == mid-pos){
                lo = mid+1;
                retbe = mid;
            } else {
                hi = mid-1;
            }
        }
        // count
        reta = pos - reta;  retae = pos - retae + 1;
        retb = retb - pos;  retbe = retbe - pos + 1;
        reta -= retae - 1;
        retb -= retbe - 1;
        res += (ll)dat[i].fi * (ll)(reta*retbe + retb*retae);
    }
    // print
    printf("%lld\n", res);
    return 0;
}

