	ll ret = typ * (n + 1);
	while(l <= r)
	{
		// printf("%lld %lld\n", l, r);
		ll mid = (l + r) >> 1;
		if(typ == 1)
		{
			if(query(mid, s) > x) r = mid - 1, ret = mid;
			else l = mid + 1;
		}
		else
		{
			if(query(mid, e) > x) l = mid + 1, ret = mid;
			else r = mid - 1;
		}
	}
	return ret;
}

