vpii find2(int N, vi& p) {
    vpii res(N, mp(N, N));

    stack<pii> st; st.push({ INT_MAX, N });
    vvi when(N + 1);
    F0Rd (i, N) {
        while (st.top().f < p[i]) st.pop();
        res[i].f = st.top().s;
        when[res[i].f].pb(i);
        st.push({ p[i], i });
    }

    deque<pii> active; active.push_front({ INT_MAX, N });
    F0Rd (i, N) {
        trav (j, when[i]) {
            res[j].s = lb(all(active), mp(p[j], INT_MAX))->s;
        }
        while (active.front().f < p[i]) active.pop_front();
        active.push_front({ p[i], i });
    }

    return res;
}

int main() {
    setIO();

    int N; re(N); vi p(N); re(p);

    vpii right = find2(N, p);
    reverse(all(p));
    vpii left = find2(N, p);

    reverse(all(p));
    reverse(all(left));
    F0R (i, N) {
        left[i].f = N - 1 - left[i].f;
        left[i].s = N - 1 - left[i].s;
        swap(left[i].f, left[i].s);
    }

    ll ans = 0;
    F0R (i, N) {
        ans += p[i] * ll(left[i].s - left[i].f) * ll(right[i].f - i);
        ans += p[i] * ll(right[i].s - right[i].f) * ll(i - left[i].s);
    }
    ps(ans);

    return 0;
}

