#define mu(x) (1 << (x))
#define maxn 100005

using namespace std;
typedef long long ll;

int n;

int a[maxn];

int p[maxn][20];
int f[maxn];

void RMQ(){
    for (int i = 0; i <= n + 1; ++i)
        p[i][0] = a[i];

    for (int j = 1; j < 20; ++j)
        for (int i = 0; i <= n + 1; ++i)
            if (i + mu(j) <= n + 2)
                p[i][j] = max(p[i][j - 1], p[i + mu(j - 1)][j - 1]);

    for (int i = 1; i <= n + 1; ++i)
        for (int j = 0; j < 20; ++j)
            if (mu(j) <= i) f[i] = j;
}

int Max(int i, int j){

    return max(p[i][f[j -  i]], p[j - mu(f[j - i]) + 1][f[j - i]]);
}

int tkr(int l, int r, int k){
    int i = l;
    while (l < r){
        int mid = (l + r) / 2;
        if (Max(i, mid) > k) r = mid;
        else l = mid + 1;
    }
    return r;
}

int tkl(int l, int r, int k){
    int j = r;
    while (l < r){
        int mid = (l + r + 1) / 2;
        if (Max(mid, j) >= k) l = mid;
        else r = mid - 1;
    }
    return l;
}
int main(){
  //  #define TASK "ABC"
