    ios_base::sync_with_stdio(0); cin.tie(); cout.tie();

    cin >> n;
    for (int i = 1; i <= n; ++i)
        cin >> a[i];
    a[0] = a[n + 1] = n + 1;

    RMQ();

    ll ans = 0;
    for (int i = 1; i <= n; ++i){
        int r1 = tkr(i + 1, n + 1, a[i]), r2 = tkr(r1 + 1, n + 1, a[i]);
        int l1 = tkl(0, i - 1, a[i]), l2 = tkl(0, l1 - 1, a[i]);

        ll ret = 0;

        ret += 1ll * (r2 - r1) * (i - l1);
        ret += 1ll * (r1 - i) * (l1 - l2);
        ans += ret * a[i];
    }
    cout << ans;
    return 0;
}

