int main () {
	int N; cin >> N;
	vi P(N); // index -> value
	map<int, int> m; // value -> index
	rep(i, N) { // 0-indexed
		cin >> P.at(i); // index -> value
		m[P.at(i)] = i; // value -> index
	}	
	// vdebug(P);
	// for (auto mi : m) cout << mi.first << " " << mi.second << endl;
	set<int> s;
	ll ans = 0;
	for (int k = N; k > 0; k--) { // k:value
		s.insert(m.at(k)); // indexを入れる
		auto it = lower_bound(all(s), m.at(k)); // 値kに対応する添字xに対応するiterator
		ll x = *it;
		ll l2, l1, r1, r2;
		if (it == s.begin()) {
			l2 = l1 = -1;
		} else if (prev(it) == s.begin()) {
			l2 = -1; l1 = *prev(it);
		} else {
			l2 = *prev(prev(it)); l1 = *prev(it);
		}
		if (it == prev(s.end())) {
			r1 = r2 = N;
		} else if (next(it) == prev(s.end())) {
			r1 = *next(it); r2 = N;
		} else {
			r1 = *next(it); r2 = *next(next(it));
		}
		ll temp = k * ((l1 - l2) * (r1 - x) + (x - l1) * (r2 - r1));
		// debug(k);	debug(temp);
		ans += temp;
	}

	cout << ans << endl;
}

