using namespace std;

typedef pair<int, int> pii;
typedef long long ll;

int n, _n;
pii *a;
long long ans;

pii get_max(int l, int r, int L, int R, int v) {
	if(l <= L && R <= r) return a[v];
	if(l > R || r < L) return {0,0};
	return max(get_max(l, r, L, (L+R)/2, 2*v),
	           get_max(l, r, (L+R)/2 + 1, R, 2*v+1));
}

map<pii, bool> used;

void solve(int L, int R, int M) {
	if(L + 1 > R) return;
	if(used[{L,R}]) return;
	used[{L,R}] = 1;
	pii x = get_max(L, M-1, 1, n, 1);
	pii y = get_max(M+1, R, 1, n, 1);
	if(x < y) x = y;
	ll a = min(x.Y, M);
	ll b = max(x.Y, M);

	//cout << L << ' ' << a << ' ' << b << ' ' << R << ' ' << x.X << '\n';
	ll delta = (R - b + 1) * (a - L + 1) * x.X;
	//cout << delta << '\n';
	ans += delta;

	solve(L, b-1, a);
	solve(a+1, R, b);
}

int main() {
	ios_base::sync_with_stdio(0);

	cin >> _n;
	for(n = 1; n < _n; n *= 2);

	a = (pii*)malloc(2*n*sizeof(pii));

	for(int i = 0; i < n; i++) {
		if(i < _n) {
			int x;
			cin >> x;
			a[n+i] = {x, i+1};
		} else {
			a[n+i] = {0,0};
		}
	}
	for(int i = n-1; i; i--) a[i] = max(a[2*i], a[2*i + 1]);

	solve(1, _n, a[1].Y);

	cout << ans << '\n';

	return 0;
}

