int nn_mx;
long long dat_mx[(2 * N_MAX) - 1];

void init_mx(int n1) {
  nn_mx = 1;

  while (nn_mx < n1)nn_mx *= 2;

  for (int i = 0; i < 2 * nn_mx - 1; i++) {
    dat_mx[i] = -INF;
  }
}

void update_mx(int k, long long a) {
  k += nn_mx - 1;
  dat_mx[k] = a;
  while (k > 0) {
    k = (k - 1) / 2;
    dat_mx[k] = max(dat_mx[k * 2 + 1], dat_mx[k * 2 + 2]);
  }
}

long long query_mx(int a, int b, int k, int l, int r) {
  if (r <= a || b <= l)return -INF;

  if (a <= l && r <= b) {
    return dat_mx[k];
  }
  else {
    long long vl = query_mx(a, b, k * 2 + 1, l, (l + r) / 2);
    long long vr = query_mx(a, b, k * 2 + 2, (l + r) / 2, r);
    return max(vl, vr);
  }
}

  long long query(long long a, long long b){
    return query_mx(a,b,0,0,nn_mx);
  }

pair<ll,ll> mx_range(ll i, ll n){
  ll l, r;
  {
    long long low = 0;
    long long high = i;

    ll a = query_mx(i, i + 1, 0, 0, nn_mx);

    while (low < high) {
      long long mid = (high + low) >> 1;
      ll b = query_mx(mid, i + 1, 0, 0, nn_mx);
      if (b <= a) {
        high = mid;
      }
      else {
        low = mid + 1;
      }
    }
    l = low;
  }
  {
    long long low = i;
    long long high = n-1;

    ll a = query_mx(i, i + 1, 0, 0, nn_mx);

    while (low < high) {
      long long mid = (high + low + 1) >> 1;
      ll b = query_mx(i, mid + 1, 0, 0, nn_mx);
      if (b<=a) {
        low = mid;
      }
      else {
        high = mid - 1;
      }
    }
    r = low;
  }
  return pair<ll,ll>(l,r);
}

int main() {
	ll n;
	cin>>n;
	init_mx(n);
	vector<pair<ll,ll> > v;
	rep(i,0,n){
		ll a;
		cin>>a;
		v.pb(mp(a,i));
		update_mx(i,a);
	}
	sort(all(v));
	ll ans = 0;
	rep(i,0,v.sz-1){
		ll n1 = v[i].fi;
		ll index = v[i].se;
		pair<ll,ll> p = mx_range(index,n);
		ll l = p.fi;
		ll r = p.se;
		if(l>1){
			long long low = 0;
			long long high = l-2;

			while(low < high){
			  long long mid = (high + low) >> 1;

			  if(n1 < query(low,l-1)){
			    high = mid;
			  }
			  else{
			    low = mid + 1;
			  }
			}
			ans += n1*(r-low);
		}
		if(r<n-1){
			long long low = r+1;
			long long high = n-1;

			while(low < high){
			  long long mid = (high + low + 1) >> 1;

			  if(n1 < query(r+1,mid+1)){
			    low = mid;
			  }
			  else{
			    high = mid - 1;
			  }
			}
			ans += n1*(low-l);
		}
	}
	cout << ans << endl;
	return 0;
}

