inline int read() {
    reg int s = 0, t = 0; reg char ch = getchar();
    while(ch > '9' || ch < '0') t |= ch == '-', ch = getchar();
    while(ch >= '0' && ch <= '9') s = (s << 1) + (s << 3) + (ch ^ 48), ch = getchar();
    return t ? -s : s;
}
stack <int> Q, F;
int L[maxn * 20], R[maxn * 20], t[maxn], sum[maxn * 20], lx[maxn],rx[maxn],ly[maxn],ry[maxn],a[maxn];
int cnt, n, ans, ansx , p, anss, sumx;
int build(int l,int r)
{
    int num=++cnt;
    if(l!=r)
    {
        int mid=(l+r)>>1;
        L[num]=build(l,mid);
        R[num]=build(mid+1,r);
    }
    return num;
}
int update(int pre,int l,int r,int x)
{
    int num=++cnt;
    L[num]=L[pre];R[num]=R[pre];sum[num]=sum[pre]+1;
    if(l!=r)
    {
        int mid=(l+r)>>1;
        if(x<=mid)L[num]=update(L[pre],l,mid,x);
        else R[num]=update(R[pre],mid+1,r,x);
    }
    return num;
}
int query(int k, int v, int l, int r, int Lc ,int Rc)
{
    int mid = l + r >> 1, res = 0;
    if(r <= Rc && l >= Lc) { res = sum[k] - sum[v]; return res;}
    if (Lc <= mid)
       res += query(L[k], L[v], l, mid, Lc, Rc);
    if (Rc > mid)
       res += query(R[k], R[v], mid + 1, r, Lc, Rc);
    return res;

}
