struct BIT{
    int N;
    vector<int> bit;

    BIT(int n = 0){
        N = n;
        bit.resize(n + 1);
    }

    int sum(int i){
        int s = 0;
        while(i > 0){
            s += bit[i];
            i -= i & -i;
        }
        return s;
    }

    void add(int i, int x){
        while(i <= N){
            bit[i] += x;
            i += i & -i; 
        }
    }

    int ser_sum(int val){
        int lb = -1, ub = N + 1;
        while(ub - lb > 1){
            int mid = (ub + lb) / 2;
            if(sum(mid) >= val) ub = mid;
            else lb = mid;
        }
        return ub;
    }
};

