using namespace std;

int a[500000], n;
long long ans = 0;

int F[1000000];
int La[1000000];

int GF(int l, int r, int L, int R, int V)
{
    if (l <= L && R <= r)
        return F[V];
    if (r <= L || R <= l)
        return n;
    int M = (L + R) / 2;
    return min(GF(l, r, L, M, 2 * V + 1), GF(l, r, M, R, 2 * V + 2));
}

int GL(int l, int r, int L, int R, int V)
{
    if (l <= L && R <= r)
        return La[V];
    if (r <= L || R <= l)
        return -1;
    int M = (L + R) / 2;
    return max(GL(l, r, L, M, 2 * V + 1), GL(l, r, M, R, 2 * V + 2));
}

void Set(int p, int L, int R, int V)
{
    if (p + 1 <= L || R <= p)
        return;
    if (L <= p && p + 1 <= R)
    {
        F[V] = min(F[V], p);
        La[V] = max(La[V], p);
    }
    if (L + 1 == R)
        return;
    int M = (L + R) / 2;
    Set(p, L, M, 2 * V + 1);
    Set(p, M, R, 2 * V + 2);
}

