const int MAXN = 1e5 + 1;
const int LOG = 20;

int n;
int t[LOG][MAXN], lg[MAXN];
vector<int> a;

inline int query(int l, int r) {
    int pw = lg[r - l + 1];
    return max(t[pw][l], t[pw][r - (1 << pw) + 1]);
}

int pref(int i, int k) {
    if (i == -1) return -1;
    if (query(0, i) <= k) return -1;
    if (a[i] > k) return i;
    int l = 0, r = i, mid;
    while (r - l > 1) {
        mid = (l + r) / 2;
        if (query(mid, i) <= k) r = mid;
        else l = mid;
    }
    return l;
}

int suf(int i, int k) {
    if (i == n) return n;
    if (query(i, n - 1) <= k) return n;
    if (a[i] > k) return i;
    int l = i, r = n - 1, mid;
    while (r - l > 1) {
        mid = (l + r) / 2;
        if (query(i, mid) <= k) l = mid;
        else r = mid;
    }
    return r;
}

