void solve() {
    forn (i, n)
        pos[--p[i]] = i;

    set<int> ids;
    ids.insert(-1);
    ids.insert(n);
    long long ans = 0;

    for (int i = n - 1; i >= 0; --i) {
        int x = pos[i];

        if (auto lmx = *(--ids.upper_bound(x)); lmx != -1) {
            int l = *(--ids.lower_bound(lmx));
            int r = *(ids.upper_bound(x));
            ans += (long long) (lmx - l) * (r - x) * (i + 1);
        }

        if (auto rmx = *(ids.upper_bound(x)); rmx != n) {
            int l = *(--ids.upper_bound(x));
            int r = *(ids.upper_bound(rmx));
            ans += (long long) (x - l) * (r - rmx) * (i + 1);
        }

        ids.insert(x);
    }

    cout << ans << endl;
}

