{
    scanf("%lld",&n);
    for(int i=1;i<=n;i++)read(num[i]);
    build(1,1,n);
    work_one();
    work_two();
    ll ans=0;
    for(int i=1;i<=n;i++){
        ans+=(pre[i][0]-pre[i][1])*(cur[i][0]-i)*num[i];
        ans+=(cur[i][1]-cur[i][0])*(i-pre[i][0])*num[i];
    }
    printf("%lld\n",ans);
    return 0;
}
