void build(int pos,int l,int r)
{
    if(l==r)
    {
        tre[pos]=l;
        return ;
    }
    int mid=(l+r)>>1;
    build(2*pos,l,mid);
    build(2*pos+1,mid+1,r);
    tre[pos]=mrg(tre[2*pos],tre[2*pos+1]);
}
int qry(int pos,int l,int r,int I,int J)
{
    if(l>J || r<I)return -1;
    if(I<=l && J>=r)
    {
        return tre[pos];
    }
    int mid=(l+r)>>1;
    int x=qry(2*pos,l,mid,I,J);
    int y=qry(2*pos+1,mid+1,r,I,J);
    if(x==-1 && y==-1)return -1;
    if(x==-1)return y;
    else if(y==-1)return x;
    if(a[x]>a[y])return x;
    else return y;
}

int q(int lft,int rgt,int x)
{
    if(lft>rgt)return -1;
    int lo=lft;
    int hi=rgt;
    while(hi-lo>=2)
    {
        int mid=(lo+hi)>>1;
        int id=qry(1,1,n,lo,mid);
        int val=-1;
        if(id!=(-1))val=a[id];
        if(val>x)
        {
            hi=mid;
        }
        else lo=mid+1;
    }
    for(int i=lo;i<=hi;i++)
    {
        if(a[i]>x)return i;
    }
    return -1;
}
