int n, p[N], P[N][20];
int get(int l, int r){
	int k = log2(r - l + 1);
	return max(P[l][k], P[r - (1 << k) + 1][k]);
}
signed main(){
	ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
	cin >> n;
	for(int i = 1 ; i <= n ; i ++)
		cin >> p[i];
	for(int i = 1 ; i <= n ; i ++)
		P[i][0] = p[i];
	for(int j = 1 ; (1 << j) <= n ; j ++)
		for(int i = 1 ; i + (1 << j) - 1 <= n ; i ++)
			P[i][j] = max(P[i][j - 1], P[i + (1 << (j - 1))][j - 1]);
	int ans = 0;
	for(int i = 1 ; i <= n ; i ++){
		// find safe left
		int safe_l = i, L = 1, R = i;
		while(L <= R){
			int M = (L + R) >> 1;
			if(get(M, i) == p[i]) safe_l = M, R = M - 1;
			else L = M + 1;
		}
		// find safe right
		int safe_r = i;
		L = i, R = n;
		while(L <= R){
			int M = (L + R) >> 1;
			if(get(i, M) == p[i]) safe_r = M, L = M + 1;
			else R = M - 1;
		}
		// check over left
		//cout << "doing on i = " << i << endl;
		//cout << "safe_l = " << safe_l << endl;
		//cout << "safe_r = " << safe_r << endl;
		if(safe_l > 1){
			int over_l = safe_l - 1;
			L = 1, R = over_l - 1;
			while(L <= R){
				int M = (L + R) >> 1;
				if(get(M, safe_l - 2) < p[i]) over_l = M, R = M - 1;
				else L = M + 1;
			}
			//cout << "over_l = " << over_l << endl;
			ans += p[i]*(safe_r - i + 1)*(safe_l - over_l);
		}
		if(safe_r < n){
			int over_r = safe_r + 1;
			L = over_r + 1, R = n;
			while(L <= R){
				int M = (L + R) >> 1;
				if(get(safe_r + 2, M) < p[i]) over_r = M, L = M + 1;
				else R = M - 1;
			}
			//cout << "over_r = " << over_r << endl;
			ans += p[i]*(over_r - safe_r)*(i - safe_l + 1);
		}
	}
	cout << ans;
}

