        vvc<int> right(N+4, vc<int>(2));
        vc<int> pool;
        stack<int> st1, st2;
        st1.push(1); st2.push(0);
        FOR(i, 2, N+2){
            while(P[st1.top()]<P[i]){
                pool.pb(st1.top());
                st1.pop();
            }
            while(st2.top()>=st1.top()) st2.pop();
            while(P[st2.top()]<P[i]){
                st2.pop();
            }
            left[i][0] = st1.top();
            left[i][1] = max(st2.top(), 1);
            st2.push(st1.top());
            st1.push(i);
            reverse(ALL(pool));
            for(auto& p : pool){
                st2.push(p);
            }
            pool.clear();
        }
        while(not st1.empty()) st1.pop();
        while(not st2.empty()) st2.pop();
        st1.push(N+2); st2.push(N+3);
        for(int i=N+1;1<i;--i){
