void checkdel(int& c,int& max1, int& max2, vector<int>& p, vector<int>& pos, int& cs, int& ce) {
	if (c == max1) {
		max1 = max2;
		int t = max2 - 1;
		while (1) {
			if (cs <= pos[t] && pos[t] <= ce) {
				max2 = t;
				break;
			}
			--t;
		}
	}
	else if (c == max2) {
		int t = max2 - 1;
		while (1) {
			if (cs <= pos[t] && pos[t] <= ce) {
				max2 = t;
				break;
			}
			--t;
		}
	}
}

void checkadd(int& c, int& max1, int& max2) {
	if (max1 < c) {
		max2 = max1;
		max1 = c;
	}
	else if (max2 < c) {
		max2 = c;
	}
}

int main()
{
	int n;
	cin >> n;
	vector<int> p(n);
	vector<int> pos(n+1);

	for (int i = 0; i < n; ++i) {
		cin >> p[i];
		pos[p[i]] = i;
	}

	int max1 = n;
	int max2 = n-1;
	ll ret = max2;
	int cs = 0;
	int ce = n - 1;
	for (int i = n - 1; 2 <= i; --i) {
		if (cs == 0) {
			--ce;
			checkdel(p[ce+1], max1, max2, p, pos, cs, ce);
			while (1) {
				ret += max2;
				if (ce == n - 1) {
					break;
				}
				++ce;
				checkadd(p[ce], max1, max2);
				++cs;
				checkdel(p[cs-1], max1, max2,p,pos,cs,ce);
			}
		}
		else {
			++cs;
			checkdel(p[cs-1], max1, max2, p, pos, cs, ce);
			while (1) {
				ret += max2;
				if (cs == 0) {
					break;
				}
				--cs;
				checkadd(p[cs], max1, max2);
				--ce;
				checkdel(p[ce + 1], max1, max2, p, pos, cs, ce);
			}
		}
	}

	cout << ret << endl;

	return 0;
}

