	vector<Pll>node, lazy;
	Seg(LL n_) {
		n = 1; while (n < n_)n *= 2;
		node.resize(n * 2 - 1);
		lazy.resize(n * 2 - 1);
		rep(i, n)node[n + i - 1] = Pll(-1, -1);
		Rrep(i, n - 2)node[i] = Pll(-1, -1);
		//区間最小などの時
		rep(i, n * 2 - 1)lazy[i] = Pll(-1,-1);
	}
	//区間の最小の遅延
	void ceval(LL k, LL l, LL r) {
		if (lazy[k] != Pll(-1,-1)) {
			if (lazy[k].second == -1)
				node[k] = Pll(lazy[k].first, node[k].first);
			else node[k] = lazy[k];
			if (r - l >= 1) {
				if (lazy[k].sec == -1) {
					lazy[k * 2 + 1] = Pll(lazy[k].fir, lazy[k * 2 + 1].fir);
					lazy[k * 2 + 2] = Pll(lazy[k].fir, lazy[k * 2 + 2].fir);
				}
				else {
					lazy[k * 2 + 1] = lazy[k];
					lazy[k * 2 + 2] = lazy[k];
				}
			}
			lazy[k] = Pll(-1,-1);
		}
	}
	void update(LL x, LL l, LL r) {
		update(0, x, 0, n - 1, l, r);
	}
	void update(LL i, LL x, LL a, LL b, LL l, LL r) {
		ceval(i, a, b);
		if (b < l || r < a)return;
		if (l <= a && b <= r) {
			lazy[i] = Pll(x,lazy[i].fir);
			ceval(i, a, b);
		}
		else {
			update(i * 2 + 1, x, a, (a + b) / 2, l, r);
			update(i * 2 + 2, x, (a + b + 1) / 2, b, l, r);
		}
	}
	Pll find(LL l, LL r) {
		return find(0, 0, n - 1, l, r);
	}
	Pll find(LL i, LL a, LL b, LL l, LL r) {
		ceval(i, a, b);
		if (b < l || r < a)return Pll(-1,-1);
		if (l <= a && b <= r)return node[i];
		Pll R = find(i * 2 + 2, (a + b + 1) / 2, b, l, r), L = find(i * 2 + 1, a, (a + b) / 2, l, r);
		if (R != Pll(-1, -1))return R;
		return L;
	}
};
