int main() {
  LL N;
  std::cin >> N;
  std::vector<int> P(N);
  REP(i,N) {
    std::cin >> P[i];
    P[i]--;
  }
  std::vector<int> idx(N);
  for(LL i=0; i<N; i++) {
    idx[P[i]] = i;
  }

  LL ans = 0;
  std::set<int> larges; // indexes of P that are larger than target
  larges.insert(idx[N-1]);

  for(LL t=N-2; t >= 0; t--) {
    larges.insert(idx[t]);
    std::array<LL,2> ridxes = {N,N};
    std::array<LL,2> lidxes = {-1,-1};
    auto it = larges.find(idx[t]);
    it++;
    if( it != larges.end()) {
      ridxes[0] = *it;
      it++;
      if (it != larges.end()) { ridxes[1] = *it; }
    }
    it = larges.find(idx[t]);
    if( it != larges.begin() ) {
      it--;
      lidxes[0] = *it;
      if( it != larges.begin() ) { it--; lidxes[1] = *it; }
    }

    // one larger element on right
    ans += (t+1) * (ridxes[1]-ridxes[0]) * (idx[t]-lidxes[0]);
    // one larger element on left
    ans += (t+1) * (lidxes[0]-lidxes[1]) * (ridxes[0]-idx[t]);
  }

  std::cout << ans << std::endl;

  return 0;
}

