template <typename T>
class SegmentTree {
public:
    ll size;
    vector<T> node;
    function<T(T, T)> comp;
    T identity_ele;  //comp(x, identity_ele) == x

    SegmentTree(vector<T> v, function<T(T, T)> comp, T identity_ele) 
        : comp(comp),
          identity_ele(identity_ele)
    {
        ll tmp = 1;
        while(tmp < v.size()) tmp = (tmp << 1);
        this->size = tmp;
        this->identity_ele = identity_ele;
        this->comp = comp;
        node = V<T>(2 * size - 1, identity_ele);
        for(ll i = 0; i < v.size(); i++) {
            node[i + size - 1] = v[i];
        }
        for(ll i = size - 2; 0 <= i; i--) {
            node[i] = comp(node[i * 2 + 1], node[i * 2 + 2]);
        }
    }

    void update(ll pos, T value) {
        pos += size - 1;
        node[pos] = value;
        while(pos > 0) {
            pos = (pos - 1) / 2;
            node[pos] = comp(node[2 * pos + 1], node[2 * pos + 2]);
        }
    }

    T query(ll a, ll b) {
        return sub_query(a, b, 0, 0, size);
    }

    T sub_query(ll a, ll b, ll k, ll l, ll r) {
        if(r <= a || b <= l) {
            return identity_ele;
        } else if(a <= l && r <= b) {
            return node[k];
        } else {
            T left = sub_query(a, b, k * 2 + 1, l, (l + r) / 2);
            T right = sub_query(a, b, k * 2 + 2, (l + r) / 2, r);
            return comp(left, right);
        }
    }
};

ll N;

V<PLL> calc_range(V<ll> P, bool rev) {
    if(rev) reverse(ALL(P));
    const ll v_size = 1e5 + 10;
    SegmentTree<PLL> st(V<PLL>(v_size, PLL(-1, -1)),
                        [](PLL p, PLL q) {
                            ll a, b, c, d;
                            tie(a, b) = p;
                            tie(c, d) = q;
                            ll tmp[] = { a, b, c, d };
                            sort(tmp, tmp + 4);
                            return PLL(tmp[3], tmp[2]);
                        },
                        PLL(-1, -1));
    V<PLL> ret(P.size());
    for(ll i = 0; i < N; i++) {
        ll resf, ress;
        tie(resf, ress) = st.query(P[i], v_size);
        ll idx = i;
        if(rev) {
            resf = (N - 1) - resf;
            ress = (N - 1) - ress;
            idx = (N - 1) - i;
        }
        ret[idx].first = abs(idx - resf); 
        ret[idx].second = abs(ress - resf);
        st.update(P[i], PLL(i, -1));
    }
    return ret;
}

int main() {
    cin >> N;
    V<ll> P(N);
    for(auto &&ele : P) cin >> ele;
    auto left_cnt = calc_range(P, false);
    auto right_cnt = calc_range(P, true);
    ll ans = 0;
    for(ll i = 0; i < N; i++) {
        ll lf, ls, rf, rs;
        tie(lf, ls) = left_cnt[i];
        tie(rf, rs) = right_cnt[i];
        ll range = lf * rs + ls * rf;
        ans += range * P[i];
    }
    cout << ans << endl;
    return 0;
}

