private:
    int n;
public:
    // 元配列 v をセグメント木で表現する
    SegmentTree(vector<int> v)
    {
        // 最下段のノード数は元配列のサイズ以上になる最小の 2 冪 -> これを n とおく
        // セグメント木全体で必要なノード数は 2n-1 個である
        int sz = v.size();
        n = 1;
        while (n < sz)
            n *= 2;
        node.resize(2 * n - 1, make_pair(-INF, -INF));

        // 最下段に値を入れたあとに、下の段から順番に値を入れる
        // 値を入れるには、自分の子の 2 値を参照すれば良い
        for (int i = 0; i < sz; i++)
            node[i + n - 1] = make_pair(v[i], -INF);
        for (int i = n - 2; i >= 0; i--)
        {
            int maxv, maxv2;
            maxv = max(node[2 * i + 1].FI, node[2 * i + 2].FI);
            if (node[2 * i + 1].FI > node[2 * i + 2].FI){
                maxv2 = max(node[2 * i + 2].FI, node[2 * i + 1].SE);
            }
            else if (node[2 * i + 1].FI < node[2 * i + 2].FI)
            {
                maxv2 = max(node[2 * i + 1].FI, node[2 * i + 2].SE);
            }else
            {
                maxv2 = node[2 * i + 2].FI;
            }
            node[i] = make_pair(maxv, maxv2);
        }
        REP(i,node.size()){
            if (node[i].FI == -INF)
                node[i].FI = 0;
            if (node[i].SE == -INF)
                node[i].SE = 0;
        }
    }
