void build(){

	memset(dp, 0, sizeof(dp));

	for(int k = 0 ; k < n ; k++){

		int j = k+1;
		for(int i = 0; i < n ; i++){

			if(i+1 == j){

				dp[i][j] = min(a[i], a[j]);
			}
			else{

				dp[i][j] = max(max(dp[i+1][j], dp[i][j-1]), min(a[i], a[j]));
			}
			// cout << dp[i][j] << " " << i << " " << j << endl;
			j++;
		}
	}
}

