int main()
{
    Int N;
    cin >> N;

    vector<pair<Int, Int>> V;
    for (Int i = 1; i < N + 1; i++) {
        Int p;
        cin >> p;
        V.emplace_back(p, i);
    }

    sort(begin(V), end(V));
    reverse(begin(V), end(V));

    multiset<Int> S{0, 0, N + 1, N + 1};

    Int ans = 0;
    for (auto &v : V) {
        Int value = v.first;
        Int index = v.second;

        auto it = S.lower_bound(index);

        Int r1 = *it++;
        Int r2 = *it--;

        it--;

        Int l1 = *it--;
        Int l2 = *it;

        ans += value * (
            (r2 - r1) * (index - l1) +
            (l1 - l2) * (r1 - index)
        );

        S.insert(index);
    }

    cout << ans << '\n';
}

