int main(){
    int n;cin>>n;
    vin p(n);
    map<int,int> num;
    rep(i,n){
        cin>>p[i];
        num[p[i]]=i+1;
    }
    set<int> rplus,rminus;
    rep2(i,1,n+1){
        rplus.insert(i);
        rminus.insert(-i);
    }//考えている数字より大きい数字の場所を残しておく
    int rsize=n;
    ll small,big,tmp,sum,ans=(ll)0;
    ll l1,l2,r1,r2;//l1:iより小さいまだ残ってる数字の中でiに一番近い数字の場所 l2:iに二番目に近い r1,r2も同様
    rep2(i,1,n){
        tmp=num[i];
        rplus.erase(tmp);
        rminus.erase(-tmp);
        rsize--;
        small=distance(rminus.begin(),upper_bound(all(rminus),-tmp));
        if(small<rsize){
            l1=*upper_bound(all(rminus),-tmp);
            l1*=-1;
        }
        else l1=0;
        if(small<rsize-1){
            l2=*upper_bound(all(rminus),-l1);
            l2*=-1;
        }
        else l2=0;
        big=distance(rplus.begin(),upper_bound(all(rplus),tmp));
        if(big<rsize)r1=*upper_bound(all(rplus),tmp);
        else r1=n+1;
        if(big<rsize-1)r2=*upper_bound(all(rplus),r1);
        else r2=n+1;
        sum=(l1-l2)*(r1-tmp)+(tmp-l1)*(r2-r1);
        //cout<<i<<" "<<sum<<" "<<l1<<" "<<l2<<" "<<tmp<<" "<<r1<<" "<<r2<<endl;
        sum*=(ll)i;
        ans+=sum;
    }
    cout<<ans<<endl;
}

