using namespace std;

struct Node
{
    int left;
    int right;

    Node(int left, int right) : left(left), right(right) {}
    Node() : Node(-1, -1) {}

    static Node Merge(const Node &a, const Node &b)
    {
        int left = (a.left != -1 && b.left != -1 ? min(a.left, b.left) : max(a.left, b.left));
        int right = max(a.right, b.right);

        return Node(left, right);
    }
};

class SegTree
{
public:
    SegTree(int size) : tree_(4 * size + 4), size_(size) {}

    void Add(int pos) { Update(0, 0, size_ - 1, pos); }

    int GetLeft(int pos) const { return Get(0, 0, size_ - 1, 0, pos - 1).right; }
    int GetRight(int pos) const { return Get(0, 0, size_ - 1, pos + 1, size_ - 1).left; }

private:
    void Update(int node, int left, int right, int pos);
    Node Get(int node, int left, int right, int x, int y) const;

    int LeftSon(int node) const { return 2 * node + 1; }
    int RightSon(int node) const { return 2 * node + 2; }

    vector<Node> tree_;
    int size_;
};


void SegTree::Update(int node, int left, int right, int pos)
{
    if (left == right) {
        tree_[node].left = tree_[node].right = pos;
        return;
    }

    int mid = left + (right - left) / 2;
    if (pos <= mid) {
        Update(LeftSon(node), left, mid, pos);
    } else {
        Update(RightSon(node), mid + 1, right, pos);
    }
    tree_[node] = Node::Merge(tree_[LeftSon(node)], tree_[RightSon(node)]);
}

Node SegTree::Get(int node, int left, int right, int x, int y) const
{
    if (x > y) {
        return Node();
    }
    if (x <= left && right <= y) {
        return tree_[node];
    }

    Node res;
    int mid = left + (right - left) / 2;

    if (x <= mid) {
        res = Node::Merge(res, Get(LeftSon(node), left, mid, x, y));
    }
    if (mid < y) {
        res = Node::Merge(res, Get(RightSon(node), mid + 1, right, x, y));
    }
    return res;
}

int64_t CountPairs(const SegTree &tree, int pos)
{
    int left = tree.GetLeft(pos);
    int right = tree.GetRight(pos);

    int far_left = tree.GetLeft(left);
    int far_right = tree.GetRight(right);

    int64_t pairs = 0;
    if (far_left != -1) {
        pairs += 1LL * (right - pos) * (left - far_left);
    }
    if (far_right != -1) {
        pairs += 1LL * (pos - left) * (far_right - right);
    }
    return pairs;
}

