typedef pair <int, int> pii;


inline int max (const int& a, const int& b) { return a <= b ? b : a; }

inline pii merge (pii x, pii y) {
  int first_mx = max(x.first, y.first);
  int second_mx = max(x.second, y.second);
  if (first_mx == x.first) second_mx = max(second_mx, y.first);
  if (first_mx == y.first) second_mx = max(second_mx, x.first);
  return std::move(pii(first_mx, second_mx));
}

const int MAX_N = 1e5 + 10;

int n;
pii st[2 * MAX_N];

void build () {
  for (int i = n - 1; i > 0; i--) st[i] = merge(st[i << 1], st[i << 1 | 1]);
}

pii getMax (int l, int r) {
  r++;
  pii res(-1, -1);
  for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
    if (l&1) res = merge(res, st[l++]);
    if (r&1) res = merge(res, st[--r]);
  }
  return res;
}

int main () {
  ios::sync_with_stdio(false); cin.tie(0);
  cin >> n;
  vector <int> arr(n + 1);
  vector <int> pos(n + 1);
  for (int i = 0; i < n; i++) {
    cin >> arr[i];
    pos[arr[i]] = i;
    st[n + i] = pii(arr[i], -1);
  }
  build();
  function <pii(int,int)> getRange = [&] (int num, int sec) -> pii {
    pii exp(num, sec);
    int l1 = 0, r1 = pos[num];
    while (l1 != r1) {
      int m = (l1 + r1) >> 1;
      pii cur = getMax(m, pos[sec]);
      if (exp == cur) r1 = m;
      else l1 = m + 1;
    }
    int l2 = pos[num], r2 = n - 1;
    while (l2 != r2) {
      int m = (l2 + r2 + 1) >> 1;
      pii cur = getMax(pos[sec], m);
      if (exp == cur) l2 = m;
      else r2 = m - 1;
    }
    return pii(l1, l2);
  };
  function <pii(int)> getRange2 = [&] (int num) -> pii {
    int l1 = 0, r1 = pos[num];
    while (l1 != r1) {
      int m = (l1 + r1) >> 1;
      pii cur = getMax(m, pos[num]);
      if (num == cur.first) r1 = m;
      else l1 = m + 1;
    }
    int l2 = pos[num], r2 = n - 1;
    while (l2 != r2) {
      int m = (l2 + r2 + 1) >> 1;
      pii cur = getMax(pos[num], m);
      if (num == cur.first) l2 = m;
      else r2 = m - 1;
    }
    return pii(l1, l2);
  };
  ll ans = 0;
  for (int sec = 1; sec < n; sec++) {
    pii ran = getRange2(sec);
    pii l = pii(-1, -1);
    pii r = pii(-1, -1);
    if (0 <= ran.first - 1) l = getRange(arr[ran.first - 1], sec);
    if (ran.second + 1 < n) r = getRange(arr[ran.second + 1], sec);
    if (l.first != -1) {
      l.second = ran.first - 1;
      ll x = l.second - l.first + 1;
      ll y = ran.second - pos[sec] + 1;
      ans += x * y * sec;
    }
    if (r.first != -1) {
      r.first = ran.second + 1;
      ll x = r.second - r.first + 1;
      ll y = pos[sec] - ran.first + 1;
      ans += x * y * sec;
    }
  }
  cout << ans << '\n';
  return (0);
}

