	p[0] = inf;
	seg.st(0, inf);
	for (int i = 1; i <= N; i++) {
		ll P;
		cin >> P;
		seg.st(i,P);
		p[i] = P;
	}		
	seg.st(N+1, inf);
	p[N + 1] = inf;


	ll ans = 0;
	for (int i = 1; i <= N; i++) {
		ll l1, l2, r1, r2;
		int ok1 = 0, ng1 = i;
		while (ng1 - ok1 > 1) {
			int mid = (ng1+ok1) / 2;
			if (seg.get(mid, i - 1) > p[i])ok1 = mid;
			else ng1 = mid;
		}
		l1 = ok1;
		int ok2 = N+1, ng2 = i;
		while (ok2- ng2 > 1) {
			int mid = (ng2 + ok2) / 2;
			if (seg.get(i+1,mid) > p[i])ok2 = mid;
			else ng2 = mid;
		}
		r1 = ok2;

		if (l1 != 0) {
			int ok3 = 0, ng3 = l1;
			while (ng3 - ok3 > 1) {
				int mid = (ng3 + ok3) / 2;
				ll num = seg.get(mid,l1-1);
				if (num > p[i])ok3 = mid;
				else ng3 = mid;
			}
			l2 = ok3;
		}
		else l2 = 0;

		if (r1 != N + 1) {
			int ok4 = N + 1, ng4 = r1;
