        int cur=RMQ(mid,i-1);
        if(cur>arr[i])
        {
            f=cur;
            l=mid+1;
        }
        else
            r=mid-1;
    }
    return f;
}
int find_greater_R(int l,int r,int i)
{
    int f=0;
    while(l<=r)
    {
        int mid=(l+r)>>1;
        int cur=RMQ(i+1,mid);
        if(cur>arr[i])
        {
            f=cur;
            r=mid-1;
        }
        else
        {
            l=mid+1;
        }
    }
    return f;
}
ll l_side(int i)
{
    int a=find_greater_L(0,i-1,i);
    if(a)
    {
        int x=1,y=0,z=pos[a];
        int l=0,r=pos[a]-1;
        while(l<=r){
            int mid=(l+r)>>1;
            int cur=RMQ(mid,pos[a]-1);
            if(cur>arr[i]){
                l=mid+1;
            }
            else{
                z=mid;
                r=mid-1;
            }
        }
        x+=pos[a]-z;
        int b=find_greater_R(i+1,n-1,i);
        if(b)
        {
            y=pos[b]-i-1;
        }
        else
            y=(n-1)-i;
        int ans=x+x*y;
        return ans;
    }
    return 0;
}
ll r_side(int i)
{
    int a=find_greater_R(i+1,n-1,i);
    if(a)
    {
        int x=1,y=0,z=pos[a];
        int l=pos[a]+1,r=n-1;
        while(l<=r)
        {
            int mid=(l+r)>>1;
            int cur=RMQ(pos[a]+1,mid);
            if(cur>arr[i])
            {
                r=mid-1;
            }
            else
            {
                z=mid;
                l=mid+1;
            }
        }
        x+=z-pos[a];
        int b=find_greater_L(0,i-1,i);
        if(b)
            y=i-pos[b]-1;
        else
            y=i;
        int ans=x+x*y;
        return ans;
    }
    return 0;
}
