void add(int m,int x){
  m=m+n-1;
  bit[m]=make_pair(max(bit[m].first,x),max(min(bit[m].first,x),bit[m].second));
  while(m>0){
    m=(m-1)/2;
    bit[m]=make_pair(max(bit[m].first,x),max(min(bit[m].first,x),bit[m].second));
  }
}

P query(int a,int b,int k,int l,int r){
  if(r<=a || b<=l)return make_pair(0,0);
  if(a<=l && r<=b){
   // printf("(%d,%d)+",l,r);
    return bit[k];
  }

  else{
    P vl = query(a,b,2*k+1,l,(l+r)/2);
    P vr = query(a,b,2*k+2,(l+r)/2,r);
    int vlf = vl.first , vls=vl.second;
    int vrf = vr.first , vrs=vr.second;    
    return make_pair(
      max( vlf ,vrf ),
      max( min(vlf,vrf) ,max(vls,vrs) )
    );
  }
}

