void body() {
    auto N = read<i64>();
    auto Ps_ = read<i64>(N);
    auto Ps = Vector<pair<i64, i64>>(N);
    REP (i, N) {
        Ps[i] = {i, Ps_[i]};
    }
    sort(CTR(Ps), [](auto rhs, auto lhs) { return rhs.second > lhs.second; });

    auto fin = OrderedSet<i64>();
    fin.insert(-1);
    fin.insert(N);
    i64 ans = 0;
    EACH (elem, Ps) {
        auto i = elem.first;
        auto P = elem.second;
        auto it = fin.lower_bound(i); // index >= iを満たす最小のindex
        auto it2 = it;
        auto j0 = *it;
        it++;
        auto j1 = (it == fin.end()) ? N : *it;
        if (it2 != fin.begin()) it2--;
        auto k1 = *it2;
        if (it2 != fin.begin()) it2--;
        auto k0 = *it2;

        /*
         * k0 ... k1 ... i ... j0 ... j1
         */
        ans += (k1 - k0) * (j0 - i) * P;
        ans += (i - k1) * (j1 - j0) * P;
        fin.insert(i);
    }
    cout << ans << endl;
}

