typedef long long int ll;
const ll INF = 10241024;
int N;
vector<int> P(1e5+1);
void input(){
  	cin >> N;
    rep(i,N){
        cin >> P[i];
        //cout << P[i] << endl;
    }
}

void solve(){
    input();
    int ans = 0;

    for(int l=0;l<N-1;l++){
        int fir = max(P[l], P[l+1]);
        int sec = min(P[l], P[l+1]);

        if(l == N - 2 ){
            ans += sec;
          	//cout << "a" << endl;
          	//cout << sec << endl;
            break;
        }
        for(int r=l+1;r<N;r++){
            if(sec < P[r] && P[r] < fir){
                sec = P[r];
            }
            else if(fir < P[r]){
                sec = P[r];
                swap(sec, fir);
            }
            ans += sec;

        }
    }

    cout << ans << endl;
    return;
}
int main () {
    solve();
    return 0;
}

