void E_Second_Sum(void) {

	int N; cin >> N;
	vector<int> P(N); for (int& it : P)cin >> it;

	long long sum = 0;
	for (int index = 0; index < N; index++) {
		int leftMax = -1, leftMin = -1;
		for (int left = index - 1; left >= 0; left--) {
			if (P[left] > P[index]) {
				if (leftMin == -1) {
					leftMin = left;
				}
				else {
					leftMax = left;
					break;
				}
			}
		}
		int rightMax = N, rightMin = N;
		for (int right = index + 1; right < N; right++) {
			if (P[right] > P[index]) {
				if (rightMin == N) {
					rightMin = right;
				}
				else {
					rightMax = right;
					break;
				}
			}
		}
		sum += (long long(leftMin - leftMax) * long long(rightMin - index)) * (long long)P[index];
		sum += (long long(index - leftMin) * long long(rightMax - rightMin)) * (long long)P[index];
	}

	cout << sum << flush;
	return;
}

