int f1[100005],g1[100005],f2[100005],g2[100005];
int n,a[100005],maxx[25][100005],lg2[100005];
ll ans;
int ask(int l,int r)
{
	if(l>r)return 0;
	int d=lg2[r-l+1];
	return max(maxx[d][l],maxx[d][r-(1<<d)+1]);
}
int main()
{
	scanf("%d",&n);
	for(int i=2;i<=n;i++)lg2[i]=lg2[i>>1]+1;
	for(int i=1;i<=n;i++)
	{
		scanf("%d",&a[i]);
		maxx[0][i]=a[i];
	}
	for(int i=1;i<=lg2[n];i++)
	  for(int j=1;j<=n;j++)
	    maxx[i][j]=max(maxx[i-1][j],maxx[i-1][j+(1<<(i-1))]);
	for(int i=1;i<=n;i++)
	{
		f1[i]=i-1;
		while(a[f1[i]]<a[i]&&f1[i])f1[i]=f1[f1[i]];
	}
	for(int i=n;i>=1;i--)
	{
		g1[i]=i+1;
		while(a[g1[i]]<a[i]&&g1[i]<=n)g1[i]=g1[g1[i]];
	}
	for(int i=1;i<=n;i++)
	{
		int l=1,r=f1[i]-1;
		while(l<=r)
		{
			int mid=(l+r)>>1;
			if(ask(mid,f1[i]-1)>a[i])l=mid+1;
			else r=mid-1;
		}
		f2[i]=r;
