		l=g1[i]+1,r=n;
		while(l<=r)
		{
			int mid=(l+r)>>1;
			if(ask(g1[i]+1,mid)>a[i])r=mid-1;
			else l=mid+1;
		}
		g2[i]=l;
		g2[i]=min(g2[i],n+1);
		ans+=1ll*a[i]*(1ll*(i-f1[i])*(g2[i]-g1[i])+1ll*(f1[i]-f2[i])*(g1[i]-i));
	}
	printf("%lld\n",ans);
