using namespace std;

int X(vector<int> &P, int L, int R) {
	int l = P.at(L+1);
	int sl = P.at(L);
	if (P.at(L) > P.at(L+1)) {
		l = P.at(L);
		sl = P.at(L+1);
	}

	for (int i = L; i <= R; i++) {
		if (P.at(i) > l) {
			sl = l;
			l = P.at(i);
		} else if (P.at(i) > sl && P.at(i) < l) {
			sl = P.at(i);
		}
	}

	return sl;
}

int main() {
	int anz;
	cin >> anz;
	vector <int> P;
	P.resize(anz);
	for (int i = 0; i < anz; i++) {
