{
	cin >> n;
	vec = new type[n];
	type * const start = vec;
	type * const end = vec + n;
	for (type * i = start; i < end; i++)
		scanf("%lld", i);
	func(start, end);
	cout << ans;
	//system("pause");
	return 0;
}

