template <class T>inline T updmax(T& a, T b) {return a = max(a, b);}
template <class T>inline T updmin(T& a, T b) {return a = min(a, b);}

//0-indexed
template <class T>
class SegmentTree
{
	int size;
	T def;
	vector<T> data;
	function<T(T, T)> f;

public:
	SegmentTree<T>(int _size, T _def, function<T(T, T)> _f) : f(_f), def(_def), size(1)
	{
		while (size < _size)
			size <<= 1;
		data = vector<T>(size * 2, def);
	}
	//bottom-up implementation
	//query for[l, r)
	T query(int l, int r)
	{
		T L = def, R = def;
		for (l += size, r += size; l < r; l >>= 1, r >>= 1)
		{
			if (l & 1)
				L = f(L, data[l++]);
			if (r & 1)
				R = f(data[--r], R);
		}
		return f(L, R);
	}
	void update(int idx, T val)
	{
		idx += size;
		data[idx] = val;
		while (idx > 1)
		{
			idx >>= 1;
			data[idx] = f(data[2 * idx], data[2 * idx + 1]);
		}
	}
	T operator[](int idx)
	{
		return data[idx + size];
	}
};


class Solution {
public:
	int f(SegmentTree<int> &st, int v, int l, int r){
		if(st.query(l,r) < v)return -1;
		while(r-l > 1){
			int mid = (r+l)/2;
			int x = st.query(mid, r);
			if(x < v)r = mid;
			else l = mid;
		}
		return l;
	}
	void solve() {
		int n;
		cin >> n;
		vector<int> a(n, 0), idx(n, 0);
		for(int i=0; i<n; i++)cin >> a[i];
		for(int i=0; i < n; i++)a[i]--;
		for(int i=0; i < n; i++)idx[a[i]] = i;
		SegmentTree<int> st(n, -1, [](int a, int b){return max(a, b);});
		for(int i=0; i < n; i++)st.update(i, a[i]);
		long long ret = 0;
		for (long long i = n - 1; i >= 0; i--){
			long long k = idx[i];
			long long l1 = f(st, i, 0, k);
			long long l2 = (l1 == -1)?-1:f(st, i, 0, l1);
			long long r1 = f(st, i, k+1, n);
			long long r2 = (r1 == -1)?-1:f(st, i, r1+1, n);
			if(r1 == -1)r1 = n;
			if(r2 == -1)r2 = n;
			if(l1 == -1 && r1 == n)continue;
			else if(l1 == -1) ret += (i+1) * (r2-r1) * (k+1);
			else if(r1 == n) ret += (i+1) * (l1-l2) * (n-k);
			else ret += (i+1) * (r2-r1) * (l1-l2);			
		}
		cout << ret << "\n";

		return;
	};
};

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	Solution solution;
	solution.solve();
	return 0;
}

