struct Max2
{
    int Max{0};
    int SecondMax{0};
};

long long
SolveSecondSum(const std::vector<int> &inputs)
{
    long long sum = 0;

    std::vector<Max2> max2List;
    max2List.resize(inputs.size());

    for (std::size_t currentIndex=0; currentIndex<inputs.size(); ++currentIndex)
    {
        auto &input = inputs[currentIndex];

        for (std::size_t index=0; index<currentIndex; ++index)
        {
            auto &max2 = max2List[index];
            if (input>max2.Max)
            {
                max2.SecondMax = max2.Max;
                max2.Max = input;
            }
            else if (input>max2.SecondMax)
            {
                max2.SecondMax = input;
            }
            sum += max2.SecondMax;
        }

        max2List[currentIndex].Max = input;
    }

    return sum;
}

}

