#define mp(a,b) make_pair(a,b)

const int MOD = 1000 * 1000 * 1000 + 7;

bool res() {
	int n;
	cin >> n;
	if (!cin) return false;

	vi v(n);
	for (int i = 0; i < n; ++i) cin >> v[i];

	vii primero, segundo;

	ll sol = 0;
	ll sumaseg;

	ll sumaSegElemsTot = 0; 
	for (int i = 1; i < n; ++i) {
		int cont = primero.size() - 1;
		int sumaElems = 0;
		vii segundosElementos;

		//Actualizamos los primeros elementos del Xlr
		while (cont >= 0 && primero[cont].first <= v[i]) {
			ii par = primero[cont];
			sumaElems += par.second;
			primero.pop_back();

			segundosElementos.push_back(par);
			--cont;
		}

		if(sumaElems > 0) primero.push_back(mp(v[i], sumaElems));
		//Primeros elementos Gucci

		cont = segundo.size() - 1;
		//int sumaElems2 = 0;
		int sum = 0;
		ii ultpar;

		//Actualizamos los segundos elementos de los pares que tienen como primer elemento al que acabamos de meter
		while (cont >= 0 && sum < sumaElems) {
			ultpar = segundo[cont];
			segundo.pop_back();
			sumaSegElemsTot -= ultpar.first * ultpar.second;

			if (sum + ultpar.second > sumaElems) {
				sum += ultpar.second;
				ultpar.second -= sumaElems - sum;
			}
			else {
				sum += ultpar.second;
				ultpar.second = 0;
			}
			--cont;
		}

		//METER EL ULTIMO PAR EN CASO DE SER NECESARIO
		//
		//
		//
		//
		if (ultpar.second > 0) segundo.push_back(ultpar);

		int sumaElems3 = 0;

		//Actualizamos los segundos valores de los pares que tienen como segundo valor el valor recién introducido
		while (cont >= 0 && segundo[cont].first <= v[i]) {
			ii par = segundo[cont];
			sumaElems3 += par.second;
			sumaSegElemsTot -= par.first * par.second;

			segundo.pop_back();
			--cont;
		}
		if (sumaElems3 > 0) segundo.push_back(mp(v[i], sumaElems3));
		sumaSegElemsTot += v[i] * sumaElems3;

		//Meter segundos elementos
		for (int i = segundosElementos.size() - 1; i >= 0; --i) {
			segundo.push_back(segundosElementos[i]);
			sumaSegElemsTot += segundosElementos[i].first * segundosElementos[i].second;
		}

		primero.push_back(make_pair(max(v[i], v[i - 1]), 1));
		segundo.push_back(make_pair(min(v[i], v[i - 1]), 1));

		//Actualizar sumaSegElemsTot
		sumaSegElemsTot += min(v[i], v[i - 1]);

		sol += sumaSegElemsTot;
	}

	cout << sol << '\n';

	return true;
}

int main() {
	while (res()) {}
	return 0;
}

