vector<int> mrg(vector<int> a, vector<int> b, bool bo) {
	for(int i = 0; i < b.size(); ++i) a.push_back(b[i]);
	sort(a.begin(), a.end());
	if(bo == 0) {
		a.pop_back();
		a.pop_back();
		return a;
	} else {
		b.clear();
		b.push_back(a[3]);
		b.push_back(a[2]);
		return b;
	}
}

struct dor {
	vector<int> mn, mx;
	dor *l, *r;
	dor() {
		mn.resize(2, 1e9);
		mx.resize(2, 0);
		l = r = NULL;
	}

	void pump() {
		if(l == NULL) l = new dor();
		if(r == NULL) r = new dor();
		mn = mrg(l->mn, r->mn, 0);
		mx = mrg(l->mx, r->mx, 1);
	}

	void mims(int ms) {
		mn[0] = mx[0] = ms;
	}
} *root;

void gnk(int l, int r, int si, int ms, dor *&t) {
	if(t == NULL) t = new dor();
	if(l == r) {
		t->mims(ms);
		return;
	}
	if((l + r) / 2 >= si) gnk(l, (l + r) / 2, si, ms, t->l);
	else gnk((l + r) / 2 + 1, r, si, ms, t->r);
	t->pump();
}

pair<int, int> dbr(int l, int r, int sl, int sr, dor *&t, bool bo) {
	if(l > sr || r < sl || t == NULL) {
		if(bo) return {0, 0};
		else return {1e9, 1e9};
	}
	if(l >= sl && r <= sr) {
		if(bo) return {t->mx[0], t->mx[1]};
		else return {t->mn[0], t->mn[1]};
	}
	pair<int, int> Pa = dbr(l, (l + r) / 2, sl, sr, t->l, bo);
	pair<int, int> Pb = dbr((l + r) / 2 + 1, r, sl, sr, t->r, bo);
	vector<int> Ta;
	Ta.resize(2, Pa.first);
	Ta[1] = Pa.second;
	vector<int> Tb;
	Tb.resize(2, Pb.first);
	Tb[1] = Pb.second;
	vector<int> Tv = mrg(Ta, Tb, bo);
	return make_pair(Tv[0], Tv[1]);
}

