    for(int i = 1; i <= n; ++i) {
    	cin >> p[i];
	}
	for(int i = 1; i <= n; ++i) {
		rp = dbr(1, n, p[i], n, root, 1);
		gnk(1, n, p[i], i, root);
		a[i][0][0] = rp.first;
		a[i][0][1] = rp.second;
	}
	root = NULL;
	for(int i = n; i >= 1; --i) {
		rp = dbr(1, n, p[i], n, root, 0);
