    {
        second[i] = n + 1;
        secondsecond[i] = n + 1;
    }
    for (int i = 1; i <= n; i++)
    {
        cin >> arr[i];
        ind[arr[i]] = i;
    }
    int ans = 0;
    set <int> mx, mn;
    for (int i = n; i >= 1; i--)
    {
        if (!mx.empty() && *mx.rbegin() > ind[i])
        {
            int val = *mx.lower_bound(ind[i]);
            second[ind[i]] = val;
            if (*mx.rbegin() != val)
            {
                val = *mx.lower_bound(val + 1);
                secondsecond[ind[i]] = val;
            }
        }
        if (!mn.empty() && *mn.rbegin() > -ind[i])
        {
            int val = *mn.lower_bound(-ind[i]);
            first[ind[i]] = -val;
            if (*mn.rbegin() != val)
            {
                val = *mn.lower_bound(val + 1);
                firstfirst[ind[i]] = -val;
            }
        }
        mx.insert(ind[i]);
        mn.insert(-ind[i]);
    }
    for (int i = 1; i <= n; i++)
    {
        int cnt = 0;
        for (int j = i - 1 ; j >= 1; j--)
        {
            if (arr[j] > arr[i])
            {
                cnt++;
                if (cnt == 1)
                    first[i] = j;
                if (cnt == 2)
                    firstfirst[i] = j;
            }
        }
        cnt = 0;
        for (int j = i + 1; j <= n; j++)
        {
            if (arr[j] > arr[i])
            {
                cnt++;
                if (cnt == 1)
                    second[i] = j;
                if (cnt == 2)
                    secondsecond[i] = j;
            }
        }
        if (arr[i] == n)
        {
            continue;
        }

        int flexxx = 0;
        if (second[i] != n + 1)
        {
            flexxx += (secondsecond[i] - second[i]) * (i - first[i]);
        }
        if (first[i] != 0)
        {
            flexxx += (first[i] - firstfirst[i]) * (second[i] - i);
        }
        ans += flexxx * arr[i];
    }
    cout << ans;
    return 0;
}

