class Segtree {
public:
    int n;
    vector<int> nodes;
    Segtree(int _n) {
        n = 1 << (int)ceil(log2(_n));
        nodes.resize(n*2-1, -INT_MAX);
    }
    void set(int i, int v) {
        i += n - 1;
        nodes[i] = v;
        while (i > 0) {
            i = (i-1) / 2;
            nodes[i] = max(nodes[i*2+1], nodes[i*2+2]);
        }
    }
    int get_max(int l, int r) {
        return get_max(l, r, 0, 0, n);
    }
    int get_max(int l, int r, int i, int tl, int tr) {
        if (tr <= l || r <= tl) return -INT_MAX;
        if (l <= tl && tr <= r) return nodes[i];
        int t1 = get_max(l, r, i*2+1, tl, (tl+tr)/2);
        int t2 = get_max(l, r, i*2+2, (tl+tr)/2, tr);
        return max(t1, t2);
    }
};

int ps[100010][4];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int N;
    cin >> N;
    vector<int> P(N);
    for (int i=0; i<N; ++i) {
        cin >> P[i];
    }

    Segtree tr1(N+1);
    for (int i=0; i<N; ++i) {
        int j = tr1.get_max(P[i]+1, N+1);
        if (j == -INT_MAX) {
            ps[i][0] = ps[i][1] = -1;
        } else {
            ps[i][1] = j;
            tr1.set(P[j], -INT_MAX);
            int k = tr1.get_max(P[i]+1, N+1);
            ps[i][0] = (k == -INT_MAX ? -1 : k);
            tr1.set(P[j], j);
        }
        tr1.set(P[i], i);
    }

    Segtree tr2(N+1);
    for (int i=N-1; i>=0; --i) {
        int j = tr2.get_max(P[i]+1, N+1);
        if (j == -INT_MAX) {
            ps[i][2] = ps[i][3] = N;
        } else {
            ps[i][2] = -j;
            tr2.set(P[-j], -INT_MAX);
            int k = tr2.get_max(P[i]+1, N+1);
            ps[i][3] = (k == -INT_MAX ? N : -k);
            tr2.set(P[-j], j);
        }
        tr2.set(P[i], -i);
    }

    long long res = 0;
    for (int i=0; i<N; ++i) {
        if (ps[i][1] == -1 && ps[i][2] == N) continue;
        if (ps[i][1] != -1) {
            long long l = (long long)(ps[i][2] - i) * (ps[i][1] - ps[i][0]);
            res += (long long)P[i] * l;
        }
        if (ps[i][2] != N) {
            long long r = (long long)(i - ps[i][1]) * (ps[i][3] - ps[i][2]);
            res += (long long)P[i] * r;
        }
    }
    cout << res << endl;

    return 0;
}

