void solve(void)
{
  int N; cin >> N;

  std::multiset<int> S{};
  S.emplace(0);
  S.emplace(0);
  S.emplace(N + 1);
  S.emplace(N + 1);
  vector<int> P(N+1);
  for(int i = 0; i < N; ++i)
  {
    int p; cin >> p;
    P[p] = i + 1; 
  }

  ull ans{};
  for(int i = N; i > 0; --i)
  {
    auto index = P[i];
    auto it = boost::lower_bound(S, index);
    auto x = std::prev(it);
    auto w = std::prev(x);
    auto y = it;
    auto z = std::next(y);
    auto r = (*x - *w) * (*y - index) + (index - *x) * (*z - *y);
    ans += (ull)(r * i);
    S.emplace(index);
  }

  cout << ans << CRLF;
  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

