const int MIN = -2147483647;

using type = long long;

using namespace std;

type * vec;
int n;
long long ans = 0;

type * m_find_max(type * start, type * end)
{
	int max = MIN;
	type * numb = nullptr;
	for (type * i = start; i < end; i++)
		if (max < *i) max = *i, numb = i;
	return numb;
}

void m_find_two_max(type * start, type * end, type *& max, type *& tax)
{
	int mm = MIN, mt = MIN;
	for (type * i = start; i < end; i++)
	{
		if (*i > mm)
		{
			mt = mm;
			mm = *i;
			tax = max;
			max = i;
		}
		else if (*i > mt)
		{
			mt = *i;
			tax = i;
		}
	}
}

void m_find_tax(type * start, type * end, type * max, type *& tax)
{
	int mm = *max, mt = MIN;
	for (type * i = start; i < end; i++)
		if (*i > mt)
			if (i != max)
			{
				tax = i;
				mt = *i;
			}
}

void fu(type * start, type * end, type * max)
{
	if (end - start == 1)
		return;
	type * tax = 0;
	m_find_tax(start, end, max, tax);
	if (tax == max)
		return;
	if (tax > max)
	{
		ans += (*tax) * (max - start + 1) * (end - tax);
		fu(start, tax, max);
	}
	else
	{
		ans += (*tax) * (tax - start + 1) * (end - max);
		fu(tax + 1, end, max);
	}
	return;
}

void func(type * start, type * end)
{
	if (end - start <= 1)
		return;
	if (end - start == 2)
	{
		ans += min(*(end - 1), *start);
		return;
	}

	type * max = m_find_max(start, end);

	fu(start, end, max);

	func(start, max);
	func(max + 1, end);
	return;
}

int main()
{
	cin >> n;
	vec = new type[n];
	type * const beg = vec;
	type * const end = vec + n;
	for (type * i = beg; i < end; i++)
		cin >> *i;

	func(beg, end);

	//cout << ans;
	cout << endl << ans << endl;
	system("pause");
	return 0;
}

