int main(){
    int n;
    cin >> n;
    vector<int> a(100000+2);
    vector<int> d(100000+2);
    for(int i=0; i<n; i++){
        cin >> a[i];
        d[a[i]] = i;
    }
    d[100001] = 100001;
    vector<int> r(100000+2,100001);
    vector<int> r2(100000+2,100001);
    vector<int> l(100000+2,100001);
    vector<int> l2(100000+2,100001);
    priority_queue<int,vector<int>,greater<int>> qr;
    priority_queue<int,vector<int>,greater<int>> qr2;
    priority_queue<int,vector<int>,greater<int>> ql;
    priority_queue<int,vector<int>,greater<int>> ql2;

    qr.push(a[0]);
    ql.push(a[n-1]);
    int t;
    for(int i=1; i<n; i++){
        while(qr2.size()>0 and qr2.top()<a[i]){
            t = qr2.top();
            qr2.pop();
            r2[t] = a[i];
        }
        while(qr.size()>0 and qr.top()<a[i]){
            t = qr.top();
            qr.pop();
            r[t] = a[i];
            qr2.push(t);
        }
        qr.push(a[i]);

        while(ql2.size()>0 and ql2.top()<a[n-1-i]){
            t = ql2.top();
            ql2.pop();
            l2[t] = a[n-1-i];
        }
        while(ql.size()>0 and ql.top()<a[n-1-i]){
            t = ql.top();
            ql.pop();
            l[t] = a[n-1-i];
            ql2.push(t);
        }
        ql.push(a[n-1-i]);
    }

    int dl1, dl2, dr1, dr2;
    int ans = 0;
    for(int i=0; i<n; i++){
        dl1 = d[l[a[i]]];
        dl2 = d[l2[a[i]]];
        if(dl1==100001){
            dl1 = -1;
        }
        if(dl2==100001){
            dl2 = -1;
        }
        dr1 = min(d[r[a[i]]], n);
        dr2 = min(d[r2[a[i]]], n);
        ans += ((dl1-dl2) * (dr1-i))*a[i];
        ans += ((dr2-dr1) * (i-dl1))*a[i];
    }
    cout << ans << endl;
}

