int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	cout << fixed << setprecision(12);

	ll n; cin >> n;
	vll p(n); cin >> p;
	segment_tree<M::max_indexed_t<>> seg(n);
	segment_tree<M::min_indexed_t<>> seg_min(n);

	rep(i, 0, n) {
		seg.update(i, { -INF,i });
		seg_min.update(i, { INF,i });
	}
	ll res = 0;
	vll ord(n); iota(all(ord), 0);
	sort(all(ord), [&](ll l, ll r) {return p[l] > p[r]; });
	rep(ind, 0, n) {
		ll i = ord[ind];
		if (ind == 0)
		{
			seg.update( i,{i,i} );
			seg_min.update(i, { i,i });
			continue;
		}
		ll left_len=0, left_len2=0;
		auto left = seg.query(0, i+1);
		if (left.first != -INF) {
			left_len = i- left.second;
			if (left.second > 0) {
				auto left2 = seg.query(0, left.second);
				if (left2.first != -INF) {
					left_len2 = left.second - left2.second;
				}
				else {
					left_len2 = left.second + 1;
				}
			}
			else {
				left_len2 = 1;
			}
		}
		else {
			left_len = i + 1;
			left_len2 = 0;
		}
		auto right = seg_min.query(i, n);
		ll right_len=0, right_len2 = 0;
		if (right.first != INF) {
			right_len = right.second - i;
			if (right.second < n - 1) {
				auto right2 = seg_min.query(right.second + 1, n);
				if (right2.first != INF) {
					right_len2 = right2.second - right.second;
				}
				else {
					right_len2 = n - right.second ;
				}
			}
			else {
				right_len2 = 1;
			}
		}
		else {
			right_len = n - i ;
		}
		seg.update(i, { i,i });
		seg_min.update(i, { i,i });
		res += (n-ind)*left_len * right_len2;
		res += (n - ind) * left_len2 * right_len;
	}
	write(res,'\n');

	return 0;
}

