int firstAtLeast(int L, int R, int K){ /// first index in range [L,R] where value>=K
    if (R < L) return -1;
    int node = L+n-1;
    while(t[node] < K){
        while( (node&1) == 1 ){
            node = node>>1;
            if (node <= 1) return -1;
        }
        ++node;
    }
    while(node < n) {
       node <<= 1;
       if (t[node] < K) ++node;
    }
    int index = node-(n-1);
    return (index <= R ? index : -1);
}
int lastAtLeast(int L, int R, int K){ /// last index in range [L,R] where value>=K
    if (R < L) return arr_siz+1;
    int node = R+n-1;
    while(t[node] < K){
        while( (node&1) == 0 ) {
            node = node>>1;
            if (node <= 1) return -1;
        }       
        --node;
    }
    while(node < n) {
       node = (node<<1)|1;
       if (t[node] < K) --node;
    }
    int index = node-(n-1);
    return (index >= L ? index : -1);
}
