#define FOR0(var, max) for (ui var = 0; var < max; ++var)
#define FORINV(var, min, max) for (ui (var) = (max) - 1; (var) + 1 > (min); --(var))

using namespace std;

using ui = unsigned int;
using uc = unsigned char;

const static ui NMAX = 100000;
static ui N;
static ui Pi[2*NMAX];
static ui Pi_inv[2*NMAX];

ui solve(void) {
  ui res = 0;
  multiset<ui> all;

  all.insert(0);
  all.insert(0);
  all.insert(N + 1);
  all.insert(N + 1);

  FORINV(P, 1, N + 1) {
    ui i = Pi_inv[P] + 1;

    auto it = all.lower_bound(i);
    ui wi = *prev(it, 2);
    ui xi = *prev(it, 1);
    ui yi = *it;
    ui zi = *next(it);

    auto Ci = (xi - wi) * (yi - i) + (i - xi) * (zi - yi);
    res += P * Ci;
    all.insert(i);
  }

  return res;
}

int main(int ac, char **av) {
  cin >> N;
  FOR0(i, N) {
    cin >> Pi[i];
    Pi_inv[Pi[i]] = i;
  }
  cout << solve() << endl;
  return 0;
}

