struct Set{
    ll a, b;
    void insert(ll x){
        if(b > x)b = x;
        if(a > b)swap(a, b);
    }
};

Set t[400010];

void modify(ll v, ll tl, ll tr, ll pos, ll val){
    t[v].insert(val);
    if(tl != tr){
        ll tm = (tl + tr) >> 1;
        if(pos <= tm)modify(v << 1, tl, tm, pos, val);
        else modify((v << 1) + 1, tm + 1, tr, pos, val);
    }
}

Set Ans;

void get(ll v, ll tl, ll tr, ll l, ll r){
    if(l > r)return;
    if(tl == l && tr == r){
        Ans.insert(t[v].a);
        Ans.insert(t[v].b);
        return;
    }
    ll tm = (tl + tr) >> 1;
    get(v << 1, tl, tm, l, min(r, tm));
    get((v << 1) + 1, tm + 1, tr, max(l, tm + 1), r);
}

int main(){
    ios_base :: sync_with_stdio(0);
    cin.tie(0);

    ll n;
    cin >> n;

    for(int i = 0; i < 400010; i++)t[i].a = t[i].b = n + 1;

    vector <ll> a(n + 1);
    vector <Set> l(n + 1), r(n + 1);

    for(int i = 1; i <= n; i++){
        cin >> a[i];
        modify(1, 1, n, a[i], -i);
        Ans.a = n + 1;
        Ans.b = n + 1;
        get(1, 1, n, a[i] + 1, n);
        l[i] = Ans;
    }

    for(int i = 0; i < 400010; i++)t[i].a = t[i].b = n + 1;

    for(int i = n; i > 0; i--){
        modify(1, 1, n, a[i], i);
        Ans.a = n + 1;
        Ans.b = n + 1;
        get(1, 1 ,n, a[i] + 1, n);
        r[i] = Ans;
    }

    ll ans = 0;

    for(int i = 1; i <= n; i++){
        l[i].a *= -1;
        l[i].b *= -1;
        l[i].a = max(l[i].a, 0ll);
        l[i].b = max(l[i].b, 0ll);
        ans += a[i] * (l[i].a - l[i].b) * (r[i].a - i);
        ans += a[i] * (-r[i].a + r[i].b) * (-l[i].a + i);

    }

    cout << ans << "\n";

    return 0;
}

