const int N=300005;
int n,a[N],st[N],L[N],R[N],top;
LL ans;bool TP;
int t[N*8];
void build(int p,int l,int r)
{
  if(l==r) {t[p]=a[l];return;}
  int mid=(l+r)>>1,L=(p<<1),R=L|1;
  build(L,l,mid);build(R,mid+1,r);
  t[p]=max(t[L],t[R]);
}
int ND,ax;
void into(int p,int l,int r)
{
  if(l==r) {ax=l;return;}
  int mid=(l+r)>>1,L=(p<<1),R=L|1;
  if(!TP)
    {
      if(t[R]>ND) into(R,mid+1,r);
      else into(L,l,mid);
    }
  else
    {
      if(t[L]>ND) into(L,l,mid);
      else into(R,mid+1,r);
    }
}
bool ASK(int p,int l,int r,int nl,int nr)
{
  if(l==nl&&r==nr)
    {
      if(t[p]>ND) {into(p,l,r);return 1;}
      return 0;
    }
  int mid=(l+r)>>1,L=(p<<1),R=L|1;
  if(nr<=mid) return ASK(L,l,mid,nl,nr);
  if(nl>mid) return ASK(R,mid+1,r,nl,nr);
  if(!TP)
    {
      if(ASK(R,mid+1,r,mid+1,nr)) return 1;
      if(ASK(L,l,mid,nl,mid)) return 1;
    }
  else
    {
      if(ASK(L,l,mid,nl,mid)) return 1;
      if(ASK(R,mid+1,r,mid+1,nr)) return 1;
    }
  return 0;
}
