long long n;
vector<long long> p, id, lmemo[2], rmemo[2];

long long solve();

int main() {
  cin >> n;
  p.resize(n);
  for(int i = 0; i < n; ++i) cin >> p[i];
  cout << solve() << endl;
  return 0;
}

long long solve() {
  long long ans = 0;
  id.resize(n);
  for(int i = 0; i < n; ++i) id[p[i] - 1] = i;
  for(int i = 0; i < 2; ++i) {
    lmemo[i].assign(n, -1);
    rmemo[i].assign(n, n);
  }
  set<int> str;
  set<int, greater<int>> stl;
  stl.insert(-1);
  str.insert(n);
  for(int i = 0; i < n; ++i) {
    int now = id[n - 1 - i];
    auto rid = str.upper_bound(now);
    rmemo[0][now] = *rid;
    rid = str.upper_bound(*rid);
    if(rid != str.end()) rmemo[1][now] = *rid;
    auto lid = stl.upper_bound(now);
    lmemo[0][now] = *lid;
    lid = stl.upper_bound(*lid);
    if(lid != stl.end()) lmemo[1][now] = *lid;

    str.insert(now);
    stl.insert(now);
  }
  for(int i = 0; i < n; ++i) {
    long long now = 0;
    now += (rmemo[0][i] - i) * (lmemo[0][i] - lmemo[1][i]);
    now += (rmemo[1][i] - rmemo[0][i]) * (i - lmemo[0][i]);
    ans += now * p[i];
  }
  return ans;
}

