int main() {
	int n; reader(n);
	vector<int> a(n);
	FOR(i, n) reader(a[i]);
	set<int> st;
	vector<Pii> vp;
	FOR(i, n) {
		vp.emplace_back(a[i], i);
	}

	ll ans = 0;
	sort(vp.rbegin(), vp.rend());
	for (auto& kv : vp) {
		int cur = kv.first;
		int idx = kv.second;
		auto it = st.lower_bound(idx);
		// left
		int l1 = -1, l2 = -1;
		{
			if (it != st.begin()) {
				l1 = *prev(it);
				auto pv = prev(it);
				if (pv != st.begin()) l2 = *prev(pv);
			}
		}
		int r1 = n, r2 = n;
		{
			if (it != st.end()) {
				r1 = *it;
				auto nt = next(it);
				if (nt != st.end()) r2 = *nt;
			}
		}
		l1 = (idx) - (l1);
		l2 = (idx) - (l2);
		r1 = (r1) - (idx);
		r2 = (r2) - (idx);

		ll x1 = l1 * ll(r2 - r1);
		ll x2 = ll(l2 - l1) * r1;

		ll cnt = x1 + x2;
		ans += cnt * cur;

		st.insert(kv.second);
	}
	writerLn(ans);

	return 0;
}

