template <class T> using reversed_priority_queue = priority_queue<T, vector<T>, greater<T> >;

template <class T> struct FenwickTree {

    vector < T > node;
    FenwickTree (int n) : node(n, 0) {}

    void add(int idx, T val) {
        for (int i = idx; i < node.size(); i |= i + 1) {
            node[i] += val;
        }
    }

    void update(int idx, T val) {
        add(idx, -sum(idx, idx + 1));
        add(idx, val);
    }

    T sum(int idx) {
        T ret = 0;
        for (int i = idx - 1; i >= 0; i = (i & (i + 1)) - 1) {
            ret += node[i];
        }
        return ret;
    }

    T sum(int l, int r) {
        return sum(r) - sum(l);
    }

};

int main ()
{
    int N; cin >> N;
    vector < int > P(N);
    REP(i,N) cin >> P[i];

    FenwickTree < ll > inst(100010);
    inst.add(0, 2);
    inst.add(N + 1, 2);

    ll ans = 0;
    for (int i = 0; i < N; i++) {
        ll l1 = -1, r1 = i;
        while (r1 - l1 > 1) {
            ll mid = (l1 + r1) / 2;
            if (inst.sum(mid, i + 1) == 0) {
                r1 = mid;
            } else {
                l1 = mid;
            }
        }
        ll l2 = -1, r2 = i;
        while (r2 - l2 > 1) {
            ll mid = (l2 + r2) / 2;
            if (inst.sum(mid, i + 1) == 1) {
                r2 = mid;
            } else {
                l2 = mid;
            }
        }
        ll l3 = i, r3 = N + 2;
        while (r3 - l3 > 1) {
            ll mid = (l3 + r3) / 2;
            if (inst.sum(i, mid + 1) == 0) {
                l3 = mid;
            } else {
                r3 = mid;
            }
        }
        ll l4 = i, r4 = N + 2;
        while (r4 - l4 > 1) {
            ll mid = (l4 + r4) / 2;
            if (inst.sum(i, mid + 1) == 1) {
                l4 = mid;
            } else {
                r4 = mid;
            }
        }

        ll t1 = (r1 - r2 + 1) * (l3 - i + 1LL);
        ans += t1;
