void Magic(){

	a[n+1] = MAXN;
	Lmin[0] = 0;
    Rmin[n] = n+1;

    for (int i=1; i<=n; ++i)
        if ( a[i] < a[i-1] ) Lmin[i] = i-1;
        else {
            int x = Lmin[i-1];
            while( a[x] < a[i] && x)
                x = Lmin[x];
            Lmin[i] = x;
        }

    for (int i=n-1; i; --i)
        if ( a[i] < a[i+1] ) Rmin[i] = i+1;
        else {
            int x = Rmin[i+1];
            while( a[x] < a[i] && x <= n)
                x = Rmin[x];
            Rmin[i] = x;
        }
}

void Solve(){

	LL ans = 0;
    for (int i=1; i<=n; ++i) {
        int cnt = 0,
            l = Lmin[i],
            r = Rmin[i];
