              dp[i][j].second = p.at(i-1);
            }else{
              dp[i][j].first = p.at(i-1);
              dp[i][j].second = dp[i+1][j].second;
            }
          }else{
              dp[i][j].first = dp[i+1][j].first;
              dp[i][j].second = dp[i+1][j].second;
          }
        }else{
          dp[i][j] = P(min(p.at(i-1),p.at(j-1)), max(p.at(i-1),p.at(j-1)));
        }
        t += dp[i][j].first;
      }
    }
  }
  cout << t << endl;
  return 0;
}

