vector<int> InversePermutation(vector<int> const &P) // 0-indexed
{
  vector<int> Q(P.size());
  for (auto i = 0; i < static_cast<int>(P.size()); ++i)
  {
    Q.at(P[i]) = i;
  }
  return Q;
}

