  cin >> N;
  vector<int> P(N);
  for (auto i = 0; i < N; ++i)
  {
    cin >> P[i];
    P[i]--;
  }
  auto to_ind{InversePermutation(P)};
  set<int> S;
  ll ans{0};
  for (auto x = N - 1; x >= 0; --x)
  {
    ll ind{to_ind[x]};
    S.insert(ind);
    ll l0, l1, r0, r1;
    auto it{S.find(ind)};
    if (it == S.begin())
    {
      l0 = l1 = -1;
    }
    else
    {
      --it;
      l0 = *it;
      if (it == S.begin())
      {
        l1 = -1;
      }
      else
      {
        --it;
        l1 = *it;
      }
    }
    it = S.find(ind);
    ++it;
    if (it == S.end())
    {
      r0 = r1 = N;
    }
    else
    {
      r0 = *it;
      ++it;
      if (it == S.end())
      {
        r1 = N;
      }
      else
      {
        r1 = *it;
      }
    }
    ans += (x + 1) * ((l0 - l1) * (r0 - ind) + (r1 - r0) * (ind - l0));
  }
  cout << ans << endl;
}

