        ll idx = PS[i].ss;
        auto r1 = s.upper_bound(idx);
        auto r2 = next(r1);
        auto l1 = --s.lower_bound(idx);
        auto l2 = prev(l1);
        ll tmp1 = (*r2-*r1)*(idx-*l1);
        ll tmp2 = (*l1-*l2)*(*r1-idx);
        ans += PS[i].ff*(tmp1+tmp2);
        s.insert(idx);
    }
    cout << ans << endstr;
    return 0;
}

