int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  int n; std::cin >> n;
  std::vector<std::pair<int, int>> pairs(n);
  rep(x, 0, n) {
    int y; std::cin >> y;
    pairs.at(x) = {y, x};
  }
  std::sort(all(pairs));
  std::reverse(all(pairs));
  auto ret = 0LL;
  auto bit = make_binary_indexed_tree(
    n,
    [](auto x, auto y){ return x + y; },
    [](auto x, auto y){ return x - y; },
    0
  );
  auto find_left = [&] (int r) {
    auto check = [&] (int l) {
      return bit.query(l, r) >= 1;
    };
    auto lwr = -1, upr = r, md = 0;
    while (abs(lwr - upr) > 1) {
      md = (lwr + upr) >> 1;
      if (check(md)) lwr = md;
      else upr = md;
    }
    return lwr;
  };
  auto find_right = [&] (int l) {
    auto check = [&] (int r) {
      return bit.query(l, r) <= 1;
    };
    if (check(n)) return n;
    auto lwr = l, upr = n, md = 0;
    while (abs(lwr - upr) > 1) {
      md = (lwr + upr) >> 1;
      if (check(md)) lwr = md;
      else upr = md;
    }
    return lwr;
  };
  auto calc_left = [&] (int x) {
    auto r = find_left(x);
    auto l = find_left(r);
    return std::make_pair(r - l, x - r);
  };
  auto calc_right = [&] (int x) {
    auto l = find_right(x);
    auto r = find_right(l);
    return std::make_pair(l - x, r - l);
  };
  for (auto pair : pairs) {
    int y, x; std::tie(y, x) = pair;
    bit.add(x, 1);
    // debug(bit.collect());
    int p, q, r, s;
    std::tie(p, q) = calc_left(x);
    std::tie(r, s) = calc_right(x);
    // debug(y, p, q, r, s);
    ret += (lint)y * (p * r + q * s);
  }
  std::cout << ret << std::endl;
  return 0;
}

