struct
{
    void init(int _N)
    {
        N = _N;
        build(1,N,1);
    }
    void build(int l, int r, int id)
    {
        if(l==r)
        {
            st[id] = A[l];
            return;
        }
        int m = (l+r)/2;
        build(l,m,id*2);
        build(m+1,r,id*2+1);
        up(id);
    }
    void up(int id)
    {
        st[id] = max( st[id*2], st[id*2+1] );
    }
    ll que(int l, int r, int L, int R, int id=1)
    {
        if( l>R || r<L )return 0;
        if( l>=L && r<=R )return st[id];
        int m = (l+r)/2;
        return max( que(l,m,L,R,id*2), que(m+1,r,L,R,id*2+1) );
    }
    int N;
    ll st[MXN*4];
}segt;

