		L[i] = L[i-1];
		R[i] = R[i+1];
		int kanan = find_par(i,R);
		int kiri = find_par(i,L);
		int kanan2 = find_par((kanan==0)?0:kanan+1,R);
		int kiri2 = find_par((kiri==0)?0:kiri-1,L);
//		cout << kiri2 << " , " << kiri << " DAN " << kanan << " , " << kanan2 << endl;
		if(kanan == 0) kanan = n+1;
		if(kanan2 == 0) kanan2 = n+1;
		LL tmp = (kanan2-kanan)*(i-kiri);
		tmp+= (kiri-kiri2)*(kanan-i);
		ans+=tmp*(LL)ii;
//		cout << tmp << " " << ii << endl;
	}
	printf("%lld\n",ans);
	return 0;
}

