struct
{
    void init(int _N)
    {
        N = _N;
        build(1,N,1);
    }
    void build(int l, int r, int id)
    {
        if(l==r)
        {
            st[id] = A[l];
            return;
        }
        int m = (l+r)/2;
        build(l,m,id*2);
        build(m+1,r,id*2+1);
        up(id);
    }
    void up(int id)
    {
        st[id] = max( st[id*2], st[id*2+1] );
    }
    ll que(int l, int r, int L, int R, int id=1)
    {
        if( l>R || r<L )return 0;
        if( l>=L && r<=R )return st[id];
        int m = (l+r)/2;
        return max( que(l,m,L,R,id*2), que(m+1,r,L,R,id*2+1) );
    }
    int N;
    ll st[MXN*4];
}segt;

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin>>N;
    FOR(i,1,N)cin>>A[i];
    segt.init(N);

    FOR(i,1,N)
    {
        ll Ai = A[i];
        ll l1,l2,r1,r2;
        ll ls1,ls2,rs1,rs2;

        //find first pos right > Ai
        int l = i, r = N+1;
        while(l+1<r)
        {
            int m = (l+r)/2;
            if( segt.que(1,N,i,m)==Ai )l=m;
            else r=m;
        }
        r1 = l;
        rs1 = r1-i+1;

        if( r1==N )rs2=0;
        else if( r1==N-1 )rs2=1;
        else if( A[r1+2]>Ai )rs2=1;
        else
        {
            l = r1+2, r = N+1;
            while(l+1<r)
            {
                int m = (l+r)/2;
                if( segt.que(1,N,i,m)<=Ai )l=m;
                else r=m;
            }
            r2 = l;
            rs2 = r2-r1;
        }

        l = 0, r = i;
        while(l+1<r)
        {
            int m = (l+r)/2;
            if( segt.que(1,N,m,i)==Ai )r=m;
            else l=m;
        }
        l1 = r;
        ls1 = i-l1+1;

        if( l1==1 )ls2=0;
        else if( l1==2 )ls2=1;
        else if( A[l1-2]>Ai )ls2=1;
        else
        {
            l = 0, r = r-2;
            while(l+1<r)
            {
                int m = (l+r)/2;
                if( segt.que(1,N,m,i)<=Ai )r=m;
                else l=m;
            }
            l2 = r;
            ls2 = l1-l2;
        }

        ans+=Ai*( rs2*ls1 );
        ans+=Ai*( ls2*rs1 );

        /*
