ll N;
vector<P> A;
set<ll> used;

ll solve(){
  ll res = 0;
  sort(A.begin(), A.end());
  reverse(A.begin(), A.end());
  used.insert(-1);
  used.insert(N);
  rep(i, N){
    ll pos = A[i].s;
    ll plus = A[i].f;
    auto left = used.lower_bound(pos);
    auto right = used.lower_bound(pos);
    left--;
    if(*left == -1 && *right == N){

    }else if(*left == -1){
      auto rright = right;
      rright++;
      res += plus * (pos + 1) * (*rright - *right);
    }else if(*right == N){
      auto lleft = left;
      lleft--;
      res += plus * (*left - *lleft) * (N - pos);
    }else{
      auto lleft = left;
      lleft--;
      auto rright = right;
      rright++;
      res += plus * (*left - *lleft) * (*right - pos);
      res += plus * (pos - *left) * (*rright - *right);
    }
    used.insert(pos);
  }
  return res;
}

