int it[N*4],itt[N*4],pos[N];
void update(int i,int l,int r,int x)
{
    if(l>x||r<x) return;
    if(l==r)
    {
        if(l==x) it[i]=itt[i]=x;
        //   cout<<l<<' '<<r<<' '<<it[i]<<endl;
        return;
    }
    int mid=(l+r)>>1;
    update(i*2,l,mid,x);
    update(i*2+1,mid+1,r,x);
    it[i]=min(it[i*2],it[i*2+1]);
    itt[i]=max(itt[i*2],itt[i*2+1]);
    // cout<<l<<' '<<r<<' '<<it[i]<<endl;
}
int get(int i,int l,int r,int u,int v)
{
    //  cout<<u<<'*'<<v<<endl;
    if(l>v||r<u) return n+1;
    if(l>=u&&r<=v) return it[i];
    int mid=(l+r)>>1;
    return min(get(i*2,l,mid,u,v),get(i*2+1,mid+1,r,u,v));
}
int gett(int i,int l,int r,int u,int v)
{
    if(u>v) return 0;
    if(l>v||r<u) return 0;
    if(l>=u&&r<=v) return itt[i];
    int mid=(l+r)>>1;
    return max(gett(i*2,l,mid,u,v),gett(i*2+1,mid+1,r,u,v));
}
