           // cout<<ans<<endl;
        }
        if(est[p].se<n)
        {
            er=get(1,1,n,est[p].se+2,est[est[p].se+1].se);
            if(er==n+1) er=est[est[p].se+1].se+1;
           // cout<<"2 "<<er<<' '<<endl;
            ans+=(ll)max(0,p-est[p].fi+1)*(ll)max(0,(er-est[p].se-1))*(ll)a[p];
           // cout<<ans<<endl;
        }
        update(1,1,n,p);
    }
    cout<<ans;
}
