using namespace std;
using large = long long;

int main() {
    int n;
    cin >> n;
    auto p = vector<int>(n);
    auto Pos = map<int, int, greater<int>>();
    for (auto i = 0; i < n; ++i) {
        cin >> p[i];
        Pos.emplace(p[i], i);
    }

    auto sum = 0LL;
    auto indices = set<int>();
    for (auto [p_i, i] : Pos) {
        indices.insert(i);
        const auto this_itr = indices.find(i);

        auto L0 = -1;
        auto L1 = -1;

        {
            auto itr = this_itr;
            while (itr != indices.begin()) {
                --itr;
                if (p[*itr] > p[i]) {
                    L1 = *itr;
                    break;
                }
            }
            while (itr != indices.begin()) {
                --itr;
                if (p[*itr] > p[i]) {
                    L0 = *itr;
                    break;
                }
            }
        }

        auto R0 = n;
        auto R1 = n;
        {
            auto itr = this_itr;
            for (++itr; itr != indices.end(); ++itr) {
                if (p[*itr] > p[i]) {
                    R0 = *itr;
                    ++itr;
                    break;
                }
            }
            for (; itr != indices.end(); ++itr) {
                if (p[*itr] > p[i]) {
                    R1 = *itr;
                    break;
                }
            }
        }

        auto cases = 0LL;
        {
            auto Ls = L1 - L0;
            auto Rs = R0 - i;
            cases += large{Ls} * large{Rs};
        }
        {
            auto Ls = i - L1;
            auto Rs = R1 - R0;
            cases += large{Ls} * large{Rs};
        }
        sum += cases * p_i;
    }

    cout << sum << endl;
    return 0;
}

