void solve() {
	int N;
	cin >> N;
	vector<LL> A(N+2);
	vector<int> pos(N + 1, 0);
	A[0] = INF; A[N + 1] = INF;
	for (int i = 1; i <=N; ++i) {
		cin >> A[i];
		pos[A[i]] = i;
	}
	set<int> L, R;
	L.insert(-pos[N]);
	R.insert(pos[N]);

	LL ans = 0;
	set<int>::iterator itr;
	for (int i = N - 1; i >= 1; --i) {
		LL ter = pos[i];
		int Lpos2,Lpos1,Rpos1, Rpos2;
		itr = R.upper_bound(ter);
		if (itr != R.end() ){
			Rpos1 = *itr;
			itr = R.upper_bound(Rpos1);
			if (itr != R.end()) {
				Rpos2 = *itr;
			}
			else {
				Rpos2 = N + 1;
			}

			itr = L.upper_bound(-ter);
			if (itr != L.end()) {
				Lpos1 = -(*itr);
			}
			else {
				Lpos1 = 0;
			}
			LL res = (LL)(ter - Lpos1) * (Rpos2 - Rpos1);
			ans += res*i;
		}

		itr = L.upper_bound(-ter);
		if(itr != L.end()){
			Lpos1 = -(*itr);
			itr = L.upper_bound(-Lpos1);
			if (itr != L.end()) {
				Lpos2 = -(*itr);
			}
			else {
				Lpos2 = 0;
			}

			itr = R.upper_bound(ter);
			if (itr != R.end()) {
				Rpos1 = (*itr);
			}
			else {
				Rpos1 = N + 1;
			}
			LL res = (LL)(Lpos1 - Lpos2) * (Rpos1 - ter);
			ans += res*i;
		}
		R.insert(ter);
		L.insert(-ter);
	}
	cout << ans << endl;
}

