  vector<int> p(n);
  rep (i, n) cin >> p[i];
  vector<pair<int, int>> psort(n);
  rep (i, n) psort[i] = {p[i], i};
  sort(all(psort), greater<pair<int, int>>());
  lint sum = 0;
  multiset<int> checked{-1, -1, n, n, psort[0].second};
  rep (i, 1, n) {
    lint times = 0;
    int  now   = psort[i].second;
    auto rfir  = checked.lower_bound(now);
    auto rsec  = next(rfir);
    auto lfir  = prev(rfir);
    auto lsec  = prev(lfir);
    times += ((*lfir) - (*lsec)) * ((*rfir) - now);
    times += (now - (*lfir)) * ((*rsec) - (*rfir));
    sum   += psort[i].first * times;
    checked.insert(now);
  }
  cout << sum << endl;
  return 0;
}

