#define MAXN 100007

int n ;
int a[ MAXN ] ;

int pos[ MAXN ] ;

class Tree {
    public :
    int tr[ 6 * MAXN ] ;
    void init ( int where , int IL , int IR ) {
        tr[ where ] = 0 ;
        if ( IL == IR ) { return ; }
        int mid = ( IL + IR ) / 2 ;
        init ( 2 * where , IL , mid ) ;
        init ( 2 * where + 1 , mid + 1 , IR ) ;
    }
    void update ( int where , int IL , int IR , int pos , int val ) {
        if ( IR < pos || pos < IL ) { return ; }
        if ( IL == IR ) {
            tr[ where ] = val ;
            return ;
        }
        int mid = ( IL + IR ) / 2 ;
        if ( pos <= mid ) {
            update ( 2 * where , IL , mid , pos , val ) ;
        }
        else {
            update ( 2 * where + 1 , mid + 1 , IR , pos , val ) ;
        }
        tr[ where ] = tr[ 2 * where ] + tr[ 2 * where + 1 ] ;
    }
    int getl ( int where , int IL , int IR , int pos ) {
        if ( pos < IL ) { return 0 ; }
        if ( IR <= pos && tr[ where ] == 0 ) { return 0 ; }
        if ( IL == IR ) { return IL ; }
        int mid = ( IL + IR ) / 2 ;
        int ret = getl ( 2 * where + 1 , mid + 1 , IR , pos ) ;
        if ( ret > 0 ) { return ret ; }
        return getl ( 2 * where , IL , mid , pos ) ;
    }
    int getr ( int where , int IL , int IR , int pos ) {
        if ( IR < pos ) { return n + 1 ; }
        if ( pos <= IL && tr[ where ] == 0 ) { return n + 1 ; }
        if ( IL == IR ) { return IL ; }
        int mid = ( IL + IR ) / 2 ;
        int ret = getr ( 2 * where , IL , mid , pos ) ;
        if ( ret < n + 1 ) { return ret ; }
        return getr ( 2 * where + 1 , mid + 1 , IR , pos ) ;
    }
};

Tree w ;

void input ( ) {
    scanf ( "%d" , &n ) ;
    for ( int i = 1 ; i <= n ; ++ i ) {
        scanf ( "%d" , &a[ i ] ) ;
        pos[ a[ i ] ] = i ;
    }
}

void solve ( ) {
    w.init ( 1 , 1 , n ) ;
    long long ans = 0 ;
    for ( int i = n ; i >= 1 ; -- i ) {
        int prv1 , nxt1 ;
        prv1 = w.getl ( 1 , 1 , n , pos[ i ] ) ;
        nxt1 = w.getr ( 1 , 1 , n , pos[ i ] ) ;
        int prv2 , nxt2 ;
        if ( prv1 == 0 ) { prv2 = 0 ; }
        else { prv2 = w.getl ( 1 , 1 , n , prv1 - 1 ) ; }

        if ( nxt1 == n + 1 ) { nxt2 = n + 1 ; }
        else { nxt2 = w.getr ( 1 , 1 , n , nxt1 + 1 ) ; }

        ans += 1LL * i * ( pos[ i ] - prv1 ) * ( nxt2 - nxt1 ) ;
        ans += 1LL * i * ( prv1 - prv2 ) * ( nxt1 - pos[ i ] ) ;

        w.update ( 1 , 1 , n , pos[ i ] , 1 ) ;
    }
    printf ( "%lld\n" , ans ) ;
}

int main ( ) {
    ios_base :: sync_with_stdio ( false ) ;
    cin.tie ( NULL ) ;
    input ( ) ;
    solve ( ) ;
    return 0 ;
}

