void pushup(int rt)
{
    tree[rt]=max(tree[rt<<1],tree[rt<<1|1]);
}
void build(int l,int r,int rt)
{
    if(l==r)
    {
        tree[rt]=a[l];
        return;
    }
    int mid=(l+r)>>1;
    build(l,mid,rt<<1);
    build(mid+1,r,rt<<1|1);
    pushup(rt);
}
int ask(int l,int r,int L,int R,int rt)
{
    int ans=0;
    if(l<=L&&R<=r)
    {
        return tree[rt];
    }
    int mid=(L+R)>>1;
    if(l<=mid)
        ans=max(ans,ask(l,r,L,mid,rt<<1));
    if(r>mid)
        ans=max(ans,ask(l,r,mid+1,R,rt<<1|1));
    return ans;
}
int findx(int l,int r,int x,int op)
{
    if(l>r)
        return -1;
    if(ask(l,r,1,n,1)<x)
        return -1;
    if(l==r)
        return l;
    int mid=(l+r)>>1;

    if(op==0)
    {
        int rnum=ask(mid+1,r,1,n,1);
        if(rnum>x)
            return findx(mid+1,r,x,op);
        else
            return findx(l,mid,x,op);
    }
    else if(op==1)
    {
        int rnum=ask(l,mid,1,n,1);
        if(rnum>x)
            return findx(l,mid,x,op);
        else
            return findx(mid+1,r,x,op);
    }

}
