ll gcd(ll a, ll b) { while(b != 0) { a %= b; swap(a, b); } return a; }

ll lcm(ll a, ll b) { return a / gcd(a, b) * b; }

ll modinv(ll a, ll p = MOD) {
    ll b = p, u = 1, v = 0;
    while(b) {
        ll tmp = a / b;
        a -= tmp * b; u -= tmp * v;
        swap(a, b); swap(u, v);
    }
    u %= p;
    if (u < 0) u += p;
    return u;
}

bool isprime(ll p) {
    if(p <= 1) return false;
    ll s = min(p - 1, (ll)ceil(sqrt(p)));
    for(int i = 2;i <= s;i++)
        if(p % i == 0) return false;
    return true;
}

ll minDivisor(ll x, ll n = 2) {
    if(x <= 1) return 1;
    ll s = min(x - 1, (ll)ceil(sqrt(x)));
    for(int i = n;i <= s;i++)
        if(x % i == 0) return i;
    return x;
}

ll countDivisor(ll x) {
    map<ll, int> m;
    if(x <= 1) return 1;
    ll s = min(x - 1, (ll)ceil(sqrt(x)));
    for(int i = 2;i <= s;i++) {
        if(x % i == 0) {
            x /= i;
            m[i]++;
            i = 1;
        }
    }
    if(x != 1) m[x]++;
    ll ret = 1;
    for(auto i : m) {
        ret *= i.second + 1;
    }
    return ret;
}

class disjoint_set
{
    vector<int> _parent, _size;

public:
    disjoint_set(int n) : _parent(n), _size(n) {
        for (int i = 0; i < n; i++) {
            _parent[i] = i;
            _size[i] = 1;
        }
    }
    int root(int x) {
        if (_parent[x] == x) return x;
        return _parent[x] = root(_parent[x]);
    }
    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        _parent[rx] = ry;
        _size[ry] += _size[rx];
    }
    bool same(int x, int y) { return root(x) == root(y); }
    int size(int x) { return _size[root(x)]; }
};

void warshall_floyd(vector<vector<ll>>& dist, int n) {
    for(int i = 0;i < n;i++) {
        for(int j = 0;j < n;j++) {
            for(int k = 0;k < n;k++) {
                chmin(dist[j][k], dist[j][i] + dist[i][k]);
            }
        }
    }
}

