ll func(vector<int>& v, vector<int>::iterator begin, vector<int>::iterator end){
    if (begin == end){
        return 0;
    }

    auto first = max_element(begin, end);

    auto l_max_ind = max_element(begin, first);
    auto r_max_ind = max_element(first+1, end);

    ll ans = 0;
    if (*l_max_ind > *r_max_ind || r_max_ind == end) {
        ans += (*l_max_ind * (l_max_ind - begin + 1) * (end - first));
        ans += func(v, begin, first);
    } else if (*l_max_ind < *r_max_ind || l_max_ind == first){
        ans += (*r_max_ind * (first - begin + 1) * (end - r_max_ind));
        ans += func(v, first+1, end);
    }

    return ans;
}


