	for(int i=n;i;i--){
		r[i]=qry(0,0,n+1,a[i]+1,n+1,1);
		update(0,0,n+1,a[i],i,1);
		//cout<<r[i]<<" "<<i<<"\n";
	}
	for(int i=1;i<=n;i++){
		l[i]=qry(0,0,n+1,a[i]+1,n+1,0);
		update(0,0,n+1,a[i],i,0);
		//cout<<l[i]<<" "<<i<<"\n";
	}
	r[n+1]=pii(n+1,n+1);
