    maxx(1,0,n-1,i+1,n-1,a[i],'r'); 
    if(done){
      jr=pos[val]; 
      done=0; 
      maxx(1,0,n-1,jr+1,n-1,a[i],'r'); 
      if(done){
        sr=pos[val]-jr; 
      }
      else sr=n-jr; 
    }
    done=0; 
    maxx(1,0,n-1,0,i-1,a[i],'l'); 
    if(done){
      jl=pos[val]; 
      done=0; 
      maxx(1,0,n-1,0,jl-1,a[i],'l'); 
      if(done){
        sl=jl-pos[val]; 
      }
      else {
        sl=jl+1;  
      }
    }
//    cout<<" i jr sr jl sl "<<i<<" " <<jr<<" " <<sr<<" " <<jl<<" " <<sl<<endl; 
    ans+=(ll)a[i]*sr*(i-jl); 
    ans+=(ll)a[i]*sl*(jr-i); 
  }
  cout<<ans<<endl; 
}

int main()
{
	fast_io;
	clock_t beg=clock(); 
	solve(); 
	clock_t end=clock(); 
	fprintf(stderr,"%.2lf sec\n",(double)(end-beg)/CLOCKS_PER_SEC); 
	return 0;
}

