  vector<int> P(N);
  for (int i = 0; i < N; ++i) {
    cin >> P[i];
  }

  vector<int> idx(N + 1);
  for (int i = 0; i < N; ++i) {
    idx[P[i]] = i;  // P[i] in {1..N}
  }

  ll ans = 0;
  set<int> s;
  for (int val = N; val >= 1; --val) {
    int x = idx[val];
    s.insert(x);

    vector<int> l(2, -1);
    vector<int> r(2, N);
    {  // left
      auto it = s.find(x);
      for (int i = 0; i < 2; ++i) {
	if (it == s.begin()) break;
	--it;
	l[i] = *it;
      }
    }
    {  // right
      auto it = s.find(x);
      for (int i = 0; i < 2; ++i) {
	++it;
	if (it == s.end()) break;
	r[i] = *it;
      }
    }

    if (l[0] != -1) {
      ans += (ll)(l[0] - l[1]) * (r[0] - x) * val;
    }
    if (r[0] != N) {
      ans += (ll)(x - l[0]) * (r[1] - r[0]) * val;
    }
  }

  cout << ans << endl;

  return 0;
}

