		lex[i] = -1;
		ri[i] = -1;
		rix[i] = -1;
	}

	priority_queue<pai, vector<pai>, greater<pai> > pq1, pq2;
	priority_queue<pai, vector<pai>, greater<pai> > pq3, pq4;

