			rix[p.second] = i-1;
 		}
		while (pq1.top().first < temp){
			auto p = pq1.top();
			pq1.pop();
			ri[p.second] = i;
			pq3.push(p);
		}
	}
	while(!pq3.empty()){
		auto p = pq3.top();
		pq3.pop();
		rix[p.second] = n-1;
	}
	for (int i = n-1; i >= 0; i--){
		pq2.push(make_pair(p[i], i));
		int temp = p[i];
		while (!pq4.empty() && pq4.top().first < temp){
			auto p = pq4.top();
			pq4.pop();
			lex[p.second] = i+1;
		}
		while (pq2.top().first < temp){
			auto p = pq2.top();
			pq2.pop();
			le[p.second] = i;
			pq4.push(p);
		}
	}
	while(!pq4.empty()){
