struct RMQ {
  long dat[kMax5][20];
  long dat2[kMax5][20];

  RMQ() {}
  void init(const vector<long> & a) {
    auto n = a.size();
    rep(i, 0, n - 2) {
      dat[i][1] = max(a[i], a[i + 1]);
      dat2[i][1] = min(a[i], a[i + 1]);
      // cout << i << " " << 1 << " " << dat[i][1] << " " << dat2[i][1] << endl;
    }
    for (auto j = 2; (1 << j) <= n; ++j) {
      for (auto i = 0; i + (1 << j) - 1 < n; ++i) {
        dat[i][j] = max(dat[i][j - 1], dat[i + (1 << (j - 1))][j - 1]);
        auto min_dat = min(dat[i][j - 1], dat[i + (1 << (j - 1))][j - 1]);
        auto max_dat2 = max(dat2[i][j - 1], dat2[i + (1 << (j - 1))][j - 1]);
        dat2[i][j] = max(min_dat, max_dat2);
        // cout << i << " " << j << " " << dat[i][j] << " " << dat2[i][j] << endl;
      }
    }
  }

  long query(ll l, ll r) {
    if (l > r) {
      return 0;
    }

    auto k = 0;
    while (l + (1 << (k + 1)) - 1 <= r) { ++k; }
    auto dat_l = dat[l][k];
    auto dat_r = dat[r - (1 << k) + 1][k];
    auto dat2_l = dat2[l][k];
    auto dat2_r = dat2[r - (1 << k) + 1][k];
    // auto min_dat = min(dat[l][k], dat[r - (1 << k) + 1][k]);
    // auto max_dat2 = max(dat2[l][k], dat2[r - (1 << k) + 1][k]);
    if (dat_l == dat_r && dat2_l == dat2_r) {
      return dat2_l;
    } else if (dat_l == dat_r) {
      return max(dat2_l, dat2_r);
    } else if (dat2_l == dat2_r){
      return min(dat_l, dat_r);
    } else if (dat_l == dat2_r){
      return dat_l;
    } else if (dat2_l == dat_r){
      return dat2_l;
    } else {
      return max(min(dat_l, dat_r), max(dat2_l, dat_r));
    }
  }
};

