        while(r-l>1){
          int X=(l+r)/2;
        if(qu(A+1+a,X,0,0,MAX_N)>i){
          r=X;
        }
        else{
          l=X;
        }
        }
        B=r-a-1;
      }
    }
    if(qu(0,a,0,0,MAX_N)>i){
      l=0,r=a;
