ll n, ans;

ll p[maxn];

ll st[maxn][20], lg[maxn];

void init()
{
	rep(i, 1, n) st[i][0] = p[i];
	ll tot = 0;
	rep(i, 1, n)
	{
		if((1 << (tot + 1)) < i) tot ++;
		lg[i] = tot;
	}
	if(tot >= 20)
	{
		puts("0");
		exit(0);
	}
	rep(i, 1, tot) rep(j, 1, n)
	{
		if(!(j + (1 << (i - 1)) < maxn))
		{
			puts("0");
			exit(0);
		}
		if(!(j + (1 << (i - 1)) > 0))
		{
			puts("0");
			exit(0);
		}
		st[j][i] = max(st[j][i - 1], st[j + (1 << (i - 1))][i - 1]);
	}
	return ;
}

#define query(l, r) max(st[l][lg[r - l + 1]], st[r - (1 << lg[r - l + 1]) + 1][lg[r - l + 1]])

ll bsearch(ll l, ll r, ll x, ll typ)
{
	ll s = l, e = r;
	ll ret = typ * (n + 1);
	while(l <= r)
	{
		ll mid = (l + r) >> 1;
		if(typ == 1)
		{
			if(query(mid, s) > x) r = mid - 1, ret = mid;
			else l = mid + 1;
		}
		else
		{
			if(query(mid, e) > x) l = mid + 1, ret = mid;
			else r = mid - 1;
		}
	}
	return ret;
}

signed main()
{
	scanf("%lld", &n);
	rep(i, 1, n) scanf("%lld", &p[i]);
	init();
	rep(i, 1, n)
	{
		ll tl = bsearch(1, i - 1, p[i], 0), tr = bsearch(i + 1, n, p[i], 1);
		ll sl = bsearch(1, tl - 1, p[i], 0), sr = bsearch(tr + 1, n, p[i], 1);
		ans += p[i] * (sr - tr) * (i - tl);
		ans += p[i] * (tl - sl) * (tr - i);
	}
	printf("%lld\n", ans);
	return 0;
}

