		if (l[z] != -1)r[l[z]] = w;
		if (y[1] != -1) {
			an = y[1] - y[0];
			an *= (y[2] - id[i]);
			ans += an * i;
		}
		if (y[2] != n) {
			an = y[3] - y[2];
			an *= (id[i] - y[1]);
			ans += an * i;
		}
	}
	printf("%lld\n", ans);
}

