	ll ret = 0;
	for (int i = 0; i < N; ++i)
	{
		ll right1;
		ll right2;

		{
			ll ok = N;
			ll ng = i;
			binary(ok, ng, rmq, i, x[i]);
			right1 = ok;
		}

		{
			rmq.set(right1, NG);

			ll ok = N;
			ll ng = i;
			binary(ok, ng, rmq, i, x[i]);

			rmq.set(right1, x[i]);
			right2 = ok;
		}

		ll left1;
