pii getmx(pii a,pii b)
{
    pii ans;

    if(a.f>b.f){
        ans.f = a.f;
        ans.s = max(b.f,a.s);
    }
    else {
        ans.f = b.f;
        ans.s = max(a.f,b.s);
    }
    return ans;
}

pii getans(int L,int R)
{
    pii res;

    while(L<=R){
        if(L&1){res=getmx(res,tree[L]); L++;}
        if(!(R&1)){res=getmx(res,tree[R]); R--;}
        L>>=1; R>>=1;
    }

    return res;
}

bool ok(int L,int R,bool iss,int x)
{
    pii cur = getans(L,R);

    if(!iss){
