Range_Query<SUB_MAX> rq(MAX_N);

int main(int argc, char **argv) {
    std::cin.tie(0);
   	std::ios::sync_with_stdio(false);
    std::cout << std::fixed << std::setprecision(15);

    std::cin >> N;
    input1(1, N, P);

    rq.update(0, N + 1, 0);
    rep (i, 1, N) {
        rq.update_spot(i, P[i]);
    }

    int128_t ret = 0;
    rep (i, 1, N) {
        int128_t n = -1;
        int128_t nn = -1;
        int128_t p = -1;
        int128_t pp = -1;
        auto bsr = binary_search(i+1, N+1, [&](int128_t j){
            return P[i] < rq.query(i+1, j);
        });
        if (bsr.found) {
            n = bsr.begin;
            bsr = binary_search(n+1, N+1, [&](int128_t j){
                return P[i] < rq.query(n+1, j);
            });
            if (bsr.found) {
                nn = bsr.begin;
            }
        }

        bsr = binary_search(0, i-1, [&](int128_t j){
            return P[i] < rq.query(j, i-1);
        });
        if (bsr.found) {
            p = bsr.end;
            bsr = binary_search(0, p-1, [&](int128_t j){
                return P[i] < rq.query(j, p-1);
            });
            if (bsr.found) {
                pp = bsr.end;
            }
        }

        if (n != -1) {
            int128_t pu = p == -1 ? 0 : p;
            int128_t nnu = nn == -1 ? N + 1 : nn;
            ret += (i - pu) * (nnu - n) * P[i];
        }
        if (p != -1) {
            int128_t nu = n == -1 ? N + 1 : n;
            int128_t ppu = pp == -1 ? 0 : pp;
            ret += (p - ppu) * (nu - i) * P[i];
        }
    }

    std::cout << ret << std::endl;

    return 0;
}

