vector<int> lg;

template <typename T>
struct RMQ {
    int n;
    vector<vector<T>> table;
    RMQ(vector<int>& xs): n(xs.size()) {
        int K = lg[n] + 2;
        table = vector<vector<T>>(K, vector<T>(n, 0));
        for (int i = 0; i < n; ++i) {
            table[0][i] = xs[i];
        }
        for (int k = 1; k < K; ++k) {
            for (int i = 0; i < n; ++i) {
                int j = min(i + (1 << (k-1)), n-1);
                table[k][i] = max(table[k-1][i], table[k-1][j]);
            }
        }
    }
    T get_max(int i, int j) {
        int k = lg[j-i];
        return max(table[k][i], table[k][j - (1 << k)]);
    }
};

long long second_sum(vector<int>& ps) {
    int n = (int)ps.size();
    vector<int> inv_p(n+1);
    for (int i = 0; i < n; ++i) {
        inv_p[ps[i]] = i;
    }
    RMQ<int> rmq(ps);
    function<long long (int, int)> calc_sum = [&](int l, int r) {
        if (r - l < 2) return 0LL;
        int m = inv_p[rmq.get_max(l, r)];
        deque<int> lefts, rights;
        int i = l-1;
        lefts.push_back(l-1);
        while (i < m-1) {
            i = inv_p[rmq.get_max(i+1, m)];
            lefts.push_back(i);
        }
        i = r;
        rights.push_back(r);
        while (m+1 < i) {
            i = inv_p[rmq.get_max(m+1, i)];
            rights.push_back(i);
        }
        int current_left = m, current_right = m;
        int current = 0;
        long long sum = 0;
        while (lefts.size() > 1 || rights.size() > 1) {
            if (lefts.size() == 1 || (rights.size() > 1 && ps[rights.back()] < ps[lefts.back()])) {
                current = ps[rights.back()];
                rights.pop_back();
                int new_right = rights.back() - 1;
                sum += ((long long) current) * ((long long) m - current_left + 1) * (new_right - current_right);
                current_right = new_right;
            } else {
                current = ps[lefts.back()];
                lefts.pop_back();
                int new_left = lefts.back() + 1;
                sum += ((long long) current) * ((long long) current_right - m + 1) * (current_left - new_left);
                current_left = new_left;
            }
        }
        return sum + calc_sum(l, m) + calc_sum(m+1, r);
    };
    return calc_sum(0, n);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    lg = vector<int>(n+1, 0);
    for (int i = 2; i <= n; ++i) {
        lg[i] = 1 + lg[i/2];
    }
    vector<int> ps(n);
    for (int& p : ps) {
        cin >> p;
    }
    cout << second_sum(ps) << endl;
    return 0;
}

