    {
        ll ans=0,f=1;char c=getchar();
        while(c<'0' or c>'9') {if(c=='-')f=-1;c=getchar();}
        while('0'<=c and c<='9') ans=ans*10+c-'0',c=getchar();
        return ans*f;
    }
    void write(ll num)
    {
        if(num<0) putchar('-'),num=-num;
        if(num>=10) write(num/10);
        putchar('0'+num%10);
    }
    void write1(ll num){write(num);putchar(' ');}
    void write2(ll num){write(num);putchar('\n');}
    template<typename T> void chmax(T &x,const T y) {x=(x>y?x:y);}
    template<typename T> void chmin(T &x,const T y) {x=(x<y?x:y);}
    ll gcd(ll x,ll y){return y?gcd(y,x%y):0;}

    const int INF=0x3f3f3f3f;
    const int MOD=998244353;
    inline int mm(const int x){return x>=MOD?x-MOD:x;}
    inline ll qpower(ll x,ll e)
    {
        ll ans=1;
        while(e){if(e&1)ans=ans*x%MOD;x=x*x%MOD;e>>=1;}
        return ans;
    }
    ll invm(ll x){return qpower(x,MOD-2);}
    const int N=1e6+10;

	int op;
	struct SGT
	{
		pr mx[N*4];
		pr merg(pr x,pr y)
		{
			int a[5];a[0]=x.FR,a[1]=x.SE,a[2]=y.FR,a[3]=y.SE;
			sort(a,a+4);if(op==1)return MP(a[0],a[1]); else return MP(a[3],a[2]);
		}
		#define LC 2*x
		#define RC 2*x+1
		#define MID (l+r)/2
		void insert(int x,int l,int r,int pos,int num)
		{
			if(l==r){mx[x].FR=num;return;}
			if(pos<=MID) insert(LC,l,MID,pos,num);
			else insert(RC,MID+1,r,pos,num);
			mx[x]=merg(mx[LC],mx[RC]);
		}
		pr ask(int x,int l,int r,int fl,int fr)
		{
			if(fl>fr) return mx[0];
			if(l==fl and r==fr) return mx[x];
			if(fr<=MID) return ask(LC,l,MID,fl,fr); else if(fl>MID) return ask(RC,MID+1,r,fl,fr);
			return merg(ask(LC,l,MID,fl,MID),ask(RC,MID+1,r,MID+1,fr));
		}
	}sgt[2]; 
	pr x[N],y[N];int a[N];
