	{
		int n=qread();for(int i=1;i<=n;i++) a[i]=qread();
		for(int i=1;i<=n;i++) x[i]=sgt[0].ask(1,1,n,a[i]+1,n),sgt[0].insert(1,1,n,a[i],i);
		op=1;for(int i=0;i<N*4;i++) sgt[1].mx[i]=MP(n+1,n+1);
		for(int i=n;i>=1;i--) y[i]=sgt[1].ask(1,1,n,a[i]+1,n),sgt[1].insert(1,1,n,a[i],i);
		ll ans=0;
		for(int i=1;i<=n;i++)
		{
			ll cnt=0;
			if(x[i].FR>0) cnt+=1ll*((x[i].FR-x[i].SE)*(y[i].FR-i));
			if(y[i].FR<=n) cnt+=1ll*((i-x[i].FR)*(y[i].SE-y[i].FR));
			ans+=cnt*a[i];
		}
		write(ans);
	}
};
