    m[i][i+1]=max(p[i],p[i+1]);
    x[i][i+1]=min(p[i],p[i+1]);
    ans += x[i][i+1];
  }

  for (int i=0; i<n-2; i++){
    for (int j=i+2; j<n; j++){
      int first = m[i][j-1];
      int second = x[i][j-1];
      int num = p[j];
      if (num > first){
        m[i][j]=num;
        x[i][j]=first;
