signed main(){
    int START_TIME = clock();
    cin.tie(nullptr);
    ios::sync_with_stdio(false);   //cin cout 高速化
//    cout << fixed << setprecision(15);

    /**
     * set = {-1, place of max(Ai), n} として、
     * valがでかい方から順に決めていく
     * Ai が最大から2つ目になるときは、
     * Aiよりでかい要素を"一つのみ"含むとき
     *
     */

    i32 n, p; cin >> n;
    vi place(n+1);
    rep (i,n) {
        cin >> p;
        place[p] = i;
    }

    multiset<i32> used_p_places;
    used_p_places.insert(-1);
    used_p_places.insert(-1);
    used_p_places.insert(n);
    used_p_places.insert(n);

    i64 sum = 0;
    for (i32 val = n; val >= 1; --val) {
        i32 plc = place[val];
        auto iter = used_p_places.lower_bound(plc);
        i32 R = *++iter;
        i32 r = *--iter;
        i32 l = *--iter;
        i32 L = *--iter;

        sum += val * (R-r) * (plc-l);
        sum += val * (r-plc) * (l-L);

        used_p_places.insert(plc);
    }
    cout << sum << '\n';

    // printf("ExecutionTime: %d /ms\n",1000*(int)((clock()-START_TIME)/CLOCKS_PER_SEC));
}

