void solve(){
    input();
    vector<int> locate(N);

    rep(i,N){
        locate[p[i]] = i;
    }
    set<int> s;
    ll ans = 0;
    for(int i = N -1; i >= 0;i--){
        int x = locate[i];
        ll c = 0;
        {
            vector<int> l(2, -1);
            vector<int> r(2, N);
            s.insert(i);
            {
                auto it = s.find(i);
                rep(j, 2){
                    if(it == s.begin()) break;
                    --it;
                    l[j] = *it;
                }
             }

            {
                auto it = s.find(i);
                rep(j, 2){
                    ++it;
                    if(it == s.end()) break;
                    r[j] = *it;
                }
            }


            vector<int> ls(2);
            ls[0] = i - l[0];ls[1] = l[0] - l[1];
            vector<int> rs(2);
            rs[0] = r[0] - i;rs[1] = r[1] - r[0];

            c = (ll)ls[0]*rs[1] + (ll)ls[1]*rs[0];
        }
            ans += c*(x+1);

    }
    cout << ans << endl;
    return;
}
