template<typename T>
class Table {
public:
	Table(int height, int width, T value) {
		if (width < 0)throw out_of_range("Width should be >=0");
		if (height < 0)throw out_of_range("Height should be >=0");
		this->wid = width;
		this->hgt = height;
		vs = vector<T>(width * height);
		for (auto i = 0; i < width * height; i++)vs[i] = value;
	}
	Table(const Table& table) {
		hgt = table.hgt;
		wid = table.wid;
		vs = vector<T>(hgt * wid);
		for (size_t i = 0; i < table.size(); i++) {
			vs[i] = table.vs[i];
		}
	}
	Table(Table&& table) {
		hgt = table.hgt;
		wid = table.wid;
		swap(vs, table.vs);
	}
	Table& operator=(const Table& table) {
		if (table == *this)return *this;
		this->wid = table.wid;
		this->hgt = table.hgt;
		vs = table.vs;
	}
	Table& operator=(Table&& table) {
		wid = table.wid;
		hgt = table.hgt;
		swap(vs, table.vs);
	}
	inline T& at(int y, int x) {
		if (wid > x)throw out_of_range("x>width.");
		if (hgt > y)throw out_of_range("y>height.");
		return vs[x + y * wid];
	}
	int size()const { return wid * hgt; }
	int width()const { return wid; };
	int height()const { return hgt; };
	T& operator()(int y, int x) { return vs[x + y * wid]; }
	const T& operator()(int y, int x)const { return vs[x + y * wid]; }
private:
	int wid, hgt;
	vector<T> vs;
};

struct MaxInfo {
	int first{ 0 };
	int second{ 0 };
	bool calculated{ false };
	static MaxInfo fromTry(int a, int b, int c) {
		if (a > b) {
			if (a > c) return { a,max(b,c),true };
			else return { c,a,true };
		} else {
			if (b > c)return { b,max(a,c),true };
			else return { c,b,true };
		}
	}
	static MaxInfo merge(MaxInfo a, MaxInfo b) {
		auto info = MaxInfo();
		if (a.first > b.first) return { a.first,max(a.second,b.first),true };
		else return { b.first,max(b.second,a.first),true };
	}
};

MaxInfo E_impl(const vector<int>& ns, Table<MaxInfo>& result, int l, int r) {
	if (result(l, r).calculated) return result(l, r);
	if (r - l == 1) {
		result(l, r) = { max(ns[l], ns[r]),min(ns[l],ns[r]),true };
		return result(l, r);
	}
	if (r - l == 2) {
		result(l, r) = MaxInfo::fromTry(ns[l], ns[l + 1], ns[l + 2]);
		return result(l, r);
	}
	// l=0  r=3 ->inter = 1
	auto inter = l + (r - l) / 2;
	result(l, inter) = E_impl(ns, result, l, inter);
	result(inter + 1, r) = E_impl(ns, result, inter + 1, r);
	result(l, r) = MaxInfo::merge(result(l, inter), result(inter + 1, r));
	return result(l, r);
}

void E() {
	read(int, n);
	auto ns = vector<int>(n);
	auto result = Table<MaxInfo>(n, n, {});
	for (auto i = 0; i < n; i++) cin >> ns[i];
	ll sum = 0;
	for (int l = 0; l < n-1; l++) {
		for (int r = l + 1; r < n; r++) {
			sum += E_impl(ns, result, l, r).second;
		}
	}
	cout << sum << endl;
}
