ll sumUp(int a) {
  ll ret = 0;
  while (a) {
    ret += BIT[a];
    a -= a & -a;
  }
  return ret;
}
void add(ll n, int v, int N) {
  while (v <= N) {
    BIT[v] += n;
    v += v & -v;
  }
}
int main () {
