  add(1, 1, N + 2);
  add(1, N + 2, N + 2);
  ll ans = 0;
  for (int i = N - 1; i >= 1; i --) {
    int mi = F[i];
    int ma = N + 2;
    ll ke = sumUp(F[i]);
    while (ma != mi) {
      int mu = (ma + mi) / 2;
      if (sumUp(mu) < ke + 1) mi = mu + 1;
      else ma = mu;
    }
    ll R1 = (ll)mi;
    ma = N + 2;
    ll R2 = (ll)N + 2;
    if ((int)R1 != N + 2) {
      ke ++;
      while (ma != mi) {
        int mu = (ma + mi) / 2;
        if (sumUp(mu) < ke + 1) mi = mu + 1;
        else ma = mu;
      }
      R2 = (ll)mi;
      ke --;
    }
    mi = 1;
    ma = F[i];
    while (ma != mi) {
      int mu = (ma + mi) / 2;
      if (sumUp(mu) < ke) mi = mu + 1;
      else ma = mu;
