        else ma = mu;
      }
      L2 = (ll)mi;
    }
    ll kj = (ll)F[i];
    //cout << i << ' ' << L1 << ' ' << L2 << ' ' << R1 << ' ' << R2 << endl;
    ans += (ll)((R1 - kj) * (L1 - L2) + (R2 - R1) * (kj - L1)) * i;
