};

llong n;
llong p[100005];
pair<llong, llong> range[100005];
llong sum;

int main() {
    cin >> n;

    SegmentTree<M>seg(n, M(-1, -1),
                  [](M l, M r){
                      if (l.v > r.v) return l;
                      else return r;
                  });

    llong mv = 0;
    for (int i = 0; i < n; i++) {
        cin >> p[i];

        mv = max(mv, p[i]);
        seg.update(i, M(p[i], i));
    }

    for (int i = 0; i < n; i++) {

        llong l, r;
        //left
        {
            llong valid = i;
            llong invalid = -1;

            while (valid - invalid > 1) {
                llong mid = (valid + invalid) / 2;

                if (seg.query(mid, i).v > p[i]) {
                    invalid = mid;
                }
                else {
                    valid = mid;
                }
            }

            l = valid - 1;
        }
        //right
        {
            llong valid = i + 1;
            llong invalid = n + 1;

            while (invalid - valid > 1) {
                llong mid = (valid + invalid) / 2;

                if (seg.query(i + 1, mid).v > p[i]) {
                    invalid = mid;
                }
                else {
                    valid = mid;
                }
            }

            r = valid;
        }

        range[i] = make_pair(l, r);
    }

    for (llong i = 0; i < n; i++) {
        if (mv == p[i]) continue;

        llong l, r, ml, mr;
        l = 0; r = n;
        ml = range[i].first;
        mr = range[i].second;


        if (mr < n) {
            // right;
            seg.update(mr, M(-1, -1));
            llong valid = mr;
            llong invalid = n + 1;
            while (invalid - valid > 1) {
                llong mid = (valid + invalid) / 2;

                if (seg.query(i, mid).v > p[i]) {
                    invalid = mid;
                }
                else {
                    valid = mid;
                }
            }

            r = valid;
            seg.update(mr, M(p[mr], mr + 1));
        }

        if (ml >= 0) {
            // left;
            seg.update(ml, M(-1, -1));
            llong valid = i;
            llong invalid = -1;
            while (valid - invalid > 1) {
                llong mid = (valid + invalid) / 2;

                if (seg.query(mid, i).v > p[i]) {
                    invalid = mid;
                }
                else {
                    valid = mid;
                }
            }
            l = valid - 1;
            seg.update(ml, M(p[ml], ml - 1));
        }

        llong mul = 0;

        // printf("%lld: [%lld, %lld, %lld, %lld] ", p[i], l, ml, mr, r);

        mul = (r - mr) * (i - ml) + (mr - i) * (ml - l);
        sum += mul * p[i];
        //        cout << sum << endl;
    }

    cout << sum << endl;

    return 0;
}

