template <typename T,typename E>
struct SegmentTree{
  typedef function<T(T,T)> F;
  typedef function<T(T,E)> G;
  int n;
  F f;
  G g;
  T d1;
  E d0;
  vector<T> dat;
  SegmentTree(){};
  SegmentTree(int n_,F f,G g,T d1,
	      vector<T> v=vector<T>()):
    f(f),g(g),d1(d1){
    init(n_);
    if(n_==(int)v.size()) build(n_,v);
  }
  void init(int n_){
    n=1;
    while(n<n_) n*=2;
    dat.clear();
    dat.resize(2*n-1,d1);
  }
  void build(int n_, vector<T> v){
    for(int i=0;i<n_;i++) dat[i+n-1]=v[i];
    for(int i=n-2;i>=0;i--)
      dat[i]=f(dat[i*2+1],dat[i*2+2]);
  }
  void update(int k,E a){
    k+=n-1;
    dat[k]=g(dat[k],a);
    while(k>0){
      k=(k-1)/2;
      dat[k]=f(dat[k*2+1],dat[k*2+2]);
    }
  }
  inline T query(int a,int b){
    T vl=d1,vr=d1;
    for(int l=a+n,r=b+n;l<r;l>>=1,r>>=1) {
      if(l&1) vl=f(vl,dat[(l++)-1]);
      if(r&1) vr=f(dat[(--r)-1],vr);
    }
    return f(vl,vr);
  }

};

int main(){
    int n;
    cin >> n;
    vector<int> P(n);
    copy_n(istream_iterator<int>(cin), n, P.begin());
    SegmentTree<int,int> rmq(n,
                [](int a,int b){return max(a,b);},
                [](int a,int b){return b;},
                0);

    for (int i = 0; i < n; i++)
        rmq.update(i, P[i]);

    auto b_search = [&](auto ok, auto ng, auto check, auto i, auto r){
        while (abs(ok - ng) > 1){
            auto mid = (ok + ng) / 2;
            if (check(mid, r, i))
                ok = mid;
            else
                ng = mid;
        }
        return ok;
    };

    auto check = [&](auto mid, auto r, auto i){
        if (r < mid) swap(r, mid);
        return rmq.query(mid, r + 1) <= P[i];
    };

    int64_t ans = 0;
    for (int i = 0; i < n; i++){
        int l1 = b_search(i, -1, check, i, i);
        int l2 = b_search(max(0, l1 - 1), -1, check, i, max(0, l1 - 2));
        int r1 = b_search(i, n, check, i, i);
        int r2 = b_search(min(n - 1, r1 + 1), n, check, i, min(n - 1, r2 + 2));

        ans += (i - l1 + 1) * (r2 - r1) * P[i];
        ans += (r1 - i + 1) * (l1 - l2) * P[i];
    }

    cout << ans << endl;
}

