}

long think(vector<int> input) {
  auto n = input.size();
  auto dp = vector< vector<int> > (n, vector<int> (n, 0));

  for (int i = 0; i < n - 1; i++) {
    dp.at(i).at(i + 1) = min(input.at(i), input.at(i + 1));
  }

  for (int left = 0; left < n - 1; left++) {
    for (int right = left + 2; right < n; right++) {
      if (dp.at(left).at(right - 1) > input.at(right)) {
        dp.at(left).at(right) = dp.at(left).at(right - 1);
      } else {
        dp.at(left).at(right) = findSecondMaximum(input, left, right);
      }
    }
  }

  long total = 0;
  for (int left = 0; left < n - 1; left++) {
    for (int right = left + 1; right < n; right++) {
      total += dp.at(left).at(right);
    }
  }
  return total;
}

void write(long result) {
  cout << result << endl;
}

int findSecondMaximum(vector<int> input, int left, int right) {
  int maximum = 0;
  int secondMaximum = 0;

  for (int i = left; i <= right; i++) {
    if (maximum < input.at(i)) {
      secondMaximum = maximum;
      maximum = input.at(i);
      continue;
    }
    if (secondMaximum < input.at(i)) {
      secondMaximum = input.at(i);
    }
  }
  return secondMaximum;
}

