class Shakutori {
public:
  // 全体の範囲
  // [0, end)
  // 注目している範囲
  // [tail, head)
  Int head, tail, end = 0;
  bool moveHead() {
    if (head == end) {
      return false;
    }
    head++;
    return true;
  }
  void moveTail() { tail++; }
  bool valid() {
    if (head == tail)
      return true;
    // [tail, head)
    // が解として適当か検証する
    return true;
  }
  void solve() {
    head = tail = 0;
    Int ans = 0;
    while (moveHead()) {
      while (!valid()) {
        moveTail();
      }
      // ここで解を更新する
    }
  }
};

class Solver {
public:
  Int ans = 0, N;
  vi P;
  Solver() {}
  void input() {
    cin >> N;
    P = vi(N);
    FOR(p, P)cin>>p;
  }
  void solve() {
    vector<pii> V(N);
    rep(i, N){
      V[i] = {P[i],i };
    }
    rsort(V);


    set<Int> pos;
    FOR(v, V){
      pp(v.first);
      if(pos.size() != 0){
        auto rit = pos.upper_bound(v.second);
        Int rPos = N;
        Int lPos = -1;
        bool rightest = true;
        bool lefttest = true;
        // 自分が一番右ではない場合
        if(rit != pos.end()){
          rightest = false;
          rPos = *rit;
        }
        // 自分が一番左ではない場合
        auto lit = pos.upper_bound(v.second);
        if(lit != pos.begin()){
          lefttest = false;
          lit--;
          lPos = *lit;
        }
        if(!rightest){
          rit++;
          Int rPos2 = N;
          if(rit != pos.end()){
            rPos2 = *rit;
          }
          ans += (rPos2 - rPos) * (v.second - lPos) * v.first;
          pp(ans);
        }
        if(!lefttest){
          Int lPos2 = -1;
          if(lit != pos.begin()){
            lit--;
            lPos2 = *lit;
          }
          ans += (lPos - lPos2) * (rPos - v.second) * v.first;
          pp(ans);
        }
      }
      pos.insert(v.second);
    }
  }
  void output() {
    cout << ans <<endl;
  }
};

