            sqAns += sqNumCntR * sqNumCntL * num.sqNum;
        }


        /* 右側に自分より大きな数がいる */
        { 
            SQWORD sqNumCntL;
            if (lPos_l1 < 0) {
                sqNumCntL = num.sqIdx + 1;
            } else {
                sqNumCntL = num.sqIdx - lPos_l1;
            }

            SQWORD sqNumCntR;
