	for (int i = 1; i <= N; i++) {
		cin >> P[i];
		dat[i-1] = Pi(P[i], i);
	}
	sort(begin(dat), end(dat));

	vint nxt(N+2), prv(N+2);
	for (int i = 1; i <= N; i++) {
		nxt[i] = i+1;
		prv[i] = i-1;
	}

	ll ans = 0;
	for (int i = 0; i < N; i++) {
		ll v = dat[i].first, idx = dat[i].second;
		ll left = prv[idx];
		ll right = nxt[idx];
		//cout << " " << left << " " << right << endl;
		if (left > 0) {
			int left2 = prv[left];
			//cout << " " << left2 << endl;
