		}
		if (right <= N) {
			int right2 = nxt[right];
			//cout << "  " << right2 << endl;
			ans += (right2 - right) * (idx - left) * v;
		}
		nxt[left] = right;
		prv[right] = left;
	}
	cout << ans << endl;
}

