int main()
{
	int N;
	cin >> N;
	for (int i = 0; i < N; ++i)
	{
		cin >> P[i];
		P[i]--;
	}

	set<int> s;
	int index[MAX_N];
	ll ans = 0;

	for (int i = 0; i < N; ++i)
	{
		index[P[i]] = i;
	}

	for (int x = N-1; x >= 0; --x)
	{
		int i = index[x];
		ll c;
		//calc c
		s.insert(i);
		int l[2] = {-1,-1};
		int r[2] = {N,N};

		//calc l
		auto it = s.find(i);
		for (int j = 0; j < 2; ++j)
		{
			if (it == s.begin()) break;
			it--;
			l[j] = *it;
		}

		//calc r
		it = s.find(i);
		for (int j = 0; j < 2; ++j)
		{
			it++;
			if (it == s.end()) break;
			r[j] = *it;
		}

		int ls[2],rs[2];
		ls[0] = i-l[0];
		ls[1] = l[0]-l[1];
		rs[0] = r[0]-i;
		rs[1] = r[1]-r[0];
		c = (ll)ls[0]*rs[1] + (ll)ls[1]*rs[0];

		ans += c * (x+1);
	}
	cout << ans << endl;
	return 0;
