            r2[st2.back().first] = i;
            st2.pop_back();
        }
        int x = 0;
        while (!st.empty() && st.back().second < arr[i]) {
            r[st.back().first] = i;
            st2.push_back(st.back());
            st.pop_back();
            ++x;
        }
        reverse(st2.end() - x, st2.end());
        st.push_back({i, arr[i]});
    }
