    st2.clear();
    for (int i = n; i >= 1; --i) {
        while (!st2.empty() && st2.back().second < arr[i]) {
            l2[st2.back().first] = i;
            st2.pop_back();
        }
        int x = 0;
        while (!st.empty() && st.back().second < arr[i]) {
            l[st.back().first] = i;
            st2.push_back(st.back());
            st.pop_back();
            ++x;
