template<typename T>
struct SegmentTree{
private:
    typedef function<T(T, T)> F;
    int n;
    vector<T> node;
    T INF;
    F f;
public:
    SegmentTree(vector<T> v, T inf, F f): f(f){
        int vSize = v.size();
        n = 1;
        INF = inf;
        while(n < vSize){
            n *= 2;
        }
        node.resize(2*n-1, INF);
        for(int i = 0; i < vSize; i++){
            node[n-1+i] = v[i];
        }
        for(int i = n-2; i >= 0; i--){
            node[i] = f(node[i*2+1], node[i*2+2]);
        }
//        rep(i, 2*n-1){
//            cerr << i << " " << node[i].first << " " << node[i].second << endl;
//        }
    }
    void update(int x, int val){
        x += (n-1);
        node[x] = val;
        while(x > 0){
            x = (x-1)/2;
            node[x] = f(node[x*2+1], node[x*2+2]);
        }
    }
    T query(int a, int b, int k=0, int l=0, int r=-1){
        if(r < 0){
            r = n;
        }
        if(r <= a || b <= l){
            return INF;
        }
        if(a <= l && r <= b){
            return node[k];
        }
        T vl = query(a, b, 2*k+1, l, (l+r)/2);
        T vr = query(a, b, 2*k+2, (l+r)/2, r);
        return f(vl, vr);
    }
};

pair<ll,ll> fs(pair<ll,ll> a, pair<ll,ll> b){
    ll m = max(a.first, b.first);
    ll h1 = max(a.second, b.second);
    ll h2 = min(a.first, b.first);
    ll m2 = max(h1, h2);
    return make_pair(m, m2);
}

