    }
    SegmentTree<pair<ll,ll> > st(v, make_pair(-1,-1), fs);

    ll score = 0;
    for(ll i = 0; i < n-1; i++){
        for(ll j = i+1; j < n; j++){
//            cerr << i << " " << j << " " << st.query(i, j+1).first << " " << st.query(i, j+1).second << endl;
            score += st.query(i, j+1).second;
        }
    }

    cout << score << endl;

    return 0;
}

