void solve()
{
	READ(int, N);
	auto A = read<int>(N);
	vector<int> R(N);

	REP(i, N)
	{
		R[A[i] - 1] = i;
	}

	set<int> visited;

	llong ans = 0;
	RREP(i, N)
	{
		int index = R[i];

		visited.insert(index);
		auto it = visited.find(index);

		int c = *it;

		llong l = -1, ll = -1;
		auto lit = it;
		if (lit != visited.begin()) { --lit; l = *lit; }
		if (lit != visited.begin()) { --lit; ll = *lit; }

		llong r = N, rr = N;
		auto rit = it;
		if (rit != visited.end()) { ++rit; }
		if (rit != visited.end()) { r = *rit; ++rit; }
		if (rit != visited.end()) { rr = *rit; }

		ans += (l - ll) * (r - c) * (i + 1);
		ans += (rr - r) * (c - l) * (i + 1);
	}
	WRITE(ans);
}

