template<typename dtype, dtype initValue /*範囲外の時に返す値*/>
class RMQ{
public :

  struct data{
    bool type; //0 - empty   , 1 - update
    dtype value;
  };

  Int n,n_;
  vector<dtype> dat;
  vector<data> td;
  Int toMax;          //0 -> RangeMin 1->RangeMax;

  RMQ(){n=-1;}
  RMQ(Int n_, Int toMax = 0):n_(n_),toMax(toMax){
    n=1;
    while(n<n_)n*=2;
    td.resize(2*n-1,(data){0,initValue});
    dat.resize(2*n-1,initValue);
  }

  inline dtype merge(dtype a, dtype b){return toMax? max(a, b):min(a, b);}


  dtype dfs(Int a,Int b,dtype x,bool flag,Int k,Int l,Int r){
    if(r <= a || b <= l) return flag? dat[k]:initValue;
    if(a <= l && r <= b){
      if(flag == true){
        td[k]=(data){1,x};
        dat[k]=x;
      }
      return dat[k];
    }

    if(td[k].type){
      td[k].type = 0;
      dat[k*2+1] = dat[k*2+2] = td[k].value;
      td[k*2+1] = td[k*2+2] = (data){1,td[k].value};
    }

    dtype vl=dfs(a, b, x, flag, k*2+1, l, (l+r)/2);
    dtype vr=dfs(a, b, x, flag, k*2+2, (l+r)/2, r);
    return flag? (dat[k] = merge(vl, vr)):merge(vl,vr);
  }

  //[l,r)の値をxに変更　update(l,r,x)
  void update(Int l,Int r,dtype x){
    assert(l <= r), assert(l <= n && r <= n), assert(l >= 0 && r >= 0);
    dfs(l, r, x, true, 0, 0, n);
  }

  //[l,r)の最小値を得る　find(l,r);
  dtype get(Int l,Int r){
    assert(l <= r), assert(l <= n && r <= n), assert(l >= 0 && r >= 0);
    return dfs(l, r, initValue , false, 0 , 0 ,n);
  }
};

Int solve(Int N, vector<Int> A){
  vector<Int> Idx(N);
  for(Int i=0;i<N;i++) Idx[A[i]] = i;

  RMQ<Int, -INF> seg(N, 1);
  for(Int i=0;i<N;i++) seg.update(i, i+1, A[i]);

  auto get = [&](Int l, Int r){ //[l, r)
    Int top = seg.get(l, r);
    seg.update(Idx[top], Idx[top] + 1, -INF);
    Int top2 = seg.get(l, r);
    seg.update(Idx[top], Idx[top] + 1, top);
    return top2;
  };

  auto calc = [&](Int l){
    Int L = 0, R = N - l;
    while(L + 1 < R){
      Int M = (L + R) / 2;
      if( seg.get(l, l + M + 1) == A[l]) L = M;
      else R = M;
    }
    return l + L;
  };

  auto calc1 = [&](Int l, Int L){
    Int R = N - l;
    assert(get(l, l+L+1) == A[l]);
    while(L + 1 < R){
      Int M = (L + R) / 2;
      if( get(l, l + M + 1) == A[l] ) L = M;
      else R = M;
    }
    return l + L;
  };

  auto calc2 = [&](Int l){
    Int L = 0, R = l + 1;
    while(L + 1 < R){
      Int M = (L + R) / 2;
      if( seg.get(l - M, l+1) == A[l] ) L = M;
      else R = M;
    }
    return L;
  };

  Int ans = 0;
  //pr(A);
  for(Int i=0;i<N - 1;i++){
    Int numRight = calc(i) + 1;
    if(numRight == N) continue;
    Int len = calc1(i, numRight - i) - numRight + 1;
    Int numLeft = calc2(i) + 1;
    Int score = len * numLeft * (A[i] + 1);
    //pr(i, A[i], numRight, calc1(i, numRight - i), len, numLeft, score);
    ans += score;
  }
  return ans;
}

