class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}
    void run(){
        int N;
        is >> N;
        if(!is) return;
        vector<ll> A(N);
        max_queue<pair<int, int>> qi;
        for (int i = 0; i < N; ++i) {
            is >> A[i]; qi.emplace(A[i], i);
        } // end i
        multiset<int> S;
        S.insert(-1); S.insert(N);
        S.insert(-1); S.insert(N);

        ll ans = 0;
        while(!qi.empty()){
            ll index, val;
            tie(val, index) = qi.top(); qi.pop();
            ll r1, r2, l1, l2;
            auto lp = S.lower_bound(index);
            auto rp = lp--;
            r1 = *rp; l1 = *lp;
            lp--; rp++;
            r2 = *rp; l2 = *lp;

            ans += val * ((r2 - r1) * (index-l1) + (l1 - l2) * (r1- index));
            S.insert(index);
        }
        os << ans << endl;
    }
};

