int N;
int rev[123456];

int main() {
	cin >> N;
	for (int i = 0; i < N; ++i) {
		int tmp;
		cin >> tmp;
		--tmp;
		rev[tmp] = i;
	}
	multiset<int>S;
	S.insert(-1);
	S.insert(-1);
	S.insert(N);
	S.insert(N);
	LL ans = 0;
	for (int i = N - 1; i >= 0; --i) {
		auto r1 = S.lower_bound(rev[i]);
		auto r2 = next(r1);
		auto l1 = prev(r1);
		auto l2 = prev(l1);
		LL Ra = *r1 - rev[i];
		LL Rb = *r2 - *r1;
		LL La = rev[i] - *l1;
