bool cmp(pair<int, int> &a, pair<int, int> &b) {
    if (a.first != b.first)
        return a.first > b.first;
    return a.second < b.second;
}

int main()
{
    multiset<int> st;
    int n;
    cin >> n;
    vector<pair<int, int>> a(n + 1);
    for (int i = 1; i <= n; i++) {
        cin >> a[i].first;
        a[i].second = i;
    }
    st.insert(0);
    st.insert(0);
    st.insert(n + 1);
    st.insert(n + 1);
    ll ans = 0;
    sort(a.begin(), a.end(), cmp);
    for (int i = 0; i < n; i++) {
        ll idx = a[i].second;
        ll num = a[i].first;
        auto it = st.lower_bound(idx);
        ll x = *it;
        it++;
        ll y = *it;
        it--;
        it--;
        ll c = *it;
        it--;
        ll d = *it;
        ans += num * ((c - d) * (x - idx) + (idx - c) * (y - x));
        st.insert(idx);
    }
    cout << ans;
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

vector<int> lg;

template <typename T>
struct RMQ {
    int n;
    vector<vector<T>> table;
    RMQ(vector<int>& xs): n(xs.size()) {
        int K = lg[n] + 2;
        table = vector<vector<T>>(K, vector<T>(n, 0));
        for (int i = 0; i < n; ++i) {
            table[0][i] = xs[i];
        }
        for (int k = 1; k < K; ++k) {
            for (int i = 0; i < n; ++i) {
                int j = min(i + (1 << (k-1)), n-1);
                table[k][i] = max(table[k-1][i], table[k-1][j]);
            }
        }
    }
    T get_max(int i, int j) {
        int k = lg[j-i];
        return max(table[k][i], table[k][j - (1 << k)]);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    cin >> n;
    lg = vector<int>(n+1, 0);
    for (int i = 2; i <= n; ++i) {
        lg[i] = 1 + lg[i/2];
    }
    vector<int> ps(n);
    for (int& p : ps) {
        cin >> p;
    }
    vector<int> inv_p(n+1);
    for (int i = 0; i < n; ++i) {
        inv_p[ps[i]] = i;
    }
    RMQ<int> rmq(ps);
    function<long long (int, int)> calc_sum = [&](int l, int r) {
        if (r - l < 2) return 0LL;
        int m = inv_p[rmq.get_max(l, r)];
        deque<int> lefts, rights;
        int i = l-1;
        while (i < m-1) {
            i = inv_p[rmq.get_max(i+1, m)];
            lefts.push_back(i);
        }
        i = r;
        while (m+1 < i) {
            i = inv_p[rmq.get_max(m+1, i)];
            rights.push_back(i);
        }
        int current_left = m, current_right = m;
        int current = 0;
        long long sum = 0;
        while (!lefts.empty() || !rights.empty()) {
            if (lefts.empty() || (!rights.empty() && ps[rights.back()] < ps[lefts.back()])) {
                int new_right = rights.back();
                rights.pop_back();
                sum += ((long long) current) * ((long long) m - current_left + 1) * (new_right - current_right - 1);
                current = ps[new_right];
                current_right = new_right;
                sum += ((long long) current) * ((long long) m - current_left + 1);
            } else {
                int new_left = lefts.back();
                lefts.pop_back();
                sum += ((long long) current) * ((long long) current_right - m + 1) * (current_left - new_left - 1);
                current = ps[new_left];
                current_left = new_left;
                sum += ((long long) current) * ((long long) current_right - m + 1);
            }
        }
        // extending to [l, current_right]
        sum += ((long long) current) * ((long long) current_right - m + 1) * (current_left - l);
        // extending to [l, r-1]
        sum += ((long long) current) * ((long long) m - l + 1) * ((r-1) - current_right);
        return sum + calc_sum(l, m) + calc_sum(m+1, r);
    };
    cout << calc_sum(0, n) << endl;
    return 0;
}

