ll mx(ll l, ll r){
    ll u = c[r-l+1], d = 1<<u;
    return max(n[u][l], n[u][r-d+1]);
}

ll findl(ll p, ll x){
    ll l = -1, r = p+1;
    for(; l+1!=r;){
        ll md = (l+r)/2;
        if(mx(md, p)<x) r = md;
        else l = md;
    }
    return l;
}

ll findr(ll p, ll x){
    ll l = p-1, r = a;
    for(; l+1!=r;){
        ll md = (l+r)/2;
        if(mx(p, md)<x) l = md;
        else r = md;
    }
    return r;
}

