void solve(){
    input();
    int ans = 0;

    for(int l=0;l<N-1;l++){
        int fir = max(P[l], P[l+1]);
        int sec = min(P[l], P[l+1]);

        if(l == N -2 ){
            ans += sec;
            break;
        }
        for(int r=l+1;r<N;r++){
            if(P[r] <= sec)continue;
            else if(sec < P[r] && P[r] < fir){
                sec = P[r];
            }
            else if(fir < P[r]){
                sec = P[r];
                swap(sec, fir);
            }
            ans += sec;
        }
    }

    cout << ans << endl;
    return;
}
