  int n; cin >> n;
  vector<int> a(n), pos(n);
  for (int &z : a) cin >> z, --z;
  for (int i = 0; i < n; ++i) pos[a[i]] = i;
  set<int> s;
  vector<vector<int>> L(n, vector<int>(2, -1));
  vector<vector<int>> R(n, vector<int>(2, n));
  for (int i = n - 1; i >= 0; --i) {
    s.insert(pos[i]);
    auto it = s.find(pos[i]);
    if (it != s.begin()) {
      --it;
      for (int j = 0; j < 2; ++j) {
        L[pos[i]][j] = *it;
        if (it == s.begin()) break;
        --it;
      }
    }
    it = s.find(pos[i]);
    ++it;
    for (int j = 0; j < 2 && it != s.end(); ++j, ++it) {
      R[pos[i]][j] = *it;
    }
  }
  i64 ans = 0;
  for (int i = 0; i < n; ++i) {
    int l = 1, r = 1;
    if (L[i][0] != -1) {
      l = L[i][0] - L[i][1];
      r = R[i][0] - i;
      ans += (i64) l * r * (a[i] + 1);
    }
    if (R[i][0] != n) {
      r = R[i][1] - R[i][0];
      l = i - L[i][0];
      ans += (i64) l * r * (a[i] + 1);
    }
  }
  kek(ans);
}

