void solve() {
	int n; cin >> n;
    vector<P> p(n);
    rep(i, n) {
        ll x; cin >> x;
		p[i] = P(x, i);
    }
	sort(all(p));
	reverse(all(p));
	//自分より大きいもの位置さえわかれば良さそう
	//大きい順に考えればok
	ll ans = 0;
	multiset<int> se;
	se.insert(-1);
	se.insert(-1);
	se.insert(n);
	se.insert(n);
    rep(i, n) {
		ll y = p[i].fr; int k = p[i].sc;
		se.insert(k);
		auto ite = se.lower_bound(k);
		auto ma2 = ite, ma1 = ite, mi1 = ite, mi2 = ite;
		ma1 ++; ma2 ++; ma2 ++; mi1 --; mi2 --; mi2 --;
		ans += y * ((*ma2 - *ma1) * (*ite - *mi1) + (*mi1 - *mi2) * (*ma1 - *ite));
	}
	cout << ans << endl;
}

