ll n, m, d, p[114514];
vector<ll> maxi;

ll find_larger_element(ll val, ll idx, ll dir){
  // 特殊処理
  if (idx < 0) return -1;
  if (n <= idx) return n;
  // idx の次から数えて最初に val より大きなインデクスを返す． 
  if (dir==1){
    idx++;
    for(;;idx++){
      if (n <= idx) return n;
      if (idx % m == 0){
        if (maxi[idx/m] <= val){
          idx += m - 1;
          if (n <= idx) return n;
        }
      }
      if (p[idx] > val) return idx;     
    }
  }else{
    idx--;
    for(;;idx--){
      if (idx < 0) return -1;
      if (idx % m == m - 1){
        if (maxi[idx/m] <= val){
          idx -= m - 1;
          if (idx < 0) return -1;
        }
      }
      if (p[idx] > val) return idx;     
    }    
  }  
  return 0;
}


int main(){
  cin >> n;
  for(int i=0;i<n;i++) cin >> p[i];
  m = (ll) sqrt(n);
  d = (n + m - 1) / m;
  maxi = vector<ll>(d);
  for(int i=0;i<n;i++){
    maxi[i/m] = max(maxi[i/m], p[i]);
  }

  ll ans = 0;
  for(int i=0;i<n;i++){
    ll a = find_larger_element(p[i], i, -1);
    ll b = find_larger_element(p[i], a, -1);
    ll c = find_larger_element(p[i], i, 1);
    ll d = find_larger_element(p[i], c, 1);
    // cerr << a << b << c << d << endl;
    ans += p[i] * ((i-a)*(d-c) + (c-i)*(a-b));
  }

  cout << ans << endl;

  return 0;
}

