void build(int node,int st,int ed){
	if(st==ed){
		seg[node] = a[st];
		return;
	}
	build(2*node,st,(st+ed)/2);
	build(2*node+1,(st+ed)/2+1,ed);
	seg[node] = max(seg[2*node],seg[2*node+1]);
	return;
}
int query(int node,int st,int ed,int l,int r){
	if(l>r) return 0;
	if(ed<l||r<st) return 0;
	if(l<=st&&ed<=r) return seg[node];
	int a = query(2*node,st,(st+ed)/2,l,r);
	int b = query(2*node+1,(st+ed)/2+1,ed,l,r);
	return max(a,b);
}

int clc(int st,int ed,int val){
	if(st==0){
		int l = st;
		int r = ed;
		int ans = -1;
		while(l<=r){
			int mid = l+r;
			mid /= 2;
			int a = query(1,0,n-1,mid,r);
			if(a>val){
				ans = mid;
				l = mid+1;
			}
			else r = mid-1;
		}
		if(ans==-1) return -1;
		return ans;
	}else if(ed==n-1){
		int l = st;
		int r = ed;
		int ans = -1;
		while(l<=r){
			int mid = l+r;
			mid /= 2;
			int a = query(1,0,n-1,l,mid);
			if(a>val){
				ans = mid;
				r = mid-1;
			}
			else l = mid+1;
		}
		if(ans==-1) return n;
		return ans;
	}
}

