template <class T>
class SegmentTree {
public:
    SegmentTree(int size) {
        init(size);
    }

    void init(int size) {
        vec.clear();
        k = 1;
        while(k < size) {
            k *= 2;
        }
        for(int i = 0; i < 2*k; i++) {
            vec.push_back(T::unit());
        }
    }

    void update(int i, T x) { //iをxに変更する
        i += k-1;
        vec[i] = x;
        while(i > 0) {
            i = (i-1)/2;
            vec[i] = vec[i*2+1] + vec[i*2+2];
        }
    }

    T find(int l, int r) {
        return _find(l, r, 0, 0, k);
    }

private:
    vector<T> vec;
    int k;

    T _find(int l, int r, int k, int x, int y) {
        if (r <= x || y <= l) { //重なってない場合
            return T::unit();
        } else if (l <= x && y <= r) { //完全にかぶってる場合
            return vec[k];
        } else { //中途半端にかぶってる場合
            int mid = (x+y)/2;
            T lNode = _find(l, r, 2*k+1, x, mid);
            T rNode = _find(l, r, 2*k+2, mid, y);
            return lNode + rNode;
        }
    }
};

SegmentTree<Node> sg(MAX_N);

int solve()
{
  int ret = 0;
  REP(n,N) {
    int l, r, rr;

    int i = -1, j = n;
    while(j-i>1) {
      int mid = (i+j)/2;
      if(sg.find(mid, n).getValue() < P[n]) {
        j = mid;
      } else {
        i = mid;
      }
    }
    l = i;

    if(P[n+1] > P[n]) {
      r = n+1;
    } else {
      i = n+1, j = N;
      while(j-i>1) {
        int mid = (i+j)/2;
        if(sg.find(n+1, mid+1).getValue() < P[n]) {
          i = mid;
        } else {
          j = mid;
        }
        if(n == 5) {
          // cerr << i << " " << j << endl;
        }
      }
      r = min(N, j);
      if(n == 5) {
        // cerr << i << " " << j << endl;
      }
    }

    if(P[r+1] > P[n]) {
      rr = r+1;
    } else {
      i = r+1, j = N+1;
      while(j-i>1) {
        int mid = (i+j)/2;
        if(sg.find(r+1, mid+1).getValue() < P[n]) {
          i = mid;
        } else {
          j = mid;
        }
      }
      rr = min(N, j);
    }

    ret += (n-l) * (rr-r) * P[n];
    // cerr << n << " " << P[n] << " " << l << " " << r << " " << rr << endl;
    // cerr << (n-l) * (rr-r) * P[n] << endl;

  }
  return ret;
}

signed main()
{
  cin >> N;
  REP(n,N) {
    cin >> P[n];
    sg.update(n,Node(P[n]));
  }

  int ans = solve();

  reverse(P, P+N);
  REP(n,N) {
    sg.update(n, Node(P[n]));
  }

  ans += solve();

  cout << ans << endl;

  return 0;
}

