const int N = 1e6 + 7;

int n;
int fen[N][2];
void upd(int x, int val, int t) {
    for(; x < n; x |= (x + 1)) {
        (t ? setmax(fen[x][t], val) : setmin(fen[x][t], val));
    }
}
int get(int x, int t) {
    int res = (t ? -1 : INF);
    for(; x >= 0; x = (x & (x + 1)) - 1) {
        (t ? setmax(res, fen[x][t]) : setmin(res, fen[x][t]));
    }
    return res;
}


int najw[2][N];
int najw2[2];

pii a[N];

int main() {
    // BOOST;

    // re(n);
    scanf("%d", &n);
    FOR(i, n) {
        // re(a[i].F);
        scanf("%d", &a[i].F);
        a[i].S = i;
        fen[i][0] = INF;
        fen[i][1] = -1;
    }

    vi Q;
    FOR(i, n) {
        while(SZ(Q) and a[Q.back()] < a[i]) {
            Q.pop_back();
        }
        najw[0][i] = (SZ(Q) ? Q.back() : -1);
        Q.PB(i);
    }

    Q.clear();
    FOR(i, n - 1, 0, -1) {
        while(SZ(Q) and a[Q.back()] < a[i]) {
            Q.pop_back();
        }
        najw[1][i] = (SZ(Q) ? Q.back() : INF);
        Q.PB(i);
    }

    sort(a, a + n, [](const pii& a, const pii& b) {
        return a > b;
    });

    ll res = 0;
    FOR(k, n) {
        auto x = a[k];

        int id = x.S;
        auto p = najw[1][id];
        if(p != INF) {
            najw[1][id] = p - 1;
            p = get(n - 1 - (p + 1), 0);
            if(p != INF) {
                najw2[1] = p - 1; 
            } else {
                najw2[1] = n - 1;
            }
        } else {
            najw[1][id] = n - 1;
            najw2[1] = -1;
        }

        auto l = najw[0][id];
        if(l != -1) {
            najw[0][id] = l + 1;
            l = get(l - 1, 1);
            if(l != -1) {
                najw2[0] = l + 1;
            } else {
                najw2[0] = 0;
            }
        } else {
            najw[0][id] = 0;
            najw2[0] = -1;
        }

        upd(id, id, 1);
        upd(n - 1 - id, id, 0);

        int lnajw = id - najw[0][id] + 1;
        int pnajw = najw[1][id] - id + 1;
        if(najw2[1] != -1) {
            int pnajw2 = najw2[1] - najw[1][id];
            res += 1.0 * x.F * (1ll * lnajw * pnajw2);
        }
        if(najw2[0] != -1) {
            int lnajw2 = najw[0][id] - najw2[0];
            res += 1.0 * x.F * (1ll * pnajw * lnajw2);
        }
    }

   // res /= 1.0 * n * (n - 1) / 2;

    cout << res << "\n";
}

