			w = x;
		}
		else {
			w = *--t;
			++t;
		}
		++t;

		y = *++t;
		if (t == s.find(n)) {
			z = y;
		}
		else {
			z = *++t;
		}

		ans += p[i].first * ((x - w)*(y - p[i].second) + (p[i].second - x)*(z - y));
	}

	cout << ans << "\n";
 }

