			L1[P[i].second] = -1;
			L2[P[i].second] = -1;
		}
		else {
			L1[P[i].second] = *l1;
			auto l2 = tmp.upper_bound(*l1);
			if (l2 == tmp.end()) L2[P[i].second] = -1;
			else L2[P[i].second] = *l2;
		}
		tmp.insert(P[i].second);
	}
	set<ll> tmp2;
	for (ll i = 0; i < N; ++i) {
		auto r1 = tmp2.upper_bound(P[i].second);
