    for (int i = 0; i < n; ++i) {
        int p;
        std::cin >> p;
        p_to_i[p] = i;
    }
    std::set<int> indices;
    for (int i = 0; i < n; ++i) {
        indices.insert(i);
    }
    long long ans = 0;
    for (int p = 1; p < n; ++p) {
        int i = p_to_i[p];
        const auto it = indices.find(i);
        auto next = std::next(it);
        if (it == indices.begin()) {
            int r1 = *next;
            int r2 = (std::next(next) == indices.end()) ? n : *std::next(next);
            ans += p * (r2-r1) * (i+1);
        } else if (std::next(it) == indices.end()) {
            auto prev = std::prev(it);
            int l1 = *prev;
            int l2 = (prev == indices.begin()) ? -1 : *std::prev(prev);
            ans += p * (l1-l2) * (n-i);
        } else {
            auto next = std::next(it);
            auto prev = std::prev(it);
            auto l1 = *prev;
            auto r1 = *next;
            int l2 = (prev == indices.begin()) ? -1 : *std::prev(prev);
            int r2 = (std::next(next) == indices.end()) ? n : *std::next(next);
            ans += p * ((l1-l2) * (r1-i) + (i-l1) * (r2-r1));
        }

        indices.erase(i);
