const static ui NMAX = 100000;
static ui N;
static vector<ui> Pi;
static map<ui, ui> Pi_inv;

ui solve(void) {
  ul res = 0;
  multiset<ui> all;

  all.insert(0);
  all.insert(0);
  all.insert(N + 1);
  all.insert(N + 1);

  FORINV(P, 1, N + 1) {
    ul i = Pi_inv[P] + 1;

    auto it = all.lower_bound(i);
    ul wi = *prev(it, 2);
    ul xi = *prev(it, 1);
    ul yi = *it;
    ul zi = *next(it);

    ul Ci = (xi - wi) * (yi - i) + (i - xi) * (zi - yi);
    res += P * Ci;
    all.insert(i);
  }

  return res;
}

