struct RUP{
    int n; vector<ll> dat,laz;
    RUP(){}
    RUP(int n_){init(n_);}
    void init(int n_){
        n=1; while(n<n_) n*=2;
        dat.clear(); dat.resize(2*n-1,INF);
        laz.clear(); laz.resize(2*n-1,-INF);
    }
    inline void eval(int len,int k){
        if(laz[k]==-INF) return;
        if(k*2+1<n*2-1)laz[k*2+1]=laz[k],laz[k*2+2]=laz[k];
        dat[k]=laz[k];laz[k]=-INF;
    }
    ll update(int a,int b,ll x,int k,int l,int r){
        eval(r-l,k);
        if(r<=a||b<=l) return dat[k];
        if(a<=l&&r<=b) return laz[k]=x;
        eval(r-l,k);
        dat[k]=min(update(a,b,x,k*2+1,l,(l+r)/2),
        update(a,b,x,k*2+2,(l+r)/2,r));
        return dat[k];
    }
    void update(int a,int b,ll x){update(a,b,x,0,0,n);}
    ll query(int a,int b,int k,int l,int r){
        eval(r-l,k);
        if(r<=a||b<=l) return INF;
        if(a<=l&&r<=b) return dat[k];
        return min(query(a,b,k*2+1,l,(l+r)/2),query(a,b,k*2+2,(l+r)/2,r));
    }
    ll query(int a,int b){return query(a,b,0,0,n);}
};

int main(){
    int n; scanf("%d",&n);
    vector<int> a(n);
    rep(i,0,n)scanf("%d",&a[i]);
    RUP seg(n);//max
    rep(i,0,n){
        seg.update(i,i+1,-a[i]);
    }
    ll ans=0,add;
    int l[2],r[2],lb,rb,mid;//l0.l1.r0.r1
    rep(i,0,n){ add=1;
        lb=-1,rb=i;
        while(rb-lb>1){
            mid=(lb+rb)/2;
            if(seg.query(mid,i+1)<-a[i])lb=mid;
            else rb=mid;
        }
        l[1]=lb;
        lb=-1; rb=l[1];
        while(rb-lb>1){
            mid=(lb+rb)/2;
            if(seg.query(mid,l[1])<-a[i])lb=mid;
            else rb=mid;
        }
        l[0]=lb;
        lb=i,rb=n;
        while(rb-lb>1){
            mid=(lb+rb)/2;
            if(seg.query(i+1,mid+1)<-a[i])rb=mid;
            else lb=mid;
        }
        r[0]=rb;
        lb=r[0],rb=n;
        while(rb-lb>1){
            mid=(lb+rb)/2;
            if(seg.query(r[0]+1,mid+1)<-a[i])rb=mid;
            else lb=mid;
        }
        r[1]=rb;
        cerr<<l[0]<<l[1]<<r[0]<<r[1]<<endl;
        if(l[0]==l[1]&&r[0]==r[1])continue;
        add+=(l[1]-l[0])*(r[0]-i);
        add+=(i-l[1])*(r[1]-r[0]);
        add--;ans+=a[i]*add;
        cerr<<add<<endl;
    }
    printf("%lld\n",ans);
    return 0;
}

