int main() {
  int n;
  cin >> n;
  int p[n];
  int place[n];
  rep(i,n) cin >> p[i];
  rep(i,n) place[p[i]-1] = i;  // 0-indexed
  vector<bool> search(n,false);
  ll sum = 0;

  int L1, L2, R1, R2;
  rep(i,n-1) {
    int x = place[i];
    search[x] = true;
    int l=0, r=0;

    while (1) {
      ++l;
      if (x-l < 0) {
        L1 = l;
        break;
      }
      if (!search[x-l]) {
        L1 = l;
        break;
      }
    }
    if (x-l < 0) L2 = 0;
    else {
      while (1) {
        ++l;
        if (x-l < 0) {
          L2 = l-L1;
          break;
        }
        if (!search[x-l]) {
          L2 = l-L1;
          break;
        }
      }
    }

    while (1) {
      ++r;
      if (x+r > n-1) {
        R1 = r;
        break;
      }
      if (!search[x+r]) {
        R1 = r;
        break;
      }
    }
    if (x+r > n-1) R2 = 0;
    else {
      while (1) {
        ++r;
        if (x+r > n-1) {
          R2 = r-R1;
          break;
        }
        if (!search[x+r]) {
          R2 = r-R1;
          break;
        }
      }
    }

    sum += (L1*R2 + R1*L2) * ((ll)i+1);
  }

  cout << sum << endl;
  return 0;
}

