using namespace std;

template <typename T> class SegmentTree {
    const int array_size;        // もとの配列のサイズ
    int n;
    std::vector<T> data;
    std::function<T (T,T)> op;
    T unit;

public:
    enum Mode {
        RangeMinimumQuery,
        RangeMaximumQuery,
        RangeSummationQuery,
    };

    SegmentTree(int array_size, Mode mode) : array_size(array_size) {
        if (mode == RangeMinimumQuery) {
            unit = INT_MAX;
            op = [](T a, T b) { return std::min(a, b); };
        }
        else if (mode == RangeMaximumQuery) {
            unit = 0;
            op = [](T a, T b) { return std::max(a, b); };
        }
        else if (mode == RangeSummationQuery) {
            unit = 0;
            op = [](T a, T b) { return a + b; };
        }
        else {
            assert(false);
        }

        n = 1;
        while (n < array_size) { n *= 2; }   // _n以上の最小の2冪
        data.resize(2 * n - 1, unit);
    }

    template <typename F> SegmentTree(int array_size, T unit, F op) : array_size(array_size), unit(unit), op(op) {
        while (n < array_size) { n *= 2; }   // _n以上の最小の2冪
        data.resize(2 * n - 1, unit);
    }

    T access(int idx) {
        return data[idx + n - 1];
    }

    // array[idx] = x
    // O(log N)
    void update(int idx, T x) {
        assert(0 <= idx and idx < array_size);
        idx += n - 1;   // 木での対象のインデックス
        data[idx] = x;
        while (idx > 0) {
            idx = (idx - 1) / 2;                                    // 親のインデックス
            data[idx] = op(data[idx * 2 + 1], data[idx * 2 + 2]);   // 左の子と右の子
        }
    }

    // op(array[left, right))
    // O(log N)
    T query(int left, int right) {
        assert(0 <= left and left < right and right <= array_size);
        return query(left, right, 0, 0, n);
    }

private:
    // [a, b)の目的値をノードk（区間[l, r]）から検索
    T query(int a, int b, int k, int l, int r) {
        assert(a < b && l < r);
        // 範囲外
        if (r <= a || b <= l) {
            return unit;
        }
        // 完全に含む
        if (a <= l && r <= b) {
            return this->data[k];
        }
            // 一部含む
        else {
            T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);    // 左の子
            T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);    // 右の子
            return op(vl, vr);
        }
    }
};



class Find {
public:
    int N;
    unordered_map<int, vector<int>> m;
    SegmentTree<LL> st;
    Find(int N) : N(N), st(N, SegmentTree<LL>::RangeMaximumQuery) {

    }

    void set(int i, int x) {
        st.update(i, x);
    }

    // leftより右で一番最初に出会うx以上の値のindex(leftを含まない)
    int find_right_idx(const int x, const int left) {
        assert(0 <= left and left < N);
        if (left >= N) {
            return -1;
        }

        // 開区間(low, high)で条件を満たす一番左
        // (low, high)
        int low = left + 1;
        int high = N + 1;
        while (high - low > 1) {
            auto middle = (low + high) / 2;
            if (st.query(left + 1, middle) >= x) {
                high = middle;
            }
            else {
                low = middle;
            }
        }

        if (high == N + 1) {
            return -1;
        }

        return high - 1;
    }

    // rightより左で一番最初に出会うx以上の値のindex(rightを含まない)
    int find_left_idx(int x, int right) {
        assert(0 <= right and right < N);

        if (right <= 0) {
            return -1;
        }

        int low = -1;
        int high = right;
        while (high - low > 1) {
            auto middle = (low + high) / 2;
            if (st.query(middle, right) >= x) {
                low = middle;
            }
            else {
                high = middle;
            }
        }

        return low;
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    LL N;
    cin >> N;

    auto P = make_v<LL>(N);
    Find f(N);
    FOR(i, 0, N) {
        cin >> P[i];
        f.set(i, P[i]);
    }

    LL ans = 0;
    FOR(i, 0, N) {
        auto x = P[i];

        int a = - 1, b = -1, c = -1, d = -1;
        b = f.find_left_idx(x, i);
        if (b != -1) {
            a = f.find_left_idx(x, b);
        }
        c = f.find_right_idx(x, i);
        if (c != -1) {
            d = f.find_right_idx(x, c);
        }

        if (b == -1 and c == -1) {
            continue;
        }

        LL count = 0;

        // i - c
        if (c != -1) {
            LL left = 0;
            // b - i
            if (b == -1) {
                left += i;
            }
            else {
                left += (i - b - 1);
            }

            LL right = 0;
            // c - d
            if (d == -1) {
                d = N;
            }
            right += (d - c - 1);

            count += (left + 1) * (right + 1);
        }

        // b - i
        if (b != -1) {
            LL left = 0;
            // a - b
            if (a == -1) {
                left += b;
            }
            else {
                left += (b - a - 1);
            }

            LL right = 0;
            // c - i
            if (c == -1) {
                right += (N - i - 1);
            }
            else {
                right += (c - i - 1);
            }

            count += (left + 1) * (right + 1);
        }

        ans += x * count;
    }

    print(ans);

    return 0;
}

