    rep(i,n) idx[a[i]] = i;
    //このためにa[i]--したのかな？
    set<int> s;
    ll ans=0;
    for(int x= n-1;x>=0;x--){
        //大きい順に.
        //今回、問題設定より、最大値はn,
        //全て異なる値ってのが決まっている。
        int i = idx[x];
        //お手軽index取得.こういう問題設定の時しか無理そうだけど。
        ll c = 0;
        { // calc c
            s.insert(i);
            vector<int> l(2,-1);
            vector<int> r(2,n);
            //チェックしたものをここに保存.
            {//calc l
              auto it = s.find(i);
              rep(j,2){
                if(it == s.begin())break;
                --it;
                l[j]=*it;
              }
            //setのiterator
            }
            {//calc r
              auto it = s.find(i);
              rep(j,2){
                  ++it;
                  if(it == s.end())break;
                  r[j] = *it;
              }
            }
            vector<int> ls(2);
            ls[0] = i-l[0]; ls[1] = l[0] - l[1];
            vector<int> rs(2);
            rs[0] = r[0]-i; rs[1] = r[1] - r[0];
            c = (ll)ls[0]*rs[1] + (ll)ls[1]*rs[0];
