template<class M=int> struct segmaxi {  /*@formatter:off*/  int n;    vector<int> seg;    vector<M> dat;    int e;    void build(vector<M> datt) {        dat = datt;        e = sz(dat);        dat.emplace_back(ev);        n = 1;        int asz = dat.size();        while (n <= asz)n <<= 1;        seg.assign((n << 1) - 1, e);        rep(i, asz) seg[i + n - 1] = i;        rer(i, n - 2)seg[i] = f(seg[(i << 1) | 1], seg[(i << 1) + 2]);    }    segmaxi();    void update(int k, M v) {   if(k==-1)return ;     dat[k] = v;        k += n - 1;        while (k) {            k = (k - 1) >> 1;            seg[k] = f(seg[(k << 1) | 1], seg[(k << 1) + 2]);        }    }    void del(int k) { if(k!=-1)update(k, ev); }    void add(int k, int v) { update(k, v + seg[k + n - 1]); }    M operator[](int k) {if(k==-1)return ev; else return dat[seg[k + n - 1]]; }    int query(int l, int r) {        M retl = e;        M retr = e;        l += n - 1;        r += n - 1;        while (l < r) {            /*右なら、次に右上へ移動してしまうので*/            if (!(l & 1)) { retl = f(retl, seg[l]); }            /*右なら、左を取らないと機会を逃す*/            if (!(r & 1)) { retr = f(seg[r - 1], retr); }            l >>= 1;            r = (r - 1) >> 1;        }        return f(retl, retr);    }    int geti(int l,int r) {        int v= query(l, min(r, n)); if(v==e)return -1;return v;    }    int geti(int r) {        int v= query(0, min(r, n));  if(v==e)return -1;return v;  }    int geti() {        int v= query(0, n); if(v==e)return -1 ;return v ;  }    int getir(int m) {        int v=query(m, n); if(v==e)return -1 ;return v ;   }    M get(int l,int r) {        return operator[](geti(l, r));    }    M get(int r) {        return operator[](geti(r));    }    M get() {        return operator[](geti());    }    M getr(int m){return operator[](getir(m));}
     const M ev = MIN(M);
