LL dp[25][400005];
LL LOG[400005];

void init(){
	LOG[0] = -1;
	for(LL i = 1;i <= n;i ++) LOG[i] = LOG[i >> 1] + 1;
	for(LL i = 0;i <= n;i ++) dp[0][i] = a[i];
	for(LL i = 1;i <= 20;i ++){
		for(LL j = 0;j <= n;j ++){
			if(j + (1 << (i - 1)) > n) break;
			dp[i][j] = max(dp[i - 1][j],dp[i - 1][j + (1 << (i - 1))]);
		}
	}
}

LL query(LL x,LL y){
	LL k = LOG[y - x + 1];
	return max(dp[k][x],dp[k][y - (1LL << k) + 1]);
}

