void solve()
{
	ll N;  cin >> N;
	vector<ll> P = cinv<ll>(N);

	vll idx(N+1); //idx[val]=i;
	rep(i, 0, N-1){
		idx[P[i]]=i;
	}

	set<ll> buf;
	buf.insert(-1);
	buf.insert(N);

	ll ans=0;
	dep(val, N, 1){
		ll c = idx[val];
		buf.insert(c);
		auto it = buf.find(c);
		auto itl = it;
		auto itr = it;
		itl--;
		itr++;
		ll l = *itl;
		ll r = *itr;
		if (l != -1){
			itl--;
			ll l2 = *itl;
			ans += (l-l2)*(r-c)*val;
		}
		if (r != N){
			itr++;
			ll r2 = *itr;
			ans += (r2-r)*(c-l)*val;
		}
	}
	cout << ans << '\n';
}


