#define int long long
int const maxn = 1e5 + 5;
int a[maxn];
int tree[4 * maxn];

void build(int i, int l, int r) {
    if (r - l == 1) tree[i] = a[l];
    else {
        int m = (r + l) / 2;
        build(2 * i + 1, l, m);
        build(2 * i + 2, m, r);
        tree[i] = max(tree[2 * i + 1], tree[2 * i + 2]);
    }
}

int gett(int i, int l, int r, int lq, int rq) {
    if (lq >= r || l >= rq) return 0;
    if (lq <= l && r <= rq) return tree[i];
    int m = (r + l) / 2;
    return max(gett(2 * i + 1, l, m, lq, rq), gett(2 * i + 2, m, r, lq, rq));
}

