            if (x > a[i]) lef = mid;
            else righ = mid;
        }
        start_l = lef;
        lef = 0, righ = start_l;
        while (righ - lef > 1) {
            int mid = (righ + lef) / 2;
            int x = gett(0, 1, n + 1, mid, start_l);
            if (x > a[i]) lef = mid;
            else righ = mid;
        }
        stop_l = lef;
        lef = i, righ = n + 1;
        while (righ - lef > 1) {
            int mid = (righ + lef) / 2;
            int x = gett(0, 1, n + 1, i + 1, mid + 1);
            if (x > a[i]) righ = mid;
            else lef = mid;
        }
        start_r = righ;
        lef = start_r, righ = n + 1;
        while (righ - lef > 1) {
            int mid = (righ + lef) / 2;
            int x = gett(0, 1, n + 1, start_r + 1, mid + 1);
            if (x > a[i]) righ = mid;
            else lef = mid;
        }
        stop_r = righ;
        //cout << start_l << " " << stop_l << " " << start_r << " " << stop_r << '\n';
        ans += a[i] * ((i - start_l) * (stop_r - start_r) + (start_r - i) * (start_l - stop_l));
    }
