const ll MOD = 1000000007ll;

int n;
int p[125252];
int rev[125252];

const int N = 1<<17;
pii dat[2*N];

pii merge(pii a, pii b){
    int x[4] = {a.first, a.second, b.first, b.second};
    sort(x,x+4);
    return pii(x[3], x[2]);
}
pii query(int l, int r, int a, int b, int k){
    if(r<=a || b<=l)return pii(-1,-1);
    if(l<=a && b<=r)return dat[k];
    int m = (a+b)/2;
    pii x = query(l,r,a,m,2*k+1);
    pii y = query(l,r,m,b,2*k+2);
    return merge(x,y);
}

ll solve(int l, int r){
    if(r-l <= 1)return 0;
    pii mxs = query(l,r,0,N,0);
    int ml = min(rev[mxs.first], rev[mxs.second]);
    int mr = max(rev[mxs.first], rev[mxs.second]);
    ll val = mxs.second;
    ll ret = val * (ml-l+1) * (r-mr);
    ret += solve(ml+1,r);
    ret += solve(l,mr);
    ret -= solve(ml+1,mr);
    return ret;
}

