    scanf("%d",&n);
    REP(i,n)scanf("%d",p+i);
    REP(i,n)rev[p[i]] = i;
    REP(i,n)dat[i+N-1] = pii(p[i],-1);
    FORR(i,0,N-1){
        dat[i] = merge(dat[2*i+1], dat[2*i+2]);
    }
    ll ans = solve(0,n);
    printf("%lld\n",ans);
    return 0;
}

