			r[i][j]=r[i][j-1];
		for (int i=n+1;i>=0;i--)
		if (i-(1ll<<(j-1))>=0) l[i][j]=max(l[i][j-1],l[i-(1ll<<(j-1))][j-1]);else
			l[i][j]=l[i][j-1];
	}
	ll ans=0;
	for (int i=1;i<=n;i++){
		int L=i-1,R=i+1;
		for (int j=lg[n];j>=0;j--){
			if (L-(1ll<<j)>=0&&l[L][j]<a[i]) L=L-(1ll<<j);
			if (R+(1ll<<j)<=n+1&&r[R][j]<a[i]) R=R+(1ll<<j);
		}
		int mxl=L,mxr=R;
		L--,R++;
		for (int j=lg[n];j>=0;j--){
			if (L-(1ll<<j)>=0&&l[L][j]<a[i]) L=L-(1ll<<j);
			if (R+(1ll<<j)<=n+1&&r[R][j]<a[i]) R=R+(1ll<<j);
		}
		//printf("%d %d %d %d\n",mxl,mxr,L,R);
		if (mxr<=n) ans+=1ll*a[i]*(i-mxl)*(R-mxr);
		if (mxl>0) ans+=1ll*a[i]*(mxr-i)*(mxl-L);
		//printf("i=%d %lld\n",i,ans);
	}
	printf("%lld\n",ans);
	return 0;
}

