using int64 = long long;
using uint64 = unsigned long long;

const int N = 100000 + 5;

int n , A[N];

int64 Ans;

#define mid ((l + r) >> 1)

#define lson rt << 1
#define rson rt << 1 | 1

int mx[N] , mx2[N];

void build(int rt , int l , int r)
{
	if(l == r)
	{
		mx[rt] = A[l] , mx2[rt] = 0;
		return ;
	}
	build(lson , l , mid);
	build(rson , mid + 1 , r);
	static int d[10] , c = 0;
	c = 0;
	d[++c] = mx[lson];
	d[++c] = mx[rson];
	d[++c] = mx2[lson];
	d[++c] = mx2[rson];
	sort(d + 1 , d + 1 + c);
	mx[rt] = d[c] , mx2[rt] = d[c - 1];
}

pair<int , int> query(int rt , int l , int r , int x , int y)
{
	if(x <= l && r <= y) return make_pair(mx[rt] , mx2[rt]);
	int d[5] , c = 0;
	rep(i , 1 , 4) d[i] = 0;
	c = 0;
	if(x <= mid)
	{
		pair<int , int> ret = query(lson , l , mid , x , y);
		d[++c] = ret.first;
		d[++c] = ret.second;
	}
	c = 2;
	if(y > mid)
	{
		pair<int , int> ret1 = query(rson , mid + 1 , r , x , y);
		d[++c] = ret1.first;
		d[++c] = ret1.second;
	}
	c = 4;
	sort(d + 1 , d + 1 + c);
	return make_pair(d[c] , d[c - 1]);
}

pair<int , int> halfd(int L , int R)
{
	int l = L , r = R , ret = r , d = A[r];
	while(l <= r)
	{
		if(query(1 , 1 , n , mid , R).first <= d)
		{
			ret = mid , r = mid - 1;
		}
		else l = mid + 1;
	}
	l = L , r = ret - 1;
	int ret2 = -1;
	while(l <= r)
	{
		auto RT = query(1 , 1 , n , mid , R);
		if(RT.second <= d)
		{
			if(RT.second == d) ret2 = mid;
			r = mid - 1;
		}
		else l = mid + 1;
	}
	return make_pair(ret2 , ret);
}

pair<int , int> halfu(int L , int R)
{
	int l = L , r = R , ret = l , d = A[l];
	while(l <= r)
	{
		//cerr << l << ' ' << r << ' ' << mid << endl;
		if(query(1 , 1 , n , L , mid).first <= d)
		{
			ret = mid , l = mid + 1;
		}
		else r = mid - 1;
	}
	l = ret + 1 , r = R;
	int ret2 = -1;
	while(l <= r)
	{
		auto RT = query(1 , 1 , n , L , mid);
		if(RT.second <= d)
		{
			if(RT.second == d) ret2 = mid;
			l = mid + 1;
		}
		else r = mid - 1;
	}
	return make_pair(ret , ret2);
}

int main()
{
	read(n);
	rep(i , 1 , n) read(A[i]);
	build(1 , 1 , n);
	rep(i , 1 , n)
	{
		auto L = halfd(1 , i);
		auto R = halfu(i , n);
		int64 val = 1;

		if(L.first == -1 && R.second == -1) continue;
		if(L.first != -1 && R.second != -1)
		{
			val *= 1ll * (L.second - L.first) * (R.second - R.first);
		}
		else
		{
			if(L.first != -1) val *= 1ll * (L.second - L.first);
			if(R.second != -1) val *= 1ll * (R.second - R.first);
		}
		Ans += val * A[i];
	}
	cout << Ans << endl;
	return 0;
}

