      p2 = n - i;
    } else {
      p2 = *c - i;
    }
    if (a == s.rend()) {
      if (b == s.rend()) {
        p3 = 0;
      } else {
        p3 = *b + 1;
      }
    } else {
      p3 = *b - *a;
    }
    if (d == s.end()) {
      if (c == s.end()) {
        p4 = 0;
      } else {
        p4 = n - *c;
      }
    } else {
      p4 = *d - *c;
    }

    // cout << p << ":" << p1 << "," << p2 << "," << p3 << "," << p4 << endl;
    ans += p * (p1 * p4 + p2 * p3);
  }
  cout << ans << endl;
  return 0;
}

