int dp[100001][17], power[17];
int f(int l, int r) {
    int m = log2(r - l + 1);
    return max(dp[l][m], dp[r - power[m] + 1][m]);
}

int main() {
//    cout << setprecision(10);
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);

    int n;
    cin >> n;
    int a[n];
    for (int i = 0; i < n; i++) cin >> a[i];

    for (int i = 0; i < n; i++) dp[i][0] = a[i];
    power[0] = 1;
    for (int i = 1; i < 17; i++) power[i] = power[i - 1] * 2;

    for (int j = 1; j < 17; j++) {
        for (int i = 0; i < n; i++) {
            if (i + power[j] <= n)
            dp[i][j] = max(dp[i][j - 1], dp[i + power[j - 1]][j - 1]);
        }
    }

    ll ans = 0;

    for (int i = 0; i < n; i++) {
        int l = i + 1, r = n - 1, mid;
        int r1 = n, r2 = n, l1 = -1, l2 = -1;
        while (l <= r) {
            mid = (l + r) / 2;
            if (f(i + 1, mid) > a[i]) {
                r1 = mid;
                r = mid - 1;
            }

            else {
                l = mid + 1;
            }
        }

        l = r1 + 1, r = n - 1;
        while (l <= r) {
            mid = (l + r) / 2;
            if (f(r1 + 1, mid) > a[i]) {
                r2 = mid;
                r = mid - 1;
            }

            else {
                l = mid + 1;
            }
        }

        l = 0, r = i - 1;
        while (l <= r) {
            mid = (l + r) / 2;
            if (f(mid, i - 1) > a[i]) {
                l2 = mid;
                l = mid + 1;
            }
            else {
                r = mid - 1;
            }
        }

        l = 0, r = l2 - 1;
        while (l <= r) {
            mid = (l + r) / 2;
            if (f(mid, l2 - 1) > a[i]) {
                l1 = mid;
                l = mid + 1;
            }
            else {
                r = mid - 1;
            }
        }

//        cout << l1 << ' ' << l2 << ' ' << r1 << ' ' << r2 << '\n';

        ans += a[i] * ((r2 - r1) * (i - l2) + (l2 - l1) * (r1 - i));

    }

    cout << ans;

}

