	order.insert(N+1);
	order.insert(0);
	decltype(order)::iterator x,y,w,z;
	for (long long i=N-1;i>0;i--)
	{

		x=order.upper_bound(place[i]);
		if (*x!=N+1) y=order.upper_bound(*x);
		else y=x;
		w=order.lower_bound(place[i]);
		if (*w!=0) 
		{
			w--;
			z=order.lower_bound(*w);
			if (*z!=0) z--;
		}
		else z=w;
		ans+=i*((long long)*y-(long long)*x)*(place[i]-(long long)*w);
		ans+=i*((long long)*w-(long long)*z)*((long long)*x-place[i]);
		order.insert(place[i]);
	}
	cout << ans << endl;
return 0;
