const ll N = 1e6 + 100, OO = 1e10 + 10, M = 1e9 + 7, lg = 22;
typedef pair <int, int> pii;
int a[N];
pii seg[N], seg2[N];

void build(int c, int b, int e) {
	if(e - b == 1) {
		seg[c].ff = a[b];
		seg[c].ss = b;
		return;
	}
	int mid = (b + e) / 2;
	build(2 * c, b, mid);
	build(2 * c + 1, mid, e);
	seg[c].ff = max(seg[2 * c].ff, seg[2 * c + 1].ff);
	if(seg[c].ff == seg[2 * c + 1].ff)
		seg[c].ss = seg[2 * c + 1].ss;
	else
		seg[c].ss = seg[2 * c].ss;
}

int ans(int c, int b, int e, int q) {
	if(e - b == 1) 
		return seg[c].ss;
	int mid = (b + e) / 2;
	if(seg[2 * c + 1].ff > q) 
		return ans(2 * c + 1, mid, e, q);
	else
		return ans(2 * c, b, mid, q);
}

int get(int c, int b, int e, int l, int r, int q) {
	if(r - l <= 0)
		return -1;
	if(b == l && r == e) {
		if(seg[c].ff < q)
			return -1;
		return ans(c, b, e, q);
	}
	int mid = (b + e) / 2;
	if(r <= mid) 
		return get(2 * c, b, mid, l, r, q);
	if(l >= mid)
		return get(2 * c + 1, mid, e, l, r, q);
	int z = get(2 * c + 1, mid, e, mid, r, q);
	if(z == -1)
		return get(2 * c, b, mid, l, mid, q);
	else
		return z;
}

void build2(int c, int b, int e) {
	if(e - b == 1) {
		seg2[c].ff = a[b];
		seg2[c].ss = b;
		return;
	}
	int mid = (b + e) / 2;
	build2(2 * c, b, mid);
	build2(2 * c + 1, mid, e);
	seg2[c].ff = max(seg2[2 * c].ff, seg2[2 * c + 1].ff);
	if(seg2[c].ff == seg2[2 * c].ff)
		seg2[c].ss = seg2[2 * c].ss;
	else
		seg2[c].ss = seg2[2 * c + 1].ss;
}

int ans2(int c, int b, int e, int q) {
	if(e - b == 1) 
		return seg2[c].ss;
	int mid = (b + e) / 2;
	if(seg2[2 * c].ff > q) 
		return ans2(2 * c, b, mid, q);
	else
		return ans2(2 * c + 1, mid, e, q);
}

int get2(int c, int b, int e, int l, int r, int q) {
	if(r - l <= 0)
		return -1;
	if(b == l && r == e) {
		if(seg2[c].ff < q)
			return -1;
		return ans2(c, b, e, q);
	}
	int mid = (b + e) / 2;
	if(r <= mid) 
		return get2(2 * c, b, mid, l, r, q);
	if(l >= mid)
		return get2(2 * c + 1, mid, e, l, r, q);
	int z = get2(2 * c, b, mid, l, mid, q);
	if(z == -1)
		return get2(2 * c + 1, mid, e, mid, r, q);
	else
		return z;
}

