void solve() {  
    int n; cin >> n;
    int pos[n+1]; pos[0] = 0;
    for(int i=1; i<=n; i++) {
        int x; cin >> x;
        pos[x] = i;
    }
    int ans = 0;
    multiset<int> s;
    s.insert(0); s.insert(0);
    s.insert(n+1); s.insert(n+1);
    s.insert(pos[n]);
    for(int cur=n-1; cur>0; cur--) {
        int l1, l2, r1, r2;
        int cp = pos[cur];
        auto it = s.lower_bound(cp); 
        r1 = *it; 
        auto it2 = it;
        it2++;
        r2 = *it2;
        it2 = (--it);
        l1 = *it2;
        l2 = *(--it2);
        //cout << l1 << " " << l2 << " " << r1 << " " << r2 << endl;
        ans += cur * ((cp-l1)*(r2-r1) + (l1-l2)*(r1-cp));
        s.insert(cp);
    }
    cout << ans << endl;
}

