int firstAtLeast(int L, int R, int K){ /// first index in range [L,R] where value>=K
    if (R < L)
        return -1;
    //cout << L << ", " << R << " ? " << K << "\n";
    int node = L+n-1; //find L in the tree

    //go up and right until we find a subtree that has a value >= K

    while(t[node] < K){

        //if we are a right child of our parent, go up until
        //we have a right sibling
        while( (node&1) == 1 ) {//node is odd
            node = node>>1;    //same as floor(node/2);
            if (node <= 1)
                //we went up to the root
                //there is no such element
                return -1;
                //break;
        }
        //now node is a left child.  try its right sibling        
        ++node;
    }
    //We found a subtree.  get the first valid leaf

    while(node < n) {//while it's an internal node
       node = 2*node; //left child of the node
       if (t[node] < K)
           ++node;  //left child not valid - move to right child
    }
    //Found leaf.  get index in A[i] and check against R

    int index = node-(n-1);
    return (index <= R ? index : -1);
}
int lastAtLeast(int L, int R, int K){ /// last index in range [L,R] where value>=K
    //cout << L << " " << R << " " << K << "!\n";
    if (R < L)
        return -1;

    int node = R+n-1; //find L in the tree

    //go up and right until we find a subtree that has a value >= K

    while(t[node] < K){

        //if we are a right child of our parent, go up until
        //we have a right sibling
        while( (node&1) == 0 ) {//node is odd
            node = node>>1;    //same as floor(node/2);
            if (node <= 1)
                //we went up to the root
                //there is no such element
                return -1;
               // break;
        }
        //now node is a left child.  try its right sibling        
        --node;
    }
    //We found a subtree.  get the first valid leaf

    while(node < n) {//while it's an internal node
       node = 2*node+1; //left child of the node
       if (t[node] < K)
           --node;  //left child not valid - move to right child
    }
    //Found leaf.  get index in A[i] and check against R

    int index = node-(n-1);
    return (index >= L ? index : -1);
}
