		if(x<=(s+e)/2)	update(seg[idx].l, s, (s+e)/2, x);
		else	update(seg[idx].r, (s+e)/2+1, e, x);
	}
	int Sum(int x, int y){
		return sum(0, 1, SZ, x, y);
	}
	int sum(int idx, int s, int e, int x, int y){
		if(x<=s && e<=y)	return seg[idx].sum;
		else if(x>e || y<s)	return 0;
		return sum(seg[idx].l, s, (s+e)/2, x, y) + sum(seg[idx].r, (s+e)/2+1, e, x, y);
	}
};

SEG Seg;

int right(int x, int y){
	int s = x, e = N, m;
	while(s<e){
		m = (s+e)/2+1;
		if(Seg.Sum(x, m)<=y){
			s = m;
		}else{
			e = m-1;
		}
	}
	return s;
}

int left(int x, int y){
	int s = 1, e = x, m;
	while(s<e){
		m = (s+e)/2;
		if(Seg.Sum(m, x)<=y){
			e = m;
		}else{
			s = m+1;
		}
	}
	return s;
}

