ll rec(ll begin, ll end, ll maximum, const SegmentTree<ll>& tree, map<ll, ll>& index) {
  if (end - begin < 2) return 0;
  if (maximum == 0) maximum = tree.Aggregate(begin, end);
  ll maximum_i = index[maximum];
  ll second_maximum = max(tree.Aggregate(begin, maximum_i),
                          tree.Aggregate(maximum_i + 1, end));
  ll second_maximum_i = index[second_maximum];
  ll left = min(maximum_i, second_maximum_i);
  ll right = max(maximum_i, second_maximum_i);
  dbg(begin, end, maximum, second_maximum);
  dbg(begin, end, left, right);
  return (left - begin + 1) * (end - right) * second_maximum +
      rec(begin, right, (left == maximum_i ? maximum : second_maximum), tree, index) +
      rec(left + 1, end, (right == maximum_i ? maximum  : second_maximum), tree, index) -
      rec(left + 1, right, 0, tree, index);
}

int main() {
  in(ll, n);
  SegmentTree<ll> tree(n, [](ll a, ll b) { return max(a, b); });
  map<ll, ll> index;
  rep(i, n) {
    in(ll, p);
    tree.Set(i, p);
    index[p] = i;
  }
  out(rec(0, n, n, tree, index));
}

