void RightSuns(vector<pair<long long, long long>>& rez, vector<long long>& a) {
	vector<long long> f_stack;
	vector<long long> s_stack;
	vector<long long> dimas;
	for (long long i = 0; i < a.size(); ++i) {
		while (!s_stack.empty() && s_stack.back() < a[i]) {
			rez[s_stack.back() - 1].second = i;
			s_stack.pop_back();
		}
		while (!f_stack.empty() && f_stack.back() < a[i]) {
			rez[f_stack.back() - 1].first = i;
			dimas.push_back(f_stack.back());
			f_stack.pop_back();
		}
		while (!dimas.empty()) {
			s_stack.push_back(dimas.back());
			dimas.pop_back();
		}
		f_stack.push_back(a[i]);
	}
}

void LeftSuns(vector<pair<long long, long long>>& rez, vector<long long>& a) {
	vector<long long> f_stack;
	vector<long long> s_stack;
	vector<long long> dimas;
	for (long long i = a.size() - 1; i >= 0; --i) {
		while (!s_stack.empty() && s_stack.back() < a[i]) {
			rez[s_stack.back() - 1].second = i;
			s_stack.pop_back();
		}
		while (!f_stack.empty() && f_stack.back() < a[i]) {
			rez[f_stack.back() - 1].first = i;
			dimas.push_back(f_stack.back());
			f_stack.pop_back();
		}
		while (!dimas.empty()) {
			s_stack.push_back(dimas.back());
			dimas.pop_back();
		}
		f_stack.push_back(a[i]);
	}
}

int main() {

	long long n, ans = 0;
	cin >> n;
	vector<long long> a(n);
	vector<pair<long long, long long>> left_suns(n, { -1, -1 });
	vector<pair<long long, long long>> right_suns(n, { n, n });
	for (long long i = 0; i < n; ++i) {
		cin >> a[i];
	}

	LeftSuns(left_suns, a);
	RightSuns(right_suns, a);

	for (long long i = 0; i < n; ++i) {
		if (left_suns[a[i] - 1].first == -1 && right_suns[a[i] - 1].first == -1) {
			continue;
		}
		ans += a[i] * (left_suns[a[i] - 1].first - left_suns[a[i] - 1].second) * (right_suns[a[i] - 1].first - i);
		ans += a[i] * (right_suns[a[i] - 1].second - right_suns[a[i] - 1].first) * (i - left_suns[a[i] - 1].first);
	}
	cout << ans;
}

