  }

  auto f = [](int a, int b){return min(a,b);};
  auto g = [](int a, int b){return max(a,b);};

  SegmentTree<int> segL(g,-1), segR(f,n);
  segL.build(vec(n,-1));
  segR.build(vec(n,n));

  segL.update(a[n],a[n]);
  segR.update(a[n],a[n]);

  int ans = 0;
  RFOR(i,1,n){
    int l = segL.query(0,a[i]);
    int r = segR.query(a[i],n);
    //cout << l SP r << endl;
    if(r!=n){
      segR.update(r,n);
      int r2 = segR.query(a[i],n);
      ans += (a[i]-l)*(r2-r)*i;
      segR.update(r,r);
    }
    if(l!=-1){
      segL.update(l,-1);
      int l2 = segL.query(0,a[i]);
      //debug(l2);
      ans += (l-l2)*(r-a[i])*i;
      segL.update(l,l);      
