		while(!st2.empty() && a[st2.top()] < a[i]){
			st2.pop();
		}
		if(st2.empty()) r[i] = n;
		else r[i] = st2.top();
		st2.push(i);
	}
	long long sum = 0;
	for(int i=0;i<n;i++){
		if(l[i] != -1){
			int ll = -1,rr = l[i];
			while(rr-ll > 1){
				int m = (ll+rr)/2;
