#include <bits/stdc++.h>

using namespace std;

#define PII pair<int, int>

const int N = 1e5 + 5;

int n, a[N];
PII tree[4 * N];
map<PII, int> vis;

PII merge(PII x, PII y) {
  if (x.first == -1) return y;
  if (y.first == -1) return x;
  return x.first > y.first ? x : y;
}

void build(int p, int b, int e) {
  if (b == e) {
    tree[p].first = a[b];
    tree[p].second = b;
    return;
  }
  int m = b + e >> 1;
  build(p * 2, b, m);
  build(p * 2 + 1, m + 1, e);
  tree[p] = merge(tree[p * 2], tree[p * 2 + 1]);
}

PII query(int p, int b, int e, int l, int r) {
  if (b > r || e < l) return {-1, -1};
  if (b >= l && e <= r) return tree[p];
  int m = b + e >> 1;
  return merge(query(p * 2, b, m, l, r), query(p * 2 + 1, m + 1, e, l, r));
}

