                if(lf_rg==0)
                    hi = m-1;
                else lo = m+1;
            }
            else lo = m+1;
        }
        return ret;
    }
    int mid=(b+e)>>1, lft=node<<1, rgt=lft|1;
    int x = query(lft, b, mid, l, r, k, lf_rg);
    int y = query(rgt, mid+1, e, l, r, k, lf_rg);
    if(x==-1) return y;
    if(y==-1) return x;
    if(lf_rg==0) return min(x,y);
    return max(x,y);
}
