	} else if (l <= tl && tr <= r) {
	    return t[v];
	} else {
	    int tm = (tl + tr)/2;
	    return merge(get(2*v, tl, tm, l, r), get(2*v+1, tm+1, tr, l, r));
	}
    }
    void update(int v, int tl, int tr, int idx, int val) {
	if (tl == tr) {
	    t[v] = val;
	} else {
	    int tm = (tl + tr)/2;
	    if (idx <= tm) {
		update(2*v, tl, tm, idx, val);
	    } else {
		update(2*v+1, tm+1, tr, idx, val);
	    }
	    t[v] = merge(t[2*v], t[2*v+1]);
	}

    }
};



