int qry(int pos,int l,int r,int I,int J)
{
    if(l>J || r<I)return -1;
    if(I<=l && J>=r)
    {
        return tre[pos];
    }
    int mid=(l+r)>>1;
    int x=qry(2*pos,l,mid,I,J);
    int y=qry(2*pos+1,mid+1,r,I,J);
    if(x==-1 && y==-1)return -1;
    if(x==-1)return y;
    if(y==-1)return x;
    if(a[x]>a[y])return x;
    else return y;
}

int q(int lft,int rgt,int val)
{
    if(lft>rgt)return -1;
    int lo=lft;
    int hi=rgt;
    while(hi-lo>=2)
    {
        int mid=(lo+hi)>>1;
        int x=qry(1,1,n,lo,mid);
        int y=qry(1,1,n,mid+1,hi);
        if(x!=-1 && a[x]>val)hi=mid;
        else if(y!=-1 && a[y]>val)lo=mid+1;
        else return -1;
    }
    for(int i=lo;i<=hi;i++)
    {
        if(a[i]>val)return i;
    }
    return -1;
}
int abr_q(int lft,int rgt,int val)
{
    if(lft>rgt)return -1;
