	for (ll i = 1; i < N; ++i)
	{
		ll k = P[i].first;
		mp[P[i].first] = P[i].second;
		ll a, b, c, d;
		auto itrL = mp.find(P[i].first);
		auto itrR = itrL;

		bool flagL=true, flagR = true;

		if(itrL!=mp.begin())
		{
			--itrL;
			b = itrL->first;
			if (itrL != mp.begin())
			{
				--itrL;
				a = itrL->first;
			}
			else
			{
				a = -1;
			}
		}
		else
		{
			a = b = -1;
			flagL = false;
		}

		++itrR;
		if (itrR != mp.end())
		{
			c = itrR->first;
			++itrR;
			if (itrR != mp.end())
			{
				d = itrR->first;
			}
			else
			{
				d = N;
			}
		}
		else
		{
			c = d = N;
			flagR = false;
		}

		if (flagL)
		{
			ans += (b-a) * (c-k)*P[i].second;
		}
		if (flagR)
		{
			ans += (d-c) * (k-b)*P[i].second;
		}

		//cout << ans << endl;
	}

	cout << ans << endl;

	return 0;
}

