int get(int v, int tl, int tr, int l, int r, int w){
    if(l > tr || tl > r){
        return 0;
    }
    if(l <= tl && tr <= r){
        int h = upper_bound(t[v].begin(), t[v].end(), w) - t[v].begin();
        return t[v].size() - h;
    }
    int mid = (tl + tr) / 2;
    return get(v * 2, tl, mid, l, r, w) + get(v * 2 + 1, mid + 1, tr, l, r, w);
}

