vector<string> split(string str, char ch)
{
  int first = 0;
  int last = str.find_first_of(ch);

  if(last == string::npos)
    {
      last = SIZ(str);
    }

  vector<string> result;

  while( first < SIZ(str) )
    {
      string Ssubstr(str, first, last - first);
      result.push_back(Ssubstr);
      first = last + 1;
      last = str.find_first_of(ch, first);

      if(last == string::npos)
	{
	  last = SIZ(str);
	}
    }

  return result;
}



int gcd( int a , int b ) // assuming a,b >= 1
{
  if( a < b )
    {
      swap(a,b);
    }

  if( a == 0 )
    {
      return b;
    }

  if( a % b == 0 )
    {
      return b;    
    }

  return gcd( b , a % b );

}

long long gcd( long long a , long long b ) // assuming a,b >= 1
{
  if( a < b )
    {
      swap(a,b);
    }

  if( a == 0LL )
    {
      return b;
    }

  if( a % b == 0 )
    {
      return b;
    }

  return gcd( b , a % b );

}

int lcm( int a , int b ) // assuming a,b >= 1
{
  return  a * b / gcd( a , b );

}

