template<class C>
class seg_tree {
	vector<C> tree;
	C(*key)(C, C);
	const C def;
	int p = 1;
public:
	seg_tree(vector<C> v, C func(C, C), C a) : def(a), key(func) {
		int n = (int)v.size();
		while (p < n) {
			p <<= 1;
		}
		tree.resize(2 * p, def);
		for (int i = 0; i < n; ++i) {
			tree[i + p] = v[i];
		}
		for (int i = p - 1; i > 0; --i) {
			tree[i] = key(tree[i << 1], tree[(i << 1) + 1]);
		}
	}
	seg_tree(int n, C func(C, C), C a) : def(a), key(func) {
		while (p < n) {
			p <<= 1;
		}
		tree.resize(2 * p, def);
	}
	C get(int l, int r) {
		C ans = def;
		for (l += p, r += p; l <= r; l >>= 1, r >>= 1) {
			if (l & 1) {
				ans = key(ans, tree[l++]);
			}
			if ((r & 1) == 0) {
				ans = key(ans, tree[r--]);
			}
		}
		return ans;
	}
	int get_right(int i, C x) {
		if (get(i, p - 1) < x) {
			return -1;
		}
		int v = i + p;
		while (tree[v] < x) {
			if (v & 1) {
				++v;
			}
			v >>= 1;
		}
		while (v < p) {
			v <<= 1;
			if (tree[v] < x) {
				++v;
			}
		}
		return v - p;
	}
	int get_left(int i, C x) {
		if (get(0, i) < x) {
			return -1;
		}
		int v = i + p;
		while (tree[v] < x) {
			if ((v & 1) == 0) {
				--v;
			}
			v >>= 1;
		}
		while (v < p) {
			v <<= 1;
			if (tree[v + 1] >= x) {
				++v;
			}
		}
		return v - p;
	}
};

