inline void build(int l,int r)
{
	totr++;
	int x=totr;
	rt[x].l=l;
	rt[x].r=r;
	if(l==r)
	{
		rt[x].val1=0;
		rt[x].val2=n+1;
		return ;
	}
	int mid=(l+r)>>1;
	rt[x].lch=totr+1;
	build(l,mid);
	rt[x].rch=totr+1;
	build(mid+1,r); 
	push_up(x); 
}
inline void modify1(int x,int p,int val)
{
	if(p<rt[x].l||rt[x].r<p)return ;
	if(rt[x].l==rt[x].r)
	{
		rt[x].val1=val;
		return ;
	}
	modify1(rt[x].lch,p,val);
	modify1(rt[x].rch,p,val);
	push_up(x);
}

inline void modify2(int x,int p,int val)
{
	if(p<rt[x].l||rt[x].r<p)return ;
	if(rt[x].l==rt[x].r)
	{
		rt[x].val2=val;
		return ;
	}
	modify2(rt[x].lch,p,val);
	modify2(rt[x].rch,p,val);
	push_up(x);
}
inline int search1(int x,int l,int r)
{
	if(r<rt[x].l||rt[x].r<l)return 0;
	if(l<=rt[x].l&&rt[x].r<=r)return rt[x].val1;
	return max(search1(rt[x].lch,l,r),search1(rt[x].rch,l,r));
}
inline int search2(int x,int l,int r)
{
	if(r<rt[x].l||rt[x].r<l)return n+1;
	if(l<=rt[x].l&&rt[x].r<=r)return rt[x].val2;
	return min(search2(rt[x].lch,l,r),search2(rt[x].rch,l,r));
}
