const ll MAX = 400000;


int main() {

	ll N;
	cin >> N;
	ll P[MAX];
	repn(i, N) cin >> P[i];


	ll rf[MAX];//自分より大きい右にあるもの
	ll rs[MAX];//二番目に右

	repn(i, N) {
		rf[i] = N + 1;
		rs[i] = N + 1;
	}

	stack<pair<ll,ll>> fst;
	stack<pair<ll,ll>> sec;

	repn(i, N) {

		while (!sec.empty()) {
			if (sec.top().second < P[i]) {

				pair<ll, ll> x = sec.top();

				rs[x.first] = i;

				sec.pop();
			}

			else { break; }
		}

		while (!fst.empty()) {
			if (fst.top().second< P[i]) {

				pair<ll, ll> x = fst.top();

				rf[x.first] = i;

				fst.pop();
				sec.push(x);
			}

			else { break; }
		}



		fst.push({i,P[i]});

	}



	int lf[MAX] = {};//自分より大きい左にあるもの
	int ls[MAX] = {};//二番目に左

	stack<pair<ll, ll>> fstl;
	stack<pair<ll, ll>> secl;

	for(int i=N;i>0; i--) {


		while (!secl.empty()) {
			if (secl.top().second < P[i]) {

				pair<ll, ll> x = secl.top();

				ls[x.first] = i;

				secl.pop();
			}

			else { break; }
		}

		while (!fstl.empty()) {
			if (fstl.top().second < P[i]) {

				pair<ll, ll> x = fstl.top();

				lf[x.first] = i;

				fstl.pop();
				secl.push(x);
			}

			else { break; }
		}

		fstl.push({ i,P[i] });

	}



	ll ans = 0;

	repn(i, N) {
		ans += ((lf[i] - ls[i])*(rf[i] - i)+(i-lf[i])*(rs[i]-rf[i])) * P[i];

	}

	cout << ans;
	system("PAUSE");

}

