class RMQ
{
public:
	RMQ(int elems, int invalid)
	{
		mNumElements = elems + 1; // 差分をとる形で1個多いケース頻発するので
		mInvalid = invalid;
		init(mNumElements, mInvalid);
	}

	// k番目の値をとる
	int get(int k)
	{
		return dat[k + n - 1];	// 数列の0番目がdat[n-1]にくる。
	}

	// k番目に値vを足す
	void add(int k, int v)
	{
		update(k, get(k) + v);
	}

	void set(int k, int v)
	{
		int now = get(k);
		int adder = v - now;
		add(k, adder);
	}


	// k番目をaに
	void update(int k, int a)
	{
		k += n - 1;
		dat[k] = a;
		while (k>0)
		{
			k = (k - 1) / 2;
			dat[k] = op(dat[k * 2 + 1], dat[k * 2 + 2]);
		}
	}

	// 値がvである接点番号で一番小さいのを１個探す
	int getindex(int v, int k = 0)
	{
		if (k >= n - 1)
		{
			return k - (n - 1);
		}
		else if (dat[k * 2 + 1] == v)
		{
			return getindex(v, k * 2 + 1);
		}
		else if (dat[k * 2 + 2] == v)
		{
			return getindex(v, k * 2 + 2);
		}
		else
		{
			return -1;
		}
	}

	// [a,b)の最小値を求める（注 b以下じゃなくて、b未満だよ。）
	int getQuery(int a, int b)
	{
		return query(a, b, 0, 0, n);
	}

	// 全体の最小値を求める
	int getQueryAll()
	{
		return query(0, mNumElements, 0, 0, mNumElements);
	}

private:
	virtual int op(int a, int b) = 0;

	void init(int n_, int invalid)
	{
		// n_を2の累乗にする。
		n = 1;
		while (n<n_)
		{
			n *= 2;
		}

		dat.clear();
		dat.resize(2 * n - 1);
		fill(dat.begin(), dat.end(), invalid);
	}


	// ！[a,b)の最小値を求める（注 b以下じゃなくて、b未満だよ。）
	// ！外からはrmq_query(a,b,0,0,n)で呼ぶ
	// kが接点番号
	int query(int a, int b, int k, int l, int r)
	{
		if (r <= a || b <= l)
		{
			return mInvalid;
		}

		if (a <= l && r <= b)
		{
			return dat[k];
		}
		else
		{
			int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
			int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
			return op(vl, vr);
		}
	}

	int mInvalid;
	int mNumElements;	// 実際にユーザーが使う数
	int n;				// num_elementsを2の累乗にしたもの
	vector <int> dat;
};

class RMQMax : public RMQ
{
public:
	RMQMax(int elems) : RMQ(elems, -INT_MAX)
	{
	}

private:
	virtual int op(int a, int b)
	{
		return max(a, b);
	}
};

void binary(ll& ok, ll& ng, RMQMax& rmq, ll st, ll v)
{
	while (abs(ok - ng)>1)
	{
		ll mid = ok + (ng - ok) / 2LL; // ll 溢れ時は、lo+(hi-lo)/2LL;

		if (rmq.getQuery(st, mid) > v)
		{
			ok = mid;
		}
		else
		{
			ng = mid;
		} 
	}
}


