void solve() {
  // ある数が何回 2 番目になるか
  int n;
  cin >> n;
  vector<pii> a(n);
  rep(i, n) { cin >> a[i].F; a[i].S = i; }
  // すべての値が distinct
  sort(all(a), greater<pii>());

  // i より左に 1 つ i より大きいのある, 右に i より大きいのない
  // 逆も
  ll ans = 0;
  multiset<int> s;
  // 番兵
  s.insert(-1);
  s.insert(n);
  s.insert(-1);
  s.insert(n);

  rep(i, n) {
    int j = a[i].S;
    auto rl = s.upper_bound(j);
    // auto rr = --rl; error 
    auto rr = rl;
    rr++;

    auto lr = rl;
    lr--;
    auto ll = lr;
    ll--;

    // cout << *ll << " " << *lr << " " << *rl << " " << *rr << endl;

    bool b1 = (ll == s.begin()), b2 = (rr == --s.end());
    // cout << b1 << " " << b2 << endl;
    // 両側に i より大きいのない
    long long tmp = 0; // ll が衝突する
    if (b1 && b2) {

    } else if (b1) {
      // 右側に i より大きいのある
      // 左側は i を含めて端を選ぶ
      tmp = 1LL * (j + 1) * (*rr - *rl);
    } else if (b2) {
      tmp = 1LL * (n - j) * (*lr - *ll);
    } else {
      tmp = 1LL * (j - *lr) * (*rr - *rl);
      tmp += 1LL * (*lr - *ll) * (*rl - j);
    }
    tmp *= 1LL * a[i].F;
    ans += tmp;
    // cout << ans << endl;
    s.insert(a[i].S);
  }
  cout << ans << endl;
}

