/**
A[ 2 , 0 ]    B[ 3 , 0 ]    C[ 1 , 0 ]
     \          /     \         /
      D[ 3 , 2 ]     E[ 3 , 1 ]
            \           /
              F[ 3 , 2 ]
*/

int query(int a, int b)
{
    int k = 31-__builtin_clz(b-a+1);
    int x=max(dp[a][k][0], dp[b-(1<<k)+1][k][0]);
    int y=max(dp[a][k][1], dp[b-(1<<k)+1][k][1]);
    return min(x, y);
}

