#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)

const int N_MAX = 100000;

typedef long long ll;

int N;
int P[N_MAX];

int a[N_MAX];
int b[N_MAX];
int x[4];

void solve() {
  ll ans = 0;
  REP(i, N - 1) {
    a[i] = P[i];
    b[i] = P[i + 1];
    if (a[i] < b[i]) swap(a[i], b[i]);
    ans += b[i];
  }

  for (int i = N - 2; i > 0; i--) {
    REP(j, i) {
      x[0] = a[j];
      x[1] = b[j];
      x[2] = a[j + 1];
      x[3] = b[j + 1];
      sort(x, x + 4, greater<int>());
      unique(x, x + 4);
      a[j] = x[0];
      b[j] = x[1];
      ans += b[j];
    }
  }

  printf("%lld\n", ans);
}

void input() {
  scanf("%d", &N);
  REP(i, N) scanf("%d", P + i);
}

int main() {
  input();
  solve();
  return 0;
}

