int main() {
  int n, sum = 0;
  cin >> n;
  vector<int> p(n);
  for(int i=0; i<n; i++) {
    cin >> p.at(i);
  }
  //ここまでは確定

  for(int i=0; i<n-1; i++) {
    for(int j=i+1; j<n; j++) {
      vector<int> x(j-i+1);
      for(int k = 0; k<x.size(); k++) {
        x.at(k) = p.at(i+k);
