using namespace std;

int N;
int main() {
    cin >> N;

    long P[N];
    int value_index[N+1];
    for(int i = 0; i < N; i++) {
        cin >> P[i];
        value_index[P[i]] = i;
    }

    auto cmp = [](long a, long b) { return a > b;};

    set<long> larger_idx_right;
    set<long, decltype(cmp)> larger_idx_left(cmp);

    set<long>::iterator it;

    long ans = 0;

    for(int i = N; i > 0; i--) {
        long right_1 = N;
        long right_2 = N;
        it = larger_idx_right.upper_bound(value_index[i]);
        if(it != larger_idx_right.end()) {
            right_1 = *it;
            it = larger_idx_right.upper_bound(right_1);
            if(it != larger_idx_right.end()) {
                right_2 = *it;
            }
        }

        long left_1 = -1;
        long left_2 = -1;
        it = larger_idx_left.upper_bound(value_index[i]);
        if(it != larger_idx_left.end()) {
            left_1 = *it;
            it = larger_idx_left.upper_bound(left_1);
            if(it != larger_idx_left.end()) {
                left_2 = *it;
            }
        }

        larger_idx_right.insert(value_index[i]);
        larger_idx_left.insert(value_index[i]);

        if (right_1 != N) {
            ans += i*(value_index[i]-left_1)*(right_2-right_1);
        }
        if (left_1 != -1) {
            ans += i*(right_1-value_index[i])*(left_1-left_2);
        }
    }

    cout << ans << endl;
}

