	cin >> N;

	vector<top2> t(N);
	for (int i = 0; i < N; i++) {
		int p;
		cin >> p;
		t[i] = top2(p, 0);
	}

	int ans = 0;
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N - 1 - i; j++) {
			t[j] = merge(t[j], t[j + 1]);
			ans += t[j].second;
			//cout << t[j].second << " ";
		}
		//cout << "\n";
	}

	cout << ans << "\n";

	return 0;
}

