#include <bits/stdc++.h>
#define REP(i, n) for (int i = 0; (i) < (int)(n); ++ (i))
#define REP3(i, m, n) for (int i = (m); (i) < (int)(n); ++ (i))
#define REP_R(i, n) for (int i = (int)(n) - 1; (i) >= 0; -- (i))
#define REP3R(i, m, n) for (int i = (int)(n) - 1; (i) >= (int)(m); -- (i))
#define ALL(x) begin(x), end(x)
using ll = long long;
using namespace std;

ll solve(int n, const vector<int> & p) {
    vector<int> order(n);
    iota(ALL(order), 0);
    sort(ALL(order), [&](int i, int j) { return p[i] > p[j]; });
    set<int> used;
    used.insert(-1);
    used.insert(n);
    ll ans = 0;
    for (int m : order) {
        used.insert(m);
        auto it = used.find(m);
        if (prev(it) != used.begin()) {
            ans += (ll)p[m] * (*prev(it) - *prev(prev(it))) * (*next(it) - m);
        }
        if (next(next(it)) != used.end()) {
            ans += (ll)p[m] * (*next(next(it)) - *next(it)) * (m - *prev(it));
        }
    }
    return ans;
}

int main() {
    int n; cin >> n;
    vector<int> p(n);
