using namespace std;
inline int read() {
    reg int s = 0, t = 0; reg char ch = getchar();
    while(ch > '9' || ch < '0') t |= ch == '-', ch = getchar();
    while(ch >= '0' && ch <= '9') s = (s << 1) + (s << 3) + (ch ^ 48), ch = getchar();
    return t ? -s : s;
}
stack <int> Q, F;
int L[maxn * 20], R[maxn * 20], t[maxn], sum[maxn * 20], lx[maxn],rx[maxn],ly[maxn],ry[maxn],a[maxn];
long long cnt, n, ans, ansx , p, anss, sumx;
int build(int l,int r)
{
    int num=++cnt;
    if(l!=r)
    {
        int mid=(l+r)>>1;
        L[num]=build(l,mid);
        R[num]=build(mid+1,r);
    }
    return num;
}
int update(int pre,int l,int r,int x)
{
    int num=++cnt;
    L[num]=L[pre];R[num]=R[pre];sum[num]=sum[pre]+1;
    if(l!=r)
    {
        int mid=(l+r)>>1;
        if(x<=mid)L[num]=update(L[pre],l,mid,x);
        else R[num]=update(R[pre],mid+1,r,x);
    }
    return num;
}
int query(int k, int v, int l, int r, int Lc ,int Rc)
{
    int mid = l + r >> 1, res = 0;
    if(r <= Rc && l >= Lc) { res = sum[k] - sum[v]; return res;}
    if (Lc <= mid)
       res += query(L[k], L[v], l, mid, Lc, Rc);
    if (Rc > mid)
       res += query(R[k], R[v], mid + 1, r, Lc, Rc);
    return res;

}
int main() {
    n = read();
    for(int i = 1; i <= n; i++) a[i] = read();
    for(int i = 1; i <= n; i++)
    {
        while(!Q.empty() && Q.top() < a[i])
            Q.pop(),F.pop();
            if(!Q.empty()) lx[i] = F.top();
            Q.push(a[i]); F.push(i);
    }
    while(!Q.empty()) Q.pop(), F.pop();
    for(int i = n; i >= 1; i--)
    {
        while(!Q.empty() && Q.top() < a[i])
            Q.pop(),F.pop();
            if(!Q.empty()) rx[i] = F.top();
            else rx[i] = n + 1;
            Q.push(a[i]); F.push(i);
    }
    t[0] = build(1, n);
    for(int i = 1; i <= n; i++)
    {
     t[i] = update( t[i - 1], 1, n, a[i]);
    }
    for(int i = 1; i <= n; i++)
    {
                p = rx[i]; ansx = sumx = 0;
                int l = rx[i] + 1, r = n ;
                while(l <= r){
                    int mid = l + r >> 1;
                    ans = query(t[mid], t[p], 1, n, a[i], n);
                    if(ans) { ansx++; r = mid - 1; sumx = mid;}
                    else l = mid + 1;
                }
                if(ansx == 0) sumx = n + 1;
                ry[i] = sumx;
                ansx = sumx = 0; p = lx[i] - 1;
                l = 1, r = lx[i] - 1;
                while(l <= r){
                    int mid = l + r >> 1;
                    ans = query(t[p], t[mid - 1], 1, n, a[i], n);
                    if(ans) { ansx++; l = mid + 1; sumx = mid;}
                    else r = mid - 1;
                }
                if(ansx == 0) sumx = 0;
                ly[i] = sumx;
    }
    for(int i = 1; i <= n; i++)
    {
             anss += 1ll *  (ry[i] - rx[i]) * (i - lx[i]) * a[i] + 1ll * (lx[i] - ly[i]) * (rx[i] - i) * a[i];
    }
    printf("%lld\n", anss);
  return 0;
}

