pair<int,int> getMiddle(pair<int,int> p,int d){
	if(d > p.first ) return pair<int,int>(d,p.first);
	if(p.first > d && d > p.second ){
		return pair<int,int>(p.first,d);
	}
	if(p.second > d) return p;
}

