int main(){

  set<int> st;

  int n; cin >> n;
  vector<int> p(n);
  vector<int> idx(n);
  rep(i, n){
    cin >> p[i];
    p[i]--;
    idx[p[i]] = i;
  }
  lint ans = 0;
  st.insert(idx[n - 1]);

  int inf = 10000000;

  st.insert(-inf);
  st.insert(inf);

  for(int i = n - 2; i >= 0; i--) {

    // 二番目に大きい値が i となるような通り数を加算したい
    int id = idx[i];
    st.insert(id);
    auto cur_itr = st.find(id);
    auto left_itr = cur_itr;
    auto right_itr = cur_itr;
    left_itr--;
    right_itr++;

    // 左固定
    if(*left_itr != -inf) {

      int r = n;
      if(*right_itr != inf) r = *right_itr;
      int val1 = r - id;
      auto leftleft = left_itr;
      leftleft--;
      int l = -1;
      if(*leftleft != -inf) {
        l = *leftleft;
      }

      int mid = *left_itr;
      int val2 = mid - l;


      ans += val1 * val2 * (i + 1);
    }

    // 右固定
    if(*right_itr != inf) {
      int l = -1;
      if(*left_itr != -inf) l = *left_itr;
      int val1 = id - l;
      auto rightright = right_itr;
      rightright++;
      int r = n;
      if(*rightright != inf) {
        r = *rightright;
      }

      int mid = *right_itr;
      int val2 = r - mid;   
      ans += val1 * val2 * (i + 1);

    }
  }

  cout << ans << endl;

  return 0;
}

