// 1次元上の要素のマージをしていくときに、各連結成分の[left, right)を更新
struct UnionFind {
    int cnt;                      // 集合の数
    vector<int> number;           // 0以上のとき親のindex, 負のときは集合サイズ
    vector<pair<int, int>> data;  // [left, right)
    UnionFind(int n) : cnt(n), number(n, -1), data(n) {
        for (int i = 0; i < n; i++) data[i] = {i, i + 1};
    }
    int root(int x) { return number[x] < 0 ? x : number[x] = root(number[x]); }
    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (number[y] < number[x]) swap(x, y);
        // yをxにマージ
        number[x] += number[y];
        number[y] = x;
        // dataのマージ方法に合わせて変える
        data[x] = {min(data[x].first, data[y].first), max(data[x].second, data[y].second)};
        cnt--;
    }
    bool is_same(int x, int y) { return root(x) == root(y); }
    int size(int x) { return -number[root(x)]; }
    int& left(int x) { return data[root(x)].first; }
    int& right(int x) { return data[root(x)].second; }
    pair<int, int>& ref(int x) { return data[root(x)]; }
};

signed main() {
    int n; cin >> n;
    vector<int> b(n);
    REP (i, n) {
        int a; cin >> a;
        a--;
        b[a] = i + 1;
    }
    vector<int> deleted(n + 2);
    UnionFind uf(n + 2);
    auto left = [&](int i) -> int {
        if (i == 0) return 0;
        if (!deleted[i - 1]) return i - 1;
        return uf.left(i - 1) - 1;
    };
    auto right = [&](int i) -> int {
        if (i == n + 1) return n + 1;
        if (!deleted[i + 1]) return i + 1;
        return uf.right(i + 1);
    };
    int ans = 0;
    REP (a, n) {
        int i = b[a];
        if (deleted[i - 1]) uf.unite(i - 1, i);
        if (deleted[i + 1]) uf.unite(i, i + 1);
        int l1 = left(i);
        int l2 = left(l1);
        int r1 = right(i);
        int r2 = right(r1);
        ans += (a + 1) * ((i - l1) * (r2 - r1) + (r1 - i) * (l1 - l2));
        deleted[i] = true;
    }
    cout << ans << endl;
}

