    p[N][2][2], l, r, L, R;
int64_t ans;

void update(int i,int x)
{
    for(; i>0; i-=i&-i) bit[i] = max(bit[i], x);
}
int get(int i)
{
    int res = 0; for(; i<=n; i+=i&-i)
    res = max(res, bit[i]); return res;
}
int main()
{
    cin >> n;
    for(int i=1; i<=n; ++i) cin >> a[i];
    for(int e = 0; e<2; ++e) {
        deque<int> de;
        for(int i=1; i<=n; ++i) bit[i] = 0;
        for(int i=1; i<=n; ++i) {
            while (!de.empty() && a[de.back()] < a[i]) {
                update(a[de.back()], de.back());
                de.pop_back();
            }
            p[i][0][e] = de.empty() ? 0 : de.back();
            p[i][1][e] = max(get(a[i]),p[p[i][0][e]][0][e]);
            de.push_back(i);
        }
        reverse(a+1, a+1+n);
    }

    for(int i=1; i<=n; ++i) {
        L = p[i][0][0];
        l = p[i][1][0];
        R = n+1 - p[n+1-i][0][1];
        r = n+1 - p[n+1-i][1][1];
        //cout << l <<' ' << L <<' ' << i << ' '<< R << ' ' << r << endl;
        ans += 1LL * a[i] * (1LL*(L-l)*(R-i) + 1LL*(r-R)*(i-L));
