        pos[P[i]] = i;
    }

    multiset<pair<ll, ll>> st;
    //番兵を両端に設置
    st.insert({-1, N + 1});
    st.insert({-1, N + 1});
    st.insert({ N, N + 1});
    st.insert({ N, N + 1});

    //Nはsecondになりえないので入れる
    st.insert({pos[N], N});

    ll ans = 0;
    for (ll i = N - 1; i >= 1; i--) {
        auto right1 = st.upper_bound({pos[i], i});
        auto right2 = right1;
        right2++;
        auto left1 = right1;
        left1--;
        auto left2 = left1;
        left2--;

        //left1を含むような区間(left2, right1)で[left1, pos[i]]よりは大きい区間
        ans += i * (right1->first - pos[i]) * (left1->first - left2->first);

        //right1を含むような区間(left1, right2)で[pos[i], right1]よりは大きい区間
        ans += i * (right2->first - right1->first) * (pos[i] - left1->first);

        st.insert({pos[i], i});
    }

    cout << ans << endl;
}

