        _LL l2 = -1;
        if( l1 > 0 ) l2 = findbiggerleft(p[i], l1, st);
        _LL r1 = findbiggerright(p[i], i, n, st);
        _LL r2 = n;
        if( r1 < n - 1 ) r2 = findbiggerright(p[i], r1, n, st);
        ans += ((i - l1) * (r2 - r1) + (r1 - i) * (l1 - l2)) * (_LL) p[i];
    }
    cout << ans << endl;
