int l1[200000],l2[200000],r1[200000],r2[200000];

void calc(int*l1,int*l2){
	rep(i,n)seg.update(i,INT_MIN);
	rep(i,n){
		seg.update(p[i],i);
		auto p1=seg.query(p[i]+1,n);
		if(p1.first==INT_MIN){
			l1[i]=l2[i]=-1;continue;
		}
		else{
			l1[i]=p1.first;
			int X=p1.first;
			seg.update(p1.second,INT_MIN);
			auto p2=seg.query(p[i]+1,n);
			if(p2.first==INT_MIN)l2[i]=-1;
			else l2[i]=p2.first;
			seg.update(p1.second,X);
		}
	}
}
