using namespace std;
using namespace __gnu_pbds;   
#define ordered_set tree<ll, null_type,less<ll>, rb_tree_tag,tree_order_statistics_node_update> 
#define ll long long int
#define ff first
#define ss second
#define pb push_back
#define mp make_pair
#define pll pair<ll,ll>
#define all(x) x.begin(),x.end()
#define sz(x) (ll)x.size() 

const ll M=2e5+5;
ll a[M],seg[6*M],pge[M],nge[M];

ll build(ll idx , ll st , ll en)
{
    if(st==en)
      seg[idx]=a[st];
    else
    {
        ll mid = (st+en)/2;
        build(2*idx+1,st,mid);
        build(2*idx+2,mid+1,en);
        seg[idx]=max(seg[2*idx+1],seg[2*idx+2]);
    }
}

ll query(ll idx,ll st,ll en,ll l,ll r)
{

    if(st>r || en<l)
        return -1;

    if(st>=l && en<=r)
      return seg[idx];

    ll mid = (st + en)/2;
    return max(query(2*idx+1,st,mid,l,r),query(2*idx+2,mid+1,en,l,r));            
}

void update(ll idx, ll st,ll en , ll pos,ll val)
{
      ll mid = (st+en)/2;
      if(st==en)
      {
          seg[idx]=val;
          return;
      }
      if(pos<=mid)
        update(2*idx+1,st,mid,pos,val);
      else
        update(2*idx+2,mid+1,en,pos,val);

      seg[idx]=max(seg[2*idx+1],seg[2*idx+2]);
}

void pre(ll n)
{
    ll i;
    stack<ll>s;
    for(i=0;i<n;i++)
    {
        while(!s.empty() && a[s.top()] < a[i])
        {
            nge[s.top()]=i;
            s.pop();
        }
        s.push(i);
    }
    while(!s.empty())
        nge[s.top()]=n,s.pop();

    for(i=n-1;i>=0;i--)
    {
        while(!s.empty() && a[s.top()] < a[i])
        {
            pge[s.top()]=i;
            s.pop();
        }
        s.push(i);
    }
    while(!s.empty())
        pge[s.top()]=-1,s.pop();
}

int main()
{
    ios_base::sync_with_stdio(false);
    ll n,i,j,k,x,y,t,m;

    cin >> n;
    for(i=0;i<n;i++)
      cin >> a[i];

    build(0,0,n-1);
    pre(n);    
    ll ans=0;
    for(i=0;i<n;i++)
    {
        ll pg=pge[i],ng=nge[i],spg=-1,sng=n;

        if(pg!=-1)
        {
            update(0,0,n-1,pg,-1);

            ll lo=0,hi=pg,md,prev=-1;
            while(lo<=hi)
            {
                md=(lo+hi)/2;
                if(md==prev)
                  break;
                prev=md;
