namespace commit
{

long long
SolveSecondSum(const std::vector<int> &inputs)
{
    long long sum = 0;

    std::vector<int> maxs(inputs.size(), 0);
    std::vector<int> secondMaxs(inputs.size(), 0);
    std::vector<int> mins(inputs.size(), std::numeric_limits<int>::max());

    for (std::size_t currentIndex=0; currentIndex<inputs.size(); ++currentIndex)
    {
        auto &input = inputs[currentIndex];

        for (std::size_t index=0; index<currentIndex; ++index)
        {
            if (input<mins[index])
            {
                secondMaxs[currentIndex-1] = input;
                for (std::size_t i=index; i<currentIndex; ++i)
                {
                    mins[i] = input;
                    sum += secondMaxs[i];
                }
                break;
            }

            if (input>maxs[index])
            {
                for (std::size_t i=index; i<currentIndex; ++i)
                {
                    secondMaxs[i] = maxs[i];
                    maxs[i] = input;
                    sum += secondMaxs[i];
                }
                break;
            }

            if (input>secondMaxs[index])
            {
                secondMaxs[index] = input;
            }

            sum += secondMaxs[index];
        }

        maxs[currentIndex] = input;
        mins[currentIndex] = input;
    }

    return sum;
}

}

