ll n, s[110000], pos[110000], ans[110000];
set<ll> se;
int main() {
	cin >> n;
	REP(i, n) cin >> s[i];
	REP(i, n) {
		pos[s[i]] = i;
	}
	se.insert(-1);
	se.insert(n);
	se.insert(pos[n]);
	FORR(i, n - 1, 1) {
		auto r = se.upper_bound(pos[i]);
		auto l = se.lower_bound(pos[i]);
		ll a = 1, b = 1, c = 1, d = 1;
		if (r != se.end()) {
			b = *r - pos[i];
			auto r2 = se.upper_bound(*r);
			if (r2 != se.end()) {
				d = *r2 - *r;
				if (*r == n)d = 0;
			}
			else d = 0;
		}
		if (l != se.begin()) {
			l--;
			a = pos[i] - *l;
			auto l2 = se.lower_bound(*l);
			if (l2 != se.begin()) {
				l2--;
				c = *l - *l2;
				if (*l == -1)c = 0;
			}
			else c = 0;
		}
		else b = 0;
		ans[i] = (b * c + a * d) * i;
		se.insert(pos[i]);
	}
	ll out = 0;
	REPO(i, n) {
		out += ans[i];
	}
	cout << out << endl;
