template <typename T>
class sparse_table {
	const int n;
	vector<vector<T>> t;
	T merge(const T& l, const T& r) const {
		return max(l, r);
	}
public:
	sparse_table(const vector<T>& b) : n(b.size()), t(1, b) {
		for (int i = 2, j = 1, p = 0; i <= n; i <<= 1, j++, p = 0) {
			t.emplace_back(n);
			for (int k = 0; k + i <= n; k++)
				t[j][p++] = merge(t[j - 1][k], t[j - 1][k + (i >> 1)]);
		}
	}
	T find(int l, int r) const { // [l, r)
		assert(0 <= l && l < r && r <= n);
		int i = 31 - __builtin_clz(r - l);
		return merge(t[i][l], t[i][r - (1 << i)]);
	}
};

int main()
{
	int N;
	cin >> N;
	vector<ll> P(N);
	for (int i = 0; i < N; i++) {
		cin >> P[i];
	}
	sparse_table<ll> st(P);
	vector<int> tor(N + 1), tol(N + 1);
	for (int i = 0; i < N; i++) {
		{
			int lb = -1, ub = i;
			while (ub - lb > 1) {
				int m = (lb + ub) / 2; 
				(st.find(m, i + 1) == P[i] ? ub : lb) = m;
			}
			tol[i] = lb;
		}
		{
			int lb = i + 1, ub = N + 1;
			while (ub - lb > 1) {
				int m = (lb + ub) / 2;
				(st.find(i, m) == P[i] ? lb : ub) = m;
			}
			tor[i] = lb;
		}
	}
	ll res = 0;
	for (int i = 0; i < N; i++) {
		ll val = 0;
		if (tor[i] < N) {
			int lb = tor[i] + 1, ub = N + 1;
			while (ub - lb > 1) {
				int m = (lb + ub) / 2;
				(st.find(tor[i] + 1, m) <= P[i] ? lb : ub) = m;
			}
			val += (i - tol[i]) * (lb - tor[i]);
		}
		if (0 <= tol[i]) {
			int lb = -1, ub = tol[i];
			while (ub - lb > 1) {
				int m = (lb + ub) / 2;
				(st.find(m, tol[i]) <= P[i] ? ub : lb) = m;
			}
			val += (tol[i] - lb) * (tor[i] - i);
		}
		res += val * P[i];
	}
	cout << res << endl;
	return 0;
}

