int N;
vll P;

vii lefts;  // first: next, second: next,next
vii rights;

int main(int argc, char** argv) {
  cin >> N;
  P.resize(N);
  for (int i=0; i<N; i++) {
    cin >> P[i];
  }

  lefts.resize(N);
  rights.resize(N);

  {
    // Range Maximam Query
    SegmentTree<ll> rmq(
            [](ll a, ll b) {
              return max(a, b);
            },
            -INF);
    rmq.init(N+1);

    // Look left
    for (int i=0; i<N; i++) {
      int x = rmq.query(P[i]+1, N+1);
      if (x < 0) {
        lefts[i] = {-1, -1};
      } else {
        int y = rmq.query(P[i]+1, P[x]);
	y = max({y, lefts[x].first});
	y = y<0 ? -1 : y;
        lefts[i] = {x, y};
      }

      rmq.update(P[i], i);
    }
  }

  // Look right
  {
    // Range Minimum Query
    SegmentTree<ll> rmq(
            [](ll a, ll b) {
              return min(a, b);
            },
            INF);
    rmq.init(N+1);

    // Look right
    for (int i=N-1; i>=0; i--) {
      int x = rmq.query(P[i]+1, N+1);
      if (x >= N) {
        rights[i] = {N, N};
      } else {
        int y = rmq.query(P[i]+1, P[x]);
	y = min({y, rights[x].first});
	y = y>=N ? N : y;
        rights[i] = {x, y};
      }

      rmq.update(P[i], i);
    }

//    for (int i=0; i<N; i++) {
//      cerr << rights[i].first << "," << rights[i].second << "  ";
//    }
//    cerr << endl;
  }

  ll ret = 0;
  for (int i=0; i<N; i++) {
    // Look left
    // 自分が現状2番
    if (lefts[i].first >= 0) {
      int l2 = lefts[i].first;
      int l1 = lefts[i].second + 1;
      int r1 = i;
      int r2 = rights[i].first-1;
      // [l1, l2] - [r1-r2]
      //
      ret += P[i]*(l2-l1+1)*(r2-r1+1);
//cerr << "(2) " << P[i] << ": " << l1 << " - " << l2 << "  " << r1 << " - " << r2 << endl;
    }

    // 自分が現状1番
    int l = lefts[i].first+1;
    int r1 = rights[i].first; // 自分が2番に落ちる
    if (r1<N) {
      int r2 = rights[i].second-1;
      // [l,i] - [r1,r2]
      ret += P[i]*(i-l+1)*(r2-r1+1);
//cerr << "(1) " << P[i] << ": " << l << " - " << i << "  " << r1 << " - " << r2 << endl;
    }
  }

  cout << ret << endl;

  return 0;
}

