void solve() {
    i64 N = RD();
    auto A = vec_reserve<pair<i64,i64>>(N);
    REP(i, N) {
        i64 x = RD();
        A.emplace_back(i, x);
    }
    ALL(sort, A, GT_ON(LIFT(get<1>)));
    DBG(A);

    i64 ans = 0;
    set<i64> idxs;
    for(const auto& p : A) {
        i64 i,x; tie(i,x) = p;
        i64 c = 0;

        // 先に入れてから探せば絶対見つかる
        idxs.emplace(i);

        vector<i64> l(2, -1);  // 左側i個目のインデックス
        vector<i64> r(2,  N);  // 右側i個目のインデックス
        {
            auto it = idxs.find(i);
            REP(j, 2) {
                if(it == begin(idxs)) break;
                --it;
                l[j] = *it;
            }
        }
        {
            auto it = idxs.find(i);
            REP(j, 2) {
                ++it;
                if(it == end(idxs)) break;
                r[j] = *it;
            }
        }

        c += (l[0]-l[1]) * (r[0]-i);  // 左
        c += (r[1]-r[0]) * (i-l[0]);  // 右

        ans += c * x;
    }

    PRINTLN(ans);
}

