int seg[MAXN * 4];
void update(int idx, int l, int r, int x, int val)
{
	if(l > x or r < x) return;
	if(x==l && x==r)
	{
		seg[idx] = val;
		return;
	}

	update(idx*2, l, mid, x, val);
	update(idx*2 + 1, mid+1, r, x, val);

	seg[idx] = max(seg[idx*2], seg[idx*2+1]);
}

int query(int idx, int l,int r, int lq, int rq)
{
	if(l >= lq && r <= rq) return seg[idx];
	if(l > rq or r < lq) return -INF;

	int lv = query(idx*2, l , mid, lq, rq);
	int rv = query(idx*2+1, mid+1 , r, lq, rq);

	return max(lv,rv);
}

int findLeft(int idx, int val) // find first index that is bigger than val
{
	int l = 0, r = idx;

	while(l+1 < r)
	{
		int segMax = query(1,1,n,mid,idx);
		if(segMax < val)
			r = mid-1;
		else
			l = mid;
	}

	if(query(1,1,n,r,idx) > val) return r;
	return l;
	// while(d[idx] < val) idx--;
	// return idx;
}

