	for (int i = 1; i <= n; ++i)
	{
		lx[i] = findLeft(i-1,d[i]);
		if(lx[i])
			lx2[i] = findLeft(lx[i]-1,d[i]);
		else 
			lx2[i] = 0;

		rx[i] = findRight(i+1,d[i]);
		if(rx[i] != n+1)
			rx2[i] = findRight(rx[i]+1,d[i]);
		else
			rx2[i] = n+1;
	}

	for (int i = 1; i <= n; ++i)
	{
		// cout << i _ lx[i] _ rx[i] _ lx2[i] _ rx2[i] << endl;

		ll add = 0;
		if(rx[i] != n+1)
			add += (i-lx[i]) * (rx2[i] - rx[i]);

		if(lx[i] != 0)
			add += (rx[i]-i) * (lx[i] - lx2[i]);

		ans += add * d[i];
	}

	cout << ans << endl;
}

