		}
		st[j][i] = max(st[j][i - 1], st[j + (1 << (i - 1))][i - 1]);
	}
	return ;
}

#define query(l, r) max(st[l][lg[r - l + 1]], st[r - (1 << lg[r - l + 1]) + 1][lg[r - l + 1]])

ll bsearch(ll l, ll r, ll x, ll typ)
{
	ll s = l, e = r;
	ll ret = typ * (n + 1);
	while(l <= r)
	{
		ll mid = (l + r) >> 1;
		if(typ == 1)
		{
			if(query(s, mid) > x) r = mid - 1, ret = mid;
			else l = mid + 1;
		}
		else
		{
			if(query(mid, e) > x) l = mid + 1, ret = mid;
			else r = mid - 1;
		}
	}
	return ret;
}

