    S.insert(-1);
    S.insert(N);
    sum = 0;
    for(int i=1;i<N;i++){
        ll n = v[i].first;
        ll ind = v[i].second;
        auto ep = S.upper_bound(ind);
        ll s_ind,e_ind;
        s_ind = *(ptr(ep,-1));
        e_ind = *(ptr(ep,0));
        if(s_ind == -1){
            ll v_ind = *(ptr(ep,1));
            sum += (ind + 1) * (v_ind - e_ind) * n;
