		cin >> P[i];
		num[P[i]] = i;
	}
	set<int> bigger;
	bigger.insert(num[N]);
	for (ll i = N - 1;i > 0;i--) {
		auto itr = bigger.upper_bound(num[i]), itl = itr;
		ll left, right, mid = num[i];
		if (itl == bigger.begin()) {
			//右側に広がるしかない
			left = num[i] + 1;
			itr++;
			if (itr == bigger.end()) {
				itr--;
				right = N - *itr;
			}
			else {
				right = *itr;
				itr--;
				right -= *itr;
				itr++;
			}
			ans += (left * right)*i;
		}
		else {
			itl--;
			//左に広がるパターン
			if (itl == bigger.begin()) {
				left = *itl + 1;
			}
			else {
				left = *itl;
				itl--;
				left -= *itl;
				itl++;
			}
			if (itr == bigger.end()) {
				right = N - num[i];
			}
			else {
				right = *itr - num[i];
			}
			ans += (right * left)*i;

			//右に広がるパターン
			left = num[i];
			left -= *itl;
			if (itr == bigger.end()) {
				//右に広がれない
				right = 0;
			}
			else {
				itr++;
