            res += 1L * (*next(itne) - (*itne)) * xs[p];
            f = 0;
        }
        else
        {
            res += 1L * (*itpr - *prev(itpr)) * ((*itne) - xs[p]);
        }
        if (*itne == n + 1)
        {
            res += 1L * (*itpr - *prev(itne)) * (n + 1 - xs[p]);
        }
        else
        {
            if (f)
                res += 1L * (xs[p] - *itpr) * (*next(itne) - (*itne));
        }
        //cout << res << endl;
        res *= p;
        ans += res;
        id.insert(xs[p]);
    }
    cout << ans << endl;
}

