int firstArLast(int L, int R, int val){

	if (R < L) return n+1;
	int node = R + n - 1;

	while (Tree[node] < val){
		while (node % 2 == 0){
			n /= 2;
			if (node <= 1) return 0;
		}
		node--;
	}

	while (node < n){
		node = node * 2 +1;
		if (Tree[node] < val) node--;
	}

	int index = node - (n - 1);
	//if (index<L) return 0;
	return (index>=L  ? index: 0);
}

int lastAtFirst(int L, int R, int val){
	if (R < L) return 0;

	int node = L + n - 1;

	while (Tree[node] < val){
		while (node % 2 == 1){
			node /= 2;
			if (node <= 1) return n+1;
		}
		node++;
	}

	while (node < n){
		node = node * 2;
		if (Tree[node] < val) node++;
	}

	int index = node - (n - 1);
	//if (index>R) return n+1;
	return (index <= R ? index : 0);
}



