void pre(int n){
	for(int i = 1; i <= n; i++){
		b[i].v = a[i];
		if(i==1) b[i].l = -1;
		else b[i].l = i-1;
		if(i==n) b[i].r = -1;
		else b[i].r = i+1;
	}
	//u既是a中位置, 也是b中位置
	for(int i = 1; i <= n; i++){
		int u = p[i];
		l[u][0] = b[u].l, l[u][1] = -1;
		if(l[u][0]!=-1) l[u][1] = b[l[u][0]].l;
		r[u][0] = b[u].r, r[u][1] = -1;
		if(r[u][0]!=-1) r[u][1] = b[r[u][0]].r;
		deleteNode(u);
	}
