const int maxn = 1e5 + 5;
int v[maxn], n, st[4*maxn];
bool f1, f2;

int left(int index){return index*2;}
int right(int index){return index*2+1;}
int mid(int l, int r){return l + (r-l)/2;}

void build(int p, int l, int r)
{
	if(l == r)
	{
		st[p] = v[l];
		return;
	}
	build(left(p), l, mid(l, r));
	build(right(p), mid(l, r)+1, r);
	st[p] = max(st[left(p)], st[right(p)]);
}

int query(int p, int l, int r, int i, int j)
{
	if(r < i || l > j) return -1;
	if(l >= i && r <= j) return st[p];
	return max(query(left(p), l, mid(l, r), i, j), query(right(p), mid(l, r)+1, r, i, j));
}

int query(int i, int j){return query(1, 0, n-1, i, j);}
int big_right(int index, int left, int right)
{
	if(left == right && v[left] > v[index]) return left;
	else if(left == right) return -1;
	int l = query(left, mid(left, right));
	if(l > v[index]) return big_right(index, left, mid(left, right));
	return big_right(index, mid(left, right)+1, right);
}
int big_left(int index, int left, int right)
{
	if(left == right && v[left] > v[index]) return left;
	else if(left == right) return -1;
	int r = query(mid(left, right)+1, right);
	if(r > v[index]) return big_left(index, mid(left, right)+1, right);
	return big_left(index, left, mid(left, right));
}
