	loop(i, n) scanf("%d", &v[i]);
	build(1, 0, n-1);
	ll ans = 0;
	loop(i, n)
	{
		if(v[i] == n) continue;
		int l = big_left(i, 0, i), r = big_right(i, i, n-1);
		int l2 = (l == 0) ? -1 : l+1, r2 = (r == n-1) ? n : r-1;
		if(l != -1 && l != 0) l2 = big_left(i, 0, l-1);
		if(r != -1 && r != n-1) r2 = big_right(i, r+1, n-1);
		if(r2 == -1) r2 = n;
		if(l != -1) ans += 1LL*(v[i])*(l-l2)*(((r==-1) ? n:r) -i);
