		return std::max(lhs, rhs);
	}
};

template<class T, class Op = std::plus<>>class seg_tree
{
	std::vector<T> vec;
	T unit;
	std::size_t sz;
	Op op;
	static std::size_t get_size(std::size_t s)
	{
		std::size_t ret = 1;
		while (ret < s)
		{
			ret <<= 1;
		}
		return ret;
	}
public:
	seg_tree(std::size_t size, T u = T(), Op f = Op()) :vec(), unit(u), sz(get_size(size)), op(f)
	{
		vec.assign(2 * sz, unit);
	}
	template<class Range>void set(Range const& rng)
	{
		std::size_t i = 0;
		for (auto&& v : rng)
		{
			vec[i + sz] = v;
			if (++i >= sz)
			{
				break;
			}
		}
		for (auto s = sz / 2; s > 0; s /= 2)
		{
			for (auto i : boost::irange<std::size_t>(0, s))
			{
				vec[(i + s)] = op(vec[2 * (i + s)], vec[2 * (i + s) + 1]);
			}
		}
	}
	T operator()(std::size_t start, std::size_t end)const
	{
		T L = unit, R = unit;
		for (std::size_t a = start + sz, b = end + sz; a < b; a >>= 1, b >>= 1)
		{
			if (a & 1)
			{
				L = op(L, vec[a++]);
			}
			if (b & 1)
			{
				R = op(vec[--b], R);
			}
		}
		return op(L, R);
	}
	void update(std::size_t i, T const& v)
	{
		auto k = i + sz;
		vec[k] = v;
		while (k >>= 1)
		{
			vec[k] = op(vec[2 * k], vec[2 * k + 1]);
		}
	}
};
typedef seg_tree<std::int64_t, max_t> max_seg_tree;

template<class Rng, class Pred>auto partition_point(Rng const& rng, Pred pred)
{
	return std::partition_point(rng.begin(), rng.end(), pred);
}

class memoization_t
{
	std::map<std::int64_t, index_t> map;
	max_seg_tree seg;
	std::size_t N;
	std::int64_t run(index_t lhs, index_t rhs, index_t mid, std::int64_t v)
	{
		if (lhs == rhs)
		{
			return 0;
		}
		else
		{
			std::priority_queue<std::pair<std::int64_t, index_t>> queue;
			for (auto i : boost::irange(lhs, mid))
			{
				queue.emplace(seg(i, mid), i);
			}
			for (auto i : boost::irange(mid + 1, rhs + 1))
			{
				queue.emplace(seg(mid + 1, i + 1), i);
			}
			std::int64_t sum = 0;
			auto ilhs = lhs;
			auto irhs = rhs;
			while (queue.size())
			{
				auto p = queue.top();
				auto s = p.first;
				auto i = p.second;
				queue.pop();
				if (i < mid)
				{
					sum += (i - ilhs + 1) * (irhs - mid + 1) * s;
					ilhs = i + 1;
				}
				else
				{
					sum += (irhs - i + 1) * (mid - ilhs + 1) * s;
					irhs = i + 1;
				}
			}
			if (lhs != mid)
			{
				auto s = seg(lhs, mid);
				sum += run(lhs, mid - 1, map[s], s);
			}
			if (rhs != mid)
			{
				auto s = seg(mid + 1, rhs + 1);
				sum += run(mid + 1, rhs, map[s], s);
			}
			return sum;
		}
		return 0;
	}
public:
	memoization_t(std::vector<std::int64_t>const& values) :map(), seg(values.size()), N(values.size())
	{
		for (auto i : boost::irange<index_t>(0, N))
		{
			map[values[i]] = i;
		}
		seg.set(values);
	}
	memoization_t(memoization_t const&) = delete;
	memoization_t(memoization_t&&) = delete;

	auto operator()()
	{
		return run(0, N - 1, map[N], N);
	}
};


void Main()
{
	int N;
	std::cin >> N;
	std::vector<std::int64_t> values(N);
	for (auto& v : values)
	{
		std::cin >> v;
	}
	memoization_t memo(values);
	std::cout << memo() << std::endl;
}

