ll seg[MAXN * 4];
void update(ll idx, ll l, ll r, ll x, ll val)
{
	if(l > x or r < x) return;
	if(x==l && x==r)
	{
		seg[idx] = val;
		return;
	}

	update(idx*2, l, mid, x, val);
	update(idx*2 + 1, mid+1, r, x, val);

	seg[idx] = max(seg[idx*2], seg[idx*2+1]);
}

ll query(ll idx, ll l,ll r, ll lq, ll rq)
{
	if(l >= lq && r <= rq) return seg[idx];
	if(l > rq or r < lq) return -INF;

	ll lv = query(idx*2, l , mid, lq, rq);
	ll rv = query(idx*2+1, mid+1 , r, lq, rq);

	return max(lv,rv);
}

ll findLeft(ll idx, ll val) // find first index that is bigger than val
{
	ll l = 0, r = idx;

	while(l+1 < r)
	{
		ll segMax = query(1,1,n,mid,idx);
		if(segMax < val)
			r = mid-1;
		else
			l = mid;
	}

	if(query(1,1,n,r,idx) > val) return r;
	return l;
	// while(d[idx] < val) idx--;
	// return idx;
}

ll findRight(ll idx, ll val) // find first index that is bigger than val
{
	ll l = idx, r = n+1;

	while(l+1 < r)
	{
		ll segMax = query(1,1,n,idx,mid);
		if(segMax < val)
			l = mid;
		else
			r = mid-1;
	}

	if(query(1,1,n,idx,l) > val) return l;
	return r;

	// while(d[idx] < val) idx++;
	// return idx;
}

