#include  <bits/stdc++.h>
using namespace std;
using ll = long long;
const int maxn = 1e5 + 5;
int t[maxn << 2], a[maxn], n, pg[maxn], ng[maxn];
ll ans = 0;
void build(int u = 1, int b = 1, int e = 100000) {
	if(b == e) return void(t[u] = a[b]);
	int m = b + e >> 1;
	build(u << 1, b, m);
	build(u << 1 | 1, m + 1, e);
	t[u] = max(t[u << 1], t[u << 1 | 1]);
}
int query(int l, int r, int u = 1, int b = 1, int e = 100000) {
	if(b > r or e < l or l > r) return 0;
	if(l <= b and e <= r) return t[u];
	int m = b + e >> 1;
	return max(query(l, r, u << 1, b, m), query(l, r, u << 1 | 1, m + 1, e));
}
int main(int argc, char const *argv[])
{
	// freopen("in", "r", stdin);
	cin >> n;
	for(int i = 1; i <= n; i++) {
		cin >> a[i];
	}
	build();
	a[0] = a[n + 1] = maxn;
	vector<int> stk = {0};
	for(int i = 1; i <= n; i++) {
		while(a[stk.back()] < a[i]) stk.pop_back();
		pg[i] = stk.back(), stk.push_back(i);
	}
	stk = {n + 1};
	for(int i = n; i >= 1; i--) {
		while(a[stk.back()] < a[i]) stk.pop_back();
		ng[i] = stk.back(), stk.push_back(i);
	}
	pg[0] = 0, ng[n + 1] = n + 1;
	for(int i = 1; i <= n; i++) {
		int l = 0, r = 0;
		if(pg[i] > 0) {
			int lx = -1, lo = 1, hi = pg[i] - 1, mid;
			if(a[pg[i] - 1] > a[i]) lx = pg[i] - 1;
			else {
				while(lo <= hi) {
					mid = lo + hi >> 1;
					if(query(mid, pg[i] - 1) < a[i]) {
						lx = mid, hi = mid - 1;
					} else {
						lo = mid + 1;
					}
				}
				lx--;
			}
			l = pg[i] - lx;
		} else {
			l = 0;
		}
		if(ng[i] < n + 1) {
			int rx = -1, lo = ng[i] + 1, hi = n, mid;
			if(a[ng[i] + 1] > a[i]) rx = ng[i] + 1;
			else {
				while(lo <= hi) {
					mid = lo + hi >> 1;
					if(query(ng[i] + 1, mid) < a[i]) {
						rx = mid, lo = mid + 1;
					} else {
						hi = mid - 1;
					}
				}
				rx++;
			}
			r = rx - ng[i];
		} else {
			r = 0;
		}
		ll ls = ll(l) * ll(ng[i] - i);
		ll rs = ll(r) * ll(i - pg[i]);
		ans += (ls + rs) * a[i];
	}
	cout << ans << endl;
	return 0;
}

