#define M 100005
using namespace std;
using  P = pair<int,int>;
using LL = long long;
int n,in[M];
vector<P> s;
set<int> sp;
int main()
{
    while (~scanf("%d", &n)) {
        s.clear();
        sp.clear();
        REP(i,1,n) {
            scanf("%d", &in[i]);
            s.push_back(make_pair(in[i], i));
        }
        sort(s.begin(), s.end(), greater<P>());

        auto find_less = [&](int x) {
            auto it = sp.lower_bound(x);
            if (it==sp.begin()) return 0;
            it--;
            return *it;
        };
        auto find_more = [&](int x) {
            auto it = sp.upper_bound(x);
            if (it==sp.end()) return n+1;
            return *it;
        };

        LL ans = 0;
        for (auto itt: s) {
            int num = itt.first;
            int pos = itt.second;

            int l = find_less(pos);
            int r = find_more(pos);
            if (l!=0) {
                int ll = find_less(l);
                ans += (LL)(l-ll) * (r-pos) * num;
            }
            if (r!=n+1) {
                int rr = find_more(r);
                ans += (LL)(pos-l) * (rr-r) * num;
            }

            sp.insert(pos);
        }
        printf("%lld\n", ans);
    }
    return 0;
}

