long long calc(int x, set<int> &s)
{
  auto l = s.lower_bound(x), r = l;
  l--;
  long long res = 0;
  if (l != s.begin())
    res += 1LL * (*r - x) * (*l - *prev(l));

  auto rr = next(r);
  if (rr != s.end())
    res += 1LL * (x - *l) * (*rr - *r);

  return res;
}

