using namespace std;
typedef long long int ll;

int main() {
	int n; cin >> n;
	vector<int> p(n);
	int ra[n + 1];
	for (int i = 0; i < n; i++) {
		cin >> p[i];
		ra[p[i]] = i;
	}
	ll ans = 0;
	set<int> S;
	S.insert(-1); S.insert(n);
	for (ll d = n; d >= 1; d--) {
		int i = ra[d];
		auto it = S.lower_bound(i);
		int r = *it;
		it--;
		int l = *it;
		if (r == n && l == -1) {
			S.insert(i);
			continue;
		}
		if (l == -1) {
			it++; it++;
			int rr = *it;
			ans += d * (rr - r) * (i + 1);
		}
		else if (r == n) {
			it--;
			int ll = *it;
			ans += d * ((l - ll)) * (n - i);
		}
		else {
			it--;
			int ll = *it;
			it++; it++; it++;
			int rr = *it;
			ans += (l - ll) * (r - i) * d;
			ans += (rr - r) * (i - l) * d;
		}
		S.insert(i);
	}
	cout << ans << endl;
}

