#include<bits/stdc++.h>
using namespace std;
int a[100001],ST[(1<<18)];
long long ans=0;
void build(int l,int r,int p){
    if(l==r){
        ST[p]=r;
        return;
    }
    int mid=(l+r)/2;
    build(l,mid,p*2);
    build(mid+1,r,p*2+1);
    ST[p] = (a[ST[p*2]] > a[ST[p*2+1]]) ? ST[p*2] : ST[p*2+1];
}
int query(int l,int r ,int p,int i,int j){
    if(l>j | r<i){
        return -1;
    }
    if(l>=i && r<=j){
        return ST[p];
    }
    int mid=(l+r)/2;
    int p1=query(l,mid,p*2,i,j);
    int p2=query(mid+1,r,p*2+1,i,j);
    if(p1 == -1)
        return p2;
    if(p2 == -1)
        return p1;
    return (a[p1] > a[p2]) ? p1 : p2;
}
int main(){
