        while(l<=r){
            if(l==r){
                int pos=query(1,n,1,l,l);
                if(a[pos]>a[i]){
                    pre1=pos;
                }
                break;
            }
            int mid=(l+r)/2;
            int pos=query(1,n,1,mid+1,r);
            if(a[pos]>a[i]){
                pre1=pos;
                l=pos+1;
            }
            else{
