        for (int i = 0; i < n; i++) {
            if (i + power[j] <= n)
            dp[i][j] = max(dp[i][j - 1], dp[i + power[j - 1]][j - 1]);
        }
    }

    ll ans = 0;

    for (int i = 0; i < n; i++) {
        int l = i + 1, r = n - 1, mid;
        int r1 = n, r2 = n, l1 = -1, l2 = -1;
        while (l <= r) {
            mid = (l + r) / 2;
            if (f(i + 1, mid) > a[i]) {
                r1 = mid;
                r = mid - 1;
            }

            else {
                l = mid + 1;
            }
        }

        l = r1 + 1, r = n - 1;
        while (l <= r) {
            mid = (l + r) / 2;
            if (f(r1 + 1, mid) > a[i]) {
                r2 = mid;
                r = mid - 1;
            }

            else {
                l = mid + 1;
            }
        }

        l = 0, r = i - 1;
        while (l <= r) {
            mid = (l + r) / 2;
            if (f(mid, i - 1) > a[i]) {
                l2 = mid;
                l = mid + 1;
            }
            else {
                r = mid - 1;
            }
        }

        l = 0, r = l2 - 1;
        while (l <= r) {
            mid = (l + r) / 2;
            if (f(mid, l2 - 1) > a[i]) {
                l1 = mid;
                l = mid + 1;
            }
            else {
                r = mid - 1;
            }
        }

//        cout << l1 << ' ' << l2 << ' ' << r1 << ' ' << r2 << '\n';

        ans += a[i] * ((ll) (r2 - r1) * (i - l2) + (ll) (l2 - l1) * (r1 - i));

    }

    cout << ans;

}

