int solve()
{
    int N;
    std::cin >> N;

    vector<int> A(N);
    for (int i = 0; i < N; ++i)
        std::cin >> A[i];

    ll sum = 0;
    for (int i = 0; i < N - 1; ++i)
    {
        int maxValue = A[i], secondMaxValue = A[i + 1];

        if (maxValue < secondMaxValue)
            std::swap(maxValue, secondMaxValue);

        sum += secondMaxValue;

        for (int j = i + 2; j < N; ++j)
        {
            if (A[j] > maxValue)
            {
                secondMaxValue = maxValue;
                maxValue = A[j];
            }
            else if (A[j] > secondMaxValue)
            {
                secondMaxValue = A[j];
            }

            sum += secondMaxValue;
        }
    }

    return sum;
}

int main()
{
    std::cout << solve() << std::endl;

    return 0;
}

