int n, p[N], t[N * 4];

void build (int v, int tl, int tr){
    if (tl == tr) t[v] = p[tl];
    else {
        int tm = tl + tr >> 1;
        build ((v << 1), tl, tm);
        build ((v << 1) + 1, tm + 1, tr);
        t[v] = max(t[(v << 1)], t[(v << 1) + 1]);
    }
}

int get (int v, int tl, int tr, int l, int r){
    if (tl > r || tr < l) return 0;
    if (l <= tl && tr <= r) return t[v];
    int tm = tl + tr >> 1;
    return max(get((v << 1), tl, tm, l, r), get((v << 1) + 1, tm + 1, tr, l, r));
}

int findPRE (int l, int r, int k){
    int lf = l, rg = r;
    while (rg - lf > 1){
        int mid = lf + rg >> 1;
        if (get(1, 1, n, mid, r) > k) lf = mid;
        else rg = mid;
    }
    if (get(1, 1, n, rg, r) > k) return rg;
    else if (get(1, 1, n, lf, r) > k) return lf;
    return 0;
}

int findSUFF (int l, int r, int k){
    int lf = l, rg = r;
    while (rg - lf > 1){
        int mid = lf + rg >> 1;
        if (get(1, 1, n, l, mid) > k) rg = mid;
        else lf = mid;
    }
    if (get(1, 1, n, l, lf) > k) return lf;
    else if (get(1, 1, n, l, rg) > k) return rg;
    return (n + 1);
}

int main (){
    scanf ("%d", &n);
    for (int i = 1; i <= n; ++i) scanf ("%d", p + i);
    build (1, 1, n);
    ll ans = 0;
    for (int i = 1; i <= n; ++i){
        int p1 = findPRE(1, i - 1, p[i]);
        int p2 = findPRE(1, p1 - 1, p[i]);
        int s1 = findSUFF(i + 1, n, p[i]);
        int s2 = findSUFF(s1 + 1, n, p[i]);
        ll kol = 0;
        kol += 1ll * (p1 - p2) * (s1 - i);
        kol += 1ll * (s2 - s1) * (i - p1);
        ans += kol * 1ll * p[i];
    }
    return !printf ("%lld\n", ans);
}

