const int MAX_N = 1<<17;
int n;
vector<int> dat(2*MAX_N-1,0);
// [0.._n) 0以上_n-1以下
void init_segtree(const int n_) {
  n = 1;
  while(n < n_) n *= 2;
  for(int i = 0; i < 2 * n-1; i++) {
    dat[i] = INT_MIN;
  }
}

// k番目の値(0-indexed)をaに変更
void update_segtree(int k, int a) {
  k += n-1;
  dat[k] = a;
  while(k > 0) {
    k = (k-1) / 2;
    dat[k] = max(dat[k*2+1], dat[k*2+2]);
  }
}

// [a,b)の最小値を求める
// query(a,b,0,0,n)として呼ぶ
int query_segtree(const int a, const int b, const int k, const int left, const int right) {
  if(right <= a || b <= left) return INT_MIN;
  if(a <= left && right <= b) return dat[k];
  else {
    const int vleft = query_segtree(a, b, k*2+1, left, (left + right) / 2);
    const int vright = query_segtree(a, b, k*2+2, (left + right) / 2, right);
    return max(vleft, vright);
  }

}

vector<int> P, rev;

inline ll comb(int m, int n) {
  const ll a = n - m;
  return a * (a - 1LL) / 2LL;
}

ll solve(int left, int right) {
  //  cout << left << "," << right << endl;
  ll ans = 0;
  if(right - left <= 1) ;
  else if(right - left <= 2) {
    ans =  min(P[left], P[left+1]);
    return ans;
  }
  else {
  int v1 = query_segtree(left, right, 0, 0, n);
  int idx1 = rev[v1];
  int v2 = query_segtree(left, idx1, 0, 0, n);
  int v3 = query_segtree(idx1+1, right, 0, 0, n);
  ll tmp  = (ll)max(v2, v3);
  int idx2 = rev[max(v2, v3)];
  if(idx1 < idx2) {
    tmp *= comb(left, right) - comb(left, idx2) - comb(idx1 + 1, right) + comb(idx1 + 1, idx2);
    ans += tmp;
    //    cout << tmp << endl;
    ans += solve(left, idx2);
    ans += solve(idx1 + 1, right);
    ans -= solve(idx1 + 1, idx2);
  } else {
    tmp *= comb(left, right) - comb(left, idx1) - comb(idx2 + 1, right) + comb(idx2 + 1, idx1);
    ans += tmp;
    //    cout << tmp << endl;
    ans += solve(left, idx1);
    ans += solve(idx2 + 1, right);
    ans -= solve(idx2 + 1, idx1);

  }

  }
  //  cout << "Answer=" << left << "," << right <<  "=" << ans << endl;
  return ans;
}

