                sp[i][j]=max(sp[i][j-1],sp[i+(1<<(j-1))][j-1]);
            }
        }


        stack<ll>b;
        for(i=0;i<n+2;i++){
            if(b.empty())b.push(i);
            else{
                while(!b.empty() && a[b.top()]<a[i]){
                    rgt[b.top()]=i;
                    b.pop();
                }b.push(i);
            }
        }
        while(!b.empty()){
            rgt[b.top()]=n+2;
            b.pop();
        }

        for(i=n+1;i>=0;i--){
            if(b.empty())b.push(i);
            else{
                while(!b.empty() && a[b.top()]<a[i]){
                    lft[b.top()]=i;
                    b.pop();
                }b.push(i);
            }
        }
        while(!b.empty()){
            lft[b.top()]=-1;
            b.pop();
        }

        ll ans=0;

        //for(i=1;i<=n;i++)cout<<lft[i]<<","<<rgt[i]<<"\t"; cout<<"\n";

        for(i=1;i<=n;i++){
            ll ridx = rgt[i], lidx=lft[i];
            ll rx=0,lx=0;
            if(ridx<n+1){
                ll lo=ridx+1,hi=n,mid=(lo+hi)/2;
                while(hi-lo>1){
                    if(query(ridx+1,mid)<a[i])lo=mid;
                    else hi=mid;
                    mid=(lo+hi)/2;
                }
                if(lo<n+1 && query(ridx+1,lo)<a[i])rx=max(rx,lo-ridx);
                ans +=((i-lft[i])*(rx+1)*a[i]);
            }

            if(lidx>0){
                ll lo=1,hi=lidx-1,mid=(lo+hi)/2;
                while(hi-lo>1){
                    if(query(mid,lidx-1)<a[i])hi=mid;
                    else lo=mid;
                    mid=(lo+hi)/2;
                }
                if(hi>0 && query(hi,lidx-1)<a[i])lx=max(lx,lidx-hi);
                ans +=((rgt[i]-i)*(lx+1)*a[i]);
            }
            //cout<<i<<":: lft = "<<lft[i]<<" lx = "<<lx<<" rgt = "<<rgt[i]<<" rx = "<<rx<<" ans = "<<ans<<"\n";
        }

        cout<<ans;


    }
