const std::pair<ll, ll> &calc_second(std::vector<ll>::iterator first, std::vector<ll>::iterator last) {
    static std::pair<ll, ll> ret;
    ret.first = ret.second = 0;
    for (; first != last; ++first) {
        if (*first > ret.first) {
            ret.second = ret.first;
            ret.first = *first;
        } else if (*first > ret.second) {
            ret.second = *first;
        } else {}
    }
    return ret;
}

int main() {
    ll N;
    cin >> N;

    std::vector<ll> P(N);
    std::for_each(P.begin(), P.end(), [](auto &x) { cin >> x; });

    ll ans = 0;

    std::vector<pair<ll, ll>> dp(N, make_pair(0, 0));
    for (ll l = 0; l < N - 1; ++l) {
        {
            const ll r = l + 1;
            dp[r].first = std::max(P[l], P[r]);
            dp[r].second = std::min(P[l], P[r]);
            ans += dp[r].second;
        }
        for (ll r = l + 2; r < N; ++r) {
            if (P[r] > dp[r - 1].first) {
                dp[r].second = dp[r - 1].first;
                dp[r].first = P[r];
            } else if (P[r] > dp[r - 1].second) {
                dp[r].first = dp[r-1].first;
                dp[r].second = P[r];
            } else {
                dp[r] = dp[r - 1];
            }
            ans += dp[r].second;
        }
    }

    cout << ans << endl;

    return 0;
}

