using namespace std;
using ll = long long;

constexpr int INF = 1e9;

struct RMQ {
  int N;
  vector<int> dat;

  RMQ(int n) {
    N = 1;
    while (N < n) N *= 2;
    dat.resize(N * 2, INF);
  }

  void update(int k, int v) {
    k += N;
    dat[k] = v;
    while (k > 1) {
      k >>= 1;
      dat[k] = min(dat[k * 2], dat[k * 2 + 1]);
    }
  }

  int query(int l, int r) {
    l += N;
    r += N - 1;
    int res = INF;
    while (l <= r) {
      if ((l & 1) == 1) res = min(res, dat[l++]);
      if ((r & 1) == 0) res = min(res, dat[r--]);
      l >>= 1;
      r >>= 1;
    }
    return res;
  }
};




int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  ll N; cin >> N;
  RMQ rmq(N), rmq2(N);
  vector<int> P(N); rep(i, N) cin >> P[i];
  vector<int> pos(N + 1);
  rep(i, N) {
    cin >> P[i];
    pos[P[i]] = i;
  }
  ll ans = 0;
  for (int i = N; i >= 1; i--) {
    int k = pos[i];
    ll r = rmq.query(k, N);
    ll r2 = r != INF ? rmq.query(r + 1, N) : INF;
    ll l = -rmq2.query(0, k);
    ll l2 = l != -INF ? -rmq2.query(0, l) : -INF;
    ans += i * (k - max(l, -1LL)) * (min(N, r2) - min(r, N));
    ans += i * (max(l, -1LL) - max(l2, -1LL)) * (min(r, N) - k);
    rmq.update(k, k);
    rmq2.update(k, -k);
  }
  cout << ans << endl;
}

