class BIT {
  int n;
  vecpii bit;
  const pii INIT = make_pair(-1, -1);

 public:

  BIT(int n) : n(n) {
      init(n);
  }

  void init(int n){
      bit.resize(n + 1);
      FORO(i, n + 1) {
          bit[i] = INIT;
      }
  }

  void update_2max(pii &x, int a) {
      if (a > x.first) {
          x.second = x.first;
          x.first = a;
      } else if (a > x.second) {
          x.second = a;
      }
  }

  void update(int i, int x) {
      while (i <= n) {
          update_2max(bit[i], x);
          i += i & -i;
      }
  }

  pii get_2max(int i) {
      pii ret = INIT;
      while (i > 0) {
          update_2max(ret, bit[i].first);
          update_2max(ret, bit[i].second);
          i -= i & -i;
      }
      return ret;
  }
};

