  size_t n;
  cin >> n;
  vector<size_t> a(n);
  cin >> a;
  --a;
  vector<size_t> rev(n);
  for (size_t i = 0; i < n; ++i) {
    rev[a[i]] = i;
  }
  reverse(rev.begin(), rev.end());

  set<int> idx;
  idx.insert(-1);
  idx.insert(-2);
  idx.insert(n);
  idx.insert(n + 1);
  int64_t out = 0, val = n;
  for (const int k: rev) {
    auto i = idx.lower_bound(k);
    array<int, 4> xs =
      {*std::prev(i, 2), *std::prev(i, 1), *i, *std::next(i, 1)};
    if (xs[0] == -2) xs[0] = -1;
    if (xs[3] == n + 1) xs[3] = n;

    out += val * (xs[1] - xs[0]) * (xs[2] - k);
    out += val * (k - xs[1]) * (xs[3] - xs[2]);
    idx.insert(k);
    --val;
  }
  cout << out;


  return EXIT_SUCCESS;
}

