    a[n + 1] = INF; L[1] = 1; R[n] = n;
    s[0] = 0;
    for(int i = 1; i <= n + 1; i++) {
        while (a[i] > a[s[top]]) {
            top--;
        }
        L[i] = s[top] + 1;
        s[++top] = i;
    }
    fill(s, s + n + 2, 0); s[0] = n + 1; top = 0;
    for(int i = n; i >= 0; i--) {
        while(a[i] > a[s[top]]) {
           top--;
        }
        R[i] = s[top] - 1;
        s[++top] = i;
    }
    //  for(int i = 1; i <= n; i++) {
    //      cout << L[i] << " " << R[i] << "\n";
    //  }
    long long sum = 0;
    a[0] = a[n + 1] = 0;
    for(int i = 1; i <= n; i++) {
        int l = L[i], r = R[i];
        int tot = 0;
        if(l - 1 >= 1) {
            int ln = L[l - 1];
            int p = block.queryleft(ln, max(l - 2, ln), a[i]);
           // int lsum = p + 1 <= l - 1 ? (l - 1 - (p + 1) + 1) : 
         //  cout << i << " " << ln << " " << p + 1 << " " << l - 1 << " ";
            if(p + 1 > l - 1) p = -1;
            if(p == -1) tot = (r - i + 1) * a[i]; // [p + 1, l - 1]
            else
            tot = (l - 1 - (p + 1) + 1) * (r - i + 1) * a[i];
        //    cout << tot << "\n";
            sum += tot;
        }
        if(r + 1 <= n) {
            int rn = R[r + 1];
            int p = block.queryright(min(r + 2, rn), rn, a[i]);
           // cout << i << " " << rn << " " << r + 1 << " " << p - 1 << " "; // [r + 1, p - 1]
          //  if(p == -1) p = rn + 1;
            if(r + 1 > p - 1) p = -1;
            if(p == -1) tot = (i - l + 1) * a[i];
            else
            tot = (p - 1 - (r + 1) + 1) * (i - l + 1) * a[i];
           // cout << tot << "\n";
            sum += tot;
        }
    }
    cout << sum;
    return 0;
}

