	for (int i = 0; l+i <= r-i; ++i) {
		swap(s[l+i], s[r-i]);
		s[l + i] = s[l + i] == 'L' ? 'R' : 'L';
		s[r - i] = s[r - i] == 'L' ? 'R' : 'L';
	}
}

long long int count(string& s) {
	long long int n = 0;
	for (int i = 0; i < s.length(); ++i) {
		if (   s[i] == 'L' && i > 0 && s[i-1] == 'L'
			|| s[i] == 'R' && i < s.length()-1 && s[i + 1] == 'R'
			) {
			++n;
		}
	}
	return n;
}

