        for (j = i - 1; j >= 0; --j) {
            if (p[j] > p[i]) {
                L1 = j;
                break;
            }
        }
        for (--j; j >= 0; --j) {
            if (p[j] > p[i]) {
                L0 = j;
                break;
            }
        }

        auto R0 = n;
        auto R1 = n;
        for (j = i + 1; j < n; ++j) {
            if (p[j] > p[i]) {
                R0 = j;
                break;
            }
        }
        for (++j; j < n; ++j) {
            if (p[j] > p[i]) {
                R1 = j;
                break;
            }
        }

        auto cases = 0LL;
        {
            auto Ls = L1 - L0;
            auto Rs = R0 - i;
            cases += large{Ls} * large{Rs};
        }
        {
            auto Ls = i - L1;
            auto Rs = R1 - R0;
            cases += large{Ls} * large{Rs};
        }
        sum += cases * p[i];
    }

    cout << sum << endl;
    return 0;
}

