using namespace std;

const int MAX_N = 1 << 17;
typedef pair<long long, long long> PLL;
static long long M, N, P[100000], A[100000][3], B[100000][3], INF = 1000000000, ANS = 0;
static PLL DAT[2 * MAX_N - 1];

void init(int N_, int X) {
	N = 1;
	while (N < N_) N *= 2;
	for (int i = 0; i < 2 * N - 1; i++) DAT[i] = { X, X };
}

void update(int K, int A) {
	K += N - 1;
	DAT[K].first = A;
	while (K > 0) {
		K = (K - 1) / 2;
		long long V[4] = {};
		V[0] = DAT[K * 2 + 1].first;
		V[1] = DAT[K * 2 + 1].second;
		V[2] = DAT[K * 2 + 2].first;
		V[3] = DAT[K * 2 + 2].second;
		sort(V, V + 4);
		DAT[K] = { V[3], V[2] };
	}
}

void update2(int K, int A) {
	K += N - 1;
	DAT[K].first = A;
	while (K > 0) {
		K = (K - 1) / 2;
		long long V[4] = {};
		V[0] = DAT[K * 2 + 1].first;
		V[1] = DAT[K * 2 + 1].second;
		V[2] = DAT[K * 2 + 2].first;
		V[3] = DAT[K * 2 + 2].second;
		sort(V, V + 4);
		DAT[K] = { V[0], V[1] };
	}
}

PLL query(int A, int B, int K, int L, int R) {
	if (R <= A || B <= L) return { -1, -1 };
	else if (A <= L && R <= B) return DAT[K];
	else {
		PLL VL = query(A, B, K * 2 + 1, L, (L + R) / 2);
		PLL VR = query(A, B, K * 2 + 2, (L + R) / 2, R);
		long long V[4] = {};
		V[0] = VL.first;
		V[1] = VL.second;
		V[2] = VR.first;
		V[3] = VR.second;
		sort(V, V + 4);
		return { V[3], V[2] };
	}
}

PLL query2(int A, int B, int K, int L, int R) {
	if (R <= A || B <= L) return { M, M };
	else if (A <= L && R <= B) return DAT[K];
	else {
		PLL VL = query2(A, B, K * 2 + 1, L, (L + R) / 2);
		PLL VR = query2(A, B, K * 2 + 2, (L + R) / 2, R);
		long long V[4] = {};
		V[0] = VL.first;
		V[1] = VL.second;
		V[2] = VR.first;
		V[3] = VR.second;
		sort(V, V + 4);
		return { V[0], V[1] };
	}
}

int main() {
	cin >> N;
	for (int i = 0; i < N; i++) cin >> P[i];
	for (int i = 0; i < N; i++) {
		A[i][0] = A[i][1] = -1;
		A[i][2] = i;
		B[i][0] = i;
		B[i][1] = B[i][2] = M;
	}
	M = N;
	init(N, -1);
	for (int i = 0; i < M; i++) {
		PLL p = query(P[i], M, 0, 0, N);
		A[i][0] = p.second;
		A[i][1] = p.first;
		update(P[i] - 1, i);
	}
	init(N, M);
	for (int i = M - 1; i >= 0; i--) {
		PLL p = query2(P[i], M, 0, 0, N);
		B[i][1] = p.first;
		B[i][2] = p.second;
		update2(P[i] - 1, i);
	}
	for (int i = 0; i < M; i++) {
		ANS += (A[i][1] - A[i][0]) * (B[i][1] - B[i][0]) * P[i];
		ANS += (A[i][2] - A[i][1]) * (B[i][2] - B[i][1]) * P[i];
	}
	cout << ANS << endl;
}

