int main(){

	int n;
	cin >> n;
	vector<int> p(n);
	rep(i,n){
		cin >> p[i];
		p[i]--;
	}

	vector<int> idx(n);
	rep(i,n) idx[p[i]] = i;

	set<int> setidx;
	vector<ll> c(n);

	for(int i = n-1; i >= 0; i--){
		// calc c
		int idxi = idx[i];
		setidx.insert(idxi);

		vector<int> leftidx(2,-1);
		vector<int> rightidx(2,n);
		{
			// calc left
			auto itr = setidx.find(idxi);
			rep(j,2){
				if(itr-- == setidx.begin()) break;
				leftidx[j] = *itr;
			}
		}

		{
			// calc right
			auto itr = setidx.find(idxi);
			rep(j,2){
				if(++itr == setidx.end()) break;
				rightidx[j] = *itr;
			}
		}

		vector<int> ls(2);
		vector<int> rs(2);
		ls[0] = idxi - leftidx[0];
		ls[1] = leftidx[0] - leftidx[1];
		rs[0] = rightidx[0] - idxi;
		rs[1] = rightidx[1] - rightidx[0];

		c[idxi] = (ll)ls[0]*rs[1] + (ll)ls[1]*rs[0];

	}

	ll res = 0;
	rep(i,n) res += (p[i]+1) * c[i];
	cout << res << endl;

	return 0;
}

