#define int long long

void sinsert(vector<int>& v, int i) {
    v.insert(lower_bound(v.begin(), v.end(), i), i);
}

int left(vector<int>& seen, int sz, int fnd, int ind) {
    if(fnd == 1) return 0;
    int lsz = seen[fnd-1]-seen[fnd-2];
    int rsz = seen[fnd]-ind;
    return lsz*rsz;
}

int right(vector<int>& seen, int sz, int fnd, int ind) {
    if(fnd == sz-1) return 0;
    int rsz = seen[fnd+1]-seen[fnd];
    int lsz = ind-seen[fnd-1];
    return lsz*rsz;
}

int32_t main() {

    int n; cin >> n;
    vector<int> p(n);
    for(int i = 0; i < n; ++i) cin >> p[i];

    vector<int> index(n+1);
    for(int i = 0; i < n; ++i) {
        index[p[i]] = i;
    }

    vector<int> seen = {-1, index[n], n};
    int sz = 3;

    int ans = 0;

    for(int num = n-1; num > 0; --num) {
        int ind = index[num];
        int it = lower_bound(seen.begin(), seen.end(), ind) - seen.begin();

        int c1 = left(seen, sz, it, ind), c2 = right(seen, sz, it, ind);

        ans += (c1+c2)*num;

        sinsert(seen, ind);
        sz++;
    }

    cout << ans << endl;

    return 0;
}

