template <typename T>
constexpr T popCount(const T u)
{
#ifdef __has_builtin
    return u == 0 ? T(0) : (T)__builtin_popcountll(u);
#else
    unsigned long long v = static_cast<unsigned long long>(u);
    return v = (v & 0x5555555555555555ULL) + (v >> 1 & 0x5555555555555555ULL), v = (v & 0x3333333333333333ULL) + (v >> 2 & 0x3333333333333333ULL), v = (v + (v >> 4)) & 0x0F0F0F0F0F0F0F0FULL, static_cast<T>(v * 0x0101010101010101ULL >> 56 & 0x7f);
#endif
}
template <typename T>
constexpr T log2p1(const T u)
{
#ifdef __has_builtin
    return u == 0 ? T(0) : T(64 - __builtin_clzll(u));
#else
    unsigned long long v = static_cast<unsigned long long>(u);
    return v = static_cast<unsigned long long>(v), v |= (v >> 1), v |= (v >> 2), v |= (v >> 4), v |= (v >> 8), v |= (v >> 16), v |= (v >> 32), popCount(v);
#endif
}
template <typename T>
constexpr T clog(const T v) { return v == 0 ? T(0) : log2p1(v - 1); }
template <typename T>
constexpr T msbp1(const T v) { return log2p1(v); }
template <typename T>
constexpr T lsbp1(const T v)
{
#ifdef __has_builtin
    return __builtin_ffsll(v);
#else
    return v == 0 ? T(0) : popCount((v & (-v)) - T(1)) + T(1);
#endif
}
template <typename T>
constexpr bool ispow2(const T v) { return popCount(v) == 1; }
template <typename T>
constexpr T ceil2(const T v) { return v == 0 ? T(1) : T(1) << log2p1(v - 1); }
template <typename T>
constexpr T floor2(const T v) { return v == 0 ? T(0) : T(1) << (log2p1(v) - 1); }
//!==============================================================================================!//
//!  dP   dP   dP                            dP            dP      8888ba.88ba             dP    !//
//!  88   88   88                            88            88      88  '8b  '8b            88    !//
//!  88  .8P  .8P .d8888b. dP   .dP .d8888b. 88 .d8888b. d8888P    88   88   88 .d8888b. d8888P  !//
//!  88  d8'  d8' 88'  '88 88   d8' 88ooood8 88 88ooood8   88      88   88   88 88'  '88   88    !//
//!  88.d8P8.d8P  88.  .88 88 .88'  88.  ... 88 88.  ...   88      88   88   88 88.  .88   88    !//
//!  8888' Y88'   '88888P8 8888P'   '88888P' dP '88888P'   dP      dP   dP   dP '88888P8   dP    !//
//!==============================================================================================!//
template <std::size_t L>
class WaveletMatrix
{
public:
    using T = unsigned long long;
    template <typename InIt>
    WaveletMatrix(const InIt first, const InIt last) : sz(std::distance(first, last))
    {
        std::vector<bool> b(sz);
        std::vector<T> v(first, last);
        for (std::size_t i = 0, j = L - 1; i < L; i++, j--) {
            std::vector<T> z, o;
            for (std::size_t i = 0; i < sz; i++) { b[i] = (v[i] >> j) & 1, (b[i] ? o : z).push_back(v[i]); }
            table.push_back(FID{b}), v = z, zero.push_back(z.size());
            for (const T e : o) { v.push_back(e); }
        }
    }
    std::size_t noLessThan(std::size_t l, std::size_t r, const T v) const
    {
        assert(l < r);
        std::size_t ans = 0;
        for (std::size_t i = 0, j = L - 1; i < L; i++, j--) {
            const bool b = (v >> j) & 1;
            const std::size_t rl = table[i].rank(l), rr = table[i].rank(r);
            l = (b ? rl + zero[i] : l - rl), r = (b ? rr + zero[i] : r - rr), ans += (b ? 0 : rr - rl);
        }
        return r - l + ans;
    }
    std::size_t lessThan(const std::size_t l, const std::size_t r, const T v) const { return assert(l < r), r - l - noLessThan(l, r, v); }
    std::size_t rangeFreq(const std::size_t l, const std::size_t r, const T vinf, const T vsup) const { return assert(l < r), assert(vinf < vsup), noLessThan(l, r, vinf) - noLessThan(l, r, vsup); }
    std::size_t rank(const std::size_t l, const std::size_t r, const T v) const { return assert(l < r), rangeFreq(l, r, v, v + 1); }
    T quantile(std::size_t l, std::size_t r, std::size_t k) const
    {
        assert(l < r);
        std::size_t ans = 0;
        for (std::size_t i = 0, j = L - 1; i < L; i++, j--) {
            const std::size_t rl = table[i].rank(l), rr = table[i].rank(r);
            const bool b = rr - rl > k;
            l = (b ? rl + zero[i] : l - rl), r = (b ? rr + zero[i] : r - rr), k += (b ? 0 : k -= rr - rl), ans |= ((std::size_t)b << j);
        }
        return ans;
    }

private:
    class FID
    {
    private:
        using B = unsigned long long;
        static constexpr std::size_t BS = sizeof(B) * 8;
        const std::size_t sz;
        std::vector<B> data;
        std::vector<std::size_t> large;

    public:
        FID(const std::vector<bool>& b) : sz(b.size()), data((sz + BS) / BS, 0), large((sz + BS) / BS, 0)
        {
            std::size_t one = 0;
            for (std::size_t i = 0; i < sz; i++) {
                data[i / BS] |= ((B)b[i] << (i % BS)), one += b[i];
                if (i % BS == BS - 1) { large[(i + 1) / BS] = one; }
            }
        }
        bool operator[](const std::size_t n) const { return (data[n / BS] >> (n % BS)) & 1; }
        std::size_t rank(const std::size_t n) const { return large[n / BS] + (n % BS == 0 ? 0 : popCount(data[n / BS] & ((1ULL << (n % BS)) - 1))); }
    };
    const std::size_t sz;
    std::vector<std::size_t> zero;
    std::vector<FID> table;
};
// clang-format on
int main()
{
    const int n  = read<int>();
    const auto p = readVec<int>(n);
    WaveletMatrix<17> wm(p.begin(), p.end());
    ll ans = 0;
    for (int i = 0; i < n; i++) {
        const int v = p[i];
        int l1      = -1;
        for (int r1 = i + 1; r1 - l1 > 1;) {
            const int m1                                           = (l1 + r1) / 2;
            (wm.rangeFreq(m1, i + 1, v + 1, n + 2) == 0 ? r1 : l1) = m1;
        }
        int l2 = -1;
        for (int r2 = i + 1; r2 - l2 > 1;) {
            const int m2                                           = (l2 + r2) / 2;
            (wm.rangeFreq(m2, i + 1, v + 1, n + 2) <= 1 ? r2 : l2) = m2;
        }
        int r1 = n + 1;
        for (int l1 = i; r1 - l1 > 1;) {
            const int m1                                       = (l1 + r1) / 2;
            (wm.rangeFreq(i, m1, v + 1, n + 2) == 0 ? l1 : r1) = m1;
        }
        int r2 = n + 1;
        for (int l2 = i; r2 - l2 > 1;) {
            const int m2                                       = (l2 + r2) / 2;
            (wm.rangeFreq(i, m2, v + 1, n + 2) <= 1 ? l2 : r2) = m2;
        }
        r1--, r2--;
        const int num = (l1 - l2) * (r1 - i) + (r2 - r1) * (i - l1);
        ans += (ll)v * num;
    }
    std::cout << ans << std::endl;

    return 0;
}

