    workingSetDesc.insert(0);
    workingSetDesc.insert(N + 1);
    workingSetDesc.insert(N + 1);
    workingSetDesc.insert(numbersKeyIndexValue.at(N));

    long long result = 0;
    for (int num = N - 1; num > 0; --num)
    {
        int index = numbersKeyIndexValue.at(num);
        auto rightIte = workingSetAsc.lower_bound(index);
        int rightUpperIn = *rightIte;
        ++rightIte;
        int rightUpperOut = *rightIte;
        auto leftIte = workingSetDesc.lower_bound(index);
        int leftUpperIn = *leftIte;
        ++leftIte;
        int leftUpperOut = *leftIte;
