ll rec(ll begin, ll end, const SegmentTree<ll>& tree, map<ll, ll>& index) {
  if (end - begin < 2) return 0;
  ll maximum = tree.Aggregate(begin, end);
  ll maximum_i = index[maximum];
  ll second_maximum = max(tree.Aggregate(begin, maximum_i),
                          tree.Aggregate(maximum_i + 1, end));
  ll second_maximum_i = index[second_maximum];
  ll left = min(maximum_i, second_maximum_i);
  ll right = max(maximum_i, second_maximum_i);
  dbg(begin, end, maximum, second_maximum);
  dbg(begin, end, left, right);
  return (left - begin + 1) * (end - right) * second_maximum +
      rec(begin, right, tree, index) +
      rec(left + 1, end, tree, index) -
      rec(left + 1, right, tree, index);
}

