	long long ans = 0ll ;
	for(int i = 1 ; i <= n ; ++i)
	{
		int l = i , r = n ;
		int a = i , c = i;
		while(l <= r)
		{
			int mid = (l + r) >> 1 ;
			int x = mid-i+1 - T.LTE(i , mid , arr[i]) ;
			if(x <= 1)
			{
				l = mid+1 ;
				if(x == 1)
					a = mid ;
			}
			else
				r = mid - 1;
		}
		l = i , r = n ;
		while(l <= r)
		{
			int mid = (l + r) >> 1 ;
			int x = mid-i+1 - T.LTE(i , mid , arr[i]) ;
			if(x == 0)
			{
				l = mid+1 ;
				c = mid ;
			}
			else
				r = mid - 1;
		}
		l = 1 , r = i ;
		int b = i , d = i;
		while(l <= r)
		{
			int mid = (l + r) >> 1 ;
			int x = i-mid+1 - T.LTE(mid , i , arr[i]) ;
			if(x <= 1)
			{
				r = mid-1 ;
				if(x == 1)
					b = mid ;
			}
			else
				l = mid + 1;
		}
		l = 1 , r = i ;
		while(l <= r)
		{
			int mid = (l + r) >> 1 ;
			int x = i-mid+1 - T.LTE(mid , i , arr[i]) ;
			if(x == 0)
			{
				r = mid-1 ;
				d = mid ;
			}
			else
				l = mid + 1;
		}
		long long x1 = (i - d + 1ll) * 1ll ;
		long long x2 = (a - c) * 1ll ;
		x1 = max(x1 , 0ll) ;
		x2 = max(x2 , 0ll) ;
		ans += (x1 * x2) * arr[i] * 1ll ;
		x1 = (d - b) * 1ll ;
		x2 = (c - i + 1ll) * 1ll ;
		x1 = max(x1 , 0ll) ;
		x2 = max(x2 , 0ll) ;
		ans += (x1 * x2) * arr[i] * 1ll ;
	}
	return cout<<ans<<"\n" , 0 ;
