using namespace std;
const int N = 1e6 + 44;
const int X[] = {1,0,-1,0,1,-1,1,-1};
const int Y[] = {0,1,0,-1,1,1,-1,-1};
const int mod = 1e9 + 7;
const long long INF = 1e18;
const int inf = 1e9;

pair <int, int> t[N * 4];

int a[N], n;

pair <int, int> pairmax (pair <int, int> a, pair <int, int> b) {
	if (a.first > b.first) return a;
	return b;
}

void build (int l = 0, int r = n, int v = 0) {
	if (r - l == 1) {
		t[v] = {a[l], l};
		return;
	}
	int m = (l + r) >> 1;
	build (l, m, v + v + 1);
	build (m, r, v + v + 2);
	t[v] = pairmax (t[v + v + 1], t[v + v + 2]);
}

void upd (int pos, int x, int l = 0, int r = n, int v = 0) {
	if (r - l == 1) {
		t[v] = {x, l};
		return;
	}
	int m = (l + r) >> 1;
	if (pos < m) upd (pos, x, l, m, v + v + 1);
	else upd (pos, x, m, r, v + v + 2);
	t[v] = pairmax (t[v + v + 1], t[v + v + 2]);
}

pair <int, int> get (int L, int R, int l = 0, int r = n, int v = 0) {
	if (L <= l && r <= R) {
		return t[v];
	}
	if (R <= l || r <= L) {
		return {-1, -1};
	}
	int m = (l + r) >> 1;
	return pairmax (get (L, R, l, m, v + v + 1), get (L, R, m, r, v + v + 2));
}

long long ANS (int l, int r) {
	if (l >= r) return 0;
	pair <int, int> a = get (l, r + 1);
	int pos1 = a.second;
	upd (pos1, -inf);
	pair <int, int> b = get (l, r + 1);
	upd (pos1, a.first);
	int pos2 = b.second;
	long long ans = (min (pos1, pos2) - l + 1) * (r - max (pos1, pos2) + 1) * b.first;
	// cout << l << " " << r << " " << ans << "\n";
	// if (l != pos1)
		// ans += ANS (pos1, r);
	// if (r != pos1)
		// ans += ANS (l, pos1);
	// ans += ANS (min (pos1, pos2) + 1, max (pos1, pos2) - 1);
	if (pos1 > pos2) swap (pos1, pos2);
	ans += ANS (l, pos2 - 1) + ANS (pos1 + 1, r) - ANS (pos1 + 1, pos2 - 1);
	return ans;
}

int main () {
	// boost;
	cin >> n;
	for (int i = 0 ; i < n ; ++ i) {
		cin >> a[i];
	}
	build ();
	cout << ANS (0, n - 1);
}

