    BIT<int> bit(n + 2);
    bit.add(0, 1);
    bit.add(n+1,1);
    ll ans = 0;
    bit.add(a[n],1);
    rep(_,n){
        if(!_)continue;
        const int id = a[n-_];
        const int num = n - _;
        int sum = bit.sum(id);
        int l = bit.lower_bound(sum);
        int l2 = bit.lower_bound(sum - 1);
        int r = bit.lower_bound(sum + 1);
        int r2 = bit.lower_bound(sum + 2);
        if(id > 1 and l >= 1)ans += (long long) num * (l - l2) *  (r - id);
        if(id < n and r <= n)ans += (long long) num * (r2 - r) * (id - l);
        bit.add(id, 1);
    }
    cout << ans << endl;
}

