#define mx 100005

long long re=0;

struct me
{
    int tree,position;

}sum[mx*4],base;

me querey(int node,int be,int en,int i,int j)
{
    if(be>j||en<i)return base;
    if(be>=i&&en<=j)return sum[node];

    int left=node*2;
    int right=left+1;
    int mid=(be+en)/2;

    me re1=querey(left,be,mid,i,j);
    me re2=querey(right,mid+1,en,i,j);

    if(re1.tree>re2.tree)return re1;
    else return re2;
}

void update(int node,int be,int en,int pos,int val)
{
    if(pos<be||pos>en)return;
    if(be==en)
    {
        sum[node].tree=val;
        sum[node].position=pos;
        return;
    }

    int left=node*2;
    int right=left+1;
    int mid=(be+en)/2;

    update(left,be,mid,pos,val);
    update(right,mid+1,en,pos,val);

    if(sum[left].tree>sum[right].tree)
    {
        sum[node].tree=sum[left].tree;
        sum[node].position=sum[left].position;
    }
    else
    {
        sum[node].tree=sum[right].tree;
        sum[node].position=sum[right].position;

    }
}



