const int LOG = 20;
int n, A[100005], m[100005][20];

// maximum in [l, r]
int query(int l, int r) {
    int k = 32 - __builtin_clz(r - l + 1) - 1;
    int ans = A[m[l][k]] > A[m[r - (1 << k) + 1][k]] ? m[l][k] : m[r - (1 << k) + 1][k];
    // DUMP3(l, r, ans);
    return ans;
}

void build() {
    for (int i = 1; i <= n; ++i) m[i][0] = i;
    for (int k = 1; k < LOG; ++k) {
        for (int i = 1; i <= n; ++i) {
            if (i + (1 << k) - 1 > n) continue;
            int x = i + (1 << (k - 1));
            if (A[m[i][k - 1]] > A[m[x][k - 1]])
                m[i][k] = m[i][k - 1];
            else
                m[i][k] = m[x][k - 1];
        }
    }
}

int boundr(int l, int v) {
    if (l == n + 1) return n + 1;
    if (A[query(l, n)] <= v) {
        return n + 1;
    }
    int lo = l, hi = n;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (A[query(l, mid)] > v) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    return lo;
}

int boundl(int r, int v) {
    if (r == 0) return 0;
    debugf("boundl(%d, %d)\n", r, v);
    if (A[query(1, r)] <= v) {
        return 0;
    }
    int lo = 1, hi = r;
    while (lo < hi) {
        int mid = hi - (hi - lo) / 2;
        if (A[query(mid, r)] > v) {
            lo = mid;
        } else {
            hi = mid - 1;
        }
    }
    return lo;
}

void solve() {
    scanf("%d", &n);
    for (int i = 1; i <= n; ++i) {
        scanf("%d", &A[i]);
    }
    build();
    ll ans = 0;
    for (int i = 1; i <= n; ++i) {
        int v = A[i];
        DUMP2(i, v);
        int r = boundr(i + 1, v);
        int r2 = n + 1;
        if (r < n)
            r2 = boundr(r + 1, v);

        DUMP2(r, r2);

        int l = boundl(i - 1, v);
        int l2 = 0;
        if (l > 0) {
            l2 = boundl(l - 1, v);
        }

        DUMP2(l, l2);

        ans += 1LL * A[i] * (r2 - r) * (i - l);
        ans += 1LL * A[i] * (l - l2) * (r - i);
        DUMP(ans);
    }
    cout << ans << "\n";
}

