struct TreeQuery{
    std::vector<std::vector<std::pair<int,int>>> tree;
    std::vector<int> dist;
    TreeQuery() = delete;
    TreeQuery(const std::vector<std::vector<std::pair<int,int>>>&& t){
        tree = t;
        dist.assign(tree.size(), -1);
    }

    void memDist(const size_t v, const int d){
        if(dist[v] != -1) return;
        dist[v] = d;
        for(const std::pair<int,int> next : tree[v]) memDist(next.first, d+next.second);
    }

    size_t twoPointDist(const size_t x, const size_t y){
        std::fill(dist.begin(), dist.end(), -1);
        memDist(x, 0);
        return dist[y];
    }

    size_t furthestPoint(const size_t start){
        std::fill(dist.begin(), dist.end(), -1);
        memDist(start, 0);
        return std::max_element(dist.begin(), dist.end()) - dist.begin();
    }   

    size_t diameter(const size_t v=0){
        size_t x = furthestPoint(v);
        size_t y = furthestPoint(x);
        return dist[y];
    }
};

