        auto high_itr = itr; high_itr++;
        int y = *high_itr++; 
        int z = *high_itr;

        i64 cnt =  (x - w)*(y - k) + (k - x)*(z - y);
        ans += P[i].first * cnt;
    }

    cout << ans << endl;
}

