	template <std::size_t dim, typename T>
	modulomatrix<dim, T> powm(const modulomatrix<dim, T> & m, u6 count) {
		if (count == 0)return m.toid(); //count==
		auto r = powm(m, count / 2);
		if (count & 1)return r * r*m;
		else return r * r;
	}

