		(u6, N)
	);///////////////////////////////////////////////////////

	auto calc() {
		vector<pair<s3, s3> > buf;
		u6 result = 0;
		buf.reserve(N);
		rep(i, N) {
			s3 t;
			inputdatastream >> t;
			buf.emplace_back(t, i + 1);
		}
		sort(ALL(buf), std::greater<>());
		set<s3> st;
		st.insert(0);
		st.insert(N + 1);
		st.insert(buf[0].second);
		rep(i, 1, N) {
			u6 val = buf[i].first;
			auto idx = buf[i].second;
			auto ite = st.lower_bound(idx);
			auto p = prev(ite);
			u6 t = 0;
			if (p != st.begin()) {
				t += (*p - *prev(p))*(*ite - idx);
			}
			else {
				t += (*ite - idx);
			}
			if (ite != prev(st.end())) {
				t += (*next(ite) - *ite)*(idx - *p);
			}
			else {
				//t += 1;
			}
			//--t;
			result += t * val;
			st.insert(idx);
		}
		return result;
	}
