#include<bits/stdc++.h>
using namespace std;
const int N = 100005;
const int mod = 1e9 + 7;
int power(int a, int b){
    int res = 1;
    while(b > 0){
        if(b % 2){
            res = 1LL * res * a % mod;
        }
        a = 1LL * a * a % mod;
        b /= 2;
    }
    return res;
}
int n, seg[4 * N];
void update(int node, int start, int end, int idx){
    if(start > end || idx < start || end < idx) return;
    if(start == end){
        seg[node] = 1;
        return;
    }
    int mid = (start + end) / 2;
    update(node << 1, start, mid, idx);
    update(node << 1 | 1, mid + 1, end, idx);
    seg[node] = seg[node << 1] + seg[node << 1 | 1];
}
int findl(int node, int start, int end, int l, int r){
    if(start > end || l > r || r < start || end < l || seg[node] == 0) return 0;
    if(start == end){
        return (seg[node] ? start : 0);
    }
    int mid = (start + end) >> 1;
    int idx = findl(node << 1 | 1, mid + 1, end, l, r);
    return (idx ? idx : findl(node << 1, start, mid, l, r));
}
int findr(int node, int start, int end, int l, int r){
    if(start > end || l > r || r < start || end < l || seg[node] == 0) return n + 1;
    if(start == end){
        return (seg[node] ? start : n + 1);
    }
    int mid = (start + end) >> 1;
    int idx = findr(node << 1, start, mid, l, r);
    return (idx != n + 1 ? idx : findr(node << 1 | 1, mid + 1, end, l, r));
}
int main(){
    int a, pos[N];
    long long ans = 0;
    stack<int> s;
    scanf("%d", &n);
    for(int i = 1; i <= n; i++){
        scanf("%d", &a);
        pos[a] = i;
    }
    update(1, 0, n + 1, 0);
    update(1, 0, n + 1, n + 1);
    for(int i = n; i >= 1; i--){
        update(1, 0, n + 1, pos[i]);
        int l = findl(1, 0, n + 1, 0, pos[i] - 1);
        int ll = findl(1, 0, n + 1, 0, l - 1);
        int r = findr(1, 0, n + 1, pos[i] + 1, n + 1);
        int rr = findr(1, 0, n + 1, r + 1, n + 1);
        if(l){
            ans += 1LL * (l - ll) * (r - pos[i]) * 1LL * i;
        }
        if(r != n + 1){
            ans += 1LL * (rr - r) * (pos[i] - l) * 1LL * i;
        }
    }
    printf("%lld\n", ans);
    return 0;
}

