const LL MOD = 1e9+7;

const int MAX_LOG = 18;
class SparseTable{
private:
  int n;

  // (data, idx)
  using Data = PLL;
  using Data2 = pair<Data,Data>;
  vector<Data2> dat[MAX_LOG];
  vector<int> logTable;
public:
  Data2 top2(const Data2& d1, const Data2& d2) const {
    vector<Data> tmp{d1.FF, d1.SS, d2.FF, d2.SS};
    RSORT(tmp);
    auto res = MP(tmp[0],tmp[1]);
    for(int i=2;res.FF == res.SS;++i) res.SS = tmp[i];
    return res;
  }

  SparseTable(int n, const VL& xs): n(n)
  {
    logTable.resize(n+1);
    logTable[0] = logTable[1] = 0;
    for(int i=2;i<=n;++i)
      logTable[i] = logTable[i>>1] + 1;

    dat[0].resize(n);    
    REP(i,n){
      dat[0][i] = MP(MP(xs[i], i), MP(-1,-1));
    }
    for(int i=1;i<MAX_LOG;++i){
      dat[i].resize(n);
      for(int j=0;j<n;++j){
        auto d1 = dat[i-1][j];
        auto d2 = dat[i-1][min(n-1, j + (1<<(i-1)))];
        dat[i][j] = top2(d1, d2);
      }
    }
  }

  Data2 query(int l, int r) const{
    int d = logTable[r - l];
    return top2(dat[d][l], dat[d][r - (1<<d)]);
  }
};

struct PH{
  template<class T, class U>
  size_t operator()(const pair<T,U>& x) const{
	size_t seed = 0;
	seed ^= hash<T>{}(x.first) + 0x9e3779b9 + (seed<<6) + (seed>>2);
	seed ^= hash<U>{}(x.second) + 0x9e3779b9 + (seed<<6) + (seed>>2);
	return seed;
  }
};

using Memo = unordered_map<PII,LL,PH>;
LL solve(int l, int r, const SparseTable& sp, Memo& memo){
  if(r - l <= 1) return 0;
  if(memo.count(MP(l, r))) return memo[MP(l,r)];

  auto ds = sp.query(l, r);
  auto lval = (ds.FF.SS < ds.SS.SS ? ds.FF : ds.SS);
  auto rval = (ds.FF.SS < ds.SS.SS ? ds.SS : ds.FF);
  auto val = min(ds.FF.FF, ds.SS.FF);

  LL ans = val * (lval.SS - l + 1) * (r - rval.SS);  

  ans += solve(l, rval.SS, sp, memo);
  ans += solve(lval.SS+1, r, sp, memo);
  ans -= solve(lval.SS+1, rval.SS, sp, memo);

  memo[MP(l, r)] = ans;
  return ans;
}

