  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int N;
  cin >> N;
  VL xs(N);
  cin >> xs;

  Memo memo;
  SparseTable sp(N, xs);
  cout << solve(0, N, sp, memo) << endl;

  return 0;
}

