        t[v] = {-C,a[tl]};
    else 
    {
        ll tm = (tl + tr) / 2;
        build1(a, v*2, tl, tm);
        build1(a, v*2+1, tm+1, tr);
        ll x[4]={t[v*2].first,t[v*2].second,t[v*2+1].first,t[v*2+1].second};
        sort(x,x+4);
        t[v] = {x[2],x[3]};
    }
}
pair<ll,ll> tma(ll v, ll tl, ll tr, ll l, ll r) 
{
    if (l > r) 
        return {-C,-C};
    if (l == tl && r == tr) 
        return t[v];
    ll tm = (tl + tr) / 2;
    pair<ll,ll> p = tma(v*2, tl, tm, l, min(r, tm)), q = tma(v*2+1, tm+1, tr, max(l, tm+1), r);
    ll x[4]={p.first,p.second,q.first,q.second};
   	sort(x,x+4);
    return {x[2],x[3]};
}
void update1(ll v, ll tl, ll tr, ll pos, ll new_val) 
{
    if (tl == tr) 
    	t[v] = {-C,new_val};
    else 
    {
        ll tm = (tl + tr) / 2;
        if (pos <= tm)
            update1(v*2, tl, tm, pos, new_val);
        else
            update1(v*2+1, tm+1, tr, pos, new_val);
        ll x[4]={t[v*2].first,t[v*2].second,t[v*2+1].first,t[v*2+1].second};
        sort(x,x+4);
        t[v] = {x[2],x[3]};
    }
}

