    ll ans=0;
    build1(a, 1, 1, n);
    for(int i=0;i<n;i++)
    {
    	update1(1, 1, n, p[i], i);
    	pair<ll,ll> q = tma(1, 1, n, p[i]+1, n);
    	if(q.second==-C && q.first==-C)
    	{	
    		x1[i]=0;
    		x2[i]=i+1;
    	}
    	if(q.second!=-C && q.first==-C)
    	{
    		x1[i]=q.second+1;
    		x2[i]=i-q.second;
    	}
    	if(q.second!=-C && q.first!=-C)
