int main() {
	int N;
	ll ans = 0;
	cin >> N;
	rep(i, N) {
		cin >> P[i];
		Pp[i].first = P[i];
		Pp[i].second = i;
		A[i] = 0;
	}
	sort(Pp, Pp + N, less<pii>());
	rep(j, N) {
		int i = Pp[j].second;
		if (A[i])
			continue;
		int Ptmp = P[i];
		int L1 = -1, L2 = -1, R1 = -1, R2 = -1;
		int L = i - 1;
		int R = i + 1;
		while (1) {
			if (L < 0)
				break;
			if (P[L] > Ptmp)
				break;
			L--;
		}
		L1 = L;
		L--;
		L = max(-1, L);
		while (1) {
			if (L < 0)
				break;
			if (P[L] > Ptmp)
				break;
			L--;
		}
		L2 = L;
		while (1) {
			if (R > N - 1)
				break;
			if (P[R] > Ptmp)
				break;
			R++;
		}
		R1 = R;
		R++;
		R = min(N, R);
		while (1) {
