template <typename T>
std::vector<int> sort_indexes(const std::vector<T> &v) {
  std::vector<int> idx(v.size());
  std::iota(idx.begin(), idx.end(), 0);
  std::sort(idx.begin(), idx.end(), [&v](int i1, int i2) {return v[i1] > v[i2];});
  return idx;
}


signed main() {
	int n;
	std::cin >> n;
	std::vector<int> p(n);
	rep(i,n) std::cin >> p[i];
	auto idx = sort_indexes(p);
	std::set<int> set;
	int sum = 0;
	for(auto i:idx) {
		auto it = set.emplace(i).first;
		int a,b,c,d;
		if(it==set.begin()) {
			a=0;b=*it+1;
		} else {
			auto itb = std::prev(it);
			b = *it - *itb;
			if(itb == set.begin()) {
				a = *itb+1;
			} else {
				auto ita = std::prev(itb);
				a = *itb - *ita;
			}
		}
		auto itc = std::next(it);
		if(itc==set.end()) {
			d=0;c=n-*it;
		} else {
			auto itd = std::next(itc);
			c = *itc - *it;
			if(itd==set.end()) {
				d=n-*itc;
			} else {
				d=*itd-*itc;
			}
		}
		sum+=p[*it]*(a*c+b*d);
	}
	print(sum);
	return 0;
}

