#include<bits/stdc++.h>
using namespace std;
#define MAX (int)1e+5+1
typedef long long ll;

int N;
int P[MAX];
int first[2*MAX+1];
int second[2*MAX+1];

void init(int i, int l, int r) {
    if (l==r-1) {
        first[i] =  P[l];
        second[i] = 0;
    }
    else {
        int m = (l+r)/2;
        int cl = (i<<1)+1, cr = (i<<1)+2;
        init(cl, l, m);
        init(cr, m, r);
        first[i] = max(first[cl], first[cr]);
        second[i] = max(min(first[cl], first[cr]), max(second[cl], second[cr]));
    }
}

pair<int, int> search(int i, int l, int r, int l0, int r0) {
    if (r0 <= l || r <= l0) return make_pair(0, 0);
    else if (l0 <= l && r <= r0) return make_pair(first[i], second[i]);
    else {
        pair<int, int> ls, rs;
        ls = search((i<<1)+1, l, (l+r)/2, l0, r0);
        rs = search((i<<1)+2, (l+r)/2, r, l0, r0);
        int f = max(ls.first, rs.first);
        int s = max(min(ls.first, rs.first), max(ls.second, rs.second));
        return make_pair(f, s);
    }
}

void solve() {
    init(0, 1, N+1);
    ll ans = 0;
    for (int i=1; i<=N-1; i++) {
        for (int j=i+1; j<=N; j++) {
            ans += search(0, 1, N+1, i, j+1).second;
        }
    }

    cout << ans << endl;
}

int main() {
    cin >> N;
