using namespace std;

template<class T = int>
class BIT {
    private:
        T size;
        vector<T> data;
    public:
        BIT(T size) {
            this->size = size;
            this->data = vector<T>(size + 1, 0);
        };

        void add(T index, T value = 1) {
            while (index <= this->size) {
                this->data[index] += value;
                index += index & (-index);
            }
        };

        T sum(T index) {
            T ret = 0;
            while (index > 0) {
                ret += this->data[index];
                index -= index & (-index);
            }
            return ret;
        };

        T search(T value) {
            T i = 0, s = 0;
            T step = 1;
            while (step < this->size) step *= 2;

            while (step > 0) {
                if (i + step <= this->size && s + this->data[i + step] < value) {
                    i += step;
                    s += this->data[i];
                }
                step /= 2;
            }
            return i + 1;
        };
};

int main(void) {
    int N;
    cin >> N;

    vector<int> P(N, 0);
    for (int i = 0; i < N; i++) {
        cin >> P[i];
    }

    map<int, int> pToI;
    for (int i = 0; i < N; i++) {
        pToI[P[i]] = i + 1;
    }

    BIT<> tree(N);
    long ans = 0;

    for(int p = N; p > 0; p--) {
        int i = pToI[p];

        int left = tree.sum(i);
        int right = (N - p) - left;
        tree.add(i);

        int L1 = (left >= 2) ? tree.search(left - 1) : 0;
        int L2 = (left >= 1) ? tree.search(left) : 0;
        int R1 = (right >= 1) ? tree.search(left + 2) : N + 1;
        int R2 = (right >= 2) ? tree.search(left + 3) : N + 1;

        int cnt = 0;
        if (L2 != 0) cnt += (L2 - L1) * (R1 - i);
        if (R1 != 0) cnt += (R2 - R1) * (i - L2);

        ans += cnt * p;
    }

    cout << ans << endl;

    return 0;
}

