template<typename Monoid>
struct segtree {
    using T = typename Monoid::T;
    int n;
    vector<T> dat;

    segtree(int n_) {
        n = 1;
        while(n < n_) n <<= 1;
        dat.assign(n*2, Monoid::id());
    }
    void build(vector<T> v) {
        REP(i, v.size()) dat[i+n-1] = v[i];
        for(int i=n-1; i>0; --i) dat[i] = Monoid::op(dat[i*2+1], dat[i*2+2]);
    }

    T query(int a, int b) {
        T l = Monoid::id(), r = Monoid::id();
        for(a+=n, b+=n; a<b; a>>=1, b>>=1) {
            if(a&1) l = Monoid::op(l, dat[a++]);
            if(b&1) r = Monoid::op(dat[--b], r);
        }
        return Monoid::op(l, r);
    }
    void update(int i, T v) {
        i += n;
        dat[i] = v;
        while(i >>= 1) {
            dat[i] = Monoid::op(dat[i*2], dat[i*2+1]);
        }
    }

    friend ostream &operator <<(ostream& out,const segtree<Monoid>& seg){
        out << "---------------------" << endl;
        int cnt = 1;
        for(int i=1; i<=seg.n; i*=2) {
            REP(j, i) {
                out << seg.dat[cnt] << " ";
                cnt++;
            }
            out << endl;
        }
        out << "---------------------" << endl;
        return out;
    }
};

template<typename Tp>
struct max_monoid {
    using T = Tp;
    static constexpr Tp id() {
        return PII(-LLINF, -LLINF);
    }
    static Tp op(const Tp &a, const Tp &b) {
        ll ma = a.first, ma2 = a.second;
        if(b.first > ma) {
            ma2 = ma;
            ma = b.first;
        } else if(b.first > ma2) {
            ma2 = b.first;
        }
        if(b.second > ma) {
            ma2 = ma;
            ma = b.second;
        } else if(b.second > ma2) {
            ma2 = b.second;
        }
        return PII(ma, ma2);
    }
};

