/**
 *	セグメント木を構成する
 *	2methodの変更により調整
 */
template<class T>
class SegmentTree {
private:
	const T initialValue = T(-1, -1);
	const T ignoreValue = T(-1, -1);

	const ll m_size;
	vector<T> m_node;

	ll calcSize(ll n) {
		ll size = 1;
		while (size < n) {
			size *= 2;
		}
		return size;
	}

	/**
	 * 値の更新(更新:=, 加算:+=, etc...)
	 */
	void update(ll k, T x) {
		m_node[k] = x;
	}

	/**
	* 値の併合
	*/
	T merge(T xl, T xr) {
		if (xl.first > xr.first) {
			return {xl.first,std::max(xl.second,xr.first)};
		} else {
			return {xr.first,std::max(xr.second,xl.first)};
		}
	}
public:
	SegmentTree(ll n) :
		m_size(calcSize(n)),
		m_node(m_size * 2 - 1, initialValue) {}

	void add(ll itr, T val) {
		ll i = itr + m_size - 1;
		update(i, val);

		while (i > 0) {
			i = (i - 1) / 2;
			m_node[i] = merge(m_node[i * 2 + 1], m_node[i * 2 + 2]);
		}
		/**
		cout << "-- tree -- " << endl;
		REP(i, 2 * m_size - 1) {
			cout << m_node[i] << endl;
		}
		/*//**/
	}

	T query(ll a, ll b) { return query(a, b + 1, 0, 0, m_size); }
	T query(ll a, ll b, ll k, ll l, ll r) {
		if (r <= a || b <= l) { return ignoreValue; }
		if (a <= l && r <= b) { return m_node[k]; }
		return merge(
			query(a, b, 2 * k + 1, l, (l + r) / 2),
			query(a, b, 2 * k + 2, (l + r) / 2, r)
		);
	}
};

signed main() {
	ll n;
	cin >> n;
	VL v(n);
	cin >> v;

	auto tree = SegmentTree<PAIR>(n);
	REP(i, n) { tree.add(i, {v[i],-1}); }

	auto rlow = [&](ll from, ll val) {
		ll ok = n - from;
		ll ng = -1;
		while (ok - ng > 1) {
			ll mid = (ok + ng) / 2;
			bool isOk = tree.query(from, from + mid).second >= val;
			if (isOk) { ok = mid; } else { ng = mid; }
		}
		return from + ok;
	};
	auto llow = [&](ll from, ll val) {
		ll ok = from + 1;
		ll ng = -1;
		while (ok - ng > 1) {
			ll mid = (ok + ng) / 2;
			bool isOk = tree.query(from - mid, from).second >= val;
			if (isOk) { ok = mid; } else { ng = mid; }
		}
		return from - ok;
	};
	ll ans = 0;
	REP(i, n) {
		ll lit = llow(i, v[i]);
		ll rit = rlow(i, v[i]);

		if (rit < n) {
			ll rit2 = rlow(rit, v[i]);
			ll b = rit2 - rit;
			ll a = i - lit;
			//cout << i << " " << a << " " << b << " :__oox__oo" << endl;
			ans += b * a * v[i];
		}
		if (lit > -1) {
			ll lit2 = llow(lit, v[i]);
			ll a = lit - lit2;
			ll b = rit - i;
			ans += b * a * v[i];
			//cout << i << " " << a << " " << b << " :oo__xoo__" << endl;
		}
		//BR;
	}
	cout << ans << endl;
}

