    V<t2> pidxlist;
    rep (i, n) pidxlist.pb(t2(plist[i], i));
    sort_reverse(pidxlist);

    set<ll> idxs;
    idxs.insert(-1e18);
    idxs.insert(-1);
    idxs.insert(n);
    idxs.insert(1e18);

    ll ans = 0;

    for (auto pidx : pidxlist) {
        ll p = get<0>(pidx);
        ll idx = get<1>(pidx);

        auto iter_u1 = idxs.lower_bound(idx);
        auto iter_u2 = iter_u1;
        iter_u2++;
        ll cnt_u1 = *iter_u1 - idx;
        ll cnt_u2 = *iter_u2 - *iter_u1;

        auto iter_d1 = idxs.lower_bound(idx);
        iter_d1--;
        auto iter_d2 = iter_d1;
        iter_d2--;
        ll cnt_d1 = idx - *iter_d1;
        ll cnt_d2 = *iter_d1 - *iter_d2;

        if (cnt_d2 < 1e12) ans += p * cnt_u1 * cnt_d2;
        if (cnt_u2 < 1e12) ans += p * cnt_u2 * cnt_d1;

        idxs.insert(idx);
    }

