const LL infLL = 0x7fffffffffffffffLL;
const LL mod = 1e9 + 7;
const int maxN = 1e5 + 7;
const LL ONE = 1;
const LL evenBits = 0xaaaaaaaaaaaaaaaa;
const LL oddBits = 0x5555555555555555;

int N;
int P[maxN];     // P数组为1~N的一组排列 
int pos[maxN];     // pos[i]为i在P数组中的位置 
int leftFirstMaxPos[maxN];     // leftFirstMaxPos[i]为i位置的数左边第一个比i大的数的位置,没有则为0
int rightFirstMaxPos[maxN]; // rightFirstMaxPos[i]为i位置的数右边第一个比i大的数的位置,没有则为N+1 
LL ans = 0; 

int main(){
    //freopen("MyOutput.txt","w",stdout);
    //freopen("input.txt","r",stdin);
    //INIT();
    scanf("%d", &N);
    For(i, 1, N) {
        scanf("%d", &P[i]);
        pos[P[i]] = i; 
        // 后面是从1开始枚举,而1是最小的,所以1的左右最近大正好是相邻的两个数 
        leftFirstMaxPos[i] = i - 1;
        rightFirstMaxPos[i] = i + 1;
    }

    // 计算每个数i为第二大的时候对答案的贡献 
    For(i, 1, N) {
        int Lpos1 = leftFirstMaxPos[pos[i]];     // i左边第一个比他大的数的位置 
        int Lpos2 = leftFirstMaxPos[Lpos1];        // i左边第二个比他大的数的位置 
        int Rpos1 = rightFirstMaxPos[pos[i]];    // i右边第一个比他大的数的位置 
        int Rpos2 = rightFirstMaxPos[Rpos1];        // i右边第二个比他大的数的位置 

        if(Lpos1 != 0) ans += ONE * i * (Lpos1 - Lpos2) * (Rpos1 - pos[i]);
        if(Rpos1 != N + 1) ans += ONE * i * (pos[i] - Lpos1) * (Rpos2 - Rpos1);

        // 更新 
        /*
            例如这个片段:
                  1 2 3 4 5 6 7 
                P 6 3 1 2 5 4 7
                此时以i = 1为例
                本来leftFirstMaxPos[4] = 3, rightFirstMaxPos[2] = 3的
                计算完i = 1的贡献之后, leftFirstMaxPos[4] = 2, rightFirstMaxPos[2] = 4
                这一步更新相当于把1给砍掉了,剩下的数中2又是最小的数,于是2的左右最近大又正好是相邻的两个数 
                没错,非常像链表删除一个值的操作 
                leftFirstMaxPos就相当于静态链表的前驱数组
                rightFirstMaxPos就相当于静态链表的后继数组 
        */ 
        leftFirstMaxPos[Rpos1] = Lpos1;
        rightFirstMaxPos[Lpos1] = Rpos1;
    }

    printf("%lld", ans);
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
vector<int>BIT;
int sumUp(int a) {
  int ret = 0;
  while (a) {
    ret += BIT[a];
    a -= a & -a;
  }
  return ret;
}
void add(int n, int v, int N) {
  while (v <= N) {
    BIT[v] += n;
    v += v & -v;
  }
}
int main () {
  int N;
  cin >> N;
  BIT.assign(200002, 0);
  vector<int>P(N + 2);
  vector<int>F(N + 2);
  for (int i = 2; i <= N + 1; i ++) {
    cin >> P[i];
    F[P[i]] = i;
  }
  add(1, F[N], N + 2);
  add(1, 1, N + 2);
  add(1, N + 2, N + 2);
  int ans = 0;
  for (int i = N - 1; i >= 1; i --) {
    int mi = F[i];
    int ma = N + 2;
    int ke = sumUp(F[i]);
    while (ma != mi) {
      int mu = (ma + mi) / 2;
      if (sumUp(mu) < ke + 1) mi = mu + 1;
      else ma = mu;
    }
    R1 = mi;
    ma = N + 2;
    int R2 = N + 2;
    if (R1 != N + 2) {
      ke ++;
      while (ma != mi) {
        int mu = (ma + mi) / 2;
        if (sumUp(mu) < ke + 1) mi = mu + 1;
        else ma = mu;
      }
      R2 = mi;
    }
    mi = 0;
    ma = F[i];
    while (ma != mi) {
      int mu = (ma + mi) / 2;
      if (sumUp(mu) < ke) mi = mu + 1;
      else ma = mu;
    }
    L1 = ma;
    int L2 = 0;
    if (L1) {
      mi = 0;
      ke --;
      while (ma != mi) {
        int mu = (ma + mi) / 2;
        if (sumUp(mu) < ke) mi = mu + 1;
        else ma = mu;
      }
      L2 = mi;
    }
    int kj = F[i];
    ans += ((R1 - kj) * (L1 - L2) + (R2 - R1) * (kj - L1)) * i;
    add(1, kj, N + 2);
  }
  cout << ans << endl;
}

