#include <bits/stdc++.h>

using namespace std;

const int N = 1e5 + 7;

int stk[N], top(0);
int leftovers[N], ltop(0);

int p[N];
int unust[N], doist[N], unudr[N], doidr[N], aux[N];
int n;

int plimba(int val) {
    int st = 1, dr = ltop;
    while (st != dr) {
        int mij = ((st + dr)>>1);
        if (p[leftovers[mij + 1]] < val)
            dr = mij;
        else
            st = mij + 1;
    }
    if (p[leftovers[st]] >= val)
        return st;
    return 0;
}

void baga(int *first, int *second) {
    top = ltop = 0;
    for (int i = 1; i <= n; ++i) {
        int pt = top;
        while (top && p[stk[top]] < p[i])
            --top;
        for (int j = top + 1; j <= pt; ++j) {
            while (ltop && p[leftovers[ltop]] <= p[stk[j]])
                --ltop;
            leftovers[++ltop] = stk[j];
        }
        if (top) {
            first[i] = stk[top];
            if (top - 1)
                second[i] = stk[top - 1];
            if (ltop) {
                int x = plimba(p[i]);
                if (x) {
                    if (second[i])
                        second[i] = max(leftovers[x], second[i]);
                    else
                        second[i] = leftovers[x];
                }
            }
        }
        stk[++top] = i;
    }
}

int main()
{
    ios_base::sync_with_stdio(NULL);
    cin.tie(0);
    cout.tie(0);
    cin >> n;
    for (int i = 1; i <= n; ++i)
        cin >> p[i];

    baga(unust, doist);
    reverse(p + 1, p + n + 1);
    baga(unudr, doidr);
    reverse(p + 1, p + n + 1);
    for (int i = 1; i <= n; ++i) {
        unudr[i] = n + 1 - unudr[i];
        doidr[i] = n + 1 - doidr[i];
    }
    reverse(unudr + 1, unudr + n + 1);
    reverse(doidr + 1, doidr + n + 1);

    long long ans(0);
    for (int i = 1; i <= n; ++i) {
        ans += 1LL * (unust[i] - doist[i]) * (unudr[i] - i) * p[i];
        ans += 1LL * (doidr[i] - unudr[i]) * (i - unust[i]) * p[i];
    }

    cout << ans;
    return 0;
}

