typedef set<lld>::iterator sit;
#define rep(i,a,b) for(int i=a;i<b;i++)
set<lld> pos;
bool hasPrev(sit it){
  if(it==pos.begin())return false;
  return true;
}
bool hasNext(sit it){
  if(it==pos.end())return false;
  if(next(it)==pos.end())return false;
  return true;
}
int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);
  int n;
  cin>>n;
  int per[n];
  int inv[n];
  rep(i,0,n){
    cin>>per[i];
    per[i]--;
    inv[per[i]]=i;
  }
  lld ans=0;
  for(int i=n-1;i>-1;i--){
    sit it=pos.insert(inv[i]).first;
    lld A,B,C,D;
    if(!hasPrev(it)){
      A=0;
      B=inv[i]+1;
    }else{
      B=inv[i]-*prev(it);
      if(hasPrev(prev(it))){
	A=*prev(it)-*prev(prev(it));
      }else{
	A=*prev(it)+1;
      }
    }
    if(!hasNext(it)){//ut<<"N"<<endl;
      D=0;
      C=n-inv[i];
    }else{
      C=*next(it)-inv[i];
      if(hasNext(next(it))){
	D=*next(next(it))-*next(it);
      }else{
	D=n-*next(it);
      }
    }
    //ut<<A<<" "<<B<<" "<<C<<" "<<D<<endl;
    lld can=i+1;
    can*=B*D+C*A;
    ans+=can;
  }
  cout<<ans<<endl;
  return 0;
}

