    for (int i = 0; i < n; i++) {
        std::cin >> p[i];
        p[i]--;
        id[p[i]] = i;
    }

    std::set<int> s;

    long long ans = 0;
    for (int elem = n - 1; elem >= 0; elem--) {
        int idx = id[elem];

        s.insert(idx);

        auto center = s.find(idx);

        std::vector<int> l(2, -1);
        for (int i = 0; i < 2; i++) {
            if (center == s.begin()) {
                break;
            }

            center--;
            l[i] = *center;
        }

        center = s.find(idx);
        std::vector<int> r(2, n);
        for (int i = 0; i < 2; i++) {
            center++;
            if (center == s.end()) {
                break;
            }

            r[i] = *center;
        }

        std::vector<int> ls(2), rs(2);
        ls[0] = idx - l[0];
        ls[1] = l[0] - l[1];
        rs[0] = r[0] - idx;
        rs[1] = r[1] - r[0];

        long long c = (long long)(ls[0] * rs[1]) + (long long)(ls[1] * rs[0]);

        ans += c * (elem + 1);
    }

    std::cout << ans << std::endl;
}

