        int i_p = P2i[p];
        int i_ll, i_l, i_r, i_rr;

        auto it = s.insert(i_p).first;
        auto it_first = s.begin();
        auto it_last = s.end();
        it_last--;
        if (it != it_first)
        {
            auto it_l = it;
            it_l--;
            i_l = *it_l;
            if (it_l != it_first)
            {
                it_l--;
                i_ll = *it_l;
            }
            else
                i_ll = -1;
        }
        else
            i_l = i_ll = -1;

        if (it != it_last)
        {
            auto it_r = it;
