            l[j] = *litr;
        }
        for(int j = 0; j < 2; ++j) {
            ++ritr;
            if(ritr == st.end())
                break;
            r[j] = *ritr;
        }
        int sec = (l[0] - l[1]) * (r[0] - a[i]) + (r[1] - r[0]) * (a[i] - l[0]);
        ans += sec * (i + 1);
    }
