using namespace std;

typedef long long ll;
typedef long double ld;
typedef pair <int, int> pii;

pii merge (pii x, pii y) {
  int first_mx = max(x.first, y.first);
  int second_mx = max(x.second, y.second);
  if (first_mx == x.first) second_mx = max(second_mx, y.first);
  if (first_mx == y.first) second_mx = max(second_mx, x.first);
  return pii(first_mx, second_mx);
}

struct STree {
  int l, r;
  pii state;
  STree* left = 0;
  STree* right = 0;
  STree (int l, int r, const vector <int>& arr): l(l), r(r) {
    if (l == r) {
      state = pii(arr[l], -1);
      return;
    }
    int m = (l + r) >> 1;
    left = new STree(l, m, arr);
    right = new STree(m + 1, r, arr);
    state = merge(left -> state, right -> state);
  }
  pii getMax (const int L, const int R) {
    if (r < L or R < l) return pii(0, 0);
    if (L <= l and r <= R) return state;
    return merge(left -> getMax(L, R), right -> getMax(L, R));
  }
};

int main () {
  ios::sync_with_stdio(false); cin.tie(0);
  int n;
  cin >> n;
  vector <int> arr(n + 1);
  vector <int> pos(n + 1);
  for (int i = 1; i <= n; i++) {
    cin >> arr[i];
    pos[arr[i]] = i;
  }
  STree tree(1, n, arr);
  function <pii(int,int)> getRange = [&] (int num, int sec) -> pii {
    pii exp(num, sec);
    int l1 = 1, r1 = pos[num];
    while (l1 != r1) {
      int m = (l1 + r1) >> 1;
      pii cur = tree.getMax(m, pos[sec]);
      if (exp == cur) r1 = m;
      else l1 = m + 1;
    }
    int l2 = pos[num], r2 = n;
    while (l2 != r2) {
      int m = (l2 + r2 + 1) >> 1;
      pii cur = tree.getMax(pos[sec], m);
      if (exp == cur) l2 = m;
      else r2 = m - 1;
    }
    return pii(l1, l2);
  };
  function <pii(int)> getRange2 = [&] (int num) -> pii {
    int l1 = 1, r1 = pos[num];
    while (l1 != r1) {
      int m = (l1 + r1) >> 1;
      pii cur = tree.getMax(m, pos[num]);
      if (num == cur.first) r1 = m;
      else l1 = m + 1;
    }
    int l2 = pos[num], r2 = n;
    while (l2 != r2) {
      int m = (l2 + r2 + 1) >> 1;
      pii cur = tree.getMax(pos[num], m);
      if (num == cur.first) l2 = m;
      else r2 = m - 1;
    }
    return pii(l1, l2);
  };
  ll ans = 0;
  for (int sec = 1; sec < n; sec++) {
    pii ran = getRange2(sec);
    pii l = pii(-1, -1);
    pii r = pii(-1, -1);
    if (1 <= ran.first - 1) l = getRange(arr[ran.first - 1], sec);
    if (ran.second + 1 <= n) r = getRange(arr[ran.second + 1], sec);
    if (l.first != -1) {
      l.second = ran.first - 1;
      ll x = l.second - l.first + 1;
      ll y = ran.second - pos[sec] + 1;
      ans += x * y * sec;
    }
    if (r.first != -1) {
      r.first = ran.second + 1;
      ll x = r.second - r.first + 1;
      ll y = pos[sec] - ran.first + 1;
      ans += x * y * sec;
    }
  }
  cout << ans << '\n';
  return (0);
}

