class Solve {
public:
    void solve() {
        Int N;
        cin >> N;
        vector<Int> P(N);
        vector<Int> iP(N + 1);

        vector<Int> L1(N + 1);
        vector<Int> R1(N + 1);
        vector<Int> L2(N + 1);
        vector<Int> R2(N + 1);

        for (int i = 0; i < N; ++i) {
            cin >> P[i];
            iP[P[i]] = i;
        }

        SegTreeMax maxst(N + 1);
        SegTreeMin minst(N + 1);
        for (Int i = N; i >= 1; --i) {
            Int idx = iP[i];
            Int l1 = maxst.find(0, idx);
            Int r1 = minst.find(idx + 1, N + 1);
            Int l2 = -INFl;
            Int r2 = INFl;
            if (l1 != -INFl) {
                l2 = maxst.find(0, l1);
            }
            if (r1 != INFl) {
                r2 = minst.find(r1 + 1, N + 1);
            }

            L1[i] = l1;
            L2[i] = l2;
            R1[i] = r1;
            R2[i] = r2;

            maxst.update(idx, idx);
            minst.update(idx, idx);
        }

        Int ans = 0;
        for (int i = 1; i <= N; ++i) {
            if (L1[i] == -INFl) {
                L1[i] = -1;
            }
            if (L2[i] == -INFl) {
                L2[i] = -1;
            }
            if (R1[i] == INFl) {
                R1[i] = N;
            }
            if (R2[i] == INFl) {
                R2[i] = N;
            }

            Int t1 = (L1[i] - L2[i]) * (R1[i] - iP[i]);
            Int t2 = (R2[i] - R1[i]) * (iP[i] - L1[i]);
            Int add = (t1 + t2) * i;
            ans += add;
        }
        cout << ans << endl;


    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

