struct BIT {
    BIT(int n) : b(n + 1), n(n) {}
    void add(int i, int v) {
        for (int k = i + 1; k <= n; k += k & -k) b[k] += v;
    }
    int sum(int k) {
        int s = 0;
        for (; k > 0; k -= k & -k) s += b[k];
        return s;
    }
    vector<int> b;
    int n;
};

template <class F>
int lower_bound(int i0, int i1, F f) {
    while (i0 < i1) {
        int i = (i0 + i1) / 2;
        if (f(i)) i1 = i; else i0 = i + 1;
    }
    return i0;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<int> q(n);
    for (int i = 0; i < n; i++) {
        int p;
        cin >> p;
        p--;
        q[p] = i;
    }

    ll r = 0;
    BIT bt(n);
    for (int i = n - 1; i >= 0; i--) {
        int j = q[i];

        int jl = lower_bound(0, j, [&](int j1) {
            return bt.sum(j) - bt.sum(j1) <= 0;
        });
        jl--;
        int jl2 = lower_bound(0, j, [&](int j1) {
            return bt.sum(j) - bt.sum(j1) <= 1;
        });
        jl2--;
        int jr = lower_bound(j + 1, n, [&](int j1) {
            return bt.sum(j1 + 1) - bt.sum(j + 1) > 0;
        });
        int jr2 = lower_bound(j + 1, n, [&](int j1) {
            return bt.sum(j1 + 1) - bt.sum(j + 1) > 1;
        });
        if (jl >= 0 || jr < n) {
            if (jr < n) r += (ll)(i + 0) * (jl >= 0 ? j - jl : j + 1) * (jr2 - jr);
            //cout << i + 1 << ' ' << (n - jr) << endl;
            if (jl >= 0) r += (ll)(i + 0) * (jr < n ? jr - j : n - j) * (jl - jl2);
            //cout << i+1 << ' ' << r << endl;
        }
        bt.add(j, 1);
    }

    r += (ll)n * (n - 1) / 2;
    cout << r << endl;

    return 0;
}

