pair<int, vector<vector<int>>> func(int N, vector<int> P, int i) {

  if (i == 1) {

    int a = max(P[0], P[1]);
    int b = min(P[0], P[1]);

    pair<int, vector<vector<int>>> p(b, {{a, b}});

    return p;

  }

  int sum = func(N, P, i - 1).first;
  vector<vector<int>> old_vec = func(N, P, i - 1).second;

  vector<vector<int>> new_vec(i, vector<int>(2));

  for (int j = 0; j < i - 1; j++) {

    if (P[i] > old_vec[j][0]) {
      new_vec[j][0] = P[i];
      new_vec[j][1] = old_vec[j][0];
    }

    else if (old_vec[j][0] > P[i] && P[i] > old_vec[j][1]) {
      new_vec[j][0] = old_vec[j][0];
      new_vec[j][1] = P[i];
    }

    else {
      new_vec[j][0] = old_vec[j][0];
      new_vec[j][1] = old_vec[j][1];
    }

    sum += new_vec[j][1];

  }

  new_vec[i-1][0] = max(P[i], P[i-1]);
  new_vec[i-1][1] = min(P[i], P[i-1]);

  sum += new_vec[i-1][1];

  pair<int, vector<vector<int>>> q(sum, new_vec);

  return q;

}

