const int N = 100000 + 5;
inline int lowbit (int u) { return u & (-u); }
int n;
int info[N], p[N];
int tree[N];
long long ans;
inline void add (int u, int v) {
	while (u <= N - 5)
		tree[u] += v,
		u += lowbit (u);
}
inline int query (int u) {
	int res = 0;
	while (u)
		res += tree[u],
		u -= lowbit (u);
	return res;
}

inline int sh (int l, int r, int k) {
	int mid;
	while (l < r) {
		mid = (l + r) >> 1;
		int now = query (mid);
		if (now >= k) r = mid;
		else l = mid + 1;
	}
	return l;
}

inline void solve (int opt, int p) {
	if (opt == 1) {
		int lm, rm, nxt;
		int tmp = query (p);
		if (tmp == 1) { return ; }
		else if (tmp == 2) lm = 1, nxt = sh (1, p - 1, tmp - 1);
		else lm = sh (1, p - 1, tmp - 2) + 1, nxt = sh (1, p - 1, tmp - 1);
		int tmp2 = n - info[p] + 1;
		if (tmp2 - tmp == 0) rm = n;
		else rm = sh (p + 1, n, tmp + 1) - 1;
		ans += 1LL * info[p] * (rm - p + 1) * (nxt - lm + 1);
	}
	else {
		int lm, rm, nxt;
		int tmp = query (p), tmp2 = n - info[p] + 1;
		if (tmp2 - tmp == 0) { return ;}
		else if (tmp2 - tmp == 1) rm = n, nxt = sh (p + 1, n, tmp + 1);
		else rm = sh (p + 1, n, tmp + 2) - 1, nxt = sh (p + 1, n, tmp + 1);
		if (tmp == 1) lm = 1;
		else lm = sh (1, p - 1, tmp - 1) + 1;
		ans += 1LL * info[p] * (rm - nxt + 1) * (p - lm + 1);
	}
}

