	scanf ("%d", &n);
	for (int i = 1; i <= n; ++i)
		scanf ("%d", &info[i]), p[ info[i] ] = i;
	for (int i = n; i >= 1; --i) {
		add (p[i], 1);
		if (i == n) continue;
		solve (1, p[i]);
		solve (2, p[i]);
	}
	printf ("%lld\n", ans);
	return 0;
}

