		For ( i, 1, n ) a[i] = read();
		Max1pos = (a[1] > a[2])? 1: 2;
		Max2pos = (a[1] < a[2])? 1: 2;
		Max1 = max(a[1], a[2]), Max2 = min(a[1], a[2]);
		S += Max2, ++cc[Max2];
		For ( r, 3, n ) {
			if (a[r] > Max1) 
				Max4 = Max3, 
				Max3pos = Max2pos, Max3 = Max2,
				Max2pos = Max1pos, Max2 = Max1, 
				Max1 = a[Max1pos = r];
			else if (a[r] > Max2) 
				Max4 = Max3, 
				Max3pos = Max2pos, Max3 = Max2, 
				Max2 = a[Max2pos = r];
			else if (a[r] > Max3) Max4 = Max3, Max3 = a[Max3pos = r];
			else if (a[r] > Max4) Max4 = a[r];
			S += Max2, ++cc[Max2];
			if (Max3pos > Max2pos) CC[Max2] += Max3;
