		ll nowk = 0;
		For ( l, 2, n - 1 ) {
			ll x = -cc[a[l - 1]] * a[l - 1];
			nowk += x; Ans += CC[a[l - 1]] + S + nowk;
		} return wln(Ans), 0;
	}

