	set<int> se;
	se.insert(-1); se.insert(n);
	se.insert(p[0].second);
	long long ans = 0;
	for (int i = 1; i < n; ++i) {
		int now = p[i].second;
		auto r = lower_bound(se.begin(), se.end(), now);
		auto l = r; l--;
		long long lcnt1 = now - *l, rcnt1 = *r - now;
		long long lcnt2 = 0, rcnt2 = 0;
		if (l != se.begin()) l--, lcnt2 = now - *l - lcnt1;
		r++;
		if (r != se.end()) rcnt2 = *r - now - rcnt1;
		ans += p[i].first * (lcnt1 * rcnt2 + rcnt1 * lcnt2);
		se.insert(now);
	}
	cout << ans << endl;

	return 0;
}

