const int MAX_N = 1e5+12;
int N;
int P[MAX_N],a[MAX_N];

void solve()
{
	multiset<int> idx = {-1,-1, N, N};
	for(int i=0;i<N;++i){
		a[P[i]-1]=i;
	}
	long long ans = 0;
	for(int i=N-1;i>=0;--i){
		const int cur_p = a[i];
		auto it = idx.upper_bound(cur_p);
		int a = *prev(it, 2), b = *prev(it), x = *it, y = *next(it);
		// a .. b .. cur_p .. x .. y
		ans += (long long)(i+1)*(((long long)b-a)*(x-cur_p)+((long long)cur_p-b)*(y-x));
		idx.emplace(cur_p);
	}
	cout << ans;
}

