  REP(i,N){
    vll l_num(2, 0);
    vll r_num(2, 0);
    if(0<i){
      ll l_index1 = l_binary_search(que, 0, i-1, P[i]);
      l_num[0] = i-l_index1;
      if(l_index1>=0){
        que.update1(l_index1, 0);
        ll l_index2 = l_binary_search(que, 0, i-1, P[i]);
        l_num[1] = l_index1-l_index2;
        que.update1(l_index1, P[l_index1]);
      }
