void build(int v, int tl, int tr){
    if(tl == tr){
        t[v].push_back(a[tl]);
    }
    else {
        int mid = (tl + tr) / 2;
        build(v * 2, tl, mid);
        build(v * 2 + 1, mid + 1, tr);
        merge(t[v * 2].begin(), t[v * 2].end(), t[v * 2 + 1].begin(), t[v * 2 + 1].end(), back_inserter(t[v]));
    }
}


int get(int v, int tl, int tr, int l, int r, int w){
    if(l > tr || tl > r){
        return 0;
    }
    if(l <= tl && tr <= r){
        int h = upper_bound(t[v].begin(), t[v].end(), w) - t[v].begin();
        return t[v].size() - h;
    }
    int mid = (tl + tr) / 2;
    return get(v * 2, tl, mid, l, r, w) + get(v * 2 + 1, mid + 1, tr, l, r, w);
}

