            if(get(1, 1, n, mid, i,  a[i]) > 1){
                l = mid;
            }
            else {
                r = mid;
            }
        }
        while(get(1, 1, n, l, i, a[i]) < 2 && l > 1){
            l--;
        }
        if(get(1, 1, n, l, i, a[i]) == 2){
            l++;
        }
        l1 = l;

        l = i, r = n;
        while(r - l > 1){
            int mid = (l + r) / 2;
            if(get(1, 1, n, i, mid,  a[i]) > 0){
                r = mid;
            }
            else {
                l = mid;
