int main(void) {
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (int i = 0; i < n; i++)
        scanf("%d", &p[i]);

    int ans = 0;

    for (int i=0;i<n;i++){
        int L1=-1, L2=-1, R1=n, R2=n, k1, k2, idx;

        k1=0, idx = i;
        while(k1!=2 and idx>0){
            idx--;
            if(p[idx]>p[i]){
                if(k1==0)
                    L1 = idx;
                else if(k1==1)
                    L2 = idx;
                k1++;
            }
        }

        k2=0, idx = i;
        while(k2!=2 and idx<n-1){
            idx++;
            if(p[idx]>p[i]){
                if(k2==0)
                    R1 = idx;
                else if(k2==1)
                    R2 = idx;
                k2++;
            }
        }

        if(k1!=0 and k2!=0){
            ans += p[i]*((L1-L2)*(R1-i) + (i-L1)*(R2-R1));
        }else if(k1==0 and k2!=0){
            ans += p[i]*(i-L1)*(R2-R1);
        }else if(k2==0 and k1!=0){
            ans += p[i]*(L1-L2)*(R1-i);
        }
    }
    printf("%d", ans);
}

