int main() {
    long long n;
    std::cin >> n;
    std::vector<long long> p_to_i(n+1);
    for (long long i = 0; i < n; ++i) {
        long long p;
        std::cin >> p;
        p_to_i[p] = i;
    }
    std::set<long long> indices;
    for (long long i = 0; i < n; ++i) {
        indices.insert(i);
    }
    long long ans = 0;
    for (long long p = 1; p < n; ++p) {
        long long i = p_to_i[p];
        const auto it = indices.find(i);
        auto next = std::next(it);
        if (it == indices.begin()) {
            long long r1 = *next;
            long long r2 = (std::next(next) == indices.end()) ? n : *std::next(next);
            ans += p * (r2-r1) * (i+1);
        } else if (std::next(it) == indices.end()) {
            auto prev = std::prev(it);
            long long l1 = *prev;
            long long l2 = (prev == indices.begin()) ? -1 : *std::prev(prev);
            ans += p * (l1-l2) * (n-i);
        } else {
            auto next = std::next(it);
            auto prev = std::prev(it);
            auto l1 = *prev;
            auto r1 = *next;
            long long l2 = (prev == indices.begin()) ? -1 : *std::prev(prev);
            long long r2 = (std::next(next) == indices.end()) ? n : *std::next(next);
            ans += p * ((l1-l2) * (r1-i) + (i-l1) * (r2-r1));
        }

        indices.erase(i);
    }
    std::cout << ans << std::endl;
}

