long long get(int a,int b,int c,int dir)
{
	int mx=0,smx=0,pos=a-dir,pos2=a-dir;
	pre[a]=0;
	cum[a]=0;
	for (int i=pos;i!=c-dir;i-=dir)
	{
		pre[i]=max(pre[i+dir],p[i]);
		cum[i]=cum[i+dir]+pre[i];
	}
	long long ret=0;
	for (int i=a;i!=b+dir;i+=dir)
	{
		if (p[i]>mx)
		{
			smx=mx;
			mx=p[i];
		}
		else if (p[i]>smx)
		smx=p[i];
		while (pos!=c-dir && p[pos]<smx)
		pos-=dir;
		ret+=(abs(pos-a)-1LL)*smx;
		while (pos2!=c-dir && p[pos2]<mx)
		pos2-=dir;
		ret+=cum[pos2+dir]-cum[pos+dir];
	}
	return ret;
}
