int main(int argc, char *argv[]){
    int N;
    std::cin >> N;

    std::vector<long int> P(N);
    std::for_each(P.begin(),P.end(),[](auto &p){std::cin >> p;});

    std::vector<int> PIdx(N);
    std::iota(PIdx.begin(),PIdx.end(),0);

    std::sort(PIdx.begin(),PIdx.end(),
        [&P](const auto &lhs, const auto &rhs){
            return P[lhs] > P[rhs];
        });

    std::multiset<int>S;
    S.insert(-1);
    S.insert(-1);
    S.insert(N);
    S.insert(N);
    long int sum = 0;
    int l1,l2,r1,r2;
    for(const auto &idx : PIdx){
        auto iter = ++S.upper_bound(idx);
        r2 = *(iter--);
        r1 = *(iter--);
        l2 = *(iter--);
        l1 = *iter;
        sum += P[idx]*((l2-l1)*(r1-idx) + (idx-l2)*(r2-r1));
        S.insert(idx);
    }

    std::cout << sum << std::endl;
    return 0;
}

