using namespace std;
typedef long long ll;
#define MOD 1000000007

int main() {
    ll N;
    cin >> N;

    ll P[N];
    for(int i=0; i<N; i++) cin >> P[i];

    ll dp[N][N][2];

    for(int i=0; i<N-1; i++) {
        dp[i][i+1][0] = max(P[i], P[i+1]);
        dp[i][i+1][1] = min(P[i], P[i+1]);
        for(int j=i+2; j<N; j++) {
            if(P[j] > dp[i][j-1][0]) {
                dp[i][j][0] = P[j];
                dp[i][j][1] = dp[i][j-1][0];
            } else if(P[j] > dp[i][j-1][1]) {
                dp[i][j][0] = dp[i][j-1][0];
                dp[i][j][1] = P[j];
            } else {
                dp[i][j][0] = dp[i][j-1][0];
                dp[i][j][1] = dp[i][j-1][1];
            }
        }
    }

    ll ans = 0;
    for(int i=0; i<N-1; i++) {
        for(int j=i+1; j<N; j++) {
            ans += dp[i][j][1];
        }
    }

    cout << ans << endl;

    return 0;
}

