ui solve(void) {
  ui res = 0;
  multiset<ui> all;

  all.insert(0);
  all.insert(0);
  all.insert(N + 1);
  all.insert(N + 1);

  FORINV(i, 1, N + 1) {
    ui idx = Pi_inv[i] + 1;
    auto it = all.lower_bound(idx);
    ui xi = *prev(it, 1);
    ui wi = *prev(it, 2);

    ui yi = *it;
    ui zi = *next(it);

    auto Ci = (xi - wi) * (yi - idx) + (idx - xi) * (zi - yi);
    res += i * Ci;
    all.insert(idx);
  }

  return res;
}

