int st[MAXN][MAXLOGN];

void init(int* bg, int*en){
	int sz = int(en-bg);
	for(int i=0; i<sz; ++i) st[i][0] = bg[i];
	for(int j=1; 1 << j <= sz; ++j)
		for(int i=0; i + (1<<j) <= sz; ++i)
			st[i][j] = comp(st[i][j-1], st[i + (1<<(j-1))][j-1]);
}
int query(int l, int r){
	int k = (int) floor(log((double)r-l+1) / log(2.0));
	return comp(st[l][k], st[r-(1<<k)+1][k]);
}

int pos[MAXN];
int vs[MAXN];

int greaterLeft(int l, int r, int x){
	if(l>r) return -1;
	int y = query(l, r);
	if(y<=x) return -1;

	++r;
	while(r-l>1){
		int k = l + (r-l)/2;
		y = query(k, r-1);
		if(y>x) l = k;
		else r = k;
	}
	return vs[l];
}
int greaterRight(int l, int r, int x){
	if(l>r) return -1;
	int y = query(l, r);
	if(y<=x) return -1;

	--l;
	while(r-l>1){
		int k = l + (r-l)/2;
		y = query(k, r-1);
		if(y>x) r = k;
		else l = k;
	}
	return vs[r];
}
