using namespace std;

#define REP(i,n) for(int i = 0; i < (int)(n); i++)

int q[18][100010];

int maxv(int l, int r){
  int len = r - l + 1;
  int o = 31 - __builtin_clz(len);
  return max(q[o][l], q[o][r + 1 - (1 << o)]);
}

int searchl(int s, int e, int v){
  if(maxv(e, s) < v){
    return -1;
  }
  while(1){
    if(s == e){
      return s;
    }else if(s == e + 1){
      if(q[0][s] > v){
        return s;
      }else{
        return e;
      }
    }
    int h = (s + e) / 2;
    if(maxv(h, s) < v){
      s = h - 1;
    }else{
      e = h;
    }
  }
}

int searchr(int s, int e, int v){
  if(maxv(s, e) < v){
    return e + 1;
  }
  while(1){
    if(s == e){
      return s;
    }else if(s == e - 1){
      if(q[0][s] > v){
        return s;
      }else{
        return e;
      }
    }
    int h = (s + e) / 2;
    if(maxv(s, h) < v){
      s = h + 1;
    }else{
      e = h;
    }
  }
}

int main(){
  int n;
  cin >> n;
  REP(i, n){
    cin >> q[0][i];
  }
  REP(i, 18) if(i > 0){
    int d = 1 << i;
    REP(j, n - d / 2){
      q[i][j] = max(q[i - 1][j], q[i - 1][j + d / 2]);
    }
  }
  uint64_t r = 0;
  REP(i, n){
    int x = q[0][i];
    if(x == n) continue;
    int l1 = -1, l2 = -1, r1 = n, r2 = n;
    if(i > 0){
      l1 = searchl(i - 1, 0, x);
      l2 = l1 - 1;
      if(l1 > 0){
        l2 = searchl(l2, 0, x);
      }
    }
    if(i < n - 1){
      r1 = searchr(i + 1, n - 1, x);
      r2 = r1 + 1;
      if(r1 < n - 1){
        r2 = searchr(r2, n - 1, x);
      }
    }
    uint64_t v = x;
    if(l1 >= 0){
      r += v * (l1 - l2) * (r1 - i);
    }
    if(r1 < n){
      r += v * (i - l1) * (r2 - r1);
    }
  }
  cout << r << endl;
  return 0;
}

