vpii find2(int N, vi& p) {
    vpii res(N, mp(N, N));

    stack<pii> st; st.push({ INT_MAX, N });
    vvi when(N + 1);
    F0Rd (i, N) {
        while (st.top().f < p[i]) st.pop();
        res[i].f = st.top().s;
        when[res[i].f].pb(i);
        st.push({ p[i], i });
    }

    deque<pii> active; active.push_front({ INT_MAX, N });
    F0Rd (i, N) {
        trav (j, when[i]) {
            res[j].s = lb(all(active), mp(p[j], INT_MAX))->s;
        }
        while (active.front().f < p[i]) active.pop_front();
        active.push_front({ p[i], i });
    }

    return res;
}

