vector <int> mrg(vector <int> a, vector <int> b) {
  int pa = 0, sa = (int) a.size();
  int pb = 0, sb = (int) b.size();

  vector <int> c;
  for (int i = 0; i < sa + sb; i++) {
    int val = (1 << 30), id;
    if (pa < sa && a[pa] < val) {
      val = a[pa];
      id = 1;
    }
    if (pb < sb && b[pb] < val) {
      val = b[pb];
      id = 2;
    }
    if (id == 1) {
      c.push_back(a[pa++]);
    } else {
      c.push_back(b[pb++]);
    }
  }

  return c;
}

vector <int> kek[4 * N];

void build(int v, int tl, int tr) {
  if (tl == tr) {
    kek[v] = {a[tl]};
  } else {
    int tm = (tl + tr) / 2;
    build(2 * v, tl, tm);
    build(2 * v + 1, tm + 1, tr);
    kek[v] = mrg(kek[2 * v], kek[2 * v + 1]);
  }
}

int smaller(int v, int tl, int tr, int l, int r, int x) {
  if (tr < l || r < tl) {
    return 0;
  }
  if (l <= tl && tr <= r) {
    int lo = 0, hi = (int) kek[v].size() - 1, ans = 0;
    while (lo <= hi) {
      int mid = (lo + hi) / 2;
      if (kek[v][mid] <= x) {
        ans = mid + 1;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    return ans;
  }
  int tm = (tl + tr) / 2;
  return smaller(2 * v, tl, tm, l, r, x) + smaller(2 * v + 1, tm + 1, tr, l, r, x);
}

int cnt(int l, int r, int x) {
  return r - l + 1 - smaller(1, 1, n, l, r, x);
}

