    while (l <= r) {
      mid = (l + r) / 2;
      if (cnt(mid, i - 1, a[i]) <= 1) {
        r = mid - 1;
      } else {
        p2 = mid;
        l = mid + 1;
      }
    }


    /// CB 3
    l = i + 1, r = n;
    while (l <= r) {
      mid = (l + r) / 2;
      if (cnt(i + 1, mid, a[i]) <= 0) {
        l = mid + 1;
      } else {
        p3 = mid;
        r = mid - 1;
      }
    }

    /// CB 4
    l = i + 1, r = n;
    while (l <= r) {
      mid = (l + r) / 2;
      if (cnt(i + 1, mid, a[i]) <= 1) {
        l = mid + 1;
      } else {
        p4 = mid;
        r = mid - 1;
      }
    }

    ll cnt = (i - p1) * (ll) (p4 - p3) + (p3 - i) * (ll) (p1 - p2);
    ans += cnt * a[i];

  }
  cout << ans << "\n";

}

