    n = read();
    for(int i = 1; i <= n; i++) a[i] = read();
    for(int i = 1; i <= n; i++)
    {
        while(!Q.empty() && Q.top() < a[i])
            Q.pop(),F.pop();
            if(!Q.empty()) lx[i] = F.top();
            Q.push(a[i]); F.push(i);
    }
    while(!Q.empty()) Q.pop(), F.pop();
    for(int i = n; i >= 1; i--)
    {
        while(!Q.empty() && Q.top() < a[i])
            Q.pop(),F.pop();
            if(!Q.empty()) rx[i] = F.top();
            else rx[i] = n + 1;
            Q.push(a[i]); F.push(i);
    }
    t[0] = build(1, n);
    for(int i = 1; i <= n; i++)
    {
     t[i] = update( t[i - 1], 1, n, a[i]);
    }
    for(int i = 1; i <= n; i++)
    {
                p = rx[i]; ansx = sumx = 0;
                int l = rx[i] + 1, r = n ;
                while(l <= r){
                    int mid = l + r >> 1;
                    ans = query(t[mid], t[p], 1, n, a[i], n);
                    if(ans) { ansx++; r = mid - 1; sumx = mid;}
                    else l = mid + 1;
                }
                if(ansx == 0) sumx = n + 1;
                ry[i] = sumx;
                ansx = sumx = 0; p = lx[i] - 1;
                l = 1, r = lx[i] - 1;
                while(l <= r){
                    int mid = l + r >> 1;
