int Max(int i, int j){
    return max(p[i][f[j -  i]], p[j - mu(f[j - i]) + 1][f[j - i]]);
}

int tkr(int l, int r, int k){
    int i = l;
    while (l < r){
        int mid = (l + r) / 2;
        if (Max(i, mid) > k) r = mid;
        else l = mid + 1;
    }
    return r;
}

int tkl(int l, int r, int k){
    int j = r;
    while (l < r){
        int mid = (l + r + 1) / 2;
        if (Max(mid, j) >= k) l = mid;
        else r = mid - 1;
    }
    return l;
}
