int n;
int func(int first, int second, int idx) {
  if (idx >= n) {
    return 0;
  }

  if (first <= P[idx]) {
    second = first;
    first = P[idx];
  } else if (second < P[idx]) {
    second = P[idx];
  }
  int ans = second;
  II fs = II(first, second);
  if (memo[idx].find(fs) != memo[idx].end()) {
    ans += memo[idx][fs];
  } else {
    int res = func(first, second, idx + 1);
    ans += res;
    memo[idx][fs] = res;
  }
  return ans;
}

