	};

	auto myMax = [&](int a, int b) -> int {
		return max(a, b);
	};

	auto chg = [&](int a, int b) -> int {
		return b;
	};

	SegmentTree<int, int> lseg(N+2, myMax, chg, chg, -LL_HALFMAX, -LL_HALFMAX);
	SegmentTree<int, int> rseg(N + 2, myMin, chg, chg, LL_HALFMAX, LL_HALFMAX);

	rep(i, N + 2) {
		rseg.update(i, N);
		lseg.update(i, -1);
	}

	rep(i, N) {
		rseg.update(P[i], i);
	}

	int ans = 0;

	// 各Piの登場回数をもとめる
	rep(i, N) {
		int Pi = P[i];
		//lseg.debug_print(N+1);
		int l = lseg.query(Pi + 1, N + 1);
		int r = rseg.query(Pi + 1, N + 1);

		//rseg.debug_print(4);

		int cnt = 0;

		//自分より大きい l が存在してたら[i, r)がオッケー
		if (l != -1 && l != -LL_HALFMAX) {
			// l をけす
			lseg.update(P[l], -1);
			int nl = lseg.query(Pi + 1, N + 1);
			lseg.update(P[l], l);
			//nl = nl == -LL_HALFMAX ? -1 : nl;
			int cr = r == LL_HALFMAX ? N : r;

			int addl = l - nl;
			int addr = cr - i;

			cnt += (addl*addr);
		}
		if (r != N && r != LL_HALFMAX) {
			int add;

			// rを消す
			//rseg.debug_print(4);
			rseg.update(P[r], N);
			//rseg.debug_print(4);
			int nr = rseg.query(Pi + 1, N + 1);
			//nr = nr == LL_HALFMAX ? N : nr;
			rseg.update(P[r], r);
			int cl = l == -LL_HALFMAX ? -1 : l;

			// (l, i], [r, nr)
			int addl = i - cl;
			int addr = nr - r;

			cnt += (addl*addr);
		}

		// lseg には入れる、rseg からは出す
		lseg.update(P[i], i);
		rseg.update(P[i], N);

		ans += Pi * cnt;
	}

	cout << ans << "\n";

	return 0;
}

