	}

	rep(i, 2) {
		L[i][0] = 0;
		R[i][N + 1] = (ll)N + 1;
	}

	repc(i, 1, N) {
		while (!pq.empty()) {
			pli item = pq.top();
			ll v = item.first;
			int id = item.second;

			if (v >= P[i]) break;
			pq.pop();

			if (R[0][id] == -1) {
				R[0][id] = i;
				q.push(item);
			}
			else R[1][id] = i;
		}
		pq.push(p(P[i], i));
		while (!q.empty()) {
			pq.push(q.front());
			q.pop();
		}
	}

	while (!pq.empty()) {
		int id = pq.top().second; pq.pop();
		rep(i, 2) if (R[i][id] == -1) R[i][id] = (ll)N + 1;
	}

	rrepc(i, N, 1) {
		while (!pq.empty()) {
			pli item = pq.top();
			ll v = item.first;
			int id = item.second;

			if (v >= P[i]) break;
			pq.pop();

			if (L[0][id] == -1) {
				L[0][id] = i;
				q.push(item);
			}
			else L[1][id] = i;
		}
		pq.push(p(P[i], i));
		while (!q.empty()) {
			pq.push(q.front());
			q.pop();
		}
	}

	while (!pq.empty()) {
		int id = pq.top().second; pq.pop();
		rep(i, 2) if (L[i][id] == -1) L[i][id] = 0;
	}

	repc(i, 1, N) {
		ll Lnum = (L[0][i] - L[1][i]) * (R[0][i] - i);
		ll Rnum = (i - L[0][i]) * (R[1][i] - R[0][i]);
		ans += P[i] * (Lnum + Rnum);
	}

	cout << ans << endl;

	return 0;
}

