void build(int node, int b, int e) { 
    if(b == e) {tree[node].push_back(a[b]);return;};
    int mid=(b+e)>>1, lft=node<<1, rgt=lft|1;
    build(lft, b, mid);build(rgt, mid+1, e);
    merge(all(tree[lft]), all(tree[rgt]), back_inserter(tree[node])); 
}
int query(int node, int b, int e, int l, int r, int k, bool lf_rg){ //how many numbers are less than k in the range [l, r]
    if(r<b || e<l) {
        return -1;
    }
    if(l<=b && e<=r){
        int ret = -1;
        //if(lf_rg==0) ret = e+1;
        int lo = 0, hi = tree[node].size()-1;
        while(lo<=hi){
            int m = (lo+hi)>>1;
            if(tree[node][m]>k){
                ret = m+b;
                if(lf_rg==0)
                    hi = m-1;
                else lo = m+1;
            }
            else lo = m+1;
        }
        return ret;
    }
    int mid=(b+e)>>1, lft=node<<1, rgt=lft|1;
    int x = query(lft, b, mid, l, r, k, lf_rg);
    int y = query(rgt, mid+1, e, l, r, k, lf_rg);
    if(x==-1) return y;
    if(y==-1) return x;
    if(lf_rg==0) return min(x,y);
    return max(x,y);
}
