	cin >> N;
	cinv(P, N);

	lls loc(N+1);
	for (ll lc = 0; lc < N; lc++) {
		ll number = P[lc];
		loc[number] = lc;
	}

	lls locB;
	locB.push_back(loc[N]);

	ll A, B, C, D, E,sum=0;
	for (int i = N - 1; i >= 1; i--) {

		//数字iの場所lcが、locBに入る場所idxを得る
		ll lc = loc[i];
		C = lc;
		auto idxit = std::lower_bound(locB.begin(), locB.end(), lc);
		ll idx = idxit - locB.begin();

		//右側に大きいものがある場合を計算
		if (idx < locB.size()) {
			D = locB[idx];
			if (idx + 1 >= locB.size()) E = N;
			else                        E = locB[idx + 1];
			if (idx - 1 < 0) B = -1;
			else             B = locB[idx - 1];

			sum += (C - B) * (E - D) * i;
		}
		//左側に大きいものがある場合を計算
		if (idx - 1 >= 0) {
			B = locB[idx - 1];
			if (idx < locB.size()) D = locB[idx];
			else                   D = N;

			if (idx - 2 < 0) A = -1;
			else             A = locB[idx - 2];

			sum += (B - A) * (D - C) * i;
		}
		//locBの更新
		locB.insert(idxit, C);
	}

	cout << sum << '\n';

	return 0;
}

