int main(){
  long long int N, tmp;
  scanf("%lld", &N);

  std::vector<long long int> P, P_index(N);

  for(long long int i = 0; i < N; i++){
    scanf("%lld", &tmp);
    P.push_back(tmp-1);
    P_index[tmp-1] = i;
  }

  // prepare BIT
  long long int N_MAX = 1<<16;
  std::vector<long long int> BIT;
  for(long long int i = 0; i < N_MAX; i++){
    BIT.push_back(0);
  }

  // solve problem
  long long int ans = 0;
  long long int L1, L2, R1, R2, n, right, left, mid, tmp1, tmp2;
  for(long long int i = N-1; i >= 0; i--){
    //std::cerr << "i = " << i << std::endl;
    //std::cerr << "index = " << P_index[i] << std::endl;
    // update BIT
    n = P_index[i];
    add_num(BIT, N_MAX, n, 1);
    // calculate L1, L2, R1, R2
    tmp1 = cumulative_sum(BIT, n);
    // calculate L1
    if(tmp1 == 1){
      L1 = -1;
    }
    else{
      left = -1;
      right = n-1;
      while(right-left>1){
        mid = (left+right)/2;
        if(cumulative_sum(BIT, mid) == tmp1-1) right = mid;
        else left = mid;
      }
      L1 = right;
    }
    // calculate L2
    if(tmp1 <= 2){
      L2 = -1;
    }
    else{
      left = -1;
      right = L1-1;
      while(right-left>1){
        mid = (left+right)/2;
        if(cumulative_sum(BIT, mid) == tmp1-2) right = mid;
        else left = mid;
      }
      L2 = right;
    }
    // calculate R1
    if(tmp1 == N-i){
      R1 = N;
    }
    else{
      left = n;
      right = N-1;
      while(right-left>1){
        mid = (left+right)/2;
        if(cumulative_sum(BIT, mid) == tmp1)left = mid;
        else right = mid;
      }
      R1 = right;
    }
    // calculate R2
    if(tmp1 >= N-i-1){
      R2 = N;
    }
    else{
      left = R1;
      right = N-1;
      while(right-left>1){
        mid = (left+right)/2;
        if(cumulative_sum(BIT, mid) == tmp1+1) left = mid;
        else right = mid;
      }
      R2 = right;
    }

    // update answer
    //std::cerr << "L1:" << L1 << " L2:" << L2 << " R1:" << R1 << " R2:" << R2 << std::endl;
    ans += ((R2-R1)*(n-L1) + (L1-L2)*(R1-n)) * (i+1);
  }


  std::cerr << "Answer: " << std::endl;
  std::cout << ans << std::endl;
}


int init_BIT(std::vector<long long int> &BIT, long long int N_MAX){
  for(int i = 0; i < N_MAX; i++){
    BIT[i] = 0;
  }

  return 0;
}

int add_num(std::vector<long long int> &BIT, long long int N_MAX, long long int index, long long int d){
  index ++;
  while(index < N_MAX){
    BIT[index-1] += d;
    index += (index & -index);
  }

  return 0;
}

long long int cumulative_sum(std::vector<long long int> &BIT, long long int r){
  // sum of no elements
  if(r == -1){
    return 0;
  }

  r++;
  long long int sum = 0;
  while(r > 0){
    sum += BIT[r-1];
    r -= (r & -r);
  }

  return sum;
}

