	{
		cin >> p[i];
		p[i]--;
		inv[p[i]] = i;
	}


	set<int> s;

	lng res = 0;

	for (int i = n - 1; i >= 0; i--)
	{
		int idx = inv[i];
		lng l1 = -1;
		lng l2 = -1;
		lng r1 = -1;
		lng r2 = -1;

		auto it = s.lower_bound(idx);
		if (it != s.end())
		{
			r1 = *it;
			it++;
			if (it != s.end())
			{
				r2 = *it;
			}
			it--;
		}

		if (it != s.begin())
		{
			it--;
			l2 = *it;
			if (it != s.begin())
			{
				it--;
				l1 = *it;
			}
		}

		if (l2!=-1)
		{
			res += (i+1) * (l2-l1)*( (r1==-1?n:r1)-idx );
		}

		if (r1!=-1)
		{
			res += (i+1) * (idx-l2)*((r2==-1?n:r2)-r1);
		}

