void solve() {
	int n; cin >> n;
	vector<int> p(n);
	rep(i, n) {
		cin >> p[i];
	}
	vector<P> v;
	rep(i, n) {
		v.push_back({ p[i],i });
	}
	sort(v.begin(), v.end(), greater<P>());
	set<int> st;
	ll ans = 0;
	rep(i, n) {
		int loc = v[i].second;
		st.insert(loc);
		auto itr = st.find(loc);
		ll l1, l2, r1, r2;
		if (itr == st.begin()) {
			l1 = loc + 1; l2 = 0;
		}
		else {
			itr--;
			int z = *itr;
			l1 = loc - z;
			if (itr == st.begin()) {
				l2 = z+1;
			}
			else {
				itr--;
				int zz = *itr;
				l2 = z - zz;
				itr++;
			}
			itr++;
		}
		if (itr == --st.end()) {
			r1 = n - loc; r2 = 0;
		}
		else {
			itr++;
			int z = *itr;
			r1 = z - loc;
			if (itr == --st.end()) {
				r2 = n - z;
			}
			else {
				itr++;
				int zz = *itr;
				r2 = zz - z;
			}
		}
		ll num = r2 * l1 + r1 * l2;
		ans += num * v[i].first;
	}
	cout << ans << endl;
}

