int find_pre(SegmentTree& T, int L, int R, int v) {
    int l = L;
    int r = R;
    int s = 0;
    while (l <= r) {
        int m = (r - l) / 2 + l;
        res = 0;
        T.queryMax(1, 1, m);
        if (res > v) {
            s = m;
            l = m + 1;
        } else {
            r = m - 1;
        }
    }
    return s;
}

int find_suf(SegmentTree& T, int L, int R, int v) {
    int l = L;
    int r = R;
    int s = N + 1;
    while (l <= r) {
        int m = (r - l) / 2 + l;
        res = 0;
        T.queryMax(1, 1, m);
        if (res > v) {
            s = m;
            r = m - 1;
        } else {
            l = m + 1;
        }
    }
    return s;
}

