    for (int i = 1; i <= n; i++) {
        int tmp;
        cin >> tmp;
        pos[tmp] = i;
    }

    BinaryIndexedTree<int> bit(n + 1);
    ll ret = 0;
    for (int i = n; i >= 1; i--) {
        int nowpos = pos[i];
        ll s1 = bit.search_small(nowpos);
        ll s2 = bit.search_small(s1);
        ll b1 = bit.search_big(nowpos);
        ll b2 = bit.search_big(b1);

        ll cases = 0;
        if (s1 != -1)cases += (s1 - s2) * (b1 - nowpos);
        if (b1 != n + 1)cases += (nowpos - (s1 + 1)) * (b2 - b1);
        ret += i * cases;
        bit.add(nowpos, 1);
    }

    cout << ret << endl;
    return 0;
}

