}t[N*40];
int newnode()
{
    tot++;t[tot]=node();return tot;
}
void build(int l,int r,int &now)
{
    if(!now) now=newnode();
    if(l==r) return;
    int m=l+r>>1;
    build(l,m,t[now].l);build(m+1,r,t[now].r);
}
void update(int l,int r,int x,int &now,int pre)
{
    if(!now) now=newnode(),t[now].sum=t[pre].sum;
    t[now].sum++;
    if(l==r) return;
    int m=l+r>>1;
    if(x<=m) update(l,m,x,t[now].l,t[pre].l),t[now].r=t[pre].r;
    else update(m+1,r,x,t[now].r,t[pre].r),t[now].l=t[pre].l;
}
int query(int l,int r,int x,int now,int pre)
{
    if(l>x) return t[now].sum-t[pre].sum;
    if(r<=x) return 0;
    int m=l+r>>1;
    return query(l,m,x,t[now].l,t[pre].l)+query(m+1,r,x,t[now].r,t[pre].r);
}
int query(int l,int r,int x)
{
    return query(1,n,x,rt[r],rt[l-1]);
}
void solve1(int x)
{
    int l=1,r=x,ans;
    while(l<=r)
    {
        int m=l+r>>1;
        if(query(m,x,a[x])==0) ans=m,r=m-1;
        else l=m+1;
    }
    L[x][0]=x-ans+1;
}
void solve2(int x)
{
    int l=x,r=n,ans;
    while(l<=r)
    {
        int m=l+r>>1;
        if(query(x,m,a[x])==0) ans=m,l=m+1;
        else r=m-1;
    }
    R[x][0]=ans-x+1;
}
void solve3(int x)
{
    int l=1,r=x-L[x][0],ans=r;
    if(r<l) return;
    while(l<=r)
    {
        int m=l+r>>1;
        if(query(m,x,a[x])==1) ans=m,r=m-1;
        else l=m+1;
    }
    L[x][1]=x-L[x][0]-ans+1;
}
void solve4(int x)
{
    int l=x+R[x][0],r=n,ans=l;
    if(r<l) return;
    while(l<=r)
    {
        int m=l+r>>1;
        if(query(x,m,a[x])==1) ans=m,l=m+1;
        else r=m-1;
    }
    R[x][1]=ans-x-R[x][0]+1;
}
