    {
        solve1(i);
        solve2(i);
        solve3(i);
        solve4(i);
    }
    long long ans=0;
    for(int i=1;i<=n;i++)
        ans+=(ll)L[i][0]*R[i][1]*a[i]+(ll)R[i][0]*L[i][1]*a[i];
    printf("%lld\n",ans);
}

