ll compute(int ind, set<int> &st){
	auto rit = st.upper_bound(ind);
	auto lit = st.upper_bound(ind); lit--;
	int r1 = *rit; rit++;
	int l1 = *lit;
	if(rit == st.end()){
		lit--; int l2 = *lit;
		return (r1 - ind)*1LL*(l1 - l2);
	}
	if(lit == st.begin()){
		int r2 = *rit;
		return (ind - l1)*1LL*(r2 - r1);
	}
	int r2 = *rit;
	lit--; int l2 = *lit;
	return (r1 - ind)*1LL*(l1 - l2) + (ind - l1)*1LL*(r2 - r1);
}

