            }
            else{
                pos=query(1,n,1,l,mid);
                if(a[pos]>a[i]){
                    pre1=pos;
                    l=pos+1;
                }
                else{
                    break;
                }

            }
        }
        l=1,r=pre1-1,pre2=0;
        while(l<=r){
            if(l==r){
                int pos=query(1,n,1,l,l);
                if(a[pos]>a[i]){
                    pre2=pos;
                }
                break;
            }
            int mid=(l+r)/2;
            int pos=query(1,n,1,mid+1,r);
            if(a[pos]>a[i]){
                pre2=pos;
                l=pos+1;
            }
            else{
                pos=query(1,n,1,l,mid);
                if(a[pos]>a[i]){
                    pre2=pos;
                    l=pos+1;
                }
                else{
                    break;
                }

            }
        }
        l=i+1,r=n,next1=n+1;
        while(l<=r){
            if(l==r){
                int pos=query(1,n,1,l,l);
                if(a[pos]>a[i]){
                    next1=pos;
                }
                break;
            }
            int mid=(l+r)/2;
            int pos=query(1,n,1,l,mid);
            if(a[pos]>a[i]){
                next1=pos;
                r=pos-1;
            }
            else{
                pos=query(1,n,1,mid+1,r);
                if(a[pos]>a[i]){
                    next1=pos;
                    r=pos-1;
                }
                else{
                    break;
                }

            }
        }
        l=next1+1,r=n,next2=n+1;
        while(l<=r){
            if(l==r){
                int pos=query(1,n,1,l,l);
                if(a[pos]>a[i]){
                    next2=pos;
                }
                break;
            }
            int mid=(l+r)/2;
            int pos=query(1,n,1,l,mid);
            if(a[pos]>a[i]){
                next2=pos;
                r=pos-1;
            }
            else{
                pos=query(1,n,1,mid+1,r);
                if(a[pos]>a[i]){
                    next2=pos;
                    r=pos-1;
                }
                else{
                    break;
                }

            }
        }
        long long cnt=0;
        cnt+=(long long)((pre1-pre2)*(next1-i));
        cnt+=(long long)((next2-next1)*(i-pre1));
        ans+=(long long)(cnt*a[i]);
       // cout<<pre1<<" "<<pre2<<" "<<next1<<" "<<next2<<endl;
    }
    cout<<ans<<endl;
}

