vector<bool> visit;

int dfs(int id, const vector<vector<int>>& m) {
	if (distToLast[id] >= 0) return distToLast[id];

	if (visit[id] > 0) return INF;
	visit[id] = true;
	int dist = 0;
	for (auto e : m[id]) {
		dist = max(dist, dfs(e, m));
	}
	visit[id] = false;
	distToLast[id] = min(INF, dist+1);
	return distToLast[id];
}

