struct top2_t {
  vector<int> v;
  top2_t& operator+=(const top2_t& rhs) {
    v.insert(v.end(), rhs.v.begin(), rhs.v.end());
    sort(v.rbegin(), v.rend());
    if (v.size() > 2) v.resize(2);
    return *this;
  }
};

struct ans_t {
  ll less;
  ll over;
};

template <class T>
struct fenwick_tree {
  vector<T> x;
  fenwick_tree(int n)
      : x(n + 1) {
  }
  void add(int k, T a) {
    for (++k; k < x.size(); k += k & -k) x[k] += a;
  }
  T sum(int k) {
    T s;
    for (; k > 0; k &= k - 1) s += x[k];
    return s;
  }
};

vector<ans_t> solve(const vector<int>& P) {
  int N = P.size();
  fenwick_tree<top2_t> bit(N + 1);
  bit.add(0, {{-1, -1}});
  vector<ans_t> res(N);
  for (int i = 0; i < N; i++) {
    auto x = bit.sum(P[i]);
    auto v = x.v;
    assert(v.size() >= 2);
    res[i] = {i - v[0], v[0] - v[1]};
    bit.add(P[i], {{i}});
  }
  return res;
}

