    for (int& x : P) cin >> x;
    for (int& x : P) x = N + 1 - x;
    auto ans_f = solve(P);
    reverse(P.begin(), P.end());
    auto ans_b = solve(P);
    reverse(ans_b.begin(), ans_b.end());
    reverse(P.begin(), P.end());
    ll res = 0;
    for (int i = 0; i < N; i++) {
      auto f = ans_f[i], b = ans_b[i];
      res += (f.over * b.less + f.less * b.over) * (N + 1 - P[i]);
    }
    cout << res << endl;
  }
  return 0;
}

