int main() {
	int n;
	scanf("%d", &n);
	REP(i,n) scanf("%d", &A[i]);
	REP(i,n) idx[A[i]]=i+1;

	set<int> s;
	s.insert(0);
	s.insert(n+1);
	for(int x=n; x>0; x--) { // permutation [1..n]
		int i=idx[x];
		LL c=0;
		{ // calculate ci
			if(s.size()==0) continue;
			int l1,l2,r1,r2; // l2 < l1 < i < r1 < r2
			auto it=s.upper_bound(i);
