const int maxn = 2e5+10;

struct segtree {
    int tree[maxn];

    void build(int at, int L, int R) {
        if(L == R) return void(tree[at] = 0);
        int mid = L + R >> 1;
        build(at<<1, L, mid); build(at<<1|1, mid+1, R);
        tree[at] = tree[at<<1] + tree[at<<1|1];
    }

    void add(int at, int L, int R, int idx) {
        if(L == R) {tree[at]++; return;}
        int mid = L + R >> 1;
        if(idx <= mid) add(at<<1, L, mid, idx);
        else add(at<<1|1, mid+1, R, idx);
        tree[at] = tree[at<<1] + tree[at<<1|1];
    }

    int query(int at, int L, int R, int l, int r) {
        if(L >= l && R <= r) return tree[at];
        if(L > r || R < l) return 0;
        int mid = L + R >> 1;
        return query(at<<1, L, mid, l, r) + query(at<<1|1, mid+1, R, l, r);
    }
} s;

ll a[maxn], pos[maxn];

int s1(int i, int n) {
    int lo = 1, hi = i;

    while(lo <= hi) {
        int mid = lo + hi >> 1;
        int k = s.query(1, 1, n, mid, i);

        if(k >= 1) lo = mid+1;
        else hi = mid-1;
    } return hi;
}

int s2(int i, int n) {
    int lo = 1, hi = i;

    while(lo <= hi) {
        int mid = lo + hi >> 1;
        int k = s.query(1, 1, n, mid, i);

        if(k > 1) lo = mid+1;
        else hi = mid-1;
    } return hi;
}

int s3(int i, int n) {
    int lo = i, hi = n;

    while(lo <= hi) {
        int mid = lo + hi >> 1;
        int k = s.query(1, 1, n, i, mid);

        if(k >= 1) hi = mid-1;
        else lo = mid+1;
    } return lo;
}

int s4(int i, int n) {
    int lo = i, hi = n;

    while(lo <= hi) {
        int mid = lo + hi >> 1;
        int k = s.query(1, 1, n, i, mid);

        if(k > 1) hi = mid-1;
        else lo = mid+1;
