//とりあえず1-indexedでつくったBIT
template <class T>
class BinaryIndexedTree {
 private:
  T n;
  std::vector<T> bit;

 public:
  BinaryIndexedTree(T i) : n(i), bit(i + 1, 0){};

  // a番目にwを加算
  void add(T a, T w) {
    for (T x = a; x <= n; x += (x & -x)) {
      bit[x] += w;
    }
  }

  //[1,a]の和
  T sum(T a) {
    T ret = 0;
    for (T x = a; x > 0; x -= (x & -x)) {
      ret += bit[x];
    }
    return ret;
  }

  //各項がすべて非負のものに対して、sum[1,a]>=keyを満たす最小のaを返す
  //存在しないなら-1返す
  T lower_bound(T key) {
    T len = 1, temp = n, now = 0, value = 0, flag;
    while (temp / 2 != 0) {
      len *= 2;
      temp /= 2;
    }

    while (len > 0) {
      while (now + len > n) len /= 2;

      if (value + bit[now + len] >= key) {
        len /= 2;
      } else {
        now += len;
        value += bit[now];
        len /= 2;
        if (now == n) {
          return -1;
        }
      }
    }

    now++;
    return now;
  }
};

