  }

  std::sort(all(a),std::greater<P>());

  BinaryIndexedTree<ll> count(n+10);

  ll ans=0;

  count.add(a[0].second,1);

  rep(i,1,n){
    ll value=a[i].first,itr=a[i].second;
    ll cnt=count.sum(itr);
    ll left1,left2,right1,right2;
    if(cnt==0){
      left1=itr;left2=0;
    }else if(cnt==1){
      left1=itr-count.lower_bound(1);
      left2=count.lower_bound(1);
    }else{
      left1=itr-count.lower_bound(cnt);
      left2=count.lower_bound(cnt)-count.lower_bound(cnt-1);
    }

    if(i-cnt==0){
      right1=n-itr+1;right2=0;
    }else if(i-cnt==1){
      right1=count.lower_bound(cnt+1)-itr;
      right2=n-count.lower_bound(cnt+1)+1;
    }else{
      right1=count.lower_bound(cnt+1)-itr;
      right2=count.lower_bound(cnt+2)-count.lower_bound(cnt+1);
    }

    ans+=(left1*right2+left2*right1)*value;
    count.add(itr,1);
  }

  std::cout<<ans;

  return 0;
}

