int main() {
    int n = 0;
    cin >> n;
    vector<int> a(n);
    for (int i=0; i<n; i++) {
        cin >> a.at(i);
    }
    vector<int> maxi(n);
    for (int i=n-1; i>=0; i--) {
        if (i == n-1) {
            maxi.at(i) = a.at(i);
        }
        else {
            maxi.at(i) = max(maxi.at(i+1), a.at(i));
        }
    }
    int one = 0, two = 0;
    int ans = 0;
    for (int i=0; i<n-1; i++) {
        one = max(a.at(i), a.at(i+1));
        two = min(a.at(i), a.at(i+1));
        ans += two;
        for (int j=i+2; j<n; j++) {
            if (a.at(j) > one) {
                two = one, one = a.at(j);
            }
            else if (a.at(j) > two) {
                two = a.at(j);
            }
            if (two >= maxi.at(j)) {
                ans += two * (n-j);
                break;
            }
            else {
                ans += two;
            }
        }
    }
    cout << ans << endl;
    return 0;
}

