using namespace std;

const int MAX_N = 1e5;
int n;
map<int, int> p;

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        int x;
        scanf("%d", &x);
        p[x] = i;
    }

    int ans = 0;
    set<int> ind;
    for (map<int, int>::reverse_iterator i = p.rbegin(), e = p.rend(); i != e; i++) {
        if (ind.empty()) {
            ind.emplace(i->second);
            continue;
        }
        set<int>::iterator it = ind.lower_bound(i->second);
        int w, x, y, z;
        y = (it == ind.end()) ? n + 1 : *it;
        z = (it == --ind.end() || y == n + 1) ? n + 1 : *next(it);
        x = (it == ind.begin()) ? 0 : *prev(it);
        w = (it == ++ind.begin() || x == 0) ? 0 : *prev(it, 2);
        ans += i->first * (y - i->second) * (x - w);
        ans += i->first * (z - y) * (i->second - x);
        ind.emplace(i->second);
    }

    printf("%d\n", ans);
    return 0;
}

