long long N;
//           point   , position
vector<pair<long long, long long> >P;
set<long long> position;

int main(){
	cin >> N;
	for(long long i = 0; i < N; i++){
		long long point;
		cin >> point;
		P.push_back(make_pair(point, i));
	}
	sort(P.begin(), P.end(), greater<pair<long long, long long>>());


	long long num = 0;
	for(long long i = 0; i < P.size(); i++){
		long long pos = P[i].second;
		long long point = P[i].first;
		//cout << "point = " << point << endl;

		//左で大きいのを取る
		set<long long>::iterator it = position.upper_bound(pos);
		if(position.begin() != it){
			//取れる右の最大値
			long long rightMin = pos;
			long long rightMax = N - 1;
			if(it != position.end()){
				rightMax = *(it) - 1;
			}

			//取れる左の最小値
			long long leftMin = 0;
			long long leftMax = *(prev(it));
			if(position.begin() != prev(it)){
				leftMin = *(prev(prev(it))) + 1;
			}
			//cout << "get left left" << leftMin << " - " << leftMax << " right " << rightMin << " - " << rightMax << endl;
			num += (point) * (leftMax - leftMin + 1) * (rightMax - rightMin + 1);
		}


		//右で大きいのを取る
		if(position.end() != it){
			//取れる右の最大値
			long long rightMin = *it;
			long long rightMax = N - 1;
			if((next(it)) != position.end()){
				rightMax = *(next(it)) - 1;
			}

			//取れる左の最小値
			long long leftMin = 0;
			long long leftMax = pos;
			if(it != position.begin()){
				leftMin = (*(prev(it))) + 1;
			}
			//cout << "get right left" << leftMin << " - " << leftMax << " right " << rightMin << " - " << rightMax << endl;
			num += (point) * (leftMax - leftMin + 1) * (rightMax - rightMin + 1);
		}
		position.insert(pos);
	}

	cout << num << endl;
}

