using namespace std;

int main(int argc, char const *argv[])
{
    int n;
    cin >> n;
    vector<int> p(n);
    for (int i = 0; i < n; i++)
    {
        cin >> p[i];
    }
    long int ans = 0;
    int dpFirst[n][n];
    for (int i = 0; i < n - 1; i++)
    {
        dpFirst[i][i + 1] = max(p[i], p[i + 1]);
    }
    for (int dist = 2; dist < n; dist++)
    {
        for (int i = 0; i < n - dist; i++) {
           dpFirst[i][i + dist] = 
            (dpFirst[i][i + dist - 1] > dpFirst[i + 1][i + dist] 
            ? dpFirst[i][i + dist - 1] : dpFirst[i + 1][i + dist]);
        }        
    }

    int dp[n][n];
    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j < n; j++)
        {
            dp[i][j] = -1;
        }        
    }

    for (int i = 0; i < n - 1; i++)
    {
        dp[i][i + 1] = min(p[i], p[i + 1]);
    }
    for (int dist = 2; dist < n; dist++)
    {
        for (int i = 0; i < n - dist; i++) {
            // dp[i][dist - 1], p[i], p[i + dist]のなかで
            if (dpFirst[i][i + dist - 1] == dpFirst[i + 1][i + dist])
            {
                dp[i][i + dist] = 
                    (dp[i][i + dist - 1] > dp[i + 1][i + dist] 
                    ? dp[i][i + dist - 1] : dp[i + 1][i + dist]);
            } else
            {
                dp[i][i + dist] = min(dpFirst[i][i + dist - 1], dpFirst[i + 1][i + dist]);
            }
        }        
    }
    for (int i = 0; i < n - 1; i++)
    {
        for (int j = i + 1; j < n; j++) {
            ans += dp[i][j];
        }        
    }
    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j < n; j++)
        {
            cout << dp[i][j] << "\t";
        }
        cout << endl;
    }

    cout << ans << endl;    

    return 0;
}

