int main(){
  I n;
  cin >> n;
  V p(n);
  VIN(p);
  I t = 0;
  for (I i=n-1;i>=1;i--){
    if (i == n-1){
      dp[n-1][n][0] = min(p.at(n-2),p.at(n-1));
      dp[n-1][n][1] = max(p.at(n-2),p.at(n-1));
      t += dp[n-1][n][0];
    }else{
      for (I j=n;j>=i+1;j--){
        if (j - i >= 2){
          if (p.at(i-1) > dp[i+1][j][0]){
            if (p.at(i-1) > dp[i+1][j][1]){
              dp[i][j][0] = dp[i+1][j][1];
              dp[i][j][1] = p.at(i-1);
            }else{
              dp[i][j][0] = p.at(i-1);
              dp[i][j][1] = dp[i+1][j][1];
            }
          }else{
              dp[i][j][0] = dp[i+1][j][0];
              dp[i][j][1] = dp[i+1][j][1];
          }
        }else{
          dp[i][j][0] = min(p.at(i-1),p.at(j-1));
          dp[i][j][1] = max(p.at(i-1),p.at(j-1));
        }
        t += dp[i][j][0];
      }
    }
