    vector<int> P(N);
    REP(i, N) { cin >> P[i]; }
    //尺取り法
    //現在地 最大値
    ll ans = 0;
    for(int left = 0; left < N - 1; left++) {
        // cout << "------" << endl;
        int current = min(P[left], P[left + 1]);
        int current_max = max(P[left], P[left + 1]);
        for(int right = left + 1; right < N; right++) {
            if(P[right] > current_max and right != left + 1) {
                current = current_max;
                current_max = P[right];
            } else if(P[right] > current and right != left + 1) {
                current = P[right];
            }
            // cout << current << endl;
            ans += current;
        }
    }
    cout << ans << endl;
}

