int st[400001];int n;
void update(int i,int l,int r,int in,int v)
{
    if(l>r)
        return;
    if(in<l||in>r)
        return;
    if(l==r)
    {
        st[i]=v;
        return;
    }
    int m=(l+r)/2;
    update(2*i+1,l,m,in,v);
    update(2*i+2,m+1,r,in,v);
    st[i]=max(st[2*i+1],st[2*i+2]);
}
int query(int i,int l,int r,int qs,int qe)
{
    if(qs>qe)
        return -1;
    if(qs>r||qe<l)
        return -1;
    if(qs<=l&&qe>=r)
        return st[i];
    int m=(l+r)/2;
    return max(query(2*i+1,l,m,qs,qe),query(2*i+2,m+1,r,qs,qe));
}

