			ans += (ll)i*(R*L);
		}else{
			auto nxt = it;
			nxt++;
			auto prev = it;
			prev--;
			L = rev[i]-(*prev);
			if(nxt==s.end()){
				R = N-(*it);
			}else{
				R = (*nxt)-(*it);
			}
			ans += (ll)i*(R*L);

			R = (*it)-rev[i];
			L = *prev;
			if(prev==s.begin())L++;
			else{
				auto pp = prev;
				pp--;
				L = L-(*pp);
			}
			ans += (ll)i*(R*L);
		}
	}
	cout << ans << endl;
	return 0;
}

