ll lmin(ll a, ll b) { return min(a, b); }
ll lmax(ll a, ll b) { return max(a, b); }

int main() {
  scanf("%lld", &n);
  Zip<ll> zip;
  for (ll i = 0; i < n; i++) scanf("%lld", &o[i]), zip.add(o[i]);
  for (ll i = 0; i < n; i++) p[i] = zip.getNum(o[i]);
  SegmentTree<ll> sgtl, sgtr;
  sgtl.init(n, lmax, 0, 0);
  sgtr.init(n, lmin, n+1, n+1);
  l[0] = 0;
  for (ll i = 0; i < n; i++) {
    l[i+1] = sgtl.rangeQuery(p[i], n);
    sgtl.valueChange(p[i], i+1);
    if (l[i+1] == 0) l2[i+1] = 0;
    else l2[i+1] = max(sgtl.rangeQuery(p[i]+1, p[l[i+1]-1]), sgtl.rangeQuery(p[l[i+1]-1]+1, n));
  }
  r[n+1] = n+1;
  for (ll i = n-1; i >= 0; i--) {
    r[i+1] = sgtr.rangeQuery(p[i], n);
    sgtr.valueChange(p[i], i+1);
    if (r[i+1] == n+1) r2[i+1] = n+1;
    else r2[i+1] = min(sgtr.rangeQuery(p[i]+1, p[r[i+1]-1]), sgtr.rangeQuery(p[r[i+1]-1]+1, n));
  }
  for (ll i = 1; i <= n; i++) {
    ans += (r2[i] - r[i]) * (i - l[i]) * o[i-1];
    ans += (r[i] - i) * (l[i] - l2[i]) * o[i-1];
  }
  printf("%lld\n", ans);
}

