#include <iostream>
#include <set>
#include <vector>

int main()
{
    int n;
    std::cin >> n;

    std::vector<int> p(n);
    std::vector<int> idx(n);
    for (int i = 0; i < n; i++) {
        std::cin >> p[i];
        p[i]--;
        idx[p[i]] = i;
    }

    std::set<int> s;

    long long ans = 0;
    for (int i = n - 1; i >= 0; i--) {
        int id = idx[i];

        s.insert(id);

        std::vector<int> l(2, -1);
        std::vector<int> r(2, n);

        auto center = s.find(id);
        for (int j = 0; j < 2; j++) {
            if (center == s.begin()) {
                break;
            }
            center--;
            l[j] = *center;
        }

        center = s.find(id);
        for (int j = 0; j < 2; j++) {
            center++;
            if (center == s.end()) {
                break;
            }
            r[j] = *center;
        }

        std::vector<int> ls(2), rs(2);

        ls[0] = id - l[0];
        ls[1] = l[0] - l[1];
        rs[0] = r[0] - id;
        rs[1] = r[1] - r[0];

        long long c = (long long)ls[0] * rs[1] + (long long)ls[1] * rs[0];
        ans += c * (i + 1);
    }

    std::cout << ans << std::endl;
}

