int main()
{
    // 整数の入力
    int N;
    cin >> N;
    vector<int> numbersKeyIndexValue(N + 1);
    set<int> indexes;
    multiset<int> workingSetAsc;
    multiset<int, greater<int>> workingSetDesc;

    for (int i = 1; i <= N; ++i)
    {
        int num;
        cin >> num;
        numbersKeyIndexValue.at(num) = i;
        indexes.insert(num);
    }
    workingSetAsc.insert(0);
    workingSetAsc.insert(0);
    workingSetAsc.insert(N + 1);
    workingSetAsc.insert(N + 1);
    workingSetAsc.insert(numbersKeyIndexValue.at(N));

    workingSetDesc.insert(0);
    workingSetDesc.insert(0);
    workingSetDesc.insert(N + 1);
    workingSetDesc.insert(N + 1);
    workingSetDesc.insert(numbersKeyIndexValue.at(N));

    int result = 0;
    for (int num = N - 1; num > 0; --num)
    {
        int index = numbersKeyIndexValue.at(num);
        auto rightIte = workingSetAsc.lower_bound(index);
        int rightUpperIn = *rightIte;
        ++rightIte;
        int rightUpperOut = *rightIte;
        auto leftIte = workingSetDesc.lower_bound(index);
        int leftUpperIn = *leftIte;
        ++leftIte;
        int leftUpperOut = *leftIte;
        result += num * ((leftUpperIn - leftUpperOut) * (rightUpperIn - index) + (index - leftUpperIn) * (rightUpperOut - rightUpperIn));

        workingSetAsc.insert(index);
        workingSetDesc.insert(index);
    }
    cout << result;

    return 0;
}

