struct NODE{
	int mx1,mx2;
}tree[400009];
NODE merge(NODE a,NODE b){
	NODE ret;
	if(a.mx1 > b.mx1){
		ret.mx1 = a.mx1;
		ret.mx2 = max(a.mx2,max(b.mx1,b.mx2));
	}
	else{
		ret.mx1 = b.mx1;
		ret.mx2 = max(b.mx2,max(a.mx1,a.mx2));
	}
	return ret;
}
void build(int node,int l,int r){
	if(l == r) return void(tree[node]={a[l],0});
	build(node*2,l,(l+r)/2),build(node*2+1,(l+r)/2+1,r);
	tree[node] = merge(tree[node*2],tree[node*2+1]);
}
NODE query(int node,int l,int r,int s,int e){
    if(s <= l && e >= r) return tree[node];
    if(s <= (l+r)/2 && e >= (l+r)/2+1){
        return merge(query(node*2,l,(l+r)/2,s,e),query(node*2+1,(l+r)/2+1,r,s,e));
    }
    if(s <= (l+r)/2) return query(node*2,l,(l+r)/2,s,e);
    return query(node*2+1,(l+r)/2+1,r,s,e);
}
