		}
		if(st2.empty()) r[i] = n;
		else r[i] = st2.top();
		st2.push(i);
	}
	long long sum = 0;
	for(int i=0;i<n;i++){
		if(l[i] != -1){
			int ll = -1,rr = l[i];
			while(rr-ll > 1){
				int m = (ll+rr)/2;
				NODE x = query(1,0,n-1,m,i);
				if(x.mx2 == a[i]) rr = m;
				else ll = m;
			}
			int x = l[i]-rr+1;
