map<pair<long long,long long>,long long>m;
struct segment_tree
{
	long long tree[N*4];
	void setAr(long long x,long long l,long long r)//set values to all leaves
	{
		if(l==r)
		{
			tree[x]=l;
			return;
		}
		this->setAr(x*2,l,(l+r)>>1);
		this->setAr(x*2+1,(l+r)/2+1,r);
		if(a[tree[x*2]]>a[tree[x*2+1]])tree[x]=tree[x*2];
		else tree[x]=tree[x*2+1];
	}
	long long RMQ(long long x,long long l,long long r,long long L,long long R)
	{
		if(L<=l && r<=R)return tree[x];
		long long f=0,ansl,ansr;
		if(L<=(l+r)/2)
		{
			ansl=this->RMQ(x*2,l,(l+r)>>1,L,R);
			f|=1;
		}
		if((l+r)/2<R)
		{
			ansr=this->RMQ(x*2+1,(l+r)/2+1,r,L,R);
			f|=2;
		}
		if(f==1)return ansl;
		if(f==2)return ansr;
		if(a[ansl]>a[ansr])return ansl;
		return ansr;
	}
}T;
int n;
long long fin(long long l,long long r)
{
	long long ans;
	if(l>=r)return 0;
	if(m.find({l,r})!=m.end())return m[make_pair(l,r)];
	long long ma=T.RMQ(1,1,n,l,r),ma2,ma3;
	if(ma==l)ma2=T.RMQ(1,1,n,l+1,r);
	else if(ma==r)ma2=T.RMQ(1,1,n,l,r-1);
	else
	{
		ma2=T.RMQ(1,1,n,l,ma-1);
		ma3=T.RMQ(1,1,n,ma+1,r);
		if(a[ma3]>a[ma2])ma2=ma3;
	}
	ans=a[ma2]*(min(ma,ma2)-l+1)*(r-max(ma,ma2)+1);
	ans+=fin(l,max(ma,ma2)-1)+fin(min(ma,ma2)+1,r)-fin(min(ma,ma2)+1,max(ma,ma2)-1);
	return m[make_pair(l,r)]=ans;
}
