    vector<int> r(2,n);
    {//calc l
    auto it = s.find(i);
    for(int j=0; j<2;j++){
      if(it == s.begin()) break;
      it--;
      l.at(j) = *it;
    }
    }
    {//calc r
    auto it = s.find(i);
    for(int j=0; j<2;j++){
      it++;
      if(it == s.end()) break;
      r.at(j) = *it;
    }
    }
    vector<int> ls(2,0);
    vector<int> rs(2,0);
    ls.at(0)= i - l.at(0);
    ls.at(1)= l.at(0) - l.at(1);
    rs.at(0)= r.at(0) - i;
    rs.at(1)= r.at(1) - r.at(0);
    c = (long long)ls.at(0) * rs.at(1) + (long long)ls.at(1) * rs.at(0);
  }
  ans += c * (x+1);
 }
 cout << ans << endl;
}

