#define INTSPACE 12
char _buf[INTSPACE*1000000 + 3];

int loadint() {
    if (fgets(_buf, INTSPACE+3, stdin)==NULL) return 0;
    return atoi(_buf);
}

int loadvec(vector<int>& v, int N=-1) {
    if (N == 0) {
        v.clear();
        return 0;
    }
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    return i;
}


ll solve(int N, vi& p) {
    priority_queue<ii> pq;

    rep(i,N) pq.emplace(p[i], i);

    multiset<int> s;
    s.insert(-1);
    s.insert(-1);
    s.insert(N);
    s.insert(N);
    ll ans = 0;
    while (!pq.empty()){
        int val=pq.top().first, me=pq.top().second; pq.pop();

        auto hi = s.upper_bound(me), hhi = hi, lo = hi, llo = lo;
        ++hhi; --lo; --llo; --llo;
        ll left = me - *lo, lleft = *lo - *llo;
        ll right = *hi - me, rright = *hhi - *hi;
        ans += val * (lleft*right + left*rright);

        s.insert(me);
    }
    return ans;
}

int main() {
    vi p;
    int N = loadvec(p);
    cout << solve(N, p) << endl;
    return 0;
}

