int main() {
    // setInput("in.txt");
    // setOutput("out.txt");
    // setError("err.txt");
    read(N);
    read(P + 1, P + N + 1);
    For(i, 1, N + 1) ind[P[i]] = i;
    iota(L + 1, L + N + 1, 0);
    iota(R + 1, R + N + 1, 2);
    ll ans = 0;
    For(i, 1, N + 1) {
        int l = L[ind[i]], r = R[ind[i]];
        if (l != 0) ans += ll(l - L[l]) * ll(r - ind[i]) * i;
        if (r != N + 1) ans += ll(R[r] - r) * ll(ind[i] - l) * i;
        L[r] = l;
        R[l] = r;
    }
    writeln(ans);
    return 0;
}

