int Get1(int _l, int _r, int val) {
    int low = _l, high = _r, mid;
    while(low <= high) {
        mid = (low + high) >> 1;
        if(GetMax(mid, _r) > val) low = mid + 1;
        else high = mid - 1;
    }
    if(high == _r && _r < 0) return 0;
    return _r + 1 - high;
}

int Get2(int _l, int _r, int val) {
    int low = _l, high = _r, mid;
    while(low <= high) {
        mid = (low + high) >> 1;
        if(GetMax(_l, mid) > val) high = mid - 1;
        else low = mid + 1;
    }
    if(low == _l && _l > n + 1) return 0;
    return low - _l + 1;
}

