class MaxBinaryIndexedTree {
	std::vector<int> vec;
public:
	MaxBinaryIndexedTree(int size) : vec(size, -1) {};
	int operator[](int position) const {
		int result = -1;
		while (position >= 0) {
			result = std::max(result, vec[position]);
			position -= (position + 1) & ~position;
		}
		return result;
	}
	void update(int position, int value) {
		while (position < vec.size()) {
			vec[position] = std::max(vec[position], value);
			position += (position + 1) & ~position;
		}
	}
};
int main() {
	int n; std::cin >> n;
	std::vector<int> permutation(n); for (auto& p : permutation) std::cin >> p;
	std::vector<int> indices(n); for (auto i = 0; i < n; ++i) indices[i] = i;
	std::sort(indices.begin(), indices.end(), [&permutation](int a, int b) {return permutation[a] > permutation[b]; });
	MaxBinaryIndexedTree forward(n), backward(n);
	long long int result = 0;
	forward.update(indices.front(), indices.front());
	backward.update(n - 1 - indices.front(), n - 1 - indices.front());
	for (auto i = 1; i < n; ++i) {
		const auto idx = indices[i];
		const auto val = permutation[idx];
		const auto left_first = forward[idx];
		const auto left_second = forward[left_first - 1];
		const auto right_first = n - 1 - backward[n - 1 - idx];
		const auto right_second = n - 1 - backward[n - 1 - right_first - 1];
		long long int left_left_length, left_right_length = idx - left_first;
		if (left_first == -1) {
			left_left_length = 0;
		}
		else {
			left_left_length = left_first - left_second;
		}
		long long int right_right_length, right_left_length = right_first - idx;
		if (right_first == n) {
			right_right_length = 0;
		}
		else {
			right_right_length = right_second - right_first;
		}
		forward.update(idx, idx);
		backward.update(n - 1 - idx, n - 1 - idx);
		result += (left_left_length * right_left_length + left_right_length * right_right_length) * val;
	}
	std::cout << result << std::endl;

}

