const ll MAXN = 100005;
pair<ll,ll> t[4*MAXN];

void build(ll a[], ll v, ll tl, ll tr) 
{
    if (tl == tr) 
        t[v] = {a[tl],C};
    else 
    {
        ll tm = (tl + tr) / 2;
        build(a, v*2, tl, tm);
        build(a, v*2+1, tm+1, tr);
        ll x[4]={t[v*2].first,t[v*2].second,t[v*2+1].first,t[v*2+1].second};
        sort(x,x+4);
        t[v] = {x[0],x[1]};
    }
}

pair<ll,ll> tmi(ll v, ll tl, ll tr, ll l, ll r) 
{
    if (l > r) 
        return {C,C};
    if (l == tl && r == tr) 
        return t[v];
    ll tm = (tl + tr) / 2;
    pair<ll,ll> p = tmi(v*2, tl, tm, l, min(r, tm)), q = tmi(v*2+1, tm+1, tr, max(l, tm+1), r);
    ll x[4]={p.first,p.second,q.first,q.second};
   	sort(x,x+4);
    return {x[0],x[1]};
}

void update(ll v, ll tl, ll tr, ll pos, ll new_val) 
{
    if (tl == tr) 
    	t[v] = {new_val,C};
    else 
    {
        ll tm = (tl + tr) / 2;
        if (pos <= tm)
            update(v*2, tl, tm, pos, new_val);
        else
            update(v*2+1, tm+1, tr, pos, new_val);
        ll x[4]={t[v*2].first,t[v*2].second,t[v*2+1].first,t[v*2+1].second};
        sort(x,x+4);
        t[v] = {x[0],x[1]};
    }
}

int main() 
{
    FAST;
    ll n;
    cin>>n;
    ll a[n+1],p[n];
    for(int i=0;i<n;i++)
    	cin>>p[i];
    for(int i=0;i<=n;i++)
    	a[i]=C;
    ll x1[n+1],x2[n+1],x3[n+1],x4[n+1];
    ll ans=0;
    build(a, 1, 0, n);
    for(int i=0;i<n;i++)
    {
    	update(1, 0, n, p[i], i);
    	pair<ll,ll> q = tmi(1, 0, n, p[i]+1, n);
    	if(q.second==C && q.first==C)
    	{	
    		x1[i]=0;
    		x2[i]=i+1;
    	}
    	if(q.second==C && q.first!=C)
    	{
    		x1[i]=q.first+1;
    		x2[i]=i-q.first;
    	}
    	if(q.second!=C && q.first!=C)
    	{
    		x1[i]=q.second-q.first;
    		x2[i]=i-q.second;
    	}
    }
    memset(t,0,sizeof(t));
    for(int i=0;i<4*MAXN;i++)
    	t[i]={0,0};
    build(a, 1, 0, n);
    for(int i=n-1;i>=0;i--)
    {
    	update(1, 0, n, p[i], i);
    	pair<ll,ll> q = tmi(1, 0, n, p[i]+1, n);
    	if(q.second==C && q.first==C)
    	{	
    		x4[i]=0;
    		x3[i]=n-i;
    	}
    	if(q.second==C && q.first!=C)
    	{
    		x4[i]=n-q.first;
    		x3[i]=q.first-i;
    	}
    	if(q.second!=C && q.first!=C)
    	{
    		x4[i]=q.second-q.first;
    		x3[i]=q.first-i;
    	}
    }
    for(int i=0;i<n;i++)
    	ans+=p[i]*((x1[i]*x3[i])+(x2[i]*x4[i]));
    cout<<ans;
    cerr << "Time : " << 1000 * ((double)clock()) / (double)CLOCKS_PER_SEC << "ms\n";
    return 0;
}

