  temp.reserve(n);
  {
    for (i64 i = 0; i != n; ++i) {
      while (!st1.empty() && a[st1.back()] < a[i]) {
        ss[st1.back()] = i;
        st1.pop_back();
      }
      while (!st0.empty() && a[st0.back()] < a[i]) {
        s[st0.back()] = i;
        temp.push_back(st0.back());
        st0.pop_back();
      }
      st0.push_back(i);
      while (!temp.empty()) {
        st1.push_back(temp.back());
        temp.pop_back();
      }
    }
    while (!st0.empty()) {
      s[st0.back()] = n;
      ss[st0.back()] = n;
      st0.pop_back();
    }
    while (!st1.empty()) {
      ss[st1.back()] = n;
      st1.pop_back();
    }
  }
  {
    for (i64 i = n; i != 0;) {
      --i;
      while (!st1.empty() && a[st1.back()] < a[i]) {
        pp[st1.back()] = i;
        st1.pop_back();
      }
      while (!st0.empty() && a[st0.back()] < a[i]) {
        p[st0.back()] = i;
        temp.push_back(st0.back());
        st0.pop_back();
      }
      st0.push_back(i);
      while (!temp.empty()) {
        st1.push_back(temp.back());
        temp.pop_back();
      }
    }
    while (!st0.empty()) {
      p[st0.back()] = -1;
      pp[st0.back()] = -1;
      st0.pop_back();
    }
    while (!st1.empty()) {
      pp[st1.back()] = -1;
      st1.pop_back();
    }
  }

  i64 ans = 0;
  for (i64 i = 0; i != n; ++i) {
    ans += a[i] * ((p[i] - pp[i]) * (s[i] - i) + (i - p[i]) * (ss[i] - s[i]));
  }
  printf("%lld\n", ans);

  return 0;
}

