template<typename T>
struct BinaryIndexedTree{
    vector<T> data;
    int sz;

    BinaryIndexedTree(int n){
        sz = n + 1;
        data.assign(sz, 0);
    }

    void add(int i, T x){
        ++i;
        while(i < sz){
            data[i] += x;
            i += i & -i;
        }
    }

    // [0, i] の区間和
    T sum(int i){
        T res = 0;
        ++i;
        while(i > 0){
            res += data[i];
            i -= i & -i;
        }
        return res;
    }

    T sum(int l, int r){
        return sum(r - 1) - sum(l - 1);
    }

    // val 以上を満たす 0-indexed の位置を返す
    int lower_bound(T val){
        // if(val <= 0)    return -1;
        int res = 0;
        int n = 1;
        while(n < sz)   n <<= 1;
        for(int k = n >> 1; k > 0; k >>= 1){
            if(res + k < sz && data[res + k] < val){
                val -= data[res + k];
                res += k;
            }
        }
        return res;     // 1-indexed であれば、res + 1 を返す
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> p(n + 1);
    for(int i = 0; i < n; ++i){
        int foo;
        cin >> foo;
        p[foo] = i + 1;
    }
    ll ans = 0;
    BinaryIndexedTree<int> bit(n + 5);
    bit.add(0, 1);
    bit.add(n + 1, 1);
    for(int i = n; i >= 1; --i){
        int S = bit.sum(p[i]);
        if(S >= 2){
            int l = bit.lower_bound(S - 1);
            int r = bit.lower_bound(S);
            int LeftLen = r - l;
            r = bit.lower_bound(S + 1);
            int RightLen = r - p[i];
            ans += (ll)LeftLen * RightLen * i;
        }
        S = bit.sum(n + 1) - bit.sum(p[i]);
        if(S >= 2){
            S = bit.sum(p[i]);
            int l = bit.lower_bound(S + 1);
            int r = bit.lower_bound(S + 2);
            int RightLen = r - l;
            l = bit.lower_bound(S);
            int LeftLen = p[i] - l;
            ans += (ll)LeftLen * RightLen * i;
        }
        bit.add(p[i], 1);
    }
    cout << ans << endl;
}

