#define MAXN 100010
#define MAXLOGN 20
#define comp(a, b) max((a), (b))
int st[MAXN][MAXLOGN];

void init(int* bg, int*en){
	int sz = int(en-bg);
	for(int i=0; i<sz; ++i) st[i][0] = bg[i];
	for(int j=1; 1 << j <= sz; ++j)
		for(int i=0; i + (1<<j) <= sz; ++i)
			st[i][j] = comp(st[i][j-1], st[i + (1<<(j-1))][j-1]);
}
int query(int l, int r){
	int k = (int) floor(log((double)r-l+1) / log(2.0));
	return comp(st[l][k], st[r-(1<<k)+1][k]);
}

int pos[MAXN];
int vs[MAXN];

int fg(int l, int r, int x, bool left){
	if(r<=l) return -1;
	int y = query(l, r-1);
	if(y<=x) return -1;
	while(r-l>1){
		int k = l + (r-l)/2;
		y = query(k, r-1);
		if(left and y>x) l = k;
		else r = k;
	}
	return vs[l];
}
int main(){
	int n;
	scanf("%d", &n);
	for(int i=0; i<n; ++i)
		scanf("%d", &vs[i]), pos[vs[i]] = i;
	init(vs, vs+n);
	ll ans = 0;
	for(int x=1; x<=n; ++x){
		int i = pos[x];
		int y;
		y = fg(0, i, x, true);
		ll res = 0;
		if(y>x){
			int xl = fg(0, pos[y], x, true);
			int xr = fg(i+1, n, x, false);
			ll r1, r2;
			if(xl==-1) r1 = pos[y]+1;
			else r1 = pos[y]-pos[xl];
			if(xr==-1) r2 = n-pos[x];
			else r2 = pos[xr]-pos[x];
			res += r1*r2*ll(x);
		}
		if(i!=n-1) y = fg(i+1, n, x, false);
		else y=-1;
		if(y>x){
			int xl = fg(0, pos[x], x, true);
			int xr = fg(pos[y]+1, n, x, false);
			ll r1, r2;
			if(xl==-1) r1 = pos[x]+1;
			else r1 = pos[x]-pos[xl];
			if(xr==-1) r2 = n-pos[y];
			else r2 = pos[xr]-pos[y];
			res += r1*r2*ll(x);
		}
		ans += res;
	}
	cout << ans << endl;
}

