int main(){
    ll n, ans = 0, tmp = 0;
    cin >> n;

    vll p(n);
    cin >> p;

    vvll q(n,vll(4));
    REP(i,n){
        if(i == 0){
            q[i][0] = -1;
            q[i][1] = -1;
            tmp = 2;
        }
        else if(p[i] > p[i-1] && p[i] < q[i][0]){
            q[i][0] = q[i-1][0];
            q[i][1] = q[i-1][1];
            tmp = 2;
        }
        else{
            RREP(j,i){
                if(p[j]>p[i]){
                    q[i][tmp] = j;
                    tmp++;
                    if(tmp == 2) break;
                }
            }
            if(tmp == 0){
                q[i][0] = -1;
                q[i][1] = -1;
                tmp = 2;
            }
            else if(tmp == 1){
                q[i][1] = -1;
                tmp = 2;
            }
        }

    REP(j,n-i-1){
            if(p[j+i+1]>p[i]){
                q[i][tmp] = j+i+1;
                tmp++;
                if(tmp == 4){
                    tmp = 0;
                    break;
                }
            }
        }
        if(tmp == 2){
            q[i][2] = n;
            q[i][3] = n;
            tmp = 0;
        }
        else if(tmp == 3){
            q[i][3] = n;
            tmp = 0;
        }
    }

    REP(i,n){
        ans += p[i]*(q[i][0]-q[i][1])*(q[i][2]-i);
        ans += p[i]*(q[i][3]-q[i][2])*(i-q[i][0]);
    }
    cout << ans << endl;
    return 0;
}

