void build(int sz) {
    while (len < sz) len <<= 1; 
    tree.resize(len + len - 1); 
    for (int i = 0; i < n; ++i) {
        tree[i + len - 1] = cnt[i]; 
    }
    for (int i = len - 2; i >= 0; --i) {
        tree[i] = max(tree[i * 2 + 1], tree[i * 2 + 2]); 
    }
}

int get(int l, int r, int l1, int r1, int rt) {
    if (l >= l1 && r <= r1) {
        return tree[rt]; 
    }
    if (max(l, l1) > min(r, r1)) return -inf; 
    int tm = (l + r) / 2;
    return max(get(l, tm, l1, r1, rt * 2 + 1), get(tm + 1, r, l1, r1, rt * 2 + 2)); 
}

