auto solve(ll n, const VL& v) {

	map<ll, ll> mp;
	REP(i, n) { mp.emplace(v[i], i); }

	multiset<ll> st;
	ll ans = 0;
	RREPI(itr, mp) {
		ll x = itr->first;
		ll i = itr->second;
		auto r1 = st.lower_bound(i);
		if (r1 != st.begin()) {
			auto l1 = r1; --l1;
			ll l = [&](auto it) {
				ll val = *it;
				if (it == st.begin()) { return val + 1; }
				--it;
				return val - *it;
			}(l1);
			ll r = ((r1 == st.end()) ? n : *r1) - i;
			ans += x * r * l;
		}
		if (r1 != st.end()) {
			auto r2 = r1; ++r2;
			ll r = [&]() {
				if (r2 == st.end()) { return n - *r1; }
				return  *r2 - *r1;
			}();
			ll l = i - ((r1 == st.begin()) ? -1 : *(--r1));
			ans += x * r * l;
		}
		st.emplace(i);
	}
	return ans;
}

auto solve_c(ll n, const VL& v) {
	ll ans = 0;
	REP(i, n - 1)FOR(j, i + 1, n) {
		ll a = 0, b = 0;
		FOR(k, i, j + 1) {
			if (v[k] > a) { b = a; a = v[k]; } else { chmax(b, v[k]); }
		}
		ans += b;
	}
	return ans;
}

