void build(ll l=0, ll r=n, ll ind=1) {
  if (r - l < 2) {
    vector<ll> temp(2, 0);
    temp[1] = v[l];
    segment[ind] = temp;
    return ;
  }
  ll mid = (l+r)/2;
  build(l, mid, ind*2);
  build(mid, r, ind*2 + 1);
  vector<ll> left = segment[ind*2];
  vector<ll> right = segment[ind*2 + 1];
  left.insert(left.end(), right.begin(), right.end());
  sort(left.begin(), left.end());
  vector<ll> temp(2, 0);
  temp[1] = left[3];
  temp[0] = left[2];
  segment[ind] = temp;
}

vector<ll> query(ll x, ll y, ll l=0, ll r=n, ll ind=1) {
  vector<ll> temp(2, 0);
  if (x >= r || y <= l) return temp;
  if (l >= x && r <= y) return segment[ind];
  ll mid = (l+r)/2;
  vector<ll> left = query(x,y,l, mid, ind*2);
  vector<ll> right = query(x,y,mid, r, ind*2 + 1);
  if (left[1] == 0) return right;
  if (right[1] == 0) return left;
  left.insert(left.end(), right.begin(), right.end());
  sort(left.begin(), left.end());
  temp[1] = left[3];
  temp[0] = left[2];
  return temp;
}

