#define ll long long

void solve()
{
    ll N /*10^5*/;
    cin >> N;
    vector<ll> P(N + 1);
    for (ll i = 1; i <= N; i++)
    {
        cin >> P.at(i);
    }

    auto compare = [](ll a, ll b) {
        return a < b;
    };

    ll count = 0;
    for (ll L = 1; L <= N - 1; L++)
    {
        priority_queue<ll,
                       vector<ll>,
                       decltype(compare)>
            A{compare};
        A.push(P.at(L));
        for (ll R = L + 1; R <= N; R++)
        {
            A.push(P.at(R));
            auto top = A.top();
            A.pop();
            auto second = A.top();
            A.push(top); // 戻しておく
            count += second;
        }
    }

    cout << count << endl;
}

