  for(int i=N-1;i>=0;i--){
    uint64_t c;//最大から2番目の値がiであるLとRの選び方の和
    s.insert(idx[i]);
    vector<int> l(2,-1);//Lの位置。l(0)は1つ目の赤丸の位置、l(1)は二つ目の赤丸の位置（iから見て）
    vector<int> r(2,N);//Rの位置。同様。
