    if(idx[i]!=*begin(s)){
      --itr;//itrを一つ左に戻す
      l[0]=*itr;//iteratorのあるsの値を参照して代入。
      if(l[0]!=*begin(s)){
        --itr;//itrを一つ左に戻す
        l[1]=*itr;//iteratorのあるsの値を参照して代入。
      }
    }
