int main()
{
    int N;
    cin >> N;

    map<int, int> ord;  //! Number -> Index map

    for (int i = 1; i <= N; ++i) {
        int P;
        cin >> P;
        ord[P] = i;
    }

    LL ans = 0;
    set<int> s; //! set of index of numbers gte i
    for (int i = N; 1 <= i; --i) {
        int curr = ord[i];
        // cout << "i = " << i << ", curr = " << curr << endl;
        auto ret = s.insert(curr);
        int p = -1;
        int pp = -1;
        if (ret.first != s.begin()) {
            auto it = ret.first;
            --it;
            p = *it;
            if (it != s.begin()) {
                --it;
                pp = *it;
            }
        }
        int n = -1;
        int nn = -1;
        auto it = ret.first;
        ++it;
        if (it != s.end()) {
            n = *it;
            ++it;
            if (it != s.end()) {
                nn = *it;
            }
        }
        // cout << pp << ' ' << p << ' ' << curr << ' ' << n << ' ' << nn << endl;

        LL count = 0;
        if (0 < p) {
            //! have a bigger number on left
            int lv = ((0 < pp) ? (p - pp) : p);
            int rv = ((0 < n) ? (n - curr) : (N-curr+1));
            count +=  lv * rv;
        }
        if (0 < n) {
            //! have a bigger number on right
            int lv = ((0 < p) ? (curr-p) : (curr));
            int rv = ((0 < nn) ? (nn - n) : (N-n+1));
            count +=  lv * rv;
        }
        ans += i * count;
    }

    cout << ans << endl;

    return 0;
}

