        auto itr2 = itr;

        x = *(--itr);
        w = *(--itr);
        y = *(++itr2);
        z = *(++itr2);

        ans += (i+1) * ((x-w) * (y-loc[i]) + (loc[i]-x) * (z-y));

    }

    cout << ans << endl;

    return 0;
}

