int a[maxn], stk[maxn], l[maxn], r[maxn];
void solve() {
    int n;
    scd(n);
    int top=0;
    for(int i=1; i<=n; i++) {
        scd(a[i]);
        while(top>0 && a[stk[top-1]] < a[i]) top--;
        stk[top++] = i;
        if(top==1) l[i]=0;
        else l[i]=stk[top-2];
    }

    top=0;
    for(int i=n; i>0; i--){
        while(top>0 && a[stk[top-1]] < a[i]) top--;
        stk[top++] = i;
        if(top==1) r[i]=n+1;
        else r[i] = stk[top-2];
    }
    ll ans=0;
    for(int i=1; i<=n; i++){
        if(l[i]!=0){
            int ll=l[i]-1;
            while(1){
                if(a[ll]>a[i] || ll==0) break;
                ll--;
            }
            int f1=l[i]-ll;
            int f2=r[i]-i;
            ans += 1LL*a[i]*f1*f2;
        }
        if(r[i]!=n+1){
            int rr=r[i]+1;
            while(1){
                if(a[rr]>a[i] || rr==n+1) break;
                rr++;
            }
            int f1=i-l[i];
            int f2=rr-r[i];
            ans += 1LL*a[i]*f1*f2;
        }
    }
    printf("%lld\n", ans);
}

