    vector<int> second_max(N);
    REP(i, N) { cin >> P[i]; }
    //尺取り法
    //現在地 最大値
    ll ans = 0;
    for(int left = 0; left < N - 1; left++) {
        if(left == 0) {
            // cout << "------" << endl;
            int current = min(P[left], P[left + 1]);
            int current_max = max(P[left], P[left + 1]);
            for(int right = left + 1; right < N; right++) {
                if(P[right] > current_max and right != left + 1) {
                    current = current_max;
                    current_max = P[right];
                } else if(P[right] > current and right != left + 1) {
                    current = P[right];
                }
                // cout << current << endl;
                ans += current;
                MAX[right] = current_max;
                second_max[right] = current;
            }
        } else {
            int current = min(P[left], P[left + 1]);
            int current_max = max(P[left], P[left + 1]);
            for(int right = left + 1; right < N; right++) {
                if(P[left - 1] != MAX[right] and
                   P[left - 1] != second_max[right]) {
                    ans += second_max[right];
                    current_max = MAX[right];
                    current = second_max[right];
                } else if(P[left - 1] == MAX[right]) {
                    MAX[right] = second_max[right];
                    // search for second max
                    if(P[right] > current_max and right != left + 1) {
                        current = current_max;
                        current_max = P[right];
                    } else if(P[right] > current and right != left + 1) {
                        current = P[right];
                    }
                    // cout << current << endl;
                    ans += current;
                    second_max[right] = current;
                } else if(P[left - 1] == second_max[right]) {
                    // search for second max
                    if(P[right] > current_max and right != left + 1) {
                        current = current_max;
                        current_max = P[right];
                    } else if(P[right] > current and right != left + 1) {
                        current = P[right];
                    }
                    // cout << current << endl;
                    ans += current;
                    second_max[right] = current;
                }
            }
        }
    }
    cout << ans << endl;
}

