int main(){
  cin>>N;
  P.resize(N);
  rep(i,N) cin>>P[i];

  for(int i=0;i<N;i++) trans[P[i]]=i;

  SegmentTree<int> seg(N+2,[](int a,int b){return min(a,b);},N+1);
  SegmentTree<int> msg(N+2,[](int a,int b){return max(a,b);},0);

  ll ans=0;
  for(int i=N;i>=1;i--){
    int now=trans[i];
    int rf=seg.query(now+1,N+1);
    int lf=msg.query(1,now+1);
    int rs=N+1,ls=0;

    //cout<<now+1<<" "<<rf<<" "<<lf<<endl;
    if(rf<N){
      rs=seg.query(rf+1,N+1);
    }
    if(lf>0){
      ls=msg.query(1,lf);
    }
    //cout<<ls<<" "<<rs<<endl;

    ll res=0;
    if(rf<=N) res+=(rs-rf)*(now+1-lf);
    if(lf>0) res+=(lf-ls)*(rf-(now+1));
    //cout<<res<<endl;
    ans+=res*i;

    seg.update(now+1,now+1);
    msg.update(now+1,now+1);
  }

  cout<<ans<<endl;


  return 0;
}

