struct segment_tree_min
{
    int n;
    vector<pair<int, int>> a;

    segment_tree_min(int n) : n(n), a(2 * n, make_pair(n-2, n-2)) {}

    pair<int, int> merge(pair<int, int> a, pair<int, int> b)
    {
    	vector<int> v = { a.F, a.S, b.F, b.S };
    	sort(v.begin(), v.end());
    	return { v[0], v[1] };
    }

    void update(int p, pair<int, int> v)
    {
        for (a[p += n] = v; p /= 2;)
            a[p] = merge(a[2 * p], a[2 * p + 1]);
    }

    pair<int, int> query(int l, int r)
    {
        pair<int, int> g = { n-2, n-2 };

        for (l += n, r += n; l < r; l /= 2, r /= 2)
        {
            if (l & 1) g = merge(g, a[l++]);
            if (r & 1) g = merge(g, a[--r]);
        }

        return g;
    }
};

struct segment_tree_max
{
    int n;
    vector<pair<int, int>> a;

    segment_tree_max(int n) : n(n), a(2 * n, make_pair(-1, -1)) {}

    pair<int, int> merge(pair<int, int> a, pair<int, int> b)
    {
    	vector<int> v = { a.F, a.S, b.F, b.S };
    	sort(v.begin(), v.end());
    	return { v[3], v[2] };
    }

    void update(int p, pair<int, int> v)
    {
        for (a[p += n] = v; p /= 2;)
            a[p] = merge(a[2 * p], a[2 * p + 1]);
    }

    pair<int, int> query(int l, int r)
    {
        pair<int, int> g = { -1, -1 };

        for (l += n, r += n; l < r; l /= 2, r /= 2)
        {
            if (l & 1) g = merge(g, a[l++]);
            if (r & 1) g = merge(g, a[--r]);
        }

        return g;
    }
};

