const int maxn=1e5+5;
int n;
vector<pair<int,int>> tree(8*maxn);
pair<int,int> merge(pair<int,int> a,pair<int,int> b,bool fl){
    vector<int> v={a.first,a.second,b.first,b.second};
    if(fl==0) sort(v.rbegin(),v.rend());
    else sort(v.begin(),v.end());
    return {v[0],v[1]};
}
void build(int v,int tl,int tr,bool fl=0){
    if(tl==tr){
        if(fl==0) tree[v]={-1,-1};
        else tree[v]={n,n};
        return ;
    }
    int mid=(tl+tr)>>1;
    build(2*v,tl,mid,fl);
    build(2*v+1,mid+1,tr,fl);
    tree[v]=merge(tree[2*v],tree[2*v+1],fl);
}
void update(int v,int tl,int tr,int pos,int val,int fl){
    if(pos > tr or pos < tl) return;
    if(tl==tr and pos==tl){
        tree[v].first=val;
        return;
    }
    int mid=(tl+tr)>>1;
    update(2*v,tl,mid,pos,val,fl);
    update(2*v+1,mid+1,tr,pos,val,fl);
    tree[v]=merge(tree[2*v],tree[2*v+1],fl);
}
pair<int,int> query(int v,int tl,int tr,int ql,int qr,bool fl){
    if(ql > qr or qr < tl or ql > tr){
        if(fl==0) return {-1,-1};
        else return {n,n};
    }
    if(tl>=ql and tr<=qr) return tree[v];
    int mid=(tl+tr)>>1;
    return merge(query(2*v,tl,mid,ql,qr,fl),query(2*v+1,mid+1,tr,ql,qr,fl),fl);
}
