typedef long long ll;
typedef pair<int, int> PAIR;

#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)
#define ITR(c,it)  for(auto it = c.begin(); it != c.end(); it++)
#define DUMP(a, n) REP(i, n) printf("%d%c", a[i], i + 1 == n ? '\n' : ' ')
#define DUMP2D(a, n, m) REP(i, n) REP(j, m) printf("%d%c", a[i][j], j + 1 == m ? '\n' : ' '); puts("")

const int N_MAX = 1e5;

int N;
int P[N_MAX];

int L1[N_MAX];
int L2[N_MAX];
int R1[N_MAX];
int R2[N_MAX];

set<PAIR, greater<PAIR>> rst, lst;

void solve() {
  fill(R1, R1 + N, N);
  fill(R2, R2 + N, N);
  fill(L1, L1 + N, -1);
  fill(L2, L2 + N, -1);
  REP(i, N) {
    PAIR p = make_pair(P[i], i);
    auto it = rst.lower_bound(p);
    while (it != rst.end()) {
      int k = it->second;
      if (R1[k] == N) {
        R1[k] = i;
        it++;
      } else {
        R2[k] = i;
        it = rst.erase(it);
      }
    }
    rst.insert(p);
  }
  for (int i = N - 1; i >= 0; i--) {
    PAIR p = make_pair(P[i], i);
    auto it = lst.lower_bound(p);
    while (it != lst.end()) {
      int k = it->second;
      if (L1[k] < 0) {
        L1[k] = i;
        it++;
      } else {
        L2[k] = i;
        it = lst.erase(it);
      }
    }
    lst.insert(p);
  }
  ll ans = 0;
  REP(i, N) {
    ll tmp = 0;
    tmp += (i - L1[i]) * (R2[i] - R1[i]);
    tmp += (L1[i] -L2[i]) * (R1[i] - i);
    // printf("%d %d %d %d %d => %lld\n", L2[i], L1[i], i, R1[i], R2[i], tmp);
    ans += tmp * P[i];
  }
  printf("%lld\n", ans);
}

void input() {
  scanf("%d", &N);
  REP(i, N) scanf("%d", P + i);
}

int main() {
  input();
  solve();
  return 0;
}

