ll find(BIT &tree, ll idx, ll edge, ll aim)
{
    ll left = 1LL;
    ll right = abs(idx - edge) + 1LL;
    ll now = (left + right) / 2LL;
    ll ret = 1LL;

    for ( ; left <= right; now = (left + right) / 2LL) {
        ll lsum;
        if (edge == 1LL) lsum = tree.sum(idx) - tree.sum(idx - now);
        else lsum = tree.sum(idx + now - 1LL) - tree.sum(idx);
        if (lsum <= aim) {
            ret = max(ret, now);
            left = now + 1LL;
        }
        else {
            right = now - 1LL;
        }
    }

    return ret;
}

