#include <bits/stdc++.h>
using namespace std;

int A[100009], L[100009], R[100009], LL[100009], RR[100009];

struct seg {
    vector<int> T;
    void upd(int idx, int s, int e, int p, int v) {
        if(p < s || e < p) return;
        if(s == e) {
            T[idx] = v;
            return;
        }
        int m = s+e >> 1;
        upd(idx*2, s, m, p, v);
        upd(idx*2+1, m+1, e, p, v);
        T[idx] = max(T[idx*2], T[idx*2+1]);
    }
    int get(int idx, int s, int e, int l, int r) {
        if(r < s || e < l) return -1e9;
        if(l <= s && e <= r) return T[idx];
        int m = s+e >> 1;
        return max(get(idx*2, s, m, l, r), get(idx*2+1, m+1, e, l, r));
    }
    seg(int N) {
        T.resize(4*N);
    }
};

int main() {
    int N; scanf("%d",&N);
    seg ST(N);
    for(int i=1; i<=N; i++) {
        scanf("%d",&A[i]);
        ST.upd(1, 1, N, i, A[i]);
        L[i] = 0; R[i] = N+1;
    }
    vector<int> S;
    for(int i=1; i<=N; i++) {
        while(S.size() && A[S.back()] < A[i]) {
            R[S.back()] = i;
            S.pop_back();
        }
        S.push_back(i);
    }
    S.clear();
    for(int i=N; i>=1; i--) {
        while(S.size() && A[S.back()] < A[i]) {
            L[S.back()] = i;
            S.pop_back();
        }
        S.push_back(i);
    }
    for(int i=1; i<=N; i++) {
        int l = 1, r = L[i] - 1, f = 0;
        while(l <= r) {
            int m = l+r >> 1;
            if(ST.get(1, 1, N, m, L[i]-1) > A[i]) l = m+1, f = m;
            else r = m-1;
        }
        LL[i] = f;
        l = R[i] + 1, r = N, f = N+1;
        while(l <= r) {
            int m = l+r >> 1;
            if(ST.get(1, 1, N, R[i]+1, m) > A[i]) r = m-1, f = m;
            else l = m+1;
        }
        RR[i] = f;
    }
    long long ans = 0;
    for(int i=1; i<=N; i++) {
        if(L[i] != 0) ans += 1LL * A[i] * (L[i] - LL[i]) * (R[i] - i);
        if(R[i] != N+1) ans += 1LL * A[i] * (RR[i] - R[i]) * (i - L[i]);
    }
    printf("%lld", ans);
    return 0;
}

#include<bits/stdc++.h>

using namespace std;

typedef long long ll;
const int maxn=2e5+10;
int mod=1e9+7;
int tree[maxn*4];
int n;
int a[maxn];

void pushup(int rt)
{
    tree[rt]=max(tree[rt<<1],tree[rt<<1|1]);
}
void build(int l,int r,int rt)
{
    if(l==r)
    {
        tree[rt]=a[l];
        return;
    }
    int mid=(l+r)>>1;
    build(l,mid,rt<<1);
    build(mid+1,r,rt<<1|1);
    pushup(rt);
}
int ask(int l,int r,int L,int R,int rt)
{
    int ans=0;

    if(l<=L&&R<=r)
    {
        return tree[rt];
    }
    int mid=(L+R)>>1;
    if(l<=mid)
        ans=max(ans,ask(l,r,L,mid,rt<<1));
    if(r>mid)
        ans=max(ans,ask(l,r,mid+1,R,rt<<1|1));
    return ans;
}
int findx(int l,int r,int x,int op,int ok)
{
    if(l>r)
        return -1;
    if(ok==0&&ask(l,r,1,n,1)<x)
        return -1;
    else ok=1;
    if(l==r)
        return l;
    int mid=(l+r)>>1;

    if(op==0)
    {
        int rnum=ask(mid+1,r,1,n,1);
        if(rnum>x)
            return findx(mid+1,r,x,op,ok);
        else
            return findx(l,mid,x,op,ok);
    }
    else if(op==1)
    {
        int rnum=ask(l,mid,1,n,1);
        if(rnum>x)
            return findx(l,mid,x,op,ok);
        else
            return findx(mid+1,r,x,op,ok);
    }

}
