    for(int i=1;i<=n;i++)
    {
        int ans[5];
        ans[1]=findx(1,i-1,a[i],0,0);
        ans[0]=findx(1,ans[1]-1,a[i],0,0);
        if(ans[0]==-1)
            ans[0]=0;
