pair<int, int> pppp(pair<int, int> a, int b, bool bo) {
	if(bo) {
		if(b > a.first) a.second = a.first, a.first = b;
		else if(b > a.second) a.second = b;
	} else {
		if(b < a.first) a.second = a.first, a.first = b;
		else if(b < a.second) a.second = b;
	}
	return a;
}

pair<int, int> P(pair<int, int> a, pair<int, int> b, bool bo) {
	a = pppp(a, b.first, bo);
	a = pppp(a, b.second, bo);
