}

struct WEEE {
	// a < b | a.first < a.second | b.first > b.second
	WEEE *l, *r;
	pair<int, int> a, b;

	WEEE() {
		l = r = NULL;
		a = np[0];
		b = np[1];
	}

	void pp() {
		if(l == NULL) l = new WEEE();
		if(r == NULL) r = new WEEE();
		a = P(l->a, r->a, 0);
		b = P(l->b, r->b, 1);
	}
} *rt;

