void rnk(int l, int r, WEEE *&t) {
	if(t == NULL) t = new WEEE();
	if(l == r) {
		t->a.first = t->b.first = vl;
		return;
	}
	if(M(l, r) >= si) rnk(l, M(l, r), t->l);
	else rnk(M(l, r) + 1, r, t->r);
	t->pp();
}

