bool bo;
int sl, sr;
pair<int, int> rgm(int l, int r, WEEE *&t) {
	if(t == NULL || l > sr || r < sl) return np[bo];
	if(sl <= l && r <= sr) return (bo ? t->b : t->a);
	return P(rgm(l, M(l, r), t->l), rgm(M(l, r) + 1, r, t->r), bo);
}

