// 1 -1
void sol(int f, int mx[N][2]) {
    v[0].clear(); v[1].clear();
    int st = 0, en = n-1;
    if(f==-1) swap(st, en); 
    for(int i = st; i != en+f; i += f) {
        vector<int> tmp;
        while(!v[0].empty() && a[v[0].back()] < a[i]) {
            tmp.push_back(v[0].back());
            v[0].pop_back();
        }
        while(!v[1].empty() && a[v[1].back()] < a[i]) {
            v[1].pop_back();
        }
        mx[i][0] = mx[i][1] = -999999999;
        if(v[0].size()) {
            mx[i][0] = cal(f, i, v[0].back());
        }
        int sz0 = v[0].size(), sz1 = v[1].size();
        if(sz0>1 && sz1) {
            if(f==1) {
                if(v[0][sz0-2] > v[1][sz1-1]) {
                    mx[i][1] = i - v[0][sz0-2];
                } else {
                    mx[i][1] = v[1][sz1-1] - i;
                }
            } else {
                if(v[0][sz0-2] < v[1][sz1-1]) {
                    mx[i][1] = v[0][sz0-2] - i;
                } else {
                    mx[i][1] = i - v[1][sz1-1];
                }
            }
        } else if(sz1) {
            mx[i][1] = cal(f, i, v[1].back());
        } else if(sz0>1) {
            mx[i][1] = cal(f, i, v[0][sz0-2]);
        }
        if(mx[i][1]<0 && mx[i][1]!=-999999999) mx[i][1]=-mx[i][1];
        if(mx[i][0]<0 && mx[i][0]!=-999999999) mx[i][0]=-mx[i][0];

        // for(int j = 0; j < 2; j++) {
        //     printf("mx[%d][%d]:%d\n", i, j, mx[i][j]);
        // }
        v[0].push_back(i);
        for(int i = int(tmp.size())-1; i >= 0; i--) {
            while(!v[1].empty() && a[v[1].back()] < tmp[i]) {
                v[1].pop_back();
            }
            v[1].push_back(tmp[i]);
        }
    }
}

ll sol2(int l0, int l1, int r0, int r1, int ex, int ex2) {
    if(l0==-1 && l1==-1 && r0==-1 && r1==-1) return 0;
    ll l = 0, r = 0;
    if(l1 != -999999999) l = l1-l0;
    else if(l0 != -999999999) l = ex-l0+1;
    if(r0 != -999999999) r = r0;
    else r = ex2+1;
    // printf("%lld * %lld\n", l, r);
    return l*r;
}

int main() {
    cin >> n;
    for(int i = 0; i < n; i++) {
        cin >> a[i];
    }
    sol(1, l_max);
    sol(-1, r_max);
    ll ans = 0;
    for(int i = 0; i < n; i++) {
        ll cnt = sol2(l_max[i][0], l_max[i][1], r_max[i][0], r_max[i][1], i, n-i-1);
        // printf("%d: %lld\n", i, cnt);
        cnt += sol2(r_max[i][0], r_max[i][1], l_max[i][0], l_max[i][1], n-i-1, i);
        // printf("%d: %lld\n", i, cnt);
        ans += 1LL*a[i]*cnt;
    }
    cout << ans << '\n';
    return 0;
}

