template <class T, std::size_t n>
T manhattan_distance(const std::array<T, n>& lhs, const std::array<T, n>& rhs)
{
    T res = 0;
    for (auto i : boost_irange(n)) {
        res += std::abs(lhs[i] - rhs[i]);
    }
    return res;
}

int main()
{
    input in;
    output out;
    int N = in.read<int>();
    StaticVector<int, 100000> P(in, N);

    long long res = 0;
    std::multiset<int> used({-1, -1, N, N});
    for (int x = N; x != 0; --x) {
        auto index = std::find(P.begin(), P.end(), x) - P.begin();
        auto it = used.insert(index);
        if (x != N) {
            auto l = std::prev(it);
            auto ll = std::prev(l);
            auto u = std::next(it);
            auto uu = std::next(u);
            // out << x, *ll, *l, index, *u, *uu;
            res += x * ((long long)(*l - *ll) * (*u - index) + (long long)(index - *l) * (*uu - *u));
        }
    }
    out << res;

    return 0;
}

