bool isPrime(ll n)//O(sqrt(n))
{
    if(n<2)
        return false;
    for(ll i=2;i*i<=n;i++)
        if(n%i==0)
            return false;
    return true;
}
std::vector<ll> factors(ll n)//O(sqrt(n))
{
    std::vector<ll> f;
    for(ll i=2;i*i<=n;i++)
    {
        while(n%i==0)
        {
            f.push_back(i);
            n = n/i;
        }
    }
    if(n>1) f.push_back(n);
    return f;
}
ll gcd(ll a,ll b)//O(logn)
{
    if(!b) return a;
    return gcd(b,a%b);
}
ll modpow(ll x,ll n,ll m)//O(logn)// used for calculating (x^n)%m
{
    if(n==0) return 1%m;
    ll u = modpow(x,n/2,m);
    u = (u%m * u%m)%m;
    if(n%2==1)
        u = (u%m * x%m)%m;
    return u%m;
}
ll eulerstotientfunction(ll n)//O(sqrt(n))
{
    ll ans = n;
    for(ll i=2;i*i<=n;i++)
    {
        if(n%i==0)
        {
            while(n%i==0)
                n = n/i;
            ans -= ans/i;
        }
    }
    if(n>1)
        ans -= ans/n;
    return ans;
}
ll modinverse(ll x,ll m)//O(logn)
{
    ll temp = eulerstotientfunction(m);
    return modpow(x,temp-1,m);
}
ll ncr(ll n,ll k)
{
    ll res = 1;
    k = min(k,n-k);
    for(ll i=0;i<k;i++)
    {
        res *= (n-i);
        res /= (i+1);
    }
    return res;
}
void construct(std::vector<pair<ll,ll> > &tree,std::vector<ll> &arr,ll start,ll end,ll pos)
{
    if(start==end)
    {
        tree[pos].fi = arr[start];
        tree[pos].se = arr[start];
        return;
    }
    ll mid = start+(end-start)/2;
    construct(tree,arr,start,mid,2*pos+1);
    construct(tree,arr,mid+1,end,2*pos+2);
    std::vector<ll> v;
    v.pb(tree[2*pos+1].fi);
    v.pb(tree[2*pos+1].se);
    v.pb(tree[2*pos+2].fi);
    v.pb(tree[2*pos+2].se);
    sort(v.rbegin(),v.rend());
    tree[mid].fi = v[0];
    tree[mid].se = v[1];
    return;
}
pair<ll,ll> query(std::vector<pair<ll,ll> > &seg_tree,ll qs,ll qe,ll si,ll ei,ll ci)
{
    if(qs<=si && qe>=ei)
        return seg_tree[ci];
    else if(qe<si||qs>ei)
        return {0,0};
    else
    {
        ll mid = si+(ei-si)/2;
        pair<ll,ll> a,b;
        a = query(seg_tree,qs,qe,si,mid,2*ci+1);
        b = query(seg_tree,qs,qe,mid+1,ei,2*ci+2);
        std::vector<ll> v;
        v.pb(seg_tree[2*ci+1].fi);
        v.pb(seg_tree[2*ci+1].se);
        v.pb(seg_tree[2*ci+2].fi);
        v.pb(seg_tree[2*ci+2].se);
        sort(v.rbegin(),v.rend());
        return make_pair(v[0],v[1]);
    }
}
