int leftmore(int v, int x, int l, int r, int cl, int cr) {
	if (t[v] <= x || cl >= r || cr <= l)
		return n;
	if (cl + 1 == cr)
		return cl;

	int m = (cl + cr) >> 1;
	if (cl >= l && cr <= r) {
		if (t[2 * v] > x)
			return leftmore(2 * v, x, l, r, cl, m);
		else
			return leftmore(2 * v + 1, x, l, r, m, cr);
	} else {
		int res1 = leftmore(2 * v, x, l, r, cl, m);
		if (res1 != n)
			return res1;
		return leftmore(2 * v + 1, x, l, r, m, cr);
	}
}


int rightmore(int v, int x, int l, int r, int cl, int cr) {
	if (t[v] <= x || cl >= r || cr <= l)
		return -1;
	if (cl + 1 == cr)
