	int m = (cl + cr) >> 1;
	if (cl >= l && cr <= r) {
		if (t[2 * v + 1] > x)
			return rightmore(2 * v + 1, x, l, r, m, cr);
		else
			return rightmore(2 * v, x, l, r, cl, m);
	} else {
		int res1 = rightmore(2 * v + 1, x, l, r, m, cr);
		if (res1 != -1)
			return res1;
		return rightmore(2 * v, x, l, r, cl, m);
	}
}


