  P mx, mx2;
  mx = seg.query(l,r);
  seg.update(mx.sc,P(-1,-1));
  mx2 = seg.query(l,r);
  seg.update(mx.sc,mx);
  int L = min(mx.sc,mx2.sc), R = max(mx.sc,mx2.sc);

  return mp[P(l,r)] = mx2.fs*(L-l+1)*(r-R) + dfs(l,R) + dfs(L+1,r) - dfs(L+1,R);
}

