typedef struct SegTree{
    int n = 1;
    vector<int> node;

    SegTree(int n_){
        while(n < n_) n *= 2;
        node.resize(n*2-1, 0);
    }

    void update(int i, int x){
        i += n-1;
        node[i] = x;
        while(i){
            i = (i-1)/2;
            node[i] = max(node[i*2+1], node[i*2+2]);
        }
    }

    int query(int a, int b, int i, int l, int r){
        if(r<=a || b<=l) return 0;
        if(a<=l && r<=b) return node[i];
        int vl = query(a, b, i*2+1, l, (l+r)/2);
        int vr = query(a, b, i*2+2, (l+r)/2, r);
        return max(vl, vr);
    }
}SegTree;

int fl(int i, int low, int high, int k, SegTree &st){
    if(st.query(high, i+1, 0, 0, st.n) > k) return high;
    while(high - low > 1){
        int mid = (high + low) / 2;
        if(st.query(mid, i+1, 0, 0, st.n) > k) low = mid;
        else high = mid;
    }
    return low;
}

int fr(int i, int low, int high, int k, SegTree &st){
    if(st.query(i, low+1, 0, 0, st.n) > k) return low;
    while(high - low > 1){
        int mid = (high + low) / 2;
        if(st.query(i, mid+1, 0, 0, st.n) > k) high = mid;
        else low = mid;
    }
    return high;
}

int main(){
    int n;
    scanf("%d", &n);
    SegTree st(n+2);
    st.update(0, n+1);
    st.update(n+1, n+1);
    int p[n+2];
    rep(i, n){
        scanf("%d", &p[i+1]);
        st.update(i+1, p[i+1]);
    }

    lint ans = 0;
    For(i, 1, n+1){
        int l1 = fl(i, 0, i, p[i], st);
        int l2 = fl(l1-1, 0, l1-1, p[i], st);
        int r1 = fr(i, i, n+1, p[i], st);
        int r2 = fr(r1+1, r1+1, n+1, p[i], st);
        ans += 1LL* p[i] * ((l1-l2)*(r1-i) + (r2-r1)*(i-l1));
    }

    printf("%lld\n", ans);
}

