};

bool operator>(const Pair& a, const Pair& b) {
	return a.v > b.v;
}

int main() {
	uint N;
	cin >> N;

	vector<Pair> P(N);
	for (uint i=0; i<N; i++) {
		cin >> P[i].v;
		P[i].i = i;
	}

	sort(P.begin(), P.end(), greater<Pair>());
	set<int> sd_l;
	set<int, greater<int>> sd_h;

	ull ans = 0;
	sd_l.insert(P[0].i);
	sd_h.insert(P[0].i);

	for (uint l=1; l<N; l++) {
		int V = P[l].v;
		int I = P[l].i;
		int nl1, nl2, nr1, nr2;

		auto l1 = sd_h.upper_bound(I);
		auto l2 = l1;
		if (l1 == sd_h.end()) {
		    nl1 = I + 1;
		    nl2 = 0;
		    //cout << "nf-l1 ";
		} else if (++l2 == sd_h.end()) {
		    nl1 = I - *l1;
		    nl2 = *l1 + 1;
		    //cout << "nf-l2 ";
		} else {
		    nl1 = I - *l1;
		    nl2 = *l1 - *l2;
		    //cout << "bf-l12 ";
		}

		auto r1 = sd_l.upper_bound(I);
		auto r2 = r1;
		if (r1 == sd_l.end()) {
		    nr1 = N - I;
		    nr2 = 0;
		    //cout << "nf-r1 ";
		} else if (++r2 == sd_l.end()) {
		    nr1 = *r1 - I;
		    nr2 = N - *r1;
		    //cout << "nf-r2 ";
		} else {
		    nr1 = *r1 - I;
		    nr2 = *r2 - *r1;
		    //cout << "bf-r12 ";
		}

		ull C = nr1 * nl2 + nr2 * nl1;
		//cout << "v" << V << " " << "i" << I << " " << nl2 << " " << nl1 << " " << nr1 << " " << nr2 << " " << "c" << C << endl;

		ans = ans + C * V;

		sd_h.insert(I);
		sd_l.insert(I);
	}

	cout << ans;

	return 0;
}

