template<typename T>
class BinaryIndexedTree{
    public:
        BinaryIndexedTree(int sz){
            data.assign(++sz, 0);
        }

        // [0, k]
        T sum(int k){
            T ret = 0;
            for(++k; k > 0; k -= k & -k) ret += data[k];
            return (ret);
        }

        void add(int k, T x){
            for(++k; k < data.size(); k += k & -k) data[k] += x;
        }

    private:
