vec P(100010),Left(100010),Right(100010);
ll left_binary(ll l,ll r,ll p){
    if(r-l==1) return l;
    ll m=(l+r)/2;
    if(P[m]<P[p]) return left_binary(l,m,p);
    else          return left_binary(m,r,p);
}
ll func_left(ll s){
    ll x=s-1-Left[s];
    if(P[x-1]>P[s]) return 1;

    return x-left_binary(x-1-Left[x],x-1,s);
}

ll right_binary(ll l,ll r,ll p){
    if(r-l==1) return r;
    ll m=(l+r)/2;
    if(P[m]<P[p]) return right_binary(m,r,p);
    else          return right_binary(l,m,p);
}
ll func_right(ll t){
    ll y=t+1+Right[t];
    if(P[y+1]>P[t]) return 1;

    return right_binary(y+1,y+1+Right[y],t)-y;
}

