    }
    for(int i=1;i<=N;i++){
        Left[i]=0;
        int j=i-1;
        while(P[j]<P[i]){
            Left[i]+=1+Left[j];
            j=j-Left[j]-1;
        }
    }
    for(int i=N;i>=1;i--){
        Right[i]=0;
        int k=i+1;
        while(P[k]<P[i]){
            Right[i]+=1+Right[k];
            k=k+Right[k]+1;
        }
    }

