            sum+=func_left(i)*((ll)1+Right[i]);
        }
        //右側
        if(Right[i]!=N-i){
            sum+=((ll)1+Left[i])*func_right(i);
        }
        ans+=sum*P[i];
    }
    cout<<ans<<endl;
    return 0;
}

