stack <int> s;
set <pair <int, int>> q;

void func_stack(int i, vector <pair <int, int>>& dir) {
    while (!s.empty() && a[s.top()] < a[i]) {
        int idx = s.top();
        dir[idx].first = i;
        s.pop();
        q.insert({a[idx], idx});
    }
    s.push(i);
}

void func_set(int i, vector <pair <int, int>>& dir) {
    while (!q.empty() && q.begin()->first < a[i]) {
        int idx = q.begin()->second;
        dir[idx].second = i;
        q.erase(q.begin());
    }
}

