#define FORINV(var, min, max) for (ui var = (max) - 1; var + 1 > (min); --var)

using namespace std;

using ui = unsigned int;
using uc = unsigned char;

const static ui NMAX = 100000;
static ui N;
static ui Pi[NMAX + 1];
static ui Pi_inv[NMAX + 1];

ui solve(void) {
  ui res = 0;
  multiset<ui> all;

  all.insert(0);
  all.insert(0);
  all.insert(N + 1);
  all.insert(N + 1);

  FORINV(i, 0, N) {
    ui idx = Pi_inv[i + 1] + 1;
    auto it = all.lower_bound(idx);
    ui xi = *prev(it, 1);
    ui wi = *prev(it, 2);

    ui yi = *it;
    ui zi = *next(it);

    auto Ci = (xi - wi) * (yi - idx) + (idx - xi) * (zi - yi);
    res += (i + 1) * Ci;
    all.insert(idx);
  }

  return res;
}

