//!   88888888b                              oo          dP        !//
//!   88                                                 88        !//
//!  a88aaaa    .d8888b. 88d888b. dP  dP  dP dP .d8888b. 88  .dP   !//
//!   88        88ooood8 88'  '88 88  88  88 88 88'  '"" 88888"    !//
//!   88        88.  ... 88    88 88.88b.88' 88 88.  ... 88  '8b.  !//
//!   dP        '88888P' dP    dP 8888P Y8P  dP '88888P' dP   'YP  !//
//!================================================================!//
template <typename T = ll>
class Fenwick
{
public:
    Fenwick(const std::size_t N, const T initial = T{}) : size(N), cap(ceil2(size)), value(cap + 1, 0)
    {
        if (initial != T{}) {
            std::fill(value.begin() + 1, value.end(), initial);
            for (std::size_t x = 1; x < cap; x++) { value[x + (x & -x)] += value[x]; }
        }
    }
    template <typename InIt>
    Fenwick(const InIt first, const InIt last) : size(std::distance(first, last)), cap(ceil2(size)), value(cap + 1, 0)
    {
        std::copy(first, last, value.begin() + 1);
        for (std::size_t x = 1; x < cap; x++) { value[x + (x & -x)] += value[x]; }
    }
    void add(const std::size_t a, const T& val)
    {
        assert(a < size);
        for (std::size_t ind = a + 1; ind <= cap; ind += ind & (-ind)) { value[ind] += val; }
    }
    T sum(const std::size_t a) const
    {
        assert(a <= size);
        T sum{};
        for (std::size_t ind = a; ind != 0; ind &= ind - 1) { sum += value[ind]; }
        return sum;
    }
    T sum(const std::size_t l, const std::size_t r) const { return assert(l < r), assert(r <= size), sum(r) - sum(l); }
    std::size_t partitionPoint(const T val) const
    {
        if (val < 0) { return 0; }
        std::size_t x = 0;
        T offset = 0;
        for (std::size_t k = ((cap == size) ? cap : cap / 2); k != 0; k >>= 1) {
            if (x + k <= cap and value[x + k] + offset <= val) { offset += value[x + k], x += k; }
        }
        return std::min(x, size);
    }
    friend std::ostream& operator<<(std::ostream& os, const Fenwick& fw)
    {
        os << "[";
        for (std::size_t i = 0; i < fw.size; i++) { os << fw.sum(i, i + 1) << (i + 1 == fw.size ? "" : ","); }
        return (os << "]\n");
    }

private:
    const std::size_t size, cap;
    std::vector<T> value;
};
