int main()
{
    const int n  = read<int>();
    const auto p = readVec<int>(n);
    std::vector<int> ind(n);
    std::iota(ind.begin(), ind.end(), 0);
    std::sort(ind.begin(), ind.end(), [&](const int i, const int j) { return p[i] > p[j]; });
    ll ans = 0;
    Fenwick<int> bit(n);
    for (const int i : ind) {
        const int v = p[i];
        int l1      = -1;
        for (int r1 = i + 1; r1 - l1 > 1;) {
            const int m1                        = (l1 + r1) / 2;
            (bit.sum(m1, i + 1) == 0 ? r1 : l1) = m1;
        }
        int l2 = -1;
        for (int r2 = i + 1; r2 - l2 > 1;) {
            const int m2                        = (l2 + r2) / 2;
            (bit.sum(m2, i + 1) <= 1 ? r2 : l2) = m2;
        }
        int r1 = n + 1;
        for (int l1 = i; r1 - l1 > 1;) {
            const int m1                    = (l1 + r1) / 2;
            (bit.sum(i, m1) == 0 ? l1 : r1) = m1;
        }
        int r2 = n + 1;
        for (int l2 = i; r2 - l2 > 1;) {
            const int m2                    = (l2 + r2) / 2;
            (bit.sum(i, m2) <= 1 ? l2 : r2) = m2;
        }
        bit.add(i, 1);
        r1--, r2--;
        const int num = (l1 - l2) * (r1 - i) + (r2 - r1) * (i - l1);
        ans += (ll)v * num;
    }
    std::cout << ans << std::endl;

    return 0;
}

