void read_int_unlocked(int * out)
{
	static int c;
	*out = 0;
	c = getchar_unlocked();
	for (; '0' <= c && c <= '9'; c = getchar_unlocked())
		*out = (*out) * 10 + c - '0';
}

int main()
{
	read_int_unlocked(&n);
	vec = new int[n];
	int * start = vec;
	int * end = vec + n;
	for (int * i = start; i < end; i++)
		read_int_unlocked(i);

	per = new int[n];
	for (int * i = start; i < start + n; i++)
		*(per + (*i) - 1) = i - vec;

	r = new ll[n];
	for (auto i = r; i < r + n; i++)
		*i = 0;
	l = new ll[n];
	for (auto i = l; i < l + n; i++)
		*i = 0;

	int vsp;
	for (auto i = per; i < per + n - 1; i++)
	{
		vsp = *i;
		if ((vsp - l[vsp]) == 0)
		{
			ans += vec[vsp] * ((r[(vsp + r[vsp] + 1)] + 1) * (1 + l[vsp]));
			l[(vsp + r[vsp] + 1)] = (vsp + r[vsp] + 1);
		}
		else if ((vsp + r[vsp] + 1) == n)
		{
			ans += vec[vsp] * ((l[(vsp - l[vsp] - 1)] + 1) * (1 + r[vsp]));
			r[(vsp - l[vsp] - 1)] = n - (vsp - l[vsp]);
		}
		else
		{
			ans += vec[vsp] * ((l[vsp] + 1) * (r[(vsp + r[vsp] + 1)] + 1) + (r[vsp] + 1) * (l[(vsp - l[vsp] - 1)] + 1));
			r[(vsp - l[vsp] - 1)] = l[(vsp + r[vsp] + 1)] = r[vsp] + l[vsp] + 1;
		}
	}
	printf("%llu", ans);
	return 0;
}

