void solve() {
	int n; cin >> n;
	int p[100000]; rep(i, n) cin >> p[i];
	int rp[100001]; rep(i, n) rp[p[i]] = i;

	multiset<int> trash;
	trash.insert(-1); trash.insert(-1);
	trash.insert(n); trash.insert(n);

	long long ans = 0;
	for (int i = n; i > 0; i--) {
		int pp = rp[i];
		auto lb = trash.lower_bound(pp);
		int l1, l2, g1, g2;
		g2 = *(++lb);
		g1 = *(--lb);
		l1 = *(--lb);
		l2 = *(--lb);

		long long t = 0;
		t += (g2 - g1) * (pp - l1);
		t += (l1 - l2) * (g1 - pp);
		ans += t * i;

		trash.insert(pp);
	}

	cout << ans << endl;
}

