typedef long long int ll;
const int size=1e5+5;
typedef pair<int,int> pi;
int n;
void update(int x,int h[])
{
    for(int i=x;i<size;i += i & -i)
        h[i] = max(h[i],x);
}
int query(int x,int h[])
{
    int res = 0;
    for(int i=x;i>0;i -= i & -i)
        res = max(res,h[i]);
    return res;
}
int cal_left(int x,int h[])
{
    int i = query(x,h);
    return i;
}
int cal_right(int x,int h[])
{
    x = n-x+1;
    if(x < 0)
        return n+1;
    int i = query(x,h);
    return n+1-i;
}
