		return l.p > r.p;
	};
};

class Comp2 {
public:
	bool operator() ( const pinfo &l, const pinfo &r ){
		return l.p > r.p;
	};
};

int pos[200005];

int next1[200005]; // pos -> next pos
int next2[200005]; // pos -> next next pos
int last1[200005];
int last2[200005];

int main(){
	cin >> N;
	vector<int> P(N);
	for ( int i = 0;i  < N; i++ ){
		cin >> P[i];
		pos[P[i]] = i;
	}

	for ( int i = 0; i < N; i++ ){
		next1[i] = next2[i] = N;
		last1[i] = last2[i] = -1;
	}

	// 全てのiについて、「次にP[i]以上の値がある位置」「次の次にP[i]以上の値がある位置」を調べる
	{
		priority_queue<pinfo,vector<pinfo>,Comp1> q1, q2;
		for ( int i = 0; i < N; i++ ){
			while ( !q2.empty() && q2.top().p < P[i] ){
				pinfo p = q2.top();
				q2.pop();
				next2[p.pos] = i;
			}

			while ( !q1.empty() && q1.top().p < P[i] ){
				pinfo p = q1.top();
				q1.pop();
				q2.push(p);
				next1[p.pos] = i;
			}

			q1.push({P[i],i});
		}
	}

	// 逆方向も調べる
	{
		priority_queue<pinfo,vector<pinfo>,Comp2> q1, q2;
		for ( int i = N-1; i >= 0; i-- ){
			while ( !q2.empty() && q2.top().p < P[i] ){
				pinfo p = q2.top();
				q2.pop();
				last2[p.pos] = i;
			}

			while ( !q1.empty() && q1.top().p < P[i] ){
				pinfo p = q1.top();
				q1.pop();
				q2.push(p);
				last1[p.pos] = i;
			}

			q1.push({P[i],i});
		}
	}




	//for ( int i = 0; i < N; i++ )		cout << last2[i] << " ";
	//cout << endl;
	//for ( int i = 0; i < N; i++ )		cout << last1[i] << " ";
