	//for ( int i = 0; i < N; i++ )		cout << i << " ";
	//cout << endl;
	//for ( int i = 0; i < N; i++ )		cout << next1[i] << " ";
	//cout << endl;
	//for ( int i = 0; i < N; i++ )		cout << next2[i] << " ";
	//cout << endl;

	ll sum = 0;
	for ( int i = 0; i < N; i++ ){
		sum += P[i] * ( 
			(ll)(next2[i]-next1[i]) * (i-last1[i]) +  // iより後方でP[i]が2番目になる(L,R)の個数
			(ll)(last1[i]-last2[i]) * (next1[i]-i)    // iより前方でP[i]が2番目になる(L,R)の個数
		);
	}


	cout << sum << endl;


	return 0;
}

