void FindPQ(set<int> &st, int x, int &p, int &q) {
  auto it = st.find(x);
  if (it == st.begin()) return;
  --it;
  q = *it;
  if (it == st.begin()) return;
  --it;
  p = *it;
}

void FindRS(set<int> &st, int x, int &r, int &s) {
  auto it = st.find(x);
  ++it;
  if (it == st.end()) return;
  r = *it;
  ++it;
  if (it == st.end()) return;
  s = *it;
}

