#define FENWICK_NMAX 200010
struct fenwick_tree{
    ll N;
    ll bit[FENWICK_NMAX];
    fenwick_tree(ll n){
        N = n;
        for(ll x = 1; x <= N; x++){
            bit[x] = 0;
        }
    }
    void add(ll a, ll w){
        for(ll x = a; x <= N; x += x & -x){
            bit[x] += w;
        }
    }
    ll sum(ll a){
        ll ret = 0;
        for(ll x = a; x > 0; x -= x & -x){
            ret += bit[x];
        }
        return ret;
    }
};

int main(){
    // cerr << guchokudai() << endl;

    // input
    ll n;
    cin >> n;
    vector<ll> p(n);
    rep(i, 0, n) cin >> p[i];

    // accumulate ans
    ll ans = 0;
    auto left_search = [&](ll cur) {
        ll i = cur - 1;
        ll zero = 0;
        ll one = 0;
        while(i >= 0 && p[i] < p[cur]) i--;
        zero = (cur-1) - i;
        if(i < 0) return make_pair(zero, one);
        ll rec = i;
        i--;
        while(i >= 0 && p[i] < p[cur]) i--;
        one = rec - i;
        return make_pair(zero, one);
    };
    auto right_search = [&](ll cur) {
        ll i = cur + 1;
        ll zero = 0;
        ll one = 0;
        while(i < n && p[i] < p[cur]) i++;
        zero = i - (cur+1);
        if(i >= n) return make_pair(zero, one);
        ll rec = i;
        i++;
        while(i < n && p[i] < p[cur]) i++;
        one = i - rec;
        return make_pair(zero, one);
    };
    rep(i, 0, n) {
        auto l = left_search(i);
        auto r = right_search(i);
        // cerr << i << ": " << l.first << " " << l.second << " " << r.first  << " " << r.second << endl;
        ans += p[i] * ((l.first + 1) * r.second + l.second * (r.first + 1));
    }

    // print
    cout << ans << endl;

    return 0;
}

