				l = P.at(L);
				sl = P.at(L+1);
			}

			for (int i = L; i <= R; i++) {
				if (P.at(i) > l) {
					sl = l;
					l = P.at(i);
				} else if (P.at(i) > sl && P.at(i) < l) {
					sl = P.at(i);
				}
			}

			sum += sl;
		}
	}

	cout << sum << endl;
	return 0;
}

