#include <bits/stdc++.h>
using namespace std;
using lint = long long;
template<class T = int> using V = vector<T>;
template<class T = int> using VV = V< V<T> >;

struct DisjointSparseTable {
  using T = int;
  static T op(const T& x, const T& y) { return max(x, y); }

  const int n;
  VV<T> t;
  template<class Itr> DisjointSparseTable(Itr first, Itr last) :
    n(distance(first, last)), t(__lg(n) + 1, V<T>(first, last)) {
    for (int k = 1; k < (int) t.size(); ++k) {
      for (int i0 = 1 << k; i0 < n; i0 += 1 << k + 1) {
        for (int i = i0 + 1; i < min(i0 + (1 << k), n); ++i) {
          t[k][i] = op(t[k][i - 1], t[k][i]);
        }
        for (int i = i0 - 2; i >= i0 - (1 << k); --i) {
          t[k][i] = op(t[k][i], t[k][i + 1]);
        }
      }
    }
  }
  T acc(int l, int r) const {
    assert(l < r);
    if (l == --r) return t[0][l];
    int k = __lg(l ^ r);
    return op(t[k][l], t[k][r]);
  }
};

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);
  int n; cin >> n;
  V<> p(n + 2, n + 1);
  for (int i = 1; i <= n; ++i) cin >> p[i];
  DisjointSparseTable dst(begin(p), end(p));

  auto fl = [&](int i, int x) -> int {
    int ng = -1, ok = i - 1;
    while (ok - ng > 1) {
      int mid = ng + ok >> 1;
      (dst.acc(mid + 1, i) <= x ? ok : ng) = mid;
    }
    return ok;
  };
  auto fr = [&](int i, int x) -> int {
    int ok = i + 1, ng = n + 2;
    while (ng - ok > 1) {
      int mid = ok + ng >> 1;
      (dst.acc(i + 1, mid) <= x ? ok : ng) = mid;
    }
    return ok;
  };

  lint res = 0;
  for (int i = 1; i <= n; ++i) {
    lint l = fl(i, p[i]);
    lint r = fr(i, p[i]);
    if (l) {
      lint ll = fl(l, p[i]);
      res += (l - ll) * (r - i) * p[i];
    }
    if (r <= n) {
      lint rr = fr(r, p[i]);
      res += (i - l) * (rr - r) * p[i];
    }
  }
  cout << res << '\n';
}

