        int64_t l2 = bit.lower_bound(s-2);
        int64_t l1 = bit.lower_bound(s-1);
        int64_t r1 = bit.lower_bound(s+1);
        int64_t r2 = bit.lower_bound(s+2);
        ans += i * ((l1-l2)*(r1-pos[i]) + (pos[i]-l1)*(r2-r1));

    }
    cout << ans << endl;
    return 0;
}

