using namespace std;
const int N = 1e5 + 10;
int Smin[4 * N] , Smax[4 * N] , a[N] , L[N] , R[N] , LL[N] , RR[N] , INF; 
long long res = 0; 
void upd_min(int l , int r , int x , int v , int node){
	if(l > x || r < x) return;
	if(l == r && x == l){
		Smin[node] = v; 
	}
	else{
		int m = (l + r) >> 1;
		upd_min(l , m , x , v , lnode); ++ m;
		upd_min(m , r , x , v , rnode);
		Smin[node] = min(Smin[lnode] , Smin[rnode]);
	}
}
void upd_max(int l , int r , int x , int v , int node){
	if(l > x || r < x) return;
	if(l == r && x == l){
		Smax[node] = v;
	}
	else{
		int m = (l + r) >> 1;
		upd_max(l , m , x , v , lnode); ++ m;
		upd_max(m , r , x , v , rnode);
		Smax[node] = max(Smax[lnode] , Smax[rnode]);
	}
}
int query_min(int l , int r , int L , int R , int node){
	if(l > r || L > R || l > R || L > r) return INF;
	if(L <= l && R >= r)return Smin[node];
	int m = (l + r) >> 1;
	return min(query_min(l , m , L , R , lnode) ,  query_min(m + 1 , r , L , R , rnode));
}
int query_max(int l , int r , int L , int R , int node){
	if(l > r || L > R || l > R || L > r) return 0;
	if(L <= l && R >= r)return Smax[node];
	int m = (l + r) >> 1;
	return max(query_max(l , m , L , R , lnode) , query_max(m + 1 , r , L , R , rnode));  
}
main(){
	int n;
	cin >> n; INF = n + 1;
	for(int i = 1; i <= n; i ++) cin >> a[i];
	for(int i = 1; i <= n; i ++){
		L[i] = query_max(1 , n , a[i] + 1 , n , 1);
		upd_max(1 , n , a[i] , i , 1);
	}
	for(int i = 0; i <= 4 * n; i ++) Smin[i] = INF;
	for(int i = n; i >= 1; i --){
		R[i] = query_min(1 , n , a[i] + 1 , n , 1);
		upd_min(1 , n , a[i] , i , 1); 
	}
	for(int i = 0; i <= 4 * n; i ++) Smin[i] = INF , Smax[i] = 0;
	for(int i = 1; i <= n; i ++){
		int m = L[i];
		if(m) m = a[m] , LL[i] = max(query_max(1 , n , a[i] + 1 , m - 1 , 1) , query_max(1 , n , m + 1 , n , 1));
		upd_max(1 , n , a[i] , i , 1); 
	}
	for(int i = n; i >= 1; i --){
		int m = R[i];
		RR[i] = n + 1; 
		if(m != n + 1)m = a[m] ,
		RR[i] = min(query_min(1 , n , a[i] + 1 , m - 1 , 1) , query_min(1 , n , m + 1 , n , 1));
		upd_min(1 , n , a[i] , i , 1);
	}
	for(int i = 1; i <= n; i ++){
		int l , r;
		if(L[i]) l = LL[i] + 1 , r = R[i] - 1 , res += (L[i] - l + 1) * (r - i + 1) * a[i];
		if(R[i] <= n) l = L[i] + 1 , r = RR[i] - 1 , res += (r - R[i] + 1) * (i - l + 1) * a[i];
	}
	cout << res << "\n";
}

