  vector<ll> P(N);
  rep (i, N) {
    cin >> P[i];
  }

  vector<ll> idx = argsort(P);

  ll ans = 0;
  set<ll> hist;
  each (i, idx) {
    hist.insert(i);
    if (hist.size() == 1) continue;

    auto it = hist.find(i);
    if (it != hist.begin()) {
      ll p1, p2, n1;
      if (prev(it, 1) != hist.begin()) {
        p1 = *prev(it, 1);
        p2 = *prev(it, 2);
      } else {
        p1 = *prev(it, 1);
        p2 = -1;
      }

      if (it != prev(hist.end())) {
        n1 = *next(it, 1);
      } else {
        n1 = N;
      }
      ans += (n1 - i) * (p1 - p2) * P[i];
    }
    if (it != prev(hist.end())) {
      ll n1, n2, p1;
      if (next(it, 1) != prev(hist.end())) {
        n1 = *next(it, 1);
        n2 = *next(it, 2);
      } else {
        n1 = *next(it, 1);
        n2 = N;
      }

      if (it != hist.begin()) {
        p1 = *prev(it, 1);
      } else {
        p1 = -1;
      }
      ans += (i - p1) * (n2 - n1) * P[i];
    }
  }
  cout << ans << "\n";
}

