int n;
int te[man*4];

void pushup(int rt){
    te[rt] = max(te[rt<<1] , te[rt<<1|1]);
}

void build(int l,int r,int rt){
    if(l==r){
        te[rt] = x[l]; 
        return;
    }
    int m = l+r>>1;
    build(l,m,rt<<1);
    build(m+1,r,rt<<1|1);
    pushup(rt);
}

int query(int l,int r,int L,int R,int rt){
    if(L<=l&&R>=r){
        return te[rt];
    }
    int ans = -1;
    int m = l+r>>1;
    if(L<=m)ans = max(ans,query(l,m,L,R,rt<<1));
    if(R>m)ans = max(ans,query(m+1,r,L,R,rt<<1|1));
    return ans;
    //pushup(rt);
}

void solve1(int id){
    int l = 1,r = id;
    int ans = 0;
    while(l<=r){
        int mid = l+r>>1;
        if(query(1,n,mid,id,1)>x[id]){
            ans = mid;
            l = mid + 1;
        }else r = mid - 1;
    }
    lef[id][0] = ans;
    if(ans==0){
        lef[id][1] = 0;
        return;
    }
    l = 1,r = ans-1;
    int tp = ans-1;
    ans = 0;
    while(l<=r){
        int mid = l+r>>1;
        if(query(1,n,mid,tp,1)>x[id]){
            ans = mid;
            l = mid + 1;
        }else r = mid - 1;
    } 
    lef[id][1] = ans;
}

void solve2(int id){
    int l = id,r = n;
    int ans = n+1;
    while(l<=r){
        int mid = l+r>>1;
        if(query(1,n,id,mid,1)>x[id]){
            ans = mid;
            r = mid - 1;
        }else l = mid + 1;
    }
    rig[id][0] = ans;
    if(ans==n+1){
        rig[id][1] = ans;
        return;
    }
    l = ans + 1,r = n;
    int tp = ans + 1;
    ans = n+1;
    while(l<=r){
        int mid = l+r>>1;
        if(query(1,n,tp,mid,1)>x[id]){
            ans = mid;
            r = mid - 1;
        }else l = mid + 1;
    }
    rig[id][1] = ans;
}

