const int maxn = 1e5 + 5;
const int inf = 1e9;
int n;
int v[maxn];
int a1[maxn], a2[maxn], b1[maxn], b2[maxn];
struct segment{
	int l, r;
	int val;
} arr[maxn << 2];
long long ans = 0;
void debug(){
	for(int i=1;i<=2*n;i++) printf("%d %d %d %d\n",i,arr[i].l,arr[i].r,arr[i].val);
	printf("\n"); 
}
int build(int pos, int l, int r){
	if(l == r){
		arr[pos].val = v[l];
		arr[pos].l = arr[pos].r = r;
		return arr[pos].val;
	}
	int mid = (l + r) >> 1;
	arr[pos].l = l, arr[pos].r = r;
	arr[pos].val = std::max(build(2*pos,l,mid), build(2*pos+1,mid+1,r));
	return arr[pos].val;
}

int query(int pos, int l, int r){
	if(l > r) return 0;
	int lseg = arr[pos].l, rseg = arr[pos].r;
	if(lseg > r || rseg < l) return 0;
	if(lseg >= l && rseg <= r) return arr[pos].val;
	else return std::max(query(2*pos,l,r),query(2*pos+1,l,r));
}

int solve1(int val, int l, int r){
	if(l == r) return l;
	int mid = (l + r) >> 1;
	if(query(1,l,mid) > val) return solve1(val,l,mid);
	else return solve1(val,mid+1,r);
}

int solve2(int val, int l, int r){
	if(l == r) return l;
	int mid = (l + r) >> 1;
	if(query(1,mid+1,r) > val) return solve2(val,mid+1,r);
	else return solve2(val,l,mid);
}

int main(){
	scanf("%d",&n);
	for(int i=1;i<=n;i++) scanf("%d",&v[i]);
	build(1,1,n);
	//debug();
	for(int i=1;i<=n;i++){
		if(query(1,1,i-1) > v[i]){
			a1[i] = solve2(v[i],1,i-1);
			if(query(1,1,a1[i]-1) > v[i]) a2[i] = solve2(v[i],1,a1[i]-1);
			else a2[i] = 0;
		} 
		else a1[i] = a2[i] = 0;
		if(query(1,i+1,n) > v[i]){
			b1[i] = solve1(v[i],i+1,n);
			if(query(1,b1[i]+1,n) > v[i]) b2[i] = solve1(v[i],b1[i]+1,n);
			else b2[i] = n+1;
		}
		else b1[i] = b2[i] = n+1;
	}
	//for(int i=1;i<=n;i++) printf("%d %d %d %d\n",a1[i],a2[i], b1[i], b2[i]);
	for(int i=1;i<=n;i++){
		if(a1[i] > 0) ans += (long long) v[i] * (a1[i] - a2[i]) * (b1[i] - i);
		if(b1[i] <= n) ans += (long long) v[i] * (b2[i] - b1[i]) * (i - a1[i]);
	}
	printf("%d",ans);
	return 0;
}

