int cnt(vector<int>& p, unordered_set<long long>& set, int s, int e) {
	if (e <= s) {
		return 0;
	}

	int first = 0, second = 0;
	for (int i = s;i <= e;i++) {
		if (p[i] > p[first]) {
			second = first;
			first = i;
		}
		else if (p[i] > p[second]) {
			second = i;
		}
		else {

		}
	}
	assert(first != 0 && second != 0);
	if (second < first) {
		swap(second, first);
	}
	if (set.count(((long long)first)*1000000L+ ((long long)second)) != 0) {
		return 0;
	}

	set.insert(((long long)first) * 1000000L + ((long long)second));
	return (first - s + 1) * (e - second + 1)*min(p[first],p[second]) + cnt(p,set, s, second-1) + cnt(p,set, first+1 , e);

}

