struct segt {
    #define type long long
    #define lc x << 1
    #define rc x << 1 | 1
    #define L t[x].l
    #define R t[x].r
    #define mid ((L + R) >> 1)

    struct seg {
        int l, r;
        type sum, mx, mn, lz;
        void update(type val) {
            sum += val * (r - l + 1);
            mx += val;
            mn += val;
            lz += val;
        }
    };

    type * a = nullptr;
    seg t[N << 2];
    bool init;
    type sum, mx, mn;

    inline void modify(type * arr) {a = arr;}
    inline void push_up(int x) {
        t[x].sum = t[lc].sum + t[rc].sum;
        t[x].mn = min(t[lc].mn, t[rc].mn);
        t[x].mx = max(t[lc].mx, t[rc].mx);
    }
    inline void push_down(int x) {
        t[lc].update(t[x].lz);
        t[rc].update(t[x].lz);
        t[x].lz = 0;
    }
    void build(int l, int r, int x = 1) {
        t[x] = seg{l, r, 0, 0, 0, 0};
        if (l == r) {
            if(a != nullptr)
                t[x].update(a[l]);
            return;
        }
        build(l, mid, lc);
        build(mid + 1, r, rc);
        push_up(x);
    }
    void update(int l, int r, type val, int x = 1) {
        if (l <= L and R <= r) {
            t[x].update(val);
            return;
        }
        push_down(x);
        if (l <= mid) update(l, r, val, lc);
        if (r > mid) update(l, r, val, rc);
        push_up(x);
    }
    void set(int p, type val, int x = 1) {
        if (L == R) {
            t[x].update(val - t[x].sum);
            return;
        }
        push_down(x);
        set(p, val, p <= mid ? lc : rc);
        push_up(x);
    }
    void query(int l, int r, int x = 1) {
        if (l <= L and R <= r) {
            if (not init) {
                sum = t[x].sum;
                mx = t[x].mx;
                mn = t[x].mn;
                init = 1;
            }
            else {
                sum += t[x].sum;
                if (t[x].mx > mx) mx = t[x].mx;
                if (t[x].mn < mn) mn = t[x].mn;
            }
            return;
        }
        push_down(x);
        if (l <= mid) query(l, r, lc);
        if (r > mid) query(l, r, rc);
    }
    tuple<type, type, type> get_info(int l, int r) {
        init = 0;
        query(l, r);
        return make_tuple(sum, mx, mn);
    }

    #undef type
    #undef lc
    #undef rc
    #undef L
    #undef R
    #undef mid
};

