//Ci:=最大値がiになる区間の個数
//求めるべき値はΣCi*i
//例えば2 1 5 7 3 4 6ならC7は16
//次に考えるべきは2 1 5と3 4 6の二つの区間。7をまたぐと最大値は7に変わるので考える必要がない
//abababaaaa←(x)baabaa a<=x b>x
//2番目に大きいという条件はbをちょうど一つ含む、ということ

int main() {
	int N; cin >> N;
	vector<int>a(N);
	REP(i, N)cin >> a[i];
	REP(i, N)a[i]--;
	vector<int>idx(N);
	REP(i, N)idx[a[i]] = i;
	set<int>s;
	ll ans = 0;
	for (int x = N - 1; x >= 0; --x) {
		int i = idx[x];
		ll c = 0;
		{//calc c
			s.insert(i);
			vector<int>l(2,-1);
			vector<int>r(2,N);
			{// calc l
				auto it = s.find(i);
				REP(j, 2) {
					if (it == s.begin())break;
					--it;
					l[j] = *it;
				}
			}
			{// calc r
				auto it = s.find(i);
				REP(j, 2) {
					++it;
					if (it == s.end())break;
					r[j] = *it;
				}
			}
			vector<int>ls(2);
			ls[0] = i-l[0];
			ls[1] = l[0] - l[1];
			vector<int>rs(2);
			rs[0] = r[0] - i;
			rs[1] = r[1] - r[0];
			c = (ll)ls[0] * rs[1] + (ll)ls[1] * rs[0];
		}
		ans += c * (x + 1);
	}
	cout << ans << endl;
	return 0;
}

