using ll = long long;
int main()
{
	ll N;
	cin >> N;

	vector<ll> P(N);
	priority_queue<pair<int, int>> pq;
	rep(i, N) {
		cin >> P[i];
		pq.push({ P[i],i });
	}

	ll res = 0;
	set<ll> st;
	st.insert(-1); // bannhei
	st.insert(N);  // bannhei
	while (!pq.empty()) {
		ll num, idx;
		tie(num, idx) = pq.top(); pq.pop();

		auto itr_right = st.lower_bound(idx);
		ll right = *itr_right;
		itr_right++;
		ll right_after = itr_right == st.end() ? N : *itr_right;

		auto itr_left = st.lower_bound(idx);
		itr_left--;
		ll left = *itr_left;
		ll left_before = (itr_left == st.begin() ? -1 : *(--itr_left));

		ll right_contain_kind = (right_after - right)*(idx - left);
		ll left_contain_klnd = (left - left_before)*(right - idx);
		ll kind = left_contain_klnd + right_contain_kind;
		ll now_res = num * kind;
		res += now_res;
		st.insert(idx);
	}
	cout << res << endl;
	return 0;
}

