      pq.pop();
    }
    while (!s.empty() && a[i] > a[s.top()]) {
      r[s.top()] = i;
      pq.emplace(a[s.top()], s.top());
      s.pop();
    }
    s.push(i);
  }
  while (!s.empty()) s.pop();
  while (!pq.empty()) pq.pop();
  for (int i = n - 1; i >= 0; i--) {
    while (!pq.empty() && a[i] > pq.top().first) {
      l1[pq.top().second] = i;
      pq.pop();
