int n,arr_siz;

int ansLeft(int L, int R, int K){
    if(R<L) return arr_siz+1;

    int node = R+n-1;

    while(Tree[node]<K){
        while((node&1)==0){
                node>>=1;
            if(node<=1) return -1;
        }
        node--;
    }

    while(node<n){
        node = (node<<1)|1;
        if(Tree[node]<K) node--;
    }

    int index = node - (n-1);

    return (index>=L ?index : -1);
}

int ansRight(int L, int R, int K){
    if(R<L) return -1;

    int node = L+n-1;

    while(Tree[node]<K){
        while((node&1)==1){
                node>>=1;
            if(node<=1) return -1;
        }
        node++;
    }

    while(node<n){
        node = (node<<1);
        if(Tree[node]<K) node++;
    }

    int index = node - (n-1);

    return (index<=R ? index : -1);
}



