template<class Type>
Type solve(Type res = Type()){
    int N; cin >> N;

    vector<pll> P(N);
    for(int i = 0; i < N;i++){
        cin >> P[i].first;
        P[i].second = i+1;
    }
    sort(P.rbegin(),P.rend());
    set<ll> S;
    S.insert(0); S.insert(N+1);
    S.insert(P.front().second); P.erase(P.begin());

    for(auto p:P){
        ll v,id; tie(v,id) = p;

        auto it = S.lower_bound(id);
        ll x1,x2,x3,x4;

        x3 = *it;
        {
            it++;
            if(it == S.end()){
                x4 = x3;
            }else{
                x4 = *it;
            }
            it--;
            it--;
        }
        x2 = *it;
        {
            if(it == S.begin()){
                x1 = x2;
            }else{
                it--;
                x1 = *it;
            }
        }
        res += v * ((x2 - x1) * (x3 - id) + (id - x2) * (x4 - x3));
        S.insert(id);
    }

    return res;
}
