vector<ll> uppper_indices(ll idx) {
  vector<ll> res;
  auto ite = st.lower_bound(idx);
  if (ite == st.end()) return res;
  res.push_back(*ite);
  if (++ite == st.end()) return res;
  res.push_back(*ite);
  return res;
}

vector<ll> lower_indices(ll idx) {
  vector<ll> res;
  auto ite = st.lower_bound(idx);
  if (ite == st.begin()) return res;
  res.push_back(*(--ite));
  if (ite == st.begin()) return res;
  res.push_back(*(--ite));
  return res;
}

ll calcNumOfInterval(vector<ll>& up, vector<ll>& low, ll idx) {
  ll res = 0;
  if (len(low) == 0 && len(up) == 0) res = 0;
  if (len(low) == 0 && len(up) == 1) res = (idx+1) * (N-up[0]);
  if (len(low) == 0 && len(up) == 2) res = (idx+1) * (up[1]-up[0]);
  if (len(low) == 1 && len(up) == 0) res = (low[0]+1) * (N-idx);
  if (len(low) == 1 && len(up) == 1) {
    res = (low[0]+1) * (up[0]-idx) + (idx-low[0]) * (N-up[0]);
  }
  if (len(low) == 1 && len(up) == 2) {
    res = (low[0]+1) * (up[0]-idx) + (idx-low[0]) * (up[1]-up[0]);
  }
  if (len(low) == 2 && len(up) == 0) res = (low[0]-low[1]) * (N-idx);
  if (len(low) == 2 && len(up) == 1) {
    res = (low[0]-low[1]) * (up[0]-idx) + (idx-low[0]) * (N-up[0]);
  }
  if (len(low) == 2 && len(up) == 2) {
    res = (low[0]-low[1]) * (up[0]-idx) + (idx-low[0]) * (up[1]-up[0]);
  }
  return res;
}


