// セグメントツリー
template <typename T>
class SegmentTree
{
private:
	vector<T> data;
	int segDataMax;
	T initValRes;
	function<T(T, T)> joinExec;

public:
	SegmentTree(int K, T initVal, function<T(T, T)> arg) : joinExec(arg)
	{
		initValRes = initVal;
		data.resize(1 << K, initVal);
		segDataMax = 1 << (K - 1);
	}

	void update(int index, T addData)
	{
		// 末端更新
		index += segDataMax - 1;
		data[index] = addData;

		// 親へ反映
		while (index != 0) {
			index = (index - 1) / 2;
			int downNodeNoL = index * 2 + 1;
			int downNodeNoR = index * 2 + 2;
			data[index] = joinExec(data[downNodeNoL], data[downNodeNoR]);
		}
	}

	// セグメントツリーのデータ数取得
	ll GetSegDataNum()
	{
		return segDataMax;
	}

	T querySub(int dataSt, int dataEnd, int nodeNo, int rangeL, int rangeR)
	{
		// この範囲にはない
		if ((dataEnd <= rangeL) || (rangeR <= dataSt)) {
			return initValRes;
		}

		// 範囲に入ってる
		if ((dataSt <= rangeL) && (rangeR <= dataEnd)) {
			return data[nodeNo];
		}

		int rangeM = (rangeL + rangeR) / 2;
		int downNodeNoL = nodeNo * 2 + 1;
		int downNodeNoR = nodeNo * 2 + 2;
		T vl = querySub(dataSt, dataEnd, downNodeNoL, rangeL, rangeM);
		T vr = querySub(dataSt, dataEnd, downNodeNoR, rangeM, rangeR);
		T vlr = joinExec(vl, vr);
		return vlr;
	}

	// セグメントツリーからデータ取得
	T query(int dataSt, int dataEnd)
	{
		return querySub(dataSt, dataEnd, 0, 0, segDataMax);
	}

	// 全区間のデータ取得
	T GetAllRangeData(void)
	{
		return data[0];
	}
};

template <class T>
T joinSegTree(const T &left, const T &right)
{
	T	joinRes = max(left, right);
	return joinRes;
}

// ベクターをインデックスのマップに変換
template <class T>
map<T, int> vectorToIdxMap(const vector<T> &vect)
{
	int cmpIdx = 0;
	map<T, int> idxTblMap;

	// 並びはそのままでインデックスを割り当て
	for (auto one : vect) {
		idxTblMap[one] = cmpIdx;
		cmpIdx++;
	}

	return idxTblMap;
}

