{
	ll N;
	cin >> N;
	vector<ll> P(N);
	REP(i, N) cin >> P[i];

	SegmentTree<ll> segTree(18, 0, joinSegTree<ll>);
	REP(i, N) {
		segTree.update(i, P[i]);
	}

	ll ans = 0;
	map<ll, int> toIdx = vectorToIdxMap<ll>(P);
	REP(i, N - 1) {
		REPN(j, i + 1, N) {
			ll valMax = segTree.query(i, j + 1);
			int idx = toIdx[valMax];
			segTree.update(idx, -1);
			{
				ll ansOne = segTree.query(i, j + 1);
				ans += ansOne;
			}
			segTree.update(idx, valMax);
		}
	}

	cout << ans << endl;

	return 0;
}

