ll solve() {
    ll N;
    cin >> N;
    vector<ll> P(N);
    for ( int i = 0; i < N; i++ ) {
        cin >> P[i];
    }
    vector<ll> L(N),R(N);
    // priority queue reverse order
    auto cmp = [&](pii& i1, pii& i2) { 
        return i1.first > i2.first;
    };
    priority_queue<pii, vector<pii>, decltype(cmp)> q(cmp);

    for ( int i = 0; i < N; i++ ) {
        if ( !q.empty() ) {
            while ( !q.empty() && q.top().first < P[i] ) {
                auto x = q.top();
                q.pop();
                R[x.second] = i - x.second;
            }
        }
        q.push(pii(P[i],i));
    }

    while ( !q.empty() ) q.pop();

    for ( int i = N-1; i >=0; i-- ) {
        if ( !q.empty() ) {
            while ( !q.empty() && q.top().first < P[i] ) {
                auto x = q.top();
                q.pop();
                R[x.second] = x.second - i;
            }
        }
        q.push(pii(P[i],i));
    }

    ll ans = 0;
    for ( int i = 0; i < N; i++ ) {
        ans += L[i] * R[i];
    }
    return ans;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

