const int MAXN=1e5+10;
int p[MAXN],n,res;
struct Segtree
{
	int val[MAXN<<2];
#define root val[o]
#define lson val[o<<1]
#define rson val[o<<1|1]
	void bd(int o,int l,int r)
	{
		if(l==r)
			return (void)(root=p[l]);
		int mid=(l+r)>>1;
		bd(o<<1,l,mid);
		bd(o<<1|1,mid+1,r);
		root=max(lson,rson);
	}
	void query(int o,int l,int r,int L,int R)
	{
		if(L>R)
			return;
		if(L<=l && r<=R)
			return (void)(res=max(res,root));
		int mid=(l+r)>>1;
		if(L<=mid)
			query(o<<1,l,mid,L,R);
		if(R>mid)
			query(o<<1|1,mid+1,r,L,R);
	}
}T;
int FindPre(int LL,int RR,int v)
{
	int L=LL,R=RR,s=0;
	while(L<=R)
	{
		int mid=(L+R)>>1;
		res=0;
		T.query(1,1,n,mid,RR);
		if(res>v)
			s=mid,L=mid+1;
		else
			R=mid-1;
	}
	return s;
}
int FindSuf(int LL,int RR,int v)
{
	int L=LL,R=RR,s=n+1;
	while(L<=R)
	{
		int mid=(L+R)>>1;
		res=0;
		T.query(1,1,n,mid,RR);
		if(res>v)
			s=mid,R=mid-1;
		else
			L=mid+1;
	}
	return s;
}
int main()
{
	n=read();
	for(int i=1;i<=n;++i)
		p[i]=read();
	T.bd(1,1,n);
	ll ans=0;
	for(int i=1;i<=n;++i)
	{
		int	pre1,pre2,suf1,suf2;
		pre1=FindPre(1,i-1,p[i]);
		pre2=FindPre(1,pre1-1,p[i]);
		if(pre2==0 && pre1==0)
			--pre2;
		suf1=FindSuf(i+1,n,p[i]);
		suf2=FindSuf(suf1+1,n,p[i]);
		if(suf2==n+1 && suf1==n+1)
			++suf2;
		ll tmp=0;
		if(pre1!=0)
			tmp+=1LL*(pre1-pre2)*(suf1-i);
		if(suf1!=n+1)
			tmp+=1LL*(suf2-suf1)*(i-pre1);
		ans+=tmp*p[i];
	}
	cout<<ans<<endl;
	return 0;
}

