tree max_tree[1<<18];

void init(int index, int left, int right){
    max_tree[index].left = left;
    max_tree[index].right = right;
    fprintf(stderr, "init %d %d %d\n", left, right, index);
    if (right == left) {
        max_tree[index].first = left;
        max_tree[index].second = -1;
    } else {
        int c1 = 2 * index + 1;
        int c2 = 2 * index + 2;
    fprintf(stderr, "init p1\n");
        init(c1, left, (left+right)/2);
    fprintf(stderr, "init p2\n");
        init(c2, (left+right)/2+1, right);
    fprintf(stderr, "init p3\n");
        if (p[max_tree[c1].first] > p[max_tree[c2].first]) {
            max_tree[index].first = max_tree[c1].first;
            max_tree[index].second = 
                (max_tree[c1].second != -1 && p[max_tree[c1].second] > p[max_tree[c2].first]) 
                ? max_tree[c1].second
                : max_tree[c2].first;
        } else {
            max_tree[index].first = max_tree[c2].first;
            max_tree[index].second = 
                (max_tree[c2].second != -1 && p[max_tree[c2].second] > p[max_tree[c1].first]) 
                ? max_tree[c2].second
                : max_tree[c1].first;
        }
    }

    fprintf(stderr, "init %d %d %d => %d %d\n", left, right, index, max_tree[index].first, max_tree[index].second);
}

ii_t range_max(int left, int right, int index=0) {
    if (max_tree[index].left == left 
            && max_tree[index].right == right) {
        //fprintf(stderr, "range_max' %d %d %d => %d %d\n", left, right, index, max_tree[index].first, max_tree[index].second);
        return ii_t(max_tree[index].first, max_tree[index].second);
    }
    int mid = (max_tree[index].left + max_tree[index].right)/2;
    if (right <= mid) {
        return range_max(left,right,2*index+1);
    }
    if (mid < left) {
        return range_max(left,right,2*index+2);
    }
    int c1 = 2 * index + 1;
    int c2 = 2 * index + 2;
    ii_t l = range_max(left,mid,c1);
    ii_t r = range_max(mid+1,right,c2);
    ii_t result;
    if (p[l.first] > p[r.first]) {
        result.first = l.first;
        result.second = 
            (l.second != -1 && p[l.second] > p[r.first]) 
            ? l.second
            : r.first;
    } else {
        result.first = r.first;
        result.second = 
            (r.second != -1 && p[r.second] > p[l.first]) 
            ? r.second
            : l.first;
    }
    //fprintf(stderr, "range_max %d %d %d => %d %d\n", left, right, index, result.first, result.second);
    return result;
}

long long calc(int left, int right) {
    if (left >= right) return 0;
    ii_t pos = range_max(left, right);
    int mnp = min(pos.first,pos.second);
    int mxp = max(pos.first,pos.second);
    long long answer = (mnp - left + 1)
        * (right - mxp + 1) * p[pos.second];
    fprintf(stderr, "calc' %d %d => %lld\n", left, right, answer);
    answer += calc(mnp+1, right);
    answer += calc(left, mxp-1);
    answer -= calc(mnp+1, mxp-1);

    fprintf(stderr, "calc %d %d => %lld\n", left, right, answer);
    return answer;
}

