int brute_force() {
    int ret = 0;
    for(int l = 0; l < N - 1; ++l) {
        for(int r = l + 1; r < N; ++r) {
            vector<int> sub;
            for(int i = l; i <= r; ++i) { sub.push_back(P[i]); }
            SORT(sub);
            ret += sub[sub.size() - 2];
        }
    }
    return ret;
}

int solve() {
    auto Rmq = [](int a, int b) -> int
    {
        return max(a, b);
    };
    SegmentTree<int> seg;
    seg.Init(N, Rmq, -INF);
    REP(i, N) {
        seg.Set(i, P[i]);
    }
    seg.Build();

    int ret = 0;
    REP(i, N) {
        int val = P[i];
        DBG("P[%lld]: %lld = val\n", i, val);
        // i より右にあるもののうち、一番左のものを調べる
        if(i + 1 < N) {
            int r_ind = bin_search6(seg, i + 1, N, val);
            DBG("  r_ind[%lld, %lld): %lld\n", i + 1, N, r_ind);
            if(r_ind != -1) {
                // r_ind から更に右を見て、Pi が 2 番手である範囲を確定
                int r_ind2 = -1;
                if(r_ind + 1 < N) {
                    r_ind2 = bin_search6(seg, r_ind + 1, N, val);
                    if(r_ind2 != -1) { r_ind2--; }
                }
                if(r_ind2 == -1) { r_ind2 = N - 1; }
                DBG("  r_ind2: %lld\n", r_ind2);
                // i から更に左側に伸ばす場合
                int l_ind = -1;
                if(i - 1 >= 0) {
                    l_ind = bin_search7(seg, 0, i, val);
                    if(l_ind != -1) { l_ind++; }
                }
                if(l_ind == -1) { l_ind = 0; }
                DBG("  l_ind: %lld\n", l_ind);
                assert(r_ind2 >= r_ind);
                assert(i >= l_ind);
                //int cnt = (r_ind2 - r_ind) + (i - l_ind) + 1;
                int cnt = (r_ind2 - r_ind + 1) * (i - l_ind + 1);
                DBG("  cnt1: %lld\n", cnt);
                ret += val * cnt;
            }
        }
        // i より左にあるもののうち、一番右のものを調べる
        if(i - 1 >= 0) {
            int l_ind = bin_search7(seg, 0, i, val);
            DBG("  l_ind[%lld, %lld): %lld\n", 0, i, l_ind);
            if(l_ind != -1) {
                int l_ind2 = -1;
                if(l_ind - 1 >= 0) {
                    l_ind2 = bin_search7(seg, 0, l_ind, val);
                    if(l_ind2 != -1) { l_ind2++; }
                }
                if(l_ind2 == -1) { l_ind2 = 0; }
                DBG("  l_ind2: %lld\n", l_ind2);
                int r_ind = -1;
                if(i + 1 < N) {
                    r_ind = bin_search6(seg, i + 1, N, val);
                    if(r_ind != -1) { r_ind--; }
                }
                if(r_ind == -1) { r_ind = N - 1; }
                DBG("  r_ind: %lld\n", r_ind);
                assert(l_ind >= l_ind2);
                assert(r_ind >= i);
                //int cnt = (l_ind - l_ind2) + (r_ind - i) + 1;
                int cnt = (l_ind - l_ind2 + 1) * (r_ind - i + 1);
                DBG("  cnt2: %lld\n", cnt);
                ret += val * cnt;
            }
        }
    }

    return ret;
}

