vector<int> a;
vector<int> t1;
vector<pii> t2;
pii combine(pii a,pii b)
{
    pii ans = make_pair(0,0);
    if(a.first>b.first)
    {
        ans.first = a.first;
        if(a.second>b.first)
            ans.second = a.second;
        else
            ans.second = b.first;
    }
    else
    {
        ans.first = b.first;
        if(b.second>a.first)
            ans.second = b.second;
        else
            ans.second = a.first;
    }
    return ans;
}
void build2(int node,int l,int r)
{
    if(l==r)
        {
            t2[node].first = a[l];
            t2[node].second = 0;
        }
    else
    {
        int mid = (l+r)/2;
        build2(2*node,l,mid);
        build2(2*node+1,mid+1,r);
        t2[node] = combine(t2[2*node],t2[2*node+1]);
    }
    return ;
}
pii query2(int node,int l,int r,int ql,int qr)
{
    if(ql>qr)
        return make_pair(0,0);
    if(l==ql && r==qr)
        return t2[node];
    int mid = (l+r)/2;
    if(qr<=mid)
        return query2(2*node,l,mid,ql,qr);
    if(ql>mid)
        return query2(2*node+1,mid+1,r,ql,qr);
    return combine(query2(2*node,l,mid,ql,mid),query2(2*node+1,mid+1,r,mid+1,qr));
}
void build1(int node,int l,int r)
{
    if(l==r)
        t1[node]=a[l]; 
    else
    {
        int mid = (l+r)/2;
        build2(2*node,l,mid);
        build2(2*node+1,mid+1,r);
        t1[node] = max(t1[2*node],t1[2*node+1]);
    }
    return ;
}
int query1(int node,int l,int r,int ql,int qr)
{
    if(ql>qr)
        return 0;
    if(l==ql && r==qr)
        return t1[node];
    int mid = (l+r)/2;
    if(qr<=mid)
        return query1(2*node,l,mid,ql,qr);
    if(ql>mid)
        return query1(2*node+1,mid+1,r,ql,qr);
    return max(query1(2*node,l,mid,ql,mid),query1(2*node+1,mid+1,r,mid+1,qr));
}
