            x3 = n-1-i;
            x4=-1;
        }
        else if(tr==1)
        {
            x3 = pos[rgt.first]-i-1;
            x4 = n-1-pos[rgt.first];
        }
        else
        {
            int lo = i+1;
            int hi = n-1;
            int md;
            while(lo<hi)
            {
                md = lo + (hi-lo)/2;
                int vl = query1(1,0,n-1,i,md);
                if(vl==a[i])
                    lo = md+1;
                else
                    hi= md;
            }
            int p1 = lo;
            lo = p1;
            hi = n-1;
            while(lo<hi)
            {
                md = lo + (hi-lo)/2;
                pii vl = query2(1,0,n-1,i,md);
                if(vl.second==a[i])
                    lo = md+1;
