int main() {
	int N;
	scanf("%d", &N);
	int *P = new int[N];
	int *w = new int[N];
	for (int i = 0; i < N; i++) {
		int p;
		scanf("%d", &p);
		P[i] = p - 1;
		w[p - 1] = i;
	}
	carr c(N);
	c.cadd(w[N - 1]);
	long long res = 0;
	for (int i = N - 2; i >= 0; i--) {
		int l = c.prev(w[i]);
		int r = c.next(w[i]);
		if (l < 0 || l>N)l = -1;
		if (r < 0 || r>N)r = N;
		long long ll = c.prev(l);
		long long rr = c.next(r);
		if (ll < 0 || ll>N)ll = -1;
		if (rr < 0 || rr>N)rr = N;
		res += ((l - ll)*(r - w[i]) + (rr - r)*(w[i] - l))*(i + 1);
		c.cadd(w[i]);
		//printf("(%lld %d %d %d,%lld)\n", ll, l, w[i], r, rr);
	}
	printf("%lld", res);
	return 0;
}

