void read_int_unlocked(int * out)
{
	static int c;
	*out = 0;
	c = getchar_unlocked();
	for (; '0' <= c && c <= '9'; c = getchar_unlocked())
		*out = (*out) * 10 + c - '0';
}

int main()
{
	read_int_unlocked(&n);
	vec = new int[n];
	int * start = vec;
	int * end = vec + n;
	for (int * i = start; i < end; i++)
		read_int_unlocked(i);

	per = new int[n];
	for (int * i = start; i < start + n; i++)
		*(per + (*i) - 1) = i - vec;

	r = new int[n];
	for (auto i = r; i < r + n; i++)
		*i = 0;
	l = new int[n];
	for (auto i = l; i < l + n; i++)
		*i = 0;

	int vsp, right, left;
	for (auto i = per; i < per + n - 1; i++)
	{
		vsp = *i;
		right = vsp + r[vsp] + 1;
		left = vsp - l[vsp] - 1;
		if (left == -1)
		{
			ans += vec[vsp] * (r[right] + 1 + l[vsp]);
			l[right] = right;
		}
		else if (right == n)
		{
			ans += vec[vsp] * (l[left] + 1 + r[vsp]);
			r[left] = n - left - 1;
		}
		else
		{
			ans += vec[vsp] * ((l[vsp] + 1) * (r[right] + 1) + (r[vsp] + 1) * (l[left] + 1));
			r[left] = l[right] = r[vsp] + l[vsp] + 1;
		}
	}

	std::cout << ans;

	//system("pause");
	return 0;
}

