}
struct segtree {
  vector<pii> tr;
  segtree(int n, int val):tr(2*n,{val,val}){}
  void update(int p, int val) {
    for(tr[p+=n].fi=val; p>1; p>>=1) {
      tr[p>>1]=merge(tr[p],tr[p^1]);
    }
  }
  pii query(int l, int r, int val) {
    r++;
    pii res={val, val};
    for(l+=n,r+=n; l<r; l>>=1,r>>=1) {
      if(l&1) res=merge(res,tr[l++]);
      if(r&1) res=merge(res,tr[--r]);
    }
    return res;
  }
};


