const int MAX { 200010 };
const ll MOD { 1000000007 }, oo { 1LL << 62 };

class SegmentTree
{
    int N;
    std::vector<int> ns;

public:
    SegmentTree(const std::vector<int>& xs) : N(xs.size()), ns(2*N, -1)
    {
        std::copy(xs.begin(), xs.end(), ns.begin() + N);

        for (int i = N - 1; i > 0; --i)
            ns[i] = max(ns[2*i], ns[2*i + 1]);
    }

    int RMQ(int i, int j)
    {
        // As folhas estão na segunda metade de ns
        int a = i + N, b = j + N;
        int s = 0;

        while (a <= b)
        {
            if (a & 1)                  
                s = max(s, ns[a++]);

            if (not (b & 1))
                s = max(s, ns[b--]);

            a /= 2;
            b /= 2;
        }

        return s;
    }
};

ll intervals(ll a, ll b, const vector<ll>& is, SegmentTree& st)
{
#ifdef DEBUG
    cout << "=== interval [" << a << ", " << b << "], size = " << b - a + 1 << endl;
#endif
    if (b - a + 1 < 2)
        return 0;


    auto M = st.RMQ(a, b);
    auto m = max(st.RMQ(a, is[M] - 1), st.RMQ(is[M] + 1, b));

    auto i = min(is[M], is[m]);
    auto j = max(is[M], is[m]);

#ifdef DEBUG
    cout << "--- M = " << M << ", m = " << m << ", i = " << i << ", j = " << j << endl;
    cout << "+++ " << m << " x " << (b - j + 1) << " x " << (i - a + 1) << " = " << m * (b - j + 1) * (i - a + 1) << endl;
#endif
    ll ans = m * (b - j + 1) * (i - a + 1);

    if (is[m] < is[M])
    {
        ans += intervals(a, is[M] - 1, is, st);
        ans += intervals(is[m] + 1, b, is, st);
        ans -= intervals(is[m] + 1, is[M] - 1, is, st);
    } else
    {
        ans += intervals(a, is[m] - 1, is, st);
        ans += intervals(is[M] + 1, b, is, st);
        ans -= intervals(is[M] + 1, is[m] - 1, is, st);
    }

    return ans;
}

ll solve(int N, const vector<int>& xs)
{
    vector<ll> is(N + 1);

    for (int i = 0; i < N; ++i)
        is[xs[i]] = i;

    SegmentTree st(xs);

    ll ans = intervals(0, N - 1, is, st);

    return ans;
}

int main()
{
    ios::sync_with_stdio(false);

    int N;
    cin >> N;

    vector<int> xs(N);

    for (int i = 0; i < N; ++i)
        cin >> xs[i];

    auto ans = solve(N, xs);

    cout << ans << '\n';

    return 0;
}

