struct BIT {
    BIT(int n) : b(n + 1), n(n) {}
    void add(int i, int v) {
        for (int k = i + 1; k <= n; k += k & -k) b[k] += v;
    }
    int sum(int k) {
        int s = 0;
        for (; k > 0; k -= k & -k) s += b[k];
        return s;
    }
    int lower_bound(int s) {
        if (s <= 0) return 0;
        int x = 0, w = 1;
        while (w << 1 <= n) w <<= 1;
        do {
            int k = x + w;
            if (k <= n && b[k] < s) {
                s -= b[k];
                x += w;
            }
        } while (w >>= 1);
        return x + 1;
    }
    vector<int> b;
    int n;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<int> q(n);
    for (int i = 0; i < n; i++) {
        int p;
        cin >> p;
        p--;

        q[p] = i;
    }

    ll r = 0;
    BIT bt(n);
    for (int j = n - 1; j >= 0; j--) {
        int i = q[j];
        int s = bt.sum(i);

        int x[4];
        for (int h = 0; h < 4; h++) {
            x[h] = bt.lower_bound(s + h - 1) - 1;
        }

        r += (ll)j * (x[1] - x[0]) * (x[2] - i);
        r += (ll)j * (x[3] - x[2]) * (i - x[1]);

        bt.add(i, 1);
    }

    r += (ll)n * (n - 1) / 2;
    cout << r << endl;

    return 0;
}

