const int N = 1e5 + 5;

int n;
int a[N], pos[N];

int maxv[N << 2];

void push_up(int o) {
    maxv[o] = max(maxv[o << 1], maxv[o << 1|1]);
}

void update(int o, int l, int r, int p, int v, int op) {
    if(l == r) {
        maxv[o] += op * v;
        return;
    }
    int mid = (l + r) >> 1;
    if(p <= mid) update(o << 1, l, mid, p, v, op);
    else update(o << 1|1, mid + 1, r, p, v, op);
    push_up(o);
}

int query(int o, int l, int r, int L, int R, int v) {
    if(l == r) return l;
    int mid = (l + r) >> 1;
    int res = 0;
    if(L == 1) {
        if(L <= mid && maxv[o << 1] > v) res = max(res, query(o << 1, l, mid, L, R, v));
        if(R > mid && maxv[o << 1|1] > v) res = max(res, query(o << 1|1, mid + 1, r, L, R, v));
        return res;
    } else {
        res = n + 1;
        if(L <= mid && maxv[o << 1] > v) res = min(res, query(o << 1, l, mid, L, R, v));
        if(R > mid && maxv[o << 1|1] > v) res = min(res, query(o << 1|1, mid + 1, r, L, R, v));
        return res;
    }
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    cin >> n;
    for(int i = 1; i <= n; i++) cin >> a[i];
    for(int i = 1; i <= n; i++) update(1, 1, n, i, a[i], 1);
    ll ans = 0;
    for(int i = 1; i <= n; i++) {
        if(a[i] == n) continue;
//        cout << ans << '\n';
        int L1 = query(1, 1, n, 1, i - 1, a[i]);
        int R1 = query(1, 1, n, i + 1, n, a[i]);
        update(1, 1, n, L1, a[L1], -1);
        update(1, 1, n, R1, a[R1], -1);
        int L2 = query(1, 1, n, 1, i - 1, a[i]);
        int R2 = query(1, 1, n, i + 1, n, a[i]);
        update(1, 1, n, L1, a[L1], 1);
        update(1, 1, n, R1, a[R1], 1);
//        cout << L2 << ' ' << L1 << ' ' << R1 << ' ' << R2 << '\n';
        if(L1) {
            ans += 1ll * a[i] * (L1 - L2) * (R1 - i);
        }
        if(R1 <= n) {
            ans += 1ll * a[i] * (R2 - R1) * (i - L1);
        }
    }
    cout << ans;
}

