#define N  500009
#define M  (L+R)/2
#define ll long long
#define pb push_back
using namespace std;

struct node{
	ll MAX;
	node *left, *right;
	node(): MAX(0), left(NULL), right(NULL){}
};

node *root(NULL);

void upd(node *&parent, ll L, ll R, ll ind, ll x){

	if(!parent){
		parent=new node();
	}
	if(L+1==R){
		parent->MAX=x;
		return;
	}
	if(ind<M){
		upd(parent->left,L,M,ind,x);
	} else {
		upd(parent->right,M,R,ind,x);	
	}
	parent->MAX=max((parent->left?parent->left->MAX:0),(parent->right?parent->right->MAX:0));
}

ll get(node *&parent, ll L, ll R, ll l, ll r){
	if(parent){
		if(L>=r || R<=l)return 0;
		if(l<=L && R<=r)return parent->MAX;
		return max(get(parent->left,L,M,l,r),get(parent->right,M,R,l,r));
	}
	return 0;
}

ll n,a[N],ans,pre1,pre2,suf1,suf2;

void answerpre(node *&parent, ll L, ll R, ll l, ll r, ll x){

	if(parent){	
		if(parent->MAX>x){
			if(l<=L && R<=r && L+1==R){
				pre2=max(pre2,L);
				return;
			}
			if(!(M>=r || R<=l) && pre2<R)answerpre(parent->right,M,R,l,r,x);
			if(!(L>=r || M<=l) && pre2<M)answerpre(parent->left,L,M,l,r,x);
		}	
	}
	return;
}

void answersuf(node *&parent, ll L, ll R, ll l, ll r, ll x){

	if(parent){	
		if(parent->MAX>x){
			if(l<=L && R<=r && L+1==R){
				suf2=min(suf2,L);
				return;
			}
			if(!(L>=r || M<=l) && suf2>L)answersuf(parent->left,L,M,l,r,x);
			if(!(M>=r || R<=l) && suf2>M)answersuf(parent->right,M,R,l,r,x);	
		}	
	}
	return;
}


