int main() {
    int N;
    cin >> N;
    priority_queue<pair<i64, i64>> q;
    for(int i = 0; i < N; i++) {
        i64 p;
        cin >> p;
        q.push({p, i});
    }
    set<i64,    less<i64>> sr;
    set<i64, greater<i64>> sl;
    i64 ans = 0;
    for(int j = 0; j < N; j++) {
        i64 p, i;
        tie(p, i) = q.top();

        i64 l1 = -1, r1 = -1, l2 = -1, r2 = -1;
        {
            auto itor = sr.upper_bound(i);
            if (itor != sr.end()) {
                r1 = *itor;
                itor = sr.upper_bound(r1);
                if (itor != sr.end()) {
                    r2 = *itor;
                }
            }
            itor = sl.upper_bound(i);
            if (itor != sl.end()) {
                l1 = *itor;
                itor = sl.upper_bound(l1);
                if (itor != sl.end()) {
                    l2 = *itor;
                }
            }
        }
        if(r1 >= 0 && r2 < 0) r2 = N;
        if(r1 < 0) r1 = N;

        if(l1 >= 0) {
            ans += (r1 - i) * (l1 - l2) * p;
        }
        if(r1 < N) {
            ans += (i - l1) * (r2 - r1) * p;
        }
        sl.insert(i), sr.insert(i);
        q.pop();
    }
    cout << ans << endl;
    return 0;
}

