template <class T>
class SegTree {
    int n;                       // 葉の数
    vector<T> data;              // データを格納するvector
    T def;                       // 初期値かつ単位元
    function<T(T, T)> operation; // 区間クエリで使う処理
    function<T(T, T)> update;    // 点更新で使う処理

    // 区間[a,b)の総和。ノードk=[l,r)に着目している。
    T _query(int a, int b, int k, int l, int r) const {
        if (r <= a || b <= l) return def; // 交差しない
        if (a <= l && r <= b)
            return data[k]; // a,l,r,bの順で完全に含まれる
        else {
            T c1 = _query(a, b, 2 * k + 1, l, (l + r) / 2); // 左の子
            T c2 = _query(a, b, 2 * k + 2, (l + r) / 2, r); // 右の子
            return operation(c1, c2);
        }
    }

  public:
    // _n:必要サイズ, _def:初期値かつ単位元, _operation:クエリ関数,
    // _update:更新関数
    SegTree(size_t _n, T _def, function<T(T, T)> _operation,
            function<T(T, T)> _update)
        : def(_def), operation(_operation), update(_update) {
        n = 1;
        while (n < _n) {
            n *= 2;
        }
        data = vector<T>(2 * n - 1, def);
    }

    // 場所i(0-indexed)の値をxで更新
    void change(int i, T x) {
        i += n - 1;
        data[i] = update(data[i], x);
        while (i > 0) {
            i = (i - 1) / 2;
            data[i] = operation(data[i * 2 + 1], data[i * 2 + 2]);
        }
    }

    // [a, b)の区間クエリを実行
    T query(int a, int b) const {
        return _query(a, b, 0, 0, n);
    }

    // 添字でアクセス
    T operator[](int i) const {
        return data[i + n - 1];
    }
};

int N;

ll calc(int idx, SegTree<int> &st) {
    // P[idx] が 2 番目になる区間の数
    ll ans = 0;

    // [l1, idx) の最大値が P[idx] を超える最大の l1
    int ok = -1, ng = idx;
    while (ng - ok > 1) {
        int mid = (ok + ng) / 2;
        if (st.query(mid, idx) > st[idx]) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    int l1 = ok;

    // [l2, l1) の最大値が P[idx] を超える最大の l2
    ok = -1, ng = l1;
    while (ng - ok > 1) {
        int mid = (ok + ng) / 2;
        if (st.query(mid, l1) > st[idx]) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    int l2 = ok;

    // [idx, r1) の最大値が P[idx] を超える最小の r1
    ok = N + 1, ng = idx;
    while (ok - ng > 1) {
        int mid = (ok + ng) / 2;
        if (st.query(idx, mid) > st[idx]) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    int r1 = ok;

    // [r1, r2) の最大値が P[idx] を超える最小の r2
    ok = N + 1, ng = r1;
    while (ok - ng > 1) {
        int mid = (ok + ng) / 2;
        if (st.query(r1, mid) > st[idx]) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    int r2 = ok;

    dump(l2, l1, idx, r1, r2);

    return (ll)(l1 - l2) * (r1 - 1 - idx) + (ll)(idx - l1) * (r2 - r1);
}

int main() {
    cin >> N;
    vi P(N);
    cin >> P;
    SegTree<int> st(N, 0, [](int a, int b) { return max(a, b); },
                    [](int a, int b) { return b; });
    rep(i, N) {
        st.change(i, P[i]);
    }

    ll ans = 0;
    rep(i, N) {
        ll c = calc(i, st);
        dump(c);
        ans += (ll)P[i] * c;
    }
