using namespace std;


vector<int> value; // ノードの値を持つ配列
int N;             // 葉の数

void update(int i, int x) {
	i += N - 1;
	value[i] = x;
	while (i > 0) {
		i = (i - 1) / 2;
		value[i] = max(value[i * 2 + 1],
			value[i * 2 + 2]);
	}
}

int query(int a, int b, int k, int l, int r) {
	if (r <= a || b <= l) return 0;
	if (a <= l && r <= b)
		return value[k];
	else {
		int c1 = query(a, b, 2 * k + 1, l, (l + r) / 2);
		int c2 = query(a, b, 2 * k + 2, (l + r) / 2, r);
		return max(c1, c2);
	}
}

int binary_search(int left, int right, int key, int pivot) {
	while (right-left >= 2) {
		int mid = left + (right - left) / 2; // 区間の真ん中
		int val = query(mid, pivot, 0, 0, N);
		if (val > key) {
			left = mid;
		}
		else right = mid;
	}
	return left;
}

int binary_search2(int left, int right, int key, int pivot) {
	while (right - left >= 2) {
		int mid = left + (right - left) / 2; // 区間の真ん中
		int val = query(pivot,mid, 0, 0, N);
		if (val > key) {
			right = mid;
		}
		else left = mid;
	}
	return right;
}

int main() {
	int n;
	cin >> n;
	N = 1;
	while (N < n) N *= 2; // 葉の数を計算（n以上の最小の2冪数）
	value = vector<int>(2 * N - 1, 0);
	vector<int> p;
	for (int i = 0; i < n; ++i) {
		int pi;
		cin >> pi;
		update(i, pi);
		p.push_back(pi);
	}
	int64_t sum = 0;
	for (int i = 0; i < n; ++i) {
		int val = p[i];
		int lp1, lp2;
		int rp1, rp2;

		int left1 = query(0, i, 0, 0, N);
		if (left1 < val) {
			lp1 = lp2 = -1;
		}
		else {
			int pos = binary_search(0, i, val, i);
			lp1 = pos;
			int left2 = query(0, lp1, 0, 0, N);
			if (left2 < val) {
				lp2 = -1;
			}
			else {
				int pos2 = binary_search(0, lp1, val, lp1);
				lp2 = pos2;
			}
		}

		int right1 = query(i+1,N, 0, 0, N);
		if (right1 < val) {
			rp1 = rp2 = -1;
		}
		else {
			int pos = binary_search(i+1, N, val, i+1);
			rp1 = pos;
			int right2 = query(rp1+1, N, 0, 0, N);
			if (right2 < val) {
				rp2 = -1;
			}
			else {
				int pos2 = binary_search(rp1+1, N, val, rp1+1);
				rp2 = pos2;
			}
		}
		//cout << i << " " << lp1 << " " << lp2 << " " << rp1 << " " << rp2 << endl;
		if (lp1 != -1) {
			int lpad, rpad;
			if (lp2 == -1) lpad = lp1+1;
			else lpad = lp1 - lp2;
			if (rp1 == -1) rpad = n - i;
			else rpad = rp1 - i;
			sum += val * lpad*rpad;
			//cout << lpad << " " << rpad << endl;
		}
		if (rp1 != -1) {
			int lpad, rpad;
			if (lp1 == -1) lpad = i+1;
			else lpad = i - lp1;
			if (rp2 == -1) rpad = n - rp1;
			else rpad = rp2 - rp1;
			sum += val * lpad*rpad;
			//cout << lpad << " " << rpad << endl;
		}
	}
	cout << sum << endl;
	return 0;
}


