  cin >> N;
  nums.reserve(N + 4);
  nums.emplace_back();
  for (int i = 1; i <= N; ++i) {
    int n;
    cin >> n;
    nums.emplace_back(n);
    sorted_its.push_back(nums.end() - 1);
  }

  sort(sorted_its.begin(), sorted_its.end(),
       [](auto&& a, auto&& b) { return *a > *b; });

  int64_t result = 0;

  for (auto&& it : sorted_its) {
    auto r1_it = seen.upper_bound(it);
    It left1, left2, right1, right2;
    if (r1_it == seen.end()) {
      right1 = nums.end();
      right2 = nums.end();
    } else {
      right1 = *r1_it;
      auto r2_it = next(r1_it);
      right2 = r2_it == seen.end() ? nums.end() : *r2_it;
    }
    if (r1_it == seen.begin()) {
      left1 = nums.begin();
      left2 = nums.begin();
    } else {
      auto l1_it = prev(r1_it);
      left1 = *l1_it;
      left2 = l1_it == seen.begin() ? nums.begin() : *prev(l1_it);
    }
    result += *it * ((left1 - left2) * (right1 - it) +
                     (right2 - right1) * (it - left1));
    seen.emplace(it);
  }

  cout << result << endl;
}

