    }
    for (ll I = 1; (1 << I) <= n; I++)
        for (ll i = 1; i + P[I] <= n + 1; i++)
            R[i][I] = max (R[i][I - 1], R[i + P[I - 1]][I - 1]);
    for (ll i = 1; i <= n; i++){
        ll l1, l2, r1, r2;
