int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n; cin >> n;
    vector<int> pos(n+1, 0);
    for(int i=1; i<=n; ++i){
        int p; cin >> p;
        pos[p] = i;
    }

    ll ans = 0;
    multiset<int> se{0, 0, n+1, n+1};
    for(int i=n; i>=1; --i){
        auto itr = se.lower_bound(pos[i]);
        int r1 = *itr;
        ++itr;
        int r2 = *itr;
        --itr;
        --itr;
        int l1 = *itr;
        --itr;
        int l2 = *itr;
        ans += (ll)i*(l1-l2)*(r1-pos[i]);
        ans += (ll)i*(r2-r1)*(pos[i]-l1);
        se.insert(pos[i]);
    }

    cout << ans << '\n';

    return 0;
}

