const int N = 1e5 + 5;
int n, p[N], pos[N], lb[2][N], ub[2][N];

int main() {
  cin >> n;
  FI(i,1,n) scanf("%d", &p[i]), pos[p[i]] = i;
  set<int> se;
  for (int x = n; x >= 1; --x) {
    lb[0][x] = lb[1][x] = 0;
    ub[0][x] = ub[1][x] = n + 1;
    auto it = se.lower_bound(pos[x]);
    if (it != se.begin()) {
      lb[0][x] = *prev(it, 1);
      if (prev(it, 1) != se.begin()) lb[1][x] = *prev(it, 2);
    }
    if (it != se.end()) {
      ub[0][x] = *it;
      if (next(it, 1) != se.end()) ub[1][x] = *next(it, 1);
    }
    se.insert(pos[x]);
  }
  LL ans = 0;
  for (int x = 1; x <= n; ++x) {
    int i = pos[x];
    LL cnt = 1LL * (lb[0][x] - lb[1][x]) * (ub[0][x] - i)
      + 1LL * (ub[1][x] - ub[0][x]) * (i - lb[0][x]);
    ans += x * cnt;
  }
  cout << ans << endl;
}

