int main(){
    int n; cin >> n;
    vector<int> idx(n, 0);
    for(int i=0; i<n; i++){
        int val; cin >> val; val--;
        idx[val] = i;
    }
    reverse(idx.begin(), idx.end());
    multiset<int> ms{-1,-1,n,n};
    ll ans = 0;
    for(int i=0; i<n; i++){
        if(i == 0){ms.insert(idx[i]); continue;}
        auto it = ms.lower_bound(idx[i]);
        int R2 = *++it;
        int R1 = *--it;
        int L1 = *--it;
        int L2 = *--it;
        ans += (L1 - L2) * (R1 - idx[i]) * (n-i);
        ans += (R2 - R1) * (idx[i] - L1) * (n-i);
        ms.insert(idx[i]);
    }
    cout << ans << endl;
    return 0;
}

