struct Grid2D{
    Graph graph;
    ll Width, Height;

    Grid2D(ll w, ll h) : Width(w), Height(h){
        graph.resize(w * h);
    }

    ll pos_to_idx(point p){
        return p.y * Width + p.x;
    }

    point idx_to_pos(ll idx){
        return {idx % Width, idx / Width};
    }

    bool undefined_region(point p, vb2& block){
        if (p.x < 0 || p.x > Width - 1) return true;
        if (p.y < 0 || p.y > Height - 1) return true;
        if (block[p.x][p.y]) return true;
        return false;
    }

    void build(vb2& block, ll val = 1){
        rep(x, Width) rep(y, Height){
            point p = {x, y};
            ll idx1 = pos_to_idx(p); ll idx2;

            if (block[x][y]) continue;
            rep(i, 4){
                point nxt = p + dirs[i];
                idx2 = pos_to_idx(nxt);
                if (!undefined_region(nxt, block))
                    graph[idx1].pb({idx2, val}); // dist[idx1][idx2] = val; (warshall-floyd)
            }
        }
    }
};

struct Cumulative2D{
    vl2 cum;
    ll w, h;

    Cumulative2D(ll w, ll h) : w(w), h(h){
        cum = vl2(w + 1, vl(h + 1, 0));
    }

    template<typename T>
    void build(vector<T>& vec){
        // never forget building
        rep(x, w + 1) cum[x][0] = 0;
        rep(y, h + 1) cum[0][y] = 0;
        rep(y, h) rep(x, w)
            cum[x + 1][y + 1] = cum[x][y + 1] + vec[x][y];
        rep(x, w + 1) rep(y, h)
            cum[x][y + 1] += cum[x][y];
    }

    ll func(ll x, ll y, ll dx, ll dy){
        // 1-indexed
        // the rectangle of (x, y), (x + dx, y), (x, y + dy) and (x + dx, y + dy)
        // think about the case of (1, 1, 1, 1).
        if (x + dx > w || y + dy > h) return - INF;
        ll val = cum[x + dx][y + dy];
        val += cum[x][y];
        val -= cum[x][y + dy];
        val -= cum[x + dx][y];
        return val;
    }
};

struct LinearSystemIncidence{
    struct Edge{ll idx, to; bool fwd;};
    /*
    Ax = c
    A: A in R^(V * E) <- given
    x: x in R^E <- estimate this vector
    c: c in R^V <- given
    */
    ll n_vertex, n_edge;
    bool mod2;
    vl x;
    vb visited;
    vector<vector<Edge>> graph;

    LinearSystemIncidence(ll n, vpl& es, bool mod2 = false) : 
        n_vertex(n), n_edge(es.size()), mod2(mod2){
        graph.resize(n); visited.resize(n);
        rep(i, n_edge){
            auto& e = es[i];
            graph[e.e1].pb({i, e.e2, true});
            graph[e.e2].pb({i, e.e1, false});
        }
    }

    ll dfs(vl& c, ll src){
        visited[src] = true;
        ll ret = c[src];
        for (Edge& e : graph[src]){
            if (visited[e.to]) continue;
            ll tmp = dfs(c, e.to);
            x[e.idx] = e.fwd ? tmp : -tmp;
            ret += tmp;
            if (mod2) x[e.idx] = ((x[e.idx] % 2) + 2) % 2;
        }
        return mod2 ? ret % 2 : ret;
    }

    bool solve(vl& c){
        x.assign(n_edge, 0);
        visited.assign(n_vertex, false);
        rep(src, n_vertex){
            if (visited[src]) continue;
            if (dfs(c, src)) return false;
        }
        return true;
    }
};

struct BigInt10{
    string num;
    ll sz;
    map<ll, vl> mod;

    BigInt10(string num) : num(num), sz(num.size()){}

    void compute_mod(ll _mod){
        mod[_mod] = vl(sz + 1, 0);
        ll tenth = 1;

        rep(i, sz){
            ll top = num[sz - 1 - i] - '0';
            mod[_mod][i + 1] = (mod[_mod][i] + top * tenth) % _mod;
            (tenth *= 10) %= _mod;
        }
    }

    ll n_digits(){return num.length();}
    ll operator[](ll k){return num[k] - '0';}
    ll subseq_mod(ll l, ll r, ll m){
        // s1 s2 ... sl .... sr ... sn
        // the modulo of 00 ... 0 sl ... sr 00 ... 0
        assert(l <= r);
        ll tot = mod[m][sz];
        ll ls = (tot - mod[m][sz - l] + m) % m;
        ll rs = mod[m][sz - r];
        return (tot - ls - rs + 2 * m) % m;
    }

    bool operator<(BigInt10& n2) const{
        if (num.length() < n2.n_digits()) return true;
        else if (num.length() > n2.n_digits()) return false;
        return num < n2.num;
    }

    bool operator>(BigInt10& n2) const{
        if (num.length() > n2.n_digits()) return true;
        else if (num.length() < n2.n_digits()) return false;
        return num > n2.num;
    }
};

struct BigInt2{
    string num;
    ll sz;
    map<ll, vl> mod;
    ll nz;

    BigInt2(string num) : num(num), sz(num.size()){
        nz = 0;
        rep(i, sz) if (num[i] == '1') nz++;
    }

    void compute_mod(ll _mod){
        mod[_mod] = vl(sz + 1, 0);
        ll base = 1;

        rep(i, sz){
            ll top = num[sz - 1 - i] - '0';
            mod[_mod][i + 1] = (mod[_mod][i] + top * base) % _mod;
            (base *= 2) %= _mod;
        }
    }

    ll n_digits(){return num.length();}
    ll popcount(){return nz;}
    ll operator[](ll k){return num[k] - '0';}
    ll subseq_mod(ll l, ll r, ll m){
        // s1 s2 ... sl .... sr ... sn
        // the modulo of 00 ... 0 sl ... sr 00 ... 0
        assert(l <= r);
        ll tot = mod[m][sz];
        ll ls = (tot - mod[m][sz - l] + m) % m;
        ll rs = mod[m][sz - r];
        return (tot - ls - rs + 2 * m) % m;
    }

    bool operator<(BigInt10& n2) const{
        if (num.length() < n2.n_digits()) return true;
        else if (num.length() > n2.n_digits()) return false;
        return num < n2.num;
    }

    bool operator>(BigInt10& n2) const{
        if (num.length() > n2.n_digits()) return true;
        else if (num.length() < n2.n_digits()) return false;
        return num > n2.num;
    }
};

ll gcd(ll m, ll n){
    ll a = max(m, n);
    ll b = min(m, n);
    while(b != 1 && b != 0){ a %= b; swap(a, b);}
    return b == 1 ? 1 : a;
}

ll lcm(ll m, ll n){ return m / gcd(m, n) * n;}

ll power_normal(ll a, ll power){
    ll value = 1;
    while(power != 0){
        if(power & 1) value = value * a;
        a = a * a;
        power = power >> 1;
    }
    return value;
}

ll power_mod(ll a, ll power, ll mod){
    ll value = 1;
    while(power != 0){
        if(power & 1) value = (value * a) % mod;
        a = (a * a) % mod;
        power = power >> 1;
    }
    return value % mod;
}

ll modinv(ll a, ll mod){
    return power_mod(a, mod - 2, mod);
}

ll combination(ll n, ll r, ll mod){
    if (n == r && n == 0) return 1;
    else if (n <= 0 || r < 0 || r > n) return 0;
    ll numerator = 1;
    ll denomenator = 1;
    for(ll i = 0; i < r ; i++){
        ll num = (n - i) % mod, den = (i + 1) % mod;
        (numerator *= num) %= mod;
        (denomenator *= modinv(den, mod)) %= mod;
    }

    return (numerator * denomenator) % mod;
}

vl2 pascal_triangle(ll n){
    /*
    Complexity: O(n^2)
    The upper bound of n is nearly 50.

    Parameters
    ----------
    n; the size of returned vector

    Returns
    -------
    comb[i][j]: combination(i, j). 0 <= i <= n, 0 <= j <= i
    */

    vl2 comb(n + 1, vl(n + 1));
    comb[0][0] = 1;
    For(i, 1, n + 1) rep(j, i + 1){
        comb[i][j] += comb[i - 1][j];
        if (j > 0) comb[i][j] += comb[i - 1][j - 1];
    }

    return comb;
}

ld log_combination(ll n, ll r){
    if (n == r && n == 0) return 0;
    else if (n <= 0 || r < 0 || r > n) return -INF;
    ld val = 0;
    for(ll i = 0; i < r ; i++){
        val += log(n - i);
        val -= log(i + 1);
    }

    return val;
}

