        Pis.push_back(Pi);
    }
    struct ValInfo {
        ll idx;
        ll value;
    };
    auto comp_val_info_0 = [](ValInfo lhs, ValInfo rhs){ return lhs.value > rhs.value; };
    auto comp_val_info_1 = [](ValInfo lhs, ValInfo rhs){ return lhs.value > rhs.value; };
    priority_queue<ValInfo, vector<ValInfo>, decltype(comp_val_info_0)> queue0(comp_val_info_0);
    priority_queue<ValInfo, vector<ValInfo>, decltype(comp_val_info_1)> queue1(comp_val_info_1);
    vector<ll> right_map0(N, N);
    vector<ll> right_map1(N, N);
    for (ll i = 0; i < N; i++) {
        ll Pi = Pis[i];
        while (!queue1.empty() && queue1.top().value < Pi) {
            ValInfo info = queue1.top();
            queue1.pop();
            right_map1[info.idx] = i;
        }
        while (!queue0.empty() && queue0.top().value < Pi) {
            ValInfo info = queue0.top();
            queue0.pop();
            right_map0[info.idx] = i;
            queue1.push(info);
        }
        queue0.push(ValInfo{i, Pis[i]});
    }
    while (!queue0.empty()) {
        queue0.pop();
    }
    while (!queue1.empty()) {
        queue1.pop();
    }
    vector<ll> left_map0(N, -1);
    vector<ll> left_map1(N, -1);
    for (ll i = N-1; i >= 0; i--) {
        ll Pi = Pis[i];
        while (!queue1.empty() && queue1.top().value < Pi) {
            ValInfo info = queue1.top();
            queue1.pop();
            left_map1[info.idx] = i;
        }
        while (!queue0.empty() && queue0.top().value < Pi) {
            ValInfo info = queue0.top();
            queue0.pop();
            left_map0[info.idx] = i;
            queue1.push(info);
        }
        queue0.push(ValInfo{i, Pis[i]});
    }
    ll ans = 0;
    for (ll i = 0; i < N; i++) {
        ll cnt = 0;
        cnt += (i - left_map0[i]) * (right_map1[i] - right_map0[i]);
        cnt += (right_map0[i] - i) * (left_map0[i] - left_map1[i]);
        ans += cnt * Pis[i];
    }
    cout << ans << endl;
}

