using namespace std;

long long n, a[200000], IT[1000000];

void Input()
{
    ios_base::sync_with_stdio(0);   cin.tie(0);

    cin >> n;
    for (int i=1; i<=n; i++)
        cin >> a[i];
    a[0] = a[n+1] = n + 1;
}

long long Max(int x, int y, int l, int r, int id)
{
    if (r < x || y < l) return -1;

    if (x <= l && r <= y) return IT[id];

    int mid = (l + r) / 2;

    return max(Max(x, y, l, mid, id*2), Max(x, y, mid+1, r, id*2+1));
}

long long pre(int l, int r, int val)
{
    while (r - l > 1)
    {
        int mid = (l + r) / 2,
            k = Max(mid, r-1, 1, n, 1);

        if (k > val) l = mid;
            else r = mid;
    }

    return l;
}

long long suf(int l, int r, int val)
{
    //cout << l << " " << r << endl;
    while (r - l > 1)
    {
        int mid = (l + r) / 2,
            k = Max(l+1, mid, 1, n, 1);

        //cout << l << " " << r << " " << k << " " << val << endl;

        if (k > val) r = mid;
            else l = mid;
    }

    return r;
}

void Update(int l, int r, int pos, int id)
{
    if (!(l <= pos && pos <= r)) return;

    if (l == r) IT[id] = a[pos];
        else
        {
            int mid = (l + r) / 2;

            Update(l, mid, pos, id*2);
            Update(mid+1, r, pos, id*2+1);

            IT[id] = max(IT[id*2], IT[id*2+1]);
        }
}

void Process()
{
    for (int i=1; i<=n; i++)
        Update(1, n, i, 1);

    long long res = 0;

    for (int i=1; i<=n; i++)
    {
        long long pre1 = pre(0, i, a[i]),
                  pre2 = pre(0, pre1, a[i]),
                  suf1 = suf(i, n+1, a[i]),
                  suf2 = suf(suf1, n+1, a[i]);

        //cout << pre2 << " " << pre1 << " " << suf1 << " " << suf2 << endl;

        res += a[i] * ((pre1 - pre2)*(suf1 - i) + (suf2 - suf1)*(i - pre1));
    }

    cout << res;
}

int main()
{
    Input();
    Process();
    return 0;
}

