    auto cmp = [](int a, int b) { return a > b;};

    set<int> larger_idx_right;
    set<int, decltype(cmp)> larger_idx_left(cmp);
    larger_idx_right.insert(value_index[N]);
    larger_idx_left.insert(value_index[N]);

    set<int>::iterator it;

    int ans = 0;

    for(int i = N-1; i > 0; i--) {
        int right_1 = N;
        int right_2 = N;
        it = larger_idx_right.upper_bound(value_index[i]);
        if(it != larger_idx_right.end()) {
            right_1 = *it;
            it = larger_idx_right.upper_bound(right_1);
            if(it != larger_idx_right.end()) {
                right_2 = *it;
            }
        } 

        int left_1 = -1;
        int left_2 = -1;
        it = larger_idx_left.upper_bound(value_index[i]);
        if(it != larger_idx_left.end()) {
            left_1 = *it;
            it = larger_idx_left.upper_bound(left_1);
            if(it != larger_idx_left.end()) {
                left_2 = *it;
            }
        } 

        larger_idx_right.insert(value_index[i]);
        larger_idx_left.insert(value_index[i]);

//        cout << i << " " << left_2 << " " << left_1 << " " << right_1 << " " << right_2 << endl;

        if (right_1 != N) {
            int con = i*(value_index[i]-left_1)*(right_2-right_1);
//            cout << "con right_1 " << con << endl;
            ans += con;
        }
        if (left_1 != -1) {
            int con = i*(right_1-value_index[i])*(left_1-left_2);
//            cout << "cont left 1 " << con << endl;
            ans += con;
        }
    }

    cout << ans << endl;
}

