using namespace std;

struct N {
	int64_t p;
	int64_t i;
};

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	int n; cin >> n;
	vector<N> ps(n);
	FOR_LT(i, 0, n) {
		cin >> ps[i].p;
		ps[i].i = i;
	}

	sort(ps.begin(), ps.end(), [](auto& lhs, auto& rhs) {
		return lhs.p > rhs.p;
	});

	set<int> used;
	int64_t sum = 0;
	for (auto& p : ps) {
		if (used.size() == 0) {
			used.insert(p.i);
			continue;
		}
		if (used.size() == 1) {
			int64_t i = p.i;
			int64_t j = *used.begin();
			if (j < i) swap(i, j);

			sum += p.p * (i + 1) * (n - j);

			used.insert(p.i);
			continue;
		}

		auto itu = used.lower_bound(p.i);
		if (itu == used.begin()) {
			int64_t i = *itu;
			itu++;
			int64_t j = *itu;

			sum += p.p * (p.i + 1) * (j - i);
		}
		else if (itu == used.end()) {
			auto itl = itu;
			itl--;
			int64_t j = *itl;
			itl--;
			int64_t i = *itl;

			sum += p.p * (n - p.i) * (j - i);
		}
		else {
			auto itl = itu;
			itl--;

			int64_t iu = *itu;
			int64_t ju = n;
			itu++;
			if (itu != used.end()) {
				ju = *itu;
			}

			int64_t il = *itl;
			int64_t jl = -1;
			if (itl != used.begin()) {
				itl--;
				jl = *itl;
			}

			sum += p.p * (p.i - il) * (ju - iu);
			sum += p.p * (iu - p.i) * (il - jl);
		}

		used.insert(p.i);
	}

	cout << sum << endl;

	return 0;
}

