void solve(long long N, std::vector<long long> P) {
	multiset<int> s{0, 0, N+1, N+1};
	vector<pair<int, int>> v;
	rep(i, N) {
		v.emplace_back(-P[i], i + 1);
	}
	sort(all(v));
	int res = 0;
	rep(i, N) {
		auto it = s.lower_bound(v[i].second);
		int r1 = *(it++);
		int r2 = *(it--);
		it--;
		int l1 = *(it--);
		int l2 = *it;
		res -= (r2 - r1) * (v[i].second - l1) * v[i].first;
		res -= (r1 - v[i].second) * (l1 - l2) * v[i].first;
		s.insert(v[i].second);
	}
	cout << res << endl;
}

