void upd(int ind , int val)
{   
    if(val == ind)return;
    if(val > ind)
    {
        if(val < num[ind][1].F || num[ind][1].F == -1)
        {
            num[ind][1].S = num[ind][1].F;
            num[ind][1].F = val;
        }
        else if(num[ind][1].S == -1 || val < num[ind][1].S)num[ind][1].S = val;
    }

    else
    {
        if(num[ind][0].F == -1 || num[ind][0].F < val)
        {
            num[ind][0].S = num[ind][0].F;
            num[ind][0].F = val;
        }
        else if(num[ind][0].S == -1 || val > num[ind][0].S)num[ind][0].S = val;
    }
}
void merge(int l , int r)
{   
    int mid = l + (r-l)/2;

    int left = l;int right = mid+1;

    while(left <= mid && right <=r+1)
    {
        while(right <= r && arr[right] < arr[left])right++;

        if(right <= r)upd(arr[left] , arr[right]);
        if(right +1 <=r)upd(arr[left] , arr[right+1]);
        if(right-1 >=mid+1)upd(arr[left] , arr[right-1]);
        if(right-2 >=mid+1)upd(arr[left] , arr[right-2]);
        if(right-3 >=mid+1)upd(arr[left] , arr[right-3]);
        left++;
    }


    int cnt = 0;
    left = l;right = mid+1;
    while(left <= mid && right <= r)
    {
        if(arr[left] <= arr[right])tpa[cnt++] = arr[left++];
        else tpa[cnt++] = arr[right++];
    }

    while(left <= mid)tpa[cnt++] = arr[left++];
    while(right <= r)tpa[cnt++] = arr[right++];

    for(int i = l;i <=r;i++)arr[i] = tpa[i-l];
}

void msort(int l , int r)
{
    if(l >= r)return;
    int mid = l + (r-l)/2;
    msort(l , mid);
    msort(mid+1 , r);
    merge(l , r);
}
