    set<int> found ({-1, N});
    for (int ind : P) {
        if (H[ind] == N) {
            found.insert(ind);
            continue;
        }

        int l0 = *(--found.lower_bound(ind));
        int l1 = (l0 != -1) ? *(--found.lower_bound(l0)) : -1;
        int r0 = *found.upper_bound(ind);
        int r1 = (r0 != N) ? *found.upper_bound(r0) : N;

        int le = (l0 != -1) ? (l0 - l1) * (r0 - ind) : 0;
        int ri = (r0 != N ) ? (r1 - r0) * (ind - l0) : 0;

        total += (le + ri) * H[ind];
        found.insert(ind);
    }

