#define MIN(a, b) (a<b?a:b)
#define MAX(a, b) (a>b?a:b)


int main(int argc, char const* argv[])
{
	int n, i, j;
	int p[100000];
	int ans=0;
	int fst, scnd;
	scanf("%d", &n);
	for(i=0; i<n; i++) {
		scanf("%d", p+i);
	}
	for(i=0; i<n-1; i++) {
		for(j=i+1; j<n; j++) {
			if(j==i+1) {
				fst = MAX(p[i], p[i+1]);
				scnd = MIN(p[i], p[i+1]);
			} else {
				if(p[j] > fst) {
					scnd = fst;
					fst = p[j];
				} else if(p[j] > scnd) {
					scnd = p[j];
				}
			}
			ans += scnd;
		}
	}
	printf("%d\n", ans);

	return 0;
}

