int whichmin(int num1,int num2) {  //小さい数字を返す関数
    if (num1<num2) {
        return num1;
    }
    else {
        return num2;
    }
}

int whichmax(int num1,int num2) {  //大きい数字を返す関数
    if (num1>num2) {
        return num1;
    }
    else {
        return num2;
    }
}

int main(void) {
    int num,temp,dummax,*permutation,i,j,ans=0;
    scanf("%d",&num);
    permutation=malloc(sizeof(int)*100001);  //メモリの動的確保
    for (i=0;i<num;i++) {
        scanf("%d",&permutation[i]);
    }
    for (i=0;i<num-1;i++) {
        for (j=i+1;j<num;j++) {
            if (j==i+1) {
                temp=whichmin(permutation[i],permutation[j]);  //2番目に大きい数
                dummax=whichmax(permutation[i],permutation[j]);  //現段階で１番大きい数
            }
            else {
                if (dummax==whichmax(dummax,permutation[j])) {  //現段階の１番大きい数が１番大きい数の時
                    temp=whichmax(temp,permutation[j]);  //２番目に大きい数はその他の数のうち大きいほう
                }
                else {  //現段階の１番の数が２番目に大きい数になったとき
                    temp=dummax;  //２番目に大きい数は現段階の１番大きい数
                    dummax=permutation[j];  //一番大きい数の更新
                }
            }
            ans+=temp;
        }
    }
    free(permutation);  //メモリの開放
    printf("%d\n",ans);
    return 0;
}

