int main(){
  int n;
  long ans=0;
  scanf("%d",&n);
  int p[3*n-1],l1[n+1],l2[n+1],r1[n+1],r2[n+1];
  for(int i=n;i<=2*n-1;i++){
    scanf("%d",&p[i]);
    p[i-n]=0;
    p[i+n]=0;
    r1[i-n+1]=2*n-i;
    r2[i-n+1]=2*n-i;
    l1[i-n+1]=i-n+1;
    l2[i-n+1]=i-n+1;
  }

  for(int i=n;i<=2*n-1;i++){
    for(int j=1;j<=i-n+1;j++){
      if(p[i-j]>p[i] && l1[i-n+1]!=i-n+1){
        l2[i-n+1]=j;
        break;
      }

      if(p[i-j]>p[i] && l1[i-n+1]==i-n+1){
        l1[i-n+1]=j;
      }
    }
  }

  for(int i=n;i<=2*n-1;i++){
    for(int j=1;j<=2*n-i;j++){
      if(p[i+j]>p[i] && r1[i-n+1]!=2*n-i){
        r2[i-n+1]=j;
        break;
      }

      if(p[i+j]>p[i] && r1[i-n+1]==2*n-i){
        r1[i-n+1]=j;
      }
    }
  }

  for(int i=1;i<=n;i++){
    ans=ans+p[i+n-1]*((l2[i]-l1[i])*r1[i]+(r2[i]-r1[i])*l1[i]);
  }

  printf("%ld",ans);
  return 0;
}

