int secondbig(int a[], int size) {
    int max = 0;
    int secmax = 0;
    for(int i = 0; i < size; i++) {
        if(a[i] > max) max = a[i];
    }
    for(int i = 0; i < size; i++) {
        if(a[i] < max && a[i] > secmax) secmax = a[i];
    }
    return secmax;
}

