int p[100000];

int argmax(int l, int r){
  int nowmax=p[l];
  int maxindex=l;
  for(int i=l+1;i<=r;i++){
    if(p[i]>nowmax){
      maxindex=i;
      nowmax=p[i];
    }
  }
  return maxindex;
}

long secondsum(int l, int r){
  if(r-l<1) return 0;
  long ans;
  int imax,i,j;
  imax=argmax(l,r);
  int ll;
  long firstsum=0;
  int tp2nd;
  for(ll=l;ll<=imax;ll++){
    if(ll==imax) tp2nd=-1;
    else tp2nd=p[ll];
    for(j=ll+1;j<=r;j++){
      if(j!=imax && p[j]>tp2nd) tp2nd=p[j];
      if(j>=imax) firstsum+=tp2nd;
    }
  }
  if(imax==l)
    ans=secondsum(imax+1,r)+firstsum;
  else if(imax==r)
    ans=secondsum(l,imax-1)+firstsum;
  else
    ans=secondsum(l,imax-1)+secondsum(imax+1,r)+firstsum;
  return ans;
}

