//グラフ
#define MAXV (MAXN*MAXN)
int Gv;
typedef struct edge
{
    int to;
    struct edge* next;
}edge;

edge* Ge[MAXV]; //vから出てる有向辺
int Gd[MAXV]; //vの次数

// vは頂点数、指定するときは0～(v-1)
void Ginit(int v)
{
    Gv = v;
}

void Gadd(int v, int to)
{
    edge* e = malloc(sizeof(edge));
    e->to = to;
    e->next = Ge[v];
    Ge[v] = e;
    Gd[v]++;
}

// 最長経路
// 閉路があれば-1
bool GLPvisit[MAXV];
bool GLPfixed[MAXV];
int GLP[MAXV];
int GLP_DFS(int v)
{
    if(GLPvisit[v])
    {
        return GLPfixed[v] ? GLP[v] : -1;
    }
    GLPvisit[v] = true;
    GLP[v] = 0;
    edge* e = Ge[v];
    while(e!=NULL)
    {
        int l = GLP_DFS(e->to);
        if(l == -1) return -1;
        GLP[v] = max(GLP[v], l+1);
        e = e->next;
    }
    GLPfixed[v] = true;
    return GLP[v];
}
int GLongestPath(void)
{
    int lmax = 0;
    for(int i=0;i<Gv;i++)
    {
        int l = GLP_DFS(i);
        if(l==-1)
        {
            return -1;
        }
        lmax = max(lmax, l);
    }
    return lmax;
}

