int p[100000];

int argmax(int l, int r){
  int nowmax=p[l];
  int maxindex=l;
  for(int i=l+1;i<=r;i++){
    if(p[i]>nowmax){
      maxindex=i;
      nowmax=p[i];
    }
  }
  return maxindex;
}

int ascending(int l, int r){
  for(int i=l;i<=r-1;i++){
    if(p[i]>p[i+1]) return 0;
  }
  return 1;
}

int descending(int l, int r){
  for(int i=l;i<=r-1;i++){
    if(p[i]<p[i+1]) return 0;
  }
  return 1;
}

long secondsum(int l, int r){
  long ans=0;
  int imax,i,j;
  int ll[100000];
  int rr[100000];
  long firstsum=0;

  if(r-l<1) return 0;
  if(ascending(l,r)){
    for(i=l;i<=r-1;i++){
      ans+=p[i]*(i-l+1);
    }
    return ans;
  }
  if(descending(l,r)){
    for(i=r;i>=l+1;i--){
      ans+=p[i]*(r-i+1);
    }
    return ans;
  }
  imax=argmax(l,r);
  ll[0]=0;
  for(i=1;i<=imax-l;i++){
    if(p[imax-i]>ll[i-1]) ll[i]=p[imax-i]; else ll[i]=ll[i-1];
  }
  rr[0]=0;
  for(i=1;i<=r-imax;i++){
    if(p[imax+i]>rr[i-1]) rr[i]=p[imax+i]; else rr[i]=rr[i-1];
  }
  for(i=0;i<=imax-l;i++){
    for(j=0;j<=r-imax;j++){
      firstsum+=(ll[i]>rr[j]?ll[i]:rr[j]);
    }
  }

  if(imax==l)
    ans=secondsum(imax+1,r)+firstsum;
  else if(imax==r)
    ans=secondsum(l,imax-1)+firstsum;
  else
    ans=secondsum(l,imax-1)+secondsum(imax+1,r)+firstsum;
  return ans;
}

