long firstsum(int l, int r, int n){
  int i,imax;
  long ans;
  if(l==n && r==n) return 0;
  if(l!=n) imax=l;
  else imax=l+1;
  for(i=l+1;i<=r;i++){
    if(i!=n && p[i]>p[imax]) imax=i;
  }
  if(imax<n){
    ans=p[imax]*(imax-l+1)*(r-n+1)+firstsum(imax+1,r,n);
  }else{
    ans=p[imax]*(n-l+1)*(r-imax+1)+firstsum(l,imax-1,n);
  }
  return ans;
}

