    for(i=l;i<=r-1;i++){
      ans+=p[i]*(i-l+1);
    }
    return ans;
  }
  if(descending(l,r)){
    for(i=r;i>=l+1;i--){
      ans+=p[i]*(r-i+1);
    }
    return ans;
  }
  imax=argmax(l,r);

  if(imax==l)
    ans=secondsum(imax+1,r)+firstsum(l,r,imax);
  else if(imax==r)
    ans=secondsum(l,imax-1)+firstsum(l,r,imax);
  else
    ans=secondsum(l,imax-1)+secondsum(imax+1,r)+firstsum(l,r,imax);
  return ans;
}

