long long bit[525252]={0},bsize=524288;
long long sum(long long i){
    long long s=0;
    while(i>0){
        s+=bit[i];
        i-=i&(-i);
    }
    return s;
}
void add(long long i,long long x){
    while(i<=bsize){
        bit[i]+=x;
        i+=i&(-i);
    }
}

long long bsear(long long x){
  long long st,fi,te;
  st=0;fi=bsize-1;
  while(st<=fi){
    te=(st+fi)/2;
    if(sum(te)<x){st=te+1;}
    else{fi=te-1;}
  }
  return st;
}

