int main(void)
{
  int N;
  scanf("%d", &N);

  int P[N];
  int R[N];
  int L[N];
  int I[N+1];
  int ans = 0;

  for(int i = 0; i < N; i++){
    int p;
    scanf("%d", &p);
    P[i] = p;
    R[i] = L[i] = I[p] =i;
  }

  for(int i = 1; i < N+1; i++){
      int idx = I[i];
      int l = idx - 1;
      int r = idx + 1;
      while(-1 < l && l != L[l])
          l = L[l];
      while(r < N && r != R[r])
          r = R[r];
      L[idx] = l;
      R[idx] = r;

      if(l != -1){
          int l2 = l-1;
          while(-1 < l2 && l2 != L[l2])
              l2 = L[l2];
          ans += i * (l-l2) * (r-idx);
      }
      if(r != N){
          int r2 = r+1;
          while(r2 < N && r2 != R[r2])
              r2 = R[r2];
          ans += i * (idx-l) * (r2-r);
      }
  }
  printf("%d", ans);
  return 0;
}

