		l[0] = BS_right(v, 1, 1, i - 1, P[i]);
		l[1] = BS_right(v, 1, 1, l[0] - 1, P[i]);
		r[0] = BS_left(v, 1, i + 1, N, P[i]);
		r[1] = BS_left(v, 1, r[0] + 1, N, P[i]);
