int p[100000];

int argmax(int l, int r){
  int nowmax=p[l];
  int maxindex=l;
  for(int i=l+1;i<=r;i++){
    if(p[i]>nowmax){
      maxindex=i;
      nowmax=p[i];
    }
  }
  return maxindex;
}

long secondsum(int l, int r){
  if(r-l<1) return 0;
  long ans;
  int imax,i,j;
  imax=argmax(l,r);
  int ll[100000];
  int rr[100000];
  long firstsum=0;
  ll[0]=0;
  for(i=1;i<=imax-l;i++){
    if(p[imax-i]>ll[i-1]) ll[i]=p[imax-i]; else ll[i]=ll[i-1];
  }
  rr[0]=0;
  for(i=1;i<=r-imax;i++){
    if(p[imax+i]>rr[i-1]) rr[i]=p[imax+i]; else rr[i]=rr[i-1];
  }
  for(i=0;i<=imax-l;i++){
    for(j=0;j<=r-imax;j++){
      firstsum+=(ll[i]>rr[j]?ll[i]:rr[j]);
    }
  }

  if(imax==l)
    ans=secondsum(imax+1,r)+firstsum;
  else if(imax==r)
    ans=secondsum(l,imax-1)+firstsum;
  else
    ans=secondsum(l,imax-1)+secondsum(imax+1,r)+firstsum;
  return ans;
}

