fun main(args: Array<String>) {
    val N = readLine()!!.toInt()
    val P = readLine()!!.split(" ").map{it.toLong()}

    fun calc(p: List<Long>): Pair<ArrayList<Long>, ArrayList<Long>> {
        val resMx = ArrayList<Long>()
        val res2nd = ArrayList<Long>()
        val Q = ArrayDeque<Pair<Long, Int>>()
        val mp = TreeMap<Long, Int>()

        for (i in p.indices) {
            if (Q.isNotEmpty() && Q.last.first <= p[i]) {
                mp.clear()
            }

            while (Q.isNotEmpty() && Q.last.first <= p[i]) {
                mp[Q.last.first] = Q.last.second
                Q.pollLast()
            }

            if (Q.isEmpty()) {
                resMx.add(i + 1L)
                res2nd.add(i + 1L)
            } else {
                resMx.add(i - Q.last.second.toLong())

                var t = i + 1L
                if (mp.isNotEmpty() && mp.lastKey() >= p[i]) {
                    t = Math.min(t, i - mp.ceilingEntry(p[i]).value.toLong())
                }
                if (Q.size > 1) {
                    val r = Q.pollLast()
                    t = Math.min(t, i - Q.last.second.toLong())
                    Q.addLast(r)
                }
                res2nd.add(t)
            }

            Q.addLast(Pair(p[i], i))
        }

        return Pair(resMx, res2nd)
    }

    val (lMx, l2nd) = calc(P)
    val (rMx, r2nd) = calc(P.reversed())
    rMx.reverse()
    r2nd.reverse()

    var res = 0L
    for (i in P.indices) {
        res += lMx[i] * (r2nd[i] - rMx[i]) * P[i]
        res += (l2nd[i] - lMx[i]) * rMx[i] * P[i]
    }

    println(res)
//    println(simple(P))
}

