fun main(args: Array<String>) {
    val N = readLine()!!.toInt()
    val P = readLine()!!.split(" ").map{it.toLong()}

    fun calc(p: List<Long>): Pair<ArrayList<Long>, ArrayList<Long>> {
        val resMn = ArrayList<Long>()
        val res2nd = ArrayList<Long>()
        val Q = ArrayDeque<Pair<Long, Int>>()
        val mp = TreeMap<Long, Int>()

        for (i in p.indices) {
            val q = N - p[i]
            if (Q.isNotEmpty() && Q.last.first >= q) {
                mp.clear()
            }

            while (Q.isNotEmpty() && Q.last.first >= q) {
                mp[Q.last.first] = Q.last.second
                Q.pollLast()
            }

            if (Q.isEmpty()) {
                resMn.add(i + 1L)
                res2nd.add(i + 1L)
            } else {
                resMn.add(i - Q.last.second.toLong())
                if (mp.isNotEmpty() && mp.firstKey() <= q) {
                    res2nd.add(i - mp.floorEntry(q).value.toLong())
                } else if (Q.size > 1) {
                    val t = Q.pollLast()
                    res2nd.add(i - Q.last.second.toLong())
                    Q.addLast(t)
                } else {
                    res2nd.add(i + 1L)
                }
            }

            Q.addLast(Pair(q, i))
        }

        return Pair(resMn, res2nd)
    }

    val (lMn, l2nd) = calc(P)
    val (rMn, r2nd) = calc(P.reversed())
    rMn.reverse()
    r2nd.reverse()

    var res = 0L
    for (i in P.indices) {
        res += lMn[i] * (r2nd[i] - rMn[i]) * P[i]
        res += (l2nd[i] - lMn[i]) * rMn[i] * P[i]
    }

    println(res)
}

