class IntSetBIT {
    private static final int EMPTY = -1;
    int[] sum;
    int size;

    public IntSetBIT(int n) {
        if (n <= 1)
            n = 2;
        n = Integer.highestOneBit(n - 1) << 1;
        sum = new int[n + 1];
    }

    public void clear() {
        Arrays.fill(sum, 0);
        size = 0;
    }

    public void add(int value) {
        add(value, 1);
    }

    private void add(int value, int number) {
        for (int j = value + 1; j < sum.length; j += j & -j) {
            sum[j] += number;
        }
        size += number;
    }

    public void remove(int value) {
        remove(value, 1);
    }

    private void remove(int value, int number) {
        number = Math.min(number, size(value));
        for (int j = value + 1; j < sum.length; j += j & -j) {
            sum[j] -= number;
        }
        size -= number;
    }

    public int get(int index) {
        int s = 0;
        for (int i = sum.length / 2; i > 0; i >>= 1) {
            if (sum[s | i] <= index) {
                s |= i;
                index -= sum[s | i];
            }
        }
        return s;
    }

    public int indexOf(int value) {
        if (size(value) == 0) {
            return EMPTY;
        }
        return sum(value + 0);
    }

    public int sum(int indexExclusive) {
        return sum1(1 + indexExclusive - 1);
    }

    private int sum1(int indexInclusive) {
        int ret = 0;
        for (int x = indexInclusive; x > 0; x -= x & -x) {
            ret += sum[x];
        }
        return ret;
    }

    public boolean contains(int value) {
        return indexOf(value) != EMPTY;
    }

    public int size() {
        return size;
    }

    public int size(int value) {
        return sum(value + 1) - sum(value);
    }

    public boolean isEmpty() {
        return size() == 0;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("{");
        for (int i = 0; i < size; i++) {
            if (i > 0) {
                sb.append(", ");
            }
            sb.append(get(i));
        }
        sb.append("}");
        return sb.toString();
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        int n = scanner.nextInt();
        ArrayList<Pair> list = new ArrayList<>(n);
        for(int i = 0; i < n; i++) list.add(new Pair(scanner.nextInt(),i));
        Collections.sort(list, Collections.reverseOrder());
        long ans = 0;
        TreeSet<Integer> indices = new TreeSet<>();
        indices.add(list.get(0).b);
        indices.add(n);
        indices.add(-1);
        for(int i =1; i < n; i++) {
            int ind = list.get(i).b;
            int above = indices.ceiling(ind);
            int below = indices.floor(ind);
            if (above != n) {
                int next = indices.ceiling(above+1);
                ans += (long)(ind - below) * (long)(next - above) * list.get(i).a;
            }
            if (below != -1) {
                int next = indices.floor(below - 1);
                ans += (long)(below - next) * (long)(above - ind) * (long) list.get(i).a;
            }
            indices.add(list.get(i).b);
        }
        out.println(ans);
        out.flush();
    }
    static class Pair implements Comparable<Pair> {
        int a,b;
        Pair(int aa, int bb) {
            a = aa; b = bb;
        }
        public int compareTo(Pair o) {
            return a - o.a;
        }
    }
