	static void solve() {
		int n = ni();
		int p[] = na(n);
		int memo[] = new int[n+1];
		for(int i=0;i<n;i++) {
			memo[p[i]] = i;
		}
		TreeSet<Integer> set = new TreeSet<>();
		set.add(-1); set.add(-2);
		set.add(n); set.add(n+1);
		long ans = 0;
		for(int i=n;i>=1;i--) {
			int idx = memo[i];
			int r = set.higher(idx);
			int rr = set.higher(r);
			int l = set.lower(idx);
			int ll = set.lower(l);
			long res = 0;
			//左に自分より大を1つ含む場合
			if(l>=0) {
				res += (l - ll)*(r-idx);
			}
			//右に自分より大を1つ含む場合
			if(r<n) {
				res += (rr - r)*(idx-l);
			}
			ans += res * i;
			set.add(idx);
		}
		out.println(ans);
	}

