	private static int ni() {
		int num = 0, b;
		boolean minus = false;
		while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
			;
		if (b == '-') {
			minus = true;
			b = readByte();
		}

		while (true) {
			if (b >= '0' && b <= '9') {
				num = num * 10 + (b - '0');
			} else {
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	@SuppressWarnings("unused")
	private static long nl() {
		long num = 0;
		int b;
		boolean minus = false;
		while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
			;
		if (b == '-') {
			minus = true;
			b = readByte();
		}

		while (true) {
			if (b >= '0' && b <= '9') {
				num = num * 10 + (b - '0');
			} else {
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

}

import java.io.PrintStream;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = null;
		PrintStream out = null;
		try {
			sc = new Scanner(System.in);
			out = System.out;
			exec(sc, out);
		} catch (Exception e) {
			e.printStackTrace();
			System.exit(1);
		} finally {
			if(out != null) {
				out.close();
			}
			if(sc != null) {
				sc.close();
			}
		}
		System.exit(0);
	}
	public static void exec(final Scanner sc, final PrintStream out) throws Exception{
		final int N = sc.nextInt();
		final int[] P = new int[N+1];
		for(int i=1;i<=N;i++) {
			P[i] = sc.nextInt();
		}

		long score = 0;
		for(int L=1;L<=N-1;L++) {
			int top = P[L];
			int second = 0;
			for(int R=L+1;R<=N;R++) {
				if(top < P[R]) {
					second = top;
					top = P[R];
				}else if(second < P[R]) {
					second = P[R];
				}
				score+=second;
			}
		}
		out.println(score);
	}

}

import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {

    public static void main(String[] args) throws Exception {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            int N = readInt(reader);
            int[] P = readIntArray(reader);

            long sum = 0;

            for (int i = 0; i < N - 1; i++) {
                int first = P[i];
                int second = -1;

                int p;
                for (int j = i + 1; j < N; j++) {
                    p = P[j];
                    if (first < p) {
                        second = first;
                        first = p;
                    } else if (second < p) {
                        second = p;
                    }

                    sum += second;
                }
            }

            System.out.println(sum);
        }
    }

    public static int readInt(BufferedReader reader) throws Exception {
        return Integer.parseInt(reader.readLine());
    }

    public static int[] readIntArray(BufferedReader reader) throws Exception {
        String[] str = reader.readLine().split(" ");
        int[] array = new int[str.length];
        for (int i = 0; i < str.length; i++) {
            array[i] = Integer.parseInt(str[i]);
        }
        return array;
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
		int n = in.nextInt();
		int[] p = new int[n];
		for (int i = 0; i < n; i++)
			p[i] = in.nextInt();
		System.out.println(solve(n, p));
		in.close();
	}

	private static long solve(int n, int[] p) {
		long r = 0;
		int[] f = new int[n];
		int[] s = new int[n];
		for (int i = 0; i < n - 1; i++)
			if (p[i] > p[i + 1]) {
				s[i] = p[i + 1];
				f[i] = p[i];
				r += s[i];
			} else {
				s[i] = p[i];
				f[i] = p[i + 1];
				r += s[i];
			}
		for (int k = 2; k < n; k++)
			for (int i = 0; i < n - k; i++)
				if (f[i] == f[i + 1])
					if (s[i] > s[i + 1]) {
						r += s[i];
					} else {
						s[i] = s[i + 1];
						r += s[i];
					}
				else if (f[i] > f[i + 1])
					if (s[i] > f[i + 1]) {
						r += s[i];
					} else {
						s[i] = f[i + 1];
						r += s[i];
					}
				else if (s[i + 1] > f[i]) {
					f[i] = f[i + 1];
					s[i] = s[i + 1];
					r += s[i];
				} else {
					s[i] = f[i];
					f[i] = f[i + 1];
					r += s[i];
				}
		return r;
	}

}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int N = sc.nextInt();
            int[] P = new int[N + 1];
            for (int i = 0; i < N; i++) {
                P[1 + i] = sc.nextInt();
            }
            int[] indexOf = new int[N + 1];
            for (int i = 0; i < N + 1; i++) {
                indexOf[P[i]] = i;
            }

            IntSetBIT indexSet = new IntSetBIT(N + 3);
            indexSet.add(-1 + 1);
            indexSet.add(-1 + 1);
            indexSet.add(N + 1);
            indexSet.add(N + 1);

            long sum = 0;
            for (int n = N; n >= 1; n--) {
                int index = indexOf[n];
                indexSet.add(index);
                int indexIndex = indexSet.indexOf(index);
                long l2 = indexSet.get(indexIndex - 2);
                long l = indexSet.get(indexIndex - 1);
                long r = indexSet.get(indexIndex + 1);
                long r2 = indexSet.get(indexIndex + 2);
                sum += n * (index - l) * (r2 - r);
                sum += n * (l - l2) * (r - index);
            }

            System.out.println(sum);
        }
    }
}

class IntSetBIT {
    private static final int EMPTY = -1;
    int[] sum;
    int size;

    public IntSetBIT(int n) {
        if (n <= 1)
            n = 2;
        n = Integer.highestOneBit(n - 1) << 1;
        sum = new int[n + 1];
    }

    public void clear() {
        Arrays.fill(sum, 0);
        size = 0;
    }

    public void add(int value) {
        add(value, 1);
    }

    private void add(int value, int number) {
        for (int j = value + 1; j < sum.length; j += j & -j) {
            sum[j] += number;
        }
        size += number;
    }

    public void remove(int value) {
        remove(value, 1);
    }

    private void remove(int value, int number) {
        number = Math.min(number, size(value));
        for (int j = value + 1; j < sum.length; j += j & -j) {
            sum[j] -= number;
        }
        size -= number;
    }

    public int get(int index) {
        int s = 0;
        for (int i = sum.length / 2; i > 0; i >>= 1) {
            if (sum[s | i] <= index) {
                s |= i;
                index -= sum[s | i];
            }
        }
        return s;
    }

    public int indexOf(int value) {
        if (size(value) == 0) {
            return EMPTY;
        }
        return sum(value + 0);
    }

    public int sum(int indexExclusive) {
        return sum1(1 + indexExclusive - 1);
    }

    private int sum1(int indexInclusive) {
        int ret = 0;
        for (int x = indexInclusive; x > 0; x -= x & -x) {
            ret += sum[x];
        }
        return ret;
    }

    public boolean contains(int value) {
        return indexOf(value) != EMPTY;
    }

    public int size() {
        return size;
    }

    public int size(int value) {
        return sum(value + 1) - sum(value);
    }

    public boolean isEmpty() {
        return size() == 0;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("{");
        for (int i = 0; i < size; i++) {
            if (i > 0) {
                sb.append(", ");
            }
            sb.append(get(i));
        }
        sb.append("}");
        return sb.toString();
    }
}

