public void solve() {
	int num = ni();
	int p[] = ni(num);
	LazySegTree stl1 = new LazySegTree(num, 1);
	LazySegTree stl2 = new LazySegTree(num, 1);
	LazySegTree str1 = new LazySegTree(num, num);
	LazySegTree str2 = new LazySegTree(num, num);
	int p2[][] = new int[num][2];
	for(int i = 0; i < num; i ++) {
		p2[i][0] = p[i];
		p2[i][1] = i;
	}
	Arrays.sort(p2, (sort1, sort2) -> Integer.compare(- sort1[0], - sort2[0]));
	long ans = 0;
	for(int i = 0; i < num; i ++) {
		int j = p2[i][1];
		int l1 = - (int)stl1.find(j, j + 1);
		int l2 = - (int)stl2.find(j, j + 1);
		int r1 = (int)str1.find(j, j + 1);
		int r2 = (int)str2.find(j, j + 1);
		ans += (long)(r2 - r1) * (j - l1) * p2[i][0];
		ans += (long)(l1 - l2) * (r1 - j) * p2[i][0];
		stl1.update(j, num, - j);
		stl2.update(j, num, - l1);
		stl2.update(r1, num, - j);
		str1.update(0, j + 1, j);
		str2.update(0, j + 1, r1);
		str2.update(0, l1 + 1, j);
	}
	prtln(ans);
}

class LazySegTree {
	long e = INF;
	long f(long a, long b) { return min(a, b); }
	long e2 = INF;
	long g(long a, long b) { return min(a, b); }

	int n;
	long nodes[];
	long lazy[];

	LazySegTree(long[] a) { init(a); }
	LazySegTree(int len, long x) {
		long a[] = new long[len];
		fill(a, x);
		init(a);
	}
	LazySegTree(int len) { init(len); }

	void init(long[] a) {
		init(a.length);
		for(int i = 0; i < a.length; i ++) {
			nodes[i + n - 1] = a[i];
		}
		for(int i = n - 2; i >= 0; i --) {
			nodes[i] = f(nodes[i * 2 + 1], nodes[i * 2 + 2]);
		}
	}
	void init(int len) {
		n = 1;
		while(n < len) { n *= 2; }
		nodes = new long[n * 2 - 1];
		fill(nodes, e);
		lazy = new long[n * 2 - 1];
		fill(lazy, e2);
		for(int i = n - 2; i >= 0; i --) {
			nodes[i] = f(nodes[i * 2 + 1], nodes[i * 2 + 2]);
		}
	}

	void eval(int k, int l, int r) {
		if(lazy[k] != e2) {
			nodes[k] = g(nodes[k], lazy[k]);
			if(r - l > 1) {
				lazy[k * 2 + 1] = g(lazy[k * 2 + 1], lazy[k]);
				lazy[k * 2 + 2] = g(lazy[k * 2 + 2], lazy[k]);
			}
			lazy[k] = e2;
		}
	}

	void update(int a, int b, long val) { update(a, b, val, 0, 0, n); }
	void update(int a, int b, long val, int k, int l, int r) {
		eval(k, l, r);
		if(b <= l || r <= a) { return; }
		if(a <= l && r <= b) {
			lazy[k] = g(lazy[k], val);
			eval(k, l, r);
			return;
		}
		update(a, b, val, k * 2 + 1, l, (l + r) / 2);
		update(a, b, val, k * 2 + 2, (l + r) / 2, r);
		nodes[k] = f(nodes[k * 2 + 1], nodes[k * 2 + 2]);
	}

	long find(int a, int b) { return find(a, b, 0, 0, n); }
	long find(int a, int b, int k, int l, int r) {
		if(b <= l || r <= a) { return e; }
		eval(k, l, r);
		if(a <= l && r <= b) { return nodes[k]; }
		return f(find(a, b, k * 2 + 1, l, (l + r) / 2), find(a, b, k * 2 + 2, (l + r) / 2, r));
	}
}

	}
}

