public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();

		int[] p = sc.nextIntArray(n);

		int[] pp = new int[n];
		for (int i = 0; i < n; i++) {
			pp[p[i] - 1] = i;
		}

		NavigableSet<Integer> ts = new TreeSet<>();
		ts.add(-2);
		ts.add(-1);
		ts.add(n);
		ts.add(n + 1);
		long ans = 0;
		for (int i = n - 1; i >= 0; i--) {
			int j = pp[i];

			int l = ts.lower(j);
			int r = ts.higher(j);
			if (l == -1 && r == n) {
				ts.add(j);
				continue;
			}

			long cnt = 0;
			int ll = ts.lower(l);
			int rr = ts.higher(r);

			if (l >= 0) {
				cnt += (long)(l - ll) * (r - j);
			}
			if (r < n) {
				cnt += (long)(rr - r) * (j - l);
			}

			ans += (i + 1) * cnt;
			ts.add(j);
		}

		pr.println(ans);
	}

	static class Pair implements Comparable<Pair> {
		int a;
		int b;

		Pair(int a, int b) {
			this.a = a;
			this.b = b;
		}

		@Override
		public int compareTo(Pair o) {
			int result = Integer.compare(a, o.a);
			if (result == 0) {
				result = Integer.compare(b, o.b);
			}
			return result;
		}

		@Override
		public int hashCode() {
			final int prime = 31;
			int result = a;
			result = prime * result + b;
			return result;
		}

		@Override
		public boolean equals(Object obj) {
			if (this == obj)
				return true;
			if (!(obj instanceof Pair))
				return false;

			Pair o = (Pair) obj;
			return a == o.a && b == o.b;
		}

		@Override
		public String toString() {
			//			Pair [xxx, xxxx]
			StringBuilder stmp = new StringBuilder(32);
			stmp.append("Pair [");
			stmp.append(a);
			stmp.append(',');
			stmp.append(' ');
			stmp.append(b);
			stmp.append(']');

			return stmp.toString();
		}
	}

