 //fac, inv, finvテーブルの初期化、これ使う場合はinitComb()で初期化必要
	public static  void initComb(){
		fac[0] = finv[0] = inv[0] = fac[1] = finv[1] = inv[1] = 1;
		for (int i = 2; i < size; ++i) {
			fac[i] = fac[i - 1] * i % mod;
			inv[i] = mod - (mod / i) * inv[(int) (mod % i)] % mod;
			finv[i] = finv[i - 1] * inv[i] % mod;
		}
	}

	//nCk % mod
	public static long comb(int n, int k){
        if (n < k) return 0;
        if (n < 0 || k < 0) return 0;
		return fac[n] * finv[k] % mod * finv[n - k] % mod;
	}

	//n! % mod
	public static long fact(int n){
		return fac[n];
	}

	//(n!)^-1 with % mod
	public static long finv(int n){
		return finv[n];
	}

}

import java.io.*;
import java.util.*;

public class Main {
	static int[] p;
	static int[][] memo;

	public static void main(String[] args) {
		try {
			BufferedReader br = createBufferedReader();
			String line = br.readLine();
			int N = Integer.parseInt(line);
			line = br.readLine();
			StringTokenizer st = new StringTokenizer(line, " ");
			p = new int[N];
			for (int i = 0; i < N; i++) {
				p[i] = Integer.parseInt(st.nextToken());
			}
			memo = new int[N][N];
			for (int l = 0; l < N - 1; l++) {
				for (int r = l + 1; r < N; r++) {
					memo[l][r] = -1;
				}
			}
			int result = 0;
			for (int l = 0; l < N - 1; l++) {
				for (int r = l + 1; r < N; r++) {
					result += secondMax(l, r);
				}
			}
			System.out.println(result);
		} catch (IOException ioe) {
			ioe.printStackTrace();
		} catch (IllegalArgumentException iae) {
			iae.printStackTrace();
			System.err.println("入力が正しくありません。");
		}

	}

	private static int secondMax(final int l, final int r) {
		if (memo[l][r] != -1) {
			return memo[l][r];
		}
		int max = 0, second = 0;
		int maxi = -1, secondi = -1;
		for (int i = l; i <= r; i++) {
			if (p[i] > max) {
				second = max;
				secondi = maxi;
				max = p[i];
				maxi = i;
			} else if (p[i] > second) {
				second = p[i];
				secondi = i;
			}
		}
		memo[l][r] = second;
		int min_i = min(secondi, maxi);
		int max_i = max(secondi, maxi);
		for (int i = l; i <= min_i; i++) {
			for (int j = r; j >= max_i; j--) {
				memo[i][j] = second;
			}
		}
		return second;
	}

	private static int min(final int a, final int b) {
		return (a < b) ? a : b;
	}

	private static int max(final int a, final int b) {
		return (a > b) ? a : b;
	}

	// 以下問題問わずに共通部分
	// 標準入力の BufferedReader を返す.
	private static BufferedReader createBufferedReader() {
		InputStreamReader isr = new InputStreamReader(System.in);
		return new BufferedReader(isr);
	}
}

import java.util.*;
import java.util.stream.*;
import java.io.*;

public class Main {

  static final long MOD = 1000000007L;
  static final int MAX = 200001;

  static long[] fac = new long[MAX];
  static long[] finv = new long[MAX];

  static long powerMOD(long a, long b){
    long result = 1L;
    while(b > 0){
      if(b % 2 == 1) result = (result * a) % MOD;
      a = (a * a) % MOD;
      b = (b>>1);
    }
    return result;
  }

  static void combIni(){
    fac[0] = 1; fac[1] = 1;
    finv[0] = 1; finv[1] = 1;
    for(int i = 2; i < MAX; i++){
      fac[i] = fac[i-1] * i % MOD;
      finv[i] = finv[i-1] * powerMOD(i, MOD - 2) % MOD;
    }
  }

  static long combMOD(int n, int r){
    if(n < r) return 0;
    if(n < 0 || r < 0) return 0;
    if(r == 0) return 1;
    return fac[n] * (finv[r] * finv[n-r] % MOD) % MOD;
  }
  public static void main(String[] args) throws IOException {

    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    String[] in1 = br.readLine().split(" ");
    int N = Integer.parseInt(in1[0]);

    in1 = br.readLine().split(" ");
    int[] P = Stream.of(in1).mapToInt(Integer::parseInt).toArray();
    br.close();

    combIni();

    int[] posInP = new int[N];

    for(int i = 0; i < N; i++){
      P[i]--;
      posInP[P[i]] = i;
    }

    Set<Integer> largeNumPos = new HashSet<>();
    largeNumPos.add(posInP[N-1]);
    int ans = 0;

    for(int i = N-2; i >= 0; i--){
      int j = posInP[i];
      int rLim1 = j + 1;
      int lLim1 = j - 1;
      for(; rLim1 < N; rLim1++){
        if(largeNumPos.contains(rLim1)) break;
      }
      for(; lLim1 >= 0; lLim1--){
        if(largeNumPos.contains(lLim1)) break;
      }

      int rLim2 = rLim1+1;
      int lLim2 = lLim1-1;
      if(rLim1 < N){
        for(; rLim2 < N; rLim2++){
          if(largeNumPos.contains(rLim2)) break;
        }
        ans += (i + 1) * (j - lLim1) * (rLim2 - rLim1);
      }
      if(lLim1 >= 0){
        for(; lLim2 >= 0; lLim2--){
          if(largeNumPos.contains(lLim2)) break;
        }
        ans += (i + 1) * (lLim1 - lLim2) * (rLim1 - j);
      }

      largeNumPos.add(j);
    }

    System.out.println(ans);
  }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.TreeSet;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(br.readLine());
		String[] sa = br.readLine().split(" ");
		Obj[] arr = new Obj[n];
		for (int i = 0; i < n; i++) {
			Obj o = new Obj();
			o.i = i;
			o.p = Integer.parseInt(sa[i]);
			arr[i] = o;
		}
		br.close();

		Arrays.parallelSort(arr);

		long ans = 0;
		TreeSet<Integer> set = new TreeSet<>();
		for (Obj o : arr) {
			int i = o.i;
			Integer l1 = set.lower(i);
			if (l1 == null) {
				l1 = -1;
			}
			Integer l2 = set.lower(l1);
			if (l2 == null) {
				l2 = -1;
			}

			Integer r1 = set.higher(i);
			if (r1 == null) {
				r1 = n;
			}
			Integer r2 = set.higher(r1);
			if (r2 == null) {
				r2 = n;
			}

			long val = (long) (l1 - l2) * (r1 - i) + (long) (i - l1) * (r2 - r1);
			ans += val * o.p;
			set.add(i);
		}
		System.out.println(ans);
	}

	static class Obj implements Comparable<Obj> {
		int i, p;

		@Override
		public int compareTo(Obj o) {
			return o.p - p;
		}
	}
}

import java.util.*;
