public class Main implements Runnable{

	private void solve(FastIO io) {
		/*
		 * author: 31536000
		 * ABC140 E問題
		 * 考察メモ
		 * 各値について何回参照されるか考える
		 * これは、各値について左右にある"丁度1回だけ"自分より大きい値を含む区間を指す
		 * まず、自分の左右について、自分より大きい値の場所を覚える(全部でO(NlogN)でできる)
		 * そして、左区間: 自分より大きい値以上自分より大きい値より大きい値以下の範囲 + 右側の自分より大きい値未満の範囲
		 * これを右側も同じようにやると求まる、O(N)
		 *
		 */
		int N = io.nextInt();
		int[] P = io.nextInt(N);
		TreeMap<Integer, Integer> where = new TreeMap<>(), map = new TreeMap<>();
		for (int i = 0;i < N;++ i) where.put(P[i], i);
		map.put(N, 1000000000);
		map.put(-1, 1000000000);
		map.put(where.get(N), N);
		long ans = 0;
		for (int i = N;i > 0;-- i) {
			int defaultWhere = where.get(i);
			Integer left = map.lowerEntry(defaultWhere).getKey();
			Integer left2 = Optional.ofNullable(map.lowerEntry(left)).map(e -> e.getKey()).orElse(-1);
			Integer right = map.higherEntry(defaultWhere).getKey();
			Integer right2 = Optional.ofNullable(map.higherEntry(right)).map(e -> e.getKey()).orElse(N);
			ans += Math.max(0L, left - left2) * (right - defaultWhere) * i; // 左側で大きい値を含み、右側で含まない
			ans += Math.max(0L, right2 - right) * (defaultWhere - left) * i; // 右側で大きい値を含み、左側で含まない
			map.put(defaultWhere, i);
		}
		io.println(ans);
	}

