public class Main {

    private static final int MOD = (int)1e9 + 7; //998244353;
    // private static final long INF = (long)1e17;
    private static final int INF = (int)1e9;

    public Main(FastScanner in, PrintWriter out) {
        int N = in.nextInt();
        int[] I = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            I[in.nextInt()] = i;
        }
        long res = 0;
        TreeSet<Integer> set = new TreeSet<>();
        set.add(0);
        set.add(N + 1);
        for (int p = N; p > 0; p--) {
            int i = I[p];
            var S = set.headSet(i, false);
            var it = S.descendingIterator();
            int x = it.next();
            int w = it.hasNext() ? it.next() : 0;

            var T = set.tailSet(i, false);
            it = T.iterator();
            int y = it.next();
            int z = it.hasNext() ? it.next() : N + 1;

            long c = 1L * (y - i) * (x - w) + 1L * (i - x) * (z - y);
            res += c * p;

            set.add(i);
        }
        out.println(res);
    }

    private int gcd(int a, int b) {
        while (true) {
            if (b == 0) return a;
            int tmp = a;
            a = b;
            b = tmp % b;
        }
    }

    private long gcd(long a, long b) {
        while (true) {
            if (b == 0) return a;
            long tmp = a;
            a = b;
            b = tmp % b;
        }
    }

    private long powm(long x, long p) {
        long res = 1;
        while (p > 0) {
            if (p % 2 == 1)
                res = res * x % MOD;
            x = x * x % MOD;
            p /= 2;
        }
        return res;
    }

