class TupleABC140E implements Cloneable {
    int max;
    int max2;
    TupleABC140E() {
        this.max = 0;
        this.max2 = 0;
    }
    void add(int a) {
        int b = this.max;
        int c = this.max2;
        this.max = Math.max(a, b);
        this.max2 = Math.max(Math.min(a, b), c);
    }
    @Override
    public TupleABC140E clone() {
        TupleABC140E tuple = new TupleABC140E();
        tuple.max = this.max;
        tuple.max2 = this.max2;
        return tuple;
    }
}

