class Main{
    public static void main(String[] args){
        FastScanner fsc=new FastScanner();
        int n=fsc.nextInt();
        int[] a=new int[n+1];
        int[] rev=new int[n+1];
        for(int i=1;i<=n;i++){
            a[i]=fsc.nextInt();
