			Integer l2 = l1 == null ? null : s.lower(l1);
			if (l1 == null && r1 == null) continue;

			int ll1 = idx[i] + 1, ll2 = 0, lr1 = n - idx[i], lr2 = 0;
			if (r1 != null) {
				lr1 = r1 - idx[i];
				lr2 = n - r1;
			}
			if (r2 != null) {
				lr2 = r2 - r1;
			}

			if (l1 != null) {
				ll1 = idx[i] - l1;
				ll2 = l1 + 1;
			}

			if (l2 != null) {
				ll2 = l1 - l2;
			}

			answer += ((long) ll1 * lr2 + ll2 * lr1) * (i + 1);

		}
		System.out.println(answer);
	}
}

