/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        ESecondSum solver = new ESecondSum();
        solver.solve(1, in, out);
        out.close();
    }

    static class ESecondSum {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int[] p = in.readIntArray(n);
            MiscUtils.decreaseByOne(p);

            List<IntIntPair> list = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                list.add(new IntIntPair(p[i], i));
            }
            list.sort(Comparator.reverseOrder());

            TreeSet<Integer> set = new TreeSet<>();
            set.add(n);
            set.add(n + 1);
            int[] next = new int[n];
            int[] next2 = new int[n];
            for (int i = 0; i < n; i++) {
                int idx = list.get(i).second;
                next[idx] = set.higher(idx);
                next2[idx] = set.higher(next[idx]);
                if (next2[idx] == n + 1) next2[idx]--;
                set.add(idx);
            }

            set = new TreeSet<>();
            set.add(-1);
            set.add(-2);
            int[] prev = new int[n];
            int[] prev2 = new int[n];
            for (int i = 0; i < n; i++) {
                int idx = list.get(i).second;
                prev[idx] = set.lower(idx);
                prev2[idx] = set.lower(prev[idx]);
                if (prev2[idx] == -2) prev2[idx]++;
                set.add(idx);
            }

            long ans = 0;
            for (int i = 0; i < n; i++) {
                ans += (long) (p[i] + 1) * (i - prev[i]) * (next2[i] - next[i]);
                ans += (long) (p[i] + 1) * (prev[i] - prev2[i]) * (next[i] - i);
            }
            out.printLine(ans);
        }

    }

    static class MiscUtils {
        public static void decreaseByOne(int[]... arrays) {
            for (int[] array : arrays) {
                for (int i = 0; i < array.length; i++) {
                    array[i]--;
                }
            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int[] readIntArray(int size) {
            int[] array = new int[size];
            for (int i = 0; i < size; i++) {
                array[i] = readInt();
            }
            return array;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class IntIntPair implements Comparable<IntIntPair> {
        public final int first;
        public final int second;

        public IntIntPair(int first, int second) {
            this.first = first;
            this.second = second;
        }

        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (o == null || getClass() != o.getClass()) {
                return false;
            }

            IntIntPair pair = (IntIntPair) o;

            return first == pair.first && second == pair.second;
        }

        public int hashCode() {
            int result = first;
            result = 31 * result + second;
            return result;
        }

        public String toString() {
            return "(" + first + "," + second + ")";
        }

        public int compareTo(IntIntPair o) {
            int value = Integer.compare(first, o.first);
            if (value != 0) {
                return value;
            }
            return Integer.compare(second, o.second);
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void printLine(long i) {
            writer.println(i);
        }

    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author anand.oza
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        ESecondSum solver = new ESecondSum();
        solver.solve(1, in, out);
        out.close();
    }

    static class ESecondSum {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int[] p = in.readIntArray(n);

            long answer = solve(n, p);
            out.println(answer);
        }

        private static long solve(int n, int[] p) {
            int[] pinv = new int[n];
            for (int i = 0; i < n; i++) {
                pinv[p[i] - 1] = i;
            }

            IntMinSegmentTree min = new IntMinSegmentTree(n);
            IntMaxSegmentTree max = new IntMaxSegmentTree(n);

            long answer = 0;
            for (int xminus1 = n - 1; xminus1 >= 0; xminus1--) {
                int x = xminus1 + 1;
                int i = pinv[xminus1];

                min.update(i, i);
                max.update(i, i);

                int firstBiggerOnLeft = max.query(0, i);
                if (firstBiggerOnLeft < 0)
                    firstBiggerOnLeft = -1;
                int secondBiggerOnLeft = firstBiggerOnLeft < 0 ? -1 : max.query(0, firstBiggerOnLeft);
                if (secondBiggerOnLeft < 0)
                    secondBiggerOnLeft = -1;

                int firstBiggerOnRight = min.query(i + 1, n);
                if (firstBiggerOnRight >= n)
                    firstBiggerOnRight = n;
                int secondBiggerOnRight = firstBiggerOnRight >= n ? n : min.query(firstBiggerOnRight + 1, n);
                if (secondBiggerOnRight >= n)
                    secondBiggerOnRight = n;

                long a1 = firstBiggerOnRight >= n ? 0 : ((long) (i - firstBiggerOnLeft)) * (secondBiggerOnRight - firstBiggerOnRight);
                long a2 = firstBiggerOnLeft < 0 ? 0 : ((long) (firstBiggerOnLeft - secondBiggerOnLeft)) * (firstBiggerOnRight - i);
                answer += ((long) x) * (a1 + a2);
            }

            return answer;
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] readIntArray(int n) {
            int[] x = new int[n];
            for (int i = 0; i < n; i++) {
                x[i] = nextInt();
            }
            return x;
        }

    }

    static class IntMinSegmentTree {
        public int size;
        public int[] value;
        protected final int identityElement;

        public IntMinSegmentTree(int size) {
            this.size = size;
            value = new int[2 * size];
            this.identityElement = Integer.MAX_VALUE;
            Arrays.fill(value, identityElement);
        }

        public void update(int i, int v) {
            i += size;
            value[i] = v;
            while (i > 1) {
                i /= 2;
                value[i] = Math.min(value[2 * i], value[2 * i + 1]);
            }
        }

        public int query(int i, int j) {
            int res_left = identityElement, res_right = identityElement;
            for (i += size, j += size; i < j; i /= 2, j /= 2) {
                if ((i & 1) == 1) {
                    res_left = Math.min(res_left, value[i++]);
                }
                if ((j & 1) == 1) {
                    res_right = Math.min(value[--j], res_right);
                }
            }
            return Math.min(res_left, res_right);
        }

    }

    static class IntMaxSegmentTree {
        public int size;
        public int[] value;
        protected final int identityElement;

        public IntMaxSegmentTree(int size) {
            this.size = size;
            value = new int[2 * size];
            this.identityElement = Integer.MIN_VALUE;
            Arrays.fill(value, identityElement);
        }

        public void update(int i, int v) {
            i += size;
            value[i] = v;
            while (i > 1) {
                i /= 2;
                value[i] = Math.max(value[2 * i], value[2 * i + 1]);
            }
        }

        public int query(int i, int j) {
            int res_left = identityElement, res_right = identityElement;
            for (i += size, j += size; i < j; i /= 2, j /= 2) {
                if ((i & 1) == 1) {
                    res_left = Math.max(res_left, value[i++]);
                }
                if ((j & 1) == 1) {
                    res_right = Math.max(value[--j], res_right);
                }
            }
            return Math.max(res_left, res_right);
        }

    }
}

