	void solve() {
		int n = scn.nextInt();
		int[] arr = new int[n + 2];
		for (int i = 1; i <= n; i++) {
			arr[i] = scn.nextInt();
		}
		arr[n + 1] = (int) 1e6;

		n++;
		int[] st = new int[n + 1], left = new int[n + 1], right = new int[n + 1];

		int top = -1;
		for (int i = 1; i <= n; i++) {
			while (top != -1 && arr[st[top]] < arr[i]) {
				top--;
			}
			left[i] = top == -1 ? 0 : st[top];
			st[++top] = i;
		}

		top = -1;
		for (int i = n; i > 0; i--) {
			while (top != -1 && arr[st[top]] < arr[i]) {
				top--;
			}
			right[i] = top == -1 ? n + 1 : st[top];
			st[++top] = i;
		}

		seg = new int[4 * n];
		build(1, 1, n, arr);

		long ans = 0;
		for (int i = 1; i < n; i++) {
			if (arr[i] == n - 1) {
				continue;
			}
			int lf = left[i], rt = right[i];

			long sub = 0;

			// right part
			if (rt != n) {
				int x = i - lf, y;

				int ind = rt == n + 1 ? n : Math.min(n, right[rt] - 1);
				int rv = queryRight(1, 1, n, rt + 1, ind, arr[i]);
				if(rv == 1e6) {
					rv = right[rt];
				}
				y = Math.max(1, rv - rt);

				sub += x * 1L * y;
			}

			// left part
			if (lf != 0) {
				int x = rt - i, y;

				int ind = lf == 0 ? 1 : Math.max(1, left[lf] + 1);
				int rv = queryLeft(1, 1, n, ind, lf - 1, arr[i]);
				if(rv == 0) {
					rv = left[lf];
				}

				y = Math.max(1, lf - rv);

				sub += x * 1L * y;
			}

			ans += sub * arr[i];
		}

		out.println(ans);
	}

	int[] seg;

	int queryLeft(int ind, int l, int r, int si, int li, int val) {
		if (l > li || r < si || l > r) {
			return (int) 0;
		}

		if (l == r) {
			if (seg[ind] > val)
				return l;
			return 0;
		}

		int m = (l + r) >> 1;
		if (l >= si && r <= li) {
			if (seg[2 * ind + 1] > val) {
				return queryLeft(2 * ind + 1, m + 1, r, si, li, val);
			} else {
				return queryLeft(2 * ind, l, m, si, li, val);				
			}
		}

		int a = queryLeft(2 * ind, l, m, si, li, val);
		int b = queryLeft(2 * ind + 1, m + 1, r, si, li, val);

		return Math.max(a, b);
	}

	int queryRight(int ind, int l, int r, int si, int li, int val) {
		if (l > li || r < si || l > r) {
			return (int) 1e6;
		}

		if (l == r) {
			if (seg[ind] > val)
				return l;
			return (int) 1e6;
		}

		int m = (l + r) >> 1;
		if (l >= si && r <= li) {
			if (seg[2 * ind + 1] > val) {
				return queryRight(2 * ind, l, m, si, li, val);
			} else {
				return queryRight(2 * ind + 1, m + 1, r, si, li, val);
			}
		}

		int a = queryRight(2 * ind, l, m, si, li, val);
		int b = queryRight(2 * ind + 1, m + 1, r, si, li, val);

		return Math.min(a, b);
	}

	void build(int ind, int l, int r, int[] arr) {
		if (l == r) {
			seg[ind] = arr[l];
			return;
		}
		int m = (l + r) >> 1;
		build(2 * ind, l, m, arr);
		build(2 * ind + 1, m + 1, r, arr);
		seg[ind] = Math.max(seg[2 * ind], seg[2 * ind + 1]);
	}

