import java.io.*;
import java.util.*;

public class Main {
  private static long solve(int n, int[] ps) {
    /*
    Node[] nodes = new Node[n];
    for (int i = 0; i < n; i++) {
      nodes[i] = new Node(ps[i], i);
    }
    Arrays.sort(nodes, new Comparator<Node>(){
      public int compare(Node n1, Node n2) {
        return n1.originalValue - n2.originalValue;
      }
    });
    */
    TreeMap<Integer, Integer> valueToIndex = new TreeMap<>();
    for (int i = 0; i < n; i++) {
      valueToIndex.put(ps[i], i);
    }
    TreeSet<Integer> indexSet = new TreeSet<>();
    indexSet.add(-1);
    indexSet.add(n);
    int count = 0;
    long answer = 0L;
    for (Map.Entry<Integer, Integer> entry : valueToIndex.descendingMap().entrySet()) {
      int index = entry.getValue();
      int value = entry.getKey();
      indexSet.add(index);

      int higher1 = indexSet.higher(index);
      int lower1 = indexSet.lower(index);
      if (higher1 < n) {
        int higher2 = indexSet.higher(higher1);
        // lower1 < index < higher1 < higher2
        answer += (long)value * (long)(higher2 - higher1) * (long)(index - lower1);
      }
      if (lower1 > -1) {
        int lower2 = indexSet.lower(lower1);
        // lower2 < lower1 < index < higher1
        answer += (long)value * (long)(higher1 - index) * (long)(lower1 - lower2);
      }
    }

    return answer;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int[] ps = reader.nextIntArray(n);
    out.println(solve(n, ps));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

class ContestReader {
  private BufferedReader reader;
  private StringTokenizer tokenizer;

  ContestReader(InputStream in) {
    reader = new BufferedReader(new InputStreamReader(in));
  }

  public String next() {
    while (tokenizer == null || !tokenizer.hasMoreTokens()) {
      try {
        tokenizer = new java.util.StringTokenizer(reader.readLine());
      } catch (Exception e) {
        throw new RuntimeException(e);
      }
    }
    return tokenizer.nextToken();
  }

  public int nextInt() {
    return Integer.parseInt(next());
  }

  public long nextLong() {
    return Long.parseLong(next());
  }

  public double nextDouble() {
    return Double.parseDouble(next());
  }

  public String[] nextArray(int n) {
    String[] array = new String[n];
    for (int i = 0; i < n; i++) {
      array[i] = next();
    }
    return array;
  }

  public int[] nextIntArray(int n) {
    int[] array = new int[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextInt();
    }
    return array;
  }

  public long[] nextLongArray(int n) {
    long[] array = new long[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextLong();
    }
    return array;
  }

  public double[] nextDoubleArray(int n) {
    double[] array = new double[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextDouble();
    }
    return array;
  }

  public int[][] nextIntMatrix(int n, int m) {
    int[][] matrix = new int[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        matrix[i][j] = nextInt();
      }
