        int[] a = new int[n+1];
        for (int i = 0; i < n; i++) {
            int x = sc.nextInt();
            p[i] = x;
            a[x] = i;
        }
        long ans = 0L;
        TreeSet<Integer> set = new TreeSet<>();
        set.add(a[n]);
        for (int i = n-1; i > 0 ; i--) {
            Integer l1, l2, r1, r2;
            l1 = set.lower(a[i]);
            r1 = set.higher(a[i]);
            if(l1 == null) l1 = -1;
            if(r1 == null) r1 = n;
            if(l1 == -1){
                l2 = -1;
            }else{
