               farright = active.ceiling(right+1);
            long cnt = (long)(left-farleft)*(right-loc);
            cnt += (long)(farright-right)*(loc-left);
            //cnt -= (long)(right-loc)*(loc-left);
            res += cnt*v;
            active.add(loc);
         }
         System.out.println(res);
      }
   }

