public class Main {
	static final long MOD=1000000007;//998244353;
	public static void main(String[] args) {
		PrintWriter out = new PrintWriter(System.out);
		InputReader sc=new InputReader(System.in);
		int N=sc.nextInt();
		int[] P=sc.nextIntArray(N);
		HashMap<Integer, Integer> hashMap=new HashMap<>();
		for (int i = 0; i < P.length; i++) {
			hashMap.put(P[i], i+1);
		}
		TreeSet<Integer> treeSet=new TreeSet<>();
		treeSet.add(0);
		treeSet.add(N+1);
		long ans=0;
		for (int i = N; i >= 1; i--) {
			int x=hashMap.get(i);
			treeSet.add(x);
			int b=treeSet.lower(x);
			int c=treeSet.higher(x);
			Integer a=treeSet.lower(b);
			Integer d=treeSet.higher(c);
			if (a==null) {
				a=0;
			}
			if (d==null) {
				d=N+1;
			}
			long X=x-b;
			long Y=b-a;
			long U=d-c;
			long Z=c-x;
			ans+=(Y*Z+X*U)*(long)i;
		}
		System.out.println(ans);
 	}
	static class InputReader { 
		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;
		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    NumPos[] p = new NumPos[N];
    for (int i = 0; i < N; i++) p[i] = new NumPos(scanner.nextInt(), i);
    Arrays.sort(p, (t1, t2) -> t2.num - t1.num);

    List<Integer> pos = new ArrayList<>(Arrays.asList(-1, -1, N, N));
    long res = 0;
    for (int i = 0; i < N; i++) {
      int n = p[i].num;
      int m = p[i].pos;
      int x = -Collections.binarySearch(pos, m) - 1;
      int r1 = pos.get(x);
      int r2 = pos.get(x + 1);
      int l1 = pos.get(x - 1);
      int l2 = pos.get(x - 2);
      res += (r2 - r1) * (m - l1) * n;
      res += (l1 - l2) * (r1 - m) * n;
      pos.add(x, m);
    }
    System.out.println(res);
  }

  private static class NumPos {
    private final int num;
    private final int pos;

    private NumPos(int num, int pos) {
      this.num = num;
      this.pos = pos;
    }
  }
}

