import java.util.Scanner;
import java.util.TreeSet;

public class Main {

	public static void main(String[] args)  {
		Scanner sc = new Scanner(System.in);
		int N = Integer.parseInt(sc.next());
		int[] P = new int[N];
		int[] A = new int[N+1];
		long sum = 0;
		for(int i = 0;i < N;i++) {
			P[i] = Integer.parseInt(sc.next());
			A[P[i]] = i+1;
		}
		sc.close();
		TreeSet<Integer> set = new TreeSet<>();
		set.add(0);
		set.add(N+1);
		set.add(A[N]);
		for(int i = N-1;i >=1;i--) {
			int Xi = A[i];
			long y = set.higher(Xi);
			long z = y < N+1 ? set.higher((int)y) : N+1;
			long x = set.lower(Xi);
			long w = x != 0 ? set.lower((int)x) : 0;
			long C = (x-w)*(y-Xi)+(Xi-x)*(z-y);
			sum += C;
		}
		System.out.println(sum);
	}
}

import java.util.*;
import java.math.*;

public class Main{

    final static int maxn = (int) 1e5 + 7;

    static int[] a = new int[maxn];

    static int[] tree = new int[maxn << 2];

    static int n;

    static void build(int l, int r, int node) {
        if(l == r) {
            tree[node] = a[l];
            return;
        }
        int mid = (l + r) >> 1;
        build(l, mid, node<<1);
        build(mid + 1, r, node << 1 | 1);
        tree[node] = Math.max(tree[node<<1], tree[node<<1|1]);
    }

    static int query(int l, int r, int node, int ql, int qr) {
        if(ql <= l && qr >= r) return tree[node];
        int mid = (l + r) >> 1;
        int res = 0;
        if(ql <= mid) res = Math.max(res, query(l, mid, node<<1, ql, qr));
        if(qr > mid)  res = Math.max(res, query(mid+1, r, node<<1|1, ql, qr));
        return res;
    }

    static long get_left(int k, int l, int r) {
        long ans = -1;
        while(l <= r){
            int mid = (l + r) >> 1;
            if(query(1, n, 1, mid, r) > a[k]) {
                ans = mid;
                l = mid + 1;
            }
            else r = mid - 1;
        }
        return ans;
    }

    static long get_right(int k, int l, int r) {
        long ans = -1;
        while(l <= r){
            int mid = (l + r) >> 1;
            if(query(1, n, 1, l, mid) > a[k]) {
                ans = mid;
                r = mid - 1;
            }
            else l = mid + 1;
        }
        return ans;
    }

    public static void main(String[] args){
        Scanner cin = new Scanner(System.in);
        while(cin.hasNext()) {
            n = cin.nextInt();
            for(int i=1; i<=n; i++) a[i] = cin.nextInt();
            build(1, n, 1);
            long ans = 0;
            for(int i=1; i<=n; i++) {
                long pl1 = get_left(i, 1, i-1);
                long pl2 = pl1 == -1 ? -1 : get_left(i, 1, (int)pl1 - 1);
                long pr1 = get_right(i, i+1, n);
                long pr2 = pr1 == -1 ? -1 : get_right(i, (int)pr1 + 1, n);
                if(pl1 != -1 && pl2 != -1 && pr1 != -1 && pr2 != -1) ans += a[i] * ((pl1 - pl2) * (pr1 - i) + (i - pl1) * (pr2 - pr1));
                if(pl1 != -1 && pl2 != -1 && pr1 != -1 && pr2 == -1) ans += a[i] * ((pl1 - pl2) * (pr1 - i) + (i - pl1) * (n - pr1 + 1));
                if(pl1 != -1 && pl2 != -1 && pr1 == -1 && pr2 == -1) ans += a[i] * ((pl1 - pl2) * (n - i + 1));

                if(pl1 != -1 && pl2 == -1 && pr1 != -1 && pr2 != -1)  ans += a[i] * (pl1 * (pr1 - i) + (i - pl1) * (pr2 - pr1));
                if(pl1 != -1 && pl2 == -1 && pr1 != -1 && pr2 == -1) ans += a[i] * (pl1 * (pr1 - i) + (i - pl1) * (n - pr1 + 1));
                if(pl1 != -1 && pl2 == -1 && pr1 == -1 && pr2 == -1) ans += a[i] * (pl1 * (n - i + 1));

                if(pl1 == -1 && pl2 == -1 && pr1 != -1 && pr2 != -1) ans += a[i] * (i * (pr2 - pr1));
                if(pl1 == -1 && pl2 == -1 && pr1 != -1 && pr2 == -1) ans += a[i] * (i * (n - pr1 + 1));
            }
            System.out.println(ans);
        }
    }

}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Iterator;
import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Main {
  public static void main(String[] args) {
        Scanner std = new Scanner(System.in);
        int count = std.nextInt();
        List<Integer> values = IntStream.range(0, count).map(it -> std.nextInt()).boxed().collect(Collectors.toList());
//        Set<Integer> set = new TreeSet<>();
        Deque<Integer> deque = new ArrayDeque<>();
        List<Integer> indexs = IntStream.range(0, count).boxed().collect(Collectors.toList());
        for (int i = 0; i < count; i++) {
            int value = values.get(i);
            indexs.set(value - 1, i);
        }
        long ans = 0;
        for (int x = count - 1; x >= 0; x--) {
            // x = value
            Integer index = indexs.get(x);


            int appearCount = 0;
//            Deque<Integer> lDeque = new ArrayDeque<>();
            int[] l = new int[2];
            Arrays.fill(l, -1);
            int[] r = new int[2];
            Arrays.fill(r, count);
//            Deque<Integer> rDeque = new ArrayDeque<>();
            {
                deque.add(index);
                deque = deque.stream()
                        .sorted()
                        .collect(Collectors.toCollection(ArrayDeque::new));
                {
                    Iterator it = deque.descendingIterator();
                    while (true) {
                        if (!it.hasNext() || it.next() == index) break;
                    }
                    for (int j = 0; j < 2; j++) {
                        if (!it.hasNext()) {
                            break;
                        }
                        Integer newIndex = (Integer) it.next();
                        l[j] = newIndex;
                    }
                }

                {
                    Iterator it = deque.iterator();
                    while (true) {
                        if (!it.hasNext() || it.next() == index) break;
                    }
                    for (int j = 0; j < 2; j++) {
                        if (!it.hasNext()) {
                            break;
                        }
                        r[j] = (int) it.next();
                    }
                }

                int[] ls = new int[2];
                int[] rs = new int[2];

                ls[0] = index - l[0];
                ls[1] = l[0] - l[1];

                rs[0] = r[0] - index;
                rs[1] = r[1] - r[0];
                appearCount = ls[0] * rs[1] + rs[0] * ls[1];
            }

            ans += appearCount * (x + 1);

        }

        System.out.println(ans);
    }
}

