import java.util.function.Predicate;

public class Main {

  static FastScanner sc = new FastScanner();
  static Output out = new Output(System.out);

  static final int[] dx = {0, 1, 0, -1};
  static final int[] dy = {-1, 0, 1, 0};

  static final long MOD = (long) (1e9 + 7);
  static final long INF = Long.MAX_VALUE / 2;

  static final int e5 = (int) 1e5;

  public static class Solver {
    public Solver() {

      int N = sc.nextInt();

      int[] P = new int[N];
      int[] toi = new int[N];
      for (int i=0; i<N; i++) {
        P[i] = sc.nextInt()-1;
        toi[P[i]] = i;
      }

      BinaryIndexedTree bit = new BinaryIndexedTree(new long[N]);

      long ans = 0;
      for (int p=N-1; p>=0; p--) {
        int i = toi[p];
        int left1 = BinarySearch.binarySearch(j -> bit.sum(j, i) >= 1, 0, i, false);
        int left2 = BinarySearch.binarySearch(j -> bit.sum(j, i) >= 2, 0, i, false);
        int right1 = BinarySearch.binarySearch(j -> bit.sum(i, j+1) >= 1, i, N, true);
        int right2 = BinarySearch.binarySearch(j -> bit.sum(i, j+1) >= 2, i, N, true);

        ans += (long)(p+1) * (left1 - left2) * (right1 - i);
        ans += (long)(p+1) * (right2 - right1) * (i - left1);

        bit.add(i, 1);
      }

      out.println(ans);

    }


    public static class BinarySearch {

      /*
       * [l, r)の区間でchecker.test()を実行する
       * rightOK ... 右側OK左側NGならtrue, 右側NG左側OKならfalse
       */
      public static long binarySearchLong(Predicate<Long> checker, long l, long r, boolean rightOK) {
        long ng, ok;

        if (rightOK) {
          ok = r-1;
          ng = l;
          if (!checker.test(ok)) {
            return r;
          }
          if (checker.test(ng)) {
            return l;
          }
        } else {
          ok = l;
          ng = r-1;
          if (!checker.test(ok)) {
            return l-1;
          }
          if (checker.test(ng)) {
            return r-1;
          }
        }

        /* ok と ng のどちらが大きいかわからないことを考慮 */
        while (Math.abs(ok - ng) > 1) {
          long mid = (ok + ng) / 2;

          if (checker.test(mid)) ok = mid;
          else ng = mid;
        }

        return ok;
      }

      /*
       * [l, r)の区間でchecker.test()を実行する
       */
      public static int binarySearch(Predicate<Integer> checker, int l, int r, boolean rightOK) {

        int ng, ok;

        if (rightOK) {
          ok = r-1;
          ng = l;
          if (!checker.test(ok)) {
            return r;
          }
          if (checker.test(ng)) {
            return l;
          }
        } else {
          ok = l;
          ng = r-1;
          if (!checker.test(ok)) {
            return l-1;
          }
          if (checker.test(ng)) {
            return r-1;
          }
        }

        while (Math.abs(ok - ng) > 1) {
          int mid = (ok + ng) / 2;

          if (checker.test(mid)) ok = mid;
          else ng = mid;
        }

        return ok;
      }

      public static int lowerBound(long[] a, long v) {

        if (a[0] >= v) return 0;

        int l = 0, r = a.length;
        int mid = (r + l) / 2;

        while (r - l > 1) {

          if (a[mid] >= v) r = mid;
          else l = mid;

          mid = (r + l) / 2;
        }

        return r;

      }

      public static int upperBound(long[] a, long v) {

        if (a[0] > v) return 0;

        int l = 0, r = a.length;
        int mid = (r + l) / 2;

        while (r - l > 1) {

          if (a[mid] > v) r = mid;
          else l = mid;

          mid = (r + l) / 2;
        }

        return r;

      }

      public static int count(long[] a, long v) {
        int lower = lowerBound(a, v);
        int upper = upperBound(a, v);
        return upper - lower;
      }

    }


    /*
     * 内部のtreeは1-based
     * add, sumはoneBased次第
     */
    public class BinaryIndexedTree {

      int oneBased = 0;

      int N;
      long[] tree;

      public BinaryIndexedTree(long[] A) {
        this.N = A.length;
        tree = new long[N+1];
        for (int i=1; i<=N; i++) {
          add(i, A[i-1]);
        }
      }

      public void add(int i, long x) {
        i += 1-oneBased;
        while(i <= N) {
          tree[i] += x;
          i += i & (-i);
        }
      }

      public long sum(int i) {
        i += 1-oneBased;
        long res = 0;
        while(i > 0) {
          res += tree[i];
          i -= i & (-i);
        }
        return res;
      }

      //[from, to)の和
      public long sum(int from, int to) {
        return sum(to-1) - sum(from-1);
      }

    }

  }

