public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] p = new int[n];
        for(int i=0; i<n; i++) {
            p[i] = in.nextInt();
        }
        memo = new HashMap<>();

        int s = 0;
        for(int l=0; l<n-1; l++) {
            for(int r=l+1; r<n; r++) {
                s+= get2ndMax(p, l, r);
            }
        }
        System.out.println(s);
    }
    private static Map<String, Integer> memo;
    private static int get2ndMax(int[] p, int l, int r) {
        String key = l + "_" + r;
        if(memo.containsKey(key)) {
            return memo.get(key);
        }
        PriorityQueue<Integer> q = new PriorityQueue<>(r-l, Collections.reverseOrder());
        for(int i=l; i<=r; i++) {
            q.add(p[i]);
        }
        q.poll();
        int result = q.poll();
        memo.put(key, result);
        return result;
    }
}

import java.util.Scanner;
import java.util.TreeMap;

public class Main {
	public static void main(String[] args){

		Scanner sc = new Scanner(System.in);
		// 整数の入力
		int n = sc.nextInt();

		int[] a = new int[n];
		int[] b = new int[n+1];

		for(int i =0;i<n;i++) {
			a[i]= sc.nextInt();
			b[a[i]]=i;
		}
		b[0]=-1;

		TreeMap<Integer,Integer> treeMap = new TreeMap<>();
		treeMap.put(-1,n+1);
		treeMap.put(n, n+1);
		treeMap.put(b[n], n);


		long sum = 0;

		for(long i=n-1;i>=1;i--) {
			treeMap.put(b[(int) i], (int) i);
			long lu = treeMap.higherKey(b[(int) i]);
			long uu = n;
			if(lu<n) {
				uu = treeMap.higherKey((int) lu);
			}
			long ul = treeMap.lowerKey(b[(int) i]);
			long ll = -1;
			if(ul>-1) {
				ll = treeMap.lowerKey((int) ul);
			}
			sum+=((ul-ll)*(lu-b[(int) i])+(uu-lu)*(b[(int) i]-ul))*i;

		}


		System.out.println(sum);
	}
}

