public class Main {
    static class Elem {
        final int i;
        final int p;
        Elem(int i, int p) {
            this.i = i;
            this.p = p;
        }
        int p() {
            return p;
        }
    }
    static void solve(MyScanner in, MyWriter out) {
        int N = in.nextInt();
        int[] P = in.nextIntArray(N);
        Elem[] elements = new Elem[N];
        for (int i = 0; i < N; i++) {
            elements[i] = new Elem(i, P[i]);
        }
        Arrays.sort(elements, Comparator.comparingInt(Elem::p));
        NavigableSet<Integer> s = new TreeSet<>();
        s.add(-1);
        s.add(N);
        long ans = 0;
        for (int i = N - 1; i >= 0; i--) {
            Elem e = elements[i];
            int x = s.lower(e.i);
            int w = x == -1 ? -1 : s.lower(x);
            int y = s.higher(e.i);
            int z = y == N ? N : s.higher(y);
            long c = (x - w) * (y - e.i) + (e.i - x) * (z - y);
            ans += e.p * c;
            s.add(e.i);
        }
        out.println(ans);
    }

