            //Console.WriteLine(P.AsJoinedString());
            var ans = 0L;

            var sortedP = P.Select((v, i) => new { V = v, N = i }).OrderByDescending(x => x.V);
            var S = new SortedArray<int>(n);
            S.Insert(-1);
            S.Insert(-1);
            S.Insert(n);
            S.Insert(n);

            //var D = new SortedList<long,long>();
            //D.Add(-1, -1);
            //D.Add(-2, -1);
            //D.Add(n, n);
            //D.Add(n+1,n);

            foreach (var elem in sortedP)
            {
                var i = S.Insert(elem.N);
                //var ndx = S.IndexOfKey(elem.N);
                //var w = D.Values[ndx - 2];
                //var x = D.Values[ndx - 1];
                //var y = D.Values[ndx + 1];
                //var z = D.Values[ndx + 2];
                var w = S[i - 2];
                var x = S[i - 1];
                var y = S[i + 1];
