class SortedArray<T>:IEnumerable<T>
      where T : IComparable<T>
    {
        #region フィールド

        List<T> buffer;
        internal T this[int x]
        {
            set { this.buffer[x] = value; }
            get { return this.buffer[x]; }
        }


        #endregion
        #region 初期化

        public SortedArray() : this(256) { }

        public SortedArray(int capacity)
        {
            this.buffer = new List<T>(capacity);
        }

        #endregion
        #region 要素の挿入・削除・検索

        /// <summary>
        /// 要素の挿入。
        /// </summary>
        /// <param name="elem">挿入する要素</param>
        public int Insert(T elem)
        {
            if (this.buffer.Count == 0)
            {
                this.buffer.Add(elem);
                return 0;
            }

            int r = this.buffer.Count - 1;
            int l = 0;
            int comp;
            while (l < r)
            {
                int m = (r + l) >> 1;
                comp = this.buffer[m].CompareTo(elem);
                if (comp > 0) r = m - 1;
                else if (comp < 0) l = m + 1;
                else
                {
                    this.buffer.Insert(m, elem);
                    return m;
                }
            }

            comp = this.buffer[l].CompareTo(elem);
            if (comp < 0)
            {
                this.buffer.Insert(l + 1, elem);
                return l + 1;
            }
            else if (comp > 0)
            {
                this.buffer.Insert(l, elem);
                return l;
            }
            else
            {
                this.buffer.Insert(l, elem);
                return l;
            }
        }

        /// <summary>
        /// 要素の検索。
        /// </summary>
        /// <param name="elem">検索する要素</param>
        /// <returns>要素の位置（見つからなかった場合、配列長）</returns>
        public int IndexOf(T elem)
        {
            if (this.buffer.Count == 0)
                return 0;

            int r = this.buffer.Count - 1;
            int l = 0;
            while (l < r)
            {
                int m = (r + l) >> 1;
                int comp = this.buffer[m].CompareTo(elem);
                if (comp > 0) r = m - 1;
                else if (comp < 0) l = m + 1;
                else return m;
            }

            if (this.buffer[l].CompareTo(elem) == 0)
                return l;
            return this.buffer.Count;
        }

        /// <summary>
        /// テーブル中に要素が含まれているかどうか判別。
        /// </summary>
        /// <param name="elem">探したい要素</param>
        /// <returns>含まれていれば true</returns>
        public bool Contains(T elem)
        {
            return this.IndexOf(elem) != this.buffer.Count;
        }

        /// <summary>
        /// テーブル中の要素を検索。
        /// </summary>
        /// <param name="elem">探したい要素</param>
        /// <returns>含まれていればその要素を、なければ default(T)</returns>
        public T Find(T elem)
        {
            int i = this.IndexOf(elem);
            if (i == this.buffer.Count)
                return default(T);
            return this.buffer[i];
        }

        /// <summary>
        /// 要素の削除。
        /// </summary>
        /// <param name="elem">削除する要素</param>
        public void Erase(T elem)
        {
            int i = this.IndexOf(elem);
            if (i < this.buffer.Count)
                this.buffer.RemoveAt(i);
        }

        #endregion
        #region IEnumerable<T> メンバ

        public IEnumerator<T> GetEnumerator()
        {
            for (int i = 0; i < this.buffer.Count; ++i)
                yield return this.buffer[i];
        }


        IEnumerator IEnumerable.GetEnumerator()
        {
            return this.GetEnumerator();
        }

        #endregion
    }

using System;
using System.Linq;
using CompLib.Collections.Generic;
using CompLib.Util;

public class Program
{
    int N;
    int[] A;
    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.IntArray();

        // iより左　最初A_iより大きいやつ
        var lF = new long[N];

        // iより左、2番目に大きいやつ
        var lS = new long[N];

        var rF = new long[N];
        var rS = new long[N];
        var st1 = new SegmentTree<long>(Math.Max, -1);
        var st2 = new SegmentTree<long>(Math.Min, N);
        for (int i = 0; i < N; i++)
        {
            lF[i] = st1.Query(A[i] + 1, N + 1);
            if (lF[i] != -1)
            {
                st1[A[lF[i]]] = -1;
                lS[i] = st1.Query(A[i] + 1, N + 1);
                st1[A[lF[i]]] = lF[i];
            }
            else
            {
                lS[i] = -1;
            }
            st1[A[i]] = i;

            int j = N - i - 1;
            rF[j] = st2.Query(A[j] + 1, N + 1);
            if (rF[j] != N)
            {
                st2[A[rF[j]]] = N;
                rS[j] = st2.Query(A[j] + 1, N + 1);
                st2[A[rF[j]]] = rF[j];
            }
            else
            {
                rS[j] = N;
            }
            st2[A[j]] = j;
        }

        long ans = 0;


        for (int i = 0; i < N; i++)
        {
            long l = (lF[i] - lS[i]) * (rF[i] - i);
            long r = (i - lF[i]) * (rS[i] - rF[i]);
            ans += (l + r) * A[i];
        }
        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
}

namespace CompLib.Collections.Generic
{
    using System;

    public class SegmentTree<T>
    {
        // 制約に合った2の冪
        private const int N = 1 << 21;
        private T[] _array;

        private T _identity;
        private Func<T, T, T> _operation;

        public SegmentTree(Func<T, T, T> operation, T identity)
        {
            _identity = identity;
            _operation = operation;
            _array = new T[N * 2];
            for (int i = 1; i < N * 2; i++)
            {
                _array[i] = _identity;
            }
        }

        /// <summary>
        /// A[i]をnに更新 O(log N)
        /// </summary>
        /// <param name="i"></param>
        /// <param name="n"></param>
        public void Update(int i, T n)
        {
            i += N;
            _array[i] = n;
            while (i > 1)
            {
                i /= 2;
                _array[i] = _operation(_array[i * 2], _array[i * 2 + 1]);
            }
        }

        private T Query(int left, int right, int k, int l, int r)
        {
            if (r <= left || right <= l)
            {
                return _identity;
            }

            if (left <= l && r <= right)
            {
                return _array[k];
            }

            return _operation(Query(left, right, k * 2, l, (l + r) / 2),
                Query(left, right, k * 2 + 1, (l + r) / 2, r));
        }

        /// <summary>
        /// A[left] op A[left+1] ... op A[right-1]を求める
        /// </summary>
        /// <param name="left"></param>
        /// <param name="right"></param>
        /// <returns></returns>
        public T Query(int left, int right)
        {
            return Query(left, right, 1, 0, N);
        }

        public T this[int i]
        {
            set { Update(i, value); }
            get { return _array[i + N]; }
        }
    }
}

