public class Program
{
    private int N;
    private int[] P;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        P = sc.IntArray();
        for (int i = 0; i < N; i++)
        {
            P[i]--;
        }

        var index = new int[N];

        for (int i = 0; i < N; i++)
        {
            index[P[i]] = i;
        }

        var set1 = new Set<int>();
        set1.Add(N);
        var set2 = new Set<int>((a, b) => -a.CompareTo(b));
        set2.Add(-1);
        long ans = 0;
        for (int i = N - 1; i >= 0; i--)
        {
            // iが2番目になる


            int right = set1[set1.UpperBound(index[i])];
            int left = set2[set2.UpperBound(index[i])];

            // 右側に一番がある

            if (right != N)
            {
                int rr = set1.UpperBound(right);
                int rightright = rr < set1.Count ? set1[rr] : N;
                //Console.WriteLine($"{i} {right}");
                ans += (long)(index[i] - left) * (rightright - right) * (i + 1);
            }

            // 左
            if (left != -1)
            {
                int ll = set2.UpperBound(left);
                int leftleft = ll < set2.Count ? set2[ll] : -1;
                //Console.WriteLine($"{i} {left}");
                ans += (long)(right - index[i]) * (left - leftleft) * (i + 1);
            }

            set1.Add(index[i]);
            set2.Add(index[i]);
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

class Scanner
{
    public Scanner()
    {
        _pos = 0;
        _line = new string[0];
    }

    const char Separator = ' ';
    private int _pos;
    private string[] _line;

    #region スペース区切りで取得

    public string Next()
    {
        if (_pos >= _line.Length)
        {
            _line = Console.ReadLine().Split(Separator);
            _pos = 0;
        }

        return _line[_pos++];
    }

    public int NextInt()
    {
        return int.Parse(Next());
    }

    public long NextLong()
    {
        return long.Parse(Next());
    }

    public double NextDouble()
    {
        return double.Parse(Next());
    }

    #endregion

    #region 型変換

    private int[] ToIntArray(string[] array)
    {
        var result = new int[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = int.Parse(array[i]);
        }

        return result;
    }

    private long[] ToLongArray(string[] array)
    {
        var result = new long[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = long.Parse(array[i]);
        }

        return result;
    }

    private double[] ToDoubleArray(string[] array)
    {
        var result = new double[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = double.Parse(array[i]);
        }

        return result;
    }

    #endregion

    #region 配列取得

    public string[] Array()
    {
        if (_pos >= _line.Length)
            _line = Console.ReadLine().Split(Separator);

        _pos = _line.Length;
        return _line;
    }

    public int[] IntArray()
    {
        return ToIntArray(Array());
    }

    public long[] LongArray()
    {
        return ToLongArray(Array());
    }

    public double[] DoubleArray()
    {
        return ToDoubleArray(Array());
    }

    #endregion
}

