public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		long[] P = GetLongs(N);

		var pair = new Tuple<int, long>[N];
		for(int i = 0; i < N; i++)
			pair[i] = Tuple.Create(i + 1, P[i]);

		Array.Sort(pair, (a, b) => b.Item2.CompareTo(a.Item2));

		var stMin = new SegmentTree<int>(N + 1, N + 1, (a, b) => Math.Min(a, b));
		var stMax = new SegmentTree<int>(N + 1, 0, (a, b) => Math.Max(a, b));

		long ans = 0;
		for(int i = 0; i < N; i++)
		{
			int pos = pair[i].Item1;

			long x = (long)stMax.Query(0, pos);
			long w = (long)stMax.Query(0, (int)x);
			stMax.Update(pos, pos);

			long y = (long)stMin.Query(pos + 1, N + 1);
			long z = (long)stMin.Query((int)y + 1, N + 1);
			stMin.Update(pos, pos);

			long c = (x - w) * (y - (long)pos) + ((long)pos - x) * (z - y);
			ans += c * pair[i].Item2;
		}

		Console.WriteLine(ans);
	}
}


public class SegmentTree<T>
{
	private int N;
	private T INI;
	private Func<T, T, T> Func;
	private T[] dat;

	public SegmentTree(int n, T ini, Func<T, T, T> func)
	{
		N = 1;		
		while(N < n)
			N <<= 1;

		INI = ini;
		Func = func;

		dat = new T[2 * N - 1];
		for(int i = 0; i < 2 * N - 1; i++)
			dat[i] = INI;
	}

	public void Update(int k, T a)
	{
		k += N - 1;
		dat[k] = a;
		while(k > 0)
		{
			k = (k - 1) / 2;
			dat[k] = Func(dat[k * 2 + 1], dat[k * 2 + 2]);
		}
	}

	public T Query(int a, int b, int k = 0, int l = 0, int r = -1)
	{
		if(r == -1)
			r = N;

		if(r <= a || b <= l)
			return INI;

		if(a <= l && r <= b)
			return dat[k];
		else
		{
			T vl = Query(a, b, k * 2 + 1, l, (l + r) / 2);
			T vr = Query(a, b, k * 2 + 2, (l + r) / 2, r);
			return Func(vl, vr);
		}
	}
}


