namespace abc140_e
{
    class Program
    {
        private static readonly Dictionary<Tuple<int, int>, Tuple<int, int>> secondMemo =
            new Dictionary<Tuple<int, int>, Tuple<int, int>>();

        static void Main(string[] args)
        {
            var n = int.Parse(Console.ReadLine());
            var pList = Console.ReadLine().Split(' ').Select(int.Parse).ToList();


            var sum = 0;
            foreach (var rightAt0 in GetRange(1, n))
            {
                foreach (var l in GetRange(0, n - rightAt0))
                {
                    Tuple<int, int> secondMax;
                    var r = l + rightAt0;
                    if (rightAt0 == 1)
                    {
                        var lValue = pList[l];
                        var rValue = pList[r];
                        secondMax = lValue < rValue // (second, first)
                            ? new Tuple<int, int>(lValue, rValue)
                            : new Tuple<int, int>(rValue, lValue);
                    }
                    else
                    {
                        var (second, max) = GetMemo(l, r - 1);
                        secondMax = GetSecondMax(second, max, pList[r]);
                    }

                    sum += secondMax.Item1;
                    Memoization(l, r, secondMax);
                }
            }

            Console.WriteLine(sum);
        }

        private static void Memoization(int l, int r, Tuple<int, int> value)
        {
            secondMemo[new Tuple<int, int>(l, r)] = value;
        }

        private static Tuple<int, int> GetMemo(int l, int r)
        {
            return secondMemo[new Tuple<int, int>(l, r)];
        }

        private static Tuple<int, int> GetSecondMax(int second, int max, int newValue)
        {
            if (second > max)
            {
                throw new ArgumentException("second > max");
            }

            if (newValue < second)
            {
                return new Tuple<int, int>(second, max);
            }

            if (max < newValue)
            {
                return new Tuple<int, int>(max, newValue);
            }

            return new Tuple<int, int>(newValue, max);
        }

        private static IEnumerable<int> GetRange(int from, int until)
        {
            return Enumerable.Range(from, until - from);
        }
    }
}

