    {
        int n = ri;
        List<int> p = new List<int>();
        for(int i = 0; i < n; i++) { p.Add(ri); }
        long q = 0;
        List<int> t = new List<int>();
        int f = 0, g = 0;
        for(int l = 0; l < n - 1; l++)
        {
            if (p[l] > p[l+1]) { f = p[l]; g = p[l+1]; }
            else { f = p[l+1]; g = p[l]; }
            q += g;
            for (int r = l + 2; r < n; r++)
            {
                if (p[r] >= f)
                {
                    g = f;
                    f = p[r];
                }
                else if (p[r] > g)
