namespace AtCoder
{
    class Program
    {
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }

        class BinarySearchTree<T> where T:IComparable<T>
        {
            class node<T> where T:IComparable<T>
            {
                public node<T> left = null;
                public node<T> right = null;
                public T key = default(T);
                public node<T> parent = null;
            }
            node<T> root = null;
            public BinarySearchTree() { }

            public void insert(T z) => _insert(new node<T>() { key = z });
            void _insert(node<T> z)
            {
                node<T> y = null;
                node<T> x = root;
                while (x != null)
                {
                    y = x;
                    if (z.key.CompareTo(x.key) < 0) 
                        x = x.left;
                    else
                        x = x.right;
                }
                if (y == null)
                    root = z;
                else if (z.key.CompareTo(y.key) < 0) 
                {
                    y.left = z;
                    y.left.parent = y;
                }
                else
                {
                    y.right = z;
                    y.right.parent = y;
                }
            }
            public bool find(T v)
            {
                var n = _find(v);
                return n == null ? false : true;
            }
            node<T> _find(T v)
            {
                var x = root;
                while (x != null)
                {
                    if(x.key.CompareTo(v)==0)
                        return x;
                    if (x.key.CompareTo(v) < 0)
                        x = x.right;
                    else
                        x = x.left;
                }
                return null;
            }

            public void delete(T v) => _delete(_find(v));
            void _delete(node<T> n)
            {
                if (n == null)
                    return;
                if (n == root)
                {
                    if (n.left == null && n.right == null)
                        root = null;
                    else if (n.left != null && n.right == null)
                    {
                        root = n.left;
                        root.parent = null;
                    }
                    else if (n.left == null && n.right != null)
                    {
                        root = n.right;
                        root.parent = null;
                    }
                    else
                    {
                        var next = n.right;
                        while (next.left != null)
                            next = next.left;
                        n.key = next.key;
                        _delete(next);
                    }
                    return;
                }
                if (n.left == null && n.right == null)
                {
                    if (n == n.parent.right)
                        n.parent.right = null;
                    else
                        n.parent.left = null;
                }
                else if (n.left != null && n.right == null)
                {
                    n.left.parent = n.parent;
                    if (n == n.parent.right)
                        n.parent.right = n.left;
                    else
                        n.parent.left = n.left;
                }
                else if (n.left == null && n.right != null)
                {
                    n.right.parent = n.parent;
                    if (n == n.parent.right)
                        n.parent.right = n.right;
                    else
                        n.parent.left = n.right;
                }
                else
                {
                    var next = n.right;
                    while (next.left != null)
                        next = next.left;
                    n.key = next.key;
                    _delete(next);
                }
            }

            List<T> preorder;
            public IReadOnlyList<T> PreOrder { get { return preorder.AsReadOnly(); } }
            List<T> inorder;
            public IReadOnlyList<T> InOrder { get { return inorder.AsReadOnly(); } }
            public void order()
            {
                preorder = new List<T>();
                inorder = new List<T>();
                _order(root);
            }
            void _order(node<T> n)
            {
                if (n == null)
                    return;
                preorder.Add(n.key);
                _order(n.left);
                inorder.Add(n.key);
                _order(n.right);
            }
            public bool prev(T v, ref T r)
            {
                var t = _find(v);
                if (null == t)
                    return false;
                if (null != t.left)
                {
                    t = t.left;
                    while (t.right != null)
                        t = t.right;
                    r = t.key;
                    return true;
                }
                while (t.parent != null)
                {
                    if (t.parent.right == t)
                    {
                        r = t.parent.key;
                        return true;
                    }
                    t = t.parent;
                }
                return false;
            }
            public bool next(T v,ref T r)
            {
                var t = _find(v);
                if (null == t)
                    return false;
                if (null != t.right)
                {
                    t = t.right;
                    while (t.left != null)
                        t = t.left;
                    r = t.key;
                    return true;
                }
                while (t.parent != null)
                {
                    if (t.parent.left == t)
                    {
                        r = t.parent.key;
                        return true;
                    }
                    t = t.parent;
                }
                return false;
            }
        }

        static void Main(string[] args)
        {
            var N = Sarray()[0];
            var P = Sarray();
            var bst = new BinarySearchTree<long>();
            var idx = new long[N];
            for (long i = 0; i < N; ++i)
                idx[P[i] - 1] = i;

            long ans = 0L;
            for (var i = N - 1; 0 <= i; --i)
            {
                long ll = -1;
                long l = -1;
                long r = N;
                long rr = N;
                bst.insert(idx[i]);
                bst.prev(idx[i], ref l);
                bst.prev(l, ref ll);
                bst.next(idx[i], ref r);
                bst.next(r, ref rr);
                ans += (i + 1) * ((l - ll) * (r - idx[i]) + (rr - r) * (idx[i] - l));
            }
            WriteLine(ans);
        }
    }
}

