using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
	static void Main(string[] args)
	{
	    int count = int.Parse(Console.ReadLine());
	    var numbers = Console.ReadLine().Split().Select(x => int.Parse(x));

	    int result = 0;
	    for (int i = 0; i < count; i++)
	    {
	        int pairCount = 2;
	        while(true)
	        {
	            if (count < i + pairCount) break;
	            IEnumerable<int> pairList = numbers.Skip(i).Take(pairCount);
 	            result += GetSecondMaximum(pairList.ToList());
 	            pairCount++;
	        }
	    }

	    Console.WriteLine(result);
	}

	private static int GetSecondMaximum(List<int> numbers)
	{
	    int max = numbers.Max();
	    numbers.Remove(max);
	    return numbers.Max();
	}
}

