using System;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder
{
    class Program
    {
        static void Main(string[] args)
        {
            int number = int.Parse(Console.ReadLine());
            int[] inputPs = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();

            long answer = 0;

            List<int> greaterValues = new List<int>{ 0, 0, number + 1, number + 1 };

            // 各値がどの index に存在するかの配列。
            int[] indices = new int[number];
            for(int i = 0; i < number; i++)
            {
                // inputPs 上の位置を 1 ～ n の値で表現
                indices[inputPs[i] - 1] = i + 1;
            }

            // 大きい数字から処理していく
            for(int i = number; i > 0; i--)
            {
                int myPoint = indices[i - 1];
                int point0 = InsertValuesInOrder(myPoint, ref greaterValues);
                long representTime = GetRepresentTime(point0, greaterValues);
                answer += representTime * i;
            }
            Console.WriteLine(answer.ToString());

            return;
        }

        static int InsertValuesInOrder(int value, ref List<int> targetSeq)
        {
            int inf = 0;
            int sup = targetSeq.Count() - 1;
            while (sup - inf > 1)
            {
                int pivot = (sup + inf) / 2;
                if (targetSeq[pivot] < value)
                {
                    inf = pivot;
                }
                else
                {
                    sup = pivot;
                }
            }
            targetSeq.Insert(sup, value);

            return sup;
        }

        static long GetRepresentTime(int myIndex, List<int> largerValuePoints)
        {
            int point0 = largerValuePoints[myIndex];
            int leftPoint2 = largerValuePoints[myIndex - 2];
            int leftPoint1 = largerValuePoints[myIndex - 1];
            int rightPoint1 = largerValuePoints[myIndex + 1];
            int rightPoint2 = largerValuePoints[myIndex + 2];
            int leftFirstValueRange = point0 - leftPoint1;
            int leftSecondValueRange = leftPoint1 - leftPoint2;
            int rightFirstValueRange = rightPoint1 - point0;
            int rightSecondValueRange = rightPoint2 - rightPoint1;
            return leftFirstValueRange * rightSecondValueRange + leftSecondValueRange * rightFirstValueRange;
        }
    }
}

using System;
