public partial class LeftLeaningRedBlackTree<TKey, TValue>
{
    private Node root = null;
    private readonly IComparer<TKey> _comparer;

    public LeftLeaningRedBlackTree() : this(Comparer<TKey>.Default)
    {
    }

    public LeftLeaningRedBlackTree(IComparer<TKey> comparer)
    {
        _comparer = comparer;
    }

    public TValue this[TKey key]
    {
        get { return Find(key); }
        set { Add(key, value); }
    }

    public TValue Find(TKey key)
    {
        return Find(root, key);
    }

    public int Count { get { return root == null ? 0 : root.Count; } }

    private TValue Find(Node h, TKey key)
    {
        while (h != null)
        {
            int cmp = _comparer.Compare(key, h.Key);
            if (cmp == 0)
            {
                return h.Value;
            }
            h = (cmp < 0) ? h.Left : h.Right;
        }
        throw new KeyNotFoundException();
    }

    public int IndexOfLowerBound(TKey key)
    {
        var node = root;
        int index = 0;
        while (node != null)
        {
            int leftCount = node.Left == null ? 0 : node.Left.Count;
            int cmp = _comparer.Compare(key, node.Key);
            if (cmp == 0)
            {
                index += leftCount;
                break;
            }
            else if (cmp < 0)
            {
                node = node.Left;
            }
            else
            {
                index += leftCount + 1;
                node = node.Right;
            }
        }
        return index;
    }

    public TValue At(int index)
    {
        var node = root;
        while (node != null)
        {
            int leftCount = node.Left == null ? 0 : node.Left.Count;
            if (index == leftCount) return node.Value;
            if (index < leftCount)
            {
                node = node.Left;
            }
            else
            {
                node = node.Right;
                index -= leftCount + 1;
            }
        }
        throw new ArgumentOutOfRangeException("index");
    }

    public void Add(TKey key, TValue value)
    {
        root = Add(root, key, value);
        root.Color = Node.BLACK;
    }

    private Node Add(Node h, TKey key, TValue value)
    {
        if (h == null)
        {
            return new Node(key, value);
        }

        if (IsRed(h.Left) && IsRed(h.Right))
        {
            ColorFlip(h);
        }

        int cmp = _comparer.Compare(key, h.Key);
        if (cmp == 0)
        {
            h.Value = value;
        }
        else if (cmp < 0)
        {
            h.Left = Add(h.Left, key, value);
            h.FixCount();
        }
        else
        {
            h.Right = Add(h.Right, key, value);
            h.FixCount();
        }

        if (IsRed(h.Right) && !IsRed(h.Left))
        {
            h = RotateLeft(h);
        }

        if (IsRed(h.Left) && IsRed(h.Left.Left))
        {
            h = RotateRight(h);
        }

        return h;
    }

    public void RemoveMin()
    {
        root = RemoveMin(root);
        if (root != null)
        {
            root.Color = Node.BLACK;
        }
    }

    private Node RemoveMin(Node h)
    {
        if (h.Left == null)
        {
            return null;
        }

        if (!IsRed(h.Left) && !IsRed(h.Left.Left))
        {
            h = MoveRedLeft(h);
        }

        h.Left = RemoveMin(h.Left);
        h.FixCount();
        return FixUp(h);
    }

    public void Remove(TKey key)
    {
        root = Remove(root, key);
        if (root != null)
        {
            root.Color = Node.BLACK;
        }
    }

    private Node Remove(Node h, TKey key)
    {
        if (_comparer.Compare(key, h.Key) < 0)
        {
            if (h.Left == null)
            {
                throw new KeyNotFoundException("key");
            }

            if (!IsRed(h.Left) && !IsRed(h.Left.Left))
            {
                h = MoveRedLeft(h);
            }
            h.Left = Remove(h.Left, key);
            h.FixCount();
        }
        else
        {
            if (IsRed(h.Left))
            {
                h = RotateRight(h);
            }

            if (h.Right == null)
            {
                if (_comparer.Compare(key, h.Key) == 0)
                {
                    return null;
                }

                throw new KeyNotFoundException("key");
            }

            if (!IsRed(h.Right) && !IsRed(h.Right.Left))
            {
                h = MoveRedRight(h);
            }

            if (_comparer.Compare(key, h.Key) == 0)
            {
                h.Value = Find(h.Right, Min(h.Right).Key);
                h.Key = Min(h.Right).Key;
                h.Right = RemoveMin(h.Right);
                h.FixCount();
            }
            else
            {
                h.Right = Remove(h.Right, key);
                h.FixCount();
            }
        }

        return FixUp(h);
    }

    private static Node MoveRedLeft(Node h)
    {
        ColorFlip(h);

        if (IsRed(h.Right.Left))
        {
            h.Right = RotateRight(h.Right);
            h.FixCount();
            h = RotateLeft(h);
            ColorFlip(h);
        }

        return h;
    }

    private static Node MoveRedRight(Node h)
    {
        ColorFlip(h);

        if (IsRed(h.Left.Left))
        {
            h = RotateRight(h);
            ColorFlip(h);
        }

        return h;
    }

    static private Node RotateLeft(Node h)
    {
        Node x = h.Right;
        h.Right = x.Left;
        x.Left = h;

        x.Color = h.Color;
        h.Color = Node.RED;
        h.FixCount();
        x.FixCount();
        return x;
    }

    private static Node RotateRight(Node h)
    {
        Node x = h.Left;
        h.Left = x.Right;
        x.Right = h;

        x.Color = h.Color;
        h.Color = Node.RED;
        h.FixCount();
        x.FixCount();
        return x;
    }

    private static bool IsRed(Node h)
    {
        return h != null && h.Color == Node.RED;
    }

    static private void ColorFlip(Node h)
    {
        h.Color = !h.Color;
        h.Left.Color = !h.Left.Color;
        h.Right.Color = !h.Right.Color;
    }

    static private Node Min(Node h)
    {
        while (h.Left != null)
        {
            h = h.Left;
        }
        return h;
    }

    static private Node FixUp(Node h)
    {
        if (IsRed(h.Right))
        {
            h = RotateLeft(h);
        }

        if (h.Left != null && IsRed(h.Left) && IsRed(h.Left.Left))
        {
            h = RotateRight(h);
        }

        if (IsRed(h.Left) && IsRed(h.Right))
        {
            ColorFlip(h);
        }

        return h;
    }

    private class Node
    {
        public static readonly bool RED = true;
        public static readonly bool BLACK = false;
        public TKey Key;
        public TValue Value;
        public bool Color = RED;
        public Node Left = null;
        public Node Right = null;
        public int Count = 1;
        public Node(TKey key, TValue value)
        {
            this.Key = key;
            this.Value = value;
        }

        public void FixCount()
        {
            this.Count = 1;
            if (Left != null) Count += Left.Count;
            if (Right != null) Count += Right.Count;
        }
    }
}

