        {
            xs[i] = new int[] { -1, -1 };
            bookmarks[0].Push(i);
            for (int k = 0; k < bookmarks.Length; ++k)
            {
                if (k + 1 >= bookmarks.Length)
                {
                    break;
                }

                int ii = Math.Min(seqP.Length, i + 1 + k);
                var t = ii < seqP.Length ? seqP[ii] : long.MaxValue;
                while (bookmarks[k].Any() && seqP[bookmarks[k].Peek()] < t)
                {
                    int j = bookmarks[k].Pop();
                    cache.Push(j);
                    xs[j][k] = ii;
                }
                while (cache.Any())
                {
                    bookmarks[k + 1].Push(cache.Pop());
                }
            }
        }
        Console.Error.WriteLine();
        return xs;
    }
}

