            {
                output[i] = x[i] - 1;
            }
            return output;
        }

        // 元の配列をソートして、ソート後の各要素の、元のインデックスを返す
        private static int[] SortwithIndex(double[] data)
        {
            var index = new int[data.Length];
            for (int i = 0; i < data.Length; i++)
            {
                index[i] = i;
            }
            QSort(data, index, 0, data.Length - 1);
            return index;
        }

        private static void QSort(double[] data, int[] index, int low, int high)
        {
            // 要素数が1以下の領域ができた場合、その領域は確定とする。
            if (high - low < 1)
                return;

            // 1. ピボットとして一つ選びそれをPとする。
            var P = data[(low + high + 1) / 2];

            // 2. 左から順に値を調べ、P以上のものを見つけたらその位置をiとする。
            // 3. 右から順に値を調べ、P以下のものを見つけたらその位置をjとする。
            // 4. iがjより左にあるのならばその二つの位置を入れ替え、2に戻る。ただし、次の2での探索はiの一つ右、次の3での探索はjの一つ左から行う。
            int i = low - 1;
            int j = high + 1;
            while (Scan(data, P, ref i, ref j))
            {
                Swap(data, index, i, j);
            }

            // 5. 2に戻らなかった場合、iの左側を境界に分割を行って2つの領域に分け、そのそれぞれに対して再帰的に1からの手順を行う。
            QSort(data, index, low, i - 1);
            QSort(data, index, i, high);
        }

        private static bool Scan(double[] data, double P, ref int i, ref int j)
        {
            while (data[++i] < P) ;
            while (data[--j] > P) ;
            return i < j;
        }


        private static void Swap(double[] data, int[] index, int i, int j)
        {
            var temp = data[i];
            data[i] = data[j];
            data[j] = temp;
            var temp2 = index[i];
            index[i] = index[j];
            index[j] = temp2;
        }
    }
}

