                int leftExclude = i - firstBiggerLeft;

                int rightExclude = firstBiggerRight - i-1;
                int rightInclude = secondBiggerRight - firstBiggerRight;
                answer += p[i] * (leftInclude * rightExclude + leftExclude * rightInclude);
