public class Spt{
	private readonly int[][] d;
	private readonly int[] l;
	public Spt(int[] a){
		int n=a.Length,m=(int)Log(n,2)+1;
		d=new int[m][];
		d[0]=new int[n];
		l=new int[n+1];
		for(int i=0;i<n;i++){
			d[0][i]=a[i];
			l[i+1]=l[i>>1]+1;
		}
		for(int i=1,k=1;i<m;i++,k<<=1){
			int p=n+1-(k<<1);
			d[i]=new int[p];
			for(int j=0;j<p;j++){d[i][j]=Max(d[i-1][j],d[i-1][j+k]);}
		}
	}
	public int Get(int a,int b){
		if(a>b){a^=b;b^=a;a^=b;}
		int p=l[b-a];
		return Max(d[p][a],d[p][b+1-(1<<p)]);
	}
}
public class Spt2{
	private int[][] he,l;
	private int[] ba;
	private int c;
	private Spt ma;
	public Spt2(int[] a){
		c=17;
		int n=(a.Length/c)+(a.Length%c==0?0:1);
		he=new int[n][];
		l=new int[n][];
		ba=new int[(1<<(c-1))+1];
		int[] ma=new int[n];
		for(int i = 1;i<c;i++) {ba[1<<i]=i;}
		for(int i = 0;i<n;i++) {
			int o=i!=n-1||(a.Length%c)==0?c:(a.Length%c);
			he[i]=new int[o];
			l[i]=new int[o];
			var ll=new LinkedList<int>();
			int p=0;
			for(int j = 0;j<o;j++) {
				he[i][j]=a[i*c+j];
				while(ll.Count>0&&he[i][ll.Last.Value]<=he[i][j]){
					p-=1<<ll.Last.Value;
					ll.RemoveLast();
				}
				ll.AddLast(j);
				p|=1<<j;
				l[i][j]=p;
			}
			ma[i]=a[i*c+ll.First.Value];
		}
		this.ma=new Spt(ma);
	}
	public int Get(int a,int b){
		if(a>b){a^=b;b^=a;a^=b;}
		int a1=a/c,b1=b/c;
		if(a1==b1){
			int q=l[a1][b%c]&~((1<<(a%c))-1);
			return he[a1][ba[q&-q]];
		}
		int f=l[a1][c-1]&~((1<<(a%c))-1);
		int g=l[b1][b%c];
		return a1+1<b1?Max(ma.Get(a1+1,b1-1),Max(he[a1][ba[f&-f]],he[b1][ba[g&-g]])):Max(he[a1][ba[f&-f]],he[b1][ba[g&-g]]);
	}
	static string Binary(long a,int b){
		string s=Convert.ToString(a,2);
		return (b>s.Length?new string('0',b-s.Length):"")+s;
	}
}

