    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        N = cr;
        P = cr.Repeat(N);
        var pq = new PriorityQueue<int, int>(N);
        for (int i = 0; i < P.Length; i++)
            pq.Add(-P[i], i);
        var ss = new Set<int>
        {
            pq.Dequeue().Value
        };
        long res = 0;
        while (pq.Count > 0)
        {
            var ix = pq.Dequeue().Value;
            var node = ss.FindNodeLowerBound(ix);
            int right1 = N;
            int right2 = N;
            int left1 = -1;
            int left2 = -1;
            if (node == null)
            {
                left1 = ss.Max;
                var l = ss.Reversed().Take(2).ToList();
                if (l.Count > 0) left1 = l[0];
                if (l.Count > 1) left2 = l[1];
            }
            else
            {
                right1 = node.Item;
                var r = ss.Enumerate(node).Skip(1).Take(1).ToList();
                if (r.Count > 0) right2 = r[0];
                var l = ss.Enumerate(node, true).Skip(1).Take(2).ToList();
                if (l.Count > 0) left1 = l[0];
                if (l.Count > 1) left2 = l[1];
            }
            res += (long)(right1 - ix) * (left1 - left2) * P[ix];
            res += (long)(ix - left1) * (right2 - right1) * P[ix];

            ss.Add(ix);
        }
        return res;
    }
