		sl.Add(-2,-2);
		sl.Add(-1,-1);
		sl.Add(N,N);
		sl.Add(N+1,N+1);
		long tot = 0;
		for(int i=0;i<N;i++){
			int k = ord[i];
			long v = A[k];
			sl.Add(k,k);
			var idx = sl.IndexOfKey(k);
			var l1 = sl.Keys[idx - 2];
			var l0 = sl.Keys[idx - 1];
