public class Program
{
    public static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        var seqP = Console.ReadLine().Split().Select(x => int.Parse(x)).ToArray();

        Array.Reverse(seqP);
        var lower = SearchNearestGreaters(seqP);
        Array.Reverse(seqP);
        var upper = SearchNearestGreaters(seqP);

        Array.Reverse(lower);
        for (int i = 0; i < lower.Length; ++i)
        for (int j = 0; j < lower[i].Length; ++j)
        {
            lower[i][j] = lower.Length - lower[i][j] - 1;
        }

        var sum = 0L;
        for (int i = 0; i < seqP.Length; ++i)
        {
            var w = lower[i][1];
            var x = lower[i][0];
            var y = upper[i][0];
            var z = upper[i][1];
            sum += seqP[i] * ((x - w) * (y - i) + (i - x) * (z - y));
        }

        Console.WriteLine(sum);
    }

    static int[][] SearchNearestGreaters(int[] seqP)
    {
        var xs = new int[seqP.Length][];
        var bookmarks = new Stack<int>[3];
        for (int i = 0; i < bookmarks.Length; ++i)
        {
            bookmarks[i] = new Stack<int>();
        }
        for (int i = 0; i < seqP.Length; ++i)
        {
            xs[i] = new int[] { -1, -1 };
            bookmarks[0].Push(i);
            for (int k = 0; k < bookmarks.Length; ++k)
            {
                if (k + 1 >= bookmarks.Length)
                {
                    break;
                }

                int ii = Math.Min(seqP.Length, i + 1 + k);
                var t = ii < seqP.Length ? seqP[ii] : long.MaxValue;
                while (bookmarks[k].Any() && seqP[bookmarks[k].Peek()] < t)
                {
                    int j = bookmarks[k].Pop();
                    bookmarks[k + 1].Push(j);
                    xs[j][k] = ii;
                }
            }
        }
        return xs;
    }
}

