		static void Main(string[] args)
		{
			Scanner cin = new Scanner();
			int n = cin.Int();
			int[] p = cin.ArrayInt(n);
			int[] indexes = new int[n];
			for (int i = 0; i < n; i++) {
				indexes[p[i] - 1] = i;
			}

			long ans = 0;
			var temp = new SortedList<int, int>(n);
			for (int i = n - 1; i >= 0; --i) {
				int index = indexes[i];
				temp.Add(index, index);
				int l1 = -1;
				int l2 = -1;
				int r1 = n;
				int r2 = n;

				int current = index;
				int currentIndex = temp.IndexOfKey(index);
				if (currentIndex - 1 >= 0) {
					l1 = temp.Keys[currentIndex - 1];
				}

				if (currentIndex - 2 >= 0) {
					l2 = temp.Keys[currentIndex - 2];
				}

				if (currentIndex + 1 < temp.Count()) {
					r1 = temp.Keys[currentIndex + 1];
				}

				if (currentIndex + 2 < temp.Count()) {
					r2 = temp.Keys[currentIndex + 2];
				}

				int rangeL1 = current - l1;
				int rangeL2 = l1 - l2;
				int rangeR1 = r1 - current;
				int rangeR2 = r2 - r1;

				ans += (i + 1) * ((long)rangeL2 * rangeR1 + (long)rangeR2 * rangeL1);
			}

			Console.WriteLine(ans);
		}
	}

