				int currentIndex = temp.IndexOfKey(index);
				if (currentIndex - 1 >= 0) {
					l1 = temp.ElementAt(currentIndex - 1).Key;
				}

				if (currentIndex - 2 >= 0) {
					l2 = temp.ElementAt(currentIndex - 2).Key;
				}

				if (currentIndex + 1 < temp.Count()) {
					r1 = temp.ElementAt(currentIndex + 1).Key;
				}

				if (currentIndex + 2 < temp.Count()) {
					r2 = temp.ElementAt(currentIndex + 2).Key;
				}

				int rangeL1 = current - l1;
				int rangeL2 = l1 - l2;
				int rangeR1 = r1 - current;
				int rangeR2 = r2 - r1;

				ans += (i + 1) * ((long)rangeL2 * rangeR1 + (long)rangeR2 * rangeL1);
			}

			Console.WriteLine(ans);
		}
	}

