public class Prog
{
    public void run()
    {
        int N = int.Parse(Console.ReadLine());
        var input = Console.ReadLine().Split();
        int[] P = Array.ConvertAll(input, int.Parse);
        int First = 0;
        int Sec = 0;
        int ans = 0;
        for(int i = 0; i < N-1; i++)
        {
            First = Math.Max(P[i], P[i + 1]);
            Sec = Math.Min(P[i], P[i + 1]);
            ans += Sec;
            for(int j = i + 2; j < N; j++)
            {
                if(P[j] < Sec)
                {
                    ans += Sec;
                }else if(P[j] < First)
                {
                    Sec = P[j];
                    ans += Sec;
                }
                else
                {
                    Sec = First;
                    First = P[j];
                    ans += Sec;
                }
            }
        }
        Console.WriteLine(ans);
    }
    public static void Main()
    {
        var prog = new Prog();
        prog.run();
    }
