    public class Program
    {
        public object Calc()
        {
            var N = consoleReader.Int;
            var p = consoleReader.Split.Int0;
            var pIndex = new int[N];
            for (int i = 0; i < p.Length; i++)
                pIndex[p[i]] = i;

            var lefts = new int[N];
            var rights = new int[N];
            var lefts2 = new int[N];
            var rights2 = new int[N];
            var indexes = new SortedCollection<int>(N);
            indexes.Add(pIndex[pIndex.Length - 1]);
            lefts[pIndex[pIndex.Length - 1]] = -1;
            lefts2[pIndex[pIndex.Length - 1]] = -1;
            rights[pIndex[pIndex.Length - 1]] = N;
            rights2[pIndex[pIndex.Length - 1]] = N;
            for (int i = p.Length - 2; i >= 0; i--)
            {
                var m = indexes.Add(pIndex[i]);
                if (m == indexes.Count - 1)
                {
                    rights[pIndex[i]] = N;
                    rights2[pIndex[i]] = N;
                }
                else if (m == indexes.Count - 2)
                {
                    rights[pIndex[i]] = indexes[m + 1];
                    rights2[pIndex[i]] = N;
                }
                else
                {
                    rights[pIndex[i]] = indexes[m + 1];
                    rights2[pIndex[i]] = indexes[m + 2];
                }


                if (m == 0)
                {
                    lefts[pIndex[i]] = -1;
                    lefts2[pIndex[i]] = -1;
                }
                else if (m == 1)
                {
                    lefts[pIndex[i]] = indexes[m - 1];
                    lefts2[pIndex[i]] = -1;
                }
                else
                {
                    lefts[pIndex[i]] = indexes[m - 1];
                    lefts2[pIndex[i]] = indexes[m - 2];
                }
            }

            var res = new long[N];
            for (int i = 0; i < N; i++)
            {
                res[i] = (lefts[i] - lefts2[i]) * (rights[i] - i)
                    + (i - lefts[i]) * (rights2[i] - rights[i]);
                res[i] *= p[i] + 1;
            }

            return res.Sum();
        }
        class SortedCollection<T> : IList<T>
        {
            List<T> list;

            public SortedCollection() : this(Comparer<T>.Default) { }
            public SortedCollection(int capacity) : this(capacity, Comparer<T>.Default) { }
            public SortedCollection(IComparer<T> comparer) { Comparer = comparer; list = new List<T>(); }
            public SortedCollection(int capacity, IComparer<T> comparer) { Comparer = comparer; list = new List<T>(capacity); }

            public IComparer<T> Comparer { get; }
            public bool IsReadOnly => false;
            public int Count => list.Count;

            public T this[int index]
            {
                get { return list[index]; }
                set { list[index] = value; }
            }
            public int BinarySearch(T item) => ~list.BinarySearch(item, Comparer);

            public int Add(T item)
            {
                var index = BinarySearch(item);
                list.Insert(index, item);
                return index;
            }
            void ICollection<T>.Add(T item) => this.Add(item);

            public void Clear() => list.Clear();
            public bool Contains(T item) => list.Count > BinarySearch(item);
            public void CopyTo(T[] array, int arrayIndex) => list.CopyTo(array, arrayIndex);

            public bool Remove(T item)
            {
                int index = this.IndexOf(item);
                if (index < 0)
                    return false;
                list.RemoveAt(index);
                return true;
            }

            IEnumerator IEnumerable.GetEnumerator() => this.GetEnumerator();
            public IEnumerator<T> GetEnumerator() => list.GetEnumerator();

            public int IndexOf(T item)
            {
                var index = BinarySearch(item);
                if (index < list.Count) return index;
                else return -1;
            }

            public void Insert(int index, T item)
            {
                throw new NotImplementedException();
            }

            public void RemoveAt(int index) => list.RemoveAt(index);

        }

