        static void ABC140E()
        {
            var N = ReadInt();
            var P = ReadIntN();

            var indices = new int[N + 1];

            for (int i = 0; i < N; ++i)
            {
                indices[P[i]]= i;
            }

            var largeIdx = new Util.MultiSet<int>();

            long sum = 0;
            largeIdx.Insert(-1);
            largeIdx.Insert(-1);
            largeIdx.Insert(N);
            largeIdx.Insert(N);

            for (int i = N; i > 0; --i)
            {
                var idx = indices[i];
                largeIdx.Insert(idx);
                var std = largeIdx.LowerBound(idx);
                var idxM2 = largeIdx.ElementAt(Math.Max(0, std - 2));
                var idxM1 = largeIdx.ElementAt(Math.Max(0, std - 1));
                var idxP1 = largeIdx.ElementAt(Math.Min(largeIdx.Count() - 1, std + 1));
                var idxP2 = largeIdx.ElementAt(Math.Min(largeIdx.Count() - 1, std + 2));
                sum += ((long)(idxM1 - idxM2) * (idxP1 - idx) + (long)(idx - idxM1) * (idxP2 - idxP1)) * i;
            }
            Console.WriteLine(sum);
        }

        class Util
        {
            public static readonly long P = 1000000007;

            public static long Sum(long[] array)
            {
                return Sum(array, array.Length);
            }
            public static long Sum(long[] array, int n)
            {
                long total = 0;
                for(int i = 0; i < n; ++i)
                {
                    total += array[i];
                }
                return total;
            }
            public static long Count(long[] array, long x)
            {
