        public static long GetAns(int n, List<int> p)
        {
            var rightLarger = GetRightLarger(p);
            var leftLarger = GetLeftLarger(p);
            var ret = 0L;

            for (int i = 0; i < p.Count(); i++)
            {
                // left: smaller than p[i], right: one element which is larger than p[i]
                var leftCount = GetSmallerLeftCount(rightLarger, leftLarger, i);
                leftCount++;    // add itself
                var rightCount = GetLargerRightCount(p, rightLarger, leftLarger, i);
                ret += (long)leftCount * rightCount * p[i];

                // right: smaller than p[i], left: one element which is larger than p[i]
                leftCount = GetLargerLeftCount(p, rightLarger, leftLarger, i);
                rightCount = GetSmallerRightCount(rightLarger, leftLarger, i);
                rightCount++;   // add itself
                ret += (long)leftCount * rightCount * p[i];
            }

            return ret;
        }

        public static List<int> GetRightLarger(List<int> p)
        {
            var ret = Enumerable.Range(0, p.Count()).Select(v => -1).ToList();
            var que = new PriorityQueue<Node>();

            for (int i = 0; i < p.Count(); i++)
            {
                while(que.Count() > 0 && que.Peek().Val < p[i])
                {
                    var n = que.Pop();
                    ret[n.Idx] = i;
                }
                que.Push(new Node(p[i], i));
            }

            return ret;
        }

        public static List<int> GetLeftLarger(List<int> p)
        {
            var ret = Enumerable.Range(0, p.Count()).Select(v => -1).ToList();
            var que = new PriorityQueue<Node>();

            for (int i = p.Count() - 1; i >= 0; i--)
            {
                while (que.Count() > 0 && que.Peek().Val < p[i])
                {
                    var n = que.Pop();
                    ret[n.Idx] = i;
                }
                que.Push(new Node(p[i], i));
            }

            return ret;
        }

        public static int GetSmallerRightCount(List<int> right, List<int> left, int idx)
        {
            var largeIdx = right[idx];
            largeIdx--;
            return Math.Max(0, largeIdx - idx);
        }

        public static int GetSmallerLeftCount(List<int> right, List<int> left, int idx)
        {
            var largeIdx = left[idx];
            largeIdx++;
            return Math.Max(0, idx - largeIdx);
        }

        public static int GetLargerRightCount(List<int> p, List<int> right, List<int> left, int idx)
        {
            var largeIdx = right[idx];
            if (largeIdx == -1) return 0;
            var largeIdx2 = largeIdx + 1;
            while (largeIdx2 < p.Count() && p[largeIdx2] < p[idx]) largeIdx2++;

            return largeIdx2 - largeIdx;
        }

        public static int GetLargerLeftCount(List<int> p, List<int> right, List<int> left, int idx)
        {
            var largeIdx = left[idx];
            if (largeIdx == -1) return 0;
            var largeIdx2 = largeIdx - 1;
            while (largeIdx2 >= 0 && p[largeIdx2] < p[idx]) largeIdx2--;

            return largeIdx - largeIdx2;
        }
    }

