        public void Solve(TextReader textReader, IConsole console)
        {
            var cin = new ConsoleInput(textReader);

            int N = cin.ReadInt;
            int[] P = cin.ReadIntArray(N);

            int[] indexes = new int[N];

            for (int i = 0; i < N; i++)
            {
                indexes[P[i] - 1] = i;
            }

            RBTree<int, Node> rbt = new RBTree<int, Node>();

            long sum = 0;

            for (int v = N - 1; v >= 0; v--)
            {
                int index = indexes[v];

                rbt.Add(index, new Node(index, index));

                var currentNode = rbt.GetNode(index);

                var node = currentNode;

                int[] l = new int[2];

                for (int k = 0; k < 2; k++)
                {
                    node = rbt.GetNextSmaller(node);

                    if (node.IsSentinelNode)
                    {
                        l[k] = -1;
                    }
                    else
                    {
                        l[k] = node.Key;
                    }
                }

                int[] r = new int[2];

                node = currentNode;

                for (int k = 0; k < 2; k++)
                {
                    node = rbt.GetNextLarger(node);

                    if (node.IsSentinelNode)
                    {
                        r[k] = N;
                    }
                    else
                    {
                        r[k] = node.Key;
                    }
                }

                int[] ls = new int[2];
                int[] rs = new int[2];

                ls[0] = index - l[0];
                ls[1] = l[0] - l[1];

                rs[0] = r[0] - index;
                rs[1] = r[1] - r[0];

                long c = (long)ls[0] * rs[1] + (long)ls[1] * rs[0];

                sum += c * (v + 1);
            }

            console.WriteLine(sum.ToString());
        }
