    public static class BTreePrinter<TKey, TValue>
        where TKey : IComparable, IComparable<TKey>, IEquatable<TKey>
    {
        public static RBNode<TKey, TValue> SentinelNode = RBTree<TKey, TValue>.SentinelNode;

        class NodeInfo
        {
            public RBNode<TKey, TValue> Node;
            public string Text;
            public int StartPos;

            public int Size
            {
                get { return Text.Length; }
            }

            public int EndPos
            {
                get { return StartPos + Size; }
                set { StartPos = value - Size; }
            }

            public NodeInfo Parent, Left, Right;
        }

        public static void PrintTree(RBNode<TKey, TValue> root, int spacing = 1, int topMargin = 2, int leftMargin = 2)
        {
            if (root == SentinelNode) return;
            int rootTop = Console.CursorTop + topMargin;
            var last = new List<NodeInfo>();
            var next = root;
            for (int level = 0; next != SentinelNode; level++)
            {
                var item = new NodeInfo {Node = next, Text = next.ToString()};

                if (item.Node.Data.ToString() == 48.ToString())
                {
                    int i = 124;
                }

                if (level < last.Count)
                {
                    item.StartPos = last[level].EndPos + spacing;
                    last[level] = item;
                }
                else
                {
                    item.StartPos = leftMargin;
                    last.Add(item);
                }

                if (level > 0)
                {
                    item.Parent = last[level - 1];
                    if (next == item.Parent.Node.Left)
                    {
                        item.Parent.Left = item;
                        item.EndPos = Math.Max(item.EndPos, item.Parent.StartPos - 1);
                    }
                    else
                    {
                        item.Parent.Right = item;
                        item.StartPos = Math.Max(item.StartPos, item.Parent.EndPos + 1);
                    }
                }

                next = next.Left != SentinelNode ? next.Left : next.Right;
                for (; next == SentinelNode; item = item.Parent)
                {
                    int top = rootTop + 2 * level;
                    Print(item.Text, top, item.StartPos);
                    if (item.Left != null)
                    {
                        Print("/", top + 1, item.Left.EndPos);
                        Print("_", top, item.Left.EndPos + 1, item.StartPos);
                    }

                    if (item.Right != null)
                    {
                        Print("_", top, item.EndPos, item.Right.StartPos - 1);
                        Print("\\", top + 1, item.Right.StartPos - 1);
                    }

                    if (--level < 0) break;
                    if (item == item.Parent.Left)
                    {
                        item.Parent.StartPos = item.EndPos + 1;
                        next = item.Parent.Node.Right;
                    }
                    else
                    {
                        if (item.Parent.Left == null)
                            item.Parent.EndPos = item.StartPos - 1;
                        else
                            item.Parent.StartPos += (item.StartPos - 1 - item.Parent.EndPos) / 2;
                    }
                }
            }

            Console.SetCursorPosition(0, rootTop + 2 * last.Count - 1);
        }

        private static void Print(string s, int top, int left, int right = -1)
        {
            Console.SetCursorPosition(left, top);
            if (right < 0) right = left + s.Length;
            while (Console.CursorLeft < right) Console.Write(s);
        }
    }


    public class RBNode<TKey, TValue>
        where TKey : IComparable, IComparable<TKey>, IEquatable<TKey>
    {
        public RBNode()
        {
            Color = RBTree<TKey, TValue>.RedBlackNodeType.Red;

            Right = RBTree<TKey, TValue>.SentinelNode;
            Left = RBTree<TKey, TValue>.SentinelNode;
        }

        public RBNode(TKey key, TValue data)
            : this()
        {
            Key = key;
            Data = data;
        }

        public TKey Key { get; set; }
        public TValue Data { get; set; }

        public RBTree<TKey, TValue>.RedBlackNodeType Color { get; set; }

        public RBNode<TKey, TValue> Left { get; set; }
        public RBNode<TKey, TValue> Right { get; set; }
        public RBNode<TKey, TValue> Parent { get; set; }

        public bool IsSentinelNode => this == RBTree<TKey, TValue>.SentinelNode;

        public override string ToString()
        {
            return Key.ToString();
            //return $"{nameof(Key)}: {Key}, {nameof(Data)}: {Data}";
        }
    }

    public class RBTree<TKey, TValue>
        where TKey : IComparable<TKey>, IComparable, IEquatable<TKey>
    {
        public static readonly RBNode<TKey, TValue> SentinelNode = new RBNode<TKey, TValue>
        {
            Color = RedBlackNodeType.Black,
            Left = null,
            Right = null,
            Parent = null,
        };

        public RBNode<TKey, TValue> LastFoundNode = SentinelNode;
        public RBNode<TKey, TValue> RootNode = SentinelNode;
        public int Count;

        public RBTree()
        {
            Count = 0;
        }

        public void Clear()
        {
            RootNode = SentinelNode;
            Count = 0;
        }

        public RBNode<TKey, TValue> GetNode(TKey key)
        {
            int result;
            if (LastFoundNode != SentinelNode)
            {
                result = key.CompareTo(LastFoundNode.Key);
                if (result == 0)
                {
                    return LastFoundNode;
                }
            }

            var treeNode = RootNode;

            while (treeNode != SentinelNode)
            {
                result = key.CompareTo(treeNode.Key);
                if (result == 0)
                {
                    LastFoundNode = treeNode;
                    return treeNode;
                }

                treeNode = result < 0 ? treeNode.Left : treeNode.Right;
            }

            return null;
        }

        public void Add(TKey key, TValue value)
        {
            New(key, value);
        }

        public bool Remove(TKey key)
        {
            var node = GetNode(key);

            if (node == null)
            {
                return false;
            }

            DeleteInternal(node);
            return true;
        }

        public RBNode<TKey, TValue> GetMinNode()
        {
            var currentNode = RootNode;

            if (currentNode == null || currentNode == SentinelNode)
            {
                throw new InvalidOperationException("RedBlackTree is empty.");
            }

            while (currentNode.Left != SentinelNode)
            {
                currentNode = currentNode.Left;
            }

            LastFoundNode = currentNode;

            return currentNode;
        }

        public RBNode<TKey, TValue> GetMaxNode()
        {
            var currentNode = RootNode;

            if (currentNode == null || currentNode == SentinelNode)
            {
                throw new InvalidOperationException("RedBlackTree is empty.");
            }

            while (currentNode.Right != SentinelNode)
            {
                currentNode = currentNode.Right;
            }

            LastFoundNode = currentNode;

            return currentNode;
        }

        public bool IsEmpty()
        {
            return RootNode == SentinelNode;
        }

        public bool RemoveMin()
        {
            if (RootNode == null)
            {
                return false;
            }

            DeleteInternal(GetMinNode());
            return true;
        }

        public bool RemoveMax()
        {
            if (RootNode == null)
            {
                return false;
            }

            DeleteInternal(GetMaxNode());
            return true;
        }

        public RBNode<TKey, TValue> GetNextLarger(RBNode<TKey, TValue> targetNode)
        {
            if (targetNode == SentinelNode)
            {
                return SentinelNode;
            }

            var next = targetNode.Right;

            if (targetNode.Right != SentinelNode)
            {
                while (next.Left != SentinelNode)
                {
                    next = next.Left;
                }

                return next;
            }

            next = targetNode;

            // ここはnull
            while (next.Parent != null)
            {
                if (next.Parent.Left == next)
                {
                    return next.Parent;
                }

                next = next.Parent;
            }

            return SentinelNode;
        }

        public RBNode<TKey, TValue> GetNextSmaller(RBNode<TKey, TValue> targetNode)
        {
            if (targetNode == SentinelNode)
            {
                return SentinelNode;
            }

            var next = targetNode.Left;

            if (targetNode.Left != SentinelNode)
            {
                while (next.Right != SentinelNode)
                {
                    next = next.Right;
                }

                return next;
            }

            next = targetNode;

            // ここはnull
            while (next.Parent != null)
            {
                if (next.Parent.Right == next)
                {
                    return next.Parent;
                }

                next = next.Parent;
            }

            return SentinelNode;
        }

        public enum RedBlackNodeType
        {
            Red = 0,
            Black = 1
        }

        private void New(TKey key, TValue data)
        {
            if (data == null)
            {
                throw new ArgumentNullException(nameof(data));
            }

            var newNode = new RBNode<TKey, TValue>(key, data);

            var currentNode = RootNode;

            while (currentNode != SentinelNode)
            {
                newNode.Parent = currentNode;
                var result = key.CompareTo(currentNode.Key);
                if (result == 0)
                {
                    throw new InvalidOperationException($"RedBlackTree found same key {key}");
                }

                currentNode = result > 0 ? currentNode.Right : currentNode.Left;
            }

            if (newNode.Parent != null)
            {
                if (newNode.Key.CompareTo(newNode.Parent.Key) > 0)
                {
                    newNode.Parent.Right = newNode;
                }
                else
                {
                    newNode.Parent.Left = newNode;
                }
            }
            else
            {
                RootNode = newNode;
            }

            BalanceOnInsert(newNode);

            LastFoundNode = newNode;

            Count++;
        }

        private void DeleteInternal(RBNode<TKey, TValue> deleteNode)
        {
            RBNode<TKey, TValue> currentNode;

            if (deleteNode.Left == SentinelNode || deleteNode.Right == SentinelNode)
            {
                currentNode = deleteNode;
            }
            else
            {
                currentNode = deleteNode.Right;

                while (currentNode.Left != SentinelNode)
                {
                    currentNode = currentNode.Left;
                }
            }

            var linkedNode = currentNode.Left != SentinelNode
                ? currentNode.Left
                : currentNode.Right;

            linkedNode.Parent = currentNode.Parent;
            if (currentNode.Parent != null)
            {
                if (currentNode == currentNode.Parent.Left)
                {
                    currentNode.Parent.Left = linkedNode;
                }
                else
                {
                    currentNode.Parent.Right = linkedNode;
                }
            }
            else
            {
                RootNode = linkedNode;
            }

            if (currentNode != deleteNode)
            {
                deleteNode.Key = currentNode.Key;
                deleteNode.Data = currentNode.Data;
            }

            if (currentNode.Color == RedBlackNodeType.Black)
            {
                BalanceOnDelete(linkedNode);
            }

            LastFoundNode = SentinelNode;

            Count--;
        }

        private void BalanceOnDelete(RBNode<TKey, TValue> linkedNode)
        {
            while (linkedNode != RootNode && linkedNode.Color == RedBlackNodeType.Black)
            {
                RBNode<TKey, TValue> currentNode;

                if (linkedNode == linkedNode.Parent.Left)
                {
                    currentNode = linkedNode.Parent.Right;
                    if (currentNode.Color == RedBlackNodeType.Red)
                    {
                        linkedNode.Parent.Color = RedBlackNodeType.Red;
                        currentNode.Color = RedBlackNodeType.Black;
                        RotateLeft(linkedNode.Parent);
                        currentNode = linkedNode.Parent.Right;
                    }

                    if (currentNode.Left.Color == RedBlackNodeType.Black &&
                        currentNode.Right.Color == RedBlackNodeType.Black)
                    {
                        currentNode.Color = RedBlackNodeType.Red;
                        linkedNode = linkedNode.Parent;
                    }
                    else
                    {
                        if (currentNode.Right.Color == RedBlackNodeType.Black)
                        {
                            currentNode.Left.Color = RedBlackNodeType.Black;
                            currentNode.Color = RedBlackNodeType.Red;
                            RotateRight(currentNode);
                            currentNode = linkedNode.Parent.Right;
                        }

                        linkedNode.Parent.Color = RedBlackNodeType.Black;
                        currentNode.Color = linkedNode.Parent.Color;
                        currentNode.Right.Color = RedBlackNodeType.Black;
                        RotateLeft(linkedNode.Parent);
                        linkedNode = RootNode;
                    }
                }
                else
                {
                    currentNode = linkedNode.Parent.Left;
                    if (currentNode.Color == RedBlackNodeType.Red)
                    {
                        linkedNode.Parent.Color = RedBlackNodeType.Red;
                        currentNode.Color = RedBlackNodeType.Black;
                        RotateRight(linkedNode.Parent);
                        currentNode = linkedNode.Parent.Left;
                    }

                    if (currentNode.Right.Color == RedBlackNodeType.Black &&
                        currentNode.Left.Color == RedBlackNodeType.Black)
                    {
                        currentNode.Color = RedBlackNodeType.Red;
                        linkedNode = linkedNode.Parent;
                    }
                    else
                    {
                        if (currentNode.Left.Color == RedBlackNodeType.Black)
                        {
                            currentNode.Right.Color = RedBlackNodeType.Black;
                            currentNode.Color = RedBlackNodeType.Red;
                            RotateLeft(currentNode);
                            currentNode = linkedNode.Parent.Left;
                        }

                        currentNode.Color = linkedNode.Parent.Color;
                        linkedNode.Parent.Color = RedBlackNodeType.Black;
                        currentNode.Left.Color = RedBlackNodeType.Black;
                        RotateRight(linkedNode.Parent);
                        linkedNode = RootNode;
                    }
                }
            }

            linkedNode.Color = RedBlackNodeType.Black;
        }

        public Stack<RBNode<TKey, TValue>> GetAll()
        {
            var stack = new Stack<RBNode<TKey, TValue>>();

            if (RootNode != SentinelNode)
            {
                AddChildrenToStack(RootNode, stack);
            }

            return stack;
        }

        private static void AddChildrenToStack(RBNode<TKey, TValue> node, Stack<RBNode<TKey, TValue>> stack)
        {
            if (node.Right != SentinelNode)
            {
                AddChildrenToStack(node.Right, stack);
            }

            stack.Push(node);
            if (node.Left != SentinelNode)
            {
                AddChildrenToStack(node.Left, stack);
            }
        }

        private void RotateRight(RBNode<TKey, TValue> rotateNode)
        {
            var currentNode = rotateNode.Left;

            rotateNode.Left = currentNode.Right;

            if (currentNode.Right != SentinelNode)
            {
                currentNode.Right.Parent = rotateNode;
            }

            if (currentNode != SentinelNode)
            {
                currentNode.Parent = rotateNode.Parent;
            }

            if (rotateNode.Parent != null)
            {
                if (rotateNode == rotateNode.Parent.Right)
                {
                    rotateNode.Parent.Right = currentNode;
                }
                else
                {
                    rotateNode.Parent.Left = currentNode;
                }
            }
            else
            {
                RootNode = currentNode;
            }

            currentNode.Right = rotateNode;

            if (rotateNode != SentinelNode)
            {
                rotateNode.Parent = currentNode;
            }
        }

        private void RotateLeft(RBNode<TKey, TValue> rotateNode)
        {
            var currentNode = rotateNode.Right;

            rotateNode.Right = currentNode.Left;

            if (currentNode.Left != SentinelNode)
            {
                currentNode.Left.Parent = rotateNode;
            }

            if (currentNode != SentinelNode)
            {
                currentNode.Parent = rotateNode.Parent;
            }

            if (rotateNode.Parent != null)
            {
                if (rotateNode == rotateNode.Parent.Left)
                {
                    rotateNode.Parent.Left = currentNode;
                }
                else
                {
                    rotateNode.Parent.Right = currentNode;
                }
            }
            else
            {
                RootNode = currentNode;
            }

            currentNode.Left = rotateNode;

            if (rotateNode != SentinelNode)
            {
                rotateNode.Parent = currentNode;
            }
        }

        private void BalanceOnInsert(RBNode<TKey, TValue> addedNode)
        {
            while (addedNode != RootNode && addedNode.Parent.Color == RedBlackNodeType.Red)
            {
                RBNode<TKey, TValue> currentNode;
                if (addedNode.Parent == addedNode.Parent.Parent.Left)
                {
                    currentNode = addedNode.Parent.Parent.Right;
                    if (currentNode != null && currentNode.Color == RedBlackNodeType.Red)
                    {
                        addedNode.Parent.Color = RedBlackNodeType.Black;
                        currentNode.Color = RedBlackNodeType.Black;
                        addedNode.Parent.Parent.Color = RedBlackNodeType.Red;
                        addedNode = addedNode.Parent.Parent;
                    }
                    else
                    {
                        if (addedNode == addedNode.Parent.Right)
                        {
                            addedNode = addedNode.Parent;
                            RotateLeft(addedNode);
                        }

                        addedNode.Parent.Color = RedBlackNodeType.Black;
                        addedNode.Parent.Parent.Color = RedBlackNodeType.Red;
                        RotateRight(addedNode.Parent.Parent);
                    }
                }
                else
                {
                    currentNode = addedNode.Parent.Parent.Left;
                    if (currentNode != null && currentNode.Color == RedBlackNodeType.Red)
                    {
                        addedNode.Parent.Color = RedBlackNodeType.Black;
                        currentNode.Color = RedBlackNodeType.Black;
                        addedNode.Parent.Parent.Color = RedBlackNodeType.Red;
                        addedNode = addedNode.Parent.Parent;
                    }
                    else
                    {
                        if (addedNode == addedNode.Parent.Left)
                        {
                            addedNode = addedNode.Parent;
                            RotateRight(addedNode);
                        }

                        addedNode.Parent.Color = RedBlackNodeType.Black;
                        addedNode.Parent.Parent.Color = RedBlackNodeType.Red;
                        RotateLeft(addedNode.Parent.Parent);
                    }
                }
            }

            RootNode.Color = RedBlackNodeType.Black;
        }
    }


