using System;
using System.Linq;
using System.Collections.Generic;

using E = System.Linq.Enumerable;

public class Program
{
    public static void Main()
    {
        var n = int.Parse(Console.ReadLine());
        var seqP = Console.ReadLine().Split().Select(x => int.Parse(x)).ToArray();

        var indices = new int[seqP.Length];
        for (int i = 0; i < indices.Length; ++i)
        {
            indices[i] = i;
        }
        Array.Sort(seqP, indices);
        Array.Reverse(seqP);
        Array.Reverse(indices);
        Console.Error.WriteLine(string.Join(" ", indices));
        Console.Error.WriteLine(string.Join(" ", seqP));

        var leftGreaters = new SortedSet<Tuple<long, int>>[seqP.Length];
        var rightGreaters = new SortedSet<Tuple<long, int>>[seqP.Length];
        var leftBound = new [] { Tuple.Create(-1L, 0), Tuple.Create(-1L, -1) };
        var rightBound = new [] { Tuple.Create((long)n, n + 1), Tuple.Create((long)n, n + 2) };
        for (int i = 0; i < leftGreaters.Length; ++i)
        {
            leftGreaters[i] = new SortedSet<Tuple<long, int>>(leftBound);
            rightGreaters[i] = new SortedSet<Tuple<long, int>>(rightBound);
        }
        for (int k = 0; k < indices.Length; ++k)
        {
            int j = indices[k];
            var t = Tuple.Create((long)j, seqP[k]);
            for (int i = k + 1; i < indices.Length; ++i)
            {
                int ii = indices[i];
                if (ii < j)
                {
                    rightGreaters[ii].Add(t);
                }
                else
                {
                    leftGreaters[ii].Add(t);
                }
            }
        }

        var sum = 0L;
        for (int k = 0; k < indices.Length; ++k)
        {
            int i = indices[k];
            var l = leftGreaters[i];
            var r = rightGreaters[i];

            var x = l.Max.Item1; l.Remove(l.Max);
            var w = l.Max.Item1;
            var y = r.Min.Item1; r.Remove(r.Min);
            var z = r.Min.Item1;
            sum += seqP[k] * ((x - w) * (y - i) + (i - x) * (z - y));
        }

        Console.WriteLine(sum);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

namespace ABC140E
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = int.Parse(Console.ReadLine());

            List<int> P = new List<int>();
            P.AddRange(ReadInt());

            int[] numToIndex = new int[P.Count + 1];
            for (int i = 0; i < P.Count; i++)
            {
                numToIndex[P[i]] = i + 1;
            }

            // 見終わったものの座標のリスト　昇順 <index, value>
            SortedList<int, int> finished = new SortedList<int, int>();
            finished.Add(-1, -1);
            finished.Add(0, 0);
            finished.Add(N + 1, N + 1);
            finished.Add(N + 2, N + 2);

            //大きいものから入れていく 今探しているナンバーはi
            long ans = 0;
            for (int i = N; i > 0; i--)
            {
                int ind = numToIndex[i];

                int R1ind = LowerBound(finished.Keys, ind);
                int R1 = finished.Keys[R1ind];
                int R2 = finished.Keys[R1ind + 1]; if (R2 == N + 2) R2 = N + 1;
                int L1 = finished.Keys[R1ind - 1];
                int L2 = finished.Keys[R1ind - 2]; if (L2 == -1) L2 = 0;

                long c1 = (long)i * (R1 - ind) * (L1 - L2);
                long c2 = (long)i * (ind - L1) * (R2 - R1);
                ans += c1 + c2;

                finished.Add(ind, i);
            }

            Console.WriteLine(ans);
            Console.ReadKey();
        }

        static int[] ReadInt()
        {
            int[] ret = Console.ReadLine().Split().Select(int.Parse).ToArray();
            return ret;
        }
        static long[] ReadLong()
        {
            long[] ret = Console.ReadLine().Split().Select(long.Parse).ToArray();
            return ret;
        }

        /// <summary>
        /// 二分探索 key以上の最低
        /// </summary>
        /// <typeparam name="T"></typeparam>
        /// <param name="a"></param>
        /// <param name="v"></param>
        /// <returns></returns>
        public static int LowerBound<T>(IList<T> a, T v)
        {
            return LowerBound(a, v, Comparer<T>.Default);
        }

        public static int LowerBound<T>(IList<T> a, T v, Comparer<T> cmp)
        {
            var l = 0;
            var r = a.Count - 1;
            while (l <= r)
            {
                var mid = l + (r - l) / 2;
                var res = cmp.Compare(a[mid], v);
                if (res == -1) l = mid + 1;
                else r = mid - 1;
            }
            return l;
        }
    }

}

