        public void Solve(TextReader textReader, IConsole console)
        {
            var cin = new ConsoleInput(textReader, ' ');

            int N = cin.ReadInt;
            int[] P = cin.ReadIntArray(N);

            Queue<int> queue1 = new Queue<int>();
            Queue<int> queue2 = new Queue<int>();

            ulong sum = 0;

            for (int i = 0; i < N - 1; i++)
            {
                queue1.Enqueue(P[i]);

                for (int j = i + 1; j < N; j++)
                {
                    int largestIN = queue1.Count > 0 ? queue1.Peek() : 0;
                    int secondLargestIN = queue2.Count > 0 ? queue2.Peek() : 0;

                    int nextJVal = P[j];

                    if (largestIN < nextJVal)
                    {
                        queue1.Enqueue(nextJVal);
                        secondLargestIN = largestIN;
                        queue2.Enqueue(secondLargestIN);
                    }
                    else if (secondLargestIN < nextJVal)
                    {
                        queue2.Enqueue(nextJVal);
                        secondLargestIN = nextJVal;
                    }

                    sum += (ulong)secondLargestIN;
                }

                queue1.Clear();
                queue2.Clear();
            }

            console.WriteLine(sum.ToString());
        }
    }

