namespace AtCoderProject
{
    public class Program
    {
        public object Calc()
        {
            var N = consoleReader.Int;
            var p = consoleReader.Split.Int0;
            var pIndex = new int[N];
            for (int i = 0; i < p.Length; i++)
                pIndex[p[i]] = i;

            var lefts = new int[N];
            var rights = new int[N];
            var lefts2 = new int[N];
            var rights2 = new int[N];
            var indexes = new List<int>(N);
            indexes.Add(pIndex[pIndex.Length - 1]);
            lefts[pIndex[pIndex.Length - 1]] = -1;
            lefts2[pIndex[pIndex.Length - 1]] = -1;
            rights[pIndex[pIndex.Length - 1]] = N;
            rights2[pIndex[pIndex.Length - 1]] = N;
            for (int i = p.Length - 2; i >= 0; i--)
            {
                var right = ~indexes.BinarySearch(pIndex[i]);
                if (right == indexes.Count)
                {
                    rights[pIndex[i]] = N;
                    rights2[pIndex[i]] = N;
                }
                else if (right == indexes.Count - 1)
                {
                    rights[pIndex[i]] = indexes[right];
                    rights2[pIndex[i]] = N;
                }
                else
                {
                    rights[pIndex[i]] = indexes[right];
                    rights2[pIndex[i]] = indexes[right + 1];
                }


                if (right == 0)
                {
                    lefts[pIndex[i]] = -1;
                    lefts2[pIndex[i]] = -1;
                }
                else if (right == 1)
                {
                    lefts[pIndex[i]] = indexes[right - 1];
                    lefts2[pIndex[i]] = -1;
                }
                else
                {
                    lefts[pIndex[i]] = indexes[right - 1];
                    lefts2[pIndex[i]] = indexes[right - 2];
                }
                indexes.Insert(right, pIndex[i]);
            }

            var res = new long[N];
            for (int i = 0; i < N; i++)
            {
                res[i] = (lefts[i] - lefts2[i]) * (rights[i] - i)
                    + (i - lefts[i]) * (rights2[i] - rights[i]);
                res[i] *= p[i] + 1;
            }

            return res.Sum();
        }
        static int BinarySearch<T>(IList<T> a, T v)
        {
            var l = 0;
            var r = a.Count - 1;
            while (l <= r)
            {
                var m = (l + r) / 2;
                var res = Comparer<T>.Default.Compare(a[m], v);
                if (res < 0) l = m + 1;
                else r = m - 1;
            }
            return l;
        }

        #region いつもの
#pragma warning disable
        [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader consoleReader;
        public Program(ConsoleReader consoleReader) { this.consoleReader = consoleReader; }
        static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.In)).Calc()); static string AllLines<T>(IEnumerable<T> source) => string.Join("\n", source);
    }
    static class Global
    {
        private class ComparerReverseImpl<T> : Comparer<T> where T : IComparable<T> { public override int Compare(T y, T x) => x.CompareTo(y); public override bool Equals(object obj) => obj != null && GetType() == obj.GetType(); public override int GetHashCode() => GetType().GetHashCode(); }
        public static IComparer<T> ComparerReverse<T>() where T : IComparable<T> => new ComparerReverseImpl<T>();
        public static BigInteger ParseBigInteger(string s)
        {
            // MonoのBigInteger.Parseが遅いので自前実装
            var res = BigInteger.Zero;
            var splited = new string[(s.Length + 7) / 8];
            for (int i = 0; i < splited.Length - 1; i++)
            {
                splited[i] = s.Substring(8 * i, 8);
            }
            splited[splited.Length - 1] = s.Substring(8 * (splited.Length - 1));
            foreach (var sp in splited)
            {
                res *= (int)Math.Pow(10, sp.Length);
                res += int.Parse(sp);
            }
            return res;
        }
    }
