        Array.Sort(seqP, indices);
        Array.Reverse(seqP);
        Array.Reverse(indices);
        Console.Error.WriteLine(string.Join(" ", indices));
        Console.Error.WriteLine(string.Join(" ", seqP));

        var leftGreaters = new SortedSet<Tuple<long, int>>[seqP.Length];
        var rightGreaters = new SortedSet<Tuple<long, int>>[seqP.Length];
        var leftBound = new [] { Tuple.Create(-1L, 0), Tuple.Create(-1L, -1) };
        var rightBound = new [] { Tuple.Create((long)n, n + 1), Tuple.Create((long)n, n + 2) };
        for (int i = 0; i < leftGreaters.Length; ++i)
        {
            leftGreaters[i] = new SortedSet<Tuple<long, int>>(leftBound);
            rightGreaters[i] = new SortedSet<Tuple<long, int>>(rightBound);
        }
        for (int k = 0; k < indices.Length; ++k)
        {
            int j = indices[k];
            var t = Tuple.Create((long)j, seqP[k]);
            for (int i = k + 1; i < indices.Length; ++i)
            {
                int ii = indices[i];
                if (ii < j)
                {
                    rightGreaters[ii].Add(t);
                    rightGreaters[ii].Remove(rightGreaters[ii].Max);
                }
                else
                {
                    leftGreaters[ii].Add(t);
                    leftGreaters[ii].Remove(leftGreaters[ii].Min);
                }
            }
        }

        var sum = 0L;
        for (int k = 0; k < indices.Length; ++k)
        {
            int i = indices[k];
            var l = leftGreaters[i];
            var r = rightGreaters[i];

            var w = l.Min.Item1;
            var x = l.Max.Item1;
            var y = r.Min.Item1;
            var z = r.Max.Item1;
            sum += seqP[k] * ((x - w) * (y - i) + (i - x) * (z - y));
        }

        Console.WriteLine(sum);
