using System;
using System.Collections.Generic;
using System.Linq;

namespace AtCoder
{
    class Program
    {
        static void Main(string[] args)
        {
            int number = int.Parse(Console.ReadLine());
            int[] inputPs = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();

            long answer = 0;

            // 各値について、
            // ・左向きに進んで自分が１番大きい範囲×右向きに進んで自分が２番目に大きい範囲
            // ・右向きに進んで自分が１番大きい範囲×左向きに進んで自分が２番目に大きい範囲
            // の和が自分が代表値として選ばれる場合の数になる。

            for(int i = 0; i < number; i++)
            {
                // Console.WriteLine("index : " + i.ToString() + ", value : " + inputPs[i].ToString());
                int[] left12 = AreasThatItIsMaxOrSecond(i, inputPs, -1);
                int[] right12 = AreasThatItIsMaxOrSecond(i, inputPs, 1);
                // Console.Write("lefts  : [" + string.Join(" ", left12) + "]");
                // Console.WriteLine("rights : [" + string.Join(" ", right12) + "]");
                int rightCount = left12[1] * right12[0];
                int leftCount = left12[0] * right12[1];
                long ttlCount = (long)rightCount + leftCount;
                answer += ttlCount * inputPs[i];
                // Console.WriteLine("-----");
            }

            Console.WriteLine(answer.ToString());
        }

        static int[] AreasThatItIsMaxOrSecond(int targetIndex, int[] sequence, int direction)
        {
            int currentValue = sequence[targetIndex];
            int[] counts = { 0, 0 };
            int isSecond = 0;
            int minTarget = 0;
            int maxTarget = sequence.Count();

            for(int i = targetIndex; minTarget <= i && i < maxTarget; i += direction)
            {
                if (sequence[i] > currentValue)
                {
                    if (isSecond == 1)
                    {
                        return counts;
                    }
                    isSecond = 1;
                }
                counts[isSecond]++;
            }
            return counts;
        }

        static void ShowSample()
        {
            List<int> dummyInput = Enumerable.Range(1, 9).OrderBy(i => Guid.NewGuid()).ToList();
            Console.WriteLine(string.Join(" ", dummyInput));

            for (int i = 2; i <= 9; i++)
            {
                List<int> tmp = new List<int>();
                for (int j = 0; j < 9 - i + 1; j++)
                {
                    // j から長さ i の列の範囲で二番目に大きな値
                    tmp.Add(dummyInput.GetRange(j, i).OrderByDescending(v => v).ToArray()[1]);
                }
                for (int j = 0; j < i - 1; j++)
                {
                    Console.Write(" ");
                }
                Console.WriteLine(string.Join(" ", tmp));
            }
        }
    }
}

