namespace AtCoder
{
    class Program
    {
        static void Main(string[] args)
        {
            int N = int.Parse(Console.ReadLine());
            int[] A = new int[N];
            string[] A_in = Console.ReadLine().Split(' ');
            for (int i = 0; i < N; i++)
            {
                A[i] = int.Parse(A_in[i]);
            }
            int result = 0;
            for (int i = 0; i < N-1; i++)
            {
                for (int j = i+1; j < N; j++)
                {
                    result += findX(A, i, j);
                }
            }

            Console.WriteLine(result.ToString());
//            Console.Read();
        }
        static int findX(int[] input, int L, int R)
        {
            int[] subArray = new int[(R - L + 1)];
            Array.Copy(input, L, subArray, 0, (R - L + 1));
            int max = subArray.Max();
            for (int i = 0; i < (R-L+1); i++)
            {
                if (subArray[i] == max) subArray[i] = 0;
            }
            return subArray.Max();
        }
    }
}

