        public void Solve(TextReader textReader, IConsole console)
        {
            var cin = new ConsoleInput(textReader, ' ');

            int N = cin.ReadInt;
            int[] P = cin.ReadIntArray(N);

            long answer = 0;

            List<int> largeValueIndexes = new List<int> {0, 0, N + 1, N + 1};

            int[] indexes = new int[N];

            for (int i = 0; i < N; i++)
            {
                int v = P[i] - 1;
                indexes[v] = i + 1;
            }

            for (int v = N; v > 0; v--)
            {
                int index = indexes[v - 1];

                int point0 = InsertValuesInOrder(index, ref largeValueIndexes);

                long representTime = GetRepresentTime(point0, largeValueIndexes);

                answer += representTime * v;
            }

            console.WriteLine(answer.ToString());
        }

        private static int InsertValuesInOrder(int v, ref List<int> largeValueIndexes)
        {
            int left = 0;
            int right = largeValueIndexes.Count - 1;

            while (right - left > 1)
            {
                int middle = left + (right - left) / 2;
                if (largeValueIndexes[middle] < v)
                {
                    left = middle;
                }
                else
                {
                    right = middle;
                }
            }

            largeValueIndexes.Insert(right, v);

            return right;
        }

        private static long GetRepresentTime(int index, List<int> largeValueIndexes)
        {
            int p0 = largeValueIndexes[index];
            int l2 = largeValueIndexes[index - 2];
            int l1 = largeValueIndexes[index - 1];
            int r1 = largeValueIndexes[index + 1];
            int r2 = largeValueIndexes[index + 2];

            return (p0 - l1) * (r2 - r1) + (l1 - l2) * (r1 - p0);
        }
    }

