		public static void Main(string[] args)
		{
			var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
			Console.SetOut(sw);

			Scanner cin = new Scanner();

			int n = cin.nextInt();
			var p = cin.ArrayInt(n);
			var s = new MultiSet<int>();
			var d = new Dictionary<int, int>();
			long ans = 0;
			for (int i = 0; i < n; i++)
			{
				d.Add(p[i], i + 1);
			}
			s.Insert(0);
			s.Insert(0);
			s.Insert(n + 1);
			s.Insert(n + 1);

			for (int i = n; i > 0; i--)
			{
				int l1, l2, r1, r2, x;
				l1 = s.LowerBound(d[i]) - 1;
				l2 = l1 - 1;
				r1 = s.UpperBound(d[i]);
				r2 = r1 + 1;
				x = d[i];
				int L1, L2, R1, R2;
				L1 = x - s[l1];
				L2 = s[l1] - s[l2];
				R1 = s[r1] - x;
				R2 = s[r2] - s[r1];
				ans += (L1 * R2 + L2 * R1) * i;
