    class Program
    {
        static void Main(string[] args)
        {
            var N = int.Parse(Console.ReadLine());

            List<int> P = new List<int>();
            P.AddRange(ReadInt());

            int[] numToIndex = new int[P.Count + 1];
            for (int i = 0; i < P.Count; i++)
            {
                numToIndex[P[i]] = i + 1;
            }

            // 見終わったものの座標のリスト　昇順 <index, value>
            SortedList<int, int> finished = new SortedList<int, int>();
            finished.Add(-1, -1);
            finished.Add(0, 0);
            finished.Add(N + 1, N + 1);
            finished.Add(N + 2, N + 2);

            //大きいものから入れていく 今探しているナンバーはi
            int ans = 0;
            for (int i = N; i > 0; i--)
            {
                int ind = numToIndex[i];

                int R1ind = LowerBound(finished.Keys.ToArray(), ind);
                int R1 = finished.Keys[R1ind];
                int R2 = finished.Keys[R1ind + 1]; if (R2 == N + 2) R2 = N + 1;
                int L1 = finished.Keys[R1ind - 1];
                int L2 = finished.Keys[R1ind - 2]; if (L2 == -1) L2 = 0;

                int c1 = i * (R1 - ind) * (L1 - L2);
                int c2 = i * (ind - L1) * (R2 - R1);
                ans += c1 + c2;

                finished.Add(ind, i);
            }

            Console.WriteLine(ans);
            Console.ReadKey();
        }

        static int[] ReadInt()
        {
            int[] ret = Console.ReadLine().Split().Select(int.Parse).ToArray();
            return ret;
        }
        static long[] ReadLong()
        {
            long[] ret = Console.ReadLine().Split().Select(long.Parse).ToArray();
            return ret;
        }

        /// <summary>
        /// 二分探索 key以上の最低
        /// </summary>
        /// <typeparam name="T"></typeparam>
        /// <param name="a"></param>
        /// <param name="v"></param>
        /// <returns></returns>
        public static int LowerBound<T>(T[] a, T v)
        {
            return LowerBound(a, v, Comparer<T>.Default);
        }

        public static int LowerBound<T>(T[] a, T v, Comparer<T> cmp)
        {
            var l = 0;
            var r = a.Length - 1;
            while (l <= r)
            {
                var mid = l + (r - l) / 2;
                var res = cmp.Compare(a[mid], v);
                if (res == -1) l = mid + 1;
                else r = mid - 1;
            }
            return l;
        }
    }

}

