// HugoWeaving ...
type HugoWeaving struct {
	n, bl, sl, chunk int
	mask             uint64
	sum, dic         []int
	bits             []uint64
}

func (fid *HugoWeaving) init(n int, dic []int) {
	fid.chunk = 16
	fid.n = n
	fid.bl = n/64 + 1
	fid.sl = (n-1)/fid.chunk + 2
	fid.bits = make([]uint64, fid.bl)
	fid.sum = make([]int, fid.sl)
	fid.dic = dic
	fid.mask = uint64(1<<16 - 1)
}

func (fid *HugoWeaving) setbit(i int) {
	fid.bits[i/64] |= uint64(1 << uint(i%64))
	fid.sum[i/fid.chunk+1]++
}

func (fid *HugoWeaving) setsum() {
	for i := 0; i < fid.sl-1; i++ {
		fid.sum[i+1] += fid.sum[i]
	}
}

func (fid *HugoWeaving) count0(i int) int {
	return i - fid.count1(i)
}

func (fid *HugoWeaving) count1(i int) int {
	c := fid.sum[i/fid.chunk]
	bits := (0xFFFF >> uint(fid.chunk-i%fid.chunk)) & (fid.bits[i/64] >> uint((i/fid.chunk)*fid.chunk))
	c += fid.dic[bits&fid.mask]
	return c
}

func (fid *HugoWeaving) access(i int) int {
	return int(fid.bits[i/64]>>uint(i%64)) & 1
}

func (fid *HugoWeaving) next(i int) int {
	if fid.access(i) == 0 {
		return fid.count0(i)
	}
	return fid.count0(fid.n) + fid.count1(i)
}

func (fid *HugoWeaving) nextrange0(l, r int) (int, int) {
	return fid.count0(l), fid.count0(r)
}

func (fid *HugoWeaving) nextrange1(l, r int) (int, int) {
	s := fid.count0(fid.n)
	return s + fid.count1(l), s + fid.count1(r)
}

func (fid *HugoWeaving) rank0(at int) int {
	l := 0
	r := fid.n
	for l < r {
		m := (l + r) >> 1
		if fid.count0(m) < at+1 {
			l = m + 1
			continue
		}
		r = m
	}
	return l - 1
}

func (fid *HugoWeaving) rank1(at int) int {
	l := 0
	r := fid.n
	for l < r {
		m := (l + r) >> 1
		if fid.count1(m) < at+1 {
			l = m + 1
			continue
		}
		r = m
	}
	return l - 1
}

// WaveletHugoWeaving ...
type WaveletHugoWeaving struct {
	bits, n  int
	tree     []HugoWeaving
	topIndex []int
}

func (wl *WaveletHugoWeaving) init(raw []int) {
	n := len(raw)
	wl.bits = 20
	wl.tree = make([]HugoWeaving, wl.bits, wl.bits)

	buf := make([]int, n, n)
	sorted := make([]int, n, n)
	wl.topIndex = make([]int, n, n)
	for i := 0; i < n; i++ {
		sorted[i] = i
		wl.topIndex[i] = -1
	}

	dic := make([]int, 1<<16)
	for i := 0; i < 1<<16; i++ {
		for ii := 0; ii < 16; ii++ {
			dic[i] += (i >> uint(ii)) & 1
		}
	}

	for i := wl.bits - 1; i >= 0; i-- {
		wl.tree[i] = HugoWeaving{}
		wl.tree[i].init(n, dic)
		bi := 0
		si := 0
		for ii := 0; ii < n; ii++ {
			bit := (raw[sorted[ii]] >> uint(i)) & 1
			if bit == 0 {
				sorted[si] = sorted[ii]
				si++
			} else {
				wl.tree[i].setbit(ii)
				buf[bi] = sorted[ii]
				bi++
			}
		}
		for ii := 0; ii < bi; ii++ {
			sorted[si+ii] = buf[ii]
		}
		wl.tree[i].setsum()
	}

	wl.n = n
}

func (wl *WaveletHugoWeaving) access(at int) int {
	var ans int

	for i := wl.bits - 1; i >= 0; i-- {
		ans |= wl.tree[i].access(at) << uint(i)
		at = wl.tree[i].next(at)
	}

	return ans
}

func (wl *WaveletHugoWeaving) rank(at, c int) int {
	l := 0
	r := at
	for i := wl.bits - 1; i >= 0 && l < r; i-- {
		bit := (c >> uint(i)) & 1
		if bit == 0 {
			l, r = wl.tree[i].nextrange0(l, r)
			continue
		}
		l, r = wl.tree[i].nextrange1(l, r)
	}

	return r - l
}

func (wl *WaveletHugoWeaving) gotop(h, index int) int {
	for i := h; i < wl.bits; i++ {
		index1 := wl.tree[i].count0(wl.n)
		if index < index1 {
			index = wl.tree[i].rank0(index)
			continue
		}
		index = wl.tree[i].rank1(index - index1)
	}
	return index
}

func (wl *WaveletHugoWeaving) gettopindex(index int) int {
	if wl.topIndex[index] != -1 {
		return wl.topIndex[index]
	}
	wl.topIndex[index] = wl.gotop(0, index)
	return wl.topIndex[index]
}

func (wl *WaveletHugoWeaving) selects(at, c int) int {
	l := 0
	r := wl.n
	for i := wl.bits - 1; i >= 0 && l < r; i-- {
		bit := (c >> uint(i)) & 1
		if bit == 0 {
			l, r = wl.tree[i].nextrange0(l, r)
			continue
		}
		l, r = wl.tree[i].nextrange1(l, r)
	}
	return wl.gettopindex(l + at)
}

func (wl *WaveletHugoWeaving) getbottomrange(l, r, c int) (int, int) {
	for i := wl.bits - 1; i >= 0; i-- {
		bit := (c >> uint(i)) & 1
		if bit == 0 {
			l, r = wl.tree[i].nextrange0(l, r)
			continue
		}
		l, r = wl.tree[i].nextrange1(l, r)
	}
	return l, r
}

func (wl *WaveletHugoWeaving) quantile(l, r, rank int) int {
	if rank > r-l {
		return -1
	}
	var ans int
	for i := wl.bits - 1; i >= 0; i-- {
		c1 := wl.tree[i].count1(r) - wl.tree[i].count1(l)
		if c1 >= rank {
			ans |= 1 << uint(i)
			l, r = wl.tree[i].nextrange1(l, r)
			continue
		}
		l, r = wl.tree[i].nextrange0(l, r)
		rank -= c1
	}

	return ans
}

func (wl *WaveletHugoWeaving) rangerankless(l, r, c int) int {
	ans := 0
	for i := wl.bits - 1; i >= 0; i-- {
		bit := (c >> uint(i)) & 1
		if bit == 0 {
			l, r = wl.tree[i].nextrange0(l, r)
			continue
		}
		ans += wl.tree[i].count0(r) - wl.tree[i].count0(l)
		l, r = wl.tree[i].nextrange1(l, r)
	}

	return ans
}

func (wl *WaveletHugoWeaving) rangerankmore(l, r, c int) int {
	ans := 0
	for i := wl.bits - 1; i >= 0; i-- {
		bit := (c >> uint(i)) & 1
		if bit == 1 {
			l, r = wl.tree[i].nextrange1(l, r)
			continue
		}
		ans += wl.tree[i].count1(r) - wl.tree[i].count1(l)
		l, r = wl.tree[i].nextrange0(l, r)
	}

	return ans
}

func (wl *WaveletHugoWeaving) rangefreq(l, r, min, max int) int {
	return wl.rangerankless(l, r, max) - wl.rangerankless(l, r, min)
}

func (wl *WaveletHugoWeaving) prevless(at, c int) int {
	l := 0
	r := at
	for l < r {
		m := (l + r) >> 1
		if wl.rangerankless(m, at, c) == 0 {
			r = m
			continue
		}
		l = m + 1
	}

	return l - 1
}

func (wl *WaveletHugoWeaving) prevmore(at, c int) int {
	l := 0
	r := at
	for l < r {
		m := (l + r) >> 1
		if wl.rangerankmore(m, at, c) == 0 {
			r = m
			continue
		}
		l = m + 1
	}

	return l - 1
}

func (wl *WaveletHugoWeaving) nextless(at, c int) int {
	l := at + 1
	r := wl.n
	for l < r {
		m := (l + r) >> 1
		if wl.rangerankless(at+1, m+1, c) == 0 {
			l = m + 1
			continue
		}
		r = m
	}

	return r
}

func (wl *WaveletHugoWeaving) nextmore(at, c int) int {
	l := at + 1
	r := wl.n
	for l < r {
		m := (l + r) >> 1
		if wl.rangerankmore(at+1, m+1, c) == 0 {
			l = m + 1
			continue
		}
		r = m
	}

	return r
}

