		l := db.nextLeft(pp[i-1])
		ll := db.nextLeft(l)
		r := db.nextRight(pp[i-1])
		rr := db.nextRight(r)

		ans += int64(l-ll) * int64(r-pp[i-1]) * int64(i)
		ans += int64(pp[i-1]-l) * int64(rr-r) * int64(i)
	}

	fmt.Fprintln(writer, ans)
	writer.Flush()
}

// DoubleBucket ...
type DoubleBucket struct {
	unit   int
	bucket [3][]int
}

func (db *DoubleBucket) init(n int) {
	db.unit = 2
	db.bucket[0] = make([]int, n)
	db.bucket[1] = make([]int, (n-1)/db.unit+1)
	db.bucket[2] = make([]int, (len(db.bucket[1])-1)/db.unit+1)
}

func (db *DoubleBucket) update(i, v int) {
	db.bucket[0][i] = v
	db.bucket[1][i/db.unit] = v
	db.bucket[2][i/db.unit/db.unit] = v
}

func (db *DoubleBucket) nextLeft(i int) int {
	big := db.unit * db.unit
	small := db.unit
	for i = i - 1; i >= 0; i-- {
		if db.bucket[0][i] > 0 {
			return i
		}
		if (i+1)%big == 0 && db.bucket[2][i/big] == 0 {
			i -= big - 1
			continue
		}
		if (i+1)%small == 0 && db.bucket[1][i/small] == 0 {
			i -= small - 1
			continue
		}
	}

	return -1
}

func (db *DoubleBucket) nextRight(i int) int {
	big := db.unit * db.unit
	small := db.unit
	n := len(db.bucket[0])
	for i = i + 1; i < n; i++ {
		if db.bucket[0][i] > 0 {
			return i
		}
		if i%big == 0 && db.bucket[2][i/big] == 0 {
			i += big - 1
			continue
		}
		if i%small == 0 && db.bucket[1][i/small] == 0 {
			i += small - 1
			continue
		}
	}

	return n
}

