			return -1 < -(bit.Sum(idx[n-i])-bit.Sum(idl))
		})
		l2 := sort.Search(idx[n-i], func(idl int) bool {
			return -2 < -(bit.Sum(idx[n-i])-bit.Sum(idl))
		})

		bit.Add(idx[n-i], 1)

		ans += ((r1-idx[n-i])*(l1-l2)+(r2-r1)*(idx[n-i]-l1))*(n-i)
		// debug(n-i,ans)

		// debug(idx[n-i], l2, l1, r1, r2)
	}

	fmt.Fprintln(wr, ans)

}

