// d: debug IO. it can print debug in test.
func solve(io *Io, d *Io) {
	N := io.NextInt()
	ps := io.NextInts(N)

	// 後で配列の copy のコストを減らすために降順にしたい
	{
		inc := 0
		dec := 0

		cur := ps[0]
		for i, p := range ps {
			if i == 0 {
				continue
			}

			if p > cur {
				inc++
			} else {
				dec++
			}

			cur = p
		}

		if inc > dec {
			tmp := make([]int, N)

			for i, p := range ps {
				tmp[N-1-i] = p
			}

			ps = tmp
		}
	}

	numToIndex := make([]int, N+1)

	for i, p := range ps {
		numToIndex[p] = i
	}

	largeIndices := make([]int, 1, N+1)
	largeIndices[0] = numToIndex[N]

	res := 0

	for num := N - 1; num >= 1; num-- {
		i := numToIndex[num]
		// その i より大きい index
		bigIndexForLarge := sort.SearchInts(largeIndices, i)

		bi := N
		bi2 := N
		si := -1
		si2 := -1

		if bigIndexForLarge < len(largeIndices) {
			bi = largeIndices[bigIndexForLarge]

			if bigIndexForLarge+1 < len(largeIndices) {
				bi2 = largeIndices[bigIndexForLarge+1]
			}
		}

		if bigIndexForLarge-1 >= 0 {
			si = largeIndices[bigIndexForLarge-1]

			if bigIndexForLarge-2 >= 0 {
				si2 = largeIndices[bigIndexForLarge-2]
			}
		}

		// s を取る場合
		res += (si - si2) * (bi - i) * num
		// b ..
		res += (bi2 - bi) * (i - si) * num

		largeIndices = append(largeIndices, 0)
		copy(largeIndices[bigIndexForLarge+1:], largeIndices[bigIndexForLarge:])
		largeIndices[bigIndexForLarge] = i
	}

	io.Println(res)
}

func main() {
	io := NewIo()
	defer io.Flush()
	solve(io, nil)
}

/* IO Helpers */

// Io combines reader, writer, & tokens as the state when processing the input
type Io struct {
	reader    *bufio.Reader
	writer    *bufio.Writer
	tokens    []string
	nextToken int
}

// NewIo creates Io with Stdin & Stdout
func NewIo() *Io {
	return &Io{
		reader: bufio.NewReader(os.Stdin),
		writer: bufio.NewWriter(os.Stdout),
	}
}

// Flush calls the writer's Flush
func (io *Io) Flush() {
	io.writer.Flush()
}

// NextLine returns the string from reader.ReadLine()
func (io *Io) NextLine() string {
	if io.nextToken < len(io.tokens) {
		panic("io.nextToken < len(io.tokens)")
	}

	var buffer bytes.Buffer

	for {
		line, isPrefix, err := io.reader.ReadLine()
		if err != nil {
			panic(err)
		}
		buffer.Write(line)
		if !isPrefix {
			break
		}
	}

	return buffer.String()
}

// NextLines returns []string from next n lines
func (io *Io) NextLines(n int) []string {
	res := make([]string, n)
	for i := 0; i < n; i++ {
		res[i] = io.NextLine()
	}
	return res
}

// Next returns the string token (partial string of the line divided by spaces)
func (io *Io) Next() string {
	if io.nextToken >= len(io.tokens) {
		line := io.NextLine()
		io.tokens = strings.Fields(line)
		io.nextToken = 0
	}

	res := io.tokens[io.nextToken]
	io.nextToken++
	return res
}

// NextStrings returns the []string from the next n tokens
func (io *Io) NextStrings(n int) []string {
	res := make([]string, n)
	for i := 0; i < n; i++ {
		res[i] = io.Next()
	}
	return res
}

// NextRunes returns next string as []rune
func (io *Io) NextRunes() []rune {
	return []rune(io.Next())
}

// NextInt returns the int from the next token
func (io *Io) NextInt() int {
	res, err := strconv.Atoi(io.Next())
	if err != nil {
		panic(err)
	}
	return res
}

// NextInts returns the []int from the next n tokens
func (io *Io) NextInts(n int) []int {
	res := make([]int, n)
	for i := 0; i < n; i++ {
		res[i] = io.NextInt()
	}
	return res
}

// NextFloat returns the float64 from the next token
func (io *Io) NextFloat() float64 {
	res, err := strconv.ParseFloat(io.Next(), 64)
	if err != nil {
		panic(err)
	}
	return res
}

// NextFloats returns the []float64 from the next n tokens
func (io *Io) NextFloats(n int) []float64 {
	res := make([]float64, n)
	for i := 0; i < n; i++ {
		res[i] = io.NextFloat()
	}
	return res
}

// Println prints the input to the writer in an easy-to-see form
func (io *Io) Println(a ...interface{}) {
	var values []string
	for i := 0; i < len(a); i++ {
		values = append(values, "%v")
	}
	io.Printfln(strings.Join(values, " "), a...)
}

// Print calls Fprint to the writer
func (io *Io) Print(a interface{}) {
	fmt.Fprint(io.writer, a)
}

// Printf calls Fprintf to the writer
func (io *Io) Printf(format string, a ...interface{}) {
	fmt.Fprintf(io.writer, format, a...)
}

// Printfln calls Fprint to the writer
func (io *Io) Printfln(format string, a ...interface{}) {
