	for i := range ps {
		var l1, l2, lbg int
		for j := 1; i-j >= 0; j++ {
			if ps[i-j] < ps[i] {
				if lbg == 0 {
					l1++
				} else {
					l2++
				}
			} else {
				lbg++
				if lbg == 2 {
					break
				}
			}
		}
		var r1, r2, rbg int
		for j := 1; i+j < n; j++ {
			if ps[i+j] < ps[i] {
				if rbg == 0 {
					r1++
				} else {
					r2++
				}
			} else {
				rbg++
				if rbg == 2 {
					break
				}
			}
		}
		var cnt int
		if lbg > 0 {
