func max2(xs ...int) (p int) {
	sort.Ints(xs)
	m := xs[len(xs)-1]
	for i := len(xs) - 2; i >= 0; i-- {
		k := xs[i]
		if k < m {
			return k
		}
	}
	return 0
}

