import (
	"fmt"

	"github.com/emirpasic/gods/trees/redblacktree"
)

func main() {
	var n int
	fmt.Scan(&n)
	p := make([]int, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&p[i])
	}

	idx := make([]int, n+1)
	for i := 0; i < n; i++ {
		idx[p[i]] = i + 1
	}

	tree := redblacktree.NewWithIntComparator()
	none := struct{}{}
	tree.Put(0, none)
	tree.Put(n+1, none)

	ans := 0
	for k := n; k > 0; k-- {
		tree.Put(idx[k], none)

		var l1, r1 int
		if v, found := tree.Floor(idx[k] - 1); found {
			l1 = v.Key.(int)
		}
		if v, found := tree.Ceiling(idx[k] + 1); found {
			r1 = v.Key.(int)
		}

		l2, r2 := l1, r1
		if v, found := tree.Floor(l1 - 1); found {
			l2 = v.Key.(int)
		}
		if v, found := tree.Ceiling(r1 + 1); found {
			r2 = v.Key.(int)
		}

		ans += (idx[k] - l1) * (r2 - r1) * k
		ans += (r1 - idx[k]) * (l1 - l2) * k
	}
	fmt.Println(ans)
}

