type MyScanner struct {
	sc *bufio.Scanner
}

type MyWriter struct {
	stdout io.Writer
}

type MyPut interface{}

func getScanner(fp io.Reader) *bufio.Scanner {
	sc := bufio.NewScanner(fp)
	sc.Split(bufio.ScanWords)
	sc.Buffer(make([]byte, 500001), 500000)
	return sc
}

func getHugeScanner(fp io.Reader, size int) *bufio.Scanner {
	sc := bufio.NewScanner(fp)
	sc.Split(bufio.ScanWords)
	sc.Buffer(make([]byte, size), size)
	return sc
}

func (mysc *MyScanner)String() string {
	mysc.sc.Scan()
	return mysc.sc.Text()
}

func (mysc *MyScanner)Int() int {
	i, _ := strconv.Atoi(mysc.String())
	return i
}

func (mysc *MyScanner)Int64() int64 {
	i, _ := strconv.ParseInt(mysc.String(), 10, 64)
	return i
}

func (mysc *MyScanner)Float64() float64 {
	i, _ := strconv.ParseFloat(mysc.String(), 64)
	return i
}

func (mw MyWriter)Puts(v MyPut) {
	_, _ = fmt.Fprintf(mw.stdout, "%v\n", v)
}

func UpperBound(l []int, n int) (int, int) {
	k := sort.Search(len(l), func(i int) bool { return l[i] > n })
	if k == len(l) {
		return k, -1
	}
	return k, l[k]
}

func Solve(stdin io.Reader, stdout io.Writer) {
	sc := MyScanner{getScanner(stdin)}
	mw := MyWriter{stdout}

	n := sc.Int()

	p := make([]int, n + 1)
	idx := make([]int, n + 1)

	up := make([]int, 0, n)

	for i := 1; i <= n; i++ {
		v := sc.Int()
		p[i] = v
		idx[v] = i
	}

	ans := 0

	for v := n; v >= 1; v-- {
		i := idx[v]
		k, _ := UpperBound(up, i)
		if k < len(up) {
			up = append(up[:k + 1], up[k:]...)
			up[k] = i
		} else {
			up = append(up, i)
		}
		var ll, lr, rl, rr int
		k--
		if k < 0 {
			lr = 0
		} else {
			lr = up[k]
		}
		k--
		if k < 0 {
			ll = 0
		} else {
			ll = up[k]
		}
		k += 3
		if k < len(up) {
			rl = up[k]
		} else {
			rl = n + 1
		}
		k++
		if k < len(up) {
			rr = up[k]
		} else {
			rr = n + 1
		}
		ans += ((lr - ll) * (rl - i) + (i - lr) * (rr - rl)) * v
	}
	mw.Puts(ans)
}

func main() {
	Solve(os.Stdin, os.Stdout)
	return
}

