type permutation struct {
	p, i int
}
type permutations []permutation

func (a permutations) Len() int           { return len(a) }
func (a permutations) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a permutations) Less(i, j int) bool { return a[i].p > a[j].p }

type decomposition struct {
	chunk  int
	bucket [][]int
}

func newDecomposition(n int) decomposition {
	bucket := make([][]int, 1)
	bucket[0] = make([]int, n)
	chunk := 8
	for i := 0; n > 1; i++ {
		n = (n-1)/chunk + 1
		bucket = append(bucket, make([]int, n))
	}
	return decomposition{
		chunk:  chunk,
		bucket: bucket,
	}
}
func (dec *decomposition) upleft(l int) int {
	return (l + dec.chunk - 1) / dec.chunk
}
func (dec *decomposition) upright(r int) int {
	return r / dec.chunk
}
func (dec *decomposition) add(index int, value int) {
	h := len(dec.bucket)
	for i := 0; i < h; i++ {
		dec.bucket[i][index] += value
		index /= dec.chunk
	}
}
func (dec *decomposition) rangesum(l, r int) int {
	return dec.rangesumh(l, r, 0)
}
func (dec *decomposition) rangesumh(l, r, h int) int {
	var sum int
	ll := dec.upleft(l)
	rr := dec.upright(r)
	for i := l; i < r && i < ll*dec.chunk; i++ {
		sum += dec.bucket[h][i]
	}
	if ll < rr {
		sum += dec.rangesumh(ll, rr, h+1)
	}
	for i := rr * dec.chunk; i < r && ll <= rr; i++ {
		sum += dec.bucket[h][i]
	}
	return sum
}
func (dec *decomposition) kright(l, r, k int) int {
	return dec.krighth(l, r, k, 0)
}
func (dec *decomposition) krighth(l, r, k, h int) int {
	ll := dec.upleft(l)
	rr := dec.upright(r)
	for i := l; i < r && i < ll*dec.chunk; i++ {
		if k > dec.bucket[h][i] {
			k -= dec.bucket[h][i]
			continue
		}
		return i
	}
	if ll < rr {
		rr = dec.krighth(ll, rr, k, h+1)
	}
	for i := rr * dec.chunk; i < r && ll <= rr; i++ {
		if k > dec.bucket[h][i] {
			k -= dec.bucket[h][i]
			continue
		}
		return i
	}

	return r
}
func (dec *decomposition) kleft(l, r, k int) int {
	return dec.klefth(l, r, k, 0)
}
func (dec *decomposition) klefth(l, r, k, h int) int {
	ll := dec.upleft(l)
	rr := dec.upright(r)
	for i := r - 1; i >= 0 && i >= rr*dec.chunk; i-- {
		if k > dec.bucket[h][i] {
			k -= dec.bucket[h][i]
			continue
		}
		return i
	}
	if ll < rr {
		ll = dec.klefth(ll, rr, k, h+1)
	}
	for i := ll*dec.chunk - 1; i >= 0 && i >= l; i-- {
		if k > dec.bucket[h][i] {
			k -= dec.bucket[h][i]
			continue
		}
		return i

	}
	return l - 1
}

