import (
	"fmt"
	"math"
)

func answer (n int, p []int) int {
	ans := 0
	for l := 1; l <= n - 1; l++ {
		max := int(math.Max(float64(p[l - 1]), float64(p[l])))
		xlr := int(math.Min(float64(p[l - 1]), float64(p[l])))
		for r := l + 1; r <= n; r++ {
			if r != l + 1 && p[r - 1] > xlr {
				if max > p[r - 1] {
					xlr = p[r - 1]
				} else {
					xlr = max
					max = p[r - 1]
				}
			}
			ans += xlr
		}
	}
	return ans
}

func main() {
	var n int
	fmt.Scan(&n)
	p := make([]int, n, n)
	for i := 0; i < n; i++ {
		fmt.Scan(&p[i])
	}
	fmt.Println(answer(n, p))
}

