	dic := make([]int, 1<<8)
	for i := 0; i < 1<<8; i++ {
		for ii := 0; ii < 8; ii++ {
			dic[i] += i >> uint(ii) & 1
		}
	}

	for i := wl.bits - 1; i >= 0; i-- {
		wl.tree[i] = HugoWeaving{}
		wl.tree[i].init(n, dic)
		bi := 0
		si := 0
		for ii := 0; ii < n; ii++ {
			bit := (raw[sorted[ii]] >> uint(i)) & 1
			if bit == 0 {
				sorted[si] = sorted[ii]
				si++
			} else {
				wl.tree[i].setbit(ii)
				buf[bi] = sorted[ii]
				bi++
			}
		}
		wl.tree[i].setsum()
		for ii := 0; ii < bi; ii++ {
			sorted[si+ii] = buf[ii]
		}
	}

	wl.n = n
}

func (wl *WaveletHugoWeaving) access(at int) int {
	var ans int

	for i := wl.bits - 1; i >= 0; i-- {
		ans |= wl.tree[i].access(i)
		at = wl.tree[i].next(at)
	}

	return ans
}

func (wl *WaveletHugoWeaving) rank(at, c int) int {
	l := 0
	r := at
	for i := wl.bits - 1; i >= 0 && l < r; i-- {
		bit := (c >> uint(i)) & 1
		if bit == 0 {
			l, r = wl.tree[i].nextrange0(l, r)
			continue
		}
		l, r = wl.tree[i].nextrange1(l, r)
	}

	return r - l
}

func (wl *WaveletHugoWeaving) gotop(h, index int) int {
	for i := h; i < wl.bits; i++ {
		index1 := wl.tree[i].count0(wl.n)
		if index < index1 {
			index = wl.tree[i].rank0(index)
			continue
		}
		index = wl.tree[i].rank1(index - index1)
	}
	return index
}

func (wl *WaveletHugoWeaving) gettopindex(index int) int {
	if wl.topIndex[index] != -1 {
		return wl.topIndex[index]
	}
	wl.topIndex[index] = wl.gotop(0, index)
	return wl.topIndex[index]
}

func (wl *WaveletHugoWeaving) selects(at, c int) int {
	l := 0
	r := wl.n
	for i := wl.bits - 1; i >= 0 && l < r; i-- {
		bit := (c >> uint(i)) & 1
		if bit == 0 {
			l, r = wl.tree[i].nextrange0(l, r)
			continue
		}
		l, r = wl.tree[i].nextrange1(l, r)
	}
	return wl.gettopindex(l + at)
}

func (wl *WaveletHugoWeaving) getbottomrange(l, r, c int) (int, int) {
	for i := wl.bits - 1; i >= 0; i-- {
		bit := (c >> uint(i)) & 1
		if bit == 0 {
			l, r = wl.tree[i].nextrange0(l, r)
			continue
		}
		l, r = wl.tree[i].nextrange1(l, r)
	}
	return l, r
}

func (wl *WaveletHugoWeaving) quantile(l, r, rank int) int {
	if rank > r-l {
		return -1
	}
	var ans int
	for i := wl.bits - 1; i >= 0; i-- {
		c1 := wl.tree[i].count1(r) - wl.tree[i].count1(l)
		if c1 >= rank {
			ans |= 1 << uint(i)
			l, r = wl.tree[i].nextrange1(l, r)
			continue
		}
		l, r = wl.tree[i].nextrange0(l, r)
		rank -= c1
	}

	return ans
}

func (wl *WaveletHugoWeaving) rangerankless(l, r, c int) int {
	ans := 0
	for i := wl.bits - 1; i >= 0; i-- {
		bit := (c >> uint(i)) & 1
		if bit == 0 {
			l, r = wl.tree[i].nextrange0(l, r)
			continue
		}
		ans += wl.tree[i].count0(r) - wl.tree[i].count0(l)
		l, r = wl.tree[i].nextrange1(l, r)
	}

	return ans
}

func (wl *WaveletHugoWeaving) rangerankmore(l, r, c int) int {
	ans := 0
	for i := wl.bits - 1; i >= 0; i-- {
		bit := (c >> uint(i)) & 1
		if bit == 1 {
			l, r = wl.tree[i].nextrange1(l, r)
			continue
		}
		ans += wl.tree[i].count1(r) - wl.tree[i].count1(l)
		l, r = wl.tree[i].nextrange0(l, r)
	}

	return ans
}

func (wl *WaveletHugoWeaving) rangefreq(l, r, min, max int) int {
