type ScoreInfo struct {
    first int
    second int
}

func main() {
    sc.Split(bufio.ScanWords)
	n := nextInt()
	var p []int
    p = make([]int, n)
    a := make([][]ScoreInfo, n + 1, n + 1)

    for i := 0; i < n; i++ {
        p[i] = nextInt()
    }

    score := 0
    // width = 2
    a[2] = make([]ScoreInfo, n - 1, n - 1)
    for i := 0 ; i < n - 1; i++ {
        if (p[i] > p[i + 1]) {
            a[2][i].first = p[i]
            a[2][i].second = p[i + 1]
        } else {
            a[2][i].first = p[i + 1]
            a[2][i].second = p[i]
        }
        score += a[2][i].second
        //fmt.Println("add: ", a[2][i].second)
    }

    // width > 2
    for width := 3; width <= n; width++ {
        a[width] = make([]ScoreInfo, n - (width - 1), n - (width - 1))
        for i := 0; i < n - (width - 1); i++ {
            if a[width - 1][i] == a[width - 1][i + 1] {
                // すべて同値
                a[width][i] = a[width - 1][i]
            } else {
                // 比較が必要
                left_first   := a[width - 1][i].first
                left_second  := a[width - 1][i].second
                right_first  := a[width - 1][i + 1].first
                right_second := a[width - 1][i + 1].second
                if left_first == right_first {
                    // 最大値が同値
                    a[width][i].first = left_first
                    if left_second > right_second {
                        a[width][i].second = left_second
                    } else {
                        a[width][i].second = right_second
                    }
                } else if left_first > right_first {
                    // 左1st > 右1st > 右2nd
                    a[width][i].first = left_first
                    if left_second > right_first {
                        a[width][i].second = left_second
                    } else {
                        a[width][i].second = right_first
                    }
                } else {
                    a[width][i].first = right_first
                    if right_second > left_first {
                        a[width][i].second = right_second
                    } else {
                        a[width][i].second = left_first
                    }
                }
            }
            score += a[width][i].second
            //fmt.Println("add: ", a[width][i].second)
        }
    }
    //fmt.Println(a)

    fmt.Println(score)
}

