		for ; cur.node.children[dir] != nil; cur.node = cur.node.children[dir] {

		}
	}
	return cur
}

type Line struct {
	idx, val int
}

type LineSorter []*Line

func (a LineSorter) Len() int           { return len(a) }
func (a LineSorter) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a LineSorter) Less(i, j int) bool { return a[i].val > a[j].val }

func solve(stdin io.Reader, stdout io.Writer) {

	r := NewScannerEx(stdin)
	r.Scan(true)
	n := r.nextInt()
	r.Scan(true)
	p := r.nextStringArray().toInts()

	pl := func(src []int) (dst []*Line) {
		dst = make([]*Line, 0, len(src)+2)
		for i := range src {
			value := &src[i]
			dst = append(dst, &Line{idx: i, val: *value})
		}
		return
	}(p)
	plGet := func(cur *RBCursor) int {
		return pl[cur.node.index].idx
	}

	sort.Sort(LineSorter(pl))

	tree := RBCursor{less: func(a, b int) bool {
		return pl[a].idx < pl[b].idx
	}}

	pl = append(pl, &Line{idx: -1, val: 1e10})
	pl = append(pl, &Line{idx: n, val: 1e10})

	tree.add(n).add(n + 1)

	ans := 0
	for pi := 0; pi < n; pi++ {
		tree.add(pi)

		wl := tree.clone().move(RBNodeLeft)
		wll := wl.clone().move(RBNodeLeft)
		wr := tree.clone().move(RBNodeRight)
		wrr := wr.clone().move(RBNodeRight)

		if wll.node != nil {
			ans += pl[tree.node.index].val * (plGet(wl) - plGet(wll)) * (plGet(wr) - plGet(&tree))
		}

		if wrr.node != nil {
			ans += pl[tree.node.index].val * (plGet(&tree) - plGet(wl)) * (plGet(wrr) - plGet(wr))
		}
	}
	fmt.Fprintln(stdout, ans)
}

