func main() {
	var n int
	fmt.Scanf("%d", &n)
	s := bufio.NewScanner(os.Stdin)
	s.Scan()
	ps := readInts(s.Text())
	ls := make([]int, n)
	var l int
	for i := 0; i < n; i++ {
		for j := 0; j < n-1-i; j++ {
			ll := max2(ps[j], ps[j+1], ls[j], ls[j+1])
			ls[j] = ll
			l += ll
			ps[j] = max(ps[j], ps[j+1])
		}
	}
	fmt.Printf("%d\n", l)
}

func max(x, y int) int {
	if x > y {
		return x
	}
	return y
}

func max2(xs ...int) int {
	y, z := 0, 0
	for _, x := range xs {
		if x > y {
			y, z = x, y
		} else if y > x && x > z {
			z = x
		}
	}
	return z
}

func readInts(s string) []int {
	xs := strings.Fields(s)
	ys := make([]int, len(xs))
	for i, x := range xs {
		ys[i], _ = strconv.Atoi(x)
	}
	return ys
}

