func UpperBound(l []int, n int) (int, int) {
	k := sort.Search(len(l), func(i int) bool { return l[i] > n })
	if k == len(l) {
		return k, -1
	}
	return k, l[k]
}

func Solve(stdin io.Reader, stdout io.Writer) {
	sc := MyScanner{getScanner(stdin)}
	mw := MyWriter{stdout}

	n := sc.Int()

	p := make([]int, n + 1)
	idx := make([]int, n + 1)

	var up []int

	for i := 1; i <= n; i++ {
		v := sc.Int()
		p[i] = v
		idx[v] = i
	}

	ans := 0

	for v := n; v >= 1; v-- {
		i := idx[v]
		k, _ := UpperBound(up, i)
		if k < len(up) {
			up = append(up[:k + 1], up[k:]...)
			up[k] = i
		} else {
			up = append(up, i)
		}
		var ll, lr, rl, rr int
		k--
		if k < 0 {
			lr = 0
		} else {
			lr = up[k]
		}
		k--
		if k < 0 {
			ll = 0
		} else {
			ll = up[k]
		}
		k += 3
		if k < len(up) {
			rl = up[k]
		} else {
			rl = n + 1
		}
		k++
		if k < len(up) {
			rr = up[k]
		} else {
			rr = n + 1
		}
		ans += ((lr - ll) * (rl - i) + (i - lr) * (rr - rl)) * v
	}
	mw.Puts(ans)
}

