	return dec.kleft(index, 1)
}
func (dec *decomposition) kleft(index, k int) int {
	l := -1
	r := index
	for l+1 < r {
		m := (l + r) >> 1
		if dec.rangesum(m, index) < k {
			r = m
			continue
		}
		l = m
	}
	return l
}
func (dec *decomposition) right(index int) int {
	return dec.kright(index, 1)
}
func (dec *decomposition) kright(index, k int) int {
	l := index
	r := len(dec.bucket[0])
	for l+1 < r {
		m := (l + r) >> 1
		if dec.rangesum(index+1, m+1) < k {
			l = m
			continue
		}
		r = m
	}
	return r
}

