func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	pp := make(permutations, n)
	for i := 0; i < n; i++ {
		pp[i].p = getNextInt(scanner)
		pp[i].i = i
	}
	sort.Sort(pp)
	dec := newDecomposition(n)
	var ans int64
	for i := 0; i < n; i++ {
		l := dec.kleft(pp[i].i, 1)
		ll := dec.kleft(pp[i].i, 2)
		r := dec.kright(pp[i].i, 1)
		rr := dec.kright(pp[i].i, 2)
		ans += int64(l-ll) * int64(r-pp[i].i) * int64(pp[i].p)
		ans += int64(rr-r) * int64(pp[i].i-l) * int64(pp[i].p)
		dec.add(pp[i].i, 1)
	}
	fmt.Fprintln(writer, ans)
}

type permutation struct {
	p, i int
}
type permutations []permutation

func (a permutations) Len() int           { return len(a) }
func (a permutations) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a permutations) Less(i, j int) bool { return a[i].p > a[j].p }

type decomposition struct {
	chunk  int
	bucket [][]int
}

func newDecomposition(n int) decomposition {
	bucket := make([][]int, 1)
	bucket[0] = make([]int, n)
	chunk := 8
	for i := 0; n > 1; i++ {
		n = (n-1)/chunk + 1
		bucket = append(bucket, make([]int, n))
	}
	return decomposition{
		chunk:  chunk,
		bucket: bucket,
	}
}
func (dec *decomposition) upleft(l int) int {
	return (l + dec.chunk - 1) / dec.chunk
}
func (dec *decomposition) upright(r int) int {
	return r / dec.chunk
}
func (dec *decomposition) add(index int, value int) {
	h := len(dec.bucket)
	for i := 0; i < h; i++ {
		dec.bucket[i][index] += value
		index /= dec.chunk
	}
}
func (dec *decomposition) rangesum(l, r int) int {
	return dec.rangesumh(l, r, 0)
}
func (dec *decomposition) rangesumh(l, r, h int) int {
	var sum int
	ll := dec.upleft(l)
	rr := dec.upright(r)
	for i := l; i < r && i < ll*dec.chunk; i++ {
		sum += dec.bucket[h][i]
	}
	if ll < rr {
		sum += dec.rangesumh(ll, rr, h+1)
	}
	for i := rr * dec.chunk; i < r && ll <= rr; i++ {
		sum += dec.bucket[h][i]
	}
	return sum
}
func (dec *decomposition) kleft(index, k int) int {
	h := 0
	for i := index - 1; i >= 0; i-- {
		if (i+1)%dec.chunk == 0 {
			i = (i + 1) / dec.chunk
			h++
			continue
		}
		if k > dec.bucket[h][i] {
			k -= dec.bucket[h][i]
			continue
		}
		if h == 0 {
			return i
		}
		h--
		i = (i + 1) * dec.chunk
	}
	return -1
}
func (dec *decomposition) kright(index, k int) int {
	h := 0
	n := len(dec.bucket[0])
	for i := index + 1; i < len(dec.bucket[h]); i++ {
		if i%dec.chunk == 0 {
			i /= dec.chunk - 1
			h++
			continue
		}
		if k > dec.bucket[h][i] {
			k -= dec.bucket[h][i]
			continue
		}
		if h == 0 {
			return i
		}
		h--
		i = i*dec.chunk - 1
	}
	return n
}

