auto solve( long[] ps )
{
	auto ans = 0L;

	for( auto l = 0L; l < ps.length; l++ )
	{
		auto f = ps[ l ];
		auto s = 0L;
		for( auto r = l + 1; r < ps.length; r++ )
		{
			if( f < ps[ r ] )
			{
				s = f;
				f = ps[ r ];
			}
			else if( s < ps[ r ] )
			{
				s = ps[ r ];
			}
			ans += s;
		}
	}
	return ans;
}

