const long infty = 1_000_009;

void solve(){
	int n = rint;
	int[] ps = rint(n);

	S marge(S p, S q){
		return S(max(p.best, q.best), max(min(p.best, q.best), max(p.next, q.next)));
	}
	S neginf = S(-infty, -infty);
	SegTree!S seg = new SegTree!S(0, n, &marge, neginf);
	foreach(int i, p; ps){
		seg.setValue(i, S(p, -infty));
	}
	log("seg:", seg);

	long ans;
	foreach(int i, p; ps){
		int l2 = downlimit!int(0, i, x => (seg.getValue(x, i + 1).best == ps[i]));
		int l1 = downlimit!int(0, l2 - 1, x => (seg.getValue(x, i + 1).next == ps[i]));
		int r1 = uplimit!int(i, n - 1, x => (seg.getValue(i, x + 1).best == ps[i]));
		int r2 = uplimit!int(r1 + 1, n - 1, x => (seg.getValue(i, x + 1).next == ps[i]));
		long tmp = (l2 - l1) * (r1 + 1 - i) + (r2 - r1) * (i + 1 - l2);
		log("i:", i, "p:", p, "l1:", l1, "l2:", l2, "r1:", r1, "r2:", r2);
		log("   ", (l2 - l1), " * ", (r1 + 1 - i), " + ", (r2 - r1), " * ", (i + 1 - l1), "tmp:", tmp);
		ans += tmp * p;
	}

	ans.writeln;
}

