auto solve(long N, long[] P) {
    const DUMMY = -1;

    P = DUMMY ~ P ~ DUMMY;
    auto rSight = iota(1, N + 3).array;
    auto lSight = iota(-1, N + 1).array;
    auto indiceOrder = P.enumerate
        .array
        .sort!"a[1] < b[1]"
        .map!"a[0]"
        .drop(2)
        .take(N - 1);

    long ans;
    foreach (i; indiceOrder) {
        long waysToMakeRange;
        if (0 < lSight[i] && lSight[i] < N + 1)
            waysToMakeRange += (lSight[i] - lSight[lSight[i]]) * (rSight[i] - i);
        if (0 < rSight[i] && rSight[i] < N + 1)
            waysToMakeRange += (rSight[rSight[i]] - rSight[i]) * (i - lSight[i]);

        ans += P[i] * waysToMakeRange;

        rSight[lSight[i]] = rSight[i];
        lSight[rSight[i]] = lSight[i];
    }

    return ans;
}


