import strutils,sequtils
import algorithm,sets,lists,critbits,sequtils,intsets,strutils,tables,math,heapqueue,future

type
  Node[T] = ref object
    key: T
    priority: int
    left: Node[T]
    right: Node[T]
  Treap[T]  = ref object
    root: Node[T]

proc xorshift*(): int =
  var
    x {.global.}: uint32 = 123456789
    y {.global.}: uint32 = 362436069
    z {.global.}: uint32 = 521288629
    w {.global.}: uint32 = 88675123
    t {.global.}: uint32
  t = x xor (x shl 11); x = y; y = z; z = w;
  w = (w xor (w shr 19)) xor (t xor (t shr 8))
  return int(w)

proc newNode*[T](key: T, priority: int, left: Node[T], right: Node[T]): Node[T] =
  Node[T](key: key, priority: priority, left: left, right: right)

proc newTreap*[T](): Treap[T] =
  Treap[T](root: nil)

proc split*[T](v: Node[T], key: T, left: var Node[T], right: var Node[T]) =
  if v == nil:
    left = nil
    right = nil
  elif key < v.key:
    split(v.left, key, left, v.left)
    right = v
  else:
    split(v.right, key, v.right, right)
    left = v

proc merge*[T](v: var Node[T], left: Node[T], right: Node[T]) =
  if left == nil:
    v = right
  elif right == nil:
    v = left
  elif left.priority > right.priority:
    merge(left.right, left.right, right)
    v = left
  else:
    merge(right.left, left, right.left)
    v = right

proc insert*[T](v: var Node[T], item: Node[T]) =
  if v == nil:
    v = item
  elif item.key == v.key:
    return
  elif item.priority > v.priority:
    split(v, item.key, item.left, item.right)
    v = item
  elif item.key < v.key:
    insert(v.left, item)
  else:
    insert(v.right, item)

proc erase*[T](v: var Node[T], key: T) =
  if v == nil:
    return
  elif key == v.key:
    merge(v, v.left, v.right)
  elif key < v.key:
    erase(v.left, key)
  else:
    erase(v.right, key)

proc find*[T](v: var Node[T], key: T): bool =
  if v == nil:
    return false
  elif key == v.key:
    return true
  elif key < v.key:
    return find(v.left, key)
  else:
    return find(v.right, key)

proc min*[T](v: var Node[T]): Node[T] =
  if v.left == nil:
    return v
  else:
    return min(v.left)

proc max*[T](v: var Node[T]): Node[T] =
  if v.right == nil:
    return v
  else:
    return max(v.right)

proc greater*[T](v: var Node[T], key: T, including: bool): Node[T] =
  if v == nil:
    return nil
  if including and v.key == key:
    return v
  if key < v.key:
    result = greater(v.left, key, including)
    if result == nil:
      return v
  else:
    result = greater(v.right, key, including)

proc less*[T](v: var Node[T], key: T, including: bool): Node[T] =
  if v == nil:
    return nil
  if including and v.key == key:
    return v
  elif key > v.key:
    result = less(v.right, key, including)
    if result == nil:
      return v
  else:
    result = less(v.left, key, including)

proc insert*[T](tree: Treap[T], key: T) =
  let node = newNode[T](key, xorshift(), nil, nil)
  insert(tree.root, node)

proc erase*[T](tree: Treap[T], key: T) =
  if tree.root == nil: return
  erase(tree.root, key)

proc find*[T](tree: Treap[T], key: T): bool =
  return find(tree.root, key)

proc min*[T](tree: Treap[T]): Node[T] =
  if tree.root == nil: return nil
  result = min(tree.root)

proc max*[T](tree: Treap[T]): Node[T] =
  if tree.root == nil: return nil
  result = max(tree.root)

proc greater*[T](tree: Treap[T], key: T, including: bool): Node[T] =
  if tree.root == nil: return nil
  result = greater(tree.root, key, including)

proc less*[T](tree: Treap[T], key: T, including: bool): Node[T] =
  if tree.root == nil: return nil
  result = less(tree.root, key, including)

