# SegmentTree : a struct to efficiently calculate fold(op, raw[l:r]) for associative op such as `+`, `*`, min, max
# st = newSegmentTree[int](@[1,2,3,4,5,6],proc(x:int,y:int):int=(x+y),0)
# st.set(k,x) <=> raw[k] = x   : O(logN)
# st.get(l,r) == fold(op, raw[l:r])    : O(logN)


#  k
# / \
#2k 2k+1

type SegmentTree*[T] = object
  size: int
  data: seq[T]
  op: proc(x:T, y:T):T
  unit: T

proc build*[T](st:var SegmentTree[T]) =
  for k in countdown(st.size-1,1):
    st.data[k] = st.op(st.data[2*k], st.data[2*k+1])

proc newSegmentTree*[T](length: int, op:proc(x:T,y:T):T, unit:T) :SegmentTree[T] =
  let size = nextPowerOfTwo(length)
  var data = newSeq[T](2*size)
  for i in size..<2*size:
    data[i] = unit
  result = SegmentTree[T](size:size, data:data, op:op, unit:unit)
  result.build()

proc newSegmentTree*[T](raw:seq[T], op:proc(x:T,y:T):T, unit:T) :SegmentTree[T] =
  let size = nextPowerOfTwo(raw.len)
  var data = newSeq[T](2*size)
  for i,d in raw:
    data[size+i] = raw[i]
  for i in raw.len..<size:
    data[size+i] = unit
  result = SegmentTree[T](size:size, data:data, op:op, unit:unit)
  result.build()

proc set*[T](st: var SegmentTree[T], i:int, x:T) =
  var k = i + st.size
  st.data[k] = x
  k = k shr 1
  while k>0:
    st.data[k] = st.op(st.data[2*k], st.data[2*k+1])
    k = k shr 1

proc get*[T](st: SegmentTree[T], l:int, r:int) :T=
  var L = st.unit
  var R = st.unit
  var a = l + st.size
  var b = r + st.size
  while a < b:
    if (a and 1) == 1:
      L = st.op(st.data[a],L)
      a += 1
    if (b and 1) == 1:
      R = st.op(R, st.data[b-1])
      b -= 1
    a = a shr 1
    b = b shr 1
  return st.op(L,R)

