        index = (index and (index - 1))

proc search(BIT : binaryIndexTree, a : int):int =

    proc bs(m, M, s : int) : int =
        if M - m <= 1:
            return M
        var mid = (M + m) div 2
        if mid >= BIT[0] or s + BIT[mid] >= a:
            return bs(m, mid, s)
        return bs(mid, M, s + BIT[mid])

    if BIT.sum(BIT[0]) < a:
        return BIT[0] + 1
    var
        index = 1
    while index < BIT[0]:
        index *= 2
    return bs(0, index, 0)

