import bisect
def cl(l, x):
    if x < 0:
        return 0
    if x == 0:
        return l[0] + 1
    return l[x] - l[x-1]
def cr(l, x, N):
    if x >= len(l):
        return 0
    if x == len(l) - 1:
        return N - l[x]
    return l[x+1] - l[x]
def main():
    N = int(input())
    P = list(map(int, input().split()))
    d = {}
    for i, v in enumerate(P):
        d[v] = i
    l = [d[N]]
    r = 0
    for i in reversed(range(1, N)):
        x = bisect.bisect_left(l, d[i])
        l = l[:x] + [d[i]] + l[x:]
        r += i * (cl(l, x) * cr(l, x+1, N) + cl(l, x-1) * cr(l, x, N))
    return r
