def slv(N, P):
    P2 = [(p, i) for i, p in enumerate(P)]
    P2.sort(reverse=True)
    done = [0, N+1]
    ans = 0
    for p, i in P2:
        i += 1
        j = bisect.bisect(done, i)
        bisect.insort(done, i)
        c = 0
        if j >= 2:
            l = done[j-1] - done[j-2]
            r = done[j+1] - done[j]
            c += l * r
        if j <= len(done) - 3:
            l = done[j] - done[j-1]
            r = done[j+2] - done[j+1]
            c += l*r
        ans += c*p

    return ans


