    P = LI()

    tree = BalancingTree()
    stoi = [None] * (N + 1)

    for i, pi in enumerate(P):
        stoi[pi] = i

    tree.append(stoi[N])
    ans = 0

    for pi in range(1, N)[::-1]:
        i = stoi[pi]
        tree.append(i)
        l = tree.find_l(i)
        r = tree.find_r(i)
        k = (i + 1 if l == -1 else i - l)
        m = (N - i if r == tree.root.value - 1 else r - i)

        ll = tree.find_l(l)
        rr = tree.find_r(r)

        if l == -1:
