import bisect
def cl(l, x):
    if x < 0:
        return 0
    if x == 0:
        return l[0] + 1
    return l[x] - l[x-1]
def cr(l, x, N):
    if x >= len(l):
        return 0
    if x == len(l) - 1:
        return N - l[x]
    return l[x+1] - l[x]
