@functools.lru_cache(maxsize=None)
def x(start, end):
    if start + 1 == end:
        return min(p[start-1], p[end-1]), max(p[start-1], p[end-1])
    if start + 2 == end:
        var1 = p[start-1]
        var2 = p[start]
