    P = [int(p) for p in input().split()]
    pindex = [None] * N
    for i, p in enumerate(P): pindex[p - 1] = i
    Ans = 0
    T = AVLTree()
    T.insert(pindex[N-1])
    for i in range(N-2, -1, -1):
        pid = pindex[i]
        left, right = T.lower_bound(pid, -1), T.upper_bound(pid, N)
        l2 = T.lower_bound(left, -1)
        if right == N: r2 = N
        else: r2 = T.upper_bound(right, N)
