            way = 'r'

        self.rebalance(p, way)

    def rebalance(self, v, dir_vw):
        while v.color == 'red':
            u = v.parent
            if v.key < u.key:
                x = u.right
                if x and x.color == 'red':
                    if u != self.root:
                        u.color = 'red'
                    v.color = 'black'
                    x.color = 'black'
                else:
                    if dir_vw == 'l':
                        self.rotate_r(u, v)
                        return
                    else:
                        self.rotate_lr(u, v)
                        return
            else:
                x = u.left
                if x and x.color == 'red':
                    if u != self.root:
