                    x.color = 'black'
                    v.color = 'black'
                else:
                    if dir_vw == 'r':
                        self.rotate_l(u, v)
                        return
                    else:
                        self.rotate_rl(u, v)
                        return
            dir_vw = self.get_way(u.parent, u)
            v = u.parent 

    def rotate_r(self, u, v, d=False):
        w = v.left
        v.left = v.right
        v.right = u.right        
        if v.right:
            v.right.parent = v

        w.parent = u

        u.left = w
        u.right = v
        u.key, v.key = v.key, u.key

        if d:
            w.color = 'black'

    def rotate_lr(self, u, v, d=False):
        w = v.right
        v.right = w.left
        if v.right:
            v.right.parent = v

        w.left = w.right
        w.right = u.right
        if w.right:
            w.right.parent = w
        w.parent = u

        u.right = w
        u.key, w.key = w.key, u.key

        if d:
            w.color = 'black'

    def rotate_l(self, u, v, d=False):
        w = v.right

        v.right = v.left
        v.left = u.left
        if v.left:
            v.left.parent = v

        w.parent = u

        u.right = w
        u.left = v
        u.key, v.key = v.key, u.key

        if d:
            w.color = 'black'

    def rotate_rl(self, u, v, d=False):
        w = v.left

        v.left = w.right
        if v.left:
            v.left.parent = v

        w.right = w.left
        w.left = u.left
        if w.left:
            w.left.parent = w
        w.parent = u

        u.left = w
        u.key, w.key = w.key, u.key

        if d:
            w.color = 'black'

    def get_way(self, u, v):
        if u.left == v:
            return 'l'
        else:
            return 'r'

