            while j-i>1:
                if ST.get(index+1,(i+j)//2)<num:
                    i = (i+j)//2
                else:
                    j = (i+j)//2
            return j
        else:
            while j-i>1:
                if ST.get((i+j)//2,index-1)<num:
                    j = (i+j)//2
                else:
                    i = (i+j)//2
            return i

