            left1 = 1
            left2 = 1

        elif i==N-1:
            left1 = bisect(0,i-1,ST,P[i],i,P,Smin,Smin_rev,True)
            if left1<=0:
                left2 = -1
            else:
                left2 = bisect(0,left1-1,ST,P[i],left1,P,Smin,Smin_rev,True)
            left1,left2 = i-left1,i-left2
            right1 = 1
            right2 = 1
        else:
            right1 = bisect(i+1,N-1,ST,P[i],i,P,Smin,Smin_rev,False)
            if right1>=N-1:
                right2 = N
