def search_index(x, sorted_ls):
    '''
    ソート済み配列からxの入る位置を返す and sorted_lsにxを挿入。
    xの入る位置が複数ある場合は一番左のindexを返す。
    '''
    n = len(sorted_ls)
    l = 0
    r = n
    while l != r:
        a = (r + l)//2
        if x <= sorted_ls[a]:
            r = a
        else:
            l = a + 1
    sorted_ls.insert(l, x)
    return l


