def read_line(n=0):
    if n == 0:
        return input().rstrip()
    else:
        return input().rstrip()[:n]


def think(data):
    n = len(data)
    dp = [[0 for x in range(n)] for y in range(n)]

    # dp[left][right] is second maximum value about pair(L, R)

    for i in range(n - 1):
        dp[i][i + 1] = min(data[i], data[i + 1])
    for left in range(0, n - 1):
        for right in range(left + 2, n):
            if dp[left][right - 1] > data[right]:
                dp[left][right] = dp[left][right - 1]
            else:
                buf = data[:right + 1]
                buf = buf[left:]
                buf.sort(key=lambda x: -x)
                dp[left][right] = buf[1]

    total = 0
    for y in range(n):
        total += sum(dp[y])
    return total


