def think(data):
    n = len(data)
    dp1 = [[0 for x in range(n)] for y in range(n)]
    dp2 = [[0 for x in range(n)] for y in range(n)]

    # dp1[left][right] is maximum value about pair(L, R)
    # dp2[left][right] is second maximum value about pair(L, R)

    for i in range(n - 1):
        dp1[i][i + 1] = max(data[i], data[i + 1])
        dp2[i][i + 1] = min(data[i], data[i + 1])

    for left in range(0, n - 1):
        for right in range(left + 2, n):
            if dp2[left][right - 1] > data[right]:
                dp2[left][right] = dp2[left][right - 1]
                dp1[left][right] = dp1[left][right - 1]
            else:
                if dp1[left][right - 1] <= data[right]:
                    dp2[left][right] = dp1[left][right - 1]
                    dp1[left][right] = data[right]
                else:
                    dp1[left][right] = dp1[left][right - 1]
                    dp2[left][right] = data[right]

    total = 0
    for y in range(n):
        total += sum(dp2[y])
    return total


