def f(Q):
    if len(Q)==2:
        return min(Q)
    else:
        s = 0
        r = Q.popleft()
        Max = r
        second_Max = 0
        for q in Q:
            if q>Max:
                second_Max = Max
                Max = q
            elif second_Max<q<=Max:
                second_Max = q
            s += second_Max
        return(f(Q) + s)

