    class BIT():
        def __init__(self,n):
            self.num=n
            self.dat=[0]*(self.num+1)

        def add(self,i,x):
            i+=1
            while i<=self.num:
                self.dat[i]+=x
                i+=i&-i

        def sum(self,i):
            i+=1
            s=0
            while i>0:
                s+=self.dat[i]
                i-=i&-i
            return s

    N=int(input())
    P=list(map(int,input().split()))
    P2=[(P[i],i) for i in range(N)]
    P2.sort(reverse=True)
    b=BIT(N)

    def nibutan(i,num,ok,ng):
        while abs(ok-ng) > 1:
            mid = (ok + ng) // 2
            if solve(i,num,mid):
                ok = mid
            else:
                ng = mid
        return ok

    def solve(i,num,mid):
        if i>mid:
            if b.sum(i)-b.sum(mid-1) >= num:
                return True
        else:
            if b.sum(mid)-b.sum(i) >= num:
                return True
        return False

    ans=0
    for p in P2:
        s=nibutan(p[1],1,-1,p[1])
        t=nibutan(p[1],2,-1,p[1])
        u=nibutan(p[1],1,N,p[1])
