use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        xs: [usize; n],
    }
    let mut bit = BIT::new(n + 4);
    let mut ys = vec![0; n + 1];
    for (i, &x) in xs.iter().enumerate() {
        ys[x] = i + 1;
    }
    // eprintln!("ys = {:?}", ys);
    for i in 1..n + 1 + 2 {
        bit.add(i, 1);
    }
    let mut res = 0i64;
    for &i in &ys[1..] {
        // eprintln!("i = {}, xs[i-1] = {}", i, xs[i-1]);

        let l1 = bit.max_non_zero_index(i - 1);
        // eprintln!("l1 = {}", l1);
        if l1 != 0 {
            let l2 = bit.max_non_zero_index(l1 - 1);
            let r = bit.min_non_zero_index(i);
            // eprintln!("r = {}", r);
            let t = (r - i) as i64 * (l1 - l2) as i64;
            // eprintln!("t = {}", t);
            res += xs[i - 1] as i64 * t;
        }

        let r1 = bit.min_non_zero_index(i);
        // eprintln!("r1 = {}", r1);
        if r1 <= n {
            let r2 = bit.min_non_zero_index(r1);
            let l = bit.max_non_zero_index(i - 1);
            // eprintln!("l = {}", l);
            let t = (i - l) as i64 * (r2 - r1) as i64;
            // eprintln!("t = {}", t);
            res += xs[i - 1] as i64 * t;
        }

        bit.add(i, -1);
    }
    writeln!(buf, "{}", res);
    buf
}

use std::cmp;

fn read_line() -> String {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim_right().to_owned()
}

fn to_vec(s: String, offset: u64) -> Vec<u64> {
    s.split_whitespace()
        .map(|s| s.parse::<u64>().unwrap() - offset)
        .collect()
}

fn evaluate(v: &[u64]) -> u64 {
    let n = v.len();
    if n == 2 {
        return cmp::min(v[0], v[1]);
    };
    let mid = n / 2;
    let edge = evaluate(&v[..mid]) + evaluate(&v[mid..]);

    let mut squre = 0;
    for i in 0..mid {
        let mut s: Vec<u64> = v[i..mid].iter().cloned().collect();
        s.sort();
        for &x in &v[mid..] {
            s.push(x);
            s.sort();
            squre += s[s.len() - 2];
        }
    }

    edge + squre
}

fn main() {
    let n: usize = read_line().parse().unwrap();
    let ps = to_vec(read_line(), 1);

    let ps_offset = (n * (n - 1) / 2) as u64;
    let val = evaluate(&ps);

    println!("{}", val + ps_offset);
}

