    };
}

macro_rules! input_inner {
    ($iter:expr) => {};
    ($iter:expr, ) => {};

    ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($iter, $t);
        input_inner!{$iter $($r)*}
    };
}

macro_rules! read_value {
    ($iter:expr, ( $($t:tt),* )) => {
        ( $(read_value!($iter, $t)),* )
    };

    ($iter:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
    };

    ($iter:expr, chars) => {
        read_value!($iter, String).chars().collect::<Vec<char>>()
    };

    ($iter:expr, usize1) => {
        read_value!($iter, usize) - 1
    };

    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input!{
        n: usize,
        v: [usize; n],
    }

    let mut xlr = 0;
    let mut imap = BTreeMap::new();

    for i in 0..n {
        imap.insert(v[i], i);
    }

    let mut iter = imap.iter().rev();

    let mut iset = BTreeSet::new();
    iset.insert(0);
    iset.insert(n+1);

    for (key, value) in iter {

        iset.insert((*value)+1);
        let mut sset = iset.split_off(&(value+1));
        //let mut trange = iset.range(0..value+1).rev();
        let mut x = &0;
        let mut w = &0;
        {
            let mut trange = iset.iter().rev();
            x = trange.next().unwrap();
            if x != &0 {
                w = trange.next().unwrap(); 
            }
        } 

        //let mut srange = iset.range(value+1..n+2);
        let mut y = 0;
        let mut z = (n+1);
        {
            let mut srange = sset.iter();
            srange.next();
            y = *srange.next().unwrap();
            if y != (n+1) {
                z = *srange.next().unwrap();
            }
        }

        xlr = xlr + ((x - w) * (y - (value+1)) + ((value+1) - x) * (z - y)) * key;

        for sn in sset.iter() {
            iset.insert(*sn);
        }

        if key == &0 {
            break;
        }

    }

    println!("{}", xlr);
}

