fn main() {
    input! {
        n: usize,
        p: [i64; n]
    };

    let mut p = p.into_iter().zip(1..n+1).collect::<Vec<_>>();
    p.sort_by_key(|&(v,i)| -v);

    let mut treap = Treap::new();
    treap.push(0);
    treap.push(n+1);
    treap.push(p[0].1);
    let mut total = 0;
    for i in 1..n {
        let mut ways = 0;
        let v = p[i].0;
        let idx = p[i].1;
        let left = treap.peek_less(idx).unwrap();
        let right = treap.peek_greater(idx).unwrap();
        if left != 0 {
            let tl = treap.peek_less(left).unwrap();
            let lway = (left - tl) as i64;
            let rway = (right - idx) as i64;
            ways += lway * rway;
        }
        if right != n+1 {
            let tr = treap.peek_greater(right).unwrap();
            let lway = (idx - left) as i64;
            let rway = (tr - right) as i64;
            ways += lway * rway;
        }
        // debug!(v, ways, left, right);
        total += v * ways;
        treap.push(idx);
    }

    println!("{}", total);
}

