fn solve() {
    input!{
        N:usize,
        p:[usize;N],
    }
    let mut set = BTreeSet::new();
    let mut ps=vec![];
    for i in 0..p.len() {
        ps.push((p[i],i+1));
    }
    ps.sort();
    ps.reverse(); // asc

    let mut ans=0;
    for x in ps {
        let p = x.0;
        let i = x.1;
        let mut right=vec![];
        let mut right_it = set.range(i+1..);
        if let Some(x) = right_it.next() {
            right.push(*x);
        }
        if let Some(x) = right_it.next() {
            right.push(*x);
        }
        let mut left=vec![];
        let mut left_it = set.range(..i);
        if let Some(x) = left_it.next() {
            left.push(*x);
        }
        if let Some(x) = left_it.next() {
            left.push(*x);
        }

        while left.len() < 2 {
            left.push(0);
        }
        while right.len() < 2 {
            right.push(N+1);
        }
        left.sort();
        right.sort();

        let ci = (left[1]-left[0])*(right[0]-i) + (right[1]-right[0])*(i-left[1]);
        ans+=p*ci;

        set.insert(i);
    }
    println!("{}",ans);
}

