fn search(n: usize, v: &Vec<usize>) -> Vec<(usize, usize)> {
    let mut ret = vec![(0, 0); n];
    let mut segt = LSegT::new(n);
    for i in 0..n {
        let (a, b) = segt.get(v[i]);
        ret[v[i]].0 = (i as i64 - a) as usize;
        ret[v[i]].1 = (a - b) as usize;
        segt.update(0, v[i], i as i64);
    }
    ret
}

struct LSegT {
    v: Vec<(i64, i64)>,
    lazy: Vec<(i64, i64)>,
    n: usize
}

impl LSegT {
    fn new(n: usize) -> LSegT {
        let mut s = 1;
        while s < n {
            s *= 2;
        }
        LSegT{v: vec![(-1, -1); 2 * s - 1], lazy: vec![(-1, -1); 2 * s - 1], n: s}
    }

    fn eval(&mut self, p: usize) {
        if self.lazy[p] == (-1, -1) {
            return;
        }
        if self.v[p].0 > self.lazy[p].0 {
            self.v[p].1 = max(self.v[p].1, self.lazy[p].0);
        } else if self.v[p].0 == self.lazy[p].0 {
            self.v[p].1 = max(self.v[p].1, self.lazy[p].1);
        } else {
            self.v[p].1 = max(self.v[p].0, self.lazy[p].1);
            self.v[p].0 = self.lazy[p].0;
        }
        if p < self.n - 1 {
            if self.lazy[2 * p + 1].0 > self.lazy[p].0 {
                self.lazy[2 * p + 1].1 = max(self.lazy[2 * p + 1].1, self.lazy[p].0);
            } else if self.lazy[2 * p + 1].0 == self.lazy[p].0 {
                self.lazy[2 * p + 1].1 = max(self.lazy[2 * p + 1].1, self.lazy[p].1);
            } else {
                self.lazy[2 * p + 1].1 = max(self.lazy[2 * p + 1].0, self.lazy[p].1);
                self.lazy[2 * p + 1].0 = self.lazy[p].0;
            }
            if self.lazy[2 * p + 2].0 > self.lazy[p].0 {
                self.lazy[2 * p + 2].1 = max(self.lazy[2 * p + 2].1, self.lazy[p].0);
            } else if self.lazy[2 * p + 2].0 == self.lazy[p].0 {
                self.lazy[2 * p + 2].1 = max(self.lazy[2 * p + 2].1, self.lazy[p].1);
            } else {
                self.lazy[2 * p + 2].1 = max(self.lazy[2 * p + 2].0, self.lazy[p].1);
                self.lazy[2 * p + 2].0 = self.lazy[p].0;
            }
        }
        self.lazy[p] = (-1, -1);
    }

    fn update(&mut self, l: usize, r: usize, x: i64) {
        let n = self.n;
        self.update_rec(l, r, x, 0, 0, n - 1);
    }

    fn update_rec(&mut self, l: usize, r: usize, x: i64, p: usize, pl: usize, pr: usize) {
        self.eval(p);
        if pl > r || pr < l {
            return;
        } else if l <= pl && pr <= r {
            if x != self.lazy[p].0 {
                self.lazy[p].1 = self.lazy[p].0;
                self.lazy[p].0 = x;
            }
            self.eval(p);
        } else {
            self.update_rec(l, r, x, 2 * p + 1, pl, (pl + pr - 1) / 2);
            self.update_rec(l, r, x, 2 * p + 2, (pl + pr + 1) / 2, pr);
        }
    }

    fn get(&mut self, l: usize) -> (i64, i64) {
        let n = self.n;
        self.get_rec(l, 0, 0, n - 1)
    }

    fn get_rec(&mut self, l: usize, p: usize, pl: usize, pr: usize) -> (i64, i64) {
        self.eval(p);
        if pl > l || pr < l {
            (-1, -1)
        } else if l == pl && pr == l {
            self.v[p]
        } else if l <= (pl + pr - 1) / 2 {
            self.get_rec(l, 2 * p + 1, pl, (pl + pr - 1) / 2)
        } else {
            self.get_rec(l, 2 * p + 2, (pl + pr + 1) / 2, pr)
        }
    }
}

use std::borrow::Borrow;
use std::cmp::Ordering::*;
use std::default::Default;
/// Implementation of AVL tree
use std::io::{stdin, Read};
use std::iter::{FromIterator, Iterator};
use std::mem;
use std::ops::Index;

#[derive(Debug)]
pub enum AVLTree<T> {
    Empty,
    NonEmpty(Box<Node<T>>),
}
use AVLTree::*;

#[derive(Debug)]
pub struct Node<T> {
    pub value: T,
    pub left: AVLTree<T>,
    pub right: AVLTree<T>,
    balance_factor: i8,
}

impl<T> Default for AVLTree<T> {
    fn default() -> Self {
        Empty
    }
}

impl<T> AVLTree<T>
where
    T: Ord,
{
    pub fn insert(&mut self, value: T) -> bool {
        self.add(value).0
    }

    fn add(&mut self, value: T) -> (bool, bool) {
        // returns: (inserted, deepened)
        let ret = match *self {
            Empty => {
                let node = Node {
                    value: value,
                    left: Empty,
                    right: Empty,
                    balance_factor: 0,
                };
                *self = NonEmpty(Box::new(node));
                (true, true)
            }
            NonEmpty(ref mut node) => match node.value.cmp(&value) {
                Equal => (false, false),
                Less => {
                    let (inserted, deepened) = node.right.add(value);
                    if deepened {
                        let ret = match node.balance_factor {
                            -1 => (inserted, false),
                            0 => (inserted, true),
                            1 => (inserted, false),
                            _ => unreachable!(),
                        };
                        node.balance_factor += 1;
                        ret
                    } else {
                        (inserted, deepened)
                    }
                }
                Greater => {
                    let (inserted, deepened) = node.left.add(value);
                    if deepened {
                        let ret = match node.balance_factor {
                            -1 => (inserted, false),
                            0 => (inserted, true),
                            1 => (inserted, false),
                            _ => unreachable!(),
                        };
                        node.balance_factor -= 1;
                        ret
                    } else {
                        (inserted, deepened)
                    }
                }
            },
        };
        self.balance();
        ret
    }

    fn balance(&mut self) {
        match *self {
            Empty => (),
            NonEmpty(_) => match self.node().balance_factor {
                -2 => {
                    let lf = self.node().left.node().balance_factor;
                    if lf == -1 || lf == 0 {
                        let (a, b) = if lf == -1 { (0, 0) } else { (-1, 1) };
                        self.rotate_right();
                        self.node().right.node().balance_factor = a;
                        self.node().balance_factor = b;
                    } else if lf == 1 {
                        let (a, b) = match self.node().left.node().right.node().balance_factor {
                            -1 => (1, 0),
                            0 => (0, 0),
                            1 => (0, -1),
                            _ => unreachable!(),
                        };
                        self.node().left.rotate_left();
                        self.rotate_right();
                        self.node().right.node().balance_factor = a;
                        self.node().left.node().balance_factor = b;
                        self.node().balance_factor = 0;
                    } else {
                        unreachable!()
                    }
                }
                2 => {
                    let lf = self.node().right.node().balance_factor;
                    if lf == 1 || lf == 0 {
                        let (a, b) = if lf == 1 { (0, 0) } else { (1, -1) };
                        self.rotate_left();
                        self.node().left.node().balance_factor = a;
                        self.node().balance_factor = b;
                    } else if lf == -1 {
                        let (a, b) = match self.node().right.node().left.node().balance_factor {
                            1 => (-1, 0),
                            0 => (0, 0),
                            -1 => (0, 1),
                            _ => unreachable!(),
                        };
                        self.node().right.rotate_right();
                        self.rotate_left();
                        self.node().left.node().balance_factor = a;
                        self.node().right.node().balance_factor = b;
                        self.node().balance_factor = 0;
                    } else {
                        unreachable!()
                    }
                }
                _ => (),
            },
        }
    }

    fn node(&mut self) -> &mut Node<T> {
        match *self {
            Empty => panic!("call on empty tree"),
            NonEmpty(ref mut v) => v,
        }
    }

    fn right(&mut self) -> &mut Self {
        match *self {
            Empty => panic!("call on empty tree"),
            NonEmpty(ref mut node) => &mut node.right,
        }
    }

    fn left(&mut self) -> &mut Self {
        match *self {
            Empty => panic!("call on empty tree"),
            NonEmpty(ref mut node) => &mut node.left,
        }
    }

    fn rotate_right(&mut self) {
        let mut v = mem::replace(self, Empty);
        let mut left = mem::replace(v.left(), Empty);
        let left_right = mem::replace(left.right(), Empty);
        *v.left() = left_right;
        *left.right() = v;
        *self = left;
    }

    fn rotate_left(&mut self) {
        let mut v = mem::replace(self, Empty);
        let mut right = mem::replace(v.right(), Empty);
        let right_left = mem::replace(right.left(), Empty);
        *v.right() = right_left;
        *right.left() = v;
        *self = right;
    }

    #[cfg(test)]
    fn depth(&self) -> usize {
        match *self {
            Empty => 0,
            NonEmpty(ref v) => std::cmp::max(v.left.depth(), v.right.depth()) + 1,
        }
    }

    pub fn len(&self) -> usize {
        match *self {
            Empty => 0,
            NonEmpty(ref v) => 1 + v.left.len() + v.right.len(),
        }
    }
    pub fn is_empty(&self) -> bool {
        match *self {
            Empty => true,
            _ => false,
        }
    }

    pub fn iter<'a>(&'a self) -> RangeIter<'a, T, &T> {
        self.range(None, None)
    }

    pub fn range<'a, 'b, K>(&'a self, l: Option<&'b K>, r: Option<&'b K>) -> RangeIter<'a, T, &'b K>
    where
        T: Borrow<K>,
        K: ?Sized + Ord,
    {
        RangeIter::new(self, l, r)
    }

    pub fn get<Q>(&self, value: &Q) -> Option<&T>
    where
        T: Borrow<Q>,
        Q: ?Sized + Ord,
    {
        match *self {
            Empty => None,
            NonEmpty(ref node) => match value.cmp(node.value.borrow()) {
                Less => node.left.get(value),
                Equal => Some(&node.value),
                Greater => node.right.get(value),
            },
        }
    }

    #[cfg(test)]
    fn value(&self) -> Option<&T> {
        match *self {
            Empty => None,
            NonEmpty(ref v) => Some(&v.value),
        }
    }
}

pub struct IntoIter<T> {
    stack: Vec<Node<T>>,
}

impl<T> IntoIter<T> {
    pub fn new(tree: AVLTree<T>) -> Self {
        let mut into_iter = IntoIter { stack: Vec::new() };
        into_iter.traverse_left(tree);
        into_iter
    }

    fn traverse_left(&mut self, mut tree: AVLTree<T>) {
        while let NonEmpty(mut node) = tree {
            tree = mem::replace(&mut node.left, Empty);
            self.stack.push(*node);
        }
    }
}

impl<T> Iterator for IntoIter<T> {
    type Item = T;
    fn next(&mut self) -> Option<Self::Item> {
        let mut node = match self.stack.pop() {
            None => return None,
            Some(node) => node,
        };
        self.traverse_left(mem::replace(&mut node.right, Empty));
        Some(node.value)
    }
}

impl<T> IntoIterator for AVLTree<T> {
    type Item = T;
    type IntoIter = IntoIter<T>;
    fn into_iter(self) -> Self::IntoIter {
        IntoIter::new(self)
    }
}

impl<T: Ord> FromIterator<T> for AVLTree<T> {
    fn from_iter<I: IntoIterator<Item = T>>(iter: I) -> Self {
        let mut tree = Empty;
        for v in iter {
            tree.insert(v);
        }
        tree
    }
}

impl<'a, T: Ord> Index<&'a T> for AVLTree<T> {
    type Output = T;
    fn index(&self, index: &T) -> &Self::Output {
        self.get(index).unwrap()
    }
}

pub struct RangeIter<'a, T: 'a, K> {
    end: Option<K>,
    stack: Vec<&'a Node<T>>,
}

impl<'a, 'b, T, K> RangeIter<'a, T, &'b K>
where
    T: Ord + Borrow<K>,
    K: ?Sized + Ord,
{
    fn new(tree: &'a AVLTree<T>, start: Option<&'b K>, end: Option<&'b K>) -> Self {
        let mut iter = RangeIter {
            end: end,
            stack: Vec::new(),
        };
        match start {
            None => iter.traverse_left(tree),
            Some(i) => iter.traverse(tree, i),
        }
        iter
    }
    fn traverse_left(&mut self, mut tree: &'a AVLTree<T>) {
        while let NonEmpty(ref node) = *tree {
            self.stack.push(node);
            tree = &node.left;
        }
    }
    fn traverse(&mut self, tree: &'a AVLTree<T>, start: &K) {
        match *tree {
            Empty => (),
            NonEmpty(ref node) => match start.cmp(node.value.borrow()) {
                Less => {
                    self.stack.push(&node);
                    self.traverse(&node.left, start);
                }
                Equal => self.stack.push(&node),
                Greater => {
                    self.traverse(&node.right, start);
                }
            },
        }
    }
}

impl<'a, 'b, T, K> Iterator for RangeIter<'a, T, &'b K>
where
    T: Ord + Borrow<K>,
    K: ?Sized + Ord,
{
    type Item = &'a T;
    fn next(&mut self) -> Option<Self::Item> {
        match self.stack.pop() {
            None => None,
            Some(ref node) => match self.end {
                None => {
                    self.traverse_left(&node.right);
                    Some(&node.value)
                }
                Some(r) => match r.cmp(&node.value.borrow()) {
                    Greater => {
                        self.traverse_left(&node.right);
                        Some(&node.value)
                    }
                    _ => None,
                },
            },
        }
    }
}

macro_rules! parse {
