    };
}

use std::cmp::Ordering;
use std::cmp::Ordering::*;
use std::cmp::PartialOrd;

#[derive(PartialEq, Eq)]
struct Rev<T>(T);

impl<T: Ord> PartialOrd for Rev<T> {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(match self.0.cmp(&other.0) {
            Less => Greater,
            Equal => Equal,
            Greater => Less,
        })
    }
}

impl<T: Ord> Ord for Rev<T> {
    fn cmp(&self, other: &Self) -> Ordering {
        self.partial_cmp(other).unwrap()
    }
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let n: usize = parse!(it);
    let p: Vec<i64> = parse!(it, n);
    let mut p: Vec<_> = p.iter().enumerate().map(|(i, &x)| (x, i as i64)).collect();
    p.sort();
    p.reverse();
    let mut ret = 0;
    let mut x = Empty::<Rev<i64>>;
    let mut y = Empty::<i64>;
    for &(pi, i) in p.iter() {
        let kx = Rev(i - 1);
        let ky = i + 1;
        {
            let mut l = x.range(Some(&kx), None);
            let mut r = y.range(Some(&ky), None);
            let l0 = l.next().unwrap_or(&Rev(-1)).0;
            let l1 = l.next().unwrap_or(&Rev(-1)).0;
            let r0 = *r.next().unwrap_or(&(n as i64));
            let r1 = *r.next().unwrap_or(&(n as i64));
            ret += (l0 - l1) * (r0 - i) * pi;
            ret += (i - l0) * (r1 - r0) * pi;
        };
        x.insert(Rev(i));
        y.insert(i);
    }
    println!("{}", ret);
}

