            else if (a<=l && r<=b){
                return self.datA[k] * ((r-l) as i64) + self.datB[k];
            }
            else{
                let mut res = (cmp::min(b, r) - cmp::max(a, l)) as i64 * self.datA[k];
                res += self.query(a, b, k*2+1, l, (l+r)/2);
