pub mod ds {
    use std::ops::{AddAssign, Sub};
    #[derive(Debug)]
    pub struct BIT<T> {
        data: Vec<T>,
    }
    impl<T> BIT<T>
    where
        T: Copy + AddAssign + Sub<Output = T> + Default,
    {
        pub fn new(size: usize) -> Self {
            let buf_size = size.next_power_of_two();
            BIT {
                data: vec![T::default(); buf_size + 1],
            }
        }
        #[doc = " [l, r) l,r: 1-indexed"]
        pub fn range_sum(&self, l: usize, r: usize) -> T {
            self.sum(r - 1) - self.sum(l - 1)
        }
        #[doc = " i: 1-indexed but returns 0 if i=0 is given."]
        pub fn sum(&self, i: usize) -> T {
            let mut i = i as i64;
            let mut ret = T::default();
            while i > 0 {
                ret += self.data[i as usize];
                i -= i & -i;
            }
            ret
        }
        #[doc = " i: 1-indexed"]
        pub fn add(&mut self, i: usize, value: T) {
            assert!(i > 0);
            let n = self.data.len() as i64;
            let mut i = i as i64;
            while i <= n - 1 {
                self.data[i as usize] += value;
                i += i & -i;
            }
        }
    }
}

use ds::BIT;

fn find_right(bit: &BIT<usize>, n:usize, cur:usize, num: usize) -> usize {
    let mut ok = n+1;
    let mut ng = cur;
    while ok != ng {
        let mid = (ok + ng) / 2;
        if bit.range_sum(cur, mid+1) >= num {
            ok = mid;
        } else {
            ng = mid + 1;
        }
    }
    ok
}

fn find_left(bit: &BIT<usize>, n:usize, cur:usize, num: usize) -> usize {
    let cur_num = bit.range_sum(1, cur+1);
    // debug!(num, cur_num);
    if cur_num == 0 {
        return 0;
    }
    if num > cur_num {
        return 0;
    }

    let mut ok = cur;
    let mut ng = 1;
    while ok != ng {
        let mid = (ok + ng) / 2;
        let sum = bit.range_sum(1, mid+1);
        if bit.range_sum(1, mid+1) >= (cur_num-num) {
            ok = mid;
        } else {
            ng = mid + 1;
        }
    }
    ok
}

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      ps: [usize; n],
    }

    let mut pos = vec![0; n+1];
    for i in 0..n {
        let p = ps[i];
        pos[p] = i;
    }

    let mut bit = BIT::new(n);
    bit.add(pos[n]+1, 1);

    let mut ans = 0 as usize;
    for i in (1..n).rev() {
        let bit_pos = pos[i] + 1;
        let mut l1 = find_left(&bit, n, bit_pos, 1);
        let l2 = find_left(&bit, n, bit_pos, 0);
        let r1 = find_right(&bit, n, bit_pos, 1);

        if l1 == 1 && l2 == 1 {
            l1 = 0;
        }
        let r2 = find_right(&bit, n, bit_pos, 2);

        let v1 = (l2-l1) * (r1 - bit_pos) * i;
        let v2 = (r2-r1) * (bit_pos-l2) * i;

        ans += v1 + v2;
        // debug!(i, l1, l2, bit_pos, r1, r2, v1, v2, ans);

        bit.add(bit_pos, 1);
    }
    puts!("{}\n", ans);
}

pub trait IterScan: Sized {
    type Output;
    fn scan<'a, I: Iterator<Item = &'a str>>(iter: &mut I) -> Option<Self::Output>;
}
pub trait MarkedIterScan: Sized {
    type Output;
    fn mscan<'a, I: Iterator<Item = &'a str>>(self, iter: &mut I) -> Option<Self::Output>;
}
#[derive(Debug)]
pub struct Scanner<'a> {
    iter: std::str::SplitAsciiWhitespace<'a>,
}
impl<'a> Scanner<'a> {
    #[inline]
    pub fn new(s: &'a str) -> Self {
        let iter = s.split_ascii_whitespace();
        Self { iter }
    }
    #[inline]
    pub fn scan<T: IterScan>(&mut self) -> <T as IterScan>::Output {
        T::scan(&mut self.iter).unwrap()
    }
    #[inline]
    pub fn mscan<T: MarkedIterScan>(&mut self, marker: T) -> <T as MarkedIterScan>::Output {
        marker.mscan(&mut self.iter).unwrap()
    }
    #[inline]
    pub fn scan_vec<T: IterScan>(&mut self, size: usize) -> Vec<<T as IterScan>::Output> {
        (0..size)
            .map(|_| T::scan(&mut self.iter).unwrap())
            .collect()
    }
    #[inline]
    pub fn scan_chars(&mut self) -> Vec<char> {
        self.iter.next().unwrap().chars().collect::<Vec<char>>()
    }
}
