fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      ps: [usize; n],
    }

    let mut pos = vec![0; n+1];
    for i in 0..n {
        pos[ps[i]] = i;
    }

    let mut seg_l = SegmentTree::new(n+2, -1i64, |a, b| max(a, b));
    seg_l.set(0, 0i64);
    let mut seg_r = SegmentTree::new(n+2, n+2, |a, b| min(a, b));
    seg_r.set(n+1, n+1);

    let mut ans = 0 as usize;
    for i in (1..n+1).rev() {
        let p = pos[i] + 1;
        seg_l.set(p, p as i64);
        seg_r.set(p, p);

        let l1 = seg_l.query(0, p) as usize;
        let l2 = if l1 == 0 { 0 } else { seg_l.query(0, l1) as usize };


        let r1 = seg_r.query(p+1, n+2) as usize;
        let r2 = if r1 == n+1 { n+1 } else { seg_r.query(r1+1, n+2) as usize };
        ans += (l1-l2) * (r1-p) * i;
        ans += (p-l1) * (r2-r1) * i;

        // debug!(l1, l2, p, r1, r2, ans);
    }
    puts!("{}\n", ans);
}

