fn solve() {
    input! {
        n: usize,
        p: [usize;n]
    }

    let mut num_index = vec![0; n + 1];
    for i in 0..n {
        num_index[p[i]] = i;
    }

    let mut ans = 0;

    let mut big_num_induces = BTreeSet::new();
    // 一番大きい数を入れておく
    big_num_induces.insert(num_index[n]);

    for i in (1..n).rev() {
        // 自分のインデックス
        let index = num_index[i];

        let mut before_induces = big_num_induces.range(..index).rev();
        let mut after_induces = big_num_induces.range(index..);

        // 自分よりすぐ前にある、自分より大きいやつ
        let greater_front = match before_induces.next() {
            Some(&b) => b as isize,
            None => -1,
        };

        // greater_frontよりすぐ前にある、自分より大きいやつ
        let greater_front_front = match before_induces.next() {
            Some(&b) => b as isize,
            None => -1,
        };

        // 自分よりすぐ後ろにある、自分より大きいやつ
        let greater_back = match after_induces.next() {
            Some(&a) => a as isize,
            None => n as isize,
        };

        // greater_backよりすぐ後ろにある、自分より大きいやつ
        let greater_back_back = match after_induces.next() {
            Some(&a) => a as isize,
            None => n as isize,
        };

        /*
        println!(
            "{} {} {} {} {}",
            greater_front_front, greater_front, index, greater_back, greater_back_back
        );
        */

        // 自分とgreater_frontを含み、greater_backを含まないものの総数*自分
        // ff(...f...i...)b...bb の数。 ff...fでは0個からffの直前まで採用でき、i...bでは0個からbの直前まで採用できる
        ans += (greater_front - greater_front_front) * (greater_back - index as isize) * i as isize;

        // 自分とgreater_backを含み、greater_frontを含まないものの総数*自分
        ans += (greater_back_back - greater_back) * (index as isize - greater_front) * i as isize;

        // 最後にこのループで考慮したインデックスを考慮済みインデックスにいれる
        big_num_induces.insert(index);
    }

    println!("{}", ans);
}

