        writeln!(&mut std::io::stderr(), concat!("[DEBUG] ", $(stringify!($a), "={:?} "),*), $($a),*);
    }
}

#[allow(unused_imports)]
use std::cmp::{min, max};
#[allow(unused_imports)]
use std::io::{stdout, stdin, BufWriter, Write};

fn solve(n:usize, k:usize, s: &Vec<char>) -> usize {
    let mut ans1 = 0;
    let mut seq = 0;
    let mut ranges = vec![];
    for i in 0..n {
        if s[i] == 'L' {
            if seq > 0 {
                ranges.push(seq);
            }
            seq = 0;
            if i > 0 {
                if s[i-1] == 'L' {
                    ans1 += 1;
                }
            }
        } else {
            seq += 1;
        }
    }
    if seq > 0 {
        ranges.push(seq-1);
    }
    ranges.sort();
    ranges.reverse();

    for i in 0..min(k, ranges.len()) {
        ans1 += ranges[i]+1;
    }
    min(ans1, n-1)
}

fn solve2(n:usize, k:usize, s: &Vec<char>) -> usize {
    let mut ans1 = 0;
    let mut seq = 0;
    let mut ranges = vec![];
    for i in (0..n).rev() {
        if s[i] == 'R' {
            if seq > 0 {
                ranges.push(seq);
            }
            seq = 0;
            if i < n-1 {
                if s[i+1] == 'R' {
                    ans1 += 1;
                }
            }
        } else {
            seq += 1;
        }
    }
    if seq > 0 {
        ranges.push(seq-1);
    }
    ranges.sort();
    ranges.reverse();
    for i in 0..min(k, ranges.len()) {
        ans1 += ranges[i]+1;
    }
    min(ans1, n-1)
}

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      k: usize,
      mut s: chars,
    }

    let ans1 = solve(n, k, &s);
    let ans2 = solve2(n, k, &s);
    let ans = max(ans1, ans2);
    puts!("{}\n", ans);
}

