use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        xs: [usize; n],
    }
    let mut set = MySet::new();
    let mut ys = vec![0; n + 1];
    for (i, &x) in xs.iter().enumerate() {
        ys[x] = i + 1;
    }
    // eprintln!("ys = {:?}", ys);
    for i in 0..n + 1 + 1 {
        set.insert(i);
    }
    let mut res = 0i64;
    for &i in &ys[1..] {
        // eprintln!("i = {}, xs[i-1] = {}", i, xs[i - 1]);

        let l1 = set.prev(i).unwrap();
        // eprintln!("l1 = {}", l1);
        if l1 != 0 {
            let l2 = set.prev(l1).unwrap();
            // eprintln!("l2 = {}", l2);
            let r = set.next(i).unwrap();
            let t = (r - i) as i64 * (l1 - l2) as i64;
            res += xs[i - 1] as i64 * t;
        }

        let r1 = set.next(i).unwrap();
        if r1 != n + 1 {
            let r2 = set.next(r1).unwrap();
            let l = set.prev(i).unwrap();
            let t = (i - l) as i64 * (r2 - r1) as i64;
            res += xs[i - 1] as i64 * t;
        }
        set.delete(i);
    }
    writeln!(buf, "{}", res);
    buf
}

fn read_line() -> String {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim_right().to_owned()
}

fn to_vec(s: String, offset: u64) -> Vec<u64> {
    s.split_whitespace()
        .map(|s| s.parse::<u64>().unwrap() - offset)
        .collect()
}

trait Container {
    fn last2(&self) -> u64;
}

impl Container for Vec<u64> {
    fn last2(&self) -> u64 {
        if self.len() < 2 {
            return 0;
        }
        self[self.len() - 2]
    }
}

fn main() {
    let n: usize = read_line().parse().unwrap();
    let ps = to_vec(read_line(), 1);

    let mut v: Vec<Vec<Vec<u64>>> = vec![vec![Vec::new(); n]; n];

    let mut map = vec![0; n];
    for (i, &p) in ps.iter().enumerate() {
        map[p as usize] = i;
    }

    for p_i in 0..n {
        let p = map[p_i];
        for i in p..n {
            for j in 0..(p + 1) {
                v[i][j].push(p_i as u64);
            }
        }
    }

    let mut total = (n * (n - 1) / 2) as u64;
    for vv in v {
        for vvv in vv {
            total += vvv.last2();
        }
    }

    println!("{}", total);
}

