use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        xs: [usize; n],
    }
    let mut set = MySet::new();
    let mut ys = vec![0; n + 1];
    for (i, &x) in xs.iter().enumerate() {
        ys[x] = i + 1;
    }
    // // eprintln!("ys = {:?}", ys);
    for i in 0..n + 1 + 1 {
        set.insert(i);
    }
    let mut res = 0i64;
    for &i in &ys[1..] {
        // // eprintln!("i = {}, xs[i-1] = {}", i, xs[i - 1]);

        let l1 = set.prev(i).unwrap();
        // // eprintln!("l1 = {}", l1);
        if l1 != 0 {
            let l2 = set.prev(l1).unwrap();
            // // eprintln!("l2 = {}", l2);
            let r = set.next(i).unwrap();
            let t = (r - i) as i64 * (l1 - l2) as i64;
            res += xs[i - 1] as i64 * t;
        }

        let r1 = set.next(i).unwrap();
        if r1 != n + 1 {
            let r2 = set.next(r1).unwrap();
            let l = set.prev(i).unwrap();
            let t = (i - l) as i64 * (r2 - r1) as i64;
            res += xs[i - 1] as i64 * t;
        }
        set.delete(i);
    }
    writeln!(buf, "{}", res);
    buf
}

