    // l_i[j] = max{k| k<j, p[k]>p_i}
    // r_i[j] = min{k| k>j, p[k]>p_i}
    let mut l_i: Vec<_> = vec![None];
    l_i.extend((0..n - 1).map(Some));
    let mut r_i: Vec<_> = (1..n).map(Some).collect();
    r_i.push(None);

    let mut ans = 0;
    while p_i < n {
        let i = idx[p_i];

        let mut l  = -1;
        let mut l2 = -1;
        if let Some(_l) = l_i[i] {
            if let Some(_l2) = l_i[_l] {
                l2 = _l2 as isize;
            }
            l = _l as isize;
        }

        let mut r  = n as isize;
        let mut r2 = n as isize;
        if let Some(_r) = r_i[i] {
            if let Some(_r2) = r_i[_r] {
                r2 = _r2 as isize;
            }
            r = _r as isize;
        }

        let i = i as isize;
        let c_i = (l-l2) * (r-i) + (r2-r) * (i-l);
        ans += (p_i+1) * c_i as usize;

        p_i += 1;

        // l_i <- l_(idx[p_i+1])
        // r_i <- r_(idx[p_i+1])
        if l >= 0 {
            r_i[l as usize] = if r < n as isize {
                Some(r as usize)
            } else {
                None
            }
        }
        if r < n as isize {
            l_i[r as usize] = if l >= 0 {
                Some(l as usize)
            } else {
                None
            }
        }
    }

    format!("{}\n", ans)
}
