pub struct BIT {
    xs: Vec<i64>,
    n: usize,
}

// 1-indexed !!!
impl BIT {
    pub fn new(n: usize) -> BIT {
        BIT {
            xs: vec![0; n + 1],
            n: n,
        }
    }
    pub fn sum(&self, i: usize) -> i64 {
        let mut res = 0;
        let mut i = i;
        while i > 0 {
            res += self.xs[i];
            i -= i & !(i - 1);
        }
        res
    }
    pub fn add(&mut self, i: usize, x: i64) {
        let mut i = i;
        while i <= self.n {
            self.xs[i] += x;
            i += i & !(i - 1);
        }
    }
    // return <= i
    pub fn max_non_zero_index(&self, i: usize) -> usize {
        let mut d = 1 << 28;
        let mut i = i;
        while d != 0 {
            if i < d {
                d /= 2;
                continue;
            }
            if self.sum(i - d) == self.sum(i) {
                i = i - d;
            }
            d /= 2;
        }
        i
    }
    pub fn min_non_zero_index(&self, i: usize) -> usize {
        let mut d = 1 << 28;
        let mut i = i;
        while d != 0 {
            if i + d > self.n {
                d /= 2;
                continue;
            }
            if self.sum(i + d) == self.sum(i) {
                i = i + d;
            }
            d /= 2;
        }
        i + 1
    }
}

