enum SortedType {
    Sorted,
    SortedReverse,
    Unsorted,
}

fn find_sorted_maxes(
    source: &Vec<u64>,
    a: usize,
    b: usize,
    to_index: &Vec<usize>,
) -> (u64, u64, SortedType) {
    let mut v: Vec<u64> = source[a..b].iter().cloned().collect();
    v.sort();

    let max = *v.last().unwrap();
    let max2 = v[v.len() - 2];

    let mut sorted = SortedType::Unsorted;

    (max, max2, sorted)
}

fn find_max2(a: u64, b: u64, c: u64) -> u64 {
    let mut v = vec![a, b, c];
    v.sort();
    v[v.len() - 2]
}

fn evaluate(v: &Vec<u64>, to_index: &Vec<usize>, r: &ops::Range<usize>) -> u64 {
    let n = r.len();
    if n < 2 {
        return 0;
    } else if n == 2 {
        return cmp::min(v[r.start], v[r.start + 1]) as u64;
    } else if n == 3 {
        let rs = r.start as u64;
        let (a, b, c) = (rs, rs + 1, rs + 2);
        let max2 = find_max2(a, b, c);
        return cmp::min(a, b) + cmp::min(b, c) + max2;
    }

    let (max, max2, maxes) = find_sorted_maxes(v, r.start, r.end, to_index);
    let (a, b, c) = {
        let a = to_index[max as usize];
        let b = to_index[max2 as usize];
        if a < b {
            split(r, a, b)
        } else {
            split(r, b, a)
        }
    };

    /*
    println!("{:?} = {:?} + {:?} - {:?}", r, a, b, c);
    print!("[{:?}, ", r.clone().map(|i| v[i]).collect::<Vec<_>>());
    print!("[{:?}, ", a.clone().map(|i| v[i]).collect::<Vec<_>>());
    println!("{:?}]", b.clone().map(|i| v[i]).collect::<Vec<_>>());
    println!("{:?}]", c.clone().map(|i| v[i]).collect::<Vec<_>>());
    println!("max2: {} * {} = {}", max2, max2_area / max2, max2_area);
    */

    let max2_area = (r.end as u64 - a.end as u64) * (b.start as u64 - r.start as u64) * max2;
    let a_e = evaluate(v, to_index, &a);
    let b_e = evaluate(v, to_index, &b);
    let dedup = evaluate(v, to_index, &c);

    let val = a_e + b_e + max2_area - dedup;
    //println!("{:?}: {}", r, val);
    val
}

fn split(
    v: &ops::Range<usize>,
    a: usize,
    b: usize,
) -> (ops::Range<usize>, ops::Range<usize>, ops::Range<usize>) {
    if v.len() == 3 {
        (v.start..(v.start + 2), (v.end - 2)..v.end, 0..0)
    } else {
        (v.start..b, (a + 1)..v.end, (a + 1)..b)
    }
}

