use std::i32;
use std::ops::{Range, Index};
use std::cmp::{ min, max };

struct RMQ {
    size: usize, len: usize,
    heap_max: Vec<usize>,
    heap_min: Vec<usize>,
    lefts: Vec<usize>, rights: Vec<usize>,
    reverse_index: Vec<usize>,
}

impl RMQ {

    const INF: usize = 1000000;

    fn new(v: &Vec<usize>) -> RMQ {
        let n = v.len();
        let size = RMQ::alignment(n);
        let lefts = (0..size).map(|i| RMQ::of_left(i, size/2)).collect();
        let rights = (0..size).map(|i| RMQ::of_right(i, size/2)).collect();
        let mut heap_max = vec![0; size];
        for i in 0..n { heap_max[i + size/2] = v[i]; }
        for i in (0..size/2).rev() { heap_max[i] = max(heap_max[i*2+1], heap_max[i*2+2]); }
        let mut heap_min = vec![0; size];
        for i in 0..n { heap_min[i + size/2] = v[i]; }
        for i in (0..size/2).rev() { heap_min[i] = min(heap_min[i*2+1], heap_min[i*2+2]); }

        let mut reverse_index = vec![0; n];
        for i in 0..n {
            reverse_index[v[i]] = i;
        }

        RMQ {
            size: size,
            len: n,
            heap_max: heap_max,
            heap_min: heap_min,
            lefts: lefts,
            rights: rights,
            reverse_index: reverse_index,
        }
    }

    fn len(&self) -> usize {
        self.len
    }

    fn alignment(n: usize) -> usize {
        let mut m = 1;
        while n > m { m <<= 1; }
        m * 2 - 1
    }

    fn of_left(idx: usize, base: usize) -> usize {
        let mut i = idx; while i < base { i = i * 2 + 1; }
        i - base
    }

    fn of_right(idx: usize, base: usize) -> usize {
        let mut i = idx; while i < base { i = i * 2 + 2; }
        i - base + 1
    }

    fn max(&self, range: Range<usize>) -> usize {
        if range.end == 0 || range.start + 1 > range.end {
            return 0
        }
        if range.start + 1 == range.end {
            return self.heap_max[self.size / 2 + range.start]
        }
        let left = range.start;
        let right = range.end;
        let mut i = self.size / 2 + left;
        while i > 0 {
            let p = (i - 1) / 2;
            if self.lefts[p] == range.start && self.rights[p] <= range.end {
                i = p;
            } else {
                break
            }
        }
        max(self.heap_max[i], self.max(self.rights[i]..right))
    }

    fn max_2nd(&self, range: Range<usize>) -> usize {
        let fu = range.start;
        let ck = range.end;
        let m = self.max(fu..ck);
        let mi = self.reverse_index[m];
        max!(self.max(fu..mi), self.max(mi + 1..ck))
    }

    fn min(&self, range: Range<usize>) -> usize {
        if range.end == 0 || range.start + 1 > range.end {
            return RMQ::INF;
        }
        if range.start + 1 == range.end {
            return self.heap_min[self.size / 2 + range.start]
        }
        let left = range.start;
        let right = range.end;
        let mut i = self.size / 2 + left;
        while i > 0 {
            let p = (i - 1) / 2;
            if self.lefts[p] == range.start && self.rights[p] <= range.end {
                i = p;
            } else {
                break
            }
        }
        min(self.heap_min[i], self.min(self.rights[i]..right))
    }

    // [idx] <- x
    fn update(&mut self, idx: usize, x: usize) {
        let mut i = idx + self.size/2;
        self.heap_max[i] = x;
        self.heap_min[i] = x;
        loop {
            i = (i - 1) / 2;
            if i == 0 { break }
            self.heap_max[i] = max(self.heap_max[i*2+1], self.heap_max[i*2+2]);
            self.heap_min[i] = min(self.heap_max[i*2+1], self.heap_max[i*2+2]);
        }
    }

    // [idx] <- [idx] + x
    fn add(&mut self, idx: usize, x: usize) {
        self.update(idx, self[idx] + x);
    }

    fn to_vec(&self) -> Vec<usize> {
        (0..self.len()).map(|i| self[i]).collect()
    }
}

impl Index<usize> for RMQ {
    type Output = usize;
    fn index(&self, i: usize) -> &usize {
        &self.heap_max[i + self.size / 2]
    }
}

fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.cin();
    let p: Vec<usize> = (0..n).map(|_| sc.cin::<usize>() - 1).collect();

    let rmq = RMQ::new(&p);
    let mut ans = 0;

    for i in 0..n {
        let m = p[i];
        let mut left_1st = None;
        let mut left_2nd = None;
        let mut right_1st = None;
        let mut right_2nd = None;

        if i > 0 {
            let mut left = 0;
            let mut right = i;
            for _ in 0..100 {
                let mid = (left + right) / 2;
                if rmq.max(mid..i) < m {
                    right = mid;
                } else {
                    left = mid;
                }
            }
            if p[left] > m {
                left_1st = Some(left);
            }
        }

        if left_1st.is_some() && left_1st.unwrap() > 0 {
            let k = left_1st.unwrap();
            let mut left = 0;
            let mut right = k;
            for _ in 0..100 {
                let mid = (left + right) / 2;
                if rmq.max(mid..k) < m {
                    right = mid;
                } else {
                    left = mid;
                }
            }
            if p[left] > m {
                left_2nd = Some(left);
            }
        }

        if i < n - 1 {
            let mut left = i + 1;
            let mut right = n;
            for _ in 0..100 {
                let mid = (left + right) / 2;
                if rmq.max(mid..i) < m {
                    right = mid;
                } else {
                    left = mid;
                }
            }
            if p[left] > m {
                right_1st = Some(left);
            }
        }

        if right_1st.is_some() && right_1st.unwrap() < n - 1 {
            let mut left = right_1st.unwrap() + 1;
            let mut right = n;
            for _ in 0..100 {
                let mid = (left + right) / 2;
                if rmq.max(mid..i) < m {
                    right = mid;
                } else {
                    left = mid;
                }
            }
            if p[left] > m {
                right_2nd = Some(left);
            }
        }

        let cases = match (left_2nd, left_1st, right_1st, right_2nd) {
            (Some(a), Some(b), Some(c), Some(d)) => {
                (b - a) * (c - i) + (d - c) * (i - b)
            }
            (None, Some(b), Some(c), Some(d)) => {
                (b + 1) * (c - i) + (d - c) * (i - b)
            }
            (Some(a), Some(b), Some(c), None) => {
                (b - a) * (c - i) + (n - c) * (i - b)
            }
            (None, Some(b), Some(c), None) => {
                (b + 1) * (c - i) + (n - c) * (i - b)
            }
            (Some(a), Some(b), None, None) => {
                (b - a) * (n - i)
            }
            (None, None, Some(c), Some(d)) => {
                (d - c) * (i + 1)
            }
            (None, Some(b), None, None) => {
                (b +1) * (n - i)
            }
            (None, None, Some(c), None) => {
                (n - c) * (i + 1)
            }
            _ => 0
        };
        ans += (p[i] + 1) * cases;

        // trace!(i);
        // trace!(left_1st, left_2nd);
        // trace!(right_1st, right_2nd);
        // trace!(cases);

    }

    put!(ans);
}

use std::io::{self, Write};
use std::str::FromStr;
use std::collections::VecDeque;

struct Scanner { stdin: io::Stdin, buffer: VecDeque<String>, }
impl Scanner {
    fn new() -> Self { Scanner { stdin: io::stdin(), buffer: VecDeque::new() } }
    fn cin<T: FromStr>(&mut self) -> T {
        while self.buffer.len() == 0 {
            let mut line = String::new();
            let _ = self.stdin.read_line(&mut line);
            for w in line.split_whitespace() {
                self.buffer.push_back(String::from(w));
            }
        }
        self.buffer.pop_front().unwrap().parse::<T>().ok().unwrap()
    }
}

fn read_stdin() -> String {
    use std::io::Read;
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input).unwrap();
    input
}

fn scan<'a, I: Iterator<Item = &'a str>, T: std::str::FromStr>(tokens: &mut I) -> T {
    tokens.next().unwrap().parse().ok().unwrap()
}

fn main() {
    use std::collections::BTreeSet;
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let n: usize = scan(tokens);
    let q: Vec<usize> = {
        let mut q = vec![0; n + 1];
        for i in 1..n + 1 {
            let p: usize = scan(tokens);
            q[p] = i;
        }
        q
    };
    let mut ans = 0;
    let mut t = BTreeSet::new();
    for p in (1..n + 1).rev() {
        let i = q[p];
        let h = *t.range(..i).rev().next().unwrap_or(&0);
        let g = *t.range(..h).rev().next().unwrap_or(&0);
        let j = *t.range(i + 1..).next().unwrap_or(&(n + 1));
        let k = *t.range(j + 1..).next().unwrap_or(&(n + 1));
        ans += p * (i - h) * (k - j);
        ans += p * (h - g) * (j - i);
        t.insert(q[p]);
    }
    println!("{}", ans);
}

