fn solve(n:usize, k:usize, s: &Vec<char>) -> usize {
    let mut ans1 = 0;
    let mut seq = 0;
    let mut ranges = vec![];
    for i in 0..n {
        if s[i] == 'L' {
            if seq > 0 {
                ranges.push(seq);
            }
            seq = 0;
            if i > 0 {
                if s[i-1] == 'L' {
                    ans1 += 1;
                }
            }
        } else {
            seq += 1;
        }
    }
    if seq > 0 {
        ranges.push(seq-1);
    }
    ranges.sort();
    ranges.reverse();

    for i in 0..min(k, ranges.len()) {
        ans1 += ranges[i]+1;
    }
    min(ans1, n-1)
}

fn solve2(n:usize, k:usize, s: &Vec<char>) -> usize {
