fn solve(n: usize, p: Vec<u32>) -> usize {
  // indexes[num] is index of num in p
  let mut indexes = vec![0; n + 1];
  // prevs[i] is the previous non-calculated index of i
  let mut prevs: Vec<_> = (0..n + 2).map(|n| if n == 0 { 0 } else {n - 1}).collect();
  // nexts[i] is the next non-calculated index of i
  let mut nexts: Vec<_> = (0..n + 2).map(|n| n + 1).collect();

  prevs[n + 1] = n;
  nexts[0] = 1;

  for i in 0..n {
    indexes[p[i] as usize] = i + 1;
  }

  let mut ans = 0;
  for num in 1..n {
    let index = indexes[num];
    // prev is the previous index
    let prev = prevs[index];
    // next is the next index
    let next = nexts[index];

    // count with some conditions
    if 0 < prev { // number bigger than num is in nexts
      ans += num * (prev - prevs[prev]) * (next - index);
    }
    // number bigger than num is in prevs
    if next != n + 1 {
      ans += num * (index - prev) * (nexts[next] - next);
    }
    println!("num: {} index: {} prev: {} next: {} ans: {}", num, index, prev, next, ans);

    // concat prev and next to mark as calculated
    nexts[prev] = next;
    prevs[next] = prev;
  }
  ans
}

