}
impl Bit {
#[allow(dead_code)]
    fn new(n: usize) -> Self {
        Bit { tree: vec![0; n] }
    }
#[allow(dead_code)]
    fn from(vec: Vec<isize>) -> Self {
        let mut bit = Bit::new(vec.len() + 1);
        for i in 1..(vec.len() + 1) {
            bit.add(i, vec[i - 1]);
        }
        bit
    }
#[allow(dead_code)]
    fn add(&mut self, a: usize, w: isize) {
        let mut x = a as isize;
        while x < self.tree.len() as isize {
            self.tree[x as usize] += w;
            x += x & (-x);
        }
    }
#[allow(dead_code)]
    fn sum(&self, n: usize) -> isize {
        let mut x = n as isize;
        let mut ret = 0;
        while x > 0 {
            ret += self.tree[x as usize];
            x -= x & (-x);
        }
        ret
    }
#[allow(dead_code)]
    fn sum_with(&self, l: usize, r: usize) -> isize {
        self.sum(r) - self.sum(l - 1)
    }
}

