trait BinarySearch<T> {
    fn lower_bound(&self, &T) -> usize;
    fn upper_bound(&self, &T) -> usize;
}

trait ExactSize {
    fn len(&self) -> usize;
}

impl ExactSize for Bit {
    fn len(&self) -> usize {
        self.tree.len()
    }
}

impl<T: Ord, U> BinarySearch<T> for U 
    where U: Indexable<Output=T> + ExactSize {
#[allow(dead_code)]
    fn lower_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();
        while low != high {
            let mid = (low + high) / 2;
            match self.index(mid).cmp(x) {
                Ordering::Less => {
                    low = mid + 1;
                }
                Ordering::Equal | Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }
#[allow(dead_code)]
    fn upper_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();
        while low != high {
            let mid = (low + high) / 2;
            match self.index(mid).cmp(x) {
                Ordering::Less | Ordering::Equal => {
                    low = mid + 1;
                }
                Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }
}

fn solve() {
    let n = get!(usize);
    let p = get!([usize]);

    let mut pinv = vec![0; n+1];
    let mut bit = Bit::new(n+3);
    for i in 0..n {
        pinv[p[i]] = i+2;
    }
    let mut res = 0;
    bit.add(1,1);
    bit.add(1,1);
    bit.add(n+2,1);
    bit.add(n+2,1);
    for i in (1..n+1).rev() {
        let pos = pinv[i];
        let posnum = bit.sum(pos);
        let ll = bit.lower_bound(&(posnum-1));
        let l = bit.lower_bound(&(posnum));
        let r = bit.lower_bound(&(posnum+1));
        let rr = bit.lower_bound(&(posnum+2));
        res += ((rr-r)*(pos-l)+(r-pos)*(l-ll))*i;
        bit.add(pos,1);
    }
    println!("{}",res);
}

