    let idx = {
        let mut idx: Vec<usize> = vec![0; n];
        for i in 0..n {
            let p: usize = sc.read();
            idx[p - 1] = i;
        }
        idx
    };

    let mut p_i = 0;

    // l_i[j] = max{k| k<j, p[k]>p_i}
    // r_i[j] = min{k| k>j, p[k]>p_i}
    let mut l_i: Vec<_> = vec![None];
    l_i.extend((0..n - 1).map(Some));
    let mut r_i: Vec<_> = (1..n).map(Some).collect();
    r_i.push(None);

    let mut ans = 0;
    while p_i < n {
        let i = idx[p_i];

        let (l, l2) = {
            if let Some(l) = l_i[i] {
                if let Some(l2) = l_i[l] {
                    (l as isize, l2 as isize)
                } else {
                    (l as isize, -1)
                }
            } else {
                (-1, -1)
            }
        };

        let (r, r2) = {
            if let Some(r) = r_i[i] {
                if let Some(r2) = r_i[r] {
                    (r as isize, r2 as isize)
                } else {
                    (r as isize, n as isize)
                }
            } else {
                (n as isize, n as isize)
            }
        };

        let i = i as isize;
        let c_i = (l - l2) * (r - i) + (r2 - r) * (i - l);
        ans += (p_i + 1) * c_i as usize;

        p_i += 1;

        // l_i <- l_(idx[p_i+1])
        // r_i <- r_(idx[p_i+1])
        if l >= 0 {
            r_i[l as usize] = r_i[i as usize]
        }
        if r < n as isize {
            l_i[r as usize] = l_i[i as usize]
        }
    }

    format!("{}\n", ans)
}
