#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn main() {
    let n = read::<usize>();
    let mut ps = vec![(0, 0); n];
    for i in 0..n {
        ps[i].0 = read::<usize>();
        ps[i].1 = i;
    }
    ps.sort();
    ps.reverse();
    let mut items = BTreeSet::<i64>::new();
    let mut ans = 0;
    for i in 0..n {
        let v = ps[i].0 as i64;
        let pos = ps[i].1 as i64;
        let mut lefts = vec![];
        let mut rights = vec![];
        for index in items.range((Included(&0), Excluded(&(pos as i64)))).rev() {
            lefts.push(*index);
            if lefts.len() == 2 {
                break;
            }
        }
        for index in items.range((Excluded(&(pos as i64)), Included(&(n as i64)))) {
            rights.push(*index);
            if rights.len() == 2 {
                break;
            }
        }
        while lefts.len() <= 1 {
            lefts.push(-1);
        }
        while rights.len() <= 1 {
            rights.push(n as i64);
        }
        ans += v * (pos - lefts[0]) * (rights[1] - rights[0]);
        ans += v * (lefts[0] - lefts[1]) * (rights[0] - pos);
        items.insert(pos as i64);
    }
    println!("{}", ans);
}

