trait Center {
    fn center(&self) -> usize;
    fn split(&self) -> (ops::Range<usize>, ops::Range<usize>);
}

impl Center for ops::Range<usize> {
    fn center(&self) -> usize {
        self.start + self.len() / 2
    }

    fn split(&self) -> (ops::Range<usize>, ops::Range<usize>) {
        let c = self.center();
        (self.start..c, c..self.end)
    }
}

trait BinarySearch {
    fn binary_search_position(&mut self, x: u64) -> usize;
    fn last2(&self) -> u64;
}

impl BinarySearch for Vec<u64> {
    fn binary_search_position(&mut self, x: u64) -> usize {
        let mut r = 0..self.len();
        while r.len() != 1 {
            let subs = r.split();
            r = if x < self[subs.0.end] as u64 {
                subs.0
            } else {
                subs.1
            };
        }
        if x < self[r.start] { r.start } else { r.end }
    }

    fn last2(&self) -> u64 {
        self[self.len() - 2]
    }
}

