use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        xs: [usize; n],
    }
    let mut set = MySet::new();
    let mut ys = vec![0; n + 1];
    for (i, &x) in xs.iter().enumerate() {
        ys[x] = i + 1;
    }
    // // eprintln!("ys = {:?}", ys);
    for i in 0..n + 1 + 1 {
        set.insert(i);
    }
    let mut res = 0i64;
    for &i in &ys[1..] {
        // // eprintln!("i = {}, xs[i-1] = {}", i, xs[i - 1]);

        let l1 = set.prev(i).unwrap();
        // // eprintln!("l1 = {}", l1);
        if l1 != 0 {
            let l2 = set.prev(l1).unwrap();
            // // eprintln!("l2 = {}", l2);
            let r = set.next(i).unwrap();
            let t = (r - i) as i64 * (l1 - l2) as i64;
            res += xs[i - 1] as i64 * t;
        }

        let r1 = set.next(i).unwrap();
        if r1 != n + 1 {
            let r2 = set.next(r1).unwrap();
            let l = set.prev(i).unwrap();
            let t = (i - l) as i64 * (r2 - r1) as i64;
            res += xs[i - 1] as i64 * t;
        }
        set.delete(i);
    }
    writeln!(buf, "{}", res);
    buf
}

fn read_line() -> String {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim_right().to_owned()
}

fn to_vec(s: String, offset: u64) -> Vec<u64> {
    s.split_whitespace()
        .map(|s| s.parse::<u64>().unwrap() - offset)
        .collect()
}

fn evaluate(v: &[u64]) -> u64 {
    let n = v.len();
    let mut total = 0;
    let mut bs: Vec<Vec<[u64; 2]>> = Vec::new();
    let init = {
        let mut b = Vec::new();
        b.reserve(n);
        for w in v.windows(2) {
            let (max2, max) = if w[0] < w[1] {
                (w[0], w[1])
            } else {
                (w[1], w[0])
            };
            b.push([max2, max]);

            total += max2;
        }
        b
    };
    bs.push(init);

    for i in 0..(n - 2) {
        let mut maxes: Vec<[u64; 2]> = Vec::new();
        maxes.reserve(n);
        for w in bs[i].windows(2) {
            // a < b, c < d
            let (a, b, c, d) = (w[0][0], w[0][1], w[1][0], w[1][1]);
            let (max2, max) = {
                if b < d {
                    if b < c { (c, d) } else { (b, d) }
                } else if b > d {
                    if a < d { (d, b) } else { (a, b) }
                } else {
                    if a < c { (c, d) } else { (a, d) }
                }
            };
            maxes.push([max2, max]);

            total += max2;
        }
        bs.push(maxes);
    }
    total
}

fn main() {
    let n: usize = read_line().parse().unwrap();
    let ps = to_vec(read_line(), 1);

    let ps_offset = (n * (n - 1) / 2) as u64;
    let val = evaluate(&ps);

    println!("{}", val + ps_offset);
}

use std::collections::BTreeMap;
use std::collections::BTreeSet;
use std::ops::Bound::Included;
use std::ops::Bound::Excluded;

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
    ($($r:tt)*) => {
        let mut s = {
            use std::io::Read;
            let mut s = String::new();
            std::io::stdin().read_to_string(&mut s).unwrap();
            s
        };
        let mut iter = s.split_whitespace();
        input_inner!{iter, $($r)*}
    };
}

macro_rules! input_inner {
    ($iter:expr) => {};
    ($iter:expr, ) => {};

    ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($iter, $t);
        input_inner!{$iter $($r)*}
    };
}

macro_rules! read_value {
    ($iter:expr, ( $($t:tt),* )) => {
        ( $(read_value!($iter, $t)),* )
    };

    ($iter:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
    };

    ($iter:expr, chars) => {
        read_value!($iter, String).chars().collect::<Vec<char>>()
    };

    ($iter:expr, usize1) => {
        read_value!($iter, usize) - 1
    };

    ($iter:expr, $t:ty) => {
        $iter.next().unwrap().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input!{
        n: usize,
        v: [usize; n],
    }

    let mut xlr = 0;
    let mut imap = BTreeMap::new();

    for i in 0..n {
        imap.insert(v[i], i);
    }

    let mut iter = imap.iter().rev();

    let mut iset = BTreeSet::new();
    iset.insert(0);
    iset.insert(0);
    iset.insert(n+1);
    iset.insert(n+1);

    for (key, value) in iter {
        let mut trange = iset.range((Included(&0), Included(&(value+1)))).rev();
        let x = trange.next().unwrap();
        let w;
        if x != &0 {
            w = trange.next().unwrap(); 
        } else {
            w = &0;
        }

        let mut srange = iset.range((Included(&(value+1)), Included(&(n+1))));
        let y = srange.next().unwrap();
        let mut z = &(n+1);
        if y != &(n+1) {
            z = srange.next().unwrap();
        }

        xlr = xlr + ((x - w) * (y - (value+1)) + ((value+1) - x) * (z - y)) * key;

        if key == &0 {
            break;
        }

        iset.insert((*value)+1);
    }

    println!("{}", xlr);
}

use std::collections::BTreeSet;
use std::io::*;
use std::ops::Bound::Excluded;
use std::ops::Bound::Included;
use std::str::FromStr;

#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn main() {
    let n = read::<usize>();
    let mut ps = vec![(0, 0); n];
    for i in 0..n {
        ps[i].0 = read::<usize>();
        ps[i].1 = i;
    }
    ps.sort();
    ps.reverse();
    let mut items = BTreeSet::<i64>::new();
    let mut ans = 0;
    for i in 0..n {
        let v = ps[i].0 as i64;
        let pos = ps[i].1 as i64;
        let mut lefts = vec![];
        let mut rights = vec![];
        for index in items.range((Included(&0), Excluded(&(pos as i64)))).rev() {
            lefts.push(*index);
            if lefts.len() == 2 {
                break;
            }
        }
        for index in items.range((Excluded(&(pos as i64)), Included(&(n as i64)))) {
            rights.push(*index);
            if rights.len() == 2 {
                break;
            }
        }
        while lefts.len() <= 1 {
            lefts.push(-1);
        }
        while rights.len() <= 1 {
            rights.push(n as i64);
        }
        ans += v * (pos - lefts[0]) * (rights[1] - rights[0]);
        ans += v * (lefts[0] - lefts[1]) * (rights[0] - pos);
        items.insert(pos as i64);
    }
    println!("{}", ans);
}

